# Theme fallback/refresh
# Some UGSM tabs can be loaded before the shared UI helper colors are initialized.
# Keep local Expansion colors from becoming $null, then refresh them again when the tab is built.
function Initialize-UGSMExpansionThemeDefaults {
    $defaults = @{
        UGSM_ColorText            = '#FFFFFF'
        UGSM_ColorBackground      = '#071120'
        UGSM_ColorPanelBackground = '#0B1728'
        UGSM_ColorInputBackground = '#0A1320'
        UGSM_ColorMutedText       = '#B8C7D9'
        UGSM_ColorPrimary         = '#3B82F6'
        UGSM_ColorSuccess         = '#22C55E'
        UGSM_ColorDanger          = '#EF4444'
        UGSM_ColorNeutral         = '#334155'
        UGSM_ColorCaution         = '#F59E0B'
        UGSM_ColorSpecial         = '#FF00FF'
        UGSM_ColorBack            = '#475569'
        UGSM_ColorGrid            = '#20344D'
        UGSM_ColorGridHeader      = '#1C2430'
        UGSM_ColorGridSelection   = '#2D5AA0'
        UGSM_ColorSurfaceAlt      = '#1B2636'
        UGSM_ColorBorder          = '#20344D'
    }

    foreach ($entry in $defaults.GetEnumerator()) {
        $existing = Get-Variable -Name $entry.Key -Scope Global -ValueOnly -ErrorAction SilentlyContinue
        if ($null -eq $existing) {
            Set-Variable -Name $entry.Key -Scope Global -Value ([System.Drawing.ColorTranslator]::FromHtml([string]$entry.Value)) -Force
        }
    }

    $UGSM_ExpansionButtonNewColor = $global:UGSM_ColorPrimary
    $UGSM_ExpansionButtonAddColor = $global:UGSM_ColorPrimary
    $UGSM_ExpansionButtonApplyColor = $global:UGSM_ColorCaution
    $UGSM_ExpansionButtonSaveColor = $global:UGSM_ColorSuccess
    $UGSM_ExpansionButtonRemoveColor = $global:UGSM_ColorDanger
    $UGSM_ExpansionButtonRefreshColor = $global:UGSM_ColorNeutral
    $UGSM_ExpansionButtonLoadColor = $global:UGSM_ColorNeutral
    $UGSM_ExpansionButtonPrettyPrintColor = $global:UGSM_ColorSpecial
    $UGSM_ExpansionButtonBackColor = $global:UGSM_ColorBack

    $UGSM_ExpansionAccentColor = $global:UGSM_ColorPrimary
    $UGSM_ExpansionNewColor = $UGSM_ExpansionButtonNewColor
    $UGSM_ExpansionRefreshColor = $UGSM_ExpansionButtonRefreshColor
    $UGSM_ExpansionApplyColor = $UGSM_ExpansionButtonApplyColor
    $UGSM_ExpansionSaveColor = $UGSM_ExpansionButtonSaveColor
    $UGSM_ExpansionPrettyPrintColor = $UGSM_ExpansionButtonPrettyPrintColor
    $UGSM_ExpansionRemoveColor = $UGSM_ExpansionButtonRemoveColor
}

