# Helper Functions
function Set-UGSMExpansionToolbarLayout {
    param(
        [Parameter(Mandatory)][System.Windows.Forms.Panel]$Toolbar,
        [System.Windows.Forms.Control]$BtnNew,
        [System.Windows.Forms.Control]$BtnRefresh,
        [System.Windows.Forms.Control]$BtnApply,
        [System.Windows.Forms.Control]$BtnSaveCurrent,
        [System.Windows.Forms.Control]$BtnSaveAll,
        [System.Windows.Forms.Control]$BtnPretty,
        [System.Windows.Forms.Control]$BtnRemove
    )

    $gap = $UGSM_ExpansionToolbarButtonGap
    $y = $UGSM_ExpansionToolbarButtonY

    $leftButtons = @($BtnNew, $BtnRefresh) | Where-Object { $null -ne $_ }
    $centerButtons = @($BtnApply, $BtnSaveCurrent, $BtnSaveAll) | Where-Object { $null -ne $_ }
    $rightButtons = @($BtnPretty, $BtnRemove) | Where-Object { $null -ne $_ }

    if ($leftButtons.Count -gt 0) {
        $x = $UGSM_ExpansionToolbarLeftStartX
        foreach ($button in $leftButtons) {
            $button.Location = New-Object System.Drawing.Point($x, $y)
            $x += $button.Width + $gap
        }
    }

    if ($centerButtons.Count -gt 0) {
        $centerGroupWidth = (($centerButtons | Measure-Object -Property Width -Sum).Sum) + (($centerButtons.Count - 1) * $gap)
        $centerStartX = [int][Math]::Floor(($Toolbar.ClientSize.Width - $centerGroupWidth) / 2)

        $x = $centerStartX
        foreach ($button in $centerButtons) {
            $button.Location = New-Object System.Drawing.Point($x, $y)
            $x += $button.Width + $gap
        }
    }

    if ($rightButtons.Count -gt 0) {
        $rightGroupWidth = (($rightButtons | Measure-Object -Property Width -Sum).Sum) + (($rightButtons.Count - 1) * $gap)
        $rightStartX = $Toolbar.ClientSize.Width - $UGSM_ExpansionToolbarRightPadding - $rightGroupWidth

        $x = $rightStartX
        foreach ($button in $rightButtons) {
            $button.Location = New-Object System.Drawing.Point($x, $y)
            $x += $button.Width + $gap
        }
    }
}


function Set-UGSMExpansionToolbarButtons {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][System.Windows.Forms.Control[]]$Buttons
    )

    $x = $UGSM_ExpansionToolbarLeftStartX
    $y = $UGSM_ExpansionToolbarButtonY
    $gap = $UGSM_ExpansionToolbarButtonGap

    foreach ($button in @($Buttons | Where-Object { $null -ne $_ })) {
        $button.Location = New-Object System.Drawing.Point($x, $y)
        $x += $button.Width + $gap
    }
}

function Convert-UGSMHexToColor {
    [CmdletBinding()]
    param(
        [AllowEmptyString()]
        [string]$Hex
    )

    $value = ([string]$Hex).Trim().TrimStart('#').ToUpper()

    if ([string]::IsNullOrWhiteSpace($value)) {
        return $global:UGSM_ColorText
    }

    if ($value.Length -ne 8) {
        return $global:UGSM_ColorText
    }

    try {
        $r = [Convert]::ToInt32($value.Substring(0, 2), 16)
        $g = [Convert]::ToInt32($value.Substring(2, 2), 16)
        $b = [Convert]::ToInt32($value.Substring(4, 2), 16)
        $a = [Convert]::ToInt32($value.Substring(6, 2), 16)
        return [System.Drawing.Color]::FromArgb($a, $r, $g, $b)
    }
    catch {
        return $global:UGSM_ColorText
    }
}

function Get-UGSMGameDayZExpansionTypesItemIndex {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$TypesPath)

    $index = @{}
    if (-not (Test-Path -LiteralPath $TypesPath -PathType Leaf)) { return $index }

    [xml]$xml = Get-Content -LiteralPath $TypesPath -Raw -ErrorAction Stop
    foreach ($typeNode in @($xml.SelectNodes('//type'))) {
        if ($null -eq $typeNode) { continue }
        $name = [string]$typeNode.GetAttribute('name')
        if ([string]::IsNullOrWhiteSpace($name)) { continue }

        $nominal = 0
        $nominalNode = $typeNode.SelectSingleNode('./nominal')
        if ($nominalNode) { [void][int]::TryParse([string]$nominalNode.InnerText, [ref]$nominal) }

        $index[$name.ToLowerInvariant()] = [pscustomobject]@{
            ClassName = $name
            Nominal   = [int]$nominal
        }
    }

    return $index
}

function Add-UGSMGameDayZMissingTypesToExpansionMarket {
    [CmdletBinding(SupportsShouldProcess = $true)]
    param(
        [Parameter(Mandatory)][object]$Instance,
        [Parameter(Mandatory)][string]$TypesPath,
        [string]$TargetFileName = 'UGSM_Generated.json',
        [string]$SkipNamePattern = '^(ZmbF_|ZmbM_|Zmb|StaticObj_|Land_|Animal_|Wreck_|Fireplace|Bonfire|BanditAI_)',
        [switch]$UpdateStockFromNominal,
        [switch]$PassThru
    )

    if (-not (Test-Path -LiteralPath $TypesPath -PathType Leaf)) {
        throw "types.xml not found: $TypesPath"
    }

    $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
    $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
    if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) {
        [void][System.IO.Directory]::CreateDirectory($marketRoot)
    }

    if ([string]::IsNullOrWhiteSpace($TargetFileName)) {
        $TargetFileName = 'UGSM_Generated.json'
    }
    if (-not $TargetFileName.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) {
        $TargetFileName += '.json'
    }

    $targetPath = Join-Path $marketRoot $TargetFileName
    $typeIndex = Get-UGSMGameDayZExpansionTypesItemIndex -TypesPath $TypesPath

    # Build a set of all class names that already exist anywhere in the market folder.
    $existingAcrossMarket = @{}
    $existingInTarget = @{}

    $marketFiles = @(Get-ChildItem -LiteralPath $marketRoot -Filter '*.json' -File -ErrorAction SilentlyContinue)
    foreach ($file in $marketFiles) {
        if ($file.Name -match '\.bak\.json$') { continue }

        try {
            $data = Read-UGSMGameDayZJsonDataSafe -Path $file.FullName
            if ($null -eq $data) { continue }

            foreach ($item in @($data.Items)) {
                $itemClass = [string]$item.ClassName
                if (-not [string]::IsNullOrWhiteSpace($itemClass)) {
                    $key = $itemClass.ToLowerInvariant()
                    $existingAcrossMarket[$key] = $true

                    if ([string]::Equals($file.FullName, $targetPath, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $existingInTarget[$key] = $true
                    }
                }
            }
        }
        catch { }
    }

    if (Test-Path -LiteralPath $targetPath -PathType Leaf) {
        $targetData = Read-UGSMGameDayZJsonDataSafe -Path $targetPath
    }
    else {
        $targetData = [pscustomobject]@{
            m_Version        = 12
            DisplayName      = 'UGSM Generated'
            Icon             = 'Deliver'
            Color            = 'FBFCFEFF'
            IsExchange       = 0
            InitStockPercent = 75.0
            Items            = @()
        }
    }

    if ($null -eq $targetData.Items) {
        $targetData | Add-Member -NotePropertyName Items -NotePropertyValue @() -Force
    }

    $items = New-Object System.Collections.ArrayList
    foreach ($item in @($targetData.Items)) {
        [void]$items.Add($item)

        $itemClass = [string]$item.ClassName
        if (-not [string]::IsNullOrWhiteSpace($itemClass)) {
            $existingInTarget[$itemClass.ToLowerInvariant()] = $true
            $existingAcrossMarket[$itemClass.ToLowerInvariant()] = $true
        }
    }

    $itemsAdded = 0
    $itemsSkipped = 0
    $itemsSkippedByPattern = 0
    $changed = $false

    foreach ($key in @($typeIndex.Keys | Sort-Object)) {
        $typeItem = $typeIndex[$key]
        $className = [string]$typeItem.ClassName

        if ([string]::IsNullOrWhiteSpace($className)) {
            $itemsSkippedByPattern++
            continue
        }

        if (-not [string]::IsNullOrWhiteSpace($SkipNamePattern) -and $className -match $SkipNamePattern) {
            $itemsSkippedByPattern++
            continue
        }

        $classKey = $className.ToLowerInvariant()

        # If the item already exists anywhere in the market, do not add it back to UGSM_Generated.
        if ($existingAcrossMarket.ContainsKey($classKey)) {
            $itemsSkipped++
            continue
        }

        $balance = Get-UGSMGameDayZItemTraderBalance -Nominal ([int]$typeItem.Nominal)

        [void]$items.Add([ordered]@{
                ClassName         = $className
                MaxPriceThreshold = [int]$balance.BuyPrice
                MinPriceThreshold = [int]($balance.BuyPrice * 0.8)
                SellPricePercent  = 75.0
                MaxStockThreshold = [int]$balance.MaxStock
                MinStockThreshold = 1
                QuantityPercent   = -1
                SpawnAttachments  = @()
                Variants          = @()
            })

        $existingInTarget[$classKey] = $true
        $existingAcrossMarket[$classKey] = $true
        $itemsAdded++
        $changed = $true
    }

    $targetData.Items = @($items)

    if ($changed -and $PSCmdlet.ShouldProcess($targetPath, 'add missing types.xml items to Expansion Market')) {
        if (Test-Path -LiteralPath $targetPath -PathType Leaf) {
            try { [void](Backup-UGSMGameDayZFile -TargetPath $targetPath) } catch { }
        }
        Write-UGSMGameDayZJsonDataSafe -Path $targetPath -Data $targetData
    }

    if ($UpdateStockFromNominal) {
        $nominalMap = @{}
        foreach ($nominalKey in @($typeIndex.Keys)) {
            $nominalMap[$nominalKey] = [int]$typeIndex[$nominalKey].Nominal
        }
        Sync-UGSMGameDayZExpansionMarketWithNominal -Instance $Instance -NominalMap $nominalMap | Out-Null
    }

    $result = [pscustomobject]@{
        MarketRoot             = $marketRoot
        TargetPath             = $targetPath
        TypesPath              = $TypesPath
        ItemsAdded             = [int]$itemsAdded
        ExistingItemsSkipped   = [int]$itemsSkipped
        ItemsSkippedByPattern  = [int]$itemsSkippedByPattern
        UpdateStockFromNominal = [bool]$UpdateStockFromNominal
        Changed                = [bool]$changed
        MarketFilesScanned     = [int]@($marketFiles | Where-Object { $_.Name -notmatch '\.bak\.json$' }).Count
        ExistingMarketCount    = [int]$existingAcrossMarket.Count
    }

    if ($PassThru) {
        return $result
    }

    return $result
}

function Sync-UGSMGameDayZExpansionMarketWithNominal {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Instance,
        [Parameter(Mandatory)][hashtable]$NominalMap
    )

    $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
    $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
    if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) { return }

    foreach ($file in @(Get-ChildItem -LiteralPath $marketRoot -Filter '*.json' -File)) {
        $data = Read-UGSMGameDayZJsonDataSafe -Path $file.FullName
        $changed = $false

        foreach ($item in @($data.Items)) {
            if ([string]::IsNullOrWhiteSpace([string]$item.ClassName)) { continue }
            $key = $item.ClassName.ToLowerInvariant()
            if ($NominalMap.ContainsKey($key)) {
                $balance = Get-UGSMGameDayZItemTraderBalance -Nominal $NominalMap[$key]

                # The only normal overwrite is stock/count based on types.xml nominal.
                $newMaxStock = [int]$balance.MaxStock
                if ([int]$item.MaxStockThreshold -ne $newMaxStock) {
                    $item.MaxStockThreshold = $newMaxStock
                    $changed = $true
                }

                # Min stock is only repaired when it is empty/invalid.
                if ([int]$item.MinStockThreshold -le 0) {
                    $item.MinStockThreshold = 1
                    $changed = $true
                }

                # Prices are only filled when placeholder values are present.
                if ([int]$item.MaxPriceThreshold -le 1) {
                    $item.MaxPriceThreshold = [int]$balance.BuyPrice
                    $item.MinPriceThreshold = [int]($balance.BuyPrice * 0.8)
                    $changed = $true
                }
            }
        }

        if ($changed) {
            try { [void](Backup-UGSMGameDayZFile -TargetPath $file.FullName) } catch { }
            Write-UGSMGameDayZJsonDataSafe -Path $file.FullName -Data $data
        }
    }
}

function Convert-UGSMColorToHex {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][System.Drawing.Color]$Color
    )

    return ('#{0:X2}{1:X2}{2:X2}{3:X2}' -f $Color.R, $Color.G, $Color.B, $Color.A)
}

function Update-UGSMColorPreview {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$TextBox,
        [Parameter(Mandatory)]$Panel
    )

    $hexValue = [string]$TextBox.Text

    if ([string]::IsNullOrWhiteSpace($hexValue)) {
        $Panel.BackColor = $global:UGSM_ColorText
        return
    }

    $Panel.BackColor = Convert-UGSMHexToColor -Hex $hexValue
}

function New-UGSMExpansionActionButton {
    param(
        [Parameter(Mandatory)][string]$Text,
        [Parameter(Mandatory)][int]$X,
        [Parameter(Mandatory)][int]$Y,
        [Parameter(Mandatory)][System.Drawing.Color]$BackColor,
        [int]$Width = 108,
        [int]$Height = 28
    )

    $button = New-UGSMButton `
        -Text $Text `
        -X $X `
        -Y $Y `
        -Width $Width `
        -Height $Height `
        -BackColor '#2A313B' `
        -ForeColor '#FFFFFF'

    $button.BackColor = $BackColor
    $button.ForeColor = $global:UGSM_ColorText

    Set-UGSMExpansionButtonStyle -Button $button | Out-Null

    return $button
}

