function Get-UGSMGameDayZExpansionPaths {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Instance
    )

    $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance

    $profileRoot = ''
    $profileExpansionRoot = ''
    $missionRoot = ''
    $profileSettingsRoot = ''
    $missionSettingsRoot = ''

    if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileRoot)) {
        $profileRoot = [string]$paths.ProfileRoot
        $profileExpansionRoot = Join-Path $profileRoot 'profiles\ExpansionMod'
        $profileSettingsRoot = Join-Path $profileExpansionRoot 'Settings'
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeMissionPath)) {
        $missionRoot = Join-Path ([string]$paths.RuntimeMissionPath) 'expansion'
        $missionSettingsRoot = Join-Path $missionRoot 'settings'
    }

    [pscustomobject]@{
        ProfileRoot          = $profileRoot
        ProfileExpansionRoot = $profileExpansionRoot
        ProfileSettingsRoot  = $profileSettingsRoot
        MissionExpansionRoot = $missionRoot
        MissionSettingsRoot  = $missionSettingsRoot
    }
}

# Modules Functions
function Get-UGSMGameDayZExpansionModuleDefinitions {
    [CmdletBinding()]
    param()

    return @(
        [pscustomobject]@{ Key = 'Overview'; Title = 'Overview'; Scope = 'System'; RelativePath = ''; IncludeInFiles = $false }

        [pscustomobject]@{ Key = 'Settings'; Title = 'Settings'; Scope = 'Both'; RelativePath = 'settings'; IncludeInFiles = $true }

        
        [pscustomobject]@{ Key = 'Market'; Title = 'Market'; Scope = 'Profile'; RelativePath = 'Market'; IncludeInFiles = $true }
        [pscustomobject]@{ Key = 'TraderSetup'; Title = 'Trader Setup'; Scope = 'Both'; RelativePath = 'traders'; IncludeInFiles = $true }

        [pscustomobject]@{ Key = 'Objects'; Title = 'Objects'; Scope = 'Mission'; RelativePath = 'objects'; IncludeInFiles = $true }


        [pscustomobject]@{ Key = 'ATM'; Title = 'ATM'; Scope = 'Profile'; RelativePath = 'ATM'; IncludeInFiles = $true }
        #[pscustomobject]@{ Key = 'Hardline'; Title = 'Hardline'; Scope = 'Mission'; RelativePath = 'settings'; IncludeInFiles = $true; DetectionFiles = @('settings\HardlineSettings.json') }
        
        
        
        [pscustomobject]@{ Key = 'Missions'; Title = 'Missions'; Scope = 'Mission'; RelativePath = 'missions'; IncludeInFiles = $true }
        
        



        [pscustomobject]@{ Key = 'P2PMarket'; Title = 'P2P Market'; Scope = 'Mission'; RelativePath = 'p2pmarket'; IncludeInFiles = $true }
        [pscustomobject]@{ Key = 'PersonalStorage'; Title = 'Personal Storage'; Scope = 'Mission'; RelativePath = 'personalstorage'; IncludeInFiles = $true }

        [pscustomobject]@{ Key = 'AI'; Title = 'AI'; Scope = 'Profile'; RelativePath = 'AI'; IncludeInFiles = $true }
        
        [pscustomobject]@{ Key = 'Groups'; Title = 'Groups'; Scope = 'Profile'; RelativePath = 'Groups'; IncludeInFiles = $true }
        
        [pscustomobject]@{ Key = 'Loadouts'; Title = 'Loadouts'; Scope = 'Profile'; RelativePath = 'Loadouts'; IncludeInFiles = $true }
        
        
        [pscustomobject]@{ Key = 'Quests'; Title = 'Quests'; Scope = 'Profile'; RelativePath = 'Quests'; IncludeInFiles = $true }
        [pscustomobject]@{ Key = 'Files'; Title = 'Files'; Scope = 'System'; RelativePath = ''; IncludeInFiles = $false }
        [pscustomobject]@{ Key = 'Help'; Title = 'Help'; Scope = 'System'; RelativePath = ''; IncludeInFiles = $false }
        [pscustomobject]@{ Key = 'StyleTest'; Title = 'Style Test'; Scope = 'System'; RelativePath = ''; IncludeInFiles = $false }
