function Get-UGSMGameDayZExpansionModulePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Paths,
        [Parameter(Mandatory)][object]$Module
    )

    $scope = [string]$Module.Scope
    $relative = [string]$Module.RelativePath

    if ($scope -eq 'Profile') {
        if ([string]::IsNullOrWhiteSpace([string]$Paths.ProfileExpansionRoot)) { return '' }
        return (Join-Path ([string]$Paths.ProfileExpansionRoot) $relative)
    }

    if ($scope -eq 'Mission') {
        if ([string]::IsNullOrWhiteSpace([string]$Paths.MissionExpansionRoot)) { return '' }
        return (Join-Path ([string]$Paths.MissionExpansionRoot) $relative)
    }

    return ''
}

function Get-UGSMGameDayZExpansionModulePaths {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Paths,
        [Parameter(Mandatory)][object]$Module
    )

    $items = New-Object System.Collections.ArrayList

    switch ([string]$Module.Scope) {
        'Profile' {
            $path = Get-UGSMGameDayZExpansionModulePath -Paths $Paths -Module $Module
            if (-not [string]::IsNullOrWhiteSpace($path)) { [void]$items.Add($path) }
        }
        'Mission' {
            $path = Get-UGSMGameDayZExpansionModulePath -Paths $Paths -Module $Module
            if (-not [string]::IsNullOrWhiteSpace($path)) { [void]$items.Add($path) }
        }
        'Both' {
            if (-not [string]::IsNullOrWhiteSpace([string]$Paths.ProfileExpansionRoot)) {
                [void]$items.Add((Join-Path ([string]$Paths.ProfileExpansionRoot) ([string]$Module.RelativePath)))
            }
            if (-not [string]::IsNullOrWhiteSpace([string]$Paths.MissionExpansionRoot)) {
                [void]$items.Add((Join-Path ([string]$Paths.MissionExpansionRoot) ([string]$Module.RelativePath)))
            }
        }
    }

    return @($items)
}

function Get-UGSMGameDayZExpansionModuleDetectionFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Paths,
        [Parameter(Mandatory)][object]$Module
    )

    $items = New-Object System.Collections.ArrayList
    $relativeFiles = @($Module.DetectionFiles)
    if ($relativeFiles.Count -eq 0) {
        return @($items)
    }

    switch ([string]$Module.Scope) {
        'Profile' {
            foreach ($relativeFile in $relativeFiles) {
                if ([string]::IsNullOrWhiteSpace([string]$relativeFile)) { continue }
                if ([string]::IsNullOrWhiteSpace([string]$Paths.ProfileExpansionRoot)) { continue }
                [void]$items.Add((Join-Path ([string]$Paths.ProfileExpansionRoot) ([string]$relativeFile)))
            }
        }
        'Mission' {
            foreach ($relativeFile in $relativeFiles) {
                if ([string]::IsNullOrWhiteSpace([string]$relativeFile)) { continue }
                if ([string]::IsNullOrWhiteSpace([string]$Paths.MissionExpansionRoot)) { continue }
                [void]$items.Add((Join-Path ([string]$Paths.MissionExpansionRoot) ([string]$relativeFile)))
            }
        }
        'Both' {
            foreach ($relativeFile in $relativeFiles) {
                if ([string]::IsNullOrWhiteSpace([string]$relativeFile)) { continue }
                if (-not [string]::IsNullOrWhiteSpace([string]$Paths.ProfileExpansionRoot)) {
                    [void]$items.Add((Join-Path ([string]$Paths.ProfileExpansionRoot) ([string]$relativeFile)))
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$Paths.MissionExpansionRoot)) {
                    [void]$items.Add((Join-Path ([string]$Paths.MissionExpansionRoot) ([string]$relativeFile)))
                }
            }
        }
    }

    return @($items)
}

function Get-UGSMGameDayZExpansionDetectedModules {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Instance
    )

    $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
    $results = New-Object System.Collections.ArrayList

    foreach ($module in @(Get-UGSMGameDayZExpansionModuleDefinitions | Where-Object { $_.Key -notin @('Overview', 'Files', 'Help', 'TraderSetup') })) {
        $candidatePaths = @(Get-UGSMGameDayZExpansionModulePaths -Paths $paths -Module $module)
        $existingPaths = @($candidatePaths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) -and (Test-Path -LiteralPath $_ -PathType Container) })
        $detectionFiles = @(Get-UGSMGameDayZExpansionModuleDetectionFiles -Paths $paths -Module $module)
        $existingDetectionFiles = @($detectionFiles | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) -and (Test-Path -LiteralPath $_ -PathType Leaf) })

        $jsonFiles = New-Object System.Collections.ArrayList
        foreach ($path in @($existingPaths)) {
            foreach ($file in @(Get-ChildItem -LiteralPath $path -File -Filter '*.json' -Recurse -ErrorAction SilentlyContinue)) {
                [void]$jsonFiles.Add($file)
            }
        }
        foreach ($filePath in @($existingDetectionFiles)) {
            if ([string]::IsNullOrWhiteSpace([string]$filePath)) { continue }
            if (@($jsonFiles | Where-Object { $_.FullName -eq $filePath }).Count -gt 0) { continue }
            try {
                [void]$jsonFiles.Add((Get-Item -LiteralPath $filePath -ErrorAction Stop))
            }
            catch { }
        }

        [void]$results.Add([pscustomobject]@{
                Key                    = [string]$module.Key
                Title                  = [string]$module.Title
                Scope                  = [string]$module.Scope
                RelativePath           = [string]$module.RelativePath
                CandidatePaths         = @($candidatePaths)
                ExistingPaths          = @($existingPaths)
                DetectionFiles         = @($detectionFiles)
                ExistingDetectionFiles = @($existingDetectionFiles)
                IsDetected             = ((@($existingPaths).Count -gt 0) -or (@($existingDetectionFiles).Count -gt 0))
                JsonFileCount          = @($jsonFiles).Count
                JsonFiles              = @($jsonFiles | Sort-Object FullName)
            })
    }

    return @($results)
}

function Resolve-UGSMGameDayZExpansionFileModule {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$FullName,
        [Parameter(Mandatory)][object]$Paths
    )

    foreach ($module in @(Get-UGSMGameDayZExpansionModuleDefinitions | Where-Object { $_.IncludeInFiles })) {
        foreach ($root in @(Get-UGSMGameDayZExpansionModulePaths -Paths $Paths -Module $module)) {
            if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
            if ($FullName.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase)) {
                return [string]$module.Key
            }
        }
    }

    return 'Other'
}

# Json Functions
function Get-UGSMGameDayZExpansionJsonFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$Instance
    )

    $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
    $roots = New-Object System.Collections.ArrayList

    if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileExpansionRoot) -and (Test-Path -LiteralPath $paths.ProfileExpansionRoot -PathType Container)) {
        [void]$roots.Add([string]$paths.ProfileExpansionRoot)
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionExpansionRoot) -and (Test-Path -LiteralPath $paths.MissionExpansionRoot -PathType Container)) {
        [void]$roots.Add([string]$paths.MissionExpansionRoot)
    }

    $items = New-Object System.Collections.ArrayList
    foreach ($root in @($roots)) {
        foreach ($file in @(
                Get-ChildItem -LiteralPath $root -File -Filter '*.json' -Recurse -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch '\.bak\.json$' }
            )) {
            $scope = $(if ($file.FullName.StartsWith([string]$paths.ProfileExpansionRoot, [System.StringComparison]::OrdinalIgnoreCase)) { 'Profile' } else { 'Mission' })
            $moduleKey = Resolve-UGSMGameDayZExpansionFileModule -FullName ([string]$file.FullName) -Paths $paths
            [void]$items.Add([pscustomobject]@{
                    Name      = [string]$file.Name
                    Title     = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                    FullName  = [string]$file.FullName
                    Directory = [string]$file.DirectoryName
                    Scope     = $scope
                    Module    = $moduleKey
                })
        }
    }

    return @(
        $items |
        Sort-Object @{ Expression = 'Module'; Ascending = $true }, @{ Expression = 'Scope'; Ascending = $true }, @{ Expression = 'Name'; Ascending = $true } |
        Select-Object -Unique FullName, Name, Title, Directory, Scope, Module
    )
}

function Get-UGSMJsonPropertyValue {
    [CmdletBinding()]
    param(
        $Object,
        [Parameter(Mandatory)][string]$Name,
        $DefaultValue = $null
    )

    if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) {
        return $DefaultValue
    }

    try {
        $prop = $Object.PSObject.Properties[$Name]
        if ($null -ne $prop) {
            return $prop.Value
        }
    }
    catch {
    }

    return $DefaultValue
}

function Set-UGSMJsonPropertyValue {
    [CmdletBinding()]
    param(
        $Object,
        [Parameter(Mandatory)][string]$Name,
        $Value
    )

    if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) {
        return
    }

    $prop = $Object.PSObject.Properties[$Name]
    if ($null -ne $prop) {
        $prop.Value = $Value
    }
    else {
        $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
    }
}

function Get-UGSMGameDayZExpansionDisplayName {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Item
    )

    if ($null -eq $Item) { return '' }
    return ('[{0}] [{1}] {2}' -f [string]$Item.Scope, [string]$Item.Module, [string]$Item.Name)
}

function New-DayZExpansionModulePlaceholderText {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object]$ModuleState
    )

    $lines = New-Object System.Collections.ArrayList
    [void]$lines.Add(([string]$ModuleState.Title + ' module'))
    [void]$lines.Add('')

    if ($ModuleState.IsDetected) {
        [void]$lines.Add('Status: Detected')
        [void]$lines.Add(('JSON files found: ' + [string]$ModuleState.JsonFileCount))
        [void]$lines.Add('')
        if (@($ModuleState.ExistingPaths).Count -gt 0) {
            [void]$lines.Add('Detected paths:')
            foreach ($path in @($ModuleState.ExistingPaths)) {
                [void]$lines.Add((' - ' + [string]$path))
            }
        }
        elseif (@($ModuleState.ExistingDetectionFiles).Count -gt 0) {
            [void]$lines.Add('Detected via settings/files:')
            foreach ($file in @($ModuleState.ExistingDetectionFiles)) {
                [void]$lines.Add((' - ' + [string]$file))
            }
            [void]$lines.Add('')
            [void]$lines.Add('No dedicated module folder has been generated yet.')
        }
        [void]$lines.Add('')
        if (@($ModuleState.JsonFiles).Count -gt 0) {
            [void]$lines.Add('Files:')
            foreach ($file in @($ModuleState.JsonFiles)) {
                [void]$lines.Add((' - ' + [string]$file.Name))
            }
        }
        else {
            [void]$lines.Add('No JSON files were found under this module yet.')
        }
        [void]$lines.Add('')
        [void]$lines.Add('Structured editors are not wired yet for this module. Use the Files tab for now.')
    }
    else {
        [void]$lines.Add('Status: Not detected')
        [void]$lines.Add('')
        [void]$lines.Add('No matching Expansion folder was found for this instance.')
        [void]$lines.Add('')
        [void]$lines.Add('Expected paths:')
        foreach ($path in @($ModuleState.CandidatePaths)) {
            [void]$lines.Add((' - ' + [string]$path))
        }
        [void]$lines.Add('')
        [void]$lines.Add('Start the server once with this module enabled, then refresh the Expansion tab.')
    }

    return [string]::Join("`r`n", @($lines))
}

# Safe Helpers
function Get-UGSMSafeString {
    [CmdletBinding()]
    param($Value)

    if ($null -eq $Value) {
        return ''
    }

    return [string]$Value
}

function Get-UGSMSafeBool {
    [CmdletBinding()]
    param($Value)

    try {
        return [bool]$Value
    }
    catch {
        return $false
    }
}

function Get-UGSMSafeIntString {
    [CmdletBinding()]
    param($Value)

    if ($null -eq $Value) {
        return ''
    }

    try {
        return [string][int]$Value
    }
    catch {
        return [string]$Value
    }
}

function Get-UGSMSafeDoubleString {
    [CmdletBinding()]
    param($Value)

    if ($null -eq $Value) {
        return ''
    }

    try {
        return [string][double]$Value
    }
    catch {
        return [string]$Value
    }
}

function Get-UGSMArrayCount {
    [CmdletBinding()]
    param($Value)

    if ($null -eq $Value) {
        return 0
    }

    if ($Value -is [string]) {
        return 0
    }

    try {
        return @($Value).Count
    }
    catch {
        return 0
    }
}

function Read-UGSMIntOrThrow {
    [CmdletBinding()]
    param(
        [string]$Text,
        [string]$FieldName
    )

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $null
    }

    try {
        return [int]$Text
    }
    catch {
        throw ($FieldName + ' must be a whole number.')
    }
}

function Read-UGSMDoubleOrThrow {
    [CmdletBinding()]
    param(
        [string]$Text,
        [string]$FieldName
    )

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $null
    }

    try {
        return [double]$Text
    }
    catch {
        throw ($FieldName + ' must be numeric.')
    }
}

function ConvertTo-UGSMPlainArray {
    [CmdletBinding()]
    param($Value)

    if ($null -eq $Value) {
        return @()
    }

    return @($Value)
}































































































