        [System.Windows.Forms.Control]$Tower6,
        [System.Windows.Forms.Control]$Tower7,
        [System.Windows.Forms.Control]$Tower8,
        [System.Windows.Forms.Control]$Tower9,

        [System.Windows.Forms.Control]$CmbFilter,
        [Parameter(Mandatory)][System.Windows.Forms.Control]$LstItems,
        [System.Windows.Forms.Control]$TxtPath,

        [System.Windows.Forms.Control]$BtnNew,
        [Parameter(Mandatory)][System.Windows.Forms.Control]$BtnRefresh,
        [System.Windows.Forms.Control]$BtnApply,
        [System.Windows.Forms.Control]$BtnSaveCurrent,
        [System.Windows.Forms.Control]$BtnSaveAll,
        [System.Windows.Forms.Control]$BtnPretty,
        [System.Windows.Forms.Control]$BtnRemove
    )

    if ($Page.ClientSize.Width -le 300 -or $Page.ClientSize.Height -le 150) {
        return
    }

    $Shell.SuspendLayout()
    $TopBar.SuspendLayout()
    $Body.SuspendLayout()
    $LeftPanel.SuspendLayout()
    $EditorPanel.SuspendLayout()

    try {
        if ($Root.ClientSize.Width -gt 0) {
            $Shell.Width = [Math]::Max($UGSM_ExpansionMaxWidth, ($Root.ClientSize.Width - 4))
        }

        $TopBar.Width = $Shell.ClientSize.Width
        $Body.Width = $Shell.ClientSize.Width
        $Body.Height = [Math]::Max(200, ($Shell.ClientSize.Height - $Body.Top - 8))

        # ------------------------------------------------------------
        # Toolbar
        # ------------------------------------------------------------
        $btnY = $UGSM_ExpansionToolbarButtonY
        $buttonGap = 10

        $leftButtons = @($BtnNew, $BtnRefresh) | Where-Object { $null -ne $_ }
        $centerButtons = @($BtnApply, $BtnSaveCurrent, $BtnSaveAll) | Where-Object { $null -ne $_ }
        $rightButtons = @($BtnPretty, $BtnRemove) | Where-Object { $null -ne $_ }

        if ($leftButtons.Count -gt 0) {
            $x = $UGSM_ExpansionToolbarLeftStartX
            foreach ($button in $leftButtons) {
                $button.Location = New-Object System.Drawing.Point($x, $btnY)
                $x += $button.Width + $buttonGap
            }
        }

        if ($centerButtons.Count -gt 0) {
            $centerGroupWidth = (($centerButtons | Measure-Object -Property Width -Sum).Sum) + (($centerButtons.Count - 1) * $buttonGap)
            $centerStartX = [int][Math]::Floor(($TopBar.ClientSize.Width - $centerGroupWidth) / 2) + $UGSM_ExpansionCenterGroupOffsetX

            $x = $centerStartX
            foreach ($button in $centerButtons) {
                $button.Location = New-Object System.Drawing.Point($x, $btnY)
                $x += $button.Width + $buttonGap
            }
        }

        if ($rightButtons.Count -gt 0) {
            $rightGroupWidth = (($rightButtons | Measure-Object -Property Width -Sum).Sum) + (($rightButtons.Count - 1) * $buttonGap)
            $rightStartX = $TopBar.ClientSize.Width - $UGSM_ExpansionToolbarRightPadding - $rightGroupWidth

            $x = $rightStartX
            foreach ($button in $rightButtons) {
                $button.Location = New-Object System.Drawing.Point($x, $btnY)
                $x += $button.Width + $buttonGap
            }
        }

        # ------------------------------------------------------------
        # Left panel
        # ------------------------------------------------------------
        $LeftPanel.Location = New-Object System.Drawing.Point(
            $UGSM_ExpansionGap,
            $UGSM_ExpansionGap
        )

        $LeftPanel.Size = New-Object System.Drawing.Size(
            $UGSM_ExpansionLeftPanelWidth,
            [Math]::Max(200, ($Body.ClientSize.Height - ($UGSM_ExpansionGap * 2)))
        )

        $innerLeft = 12
        $innerTop = 12
        $innerWidth = [Math]::Max(100, ($LeftPanel.ClientSize.Width - 24))

        if ($CmbFilter) {
            $CmbFilter.Location = New-Object System.Drawing.Point($innerLeft, $innerTop)
            $CmbFilter.Width = $innerWidth

            $listTop = $CmbFilter.Bottom + 8
            $listHeight = [Math]::Max(100, ($LeftPanel.ClientSize.Height - $listTop - 12))

            $LstItems.Location = New-Object System.Drawing.Point($innerLeft, $listTop)
            $LstItems.Size = New-Object System.Drawing.Size($innerWidth, $listHeight)
        }
        else {
            $LstItems.Location = New-Object System.Drawing.Point($innerLeft, $innerTop)
            $LstItems.Size = New-Object System.Drawing.Size(
                $innerWidth,
                [Math]::Max(100, ($LeftPanel.ClientSize.Height - 24))
            )
        }

        # ------------------------------------------------------------
        # Editor panel
        # ------------------------------------------------------------
        $editorLeft = $LeftPanel.Left + $LeftPanel.Width + $UGSM_ExpansionColumnGap
        $editorTop = $UGSM_ExpansionGap
        $editorWidth = $Body.ClientSize.Width - $editorLeft - $UGSM_ExpansionPadding
        $editorHeight = $Body.ClientSize.Height - ($UGSM_ExpansionGap * 2)

        $EditorPanel.Location = New-Object System.Drawing.Point($editorLeft, $editorTop)
        $EditorPanel.Size = New-Object System.Drawing.Size(
            [Math]::Max(200, $editorWidth),
            [Math]::Max(200, $editorHeight)
        )

        if ($EditorPanel -is [System.Windows.Forms.ScrollableControl]) {
            $EditorPanel.AutoScroll = $true
        }

        # ------------------------------------------------------------
        # Towers
        # ------------------------------------------------------------
        $towerGap = [int]$UGSM_ExpansionSectionGap
        $activeTowers = @(
            $Tower1, $Tower2, $Tower3, $Tower4, $Tower5,
            $Tower6, $Tower7, $Tower8, $Tower9
        ) | Where-Object { $null -ne $_ }

        $editorPanelWidth = [int]([int[]]@($EditorPanel.ClientSize.Width))[0]
        $editorPanelHeight = [int]([int[]]@($EditorPanel.ClientSize.Height))[0]
        $towerWidth = [Math]::Max(200, ($editorPanelWidth - 1))

        if ($activeTowers.Count -eq 1) {
            $singleTower = [System.Windows.Forms.Control]$activeTowers[0]

            $singleTower.Location = New-Object System.Drawing.Point(0, 0)
            $singleTower.Size = New-Object System.Drawing.Size(
                $towerWidth,
                [Math]::Max($editorPanelHeight, [int]$singleTower.Height)
            )
        }
        else {
            $currentY = 0

            foreach ($tower in $activeTowers) {
                $towerHeight = [int]([int[]]@($tower.Height))[0]

                $tower.Location = New-Object System.Drawing.Point(0, $currentY)
                $tower.Size = New-Object System.Drawing.Size(
                    $towerWidth,
                    [Math]::Max(50, $towerHeight)
                )

                $currentY += $towerHeight + $towerGap
            }
        }

        if ($TxtPath -and $TxtPath.Parent -and $TxtPath.Parent -is [System.Windows.Forms.Control]) {
            $parentWidth = [int]([int[]]@($TxtPath.Parent.ClientSize.Width))[0]
            $txtLeft = [int]([int[]]@($TxtPath.Left))[0]
            $pathPadding = [int]$UGSM_ExpansionPathPadding

            $TxtPath.Width = [Math]::Max(
                120,
                ($parentWidth - $txtLeft - $pathPadding)
            )
        }
    }
    finally {
        $EditorPanel.ResumeLayout()
        $LeftPanel.ResumeLayout()
        $Body.ResumeLayout()
        $TopBar.ResumeLayout()
        $Shell.ResumeLayout()
    }
}





function New-DayZExpansionStandardPlaceholderTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)][string]$TabName,
        [Parameter()]$StatusLabel,
        [string]$InfoText = 'Standardized placeholder tab. Original tab logic is intentionally bypassed during the layout conversion pass.',
        [string[]]$SampleItems = @('Placeholder 1', 'Placeholder 2', 'Placeholder 3')
    )

    try {
        $Page.Text = $TabName
        $Page.BackColor = $global:UGSM_ColorBackground
        $Page.ForeColor = $global:UGSM_ColorText
        $Page.AutoScroll = $false
        $Page.Controls.Clear()

        $root = New-Object System.Windows.Forms.Panel
        $root.Dock = 'Fill'
        $root.autoscroll = $false
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$Page.Controls.Add($root)

        $shell = New-Object System.Windows.Forms.Panel
        $shell.Location = New-Object System.Drawing.Point(0, 0)
        $shell.Size = New-Object System.Drawing.Size(
            [Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width),
            980
        )
        $shell.Anchor = 'Top,Left,Right'
        $shell.BackColor = $global:UGSM_ColorBackground
        $shell.BorderStyle = 'None'
        [void]$root.Controls.Add($shell)

        $topBar = New-Object System.Windows.Forms.Panel
        $topBar.Location = New-Object System.Drawing.Point(0, 0)
        $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
        $topBar.Anchor = 'Top,Left,Right'
        $topBar.BackColor = $global:UGSM_ColorBackground
        $topBar.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($topBar)

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveAll = New-UGSMExpansionSaveButton -Text 'Save All' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Remove' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall

        foreach ($button in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnSaveAll, $btnPretty, $btnRemove)) {
            $button.Anchor = 'Top,Left'
            $button.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $button.UseVisualStyleBackColor = $false
            $button.FlatAppearance.BorderSize = 1
            $button.FlatAppearance.MouseDownBackColor = $button.BackColor
            $button.FlatAppearance.MouseOverBackColor = $button.BackColor
            [void]$topBar.Controls.Add($button)
        }

        $body = New-Object System.Windows.Forms.Panel
        $body.Location = New-Object System.Drawing.Point($UGSM_ExpansionOffsetX, ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap))
        $body.Size = New-Object System.Drawing.Size(
            $shell.ClientSize.Width,
            ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12)
        )
        $body.Anchor = 'Top,Left,Right,Bottom'
        $body.BackColor = $global:UGSM_ColorBackground
        $body.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($body)

        $leftPanel = New-UGSMExpansionLeftListPanel -X ($UGSM_ExpansionGap) -Y ($UGSM_ExpansionGap) -Width $UGSM_ExpansionLeftPanelWidth -Height $styleTestLeftMinHeight
        [void]$body.Controls.Add($leftPanel)

        $cmbFilter = New-UGSMExpansionEditorComboBox -X 12 -Y 12 -Width ($UGSM_ExpansionLeftPanelWidth - 24)
        $cmbFilter.DropDownStyle = 'DropDownList'
        [void]$cmbFilter.Items.Add('Standard Layout Placeholder')
        $cmbFilter.SelectedIndex = 0
        [void]$leftPanel.Controls.Add($cmbFilter)

        $lstItems = New-Object System.Windows.Forms.ListBox
        $lstItems.Location = New-Object System.Drawing.Point(12, 46)
        $lstItems.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), 620)
        $lstItems.Anchor = 'Top,Left,Bottom,Right'
        $lstItems.BackColor = $global:UGSM_ColorInputBackground
        $lstItems.ForeColor = $global:UGSM_ColorText
        $lstItems.BorderStyle = 'FixedSingle'
        foreach ($item in @($SampleItems)) { [void]$lstItems.Items.Add([string]$item) }
        if ($lstItems.Items.Count -gt 0) { $lstItems.SelectedIndex = 0 }
        [void]$leftPanel.Controls.Add($lstItems)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 700
        [void]$body.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $UGSM_ExpansionTowerHeight
        [void]$editorPanel.Controls.Add($Tower1)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text ($TabName + ' Placeholder') -X 12 -Y 12 -Width 420
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)

        $lblHeaderDesc = New-UGSMExpansionEditorLabel -Text 'This tab now uses the shared standard layout copied from the style template. Original controls are being held back during the conversion pass.' -X 12 -Y 40 -Width 900
        [void]$Tower1.Controls.Add($lblHeaderDesc)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'Tab' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width $UGSM_ExpansionFileFieldWidth
        $txtFile.Text = $TabName
        $txtFile.ReadOnly = $true
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Status' -X $UGSM_ExpansionPathFieldLeft -Y 76 -Width 120
        $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 96 -Width 520
        $txtPath.Text = 'Template layout active. Old tab-specific logic is temporarily bypassed.'
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $UGSM_ExpansionTowerHeight
        [void]$editorPanel.Controls.Add($Tower2)

        $lblTower2 = New-UGSMExpansionEditorLabel -Text 'Conversion Notes' -X 12 -Y 12 -Width 260
        $lblTower2.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower2.Controls.Add($lblTower2)

        $txtInfo = New-Object System.Windows.Forms.TextBox
        $txtInfo.Location = New-Object System.Drawing.Point(12, 40)
        $txtInfo.Size = New-Object System.Drawing.Size(950, 150)
        $txtInfo.Multiline = $true
        $txtInfo.ScrollBars = 'Vertical'
        $txtInfo.ReadOnly = $true
        $txtInfo.BorderStyle = 'FixedSingle'
        $txtInfo.BackColor = $global:UGSM_ColorInputBackground
        $txtInfo.ForeColor = $global:UGSM_ColorText
        $txtInfo.Text = $InfoText
        [void]$Tower2.Controls.Add($txtInfo)

        $Tower3 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $UGSM_ExpansionTowerHeight
        [void]$editorPanel.Controls.Add($Tower3)

        $lblTower3 = New-UGSMExpansionEditorLabel -Text 'Next Step' -X 12 -Y 12 -Width 200
        $lblTower3.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower3.Controls.Add($lblTower3)

        $lblInfo = New-UGSMExpansionEditorLabel -Text 'Rebuild this tab one section at a time inside the shared shell after the layout pass is approved.' -X 12 -Y 44 -Width 920
        [void]$Tower3.Controls.Add($lblInfo)

        $layoutPlaceholder = {
            Set-UGSMExpansionLayout `
                -Page $Page `
                -Root $root `
                -Shell $shell `
                -TopBar $topBar `
                -Body $body `
                -LeftPanel $leftPanel `
                -EditorPanel $editorPanel `
                -Tower1 $Tower1 `
                -Tower2 $Tower2 `
                -Tower3 $Tower3 `
                -CmbFilter $cmbFilter `
                -LstItems $lstItems `
                -TxtPath $txtPath `
                -BtnNew $btnNew `
                -BtnRefresh $btnRefresh `
                -BtnApply $btnApply `
                -BtnSaveCurrent $btnSaveCurrent `
                -BtnSaveAll $btnSaveAll `
                -BtnPretty $btnPretty `
                -BtnRemove $btnRemove
        }.GetNewClosure()

        & $layoutPlaceholder
        $Page.Add_SizeChanged($layoutPlaceholder)
        $Page.Add_VisibleChanged($layoutPlaceholder)

        foreach ($button in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnSaveAll, $btnPretty, $btnRemove)) {
            $button.Add_Click({ if ($StatusLabel) { $StatusLabel.Text = ($TabName + ' placeholder layout active.') } }.GetNewClosure())
        }

        if ($StatusLabel) { $StatusLabel.Text = ($TabName + ' placeholder tab loaded.') }
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) {
            $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace
        }
        Show-UGSMExpansionTabMessage -Page $Page -Title ($TabName + ' placeholder failed') -Message $errorText -TitleColor '#FFB4B4' -ErrorAction SilentlyContinue
        if ($StatusLabel) { $StatusLabel.Text = ($TabName + ' placeholder failed: ' + $_.Exception.Message) }
    }
}


function New-UGSMLabel {
    param(
        [Parameter(Mandatory)][string]$Text,
        [Parameter(Mandatory)][int]$X,
        [Parameter(Mandatory)][int]$Y,
        [int]$Width = 120,
        [int]$Height = 18,
        [double]$FontSize = 8.5,
        [switch]$Bold,
        $Color = $global:UGSM_ColorText
    )

    $label = New-Object System.Windows.Forms.Label
    $label.Text = $Text
    $label.Location = New-Object System.Drawing.Point($X, $Y)
    $label.Size = New-Object System.Drawing.Size($Width, $Height)
    $label.BackColor = [System.Drawing.Color]::Transparent

    if ($Color -is [System.Drawing.Color]) {
        $label.ForeColor = $Color
    }
    elseif (-not [string]::IsNullOrWhiteSpace([string]$Color)) {
        try {
            $label.ForeColor = [System.Drawing.ColorTranslator]::FromHtml([string]$Color)
        }
        catch {
            $label.ForeColor = $global:UGSM_ColorText
        }
    }
    else {
        $label.ForeColor = $global:UGSM_ColorText
    }

    $fontStyle = $(if ($Bold) { [System.Drawing.FontStyle]::Bold } else { [System.Drawing.FontStyle]::Regular })
    $label.Font = New-Object System.Drawing.Font('Segoe UI', [float]$FontSize, $fontStyle)
    return $label
}


function Show-UGSMExpansionTabMessage {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)][string]$Title,
        [Parameter(Mandatory)][string]$Message,
        [string]$TitleColor = '#FFFFFF'
    )

    if ($null -eq $Page) { return }

    $Page.Controls.Clear()
    $Page.BackColor = $global:UGSM_ColorBackground
    $Page.ForeColor = $global:UGSM_ColorText

    $panel = New-Object System.Windows.Forms.Panel
    $panel.Dock = 'Fill'
    $panel.Padding = New-Object System.Windows.Forms.Padding(12)
    $panel.BackColor = $global:UGSM_ColorBackground
    [void]$Page.Controls.Add($panel)

    $lblTitle = New-UGSMLabel -Text $Title -X 0 -Y 0 -Width 1200 -Height 24 -FontSize 11 -Bold -Color $TitleColor
    [void]$panel.Controls.Add($lblTitle)

    $txtMessage = New-Object System.Windows.Forms.TextBox
    $txtMessage.Location = New-Object System.Drawing.Point(0, 32)
    $txtMessage.Size = New-Object System.Drawing.Size(1600, 900)
    $txtMessage.Anchor = 'Top,Left,Right,Bottom'
    $txtMessage.Multiline = $true
    $txtMessage.ReadOnly = $true
    $txtMessage.ScrollBars = 'Vertical'
    $txtMessage.BorderStyle = 'FixedSingle'
    $txtMessage.BackColor = $global:UGSM_ColorInputBackground
    $txtMessage.ForeColor = $global:UGSM_ColorText
    $txtMessage.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    $txtMessage.Text = $Message
    [void]$panel.Controls.Add($txtMessage)
}

function New-DayZExpansionContent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][System.Windows.Forms.Control]$Parent,
        [Parameter(Mandatory)][object]$Instance,
        [Parameter()][object]$StatusLabel
    )

    Initialize-UGSMExpansionThemeDefaults

    $expInstance = $Instance
    if ($null -eq $expInstance) { throw 'Editor instance is not available for Expansion.' }

    $expStatusLabel = $StatusLabel
    $expState = [ordered]@{
        Files         = @()
        Modules       = @()
        CurrentPath   = ''
        CurrentJson   = ''
        CurrentFile   = $null
        ModuleTextMap = @{}
    }

    $Parent.Controls.Clear()

    $rootLayout = New-Object System.Windows.Forms.TableLayoutPanel
    $rootLayout.Dock = 'Fill'
    $rootLayout.BackColor = $global:UGSM_ColorBackground
    $rootLayout.Padding = New-Object System.Windows.Forms.Padding(10, 8, 10, 10)
    $rootLayout.ColumnCount = 1
    $rootLayout.RowCount = 1
    $rootLayout.RowStyles.Clear()
    $rootLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent, 100)))
    [void]$Parent.Controls.Add($rootLayout)

    $tabExpansion = New-Object System.Windows.Forms.TabControl
    $tabExpansion.Dock = 'Fill'
    $tabExpansion.BackColor = $global:UGSM_ColorBackground
    [void]$rootLayout.Controls.Add($tabExpansion, 0, 0)

    $pages = @{}
    foreach ($tabDef in @(Get-UGSMGameDayZExpansionModuleDefinitions)) {
        $page = New-Object System.Windows.Forms.TabPage
        $page.Text = [string]$tabDef.Title
        $page.BackColor = $global:UGSM_ColorBackground
        [void]$tabExpansion.TabPages.Add($page)
        $pages[[string]$tabDef.Key] = $page
    }

    if (-not $pages.ContainsKey('Overview')) { throw "Expansion module definitions missing 'Overview'." }
    if (-not $pages.ContainsKey('Files')) { throw "Expansion module definitions missing 'Files'." }
    if (-not $pages.ContainsKey('Help')) { throw "Expansion module definitions missing 'Help'." }

    $overviewPanel = New-Object System.Windows.Forms.Panel
    $overviewPanel.Dock = 'Fill'
    $overviewPanel.Padding = New-Object System.Windows.Forms.Padding(8)
    $overviewPanel.BackColor = $global:UGSM_ColorBackground
    [void]$pages['Overview'].Controls.Add($overviewPanel)

    $overviewTopBar = New-Object System.Windows.Forms.Panel
    $overviewTopBar.Dock = 'Top'
    $overviewTopBar.Height = 34
    $overviewTopBar.BackColor = $global:UGSM_ColorBackground
    [void]$overviewPanel.Controls.Add($overviewTopBar)

    $btnOpenWiki = New-UGSMButton -Text 'Open Expansion Wiki' -X 0 -Y 2 -Width 150 -Height 28 -BackColor (Convert-UGSMColorToHex $global:UGSM_ColorNeutral)
    [void]$overviewTopBar.Controls.Add($btnOpenWiki)

    $txtOverview = New-Object System.Windows.Forms.TextBox
    $txtOverview.Dock = 'Fill'
    $txtOverview.Multiline = $true
    $txtOverview.ReadOnly = $true
    $txtOverview.ScrollBars = 'Vertical'
    $txtOverview.BorderStyle = 'FixedSingle'
    $txtOverview.BackColor = $global:UGSM_ColorInputBackground
    $txtOverview.ForeColor = $global:UGSM_ColorText
    $txtOverview.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    [void]$overviewPanel.Controls.Add($txtOverview)
    $txtOverview.Text = 'Expansion overview is loading...'

    foreach ($module in @(Get-UGSMGameDayZExpansionModuleDefinitions | Where-Object { $_.Key -notin @('Overview', 'Files', 'Help', 'Settings', 'Traders', 'TraderEntities', 'TraderSetup', 'StyleTest') })) {
        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'
        $panel.Padding = New-Object System.Windows.Forms.Padding(12)
        $panel.BackColor = $global:UGSM_ColorBackground
        [void]$pages[[string]$module.Key].Controls.Add($panel)

        $txt = New-Object System.Windows.Forms.TextBox
        $txt.Dock = 'Fill'
        $txt.Multiline = $true
        $txt.ReadOnly = $true
        $txt.ScrollBars = 'Vertical'
        $txt.BorderStyle = 'FixedSingle'
        $txt.BackColor = $global:UGSM_ColorInputBackground
        $txt.ForeColor = $global:UGSM_ColorText
        $txt.Font = New-Object System.Drawing.Font('Segoe UI', 9)
        [void]$panel.Controls.Add($txt)
        $expState.ModuleTextMap[[string]$module.Key] = $txt
    }

    $helpPanel = New-Object System.Windows.Forms.Panel
    $helpPanel.Dock = 'Fill'
    $helpPanel.Padding = New-Object System.Windows.Forms.Padding(8)
    $helpPanel.BackColor = $global:UGSM_ColorBackground
    [void]$pages['Help'].Controls.Add($helpPanel)

    $txtHelp = New-Object System.Windows.Forms.TextBox
    $txtHelp.Dock = 'Fill'
    $txtHelp.Multiline = $true
    $txtHelp.ReadOnly = $true
    $txtHelp.ScrollBars = 'Vertical'
    $txtHelp.BorderStyle = 'FixedSingle'
    $txtHelp.BackColor = $global:UGSM_ColorInputBackground
    $txtHelp.ForeColor = $global:UGSM_ColorText
    $txtHelp.Font = New-Object System.Drawing.Font('Segoe UI', 9)
    $txtHelp.Text = @"
Expansion Help

Current goal:
- Show a safe skeleton for detected Expansion modules
- Keep raw JSON editing in one place
- Add structured editors later without hiding missing modules

Detection model:
- Profile-side modules are detected from profiles\ExpansionMod\<Module>
- Mission-side modules are detected from mpmissions\<mission>\expansion\<module>
- A module tab stays visible even if the folder is missing

Recommended workflow:
1. Start the server once after enabling an Expansion module
2. Refresh the Expansion tab
3. Confirm the module folder appears and files are listed
4. Use Files for raw edits until a dedicated editor exists

Line endings:
- Expansion JSON should save back as UTF-8 without BOM
- Use the shared DayZ text writer that normalizes line endings to Unix LF
"@
    [void]$helpPanel.Controls.Add($txtHelp)

    $btnOpenWiki.Add_Click({
            try {
                Start-Process 'https://github.com/salutesh/DayZ-Expansion-Scripts/wiki/'
                if ($expStatusLabel) {
                    $expStatusLabel.Text = 'Opened DayZ Expansion wiki.'
                }
            }
            catch {
                if ($expStatusLabel) {
                    $expStatusLabel.Text = 'Opening DayZ Expansion wiki failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure())

    $refreshExpansionData = {
        try {
            $expPaths = Get-UGSMGameDayZExpansionPaths -Instance $expInstance
            $expState.Files = @(Get-UGSMGameDayZExpansionJsonFiles -Instance $expInstance)
            $expState.Modules = @(Get-UGSMGameDayZExpansionDetectedModules -Instance $expInstance)

            $overviewLines = New-Object System.Collections.ArrayList

            [void]$overviewLines.Add('')
            [void]$overviewLines.Add('DayZ Expansion overview')
            [void]$overviewLines.Add('Use the "Open Expansion Wiki" button above for official mod help.')
            [void]$overviewLines.Add('')
            [void]$overviewLines.Add('Expansion discovery summary')
            [void]$overviewLines.Add('')
            [void]$overviewLines.Add(('Profile root: ' + [string]$expPaths.ProfileExpansionRoot))
            [void]$overviewLines.Add(('Mission root: ' + [string]$expPaths.MissionExpansionRoot))
            [void]$overviewLines.Add('')
            [void]$overviewLines.Add(('Total JSON files: ' + [string]@($expState.Files).Count))
            [void]$overviewLines.Add('')
            [void]$overviewLines.Add('Module status:')

            foreach ($module in @($expState.Modules)) {
                $status = $(if ($module.IsDetected) { 'Detected' } else { 'Not detected' })
                [void]$overviewLines.Add((' - {0}: {1} ({2} JSON file(s))' -f [string]$module.Title, $status, [string]$module.JsonFileCount))
                $txtModule = $expState.ModuleTextMap[[string]$module.Key]
                if ($txtModule) {
                    $txtModule.Text = New-DayZExpansionModulePlaceholderText -ModuleState $module
                }
            }

            $txtOverview.Text = [string]::Join("`r`n", @($overviewLines))
            if ($expStatusLabel) { $expStatusLabel.Text = ('Expansion refresh found ' + [string]@($expState.Files).Count + ' JSON file(s).') }
        }
        catch {
            if ($expStatusLabel) { $expStatusLabel.Text = 'Refreshing Expansion files failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()


    & $refreshExpansionData

    try {
        New-DayZExpansionSettingsTab -Page $pages['Settings'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Settings'] -Title 'Settings tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

   

    try {
        New-DayZExpansionMissionsTab -Page $pages['Missions'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
        
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Missions'] -Title 'Missions tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionObjectsTab -Page $pages['Objects'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Objects'] -Title 'Objects tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionP2PMarketTab -Page $pages['P2PMarket'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['P2PMarket'] -Title 'P2P Market tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionPersonalStorageTab -Page $pages['PersonalStorage'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['PersonalStorage'] -Title 'Personal Storage tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionAITab -Page $pages['AI'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['AI'] -Title 'AI tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionATMTab -Page $pages['ATM'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['ATM'] -Title 'ATM tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionGroupsTab -Page $pages['Groups'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Groups'] -Title 'Groups tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    <#try {
        New-DayZExpansionHardlineTab -Page $pages['Hardline'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Hardline'] -Title 'Hardline tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }#>

    try {
        New-DayZExpansionLoadoutsTab -Page $pages['Loadouts'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Loadouts'] -Title 'Loadouts tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionMarketTab -Page $pages['Market'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Market'] -Title 'Market tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

   

    try {
        New-DayZExpansionQuestsTab -Page $pages['Quests'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Quests'] -Title 'Quests tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionFilesTab -Page $pages['Files'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel -RefreshDataAction $refreshExpansionData
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['Files'] -Title 'Files tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    try {
        New-DayZExpansionTraderSetupTab -Page $pages['TraderSetup'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
    }
    catch {
        Show-UGSMExpansionTabMessage -Page $pages['TraderSetup'] -Title 'Trader Setup tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
    }

    if ($pages.ContainsKey('StyleTest')) {
        try {
            New-DayZExpansionStyleTestTab -Page $pages['StyleTest'] -State $expState -Instance $expInstance -StatusLabel $expStatusLabel
        }
        catch {
            Show-UGSMExpansionTabMessage -Page $pages['StyleTest'] -Title 'Style Test tab failed' -Message $_.Exception.Message -TitleColor '#FFB4B4'
        }
    }

}


function New-DayZExpansionTraderSetupTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        $Page.Text = 'Trader Setup'
        $ui = New-UGSMExpansionTabShell -Page $Page
        $ui.Body.AutoScroll = $false
        $ui.ContentHost.AutoScroll = $false

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveSetup = New-UGSMExpansionSaveButton -Text 'Save Trader Setup' -X 0 -Y 0 -Width 150
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Delete Trader' -X 0 -Y 0 -Width 110

        foreach ($b in @($btnNew, $btnRefresh, $btnApply, $btnSaveSetup, $btnPretty, $btnRemove)) {
            [void]$ui.TopBar.Controls.Add($b)
        }

        $leftPanelHeight = [Math]::Max($UGSM_ExpansionLeftPanelMinHeight, 850)
        $tower1Height = 500
        $tower2Height = 330
        $tower3Height = 150
        $editorHeight = $tower1Height + $tower2Height + $tower3Height + ($UGSM_ExpansionSectionGap * 2) + 12

        $leftPanel = New-UGSMExpansionLeftListPanel -X $UGSM_ExpansionGap -Y $UGSM_ExpansionGap -Width $UGSM_ExpansionLeftPanelWidth -Height $leftPanelHeight
        [void]$ui.ContentHost.Controls.Add($leftPanel)

        $lblTraderList = New-UGSMExpansionEditorLabel -Text 'Trader Files' -X 12 -Y 12 -Width 160
        $lblTraderList.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$leftPanel.Controls.Add($lblTraderList)

        $lstTraders = New-Object System.Windows.Forms.ListBox
        $lstTraders.Location = New-Object System.Drawing.Point(12, 40)
        $lstTraders.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), ($leftPanelHeight - 52))
        $lstTraders.Anchor = 'Top,Left,Bottom,Right'
        $lstTraders.BackColor = $global:UGSM_ColorInputBackground
        $lstTraders.ForeColor = $global:UGSM_ColorText
        $lstTraders.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstTraders)

        $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
