        $gridCategories.MultiSelect = $true
        $gridCategories.AutoSizeColumnsMode = 'Fill'
        $gridCategories.RowHeadersVisible = $false
        $gridCategories.EnableHeadersVisualStyles = $false
        $gridCategories.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $gridCategories.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridCategories.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $gridCategories.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridCategories.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $gridCategories.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        [void]$Tower2.Controls.Add($gridCategories)
        $null = $gridCategories.Columns.Add('Category', 'Category')
        $null = $gridCategories.Columns.Add('Mode', 'Mode')
        $gridCategories.Columns['Category'].FillWeight = 84
        $gridCategories.Columns['Mode'].FillWeight = 16

        $lblValidateTitle = New-UGSMExpansionEditorLabel -Text 'Validation / Save' -X 12 -Y 12 -Width 200
        $lblValidateTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower3.Controls.Add($lblValidateTitle)

        $txtValidation = New-Object System.Windows.Forms.TextBox
        $txtValidation.Location = New-Object System.Drawing.Point(12, 40)
        $txtValidation.Size = New-Object System.Drawing.Size(974, 86)
        $txtValidation.Multiline = $true
        $txtValidation.ReadOnly = $true
        $txtValidation.ScrollBars = 'Vertical'
        $txtValidation.BorderStyle = 'FixedSingle'
        $txtValidation.BackColor = $global:UGSM_ColorInputBackground
        $txtValidation.ForeColor = $global:UGSM_ColorText
        $txtValidation.Anchor = 'Top,Left,Right,Bottom'
        [void]$Tower3.Controls.Add($txtValidation)

        $setupState = [ordered]@{
            TraderFiles       = @()
            CurrentTraderPath = ''
            CurrentEntityPath = ''
            PendingTraderData = $null
            PendingEntityRows = $null
            Dirty             = $false
        }

        $splitCommaList = {
            param([string]$Text)
            $list = New-Object System.Collections.ArrayList
            if ([string]::IsNullOrWhiteSpace($Text)) { return @($list) }
            foreach ($part in ([string]$Text).Split(',')) {
                $clean = [string]$part
                if ($null -ne $clean) { $clean = $clean.Trim() }
                if (-not [string]::IsNullOrWhiteSpace($clean)) { [void]$list.Add($clean) }
            }
            return @($list)
        }.GetNewClosure()

        $toIntOrDefault = {
            param($Value, [int]$DefaultValue)
            try {
                if ($null -eq $Value) { return $DefaultValue }
                $text = [string]$Value
                if ([string]::IsNullOrWhiteSpace($text)) { return $DefaultValue }
                return [int]$text
            }
            catch { return $DefaultValue }
        }.GetNewClosure()

        $getTraderJsonRoot = {
            $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
            return (Join-Path ([string]$paths.ProfileExpansionRoot) 'Traders')
        }.GetNewClosure()

        $getTraderEntityRoot = {
            if (Get-Command -Name Get-UGSMGameDayZProfilePaths -ErrorAction SilentlyContinue) {
                $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance
                if ($paths -and $paths.MissionFolderPath) {
                    return (Join-Path ([string]$paths.MissionFolderPath) 'expansion\traders')
                }
            }

            $basePath = ''
            if ($Instance.PSObject.Properties.Name -contains 'GameProfilePath') { $basePath = [string]$Instance.GameProfilePath }
            if ([string]::IsNullOrWhiteSpace($basePath) -and $Instance.PSObject.Properties.Name -contains 'ProfilePath') { $basePath = [string]$Instance.ProfilePath }
            if ([string]::IsNullOrWhiteSpace($basePath)) { throw 'Could not resolve mission path for Expansion traders.' }

            return (Join-Path $basePath 'mpmissions\dayzOffline.chernarusplus\expansion\traders')
        }.GetNewClosure()


        $getTraderZoneRoot = {
            if (Get-Command -Name Get-UGSMGameDayZProfilePaths -ErrorAction SilentlyContinue) {
                $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance
                if ($paths -and $paths.MissionFolderPath) {
                    return (Join-Path ([string]$paths.MissionFolderPath) 'expansion\traderzones')
                }
            }

            $basePath = ''
            if ($Instance.PSObject.Properties.Name -contains 'GameProfilePath') { $basePath = [string]$Instance.GameProfilePath }
            if ([string]::IsNullOrWhiteSpace($basePath) -and $Instance.PSObject.Properties.Name -contains 'ProfilePath') { $basePath = [string]$Instance.ProfilePath }
            if ([string]::IsNullOrWhiteSpace($basePath)) { throw 'Could not resolve mission path for Expansion trader zones.' }

            return (Join-Path $basePath 'mpmissions\dayzOffline.chernarusplus\expansion\traderzones')
        }.GetNewClosure()

        $updateEntityPreview = {
            $entityClass = [string]$cmbEntityClass.Text
            $traderFile = [string]$txtFile.Text
            if ([string]::IsNullOrWhiteSpace($entityClass) -or [string]::IsNullOrWhiteSpace($traderFile)) {
                $txtEntityPreview.Text = ''
                return
            }
            $txtEntityPreview.Text = ('{0}.{1}' -f $entityClass.Trim(), $traderFile.Trim())
        }.GetNewClosure()

        $gearClassNameCache = New-Object System.Collections.ArrayList

        $getGearClassNamesFromTypes = {
            try {
                $allNames = @(Get-UGSMDayZTypesClassNames -Instance $Instance)
                $skipPattern = '^(Zmb|Zombie|Animal_|ExpansionTrader|Survivor|StaticObj|Static|Land_|Ammo|Giftbox)'
                $filtered = @(
                    $allNames |
                    Where-Object {
                        $value = [string]$_
                        -not [string]::IsNullOrWhiteSpace($value) -and $value -notmatch $skipPattern
                    } |
                    Sort-Object -Unique
                )

                if ($filtered.Count -le 0) {
                    $filtered = @('TSHirt_Blue', 'Jeans_Blue', 'WorkingBoots_Brown', 'BaseballCap_Blue', 'Hoodie_Blue', 'WomanSuit_Blue', 'DressShoes_Black')
                }

                return @($filtered)
            }
            catch {
                return @('TSHirt_Blue', 'Jeans_Blue', 'WorkingBoots_Brown', 'BaseballCap_Blue', 'Hoodie_Blue', 'WomanSuit_Blue', 'DressShoes_Black')
            }
        }.GetNewClosure()

        $refreshGearHelper = {
            try {
                $selected = [string]$lstGearHelper.SelectedItem
                $lstGearHelper.BeginUpdate()
                try {
                    $lstGearHelper.Items.Clear()

                    if ($gearClassNameCache.Count -le 0) {
                        foreach ($name in @(& $getGearClassNamesFromTypes)) {
                            if (-not [string]::IsNullOrWhiteSpace([string]$name)) {
                                [void]$gearClassNameCache.Add([string]$name)
                            }
                        }
                    }

                    $needle = ([string]$txtGearSearch.Text).Trim().ToLowerInvariant()
                    foreach ($name in @($gearClassNameCache)) {
                        $value = [string]$name
                        if ([string]::IsNullOrWhiteSpace($needle) -or $value.ToLowerInvariant().Contains($needle)) {
                            [void]$lstGearHelper.Items.Add($value)
                        }
                    }

                    if (-not [string]::IsNullOrWhiteSpace($selected) -and $lstGearHelper.Items.Contains($selected)) {
                        $lstGearHelper.SelectedItem = $selected
                    }
                    elseif ($lstGearHelper.Items.Count -gt 0) {
                        $lstGearHelper.SelectedIndex = 0
                    }
                }
                finally {
                    $lstGearHelper.EndUpdate()
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Refreshing gear helper failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $splitGearTokens = {
            param([string]$Text)
            $tokens = New-Object System.Collections.ArrayList
            foreach ($part in @(([string]$Text) -split ',')) {
                $value = ([string]$part).Trim()
                if (-not [string]::IsNullOrWhiteSpace($value)) {
                    [void]$tokens.Add($value)
                }
            }
            return @($tokens)
        }.GetNewClosure()

        $setGearTokens = {
            param([object[]]$Tokens)
            $clean = New-Object System.Collections.ArrayList
            $seen = @{}
            foreach ($token in @($Tokens)) {
                $value = ([string]$token).Trim()
                if ([string]::IsNullOrWhiteSpace($value)) { continue }
                $key = $value.ToLowerInvariant()
                if ($seen.ContainsKey($key)) { continue }
                $seen[$key] = $true
                [void]$clean.Add($value)
            }
            $txtGear.Text = ([string]::Join(',', @($clean)))
        }.GetNewClosure()

        $addGearToken = {
            param([string]$Token)
            $value = ([string]$Token).Trim()
            if ([string]::IsNullOrWhiteSpace($value)) { return }

            $tokens = New-Object System.Collections.ArrayList
            foreach ($existingToken in @(& $splitGearTokens ([string]$txtGear.Text))) {
                [void]$tokens.Add($existingToken)
            }

            $exists = $false
            foreach ($existingToken in @($tokens)) {
                if ([string]::Equals([string]$existingToken, $value, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $exists = $true
                    break
                }
            }

            if (-not $exists) {
                [void]$tokens.Add($value)
                & $setGearTokens @($tokens)
            }
        }.GetNewClosure()

        $setTraderDisplayNameToken = {
            $displayName = ([string]$txtDisplay.Text).Trim()
            if ([string]::IsNullOrWhiteSpace($displayName)) { return }

            $safeName = $displayName.Replace(',', ' ').Trim()
            $tokens = New-Object System.Collections.ArrayList
            [void]$tokens.Add(('name:{0}' -f $safeName))

            foreach ($existingToken in @(& $splitGearTokens ([string]$txtGear.Text))) {
                $value = ([string]$existingToken).Trim()
                if ($value -match '(?i)^name:') { continue }
                [void]$tokens.Add($value)
            }

            & $setGearTokens @($tokens)
        }.GetNewClosure()

        $normalizeTraderGearForSave = {
            if ($chkSaveTraderNameInGear.Checked) {
                & $setTraderDisplayNameToken
            }
            else {
                & $setGearTokens @(& $splitGearTokens ([string]$txtGear.Text))
            }
            return [string]$txtGear.Text
        }.GetNewClosure()

        $refreshMarketHelper = {
            try {
                $cmbHelperCategory.Items.Clear()
                $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
                $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
                if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) { return }

                $allFiles = @(Get-ChildItem -LiteralPath $marketRoot -File -Filter '*.json' -ErrorAction SilentlyContinue)
                $filtered = New-Object System.Collections.ArrayList
                foreach ($file in $allFiles) {
                    if ($file.Name -notmatch '\.bak(\.|$)') { [void]$filtered.Add($file) }
                }

                foreach ($file in @($filtered | Sort-Object Name)) {
                    [void]$cmbHelperCategory.Items.Add([System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name))
                }

                if ($cmbHelperCategory.Items.Count -gt 0) { $cmbHelperCategory.SelectedIndex = 0 }
            }
            catch {}
        }.GetNewClosure()

        $readTraderFile = {
            param([string]$Path)
            $raw = Read-UGSMGameDayZTextFileSafe -Path $Path
            if ([string]::IsNullOrWhiteSpace([string]$raw)) { return $null }
            return ($raw | ConvertFrom-Json)
        }.GetNewClosure()

        $writeTraderFile = {
            param([string]$Path, $Data)
            [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content ($Data | ConvertTo-Json -Depth 100))
        }.GetNewClosure()

        $readTraderEntityFile = {
            param([string]$Path)
            $rows = New-Object System.Collections.ArrayList
            if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return @($rows) }

            foreach ($line in @(Get-Content -LiteralPath $Path -ErrorAction Stop)) {
                $trimmed = [string]$line
                if ([string]::IsNullOrWhiteSpace($trimmed)) { continue }
                $parts = $trimmed.Trim() -split '\|'
                if (@($parts).Count -lt 3) { continue }

                $left = [string]$parts[0].Trim()
                $entityClass = $left
                $traderFileName = ''
                if ($left -match '^(.+?)\.([^.]+)$') {
                    $entityClass = [string]$matches[1]
                    $traderFileName = [string]$matches[2]
                }

                [void]$rows.Add([pscustomobject]@{
                        TraderEntityClass = $entityClass
                        TraderFileName    = $traderFileName
                        Position          = [string]$parts[1].Trim()
                        Orientation       = [string]$parts[2].Trim()
                        Gear              = $(if (@($parts).Count -ge 4) { [string]$parts[3].Trim() } else { '' })
                    })
            }

            return @($rows)
        }.GetNewClosure()

        $writeTraderEntityFile = {
            param([string]$Path, [object[]]$Rows)
            $lines = New-Object System.Collections.ArrayList
            foreach ($row in @($Rows)) {
                $entityClass = [string]$row.TraderEntityClass
                $traderFileName = [string]$row.TraderFileName
                $position = [string]$row.Position
                $orientation = [string]$row.Orientation
                $gear = [string]$row.Gear

                if ([string]::IsNullOrWhiteSpace($entityClass)) { continue }
                if ([string]::IsNullOrWhiteSpace($traderFileName)) { continue }
                if ([string]::IsNullOrWhiteSpace($position)) { continue }
                if ([string]::IsNullOrWhiteSpace($orientation)) { continue }

                $combined = ('{0}.{1}' -f $entityClass.Trim(), $traderFileName.Trim())
                [void]$lines.Add(('{0}|{1}|{2}|{3}' -f $combined, $position.Trim(), $orientation.Trim(), $gear.Trim()))
            }

            [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content ([string]::Join([Environment]::NewLine, @($lines))))
        }.GetNewClosure()

        $parseVector3 = {
            param([string]$Text, [string]$FieldName)
            if ([string]::IsNullOrWhiteSpace($Text)) { throw ($FieldName + ' is required.') }
            $parts = @(([string]$Text).Trim() -split '\s+')
            if ($parts.Count -ne 3) { throw ($FieldName + ' must be in the format: X Y Z') }
            $x = 0.0; $y = 0.0; $z = 0.0
            if (-not [double]::TryParse($parts[0], [ref]$x)) { throw ($FieldName + ' X must be a valid number.') }
            if (-not [double]::TryParse($parts[1], [ref]$y)) { throw ($FieldName + ' Y must be a valid number.') }
            if (-not [double]::TryParse($parts[2], [ref]$z)) { throw ($FieldName + ' Z must be a valid number.') }
            return [object[]]@($x, $y, $z)
        }.GetNewClosure()

        $toDoubleOrThrow = {
            param([string]$Text, [string]$FieldName)
            $value = 0.0
            if ([string]::IsNullOrWhiteSpace($Text) -or -not [double]::TryParse(([string]$Text).Trim(), [ref]$value)) {
                throw ($FieldName + ' must be a valid number.')
            }
            return $value
        }.GetNewClosure()

        $getSafeZoneSettingsPath = {
            $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
            $candidates = New-Object System.Collections.ArrayList
            if ($paths -and -not [string]::IsNullOrWhiteSpace([string]$paths.ProfileSettingsRoot)) {
                [void]$candidates.Add((Join-Path ([string]$paths.ProfileSettingsRoot) 'SafeZoneSettings.json'))
            }
            if ($paths -and -not [string]::IsNullOrWhiteSpace([string]$paths.MissionSettingsRoot)) {
                [void]$candidates.Add((Join-Path ([string]$paths.MissionSettingsRoot) 'SafeZoneSettings.json'))
            }
            foreach ($candidate in @($candidates)) {
                if (Test-Path -LiteralPath $candidate -PathType Leaf) { return [string]$candidate }
            }
            if ($candidates.Count -gt 0) { return [string]$candidates[0] }
            throw 'Could not resolve Expansion SafeZoneSettings.json path.'
        }.GetNewClosure()

        $ensureSafeZoneData = {
            param($Data)
            if (-not $Data) {
                $Data = [pscustomobject][ordered]@{
                    m_Version                      = 1
                    Enabled                        = 1
                    FrameRateCheckSafeZoneInMs     = 0
                    CircleZones                    = @()
                    PolygonZones                   = @()
                    CylinderZones                  = @()
                    ActorsPerTick                  = 5
                    DisablePlayerCollision         = 0
                    DisableVehicleDamageInSafeZone = 1
                    EnableForceSZCleanup           = 1
                    ItemLifetimeInSafeZone         = 900.0
                    EnableForceSZCleanupVehicles   = 0
                    VehicleLifetimeInSafeZone      = 3600.0
                    ForceSZCleanup_ExcludedItems   = @()
                }
            }
            if (-not $Data.PSObject.Properties['m_Version']) { $Data | Add-Member -NotePropertyName m_Version -NotePropertyValue 1 -Force }
            if (-not $Data.PSObject.Properties['Enabled']) { $Data | Add-Member -NotePropertyName Enabled -NotePropertyValue 1 -Force }
            if (-not $Data.PSObject.Properties['FrameRateCheckSafeZoneInMs']) { $Data | Add-Member -NotePropertyName FrameRateCheckSafeZoneInMs -NotePropertyValue 0 -Force }
            if (-not $Data.PSObject.Properties['CircleZones']) { $Data | Add-Member -NotePropertyName CircleZones -NotePropertyValue @() -Force }
            if (-not $Data.PSObject.Properties['PolygonZones']) { $Data | Add-Member -NotePropertyName PolygonZones -NotePropertyValue @() -Force }
            if (-not $Data.PSObject.Properties['CylinderZones']) { $Data | Add-Member -NotePropertyName CylinderZones -NotePropertyValue @() -Force }
            if (-not $Data.PSObject.Properties['ActorsPerTick']) { $Data | Add-Member -NotePropertyName ActorsPerTick -NotePropertyValue 5 -Force }
            if (-not $Data.PSObject.Properties['DisablePlayerCollision']) { $Data | Add-Member -NotePropertyName DisablePlayerCollision -NotePropertyValue 0 -Force }
            if (-not $Data.PSObject.Properties['DisableVehicleDamageInSafeZone']) { $Data | Add-Member -NotePropertyName DisableVehicleDamageInSafeZone -NotePropertyValue 1 -Force }
            if (-not $Data.PSObject.Properties['EnableForceSZCleanup']) { $Data | Add-Member -NotePropertyName EnableForceSZCleanup -NotePropertyValue 1 -Force }
            if (-not $Data.PSObject.Properties['ItemLifetimeInSafeZone']) { $Data | Add-Member -NotePropertyName ItemLifetimeInSafeZone -NotePropertyValue 900.0 -Force }
            if (-not $Data.PSObject.Properties['EnableForceSZCleanupVehicles']) { $Data | Add-Member -NotePropertyName EnableForceSZCleanupVehicles -NotePropertyValue 0 -Force }
            if (-not $Data.PSObject.Properties['VehicleLifetimeInSafeZone']) { $Data | Add-Member -NotePropertyName VehicleLifetimeInSafeZone -NotePropertyValue 3600.0 -Force }
            if (-not $Data.PSObject.Properties['ForceSZCleanup_ExcludedItems']) { $Data | Add-Member -NotePropertyName ForceSZCleanup_ExcludedItems -NotePropertyValue @() -Force }
            return $Data
        }.GetNewClosure()

        $centerMatches = {
            param($Zone, [object[]]$Center)
            if (-not $Zone -or -not $Zone.PSObject.Properties['Center'] -or -not $Zone.Center) { return $false }
            $zc = @($Zone.Center)
            if ($zc.Count -lt 3 -or $Center.Count -lt 3) { return $false }
            try {
                return (([Math]::Abs(([double]$zc[0]) - ([double]$Center[0])) -lt 0.001) -and
                    ([Math]::Abs(([double]$zc[1]) - ([double]$Center[1])) -lt 0.001) -and
                    ([Math]::Abs(([double]$zc[2]) - ([double]$Center[2])) -lt 0.001))
            }
            catch { return $false }
        }.GetNewClosure()

        $saveTraderZone = {
            if (-not $chkCreateTraderZone.Checked) { return '' }

            $center = & $parseVector3 ([string]$txtPosition.Text) 'Trader Zone Position'
            $radius = & $toDoubleOrThrow ([string]$txtTraderZoneRadius.Text) 'Trader Zone Radius'
            if ($radius -le 0) { throw 'Trader Zone Radius must be greater than zero.' }

            $traderBaseName = ([string]$txtFile.Text).Trim()
            if ([string]::IsNullOrWhiteSpace($traderBaseName)) { throw 'Trader File is required before saving a trader zone.' }
            $traderBaseName = [System.IO.Path]::GetFileNameWithoutExtension($traderBaseName)
            if ([string]::IsNullOrWhiteSpace($traderBaseName)) { throw 'Trader File is required before saving a trader zone.' }

            $zoneRoot = & $getTraderZoneRoot
            if (-not (Test-Path -LiteralPath $zoneRoot -PathType Container)) { [void][System.IO.Directory]::CreateDirectory($zoneRoot) }

            $zoneFileName = ($traderBaseName + 'Zone.json')
            $zonePath = Join-Path $zoneRoot $zoneFileName

            $displayName = ([string]$txtDisplay.Text).Trim()
            if ([string]::IsNullOrWhiteSpace($displayName)) { $displayName = $traderBaseName }

            $zoneData = [pscustomobject][ordered]@{
                m_Version        = 6
                m_DisplayName    = ($displayName + ' Trading Zone')
                Position         = [object[]]@([double]$center[0], [double]$center[1], [double]$center[2])
                Radius           = [double]$radius
                BuyPricePercent  = 100.0
                SellPricePercent = -1.0
                Stock            = [ordered]@{}
            }

            try {
                $helper = Get-UGSMExpansionMarketFileData -Instance $Instance -FileName 'ExpansionMarketTraderZones.json'
                if ($helper -and $helper.Exists -and $helper.Json -and $helper.Json.Categories) {
                    $catNames = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($row in @($gridCategories.Rows)) {
                        if ($row.IsNewRow) { continue }
                        $category = [string]$row.Cells['Category'].Value
                        if ([string]::IsNullOrWhiteSpace($category)) { continue }
                        [void]$catNames.Add($category.Trim())
                    }
                    foreach ($cat in @($helper.Json.Categories)) {
                        $catName = [string]$cat.Name
                        if ([string]::IsNullOrWhiteSpace($catName) -or -not $catNames.Contains($catName.Trim())) { continue }
                        foreach ($itm in @($cat.Items)) {
                            $className = [string]$itm.ClassName
                            if ([string]::IsNullOrWhiteSpace($className)) { continue }
                            $maxStock = 0
                            try { $maxStock = [int]$itm.MaxStockThreshold } catch { $maxStock = 0 }
                            if ($maxStock -le 0) { $maxStock = 375 }
                            $zoneData.Stock[$className.ToLowerInvariant()] = $maxStock
                        }
                    }
                }
            }
            catch {}

            if (Test-Path -LiteralPath $zonePath -PathType Leaf) { [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $zonePath) }
            [void](Write-UGSMGameDayZTextFileSafe -Path $zonePath -Content ($zoneData | ConvertTo-Json -Depth 100))
            return [System.IO.Path]::GetFileName($zonePath)
        }.GetNewClosure()

        $validateSetup = {
            $errors = New-Object System.Collections.ArrayList

            if ([string]::IsNullOrWhiteSpace([string]$txtFile.Text)) { [void]$errors.Add('Trader File is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$txtDisplay.Text)) { [void]$errors.Add('Display Name is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$txtCurrencies.Text)) { [void]$errors.Add('At least one Currency is required.') }
            if ($gridCategories.Rows.Count -eq 0) { [void]$errors.Add('At least one Category is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$cmbEntityClass.Text)) { [void]$errors.Add('Trader Entity is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$txtPosition.Text)) { [void]$errors.Add('Position is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$txtOrientation.Text)) { [void]$errors.Add('Orientation is required.') }
            if ([string]::IsNullOrWhiteSpace([string]$txtEntityFile.Text)) { [void]$errors.Add('Entity File is required.') }
            if ($chkCreateTraderZone.Checked) {
                try { [void](& $parseVector3 ([string]$txtPosition.Text) 'Trader Zone Center') } catch { [void]$errors.Add($_.Exception.Message) }
                try {
                    $zoneRadiusValue = & $toDoubleOrThrow ([string]$txtTraderZoneRadius.Text) 'Trader Zone Radius'
                    if ($zoneRadiusValue -le 0) { [void]$errors.Add('Trader Zone Radius must be greater than zero.') }
                }
                catch { [void]$errors.Add($_.Exception.Message) }
                if ([string]::Equals([string]$cmbTraderZoneShape.Text, 'Cylinder', [System.StringComparison]::OrdinalIgnoreCase)) {
                    try {
                        $zoneHeightValue = & $toDoubleOrThrow ([string]$txtTraderZoneHeight.Text) 'Trader Zone Height'
                        if ($zoneHeightValue -le 0) { [void]$errors.Add('Trader Zone Height must be greater than zero.') }
                    }
                    catch { [void]$errors.Add($_.Exception.Message) }
                }
            }

            if ($errors.Count -eq 0) {
                $txtValidation.Text = "Validation passed.`r`nThe trader JSON and trader entity file are ready to save."
                return $true
            }

            $txtValidation.Text = ('Validation failed:' + [Environment]::NewLine + [string]::Join([Environment]::NewLine, @($errors)))
            return $false
        }.GetNewClosure()

        $refreshTraderFiles = {
            try {
                $root = & $getTraderJsonRoot
                $selectedName = ''
                if ($lstTraders.SelectedItem) { $selectedName = [string]$lstTraders.SelectedItem }

                $setupState.TraderFiles = @()
                $lstTraders.Items.Clear()

                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $allFiles = @(Get-ChildItem -LiteralPath $root -File -Filter '*.json' -ErrorAction SilentlyContinue)
                $filtered = New-Object System.Collections.ArrayList
                foreach ($file in $allFiles) {
                    if ($file.Name -notmatch '\.bak(\.|$)') { [void]$filtered.Add($file) }
                }
                $setupState.TraderFiles = @($filtered | Sort-Object Name)

                foreach ($file in @($setupState.TraderFiles)) {
                    [void]$lstTraders.Items.Add([System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name))
                }

                if ($lstTraders.Items.Count -gt 0) {
                    $restoreIndex = -1
                    if (-not [string]::IsNullOrWhiteSpace($selectedName)) {
                        $restoreIndex = $lstTraders.Items.IndexOf($selectedName)
                    }
                    if ($restoreIndex -lt 0) { $restoreIndex = 0 }
                    $lstTraders.SelectedIndex = $restoreIndex
                }

                & $refreshMarketHelper
                & $refreshGearHelper
                & $updateEntityPreview

                try {
                    $zoneRoot = & $getTraderZoneRoot
                    $zoneBaseName = ([string]$txtFile.Text).Trim()
                    $zoneCandidate = ''
                    if (-not [string]::IsNullOrWhiteSpace($zoneBaseName)) {
                        $zoneCandidate = Join-Path $zoneRoot ($zoneBaseName + 'Zone.json')
                    }

                    if (-not [string]::IsNullOrWhiteSpace($zoneCandidate) -and (Test-Path -LiteralPath $zoneCandidate -PathType Leaf)) {
                        $zoneRaw = Read-UGSMGameDayZTextFileSafe -Path $zoneCandidate
                        if (-not [string]::IsNullOrWhiteSpace([string]$zoneRaw)) {
                            $zoneData = $zoneRaw | ConvertFrom-Json
                            $txtZoneFile.Text = [System.IO.Path]::GetFileNameWithoutExtension($zoneCandidate)
                            $txtZoneDisplay.Text = [string]$zoneData.m_DisplayName
                            if ($zoneData.PSObject.Properties['Radius']) { $txtZoneRadius.Text = [string]$zoneData.Radius }
                            if ($zoneData.PSObject.Properties['BuyPricePercent']) { $txtZoneBuyPct.Text = [string]$zoneData.BuyPricePercent }
                            if ($zoneData.PSObject.Properties['SellPricePercent']) { $txtZoneSellPct.Text = [string]$zoneData.SellPricePercent }
                        }
                    }
                }
                catch {}

                [void](& $validateSetup)
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Refreshing Trader Setup failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $clearEditor = {
            $txtFile.Text = ''
            $txtDisplay.Text = ''
            if ($cmbTraderIcon.Items.Count -gt 0) { $cmbTraderIcon.SelectedIndex = 0 }
            $txtCurrencies.Text = 'expansionbanknotehryvnia'
            $txtDisplayCurrencyValue.Text = '1'
            $txtDisplayCurrencyName.Text = ''
            $txtMinRep.Text = ''
            $txtMaxRep.Text = '2147483647'
            $chkUseCategoryOrder.Checked = $false
            $gridCategories.Rows.Clear()
            if ($cmbEntityClass.Items.Count -gt 0) { $cmbEntityClass.SelectedIndex = 0 }
            $txtEntityPreview.Text = ''
            $txtPosition.Text = ''
            $txtOrientation.Text = '0 0 0'
            $txtGear.Text = ''
            $txtEntityFile.Text = 'UGSM_TraderEntities'
            $chkCreateTraderZone.Checked = $true
            if ($cmbTraderZoneShape.Items.Count -gt 0) { $cmbTraderZoneShape.SelectedIndex = 0 }
            $txtTraderZoneRadius.Text = '75'
            $txtTraderZoneHeight.Text = '120'
            $setupState.CurrentTraderPath = ''
            $setupState.CurrentEntityPath = ''
            $setupState.PendingTraderData = $null
            $setupState.PendingEntityRows = $null
            $setupState.Dirty = $false
            [void](& $validateSetup)
        }.GetNewClosure()

        $loadSelectedTrader = {
            try {
                if ($lstTraders.SelectedIndex -lt 0 -or $lstTraders.SelectedIndex -ge @($setupState.TraderFiles).Count) {
                    return
                }

                $file = $setupState.TraderFiles[$lstTraders.SelectedIndex]
                $data = & $readTraderFile -Path $file.FullName
                if ($null -eq $data) { return }

                $txtFile.Text = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                $txtDisplay.Text = [string]$data.DisplayName
                $cmbTraderIcon.Text = [string]$data.TraderIcon
                $txtCurrencies.Text = 'expansionbanknotehryvnia'
                $txtDisplayCurrencyValue.Text = [string]$data.DisplayCurrencyValue
                $txtDisplayCurrencyName.Text = [string]$data.DisplayCurrencyName
                $txtMinRep.Text = [string]$data.MinRequiredReputation
                $txtMaxRep.Text = [string]$data.MaxRequiredReputation
                $chkUseCategoryOrder.Checked = ([int]$data.UseCategoryOrder -ne 0)

                $gridCategories.Rows.Clear()
                foreach ($entry in @($data.Categories)) {
                    $category = [string]$entry
                    $mode = '1'
                    if ($category -match '^(.*?):([0-3])$') {
                        $category = $matches[1]
                        $mode = $matches[2]
                    }
                    [void]$gridCategories.Rows.Add($category, $mode)
                }

                $setupState.CurrentTraderPath = [string]$file.FullName
                $entityRoot = & $getTraderEntityRoot
                if (-not (Test-Path -LiteralPath $entityRoot -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($entityRoot)
                }
                $allEntityFiles = @(Get-ChildItem -LiteralPath $entityRoot -File -Filter '*.map' -ErrorAction SilentlyContinue)
                $entityFiles = New-Object System.Collections.ArrayList
                foreach ($entityFile in $allEntityFiles) {
                    if ($entityFile.Name -notmatch '\.bak(\.|$)') {
                        [void]$entityFiles.Add($entityFile)
                    }
                }
                $entityFiles = @($entityFiles | Sort-Object Name)

                $matchedRow = $null
                foreach ($entityFile in $entityFiles) {
                    foreach ($row in @(& $readTraderEntityFile -Path $entityFile.FullName)) {
                        if ([string]::Equals([string]$row.TraderFileName, [string]$txtFile.Text, [System.StringComparison]::OrdinalIgnoreCase)) {
                            $matchedRow = $row
                            $setupState.CurrentEntityPath = [string]$entityFile.FullName
                            $txtEntityFile.Text = [System.IO.Path]::GetFileNameWithoutExtension([string]$entityFile.Name)
                            break
                        }
                    }
                    if ($null -ne $matchedRow) { break }
                }

                if ($null -ne $matchedRow) {
                    $cmbEntityClass.Text = [string]$matchedRow.TraderEntityClass
                    $txtPosition.Text = [string]$matchedRow.Position
                    $txtOrientation.Text = [string]$matchedRow.Orientation
                    $txtGear.Text = [string]$matchedRow.Gear
                }
                else {
                    if ($cmbEntityClass.Items.Count -gt 0 -and [string]::IsNullOrWhiteSpace([string]$cmbEntityClass.Text)) {
                        $cmbEntityClass.SelectedIndex = 0
                    }
                    $txtPosition.Text = ''
                    $txtOrientation.Text = '0 0 0'
                    $txtGear.Text = ''
                    $setupState.CurrentEntityPath = ''
                }

                & $updateEntityPreview
                [void](& $validateSetup)

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded Trader Setup: ' + [System.IO.Path]::GetFileName($file.FullName))
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Loading Trader Setup failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $buildTraderData = {
            $currencies = @('expansionbanknotehryvnia')

            $categories = New-Object System.Collections.ArrayList
            foreach ($row in @($gridCategories.Rows)) {
                if ($row.IsNewRow) { continue }
                $category = [string]$row.Cells['Category'].Value
                if ([string]::IsNullOrWhiteSpace($category)) { continue }

                $mode = [string]$row.Cells['Mode'].Value
                if ([string]::IsNullOrWhiteSpace($mode)) { $mode = '1' }

                if ($mode -eq '1') { [void]$categories.Add($category) }
                else { [void]$categories.Add(('{0}:{1}' -f $category, $mode)) }
            }

            return [ordered]@{
                m_Version                = 13
                DisplayName              = [string]$txtDisplay.Text
                TraderIcon               = [string]$cmbTraderIcon.Text
                Currencies               = @($currencies)
                DisplayCurrencyValue     = (& $toIntOrDefault $txtDisplayCurrencyValue.Text 1)
                DisplayCurrencyName      = [string]$txtDisplayCurrencyName.Text
                UseCategoryOrder         = $(if ($chkUseCategoryOrder.Checked) { 1 } else { 0 })
                RequiredFaction          = ''
                RequiredCompletedQuestID = -1
                Categories               = @($categories)
                Items                    = [ordered]@{}
                MinRequiredReputation    = (& $toIntOrDefault $txtMinRep.Text 0)
                MaxRequiredReputation    = (& $toIntOrDefault $txtMaxRep.Text 2147483647)
            }
        }.GetNewClosure()

        $getTraderFileBaseName = {
            param([string]$Name)
            $value = [string]$Name
            if ([string]::IsNullOrWhiteSpace($value)) { return '' }
            return [System.IO.Path]::GetFileNameWithoutExtension($value.Trim())
        }.GetNewClosure()

        $buildEntityRows = {
            $traderBaseName = & $getTraderFileBaseName ([string]$txtFile.Text)
            return @(
                [pscustomobject]@{
                    TraderEntityClass = [string]$cmbEntityClass.Text
                    TraderFileName    = $traderBaseName
                    Position          = [string]$txtPosition.Text
                    Orientation       = [string]$txtOrientation.Text
                    Gear              = (& $normalizeTraderGearForSave)
                }
            )
        }.GetNewClosure()

        $applySetup = {
            try {
                if (-not (& $validateSetup)) { throw 'Validation failed. Fix the highlighted setup values first.' }
                $setupState.PendingTraderData = & $buildTraderData
                $setupState.PendingEntityRows = @(& $buildEntityRows)
                $setupState.Dirty = $true
                if ($StatusLabel) { $StatusLabel.Text = ('Applied Trader Setup for: ' + [string]$txtFile.Text) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Applying Trader Setup failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $saveSetup = {
            try {
                if (-not (& $validateSetup)) { throw 'Validation failed. Fix the setup values first.' }

                $traderData = $(if ($setupState.PendingTraderData) { $setupState.PendingTraderData } else { & $buildTraderData })
                $entityRows = $(if ($setupState.PendingEntityRows) { $setupState.PendingEntityRows } else { @(& $buildEntityRows) })

                $traderFileName = [string]$txtFile.Text
                if ([string]::IsNullOrWhiteSpace($traderFileName)) { throw 'Trader File is required.' }
                if (-not $traderFileName.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) { $traderFileName += '.json' }

                $entityFileName = [string]$txtEntityFile.Text
                if ([string]::IsNullOrWhiteSpace($entityFileName)) { throw 'Entity File is required.' }
                if (-not $entityFileName.EndsWith('.map', [System.StringComparison]::OrdinalIgnoreCase)) { $entityFileName += '.map' }

                $traderRoot = & $getTraderJsonRoot
                $entityRoot = & $getTraderEntityRoot
                if (-not (Test-Path -LiteralPath $traderRoot -PathType Container)) { [void][System.IO.Directory]::CreateDirectory($traderRoot) }
                if (-not (Test-Path -LiteralPath $entityRoot -PathType Container)) { [void][System.IO.Directory]::CreateDirectory($entityRoot) }

                $traderPath = Join-Path $traderRoot $traderFileName
                $entityPath = Join-Path $entityRoot $entityFileName

                if (Test-Path -LiteralPath $traderPath -PathType Leaf) { [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $traderPath) }
                & $writeTraderFile -Path $traderPath -Data $traderData

                $currentTraderBaseName = & $getTraderFileBaseName $traderFileName
                if ([string]::IsNullOrWhiteSpace($currentTraderBaseName)) { throw 'Trader File is required.' }

                $existingEntityRows = @()
                if (Test-Path -LiteralPath $entityPath -PathType Leaf) {
                    $existingEntityRows = @(& $readTraderEntityFile -Path $entityPath)
                    [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $entityPath)
                }

                $mergedEntityRows = New-Object System.Collections.ArrayList
                foreach ($existingRow in @($existingEntityRows)) {
                    $existingTraderBaseName = & $getTraderFileBaseName ([string]$existingRow.TraderFileName)
                    if ([string]::Equals($existingTraderBaseName, $currentTraderBaseName, [System.StringComparison]::OrdinalIgnoreCase)) {
                        continue
                    }
                    [void]$mergedEntityRows.Add([pscustomobject]@{
                            TraderEntityClass = [string]$existingRow.TraderEntityClass
                            TraderFileName    = $existingTraderBaseName
                            Position          = [string]$existingRow.Position
                            Orientation       = [string]$existingRow.Orientation
                            Gear              = [string]$existingRow.Gear
                        })
                }

                foreach ($entityRow in @($entityRows)) {
                    $entityTraderBaseName = & $getTraderFileBaseName ([string]$entityRow.TraderFileName)
                    if ([string]::IsNullOrWhiteSpace($entityTraderBaseName)) { continue }
                    [void]$mergedEntityRows.Add([pscustomobject]@{
                            TraderEntityClass = [string]$entityRow.TraderEntityClass
                            TraderFileName    = $entityTraderBaseName
                            Position          = [string]$entityRow.Position
                            Orientation       = [string]$entityRow.Orientation
                            Gear              = [string]$entityRow.Gear
                        })
                }

                & $writeTraderEntityFile -Path $entityPath -Rows @($mergedEntityRows)

                $savedZoneFile = & $saveTraderZone

                $setupState.CurrentTraderPath = $traderPath
                $setupState.CurrentEntityPath = $entityPath
                $setupState.PendingTraderData = $null
                $setupState.PendingEntityRows = $null
                $setupState.Dirty = $false

                & $refreshTraderFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($traderPath)
                $index = $lstTraders.Items.IndexOf($selectedName)
                if ($index -ge 0) { $lstTraders.SelectedIndex = $index }

                if ($StatusLabel) {
                    $zoneMsg = ''
                    if (-not [string]::IsNullOrWhiteSpace([string]$savedZoneFile)) { $zoneMsg = ' and ' + [string]$savedZoneFile }
                    $StatusLabel.Text = ('Saved Trader Setup: ' + [System.IO.Path]::GetFileName($traderPath) + ', ' + [System.IO.Path]::GetFileName($entityPath) + $zoneMsg)
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Trader Setup failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $prettyPrintSetup = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$setupState.CurrentTraderPath) -or -not (Test-Path -LiteralPath $setupState.CurrentTraderPath -PathType Leaf)) {
                    throw 'Select a saved trader first.'
                }

                $data = & $readTraderFile -Path $setupState.CurrentTraderPath
                [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $setupState.CurrentTraderPath)
                & $writeTraderFile -Path $setupState.CurrentTraderPath -Data $data

                if (-not [string]::IsNullOrWhiteSpace([string]$setupState.CurrentEntityPath) -and (Test-Path -LiteralPath $setupState.CurrentEntityPath -PathType Leaf)) {
                    $rows = & $readTraderEntityFile -Path $setupState.CurrentEntityPath
                    [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $setupState.CurrentEntityPath)
                    & $writeTraderEntityFile -Path $setupState.CurrentEntityPath -Rows $rows
                }

                if ($StatusLabel) { $StatusLabel.Text = 'Pretty printed Trader Setup files.' }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Pretty Print failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $newSetup = {
            & $clearEditor
            $txtFile.Text = 'Trader'
            $txtDisplay.Text = 'Test Trader'
            $txtEntityFile.Text = 'UGSM_TraderEntities'
            & $updateEntityPreview
            [void](& $validateSetup)
            if ($StatusLabel) { $StatusLabel.Text = 'Ready to create a new Trader Setup.' }
        }.GetNewClosure()

        $deleteSetup = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$setupState.CurrentTraderPath)) {
                    throw 'No saved trader is selected.'
                }

                $result = [System.Windows.Forms.MessageBox]::Show(
                    ('Delete trader "' + [System.IO.Path]::GetFileName($setupState.CurrentTraderPath) + '" and optionally leave entity file alone?'),
                    'Delete Trader Setup',
                    [System.Windows.Forms.MessageBoxButtons]::YesNo,
                    [System.Windows.Forms.MessageBoxIcon]::Warning
                )
                if ($result -ne [System.Windows.Forms.DialogResult]::Yes) { return }

                $deletedTraderBaseName = & $getTraderFileBaseName ([System.IO.Path]::GetFileName($setupState.CurrentTraderPath))

                if (Test-Path -LiteralPath $setupState.CurrentTraderPath -PathType Leaf) {
                    [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $setupState.CurrentTraderPath)
                    Remove-Item -LiteralPath $setupState.CurrentTraderPath -Force -ErrorAction Stop
                }

                if (-not [string]::IsNullOrWhiteSpace($deletedTraderBaseName) -and -not [string]::IsNullOrWhiteSpace([string]$setupState.CurrentEntityPath) -and (Test-Path -LiteralPath $setupState.CurrentEntityPath -PathType Leaf)) {
                    $rows = @(& $readTraderEntityFile -Path $setupState.CurrentEntityPath)
                    $filteredRows = New-Object System.Collections.ArrayList
                    foreach ($row in @($rows)) {
                        $rowTraderBaseName = & $getTraderFileBaseName ([string]$row.TraderFileName)
                        if ([string]::Equals($rowTraderBaseName, $deletedTraderBaseName, [System.StringComparison]::OrdinalIgnoreCase)) {
                            continue
                        }
                        [void]$filteredRows.Add([pscustomobject]@{
                                TraderEntityClass = [string]$row.TraderEntityClass
                                TraderFileName    = $rowTraderBaseName
                                Position          = [string]$row.Position
                                Orientation       = [string]$row.Orientation
                                Gear              = [string]$row.Gear
                            })
                    }
                    [void](Backup-UGSMGameDayZFile -Instance $Instance -TargetPath $setupState.CurrentEntityPath)
                    & $writeTraderEntityFile -Path $setupState.CurrentEntityPath -Rows @($filteredRows)
                }

                & $refreshTraderFiles
                & $clearEditor

                if ($StatusLabel) { $StatusLabel.Text = 'Deleted trader JSON file and removed that trader from the entity map.' }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Delete Trader Setup failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $addCategory = {
            $categoryName = [string]$cmbHelperCategory.Text
            $mode = [string]$txtHelperMode.Text
            if ([string]::IsNullOrWhiteSpace($categoryName)) { $categoryName = '' }
            if ([string]::IsNullOrWhiteSpace($mode)) { $mode = '1' }
            [void]$gridCategories.Rows.Add($categoryName, $mode)
            $setupState.Dirty = $true
            [void](& $validateSetup)
        }.GetNewClosure()

        $removeCategory = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $gridCategories.SelectedRows) { [void]$selected.Add($row) }
            if ($selected.Count -eq 0) { return }
            $ordered = @($selected | Sort-Object Index -Descending)
            foreach ($row in $ordered) {
                if (-not $row.IsNewRow) { $gridCategories.Rows.Remove($row) }
            }
            $setupState.Dirty = $true
            [void](& $validateSetup)
        }.GetNewClosure()

        $layout = {
            $ui.TopBar.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Height = [Math]::Max(200, ($ui.Shell.ClientSize.Height - $ui.Body.Top - 4))

            $toolbarY = 8
            $btnNew.Location = New-Object System.Drawing.Point(12, $toolbarY)
            $btnRefresh.Location = New-Object System.Drawing.Point(($btnNew.Right + 10), $toolbarY)
            $btnRemove.Location = New-Object System.Drawing.Point(($ui.TopBar.ClientSize.Width - $btnRemove.Width - 12), $toolbarY)
            $btnPretty.Location = New-Object System.Drawing.Point(($btnRemove.Left - $btnPretty.Width - 10), $toolbarY)
            $btnSaveSetup.Location = New-Object System.Drawing.Point(($btnPretty.Left - $btnSaveSetup.Width - 10), $toolbarY)
            $btnApply.Location = New-Object System.Drawing.Point(($btnSaveSetup.Left - $btnApply.Width - 10), $toolbarY)

            $bodyWidth = $ui.Body.ClientSize.Width
            $bodyHeight = $ui.Body.ClientSize.Height
            $outerGap = $UGSM_ExpansionGap
            $columnGap = $UGSM_ExpansionColumnGap
            $leftWidth = $UGSM_ExpansionLeftPanelWidth

            $editorWidth = [Math]::Max(900, ($bodyWidth - ($outerGap * 2) - $leftWidth - $columnGap))
            $workspaceWidth = $leftWidth + $columnGap + $editorWidth
            $workspaceLeft = [Math]::Max($outerGap, [int](($bodyWidth - $workspaceWidth) / 2))
            $topY = $outerGap

            $leftPanel.Location = New-Object System.Drawing.Point($workspaceLeft, $topY)
            $leftPanel.Width = $leftWidth
            $leftPanel.Height = [Math]::Max(200, ($bodyHeight - ($outerGap * 2) - 8))
            $lstTraders.Height = [Math]::Max(100, ($leftPanel.ClientSize.Height - $lstTraders.Top - 12))

            $editorScrollHost.Location = New-Object System.Drawing.Point(($leftPanel.Right + $columnGap), $topY)
            $editorScrollHost.Width = $editorWidth
            $editorScrollHost.Height = $leftPanel.Height

            $editorPanel.Location = New-Object System.Drawing.Point(0, 0)
            $editorPanel.Width = $editorWidth

            $Tower1.Width = $editorWidth - 1
            $Tower2.Width = $editorWidth - 1
            $Tower3.Width = $editorWidth - 1

            $Tower2.Location = New-Object System.Drawing.Point(0, ($Tower1.Bottom + $UGSM_ExpansionSectionGap))
            $Tower3.Location = New-Object System.Drawing.Point(0, ($Tower2.Bottom + $UGSM_ExpansionSectionGap))
            $editorPanel.Height = $Tower3.Bottom + 1

            $gridCategories.Width = [Math]::Max(420, ($Tower2.ClientSize.Width - 24))
            $gridCategories.Height = [Math]::Max(120, ($Tower2.ClientSize.Height - $gridCategories.Top - 12))
            $txtValidation.Width = [Math]::Max(420, ($Tower3.ClientSize.Width - 24))
            $txtValidation.Height = [Math]::Max(70, ($Tower3.ClientSize.Height - $txtValidation.Top - 12))
        }.GetNewClosure()

        $btnNew.Add_Click({ & $newSetup }.GetNewClosure())
        $btnRefresh.Add_Click({ & $refreshTraderFiles }.GetNewClosure())
        $btnApply.Add_Click({ & $applySetup }.GetNewClosure())
        $btnSaveSetup.Add_Click({ & $saveSetup }.GetNewClosure())
        $btnPretty.Add_Click({ & $prettyPrintSetup }.GetNewClosure())
        $btnRemove.Add_Click({ & $deleteSetup }.GetNewClosure())

        $btnAddCategory.Add_Click({ & $addCategory }.GetNewClosure())
        $btnRemoveCategory.Add_Click({ & $removeCategory }.GetNewClosure())

        $lstTraders.Add_SelectedIndexChanged({ & $loadSelectedTrader }.GetNewClosure())
        $cmbEntityClass.Add_SelectedIndexChanged({ & $updateEntityPreview; [void](& $validateSetup) }.GetNewClosure())
        $txtFile.Add_TextChanged({ & $updateEntityPreview; [void](& $validateSetup) }.GetNewClosure())
        $txtPosition.Add_TextChanged({ [void](& $validateSetup) }.GetNewClosure())
        $txtOrientation.Add_TextChanged({ [void](& $validateSetup) }.GetNewClosure())
        $txtCurrencies.Add_TextChanged({ [void](& $validateSetup) }.GetNewClosure())
        $txtGearSearch.Add_TextChanged({ & $refreshGearHelper }.GetNewClosure())
        $btnRefreshGear.Add_Click({
                $gearClassNameCache.Clear()
                & $refreshGearHelper
            }.GetNewClosure())
        $btnAddGear.Add_Click({
                if ($lstGearHelper.SelectedItem) { & $addGearToken ([string]$lstGearHelper.SelectedItem) }
            }.GetNewClosure())
        $lstGearHelper.Add_DoubleClick({
                if ($lstGearHelper.SelectedItem) { & $addGearToken ([string]$lstGearHelper.SelectedItem) }
            }.GetNewClosure())
        $btnUseDisplayNameGear.Add_Click({ & $setTraderDisplayNameToken }.GetNewClosure())
        $btnClearGear.Add_Click({ $txtGear.Text = '' }.GetNewClosure())

        & $refreshMarketHelper
        & $refreshGearHelper
        & $refreshTraderFiles
        & $updateEntityPreview
        [void](& $validateSetup)
        & $layout
        $Page.Add_SizeChanged($layout)
    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Loading Trader Setup tab failed: ' + $_.Exception.Message
        }
    }
}
























































































































































function Get-UGSMGameDayZExpansionMarketCatalog {
    param([Parameter(Mandatory)]$Instance)

    $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
    $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'

    $result = @()
    if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) {
        return @()
    }

    foreach ($file in @(Get-ChildItem -LiteralPath $marketRoot -File -Filter '*.json' -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -notmatch '\.bak\.json$' -and $_.Name -ne 'HardlineSettings.json' } |
            Sort-Object Name)) {

        try {
            $raw = Read-UGSMGameDayZTextFileSafe -Path $file.FullName
            $data = $raw | ConvertFrom-Json

            $items = New-Object System.Collections.ArrayList
            foreach ($item in @($data.Items)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$item.ClassName)) {
                    [void]$items.Add([string]$item.ClassName)
                }

                foreach ($variant in @($item.Variants)) {
                    if (-not [string]::IsNullOrWhiteSpace([string]$variant)) {
                        [void]$items.Add([string]$variant)
                    }
                }
            }

            $uniqueItems = @($items | Sort-Object -Unique)

            $result += [pscustomobject]@{
                FileName    = [string]$file.Name
                CategoryKey = [System.IO.Path]::GetFileNameWithoutExtension($file.Name)
                DisplayName = [string]$data.DisplayName
                FullName    = [string]$file.FullName
                Items       = @($uniqueItems)
            }
        }
        catch { }
    }

    return @($result)
}

