        'Backpack',
        'Bandage',
        'Bandit',
        'Batteries',
        'Berries',
        'Binoculars',
        'Bolt',
        'Bonfire',
        'Bottle',
        'Bow',
        'Base',
        'Boat',
        'Book 1',
        'Book 2',
        'Broken Lighter',
        'Bear',
        'Car',
        'Car 2',
        'Craft',
        'Can Of Beans Big',
        'Can Of Beans Small',
        'Car Keys',
        'Carrot',
        'Chain Saw',
        'Chicken',
        'Chocolate',
        'Cigarets',
