function New-DayZExpansionTradersTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        $Page.Text = 'Traders'
        $ui = New-UGSMExpansionTabShell -Page $Page
        $ui.Body.AutoScroll = $false
        $ui.ContentHost.AutoScroll = $false

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Trader' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Delete Trader' -X 0 -Y 0 -Width 110

        foreach ($b in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnPretty, $btnRemove)) {
            [void]$ui.TopBar.Controls.Add($b)
        }

        $leftPanelHeight = [Math]::Max($UGSM_ExpansionLeftPanelMinHeight, ($UGSM_ExpansionTowerHeight + 150))
        $tower1Height = $UGSM_ExpansionTowerHeight + 20
        $tower2Height = $UGSM_ExpansionTowerHeight + 150
        $tower3Height = $UGSM_ExpansionTowerHeight + 150

        [int]$bottomPadding = $UGSM_ExpansionScrollBottomPadding

        $leftPanel = New-UGSMExpansionLeftListPanel -X $UGSM_ExpansionGap -Y $UGSM_ExpansionGap -Width $UGSM_ExpansionLeftPanelWidth -Height $leftPanelHeight
        [void]$ui.ContentHost.Controls.Add($leftPanel)

        $lblTraderList = New-UGSMExpansionEditorLabel -Text 'Trader Files' -X 12 -Y 12 -Width 160
        $lblTraderList.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$leftPanel.Controls.Add($lblTraderList)

        $lstTraders = New-Object System.Windows.Forms.ListBox
        $lstTraders.Location = New-Object System.Drawing.Point(12, 40)
        $lstTraders.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), ($leftPanelHeight - 52))
        $lstTraders.Anchor = 'Top,Left,Bottom,Right'
        $lstTraders.BackColor = $global:UGSM_ColorInputBackground
        $lstTraders.ForeColor = $global:UGSM_ColorText
        $lstTraders.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstTraders)

        $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
        $editorWidth = [Math]::Max(700, ($ui.Body.ClientSize.Width - $editorLeft - 320 - 24))
        $editorHeight = $tower1Height + $tower2Height + $tower3Height + ($UGSM_ExpansionSectionGap * 2) + 12

        $editorScrollHost = New-Object System.Windows.Forms.Panel
        $editorScrollHost.Location = New-Object System.Drawing.Point($editorLeft, $UGSM_ExpansionGap)
        $editorScrollHost.Width = $editorWidth
        $editorScrollHost.Height = $leftPanelHeight
        $editorScrollHost.Anchor = 'Top,Left,Right,Bottom'
        $editorScrollHost.AutoScroll = $true
        $editorScrollHost.BackColor = $global:UGSM_ColorBackground
        [void]$ui.ContentHost.Controls.Add($editorScrollHost)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width $editorWidth -Height $editorHeight
        $editorPanel.Anchor = 'Top,Left,Right'
        [void]$editorScrollHost.Controls.Add($editorPanel)

        #$editorPanel = New-UGSMExpansionEditorHost -X $editorLeft -Y $UGSM_ExpansionGap -Width $editorWidth -Height $editorHeight
        #$editorPanel.Anchor = 'Top,Left,Right'
        #[void]$ui.ContentHost.Controls.Add($editorPanel)



        $helperWidth = 300
        $helperPanel = New-UGSMExpansionSectionPanel -X ($editorLeft + $editorWidth + $UGSM_ExpansionColumnGap) -Y $UGSM_ExpansionGap -Width $helperWidth -Height $editorHeight
        $helperPanel.Anchor = 'Top,Right'
        [void]$ui.ContentHost.Controls.Add($helperPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width $editorWidth -Height $tower1Height
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $UGSM_ExpansionSectionGap) -Width $editorWidth -Height $tower2Height
        $Tower3 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $tower2Height + ($UGSM_ExpansionSectionGap * 2)) -Width $editorWidth -Height $tower3Height
        [void]$editorPanel.Controls.Add($Tower1)
        [void]$editorPanel.Controls.Add($Tower2)
        [void]$editorPanel.Controls.Add($Tower3)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text 'Trader Editor' -X 12 -Y 12 -Width 220
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)
        [void]$Tower1.Controls.Add((New-UGSMExpansionEditorLabel -Text 'Edit DayZ Expansion trader files from profiles\ExpansionMod\Traders. m_Version is written automatically and is not shown here.' -X 12 -Y 40 -Width 920))

        $lblFile = New-UGSMExpansionEditorLabel -Text 'Trader File' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width 260
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblDisplay = New-UGSMExpansionEditorLabel -Text 'Display Name' -X 284 -Y 76 -Width 120
        $txtDisplay = New-UGSMExpansionEditorTextBox -X 284 -Y 96 -Width 220
        [void]$Tower1.Controls.Add($lblDisplay)
        [void]$Tower1.Controls.Add($txtDisplay)

        $lblIcon = New-UGSMExpansionEditorLabel -Text 'Trader Icon' -X 516 -Y 76 -Width 100
        $cmbTraderIcon = New-UGSMExpansionEditorComboBox -X 516 -Y 96 -Width 160
        $cmbTraderIcon.DropDownStyle = 'DropDownList'
        foreach ($iconName in @(Get-UGSMGameDayZExpansionDefaultIcons)) {
            [void]$cmbTraderIcon.Items.Add([string]$iconName)
        }
        [void]$Tower1.Controls.Add($lblIcon)
        [void]$Tower1.Controls.Add($cmbTraderIcon)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X 688 -Y 76 -Width 80
        $txtPath = New-UGSMExpansionEditorTextBox -X 688 -Y 96 -Width 298
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        $lblMinRep = New-UGSMExpansionEditorLabel -Text 'Min Reputation' -X 12 -Y 132 -Width 120
        $txtMinRep = New-UGSMExpansionEditorTextBox -X 12 -Y 152 -Width 120
        [void]$Tower1.Controls.Add($lblMinRep)
        [void]$Tower1.Controls.Add($txtMinRep)

        $lblMaxRep = New-UGSMExpansionEditorLabel -Text 'Max Reputation' -X 144 -Y 132 -Width 120
        $txtMaxRep = New-UGSMExpansionEditorTextBox -X 144 -Y 152 -Width 120
        [void]$Tower1.Controls.Add($lblMaxRep)
        [void]$Tower1.Controls.Add($txtMaxRep)

        $lblRequiredFaction = New-UGSMExpansionEditorLabel -Text 'Required Faction' -X 276 -Y 132 -Width 120
        $txtRequiredFaction = New-UGSMExpansionEditorTextBox -X 276 -Y 152 -Width 150
        [void]$Tower1.Controls.Add($lblRequiredFaction)
        [void]$Tower1.Controls.Add($txtRequiredFaction)

        $lblRequiredQuest = New-UGSMExpansionEditorLabel -Text 'Required Quest ID' -X 438 -Y 132 -Width 120
        $txtRequiredQuest = New-UGSMExpansionEditorTextBox -X 438 -Y 152 -Width 120
        [void]$Tower1.Controls.Add($lblRequiredQuest)
        [void]$Tower1.Controls.Add($txtRequiredQuest)

        $lblCurrencies = New-UGSMExpansionEditorLabel -Text 'Currencies' -X 570 -Y 132 -Width 100
        $txtCurrencies = New-UGSMExpansionEditorTextBox -X 570 -Y 152 -Width 180
        [void]$Tower1.Controls.Add($lblCurrencies)
        [void]$Tower1.Controls.Add($txtCurrencies)

        $lblDisplayCurrencyValue = New-UGSMExpansionEditorLabel -Text 'Display Currency Value' -X 762 -Y 132 -Width 120
        $txtDisplayCurrencyValue = New-UGSMExpansionEditorTextBox -X 762 -Y 152 -Width 100
        [void]$Tower1.Controls.Add($lblDisplayCurrencyValue)
        [void]$Tower1.Controls.Add($txtDisplayCurrencyValue)

        $lblDisplayCurrencyName = New-UGSMExpansionEditorLabel -Text 'Display Currency Name' -X 874 -Y 132 -Width 120
        $txtDisplayCurrencyName = New-UGSMExpansionEditorTextBox -X 874 -Y 152 -Width 112
        [void]$Tower1.Controls.Add($lblDisplayCurrencyName)
        [void]$Tower1.Controls.Add($txtDisplayCurrencyName)

        $chkUseCategoryOrder = New-UGSMExpansionCheckBox -Text 'Use Category Order' -X 12 -Y 184 -Width 160
        [void]$Tower1.Controls.Add($chkUseCategoryOrder)

        $lblCategoriesTitle = New-UGSMExpansionEditorLabel -Text 'Categories' -X 12 -Y 12 -Width 220
        $lblCategoriesTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower2.Controls.Add($lblCategoriesTitle)
        [void]$Tower2.Controls.Add((New-UGSMExpansionEditorLabel -Text 'Category mode: 0 buy only, 1 buy/sell, 2 sell only, 3 hidden/customization.' -X 12 -Y 38 -Width 900))

        $btnAddCategory = New-UGSMExpansionAddButton -Text 'Add Category' -X 12 -Y 64 -Width 110
        $btnRemoveCategory = New-UGSMExpansionRemoveButton -Text 'Remove Selected' -X 132 -Y 64 -Width 130
        [void]$Tower2.Controls.Add($btnAddCategory)
        [void]$Tower2.Controls.Add($btnRemoveCategory)

        $gridCategories = New-Object System.Windows.Forms.DataGridView
        $gridCategories.Location = New-Object System.Drawing.Point(12, 100)
        $gridCategories.Size = New-Object System.Drawing.Size(974, 184)
        $gridCategories.Anchor = 'Top,Left,Right,Bottom'
        $gridCategories.BackgroundColor = $global:UGSM_ColorInputBackground
        $gridCategories.ForeColor = $global:UGSM_ColorText
        $gridCategories.BorderStyle = 'FixedSingle'
        $gridCategories.AllowUserToAddRows = $false
        $gridCategories.AllowUserToDeleteRows = $false
        $gridCategories.AllowUserToResizeRows = $false
        $gridCategories.SelectionMode = 'FullRowSelect'
        $gridCategories.MultiSelect = $true
        $gridCategories.AutoSizeColumnsMode = 'Fill'
        $gridCategories.RowHeadersVisible = $false
        $gridCategories.EnableHeadersVisualStyles = $false
        $gridCategories.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $gridCategories.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridCategories.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $gridCategories.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridCategories.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $gridCategories.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        [void]$Tower2.Controls.Add($gridCategories)

        $null = $gridCategories.Columns.Add('Category', 'Category')
        $null = $gridCategories.Columns.Add('Mode', 'Mode')
        $gridCategories.Columns['Category'].FillWeight = 82
        $gridCategories.Columns['Mode'].FillWeight = 18

        $lblItemsTitle = New-UGSMExpansionEditorLabel -Text 'Items' -X 12 -Y 12 -Width 220
        $lblItemsTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower3.Controls.Add($lblItemsTitle)
        [void]$Tower3.Controls.Add((New-UGSMExpansionEditorLabel -Text 'Item mode uses the same values: 0, 1, 2, 3.' -X 12 -Y 38 -Width 900))

        $btnAddItem = New-UGSMExpansionAddButton -Text 'Add Item' -X 12 -Y 64 -Width 90
        $btnRemoveItem = New-UGSMExpansionRemoveButton -Text 'Remove Selected' -X 112 -Y 64 -Width 130
        [void]$Tower3.Controls.Add($btnAddItem)
        [void]$Tower3.Controls.Add($btnRemoveItem)

        $gridItems = New-Object System.Windows.Forms.DataGridView
        $gridItems.Location = New-Object System.Drawing.Point(12, 100)
        $gridItems.Size = New-Object System.Drawing.Size(974, 184)
        $gridItems.Anchor = 'Top,Left,Right,Bottom'
        $gridItems.BackgroundColor = $global:UGSM_ColorInputBackground
        $gridItems.ForeColor = $global:UGSM_ColorText
        $gridItems.BorderStyle = 'FixedSingle'
        $gridItems.AllowUserToAddRows = $false
        $gridItems.AllowUserToDeleteRows = $false
        $gridItems.AllowUserToResizeRows = $false
        $gridItems.SelectionMode = 'FullRowSelect'
        $gridItems.MultiSelect = $true
        $gridItems.AutoSizeColumnsMode = 'Fill'
        $gridItems.RowHeadersVisible = $false
        $gridItems.EnableHeadersVisualStyles = $false
        $gridItems.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $gridItems.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridItems.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $gridItems.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $gridItems.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $gridItems.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        [void]$Tower3.Controls.Add($gridItems)

        $null = $gridItems.Columns.Add('ClassName', 'ClassName')
        $null = $gridItems.Columns.Add('Mode', 'Mode')
        $gridItems.Columns['ClassName'].FillWeight = 88
        $gridItems.Columns['Mode'].FillWeight = 12

        $lblHelperTitle = New-UGSMExpansionEditorLabel -Text 'Market Helper' -X 12 -Y 12 -Width 180
        $lblHelperTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$helperPanel.Controls.Add($lblHelperTitle)

        $lblHelperCategory = New-UGSMExpansionEditorLabel -Text 'Market Category' -X 12 -Y 44 -Width 120
        $cmbHelperCategory = New-UGSMExpansionEditorComboBox -X 12 -Y 64 -Width 270
        $cmbHelperCategory.DropDownStyle = 'DropDownList'
        [void]$helperPanel.Controls.Add($lblHelperCategory)
        [void]$helperPanel.Controls.Add($cmbHelperCategory)

        $lblHelperMode = New-UGSMExpansionEditorLabel -Text 'Mode (0-3)' -X 12 -Y 98 -Width 120
        $txtHelperMode = New-UGSMExpansionEditorTextBox -X 12 -Y 118 -Width 80
        $txtHelperMode.Text = '1'
        $btnAddHelperCategory = New-UGSMExpansionAddButton -Text 'Add Category' -X 102 -Y 116 -Width 110
        [void]$helperPanel.Controls.Add($lblHelperMode)
        [void]$helperPanel.Controls.Add($txtHelperMode)
        [void]$helperPanel.Controls.Add($btnAddHelperCategory)

        $lblHelperItems = New-UGSMExpansionEditorLabel -Text 'Market Items' -X 12 -Y 154 -Width 120
        [void]$helperPanel.Controls.Add($lblHelperItems)

        $lstHelperItems = New-Object System.Windows.Forms.ListBox
        $lstHelperItems.Location = New-Object System.Drawing.Point(12, 174)
        $lstHelperItems.Size = New-Object System.Drawing.Size(270, 230)
        $lstHelperItems.BackColor = $global:UGSM_ColorInputBackground
        $lstHelperItems.ForeColor = $global:UGSM_ColorText
        $lstHelperItems.BorderStyle = 'FixedSingle'
        [void]$helperPanel.Controls.Add($lstHelperItems)

        $btnAddHelperItem = New-UGSMExpansionAddButton -Text 'Add Item' -X 12 -Y 412 -Width 100
        [void]$helperPanel.Controls.Add($btnAddHelperItem)

        $txtHelp = New-Object System.Windows.Forms.TextBox
        $txtHelp.Location = New-Object System.Drawing.Point(12, 450)
        $txtHelp.Size = New-Object System.Drawing.Size(270, 180)
        $txtHelp.Multiline = $true
        $txtHelp.ReadOnly = $true
        $txtHelp.ScrollBars = 'Vertical'
        $txtHelp.BorderStyle = 'FixedSingle'
        $txtHelp.BackColor = $global:UGSM_ColorInputBackground
        $txtHelp.ForeColor = $global:UGSM_ColorText
        $txtHelp.Text = @"
Trader notes

- Categories come from Market filenames without .json
- Category mode: 0 buy only, 1 buy/sell, 2 sell only, 3 hidden/customization
- Items use the same mode values
- Currencies are comma-separated
- m_Version is written automatically
"@
        [void]$helperPanel.Controls.Add($txtHelp)

        $traderState = [ordered]@{
            Files       = @()
            CurrentPath = ''
            PendingData = $null
            Dirty       = $false
        }

        

        $splitCommaList = {
            param([string]$Text)
            $list = New-Object System.Collections.ArrayList
            if ([string]::IsNullOrWhiteSpace($Text)) { return @($list) }
            foreach ($part in ([string]$Text).Split(',')) {
                $clean = [string]$part
                if ($null -ne $clean) { $clean = $clean.Trim() }
                if (-not [string]::IsNullOrWhiteSpace($clean)) {
                    [void]$list.Add($clean)
                }
            }
            return @($list)
        }.GetNewClosure()

        

        $toIntOrDefault = {
            param($Value, [int]$DefaultValue)
            try {
                if ($null -eq $Value) { return $DefaultValue }
                $text = [string]$Value
                if ([string]::IsNullOrWhiteSpace($text)) { return $DefaultValue }
                return [int]$text
            }
            catch {
                return $DefaultValue
            }
        }.GetNewClosure()

        $getTradersRoot = {
            $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
            return (Join-Path ([string]$paths.ProfileExpansionRoot) 'Traders')
        }.GetNewClosure()

        $clearEditor = {
            $txtFile.Text = ''
            $txtDisplay.Text = ''
            $cmbTraderIcon.Text = ''.Text = ''
            $txtPath.Text = ''
            $txtMinRep.Text = ''
            $txtMaxRep.Text = ''
            $txtRequiredFaction.Text = ''
            $txtRequiredQuest.Text = ''
            $txtCurrencies.Text = ''
            $txtDisplayCurrencyValue.Text = '1'
            $txtDisplayCurrencyName.Text = ''
            $chkUseCategoryOrder.Checked = $false
            $gridCategories.Rows.Clear()
            $gridItems.Rows.Clear()
            $traderState.CurrentPath = ''
            $traderState.PendingData = $null
            $traderState.Dirty = $false
        }.GetNewClosure()

        $readTraderFile = {
            param([string]$Path)
            $raw = Read-UGSMGameDayZTextFileSafe -Path $Path
            $data = $raw | ConvertFrom-Json
            return $data
        }.GetNewClosure()

        $writeTraderFile = {
            param([string]$Path, $Data)
            $jsonText = ($Data | ConvertTo-Json -Depth 100)
            [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content $jsonText)
        }.GetNewClosure()

        $refreshTraderFiles = {
            try {
                $root = & $getTradersRoot
                $selectedName = ''
                if ($lstTraders.SelectedItem) {
                    $selectedName = [string]$lstTraders.SelectedItem
                }

                $traderState.Files = @()
                $lstTraders.Items.Clear()

                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $allFiles = @(Get-ChildItem -LiteralPath $root -File -Filter '*.json' -ErrorAction SilentlyContinue)
                $filteredFiles = New-Object System.Collections.ArrayList
                foreach ($file in $allFiles) {
                    if ($file.Name -notmatch '\.bak(\.|$)') {
                        [void]$filteredFiles.Add($file)
                    }
                }
                $traderState.Files = @($filteredFiles | Sort-Object Name)

                foreach ($file in @($traderState.Files)) {
                    [void]$lstTraders.Items.Add([System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name))
                }

                if ($lstTraders.Items.Count -gt 0) {
                    $restoreIndex = -1
                    if (-not [string]::IsNullOrWhiteSpace($selectedName)) {
                        $restoreIndex = $lstTraders.Items.IndexOf($selectedName)
                    }
                    if ($restoreIndex -lt 0) { $restoreIndex = 0 }
                    $lstTraders.SelectedIndex = $restoreIndex
                }
                else {
                    & $clearEditor
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded ' + [string]@($traderState.Files).Count + ' trader file(s).')
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Refreshing trader files failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $loadSelectedTrader = {
            try {
                if ($lstTraders.SelectedIndex -lt 0 -or $lstTraders.SelectedIndex -ge @($traderState.Files).Count) {
                    & $clearEditor
                    return
                }

                $file = $traderState.Files[$lstTraders.SelectedIndex]
                $data = & $readTraderFile -Path $file.FullName

                $txtFile.Text = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                $txtDisplay.Text = [string]$data.DisplayName
                $cmbTraderIcon.Text = [string]$data.TraderIcon
                $txtPath.Text = [string]$file.FullName
                $txtMinRep.Text = [string]$data.MinRequiredReputation
                $txtMaxRep.Text = [string]$data.MaxRequiredReputation
                $txtRequiredFaction.Text = [string]$data.RequiredFaction
                $txtRequiredQuest.Text = [string]$data.RequiredCompletedQuestID
                $txtCurrencies.Text = [string]::Join(', ', @($data.Currencies))
                $txtDisplayCurrencyValue.Text = [string]$data.DisplayCurrencyValue
                $txtDisplayCurrencyName.Text = [string]$data.DisplayCurrencyName
                $chkUseCategoryOrder.Checked = ([int]$data.UseCategoryOrder -ne 0)

                $gridCategories.Rows.Clear()
                foreach ($entry in @($data.Categories)) {
                    $category = [string]$entry
                    $mode = '1'
                    if ($category -match '^(.*?):([0-3])$') {
                        $category = $matches[1]
                        $mode = $matches[2]
                    }
                    [void]$gridCategories.Rows.Add($category, $mode)
                }

                $gridItems.Rows.Clear()
                if ($data.Items) {
                    foreach ($prop in $data.Items.PSObject.Properties) {
                        [void]$gridItems.Rows.Add([string]$prop.Name, [string]$prop.Value)
                    }
                }

                $traderState.CurrentPath = [string]$file.FullName
                $traderState.PendingData = $null
                $traderState.Dirty = $false

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded Trader: ' + [System.IO.Path]::GetFileName($file.FullName))
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Loading trader failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $buildCurrentTraderData = {
            $currencies = & $splitCommaList ([string]$txtCurrencies.Text)

            $categories = New-Object System.Collections.ArrayList
            foreach ($row in @($gridCategories.Rows)) {
                if ($row.IsNewRow) { continue }

                $category = [string]$row.Cells['Category'].Value
                if ([string]::IsNullOrWhiteSpace($category)) { continue }

                $mode = [string]$row.Cells['Mode'].Value
                if ([string]::IsNullOrWhiteSpace($mode)) { $mode = '1' }

                if ($mode -eq '1') {
                    [void]$categories.Add($category)
                }
                else {
                    [void]$categories.Add(('{0}:{1}' -f $category, $mode))
                }
            }

            $itemMap = [ordered]@{}
            foreach ($row in @($gridItems.Rows)) {
                if ($row.IsNewRow) { continue }

                $className = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($className)) { continue }

                $mode = & $toIntOrDefault $row.Cells['Mode'].Value 1
                $itemMap[$className] = $mode
            }

            return [ordered]@{
                m_Version                = 13
                DisplayName              = [string]$txtDisplay.Text
                TraderIcon               = [string]$cmbTraderIcon.Text
                Currencies               = @($currencies)
                DisplayCurrencyValue     = (& $toIntOrDefault $txtDisplayCurrencyValue.Text 1)
                DisplayCurrencyName      = [string]$txtDisplayCurrencyName.Text
                UseCategoryOrder         = $(if ($chkUseCategoryOrder.Checked) { 1 } else { 0 })
                RequiredFaction          = [string]$txtRequiredFaction.Text
                RequiredCompletedQuestID = (& $toIntOrDefault $txtRequiredQuest.Text -1)
                Categories               = @($categories)
                Items                    = $itemMap
                MinRequiredReputation    = (& $toIntOrDefault $txtMinRep.Text 0)
                MaxRequiredReputation    = (& $toIntOrDefault $txtMaxRep.Text 2147483647)
            }
        }.GetNewClosure()

        $applyTrader = {
            try {
                $traderState.PendingData = & $buildCurrentTraderData
                $traderState.Dirty = $true
                if ($StatusLabel) {
                    $StatusLabel.Text = ('Applied draft for Trader: ' + [string]$txtFile.Text)
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Applying trader failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $saveTrader = {
            try {
                $data = $(if ($traderState.PendingData) { $traderState.PendingData } else { & $buildCurrentTraderData })

                $fileName = [string]$txtFile.Text
                if ([string]::IsNullOrWhiteSpace($fileName)) {
                    throw 'Trader File is required.'
                }
                if ($fileName -match '\.bak\.json$') {
                    throw 'Trader File cannot end with .bak.json'
                }
                if (-not $fileName.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) {
                    $fileName += '.json'
                }

                $root = & $getTradersRoot
                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $targetPath = Join-Path $root $fileName
                $oldPath = [string]$traderState.CurrentPath

                if (-not [string]::IsNullOrWhiteSpace($oldPath) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
                    [void](Backup-UGSMGameDayZFile -TargetPath $oldPath)
                }

                & $writeTraderFile -Path $targetPath -Data $data

                if (
                    -not [string]::IsNullOrWhiteSpace($oldPath) -and
                    ($oldPath -ne $targetPath) -and
                    (Test-Path -LiteralPath $oldPath -PathType Leaf)
                ) {
                    Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue
                }

                $traderState.CurrentPath = $targetPath
                $traderState.PendingData = $null
                $traderState.Dirty = $false

                & $refreshTraderFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstTraders.Items.IndexOf($selectedName)
                if ($index -ge 0) {
                    $lstTraders.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Trader: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving trader failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $newTrader = {
            try {
                $root = & $getTradersRoot
                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $baseName = 'NewTrader'
                $filePath = Join-Path $root ($baseName + '.json')
                if (Test-Path -LiteralPath $filePath -PathType Leaf) {
                    for ($i = 1; $i -le 999; $i++) {
                        $candidate = Join-Path $root ('{0}_{1:D2}.json' -f $baseName, $i)
                        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                            $filePath = $candidate
                            break
                        }
                    }
                }

                $data = [ordered]@{
                    m_Version                = 13
                    DisplayName              = 'New Trader'
                    MinRequiredReputation    = 0
                    MaxRequiredReputation    = 2147483647
                    RequiredFaction          = ''
                    RequiredCompletedQuestID = -1
                    TraderIcon               = 'Trader'
                    Currencies               = @()
                    DisplayCurrencyValue     = 1
                    DisplayCurrencyName      = ''
                    UseCategoryOrder         = 0
                    Categories               = @()
                    Items                    = @{}
                }

                & $writeTraderFile -Path $filePath -Data $data
                & $refreshTraderFiles

                $newName = [System.IO.Path]::GetFileNameWithoutExtension($filePath)
                $index = $lstTraders.Items.IndexOf($newName)
                if ($index -ge 0) {
                    $lstTraders.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Created Trader: ' + [System.IO.Path]::GetFileName($filePath))
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Creating trader failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $deleteTrader = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$traderState.CurrentPath)) {
                    throw 'No trader file is selected.'
                }

                $fileName = [System.IO.Path]::GetFileName($traderState.CurrentPath)
                $result = [System.Windows.Forms.MessageBox]::Show(
                    ('Delete trader file "' + $fileName + '"?'),
                    'Delete Trader',
                    [System.Windows.Forms.MessageBoxButtons]::YesNo,
                    [System.Windows.Forms.MessageBoxIcon]::Warning
                )

                if ($result -ne [System.Windows.Forms.DialogResult]::Yes) { return }

                [void](Backup-UGSMGameDayZFile -TargetPath $traderState.CurrentPath)
                Remove-Item -LiteralPath $traderState.CurrentPath -Force -ErrorAction Stop

                & $refreshTraderFiles
                & $clearEditor

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Deleted Trader: ' + $fileName)
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Deleting trader failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $prettyPrintTrader = {
            try {
                $targetPath = [string]$traderState.CurrentPath
                if ([string]::IsNullOrWhiteSpace($targetPath) -or -not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                    throw 'Select a trader first.'
                }

                $data = & $readTraderFile -Path $targetPath
                [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
                & $writeTraderFile -Path $targetPath -Data $data
                & $refreshTraderFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstTraders.Items.IndexOf($selectedName)
                if ($index -ge 0) {
                    $lstTraders.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Pretty printed Trader: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Pretty Print failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $addCategory = {
            [void]$gridCategories.Rows.Add('', '1')
            $traderState.Dirty = $true
        }.GetNewClosure()

        $removeCategory = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $gridCategories.SelectedRows) {
                [void]$selected.Add($row)
            }
            if ($selected.Count -eq 0) { return }

            $ordered = @($selected | Sort-Object Index -Descending)
            foreach ($row in $ordered) {
                if (-not $row.IsNewRow) {
                    $gridCategories.Rows.Remove($row)
                }
            }
            $traderState.Dirty = $true
        }.GetNewClosure()

        $addItem = {
            [void]$gridItems.Rows.Add('', '1')
            $traderState.Dirty = $true
        }.GetNewClosure()

        $removeItem = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $gridItems.SelectedRows) {
                [void]$selected.Add($row)
            }
            if ($selected.Count -eq 0) { return }

            $ordered = @($selected | Sort-Object Index -Descending)
            foreach ($row in $ordered) {
                if (-not $row.IsNewRow) {
                    $gridItems.Rows.Remove($row)
                }
            }
            $traderState.Dirty = $true
        }.GetNewClosure()

        $loadMarketHelper = {
            try {
                $cmbHelperCategory.Items.Clear()
                $lstHelperItems.Items.Clear()

                $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
                $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
                if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) { return }

                $allFiles = @(Get-ChildItem -LiteralPath $marketRoot -File -Filter '*.json' -ErrorAction SilentlyContinue)
                $marketFiles = New-Object System.Collections.ArrayList
                foreach ($file in $allFiles) {
                    if ($file.Name -notmatch '\.bak(\.|$)') {
                        [void]$marketFiles.Add($file)
                    }
                }

                foreach ($file in @($marketFiles | Sort-Object Name)) {
                    [void]$cmbHelperCategory.Items.Add([System.IO.Path]::GetFileNameWithoutExtension($file.Name))
                }

                if ($cmbHelperCategory.Items.Count -gt 0) {
                    $cmbHelperCategory.SelectedIndex = 0
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Loading Market helper failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $loadHelperItems = {
            try {
                $lstHelperItems.Items.Clear()
                if ($cmbHelperCategory.SelectedIndex -lt 0) { return }

                $categoryName = [string]$cmbHelperCategory.SelectedItem
                if ([string]::IsNullOrWhiteSpace($categoryName)) { return }

                $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
                $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
                $filePath = Join-Path $marketRoot ($categoryName + '.json')
                if (-not (Test-Path -LiteralPath $filePath -PathType Leaf)) { return }

                $data = Read-UGSMGameDayZJsonDataSafe -Path $filePath
                foreach ($item in @($data.Items)) {
                    if (-not [string]::IsNullOrWhiteSpace([string]$item.ClassName)) {
                        [void]$lstHelperItems.Items.Add([string]$item.ClassName)
                    }
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Loading helper items failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $addHelperCategory = {
            try {
                if ($cmbHelperCategory.SelectedIndex -lt 0) {
                    throw 'Select a Market category first.'
                }

                $categoryName = [string]$cmbHelperCategory.SelectedItem
                $mode = [string]$txtHelperMode.Text
                if ([string]::IsNullOrWhiteSpace($mode)) { $mode = '1' }

                [void]$gridCategories.Rows.Add($categoryName, $mode)
                $traderState.Dirty = $true
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Add Category failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $addHelperItem = {
            try {
                if ($lstHelperItems.SelectedIndex -lt 0) {
                    throw 'Select a Market item first.'
                }

                $className = [string]$lstHelperItems.SelectedItem
                $mode = [string]$txtHelperMode.Text
                if ([string]::IsNullOrWhiteSpace($mode)) { $mode = '1' }

                [void]$gridItems.Rows.Add($className, $mode)
                $traderState.Dirty = $true
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Add Item failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $layout = {
            $ui.TopBar.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Height = [Math]::Max(200, ($ui.Shell.ClientSize.Height - $ui.Body.Top - 4))

            $bodyWidth = $ui.Body.ClientSize.Width
            $bodyHeight = $ui.Body.ClientSize.Height
            $outerGap = $UGSM_ExpansionGap
            $columnGap = $UGSM_ExpansionColumnGap
            $leftWidth = $UGSM_ExpansionLeftPanelWidth
            $helperWidth = 300
            $toolbarY = 8

            # Manual toolbar layout so buttons stop stacking/fighting.
            $btnNew.Location = New-Object System.Drawing.Point(12, $toolbarY)
            $btnRefresh.Location = New-Object System.Drawing.Point(($btnNew.Right + 10), $toolbarY)

            $btnRemove.Location = New-Object System.Drawing.Point(($ui.TopBar.ClientSize.Width - $btnRemove.Width - 12), $toolbarY)
            $btnPretty.Location = New-Object System.Drawing.Point(($btnRemove.Left - $btnPretty.Width - 10), $toolbarY)
            $btnSaveCurrent.Location = New-Object System.Drawing.Point(($btnPretty.Left - $btnSaveCurrent.Width - 10), $toolbarY)
            $btnApply.Location = New-Object System.Drawing.Point(($btnSaveCurrent.Left - $btnApply.Width - 10), $toolbarY)

            $leftPanelHeight = [Math]::Max(200, ($bodyHeight - ($outerGap * 2) - 8))
            $editorScrollHeight = $leftPanelHeight
            $helperHeight = $leftPanelHeight

            $editorWidth = [Math]::Max(
                700,
                ($bodyWidth - ($outerGap * 2) - $leftWidth - $helperWidth - ($columnGap * 2))
            )

            $workspaceWidth = $leftWidth + $columnGap + $editorWidth + $columnGap + $helperWidth
            $workspaceLeft = [Math]::Max($outerGap, [int](($bodyWidth - $workspaceWidth) / 2))
            $topY = $outerGap

            $leftPanel.Location = New-Object System.Drawing.Point($workspaceLeft, $topY)
            $leftPanel.Width = $leftWidth
            $leftPanel.Height = $leftPanelHeight
            $lstTraders.Height = [Math]::Max(100, ($leftPanel.ClientSize.Height - $lstTraders.Top - 12))

            $editorScrollHost.Location = New-Object System.Drawing.Point(($leftPanel.Right + $columnGap), $topY)
            $editorScrollHost.Width = $editorWidth
            $editorScrollHost.Height = $editorScrollHeight

            $editorPanel.Location = New-Object System.Drawing.Point(0, 0)
            $editorPanel.Width = $editorWidth
            $editorPanel.Height = $editorHeight

            $helperPanel.Location = New-Object System.Drawing.Point(($editorScrollHost.Right + $columnGap), $topY)
            $helperPanel.Width = $helperWidth
            $helperPanel.Height = $helperHeight

            $Tower1.Location = New-Object System.Drawing.Point(0, 0)
            $Tower1.Width = $editorWidth - 1
            $Tower1.Height = $tower1Height

            $Tower2.Location = New-Object System.Drawing.Point(0, ($Tower1.Bottom + $UGSM_ExpansionSectionGap))
            $Tower2.Width = $editorWidth - 1
            $Tower2.Height = $tower2Height

            $Tower3.Location = New-Object System.Drawing.Point(0, ($Tower2.Bottom + $UGSM_ExpansionSectionGap))
            $Tower3.Width = $editorWidth - 1
            $Tower3.Height = $tower3Height

            $editorPanel.Height = $Tower3.Bottom + 1

            $txtPath.Width = [Math]::Max(180, ($Tower1.ClientSize.Width - $txtPath.Left - 12))

            $gridCategories.Width = [Math]::Max(420, ($Tower2.ClientSize.Width - 24))
            $gridCategories.Height = [Math]::Max(120, ($Tower2.ClientSize.Height - $gridCategories.Top - 12))

            $gridItems.Width = [Math]::Max(420, ($Tower3.ClientSize.Width - 24))
            $gridItems.Height = [Math]::Max(120, ($Tower3.ClientSize.Height - $gridItems.Top - 12))

            $cmbHelperCategory.Width = [Math]::Max(120, ($helperPanel.ClientSize.Width - $cmbHelperCategory.Left - 12))
            $lstHelperItems.Width = [Math]::Max(120, ($helperPanel.ClientSize.Width - 24))
            $txtHelp.Width = [Math]::Max(120, ($helperPanel.ClientSize.Width - 24))
            $txtHelp.Height = [Math]::Max(120, ($helperPanel.ClientSize.Height - $txtHelp.Top - 12))
        }.GetNewClosure()

        $btnNew.Add_Click({ & $newTrader }.GetNewClosure())
        $btnRefresh.Add_Click({
                & $refreshTraderFiles
                & $loadMarketHelper
            }.GetNewClosure())
        $btnApply.Add_Click({ & $applyTrader }.GetNewClosure())
        $btnSaveCurrent.Add_Click({ & $saveTrader }.GetNewClosure())
        $btnPretty.Add_Click({ & $prettyPrintTrader }.GetNewClosure())
        $btnRemove.Add_Click({ & $deleteTrader }.GetNewClosure())

        $btnAddCategory.Add_Click({ & $addCategory }.GetNewClosure())
        $btnRemoveCategory.Add_Click({ & $removeCategory }.GetNewClosure())
        $btnAddItem.Add_Click({ & $addItem }.GetNewClosure())
        $btnRemoveItem.Add_Click({ & $removeItem }.GetNewClosure())

        $btnAddHelperCategory.Add_Click({ & $addHelperCategory }.GetNewClosure())
        $btnAddHelperItem.Add_Click({ & $addHelperItem }.GetNewClosure())

        $lstTraders.Add_SelectedIndexChanged({ & $loadSelectedTrader }.GetNewClosure())
        $cmbHelperCategory.Add_SelectedIndexChanged({ & $loadHelperItems }.GetNewClosure())

        & $refreshTraderFiles
        & $loadMarketHelper
        & $layout
        $Page.Add_SizeChanged($layout)

    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Loading Expansion Trader tab failed: ' + $_.Exception.Message
        }
    }
}

function New-DayZExpansionTraderEntitiesTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        $Page.Text = 'Trader Entities'
        $ui = New-UGSMExpansionTabShell -Page $Page

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Delete File' -X 0 -Y 0 -Width 110

        foreach ($b in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnPretty, $btnRemove)) {
            [void]$ui.TopBar.Controls.Add($b)
        }

        $leftPanelHeight = [Math]::Max($UGSM_ExpansionLeftPanelMinHeight, ($UGSM_ExpansionTowerHeight + 220))
        $tower1Height = $UGSM_ExpansionTowerHeight + 20
        $tower2Height = $UGSM_ExpansionTowerHeight + 220

        $leftPanel = New-UGSMExpansionLeftListPanel -X $UGSM_ExpansionGap -Y $UGSM_ExpansionGap -Width $UGSM_ExpansionLeftPanelWidth -Height $leftPanelHeight
        [void]$ui.ContentHost.Controls.Add($leftPanel)

        $lblFiles = New-UGSMExpansionEditorLabel -Text 'Trader Entity Files' -X 12 -Y 12 -Width 180
        $lblFiles.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$leftPanel.Controls.Add($lblFiles)

        $lstFiles = New-Object System.Windows.Forms.ListBox
        $lstFiles.Location = New-Object System.Drawing.Point(12, 40)
        $lstFiles.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), ($leftPanelHeight - 52))
        $lstFiles.Anchor = 'Top,Left,Bottom,Right'
        $lstFiles.BackColor = $global:UGSM_ColorInputBackground
        $lstFiles.ForeColor = $global:UGSM_ColorText
        $lstFiles.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstFiles)

        $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
        $editorWidth = [Math]::Max(760, ($ui.Body.ClientSize.Width - $editorLeft - 24))
        $editorHeight = $tower1Height + $tower2Height + $UGSM_ExpansionSectionGap + 12

        $editorScrollHost = New-Object System.Windows.Forms.Panel
        $editorScrollHost.Location = New-Object System.Drawing.Point($editorLeft, $UGSM_ExpansionGap)
        $editorScrollHost.Width = $editorWidth
        $editorScrollHost.Height = $leftPanelHeight
        $editorScrollHost.Anchor = 'Top,Left,Right,Bottom'
        $editorScrollHost.AutoScroll = $true
        $editorScrollHost.BackColor = $global:UGSM_ColorBackground
        [void]$ui.ContentHost.Controls.Add($editorScrollHost)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width $editorWidth -Height $editorHeight
        $editorPanel.Anchor = 'Top,Left,Right'
        [void]$editorScrollHost.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width $editorWidth -Height $tower1Height
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $UGSM_ExpansionSectionGap) -Width $editorWidth -Height $tower2Height
        [void]$editorPanel.Controls.Add($Tower1)
        [void]$editorPanel.Controls.Add($Tower2)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text 'Trader Entities Editor' -X 12 -Y 12 -Width 260
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)

        $lblHeaderText = New-UGSMExpansionEditorLabel -Text 'Edit Expansion trader placement files from mpmissions\<map>\expansion\traders. Each row is saved as TraderEntityClass.TraderFileName|Position|Orientation|Gear.' -X 12 -Y 40 -Width 980
        [void]$Tower1.Controls.Add($lblHeaderText)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'Trader File' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width 260
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X 284 -Y 76 -Width 80
        $txtPath = New-UGSMExpansionEditorTextBox -X 284 -Y 96 -Width 702
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        $lblEntity = New-UGSMExpansionEditorLabel -Text 'Trader Entity' -X 12 -Y 132 -Width 100
        $cmbEntityClass = New-UGSMExpansionEditorComboBox -X 12 -Y 152 -Width 220
        $cmbEntityClass.DropDownStyle = 'DropDownList'
        foreach ($name in @(
