    [void]$lootPanel.Controls.Add($btnRemoveLoot)

    $gridLoot = New-Object System.Windows.Forms.DataGridView
    $gridLoot.Location = New-Object System.Drawing.Point(12, 44)
    $gridLoot.Size = New-Object System.Drawing.Size(($maxWidth - 26), 300)
    $gridLoot.BackgroundColor = $global:UGSM_ColorInputBackground
    $gridLoot.BorderStyle = 'FixedSingle'
    $gridLoot.GridColor = $global:UGSM_ColorGrid
    $gridLoot.EnableHeadersVisualStyles = $false
    $gridLoot.AutoGenerateColumns = $true
    $gridLoot.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorPanelBackground
    $gridLoot.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridLoot.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
    $gridLoot.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridLoot.DefaultCellStyle.SelectionBackColor = $UGSM_ExpansionAccentColor
    $gridLoot.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
    $gridLoot.RowHeadersVisible = $false
    $gridLoot.AllowUserToAddRows = $false
    $gridLoot.AllowUserToDeleteRows = $false
    $gridLoot.AllowUserToResizeRows = $false
    $gridLoot.SelectionMode = 'CellSelect'
    $gridLoot.EditMode = 'EditOnEnter'
    $gridLoot.AutoSizeColumnsMode = 'None'
    [void]$lootPanel.Controls.Add($gridLoot)

    $infectedPanel = New-Object System.Windows.Forms.Panel
    $infectedPanel.Location = New-Object System.Drawing.Point(0, 855)
    $infectedPanel.Size = New-Object System.Drawing.Size($maxWidth, 260)
    $infectedPanel.BackColor = $global:UGSM_ColorPanelBackground
    $infectedPanel.BorderStyle = 'FixedSingle'
    [void]$missionHost.Controls.Add($infectedPanel)

    $lblInfTitle = New-Object System.Windows.Forms.Label
    $lblInfTitle.Text = 'Infected Entries'
    $lblInfTitle.Location = New-Object System.Drawing.Point(12, 10)
    $lblInfTitle.Size = New-Object System.Drawing.Size(220, 24)
    $lblInfTitle.ForeColor = $global:UGSM_ColorText
    $lblInfTitle.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
    [void]$infectedPanel.Controls.Add($lblInfTitle)

    $btnAddInfected = New-Object System.Windows.Forms.Button
    $btnAddInfected.Text = 'Add Infected'
    $btnAddInfected.Location = New-Object System.Drawing.Point(1320, 8)
    $btnAddInfected.Size = New-Object System.Drawing.Size(110, 28)
    $btnAddInfected.BackColor = $UGSM_ExpansionAccentColor
    $btnAddInfected.ForeColor = $global:UGSM_ColorText
    $btnAddInfected.FlatStyle = 'Flat'
    $btnAddInfected.UseVisualStyleBackColor = $false
    [void]$infectedPanel.Controls.Add($btnAddInfected)

    $btnRemoveInfected = New-Object System.Windows.Forms.Button
    $btnRemoveInfected.Text = 'Remove Infected'
    $btnRemoveInfected.Location = New-Object System.Drawing.Point(1200, 8)
    $btnRemoveInfected.Size = New-Object System.Drawing.Size(110, 28)
    $btnRemoveInfected.BackColor = $global:UGSM_ColorDanger
    $btnRemoveInfected.ForeColor = $global:UGSM_ColorText
    $btnRemoveInfected.FlatStyle = 'Flat'
    $btnRemoveInfected.UseVisualStyleBackColor = $false
    [void]$infectedPanel.Controls.Add($btnRemoveInfected)

    $gridInfected = New-Object System.Windows.Forms.DataGridView
    $gridInfected.Location = New-Object System.Drawing.Point(12, 44)
    $gridInfected.Size = New-Object System.Drawing.Size(($maxWidth - 26), 200)
    $gridInfected.BackgroundColor = $global:UGSM_ColorInputBackground
    $gridInfected.BorderStyle = 'FixedSingle'
    $gridInfected.GridColor = $global:UGSM_ColorGrid
    $gridInfected.EnableHeadersVisualStyles = $false
    $gridInfected.AutoGenerateColumns = $true
    $gridInfected.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorPanelBackground
    $gridInfected.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridInfected.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
    $gridInfected.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridInfected.DefaultCellStyle.SelectionBackColor = $UGSM_ExpansionAccentColor
    $gridInfected.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
    $gridInfected.RowHeadersVisible = $false
    $gridInfected.AllowUserToAddRows = $false
    $gridInfected.AllowUserToDeleteRows = $false
    $gridInfected.AllowUserToResizeRows = $false
    $gridInfected.SelectionMode = 'CellSelect'
    $gridInfected.EditMode = 'EditOnEnter'
    $gridInfected.AutoSizeColumnsMode = 'None'
    [void]$infectedPanel.Controls.Add($gridInfected)

    $lootTable = New-Object System.Data.DataTable
    [void]$lootTable.Columns.Add('Name', [string])
    [void]$lootTable.Columns.Add('Chance', [string])
    [void]$lootTable.Columns.Add('QuantityPercent', [string])
    [void]$lootTable.Columns.Add('Max', [string])
    [void]$lootTable.Columns.Add('Attachments', [string])
    [void]$lootTable.Columns.Add('Variants', [string])

    $infectedTable = New-Object System.Data.DataTable
    [void]$infectedTable.Columns.Add('ClassName', [string])

    $bindLootColumns = {
        $gridLoot.AutoGenerateColumns = $false
        $gridLoot.Columns.Clear()
        $gridLoot.DataSource = $null

        $lootNameCol = New-Object System.Windows.Forms.DataGridViewComboBoxColumn
        $lootNameCol.Name = 'Name'
        $lootNameCol.HeaderText = 'Name'
        $lootNameCol.DataPropertyName = 'Name'
        $lootNameCol.Width = 340
        $lootNameCol.FlatStyle = 'Flat'
        foreach ($item in @($editorState.ItemClassNames)) {
            [void]$lootNameCol.Items.Add([string]$item)
        }
        [void]$gridLoot.Columns.Add($lootNameCol)

        $colChance = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $colChance.Name = 'Chance'
        $colChance.HeaderText = 'Chance'
        $colChance.DataPropertyName = 'Chance'
        $colChance.Width = 110
        [void]$gridLoot.Columns.Add($colChance)

        $colQuantityPercent = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $colQuantityPercent.Name = 'QuantityPercent'
        $colQuantityPercent.HeaderText = 'QuantityPercent'
        $colQuantityPercent.DataPropertyName = 'QuantityPercent'
        $colQuantityPercent.Width = 130
        [void]$gridLoot.Columns.Add($colQuantityPercent)

        $colMax = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $colMax.Name = 'Max'
        $colMax.HeaderText = 'Max'
        $colMax.DataPropertyName = 'Max'
        $colMax.Width = 90
        [void]$gridLoot.Columns.Add($colMax)

        $colAttachments = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $colAttachments.Name = 'Attachments'
        $colAttachments.HeaderText = 'Attachments'
        $colAttachments.DataPropertyName = 'Attachments'
        $colAttachments.Width = 360
        [void]$gridLoot.Columns.Add($colAttachments)

        $colVariants = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $colVariants.Name = 'Variants'
        $colVariants.HeaderText = 'Variants'
        $colVariants.DataPropertyName = 'Variants'
        $colVariants.Width = 300
        [void]$gridLoot.Columns.Add($colVariants)

        $gridLoot.DataSource = $lootTable
    }.GetNewClosure()

    $bindInfectedColumns = {
        $gridInfected.AutoGenerateColumns = $false
        $gridInfected.Columns.Clear()
        $gridInfected.DataSource = $null

        $infCol = New-Object System.Windows.Forms.DataGridViewComboBoxColumn
        $infCol.Name = 'ClassName'
        $infCol.HeaderText = 'ClassName'
        $infCol.DataPropertyName = 'ClassName'
        $infCol.Width = 500
        $infCol.FlatStyle = 'Flat'
        foreach ($item in @($editorState.InfectedClasses)) {
            [void]$infCol.Items.Add([string]$item)
        }
        [void]$gridInfected.Columns.Add($infCol)

        $gridInfected.DataSource = $infectedTable
    }.GetNewClosure()

    $populateLootTable = {
        $lootTable.Rows.Clear()

        $lootItems = @(ConvertTo-UGSMPlainArray -Value (Get-UGSMJsonPropertyValue -Object $editorState.Data -Name $propLoot -DefaultValue @()))
        foreach ($entry in $lootItems) {
            $name = ''
            $chance = ''
            $qty = ''
            $max = ''
            $attachments = ''
            $variants = ''

            if ($null -ne $entry) {
                $name = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'Name' -DefaultValue '')
                $chance = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'Chance' -DefaultValue '')
                $qty = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'QuantityPercent' -DefaultValue '')
                $max = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'Max' -DefaultValue '')

                $attachmentArray = @(ConvertTo-UGSMPlainArray -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'Attachments' -DefaultValue @()))
                if ($attachmentArray.Count -gt 0) {
                    $attachments = ($attachmentArray | ForEach-Object { [string]$_ }) -join ', '
                }

                $variantArray = @(ConvertTo-UGSMPlainArray -Value (Get-UGSMJsonPropertyValue -Object $entry -Name 'Variants' -DefaultValue @()))
                if ($variantArray.Count -gt 0) {
                    $variants = ($variantArray | ForEach-Object { [string]$_ }) -join ', '
                }
            }

            [void]$lootTable.Rows.Add($name, $chance, $qty, $max, $attachments, $variants)
        }

        $txtLootCount.Text = [string]$lootTable.Rows.Count
    }.GetNewClosure()

    $populateInfectedTable = {
        $infectedTable.Rows.Clear()

        $infectedItems = @(ConvertTo-UGSMPlainArray -Value (Get-UGSMJsonPropertyValue -Object $editorState.Data -Name $propInfected -DefaultValue @()))
        foreach ($entry in $infectedItems) {
            [void]$infectedTable.Rows.Add((Get-UGSMSafeString -Value $entry))
        }

        $txtInfEntries.Text = [string]$infectedTable.Rows.Count
    }.GetNewClosure()

    $populateUi = {
        $data = $editorState.Data
        if ($null -eq $data) { return }

        $txtVersion.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propVersion)
        $txtMissionName.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propMissionName)
        $txtDifficulty.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propDifficulty)
        $txtObjective.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propObjective)
        $txtReward.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propReward)
        $txtMissionMaxTime.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propMissionMaxTime)
        $txtWeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propWeight)
        $txtItemCount.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propItemCount)

        $txtHeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propHeight)
        $txtDropZoneHeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propDropZoneHeight)
        $txtSpeed.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propSpeed)
        $txtDropZoneSpeed.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propDropZoneSpeed)
        $txtFallSpeed.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propFallSpeed)
        $txtInfectedCount.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propInfectedCount)
        $txtPlane.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propPlaneClass)

        $chkEnabled.Checked = Get-UGSMSafeBool -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propEnabled -DefaultValue $null)
        $chkShowNotification.Checked = Get-UGSMSafeBool -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propShowNotification -DefaultValue $null)

        $dropLocation = Get-UGSMJsonPropertyValue -Object $data -Name $propDropLocation -DefaultValue $null

        $txtDropLocX.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dropLocation -Name 'x')
        $txtDropLocZ.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dropLocation -Name 'z')
        $txtDropLocName.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $dropLocation -Name 'Name')
        $txtDropLocRadius.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dropLocation -Name 'Radius')

        Set-UGSMComboBoxItems -ComboBox $cmbContainer -Items @(Get-UGSMAirdropContainerOptions) -SelectedValue (Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propContainer))

        & $populateLootTable
        & $populateInfectedTable
    }.GetNewClosure()

    $collectLootRows = {
        $rows = @()

        foreach ($row in @($lootTable.Rows)) {
            if ($row.RowState -eq [System.Data.DataRowState]::Deleted) { continue }

            $name = [string]$row['Name']
            $chance = [string]$row['Chance']
            $qty = [string]$row['QuantityPercent']
            $max = [string]$row['Max']
            $attachments = [string]$row['Attachments']
            $variants = [string]$row['Variants']

            if ([string]::IsNullOrWhiteSpace($name)) {
                continue
            }

            $entry = [pscustomobject]@{}
            Set-UGSMJsonPropertyValue -Object $entry -Name 'Name' -Value $name

            if (-not [string]::IsNullOrWhiteSpace($chance)) {
                Set-UGSMJsonPropertyValue -Object $entry -Name 'Chance' -Value (Read-UGSMDoubleOrThrow -Text $chance -FieldName 'Loot Chance')
            }

            if (-not [string]::IsNullOrWhiteSpace($qty)) {
                Set-UGSMJsonPropertyValue -Object $entry -Name 'QuantityPercent' -Value (Read-UGSMDoubleOrThrow -Text $qty -FieldName 'Loot QuantityPercent')
            }

            if (-not [string]::IsNullOrWhiteSpace($max)) {
                Set-UGSMJsonPropertyValue -Object $entry -Name 'Max' -Value (Read-UGSMIntOrThrow -Text $max -FieldName 'Loot Max')
            }

            $attachmentItems = @()
            if (-not [string]::IsNullOrWhiteSpace($attachments)) {
                $attachmentItems = @(
                    $attachments.Split(',') |
                    ForEach-Object { $_.Trim() } |
                    Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                )
            }
            if ($attachmentItems.Count -gt 0) {
                Set-UGSMJsonPropertyValue -Object $entry -Name 'Attachments' -Value $attachmentItems
            }

            $variantItems = @()
            if (-not [string]::IsNullOrWhiteSpace($variants)) {
                $variantItems = @(
                    $variants.Split(',') |
                    ForEach-Object { $_.Trim() } |
                    Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                )
            }
            if ($variantItems.Count -gt 0) {
                Set-UGSMJsonPropertyValue -Object $entry -Name 'Variants' -Value $variantItems
            }

            $rows += $entry
        }

        return , $rows
    }.GetNewClosure()

    $collectInfectedRows = {
        $rows = @()

        foreach ($row in @($infectedTable.Rows)) {
            if ($null -eq $row -or $row.RowState -eq [System.Data.DataRowState]::Deleted) { continue }

            $name = [string]$row['ClassName']
            if ([string]::IsNullOrWhiteSpace($name)) {
                continue
            }

            $rows += $name
        }

        return , $rows
    }.GetNewClosure()

    $saveSchema = {
        try {
            $currentPath = $editorState.FilePath

            if (-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
                throw ('Mission file not found: ' + $currentPath)
            }

            $currentDiskWriteUtc = (Get-Item -LiteralPath $currentPath -ErrorAction Stop).LastWriteTimeUtc
            if ($editorState.LastWriteUtc -and $currentDiskWriteUtc -ne $editorState.LastWriteUtc) {
                $result = [System.Windows.Forms.MessageBox]::Show(
                    'The mission file has changed on disk since it was loaded. Overwrite anyway?',
                    'File Changed On Disk',
                    [System.Windows.Forms.MessageBoxButtons]::YesNo,
                    [System.Windows.Forms.MessageBoxIcon]::Warning
                )

                if ($result -ne [System.Windows.Forms.DialogResult]::Yes) {
                    return
                }
            }

            $data = $editorState.Data
            if ($null -eq $data) {
                throw 'No mission data is loaded.'
            }

            Set-UGSMJsonPropertyValue -Object $data -Name $propVersion -Value (Read-UGSMIntOrThrow -Text $txtVersion.Text -FieldName 'Version')
            Set-UGSMJsonPropertyValue -Object $data -Name $propMissionName -Value $txtMissionName.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propDifficulty -Value $txtDifficulty.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propObjective -Value $txtObjective.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propReward -Value $txtReward.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propMissionMaxTime -Value (Read-UGSMIntOrThrow -Text $txtMissionMaxTime.Text -FieldName 'MissionMaxTime')
            Set-UGSMJsonPropertyValue -Object $data -Name $propWeight -Value (Read-UGSMDoubleOrThrow -Text $txtWeight.Text -FieldName 'Weight')
            Set-UGSMJsonPropertyValue -Object $data -Name $propItemCount -Value (Read-UGSMIntOrThrow -Text $txtItemCount.Text -FieldName 'ItemCount')

            Set-UGSMJsonPropertyValue -Object $data -Name $propHeight -Value (Read-UGSMDoubleOrThrow -Text $txtHeight.Text -FieldName 'Height')
            Set-UGSMJsonPropertyValue -Object $data -Name $propDropZoneHeight -Value (Read-UGSMDoubleOrThrow -Text $txtDropZoneHeight.Text -FieldName 'DropZoneHeight')
            Set-UGSMJsonPropertyValue -Object $data -Name $propSpeed -Value (Read-UGSMDoubleOrThrow -Text $txtSpeed.Text -FieldName 'Speed')
            Set-UGSMJsonPropertyValue -Object $data -Name $propDropZoneSpeed -Value (Read-UGSMDoubleOrThrow -Text $txtDropZoneSpeed.Text -FieldName 'DropZoneSpeed')
            Set-UGSMJsonPropertyValue -Object $data -Name $propFallSpeed -Value (Read-UGSMDoubleOrThrow -Text $txtFallSpeed.Text -FieldName 'FallSpeed')
            Set-UGSMJsonPropertyValue -Object $data -Name $propInfectedCount -Value (Read-UGSMIntOrThrow -Text $txtInfectedCount.Text -FieldName 'InfectedCount')
            Set-UGSMJsonPropertyValue -Object $data -Name $propContainer -Value $cmbContainer.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propPlaneClass -Value $txtPlane.Text

            Set-UGSMJsonPropertyValue -Object $data -Name $propEnabled -Value $chkEnabled.Checked
            Set-UGSMJsonPropertyValue -Object $data -Name $propShowNotification -Value $chkShowNotification.Checked

            $lootRows = @(& $collectLootRows)
            $infectedRows = @(& $collectInfectedRows)

            $dropLocation = Get-UGSMJsonPropertyValue -Object $data -Name $propDropLocation -DefaultValue $null
            if ($null -eq $dropLocation) {
                $dropLocation = [pscustomobject]@{}
            }

            Set-UGSMJsonPropertyValue -Object $dropLocation -Name 'x' -Value (Read-UGSMDoubleOrThrow -Text $txtDropLocX.Text -FieldName 'DropLocation x')
            Set-UGSMJsonPropertyValue -Object $dropLocation -Name 'z' -Value (Read-UGSMDoubleOrThrow -Text $txtDropLocZ.Text -FieldName 'DropLocation z')
            Set-UGSMJsonPropertyValue -Object $dropLocation -Name 'Name' -Value $txtDropLocName.Text
            Set-UGSMJsonPropertyValue -Object $dropLocation -Name 'Radius' -Value (Read-UGSMDoubleOrThrow -Text $txtDropLocRadius.Text -FieldName 'DropLocation Radius')

            Set-UGSMJsonPropertyValue -Object $data -Name $propDropLocation -Value $dropLocation

            Set-UGSMJsonPropertyValue -Object $data -Name $propLoot -Value $lootRows
            Set-UGSMJsonPropertyValue -Object $data -Name $propInfected -Value $infectedRows

            $json = $data | ConvertTo-Json -Depth 100
            [System.IO.File]::WriteAllText($currentPath, $json, [System.Text.Encoding]::UTF8)

            $editorState.LastWriteUtc = (Get-Item -LiteralPath $currentPath -ErrorAction Stop).LastWriteTimeUtc

            & $populateUi

            if ($StatusLabel) {
                $StatusLabel.Text = ('Saved Airdrop mission: ' + [System.IO.Path]::GetFileName($currentPath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Save failed: ' + $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Save Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    $reloadFromDisk = {
        try {
            & $loadFile
            & $populateUi

            if ($StatusLabel) {
                $StatusLabel.Text = ('Reloaded Airdrop mission: ' + [System.IO.Path]::GetFileName($editorState.FilePath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Reload Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    $addLootRow = {
        try {
            if ($null -eq $lootTable) { return }
            [void]$lootTable.Rows.Add('', '', '', '', '', '')

            if ($txtLootCount -and $txtLootCount.PSObject.Properties['Text']) {
                $txtLootCount.Text = [string]$lootTable.Rows.Count
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Add Loot failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $removeSelectedLootRow = {
        try {
            if ($null -eq $gridLoot -or $null -eq $lootTable) { return }
            if ($gridLoot.CurrentCell -eq $null) { return }

            $rowIndex = $gridLoot.CurrentCell.RowIndex
            if ($rowIndex -lt 0 -or $rowIndex -ge $lootTable.Rows.Count) { return }

            $lootTable.Rows.RemoveAt($rowIndex)

            if ($txtLootCount -and $txtLootCount.PSObject.Properties['Text']) {
                $txtLootCount.Text = [string]$lootTable.Rows.Count
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Remove Loot failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $addInfectedRow = {
        try {
            if ($null -eq $infectedTable) { return }
            [void]$infectedTable.Rows.Add('')

            if ($txtInfEntries -and $txtInfEntries.PSObject.Properties['Text']) {
                $txtInfEntries.Text = [string]$infectedTable.Rows.Count
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Add Infected failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $removeSelectedInfectedRow = {
        try {
            if ($null -eq $gridInfected -or $null -eq $infectedTable) { return }
            if ($gridInfected.CurrentCell -eq $null) { return }

            $rowIndex = $gridInfected.CurrentCell.RowIndex
            if ($rowIndex -lt 0 -or $rowIndex -ge $infectedTable.Rows.Count) { return }

            $infectedTable.Rows.RemoveAt($rowIndex)

            if ($txtInfEntries -and $txtInfEntries.PSObject.Properties['Text']) {
                $txtInfEntries.Text = [string]$infectedTable.Rows.Count
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Remove Infected failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $onLootDeletingRow = {
        param($sender, $e)

        try {
            $null = $HostPanel.BeginInvoke([System.Action] {
                    try {
                        if ($txtLootCount -and $lootTable) {
                            $txtLootCount.Text = [string]$lootTable.Rows.Count
                        }
                    }
                    catch {
                    }
                })
        }
        catch {
        }
    }.GetNewClosure()

    $onInfectedDeletingRow = {
        param($sender, $e)

        try {
            $null = $HostPanel.BeginInvoke([System.Action] {
                    try {
                        if ($txtInfEntries -and $infectedTable) {
                            $txtInfEntries.Text = [string]$infectedTable.Rows.Count
                        }
                    }
                    catch {
                    }
                })
        }
        catch {
        }
    }.GetNewClosure()

    $gridLoot.Add_UserDeletingRow($onLootDeletingRow)
    $gridInfected.Add_UserDeletingRow($onInfectedDeletingRow)

    $btnReload.Add_Click($reloadFromDisk)
    $btnSave.Add_Click($saveSchema)

    $btnAddLoot.Add_Click($addLootRow)
    $btnRemoveLoot.Add_Click($removeSelectedLootRow)

    $btnAddInfected.Add_Click($addInfectedRow)
    $btnRemoveInfected.Add_Click($removeSelectedInfectedRow)

    & $bindLootColumns
    & $bindInfectedColumns
    & $populateUi

    if ($StatusLabel) {
        $StatusLabel.Text = ('Loaded Airdrop mission editor: ' + [System.IO.Path]::GetFileName($FilePath))
    }
}

function Show-DayZExpansionMissionEditor_ContaminatedArea {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)][string]$FilePath,
        [Parameter(Mandatory)]$MissionState,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    $missionHost = New-Object System.Windows.Forms.Panel
    $missionHost.Location = New-Object System.Drawing.Point($baseX, $baseY)
    $missionHost.Size = New-Object System.Drawing.Size($maxWidth, 1180)
    $missionHost.BackColor = $global:UGSM_ColorBackground
    [void]$HostPanel.Controls.Add($missionHost)

    $editorState = [ordered]@{
        FilePath     = $FilePath
        Data         = $null
        LastWriteUtc = $null
    }

    $propVersion = 'm_Version'
    $propEnabled = 'Enabled'
    $propWeight = 'Weight'
    $propMissionMaxTime = 'MissionMaxTime'
    $propMissionName = 'MissionName'
    $propDifficulty = 'Difficulty'
    $propObjective = 'Objective'
    $propReward = 'Reward'
    $propData = 'Data'
    $propPlayerData = 'PlayerData'
    $propStartDecayLifetime = 'StartDecayLifetime'
    $propFinishDecayLifetime = 'FinishDecayLifetime'

    $loadFile = {
        try {
            if (-not (Test-Path -LiteralPath $editorState.FilePath -PathType Leaf)) {
                throw ('Mission file not found: ' + $editorState.FilePath)
            }

            $raw = Get-Content -LiteralPath $editorState.FilePath -Raw -ErrorAction Stop
            if ([string]::IsNullOrWhiteSpace($raw)) {
                throw 'Mission file is empty.'
            }

            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            $editorState.Data = $data
            $editorState.LastWriteUtc = (Get-Item -LiteralPath $editorState.FilePath -ErrorAction Stop).LastWriteTimeUtc
        }
        catch {
            throw ('Failed to load Contaminated Area mission file: ' + $_.Exception.Message)
        }
    }.GetNewClosure()

    try {
        & $loadFile
    }
    catch {
        $errorPanel = New-Object System.Windows.Forms.Panel
        $errorPanel.Location = New-Object System.Drawing.Point(0, 0)
        $errorPanel.Size = New-Object System.Drawing.Size(1200, 200)
        $errorPanel.BackColor = $global:UGSM_ColorPanelBackground
        $errorPanel.BorderStyle = 'FixedSingle'
        [void]$missionHost.Controls.Add($errorPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Contaminated Area Mission Editor'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(380, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$errorPanel.Controls.Add($lblTitle)

        $lblError = New-Object System.Windows.Forms.Label
        $lblError.Text = $_.Exception.Message
        $lblError.Location = New-Object System.Drawing.Point(12, 48)
        $lblError.Size = New-Object System.Drawing.Size(1120, 100)
        $lblError.ForeColor = $global:UGSM_ColorText
        [void]$errorPanel.Controls.Add($lblError)

        if ($StatusLabel) {
            $StatusLabel.Text = $_.Exception.Message
        }

        return
    }

