    [void]$playerPanel.Controls.Add($lblPPE)
    [void]$playerPanel.Controls.Add($txtPPE)

    $lblHelp = New-Object System.Windows.Forms.Label
    $lblHelp.Text = "This editor follows the real contaminated mission schema.`r`nTop-level fields, Data, PlayerData, and decay values all save back to the mission file."
    $lblHelp.Location = New-Object System.Drawing.Point(960, 56)
    $lblHelp.Size = New-Object System.Drawing.Size(460, 36)
    $lblHelp.ForeColor = $global:UGSM_ColorMutedText
    [void]$playerPanel.Controls.Add($lblHelp)

    $populateUi = {
        $data = $editorState.Data
        if ($null -eq $data) { return }

        $txtVersion.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propVersion)
        $txtWeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propWeight)
        $txtMissionMaxTime.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propMissionMaxTime)
        $txtMissionName.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propMissionName)
        $txtDifficulty.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propDifficulty)
        $txtObjective.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propObjective)
        $txtReward.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propReward)
        $txtStartDecay.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propStartDecayLifetime)
        $txtFinishDecay.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propFinishDecayLifetime)
        $chkEnabled.Checked = Get-UGSMSafeBool -Value (Get-UGSMJsonPropertyValue -Object $data -Name $propEnabled -DefaultValue $null)

        $dataNode = Get-UGSMJsonPropertyValue -Object $data -Name $propData -DefaultValue $null
        $posArray = @(Get-UGSMJsonPropertyValue -Object $dataNode -Name 'Pos' -DefaultValue @())

        $txtPosX.Text = $(if ($posArray.Count -gt 0) { Get-UGSMSafeDoubleString -Value $posArray[0] } else { '' })
        $txtPosY.Text = $(if ($posArray.Count -gt 1) { Get-UGSMSafeDoubleString -Value $posArray[1] } else { '' })
        $txtPosZ.Text = $(if ($posArray.Count -gt 2) { Get-UGSMSafeDoubleString -Value $posArray[2] } else { '' })

        $txtRadius.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'Radius')
        $txtPosHeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'PosHeight')
        $txtNegHeight.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'NegHeight')
        $txtInnerRingCount.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'InnerRingCount')
        $txtInnerPartDist.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'InnerPartDist')
        $txtOuterRingToggle.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterRingToggle')
        $txtOuterPartDist.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterPartDist')
        $txtOuterOffset.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterOffset')
        $txtVerticalLayers.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'VerticalLayers')
        $txtVerticalOffset.Text = Get-UGSMSafeDoubleString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'VerticalOffset')
        $txtParticleName.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'ParticleName')
        $txtEffectInterval.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectInterval')
        $txtEffectDuration.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectDuration')
        $txtEffectModifier.Text = Get-UGSMSafeIntString -Value (Get-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectModifier')

        $playerNode = Get-UGSMJsonPropertyValue -Object $data -Name $propPlayerData -DefaultValue $null
        $txtAroundPart.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $playerNode -Name 'AroundPartName')
        $txtTinyPart.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $playerNode -Name 'TinyPartName')
        $txtPPE.Text = Get-UGSMSafeString -Value (Get-UGSMJsonPropertyValue -Object $playerNode -Name 'PPERequesterType')
    }.GetNewClosure()

    $saveSchema = {
        try {
            $currentPath = $editorState.FilePath

            if (-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
                throw ('Mission file not found: ' + $currentPath)
            }

            $currentDiskWriteUtc = (Get-Item -LiteralPath $currentPath -ErrorAction Stop).LastWriteTimeUtc
            if ($editorState.LastWriteUtc -and $currentDiskWriteUtc -ne $editorState.LastWriteUtc) {
                $result = [System.Windows.Forms.MessageBox]::Show(
                    'The mission file has changed on disk since it was loaded. Overwrite anyway?',
                    'File Changed On Disk',
                    [System.Windows.Forms.MessageBoxButtons]::YesNo,
                    [System.Windows.Forms.MessageBoxIcon]::Warning
                )

                if ($result -ne [System.Windows.Forms.DialogResult]::Yes) {
                    return
                }
            }

            $data = $editorState.Data
            if ($null -eq $data) {
                throw 'No mission data is loaded.'
            }

            Set-UGSMJsonPropertyValue -Object $data -Name $propVersion -Value (Read-UGSMIntOrThrow -Text $txtVersion.Text -FieldName 'Version')
            
            Set-UGSMJsonPropertyValue -Object $data -Name $propWeight -Value (Read-UGSMDoubleOrThrow -Text $txtWeight.Text -FieldName 'Weight')
            Set-UGSMJsonPropertyValue -Object $data -Name $propMissionMaxTime -Value (Read-UGSMIntOrThrow -Text $txtMissionMaxTime.Text -FieldName 'MissionMaxTime')
            Set-UGSMJsonPropertyValue -Object $data -Name $propMissionName -Value $txtMissionName.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propDifficulty -Value $txtDifficulty.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propObjective -Value $txtObjective.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propReward -Value $txtReward.Text
            Set-UGSMJsonPropertyValue -Object $data -Name $propEnabled -Value $chkEnabled.Checked
            Set-UGSMJsonPropertyValue -Object $data -Name $propStartDecayLifetime -Value (Read-UGSMDoubleOrThrow -Text $txtStartDecay.Text -FieldName 'StartDecayLifetime')
            Set-UGSMJsonPropertyValue -Object $data -Name $propFinishDecayLifetime -Value (Read-UGSMDoubleOrThrow -Text $txtFinishDecay.Text -FieldName 'FinishDecayLifetime')

            $dataNode = Get-UGSMJsonPropertyValue -Object $data -Name $propData -DefaultValue $null
            if ($null -eq $dataNode) {
                $dataNode = [pscustomobject]@{}
            }

            $posArray = @(
                (Read-UGSMDoubleOrThrow -Text $txtPosX.Text -FieldName 'Data Pos X'),
                (Read-UGSMDoubleOrThrow -Text $txtPosY.Text -FieldName 'Data Pos Y'),
                (Read-UGSMDoubleOrThrow -Text $txtPosZ.Text -FieldName 'Data Pos Z')
            )

            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'Pos' $posArray
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'Radius' -Value (Read-UGSMDoubleOrThrow -Text $txtRadius.Text -FieldName 'Radius')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'PosHeight' -Value (Read-UGSMDoubleOrThrow -Text $txtPosHeight.Text -FieldName 'PosHeight')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'NegHeight' -Value (Read-UGSMDoubleOrThrow -Text $txtNegHeight.Text -FieldName 'NegHeight')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'InnerRingCount' -Value (Read-UGSMIntOrThrow -Text $txtInnerRingCount.Text -FieldName 'InnerRingCount')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'InnerPartDist' -Value (Read-UGSMIntOrThrow -Text $txtInnerPartDist.Text -FieldName 'InnerPartDist')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterRingToggle' -Value (Read-UGSMIntOrThrow -Text $txtOuterRingToggle.Text -FieldName 'OuterRingToggle')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterPartDist' -Value (Read-UGSMIntOrThrow -Text $txtOuterPartDist.Text -FieldName 'OuterPartDist')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'OuterOffset' -Value (Read-UGSMDoubleOrThrow -Text $txtOuterOffset.Text -FieldName 'OuterOffset')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'VerticalLayers' -Value (Read-UGSMIntOrThrow -Text $txtVerticalLayers.Text -FieldName 'VerticalLayers')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'VerticalOffset' -Value (Read-UGSMDoubleOrThrow -Text $txtVerticalOffset.Text -FieldName 'VerticalOffset')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'ParticleName' -Value $txtParticleName.Text
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectInterval' -Value (Read-UGSMIntOrThrow -Text $txtEffectInterval.Text -FieldName 'EffectInterval')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectDuration' -Value (Read-UGSMIntOrThrow -Text $txtEffectDuration.Text -FieldName 'EffectDuration')
            Set-UGSMJsonPropertyValue -Object $dataNode -Name 'EffectModifier' -Value (Read-UGSMIntOrThrow -Text $txtEffectModifier.Text -FieldName 'EffectModifier')

            Set-UGSMJsonPropertyValue -Object $data -Name $propData -Value $dataNode

            $playerNode = Get-UGSMJsonPropertyValue -Object $data -Name $propPlayerData -DefaultValue $null
            if ($null -eq $playerNode) {
                $playerNode = [pscustomobject]@{}
            }

            Set-UGSMJsonPropertyValue -Object $playerNode -Name 'AroundPartName' -Value $txtAroundPart.Text
            Set-UGSMJsonPropertyValue -Object $playerNode -Name 'TinyPartName' -Value $txtTinyPart.Text
            Set-UGSMJsonPropertyValue -Object $playerNode -Name 'PPERequesterType' -Value $txtPPE.Text

            Set-UGSMJsonPropertyValue -Object $data -Name $propPlayerData -Value $playerNode

            $json = $data | ConvertTo-Json -Depth 100
            [System.IO.File]::WriteAllText($currentPath, $json, [System.Text.Encoding]::UTF8)

            $editorState.LastWriteUtc = (Get-Item -LiteralPath $currentPath -ErrorAction Stop).LastWriteTimeUtc

            & $populateUi

            if ($StatusLabel) {
                $StatusLabel.Text = ('Saved Contaminated Area mission: ' + [System.IO.Path]::GetFileName($currentPath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Save failed: ' + $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Save Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    $reloadFromDisk = {
        try {
            & $loadFile
            & $populateUi

            if ($StatusLabel) {
                $StatusLabel.Text = ('Reloaded Contaminated Area mission: ' + [System.IO.Path]::GetFileName($editorState.FilePath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Reload Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    $btnReload.Add_Click($reloadFromDisk)
    $btnSave.Add_Click($saveSchema)

    & $populateUi

    if ($StatusLabel) {
        $StatusLabel.Text = ('Loaded Contaminated Area mission editor: ' + [System.IO.Path]::GetFileName($FilePath))
    }
}
   
function New-DayZExpansionMissionsTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    $Page.Controls.Clear()

    $panel = New-Object System.Windows.Forms.Panel
    $panel.Dock = 'Fill'
    $panel.Padding = New-Object System.Windows.Forms.Padding(8)
    $panel.BackColor = $global:UGSM_ColorBackground
    [void]$Page.Controls.Add($panel)

    $toolbar = New-Object System.Windows.Forms.Panel
    $toolbar.Dock = 'Top'
    $toolbar.Height = $UGSM_ExpansionToolbarHeight
    $toolbar.BackColor = $global:UGSM_ColorBackground
    $toolbar.BorderStyle = 'FixedSingle'
    $contentPanel = New-Object System.Windows.Forms.Panel
    $contentPanel.Dock = 'Fill'
    $contentPanel.Padding = New-Object System.Windows.Forms.Padding(0, 10, 0, 0)
    $contentPanel.BackColor = $global:UGSM_ColorBackground
    [void]$panel.Controls.Add($contentPanel)
    [void]$panel.Controls.Add($toolbar)
    $toolbar.BringToFront()

    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'
    $split.Orientation = 'Vertical'
    $split.SplitterWidth = 6
    $split.BackColor = $global:UGSM_ColorBackground
    $split.FixedPanel = 'None'
    [void]$contentPanel.Controls.Add($split)

    $leftPanel = New-Object System.Windows.Forms.Panel
    $leftPanel.Dock = 'Fill'
    $leftPanel.Padding = New-Object System.Windows.Forms.Padding(0, 0, 6, 0)
    $leftPanel.BackColor = $global:UGSM_ColorBackground
    [void]$split.Panel1.Controls.Add($leftPanel)

    $rightPanel = New-Object System.Windows.Forms.Panel
    $rightPanel.Dock = 'Fill'
    $rightPanel.Padding = New-Object System.Windows.Forms.Padding(6, 0, 0, 0)
    $rightPanel.BackColor = $global:UGSM_ColorBackground
    [void]$split.Panel2.Controls.Add($rightPanel)

    $setInitialSplitter = {
        try {
            if ($null -eq $split) { return }
            if ($split.Width -le 0) { return }

            $panel1Min = 260
            $panel2Min = 420
            $availableWidth = $split.ClientSize.Width

            if ($availableWidth -le 0) { return }

            $maxSplitter = $availableWidth - $panel2Min
            if ($maxSplitter -lt $panel1Min) { return }

            $split.Panel1MinSize = $panel1Min
            $split.Panel2MinSize = $panel2Min

            $desiredSplitter = 270
            $safeSplitter = [Math]::Max($panel1Min, [Math]::Min($desiredSplitter, $maxSplitter))
            $split.SplitterDistance = $safeSplitter
        }
        catch {
        }
    }.GetNewClosure()

    $split.Add_Resize($setInitialSplitter)

    $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width 90
    $btnNewAirdrop = New-UGSMExpansionNewButton -Text 'New Airdrop' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width 110
    $btnNewContaminated = New-UGSMExpansionNewButton -Text 'New Contaminated' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width 130
    $btnDeleteMission = New-UGSMExpansionRemoveButton -Text 'Delete Mission' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width 120

    foreach ($button in @($btnRefresh, $btnNewAirdrop, $btnNewContaminated, $btnDeleteMission)) {
        $button.Anchor = 'Top,Left'
        $button.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
        $button.UseVisualStyleBackColor = $false
        $button.FlatAppearance.BorderSize = 1
        $button.FlatAppearance.MouseDownBackColor = $button.BackColor
        $button.FlatAppearance.MouseOverBackColor = $button.BackColor
        [void]$toolbar.Controls.Add($button)
    }

    Set-UGSMExpansionToolbarButtons -Buttons @($btnRefresh, $btnNewAirdrop, $btnNewContaminated, $btnDeleteMission)

    $leftTop = New-Object System.Windows.Forms.Panel
    $leftTop.Dock = 'Top'
    $leftTop.Height = 64
    $leftTop.BackColor = $global:UGSM_ColorBackground
    [void]$leftPanel.Controls.Add($leftTop)

    $lblCategory = New-UGSMLabel -Text 'Mission Type' -X 0 -Y 8 -Width 140 -Height 18 -FontSize 8.5 -Color $global:UGSM_ColorText
    [void]$leftTop.Controls.Add($lblCategory)

    $cmbCategory = New-Object System.Windows.Forms.ComboBox
    $cmbCategory.Location = New-Object System.Drawing.Point(0, 28)
    $cmbCategory.Size = New-Object System.Drawing.Size(220, 24)
    $cmbCategory.DropDownStyle = 'DropDownList'
    $cmbCategory.BackColor = $global:UGSM_ColorInputBackground
    $cmbCategory.ForeColor = $global:UGSM_ColorText
    [void]$cmbCategory.Items.Add('All Missions')
    [void]$cmbCategory.Items.Add('Airdrop')
    [void]$cmbCategory.Items.Add('Contaminated Area')
    [void]$cmbCategory.Items.Add('Other')
    [void]$leftTop.Controls.Add($cmbCategory)

    $leftBody = New-Object System.Windows.Forms.Panel
    $leftBody.Dock = 'Fill'
    $leftBody.Padding = New-Object System.Windows.Forms.Padding(0, 70, 0, 0)
    $leftBody.BackColor = $global:UGSM_ColorBackground
    [void]$leftPanel.Controls.Add($leftBody)

    $lstFiles = New-Object System.Windows.Forms.ListBox
    $lstFiles.Dock = 'Fill'
    $lstFiles.BackColor = $global:UGSM_ColorInputBackground
    $lstFiles.ForeColor = $global:UGSM_ColorText
    $lstFiles.BorderStyle = 'FixedSingle'
    $lstFiles.IntegralHeight = $false
    [void]$leftBody.Controls.Add($lstFiles)

    $editorHost = New-Object System.Windows.Forms.Panel
    $editorHost.Dock = 'Fill'
    $editorHost.BackColor = $global:UGSM_ColorBackground
    [void]$rightPanel.Controls.Add($editorHost)

    $missionsState = [ordered]@{
        MissionRoot     = ''
        Files           = @()
        FilteredFiles   = @()
        CurrentFilePath = ''
        CurrentFileType = ''
        CurrentFileItem = $null
        EditorHost      = $editorHost
    }

    $getMissionRoot = {
        $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
        if ([string]::IsNullOrWhiteSpace([string]$paths.MissionExpansionRoot)) {
            return ''
        }

        return (Join-Path ([string]$paths.MissionExpansionRoot) 'missions')
    }.GetNewClosure()

    $getMissionType = {
        param($fileName)

        if ([string]::IsNullOrWhiteSpace($fileName)) {
            return 'Other'
        }

        if ($fileName -like 'Airdrop_*.json') {
            return 'Airdrop'
        }

        if ($fileName -like 'ContaminatedArea_*.json') {
            return 'Contaminated Area'
        }

        return 'Other'
    }.GetNewClosure()

    $getMissionDisplayName = {
        param($item)

        if ($null -eq $item) { return '' }

        return [string]$item.Name
    }.GetNewClosure()

    $clearEditor = {
        $editorHost.Controls.Clear()
        $missionsState.CurrentFilePath = ''
        $missionsState.CurrentFileType = ''
        $missionsState.CurrentFileItem = $null
    }.GetNewClosure()

    $sanitizeMissionFileName = {
        param([string]$name)

        if ([string]::IsNullOrWhiteSpace($name)) {
            return ''
        }

        $clean = $name.Trim()
        $invalid = [System.IO.Path]::GetInvalidFileNameChars()
        foreach ($char in $invalid) {
            $clean = $clean.Replace([string]$char, '_')
        }

        $clean = $clean -replace '\s+', '_'
        $clean = $clean.Trim('_')

        return $clean
    }.GetNewClosure()

    $showMessagePanel = {
        param(
            [string]$Title,
            [string]$Message
        )

        $editorHost.Controls.Clear()

        $missionhost = New-Object System.Windows.Forms.Panel
        $missionhost.Dock = 'Fill'
        $missionhost.BackColor = $global:UGSM_ColorBackground
        [void]$editorHost.Controls.Add($missionhost)

        $baseX = $UGSM_ExpansionBaseX
        $baseY = $UGSM_ExpansionBaseY
        $maxWidth = $UGSM_ExpansionMaxWidth

        $lblTitle = New-UGSMLabel -Text $Title -X $baseX -Y 0 -Width 600 -Height 24 -FontSize 12 -Bold -Color $global:UGSM_ColorText
        [void]$missionhost.Controls.Add($lblTitle)

        $lblMessage = New-Object System.Windows.Forms.Label
        $lblMessage.AutoSize = $false
        $lblMessage.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $lblMessage.Size = New-Object System.Drawing.Size(([Math]::Min($maxWidth, 1100)), 120)
        $lblMessage.ForeColor = $global:UGSM_ColorText
        $lblMessage.BackColor = [System.Drawing.Color]::Transparent
        $lblMessage.Text = $Message
        [void]$missionhost.Controls.Add($lblMessage)
    }.GetNewClosure()

    $showGenericMissionPlaceholder = {
        param($fileItem)

        if ($null -eq $fileItem) {
            & $showMessagePanel 'Mission Editor' 'No mission file is selected.'
            return
        }

        $message = @(
            'No file-specific mission editor has been built for this file yet.'
            ''
            ('File: ' + [string]$fileItem.Name)
            ('Type: ' + [string]$fileItem.Type)
            ('Path: ' + [string]$fileItem.FullName)
        ) -join [Environment]::NewLine

        & $showMessagePanel 'Mission Editor Not Built Yet' $message
    }.GetNewClosure()

    $refreshFileList = {
        try {
            & $clearEditor

            $lstFiles.Items.Clear()
            $missionsState.Files = @()
            $missionsState.FilteredFiles = @()

            $root = & $getMissionRoot
            $missionsState.MissionRoot = $root

            if ([string]::IsNullOrWhiteSpace($root)) {
                if ($StatusLabel) { $StatusLabel.Text = 'Mission root path could not be resolved.' }
                & $showMessagePanel 'Mission Folder Not Resolved' 'The DayZ Expansion mission path could not be resolved for this instance.'
                return
            }

            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                if ($StatusLabel) { $StatusLabel.Text = 'Mission folder was not found.' }
                & $showMessagePanel 'Mission Folder Not Found' ('Mission folder not found:' + [Environment]::NewLine + $root)
                return
            }

            $items = @(
                Get-ChildItem -LiteralPath $root -File -Filter '*.json' -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch '\.bak\.json$' } |
                Sort-Object Name |
                ForEach-Object {
                    [pscustomobject]@{
                        Name      = [string]$_.Name
                        Title     = [System.IO.Path]::GetFileNameWithoutExtension([string]$_.Name)
                        FullName  = [string]$_.FullName
                        Directory = [string]$_.DirectoryName
                        Type      = & $getMissionType $_.Name
                    }
                }
            )

            $missionsState.Files = @($items)

            $selectedCategory = [string]$cmbCategory.SelectedItem
            if ([string]::IsNullOrWhiteSpace($selectedCategory) -or $selectedCategory -eq 'All Missions') {
                $missionsState.FilteredFiles = @($missionsState.Files)
            }
            else {
                $missionsState.FilteredFiles = @($missionsState.Files | Where-Object { [string]$_.Type -eq $selectedCategory })
            }

            foreach ($item in @($missionsState.FilteredFiles)) {
                [void]$lstFiles.Items.Add((& $getMissionDisplayName $item))
            }

            if ($missionsState.FilteredFiles.Count -eq 0) {
                & $showMessagePanel 'No Mission Files Found' 'No mission files matched the selected mission type.'
            }
            elseif ($lstFiles.Items.Count -gt 0) {
                $lstFiles.SelectedIndex = 0
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded ' + [string]$missionsState.FilteredFiles.Count + ' mission file(s).')
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Refreshing missions failed: ' + $_.Exception.Message }
            & $showMessagePanel 'Mission Refresh Failed' $_.Exception.Message
        }
    }.GetNewClosure()

    $loadSelectedFile = {
        try {
            & $clearEditor

            $selectedIndex = $lstFiles.SelectedIndex
            if ($selectedIndex -lt 0 -or $selectedIndex -ge $missionsState.FilteredFiles.Count) {
                return
            }

            $file = $missionsState.FilteredFiles[$selectedIndex]
            if ($null -eq $file) { return }

            $missionsState.CurrentFilePath = [string]$file.FullName
            $missionsState.CurrentFileType = [string]$file.Type
            $missionsState.CurrentFileItem = $file

            switch ([string]$file.Type) {
                'Airdrop' {
                    if (Get-Command -Name 'Show-DayZExpansionMissionEditor_Airdrop' -ErrorAction SilentlyContinue) {
                        Show-DayZExpansionMissionEditor_Airdrop -HostPanel $editorHost -FilePath $file.FullName -MissionState $missionsState -Instance $Instance -StatusLabel $StatusLabel
                    }
                    else {
                        & $showMessagePanel 'Airdrop Mission Editor Missing' ('Show-DayZExpansionMissionEditor_Airdrop was not found.' + [Environment]::NewLine + [Environment]::NewLine + $file.Name)
                    }
                }
                'Contaminated Area' {
                    if (Get-Command -Name 'Show-DayZExpansionMissionEditor_ContaminatedArea' -ErrorAction SilentlyContinue) {
                        Show-DayZExpansionMissionEditor_ContaminatedArea -HostPanel $editorHost -FilePath $file.FullName -MissionState $missionsState -Instance $Instance -StatusLabel $StatusLabel
                    }
                    else {
                        & $showMessagePanel 'Contaminated Area Editor Missing' ('Show-DayZExpansionMissionEditor_ContaminatedArea was not found.' + [Environment]::NewLine + [Environment]::NewLine + $file.Name)
                    }
                }
                default {
                    & $showGenericMissionPlaceholder $file
                }
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded mission file: ' + [string]$file.Name)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Loading mission file failed: ' + $_.Exception.Message
            }

            & $showMessagePanel 'Mission Load Failed' $_.Exception.Message
        }
    }.GetNewClosure()

    $selectMissionByName = {
        param([string]$fileName)

        if ([string]::IsNullOrWhiteSpace($fileName)) { return }

        for ($i = 0; $i -lt $missionsState.FilteredFiles.Count; $i++) {
            $item = $missionsState.FilteredFiles[$i]
            if ($item -and [string]$item.Name -eq $fileName) {
                $lstFiles.SelectedIndex = $i
                return
            }
        }
    }.GetNewClosure()

    $newAirdropTemplate = {
        param([string]$missionName)

        $template = [ordered]@{
            m_Version             = 0
            Enabled               = $true
            Weight                = 1
            MissionMaxTime        = 1200
            MissionName           = $missionName
            Difficulty            = 0
            Objective             = 1
            Reward                = ''
            ShowNotification      = $true
            Height                = 490
            DropZoneHeight        = 450
            Speed                 = 25
            DropZoneSpeed         = 25
            Container             = 'Random'
            FallSpeed             = 4.5
            DropLocation          = [ordered]@{
                x      = 0.0
                z      = 0.0
                Name   = 'NewLocation'
                Radius = 100.0
            }
            Infected              = @()
            ItemCount             = -1
            InfectedCount         = -1
            AirdropPlaneClassName = ''
            Loot                  = @()
        }

        return ($template | ConvertTo-Json -Depth 20)
    }.GetNewClosure()

    $newContaminatedTemplate = {
        param([string]$missionName)

        $template = [ordered]@{
            m_Version           = 0
            Enabled             = $true
            Weight              = 1.0
            MissionMaxTime      = 900
            MissionName         = $missionName
            Difficulty          = 0
            Objective           = 0
            Reward              = ''
            Data                = [ordered]@{
                Pos             = @(0.0, 0.0, 0.0)
                Radius          = 200.0
                PosHeight       = 26.0
                NegHeight       = 10.0
                InnerRingCount  = 1
                InnerPartDist   = 50
                OuterRingToggle = 1
                OuterPartDist   = 50
                OuterOffset     = 0
                VerticalLayers  = 0
                VerticalOffset  = 0
                ParticleName    = 'graphics/particles/contaminated_area_gas_bigass'
                EffectInterval  = 0
                EffectDuration  = 0
                EffectModifier  = 0
            }
            PlayerData          = [ordered]@{
                AroundPartName   = 'graphics/particles/contaminated_area_gas_around'
                TinyPartName     = 'graphics/particles/contaminated_area_gas_around_tiny'
                PPERequesterType = 'PPERequester_ContaminatedAreaTint'
            }
            StartDecayLifetime  = 600.0
            FinishDecayLifetime = 300.0
        }

        return ($template | ConvertTo-Json -Depth 20)
    }.GetNewClosure()

    $newMissionFileName = {
        param(
            [string]$prefix,
            [string]$suffix
        )

        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        return ('{0}_{1}_{2}.json' -f $prefix, $suffix, $stamp)
    }.GetNewClosure()

    $getMissionFileNameFromUser = {
        param(
            [string]$title,
            [string]$defaultValue
        )

        $form = New-Object System.Windows.Forms.Form
        $form.Text = $title
        $form.StartPosition = 'CenterParent'
        $form.Size = New-Object System.Drawing.Size(420, 150)
        $form.FormBorderStyle = 'FixedDialog'
        $form.MaximizeBox = $false
        $form.MinimizeBox = $false
        $form.BackColor = $global:UGSM_ColorBackground
        $form.ForeColor = $global:UGSM_ColorText
        $form.TopMost = $true

        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = 'Enter custom mission name only:'
        $lbl.Location = New-Object System.Drawing.Point(12, 12)
        $lbl.Size = New-Object System.Drawing.Size(360, 18)
        $lbl.ForeColor = $global:UGSM_ColorText
        [void]$form.Controls.Add($lbl)

        $txt = New-Object System.Windows.Forms.TextBox
        $txt.Location = New-Object System.Drawing.Point(12, 34)
        $txt.Size = New-Object System.Drawing.Size(380, 24)
        $txt.Text = $defaultValue
        $txt.BorderStyle = 'FixedSingle'
        $txt.BackColor = $global:UGSM_ColorInputBackground
        $txt.ForeColor = $global:UGSM_ColorText
        [void]$form.Controls.Add($txt)

        $btnOk = New-Object System.Windows.Forms.Button
        $btnOk.Text = 'OK'
        $btnOk.Location = New-Object System.Drawing.Point(236, 70)
        $btnOk.Size = New-Object System.Drawing.Size(75, 28)
        $btnOk.DialogResult = [System.Windows.Forms.DialogResult]::OK
        [void]$form.Controls.Add($btnOk)

        $btnCancel = New-Object System.Windows.Forms.Button
        $btnCancel.Text = 'Cancel'
        $btnCancel.Location = New-Object System.Drawing.Point(317, 70)
        $btnCancel.Size = New-Object System.Drawing.Size(75, 28)
        $btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        [void]$form.Controls.Add($btnCancel)

        $form.AcceptButton = $btnOk
        $form.CancelButton = $btnCancel

        $result = $form.ShowDialog()

        if ($result -ne [System.Windows.Forms.DialogResult]::OK) {
            return $null
        }

        return $txt.Text
    }.GetNewClosure()

    $createMissionFile = {
        param(
            [string]$missionType
        )

        try {
            $root = & $getMissionRoot
            if ([string]::IsNullOrWhiteSpace($root)) {
                throw 'Mission folder could not be resolved.'
            }

            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                throw ('Mission folder not found: ' + $root)
            }

            $fileName = ''
            $jsonText = ''

            switch ($missionType) {
                'Airdrop' {
                    $defaultSuffix = 'Custom_NewMission'
                    $userSuffix = & $getMissionFileNameFromUser 'Create Airdrop Mission' $defaultSuffix
                    if ($null -eq $userSuffix) { return }

                    $userSuffix = & $sanitizeMissionFileName $userSuffix
                    if ([string]::IsNullOrWhiteSpace($userSuffix)) {
                        throw 'Mission name cannot be blank.'
                    }

                    $fileName = 'Airdrop_' + $userSuffix + '.json'
                    $missionName = $userSuffix
                    $jsonText = & $newAirdropTemplate $missionName
                }
                'Contaminated Area' {
                    $defaultSuffix = 'Settlement_NewMission'
                    $userSuffix = & $getMissionFileNameFromUser 'Create Contaminated Area Mission' $defaultSuffix
                    if ($null -eq $userSuffix) { return }

                    $userSuffix = & $sanitizeMissionFileName $userSuffix
                    if ([string]::IsNullOrWhiteSpace($userSuffix)) {
                        throw 'Mission name cannot be blank.'
                    }

                    $fileName = 'ContaminatedArea_' + $userSuffix + '.json'
                    $missionName = $userSuffix
                    $jsonText = & $newContaminatedTemplate $missionName
                }
                default {
                    throw ('Unsupported mission type: ' + $missionType)
                }
            }

            $fullPath = Join-Path $root $fileName

            if (Test-Path -LiteralPath $fullPath -PathType Leaf) {
                throw ('Mission file already exists: ' + $fileName)
            }

            [System.IO.File]::WriteAllText($fullPath, $jsonText, [System.Text.Encoding]::UTF8)

            $currentCategory = [string]$cmbCategory.SelectedItem
            if ($currentCategory -ne 'All Missions' -and $currentCategory -ne $missionType) {
                $cmbCategory.SelectedItem = $missionType
            }

            & $refreshFileList
            & $selectMissionByName $fileName

            if ($StatusLabel) {
                $StatusLabel.Text = ('Created mission file: ' + $fileName)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Create mission failed: ' + $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Create Mission Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    

    $deleteSelectedMission = {
        try {
            $selectedIndex = $lstFiles.SelectedIndex
            if ($selectedIndex -lt 0 -or $selectedIndex -ge $missionsState.FilteredFiles.Count) {
                throw 'No mission file is selected.'
            }

            $file = $missionsState.FilteredFiles[$selectedIndex]
            if ($null -eq $file) {
                throw 'No mission file is selected.'
            }

            $result = [System.Windows.Forms.MessageBox]::Show(
                ('Delete mission file?' + [Environment]::NewLine + [Environment]::NewLine + $file.Name),
                'Delete Mission',
                [System.Windows.Forms.MessageBoxButtons]::YesNo,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            )

            if ($result -ne [System.Windows.Forms.DialogResult]::Yes) {
                return
            }

            if (-not (Test-Path -LiteralPath $file.FullName -PathType Leaf)) {
                throw ('Mission file not found: ' + $file.FullName)
            }

            Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop

            & $refreshFileList

            if ($StatusLabel) {
                $StatusLabel.Text = ('Deleted mission file: ' + $file.Name)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Delete mission failed: ' + $_.Exception.Message
            }

            [System.Windows.Forms.MessageBox]::Show(
                $_.Exception.Message,
                'Delete Mission Failed',
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error
            ) | Out-Null
        }
    }.GetNewClosure()

    $btnRefresh.Add_Click($refreshFileList)
    $cmbCategory.Add_SelectedIndexChanged($refreshFileList)
    $lstFiles.Add_SelectedIndexChanged($loadSelectedFile)

    $newAirdropClick = {
        & $createMissionFile 'Airdrop'
    }.GetNewClosure()

    $newContaminatedClick = {
        & $createMissionFile 'Contaminated Area'
    }.GetNewClosure()

    $btnNewAirdrop.Add_Click($newAirdropClick)
    $btnNewContaminated.Add_Click($newContaminatedClick)
    $btnDeleteMission.Add_Click($deleteSelectedMission)

    if ($cmbCategory.Items.Count -gt 0) {
        $cmbCategory.SelectedIndex = 0
    }

    try {
        $null = $Page.BeginInvoke([System.Action] {
                try { & $setInitialSplitter } catch { }
            })
    }
    catch {
    }

    try {
        & $refreshFileList
    }
    catch {
        if ($StatusLabel) { $StatusLabel.Text = 'Missions tab init failed: ' + $_.Exception.Message }
    }
}


function New-DayZExpansionGenericJsonModuleTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel,
        [Parameter(Mandatory)][string]$ModuleKey,
        [Parameter(Mandatory)][string]$ModuleTitle
    )

    Initialize-UGSMExpansionThemeDefaults

    try {
        $Page.Text = $ModuleTitle
        $Page.BackColor = $global:UGSM_ColorBackground
        $Page.ForeColor = $global:UGSM_ColorText
        $Page.AutoScroll = $false
        $Page.Controls.Clear()

        # =====================================================================
        # =====================================================================
        $root = New-Object System.Windows.Forms.Panel
        $root.Dock = 'Fill'
        $root.autoscroll = $false
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$Page.Controls.Add($root)

        $shell = New-Object System.Windows.Forms.Panel
        $shell.Location = New-Object System.Drawing.Point(0, 0)
        $shell.Size = New-Object System.Drawing.Size(
            [Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width),
            980
        )
        $shell.Anchor = 'Top,Left,Right'
        $shell.BackColor = $global:UGSM_ColorBackground
        $shell.BorderStyle = 'None'
        [void]$root.Controls.Add($shell)

        # =====================================================================
        # =====================================================================
        $topBar = New-Object System.Windows.Forms.Panel
        $topBar.Location = New-Object System.Drawing.Point(0, 0)
        $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
        $topBar.Anchor = 'Top,Left,Right'
        $topBar.BackColor = $global:UGSM_ColorBackground
        $topBar.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($topBar)

        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall

        foreach ($button in @($btnRefresh, $btnSaveCurrent, $btnPretty)) {
            $button.Anchor = 'Top,Left'
            Set-UGSMExpansionButtonStyle -Button $button | Out-Null
            [void]$topBar.Controls.Add($button)
        }
        Set-UGSMExpansionToolbarButtons -Buttons @($btnRefresh, $btnSaveCurrent, $btnPretty)

        # =====================================================================
        # =====================================================================
        $body = New-Object System.Windows.Forms.Panel
        $body.Location = New-Object System.Drawing.Point(
            $UGSM_ExpansionOffsetX,
            ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap)
        )
        $body.Size = New-Object System.Drawing.Size(
            $shell.ClientSize.Width,
            ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12)
        )
        $body.Anchor = 'Top,Left,Right,Bottom'
        $body.BackColor = $global:UGSM_ColorBackground
        $body.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($body)

        $leftPanel = New-UGSMExpansionLeftListPanel `
            -X ($UGSM_ExpansionGap) `
            -Y ($UGSM_ExpansionGap) `
            -Width $UGSM_ExpansionLeftPanelWidth `
            -Height $styleTestLeftMinHeight
        [void]$body.Controls.Add($leftPanel)

        $cmbScope = New-UGSMExpansionEditorComboBox -X 12 -Y 12 -Width ($UGSM_ExpansionLeftPanelWidth - 24)
        $cmbScope.DropDownStyle = 'DropDownList'
        [void]$cmbScope.Items.Add('All module paths')
        [void]$cmbScope.Items.Add('Profile path only')
        [void]$cmbScope.Items.Add('Mission path only')
        $cmbScope.SelectedIndex = 0
        [void]$leftPanel.Controls.Add($cmbScope)

        $lstFiles = New-Object System.Windows.Forms.ListBox
        $lstFiles.Location = New-Object System.Drawing.Point(12, 46)
        $lstFiles.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), 620)
        $lstFiles.Anchor = 'Top,Left,Bottom,Right'
        $lstFiles.BackColor = $global:UGSM_ColorInputBackground
        $lstFiles.ForeColor = $global:UGSM_ColorText
        $lstFiles.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstFiles)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 700
        [void]$body.Controls.Add($editorPanel)

        # =====================================================================
        # TOWER 1 - selected file header
        # =====================================================================
        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $UGSM_ExpansionTowerHeight
        [void]$editorPanel.Controls.Add($Tower1)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text ($ModuleTitle + ' Raw JSON Editor') -X 12 -Y 12 -Width 360
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)

        $lblHeaderDesc = New-UGSMExpansionEditorLabel -Text 'Pass-one editor: load, validate, pretty print, and save JSON files without rebuilding unknown fields. Raw JSON browsing stays in the Files tab.' -X 12 -Y 40 -Width 900
        [void]$Tower1.Controls.Add($lblHeaderDesc)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'File' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width $UGSM_ExpansionFileFieldWidth
        $txtFile.ReadOnly = $false
        $txtFile.TabStop = $true
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X $UGSM_ExpansionPathFieldLeft -Y 76 -Width 120
        $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 96 -Width 400
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        # =====================================================================
        # TOWER 2 - raw JSON content
        # =====================================================================
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 560
        [void]$editorPanel.Controls.Add($Tower2)

        $lblJson = New-UGSMExpansionEditorLabel -Text 'JSON Content' -X 12 -Y 12 -Width 180
        $lblJson.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower2.Controls.Add($lblJson)

        $txtJson = New-Object System.Windows.Forms.TextBox
        $txtJson.Location = New-Object System.Drawing.Point(12, 40)
        $txtJson.Size = New-Object System.Drawing.Size(940, 500)
        $txtJson.Anchor = 'Top,Left,Right,Bottom'
        $txtJson.Multiline = $true
        $txtJson.AcceptsTab = $true
        $txtJson.AcceptsReturn = $true
        $txtJson.ScrollBars = 'Both'
        $txtJson.WordWrap = $false
        $txtJson.BorderStyle = 'FixedSingle'
        $txtJson.BackColor = $global:UGSM_ColorInputBackground
        $txtJson.ForeColor = $global:UGSM_ColorText
        $txtJson.Font = New-Object System.Drawing.Font('Consolas', 9)
        [void]$Tower2.Controls.Add($txtJson)

        $Tower2.Add_SizeChanged({
                try {
                    $txtJson.Width = [Math]::Max(200, ($Tower2.ClientSize.Width - 24))
                    $txtJson.Height = [Math]::Max(120, ($Tower2.ClientSize.Height - 52))
                }
                catch { }
            }.GetNewClosure())

        $moduleState = [ordered]@{
            Files       = @()
            CurrentPath = ''
        }

        $getModuleDefinition = {
            foreach ($module in @(Get-UGSMGameDayZExpansionModuleDefinitions)) {
                if ([string]$module.Key -eq $ModuleKey) { return $module }
            }
            return $null
        }.GetNewClosure()

        $getFilteredModulePaths = {
            $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
            $module = & $getModuleDefinition
            if ($null -eq $module) { return @() }

            $allPaths = @(Get-UGSMGameDayZExpansionModulePaths -Paths $paths -Module $module)
            $selected = [string]$cmbScope.SelectedItem

            if ($selected -eq 'Profile path only') {
                return @($allPaths | Where-Object { $_ -like '*\ExpansionMod\*' -or $_ -like '*/ExpansionMod/*' })
            }

            if ($selected -eq 'Mission path only') {
                return @($allPaths | Where-Object { $_ -like '*\mpmissions\*' -or $_ -like '*/mpmissions/*' })
            }

            return @($allPaths)
        }.GetNewClosure()

        $refreshFiles = {
            try {
                $lstFiles.Items.Clear()
                $txtFile.Text = ''
                $txtPath.Text = ''
                $txtJson.Text = ''
                $moduleState.Files = @()
                $moduleState.CurrentPath = ''

                $found = New-Object System.Collections.ArrayList
                foreach ($modulePath in @(& $getFilteredModulePaths)) {
                    if ([string]::IsNullOrWhiteSpace([string]$modulePath)) { continue }
                    if (-not (Test-Path -LiteralPath $modulePath -PathType Container)) { continue }

                    foreach ($file in @(Get-ChildItem -LiteralPath $modulePath -File -Filter '*.json' -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '\.bak\.json$' } | Sort-Object FullName)) {
                        $display = $file.Name
                        try {
                            $relative = $file.FullName.Substring(([string]$modulePath).Length).TrimStart('\', '/')
                            if (-not [string]::IsNullOrWhiteSpace($relative)) { $display = $relative }
                        }
                        catch { }

                        [void]$found.Add([pscustomobject]@{
                                Display = $display
                                Path    = [string]$file.FullName
                            })
                    }
                }

                $moduleState.Files = @($found)
                foreach ($item in @($moduleState.Files)) {
                    [void]$lstFiles.Items.Add([string]$item.Display)
                }

                if ($lstFiles.Items.Count -gt 0) {
                    $lstFiles.SelectedIndex = 0
                }

                if ($StatusLabel) { $StatusLabel.Text = ('{0}: found {1} JSON file(s).' -f $ModuleTitle, $moduleState.Files.Count) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' refresh failed: ' + $_.Exception.Message) }
            }
        }.GetNewClosure()

        $loadSelectedFile = {
            try {
                $moduleState.CurrentPath = ''
                $txtFile.Text = ''
                $txtPath.Text = ''
                $txtJson.Text = ''

                if ($lstFiles.SelectedIndex -lt 0) { return }
                if ($lstFiles.SelectedIndex -ge $moduleState.Files.Count) { return }

                $entry = $moduleState.Files[$lstFiles.SelectedIndex]
                $path = [string]$entry.Path
                if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return }

                $moduleState.CurrentPath = $path
                $txtFile.Text = [System.IO.Path]::GetFileName($path)
                $txtPath.Text = $path
                $txtJson.Text = Read-UGSMGameDayZTextFileSafe -Path $path

                if ($StatusLabel) { $StatusLabel.Text = ('Loaded ' + [System.IO.Path]::GetFileName($path)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' load failed: ' + $_.Exception.Message) }
            }
        }.GetNewClosure()

        $saveCurrentFile = {
            try {
                $path = [string]$moduleState.CurrentPath
                if ([string]::IsNullOrWhiteSpace($path)) { throw 'No JSON file is selected.' }
                if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw 'Selected JSON file no longer exists.' }

                $null = $txtJson.Text | ConvertFrom-Json
                [void](Backup-UGSMGameDayZFile -TargetPath $path)
                [void](Write-UGSMGameDayZTextFileSafe -Path $path -Content $txtJson.Text)

                if ($StatusLabel) { $StatusLabel.Text = ('Saved ' + [System.IO.Path]::GetFileName($path)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' save failed: ' + $_.Exception.Message) }
            }
        }.GetNewClosure()

        $prettyPrintCurrent = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$txtJson.Text)) { return }
                $data = $txtJson.Text | ConvertFrom-Json
                $txtJson.Text = ($data | ConvertTo-Json -Depth 100)
                if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' JSON formatted. Save to write changes.') }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' pretty print failed: ' + $_.Exception.Message) }
            }
        }.GetNewClosure()

        $btnRefresh.Add_Click($refreshFiles)
        $btnSaveCurrent.Add_Click($saveCurrentFile)
        $btnPretty.Add_Click($prettyPrintCurrent)
        $cmbScope.Add_SelectedIndexChanged($refreshFiles)
        $lstFiles.Add_SelectedIndexChanged($loadSelectedFile)

        $layoutGenericJson = {
            Set-UGSMExpansionLayout `
                -Page $Page `
                -Root $root `
                -Shell $shell `
                -TopBar $topBar `
                -Body $body `
                -LeftPanel $leftPanel `
                -EditorPanel $editorPanel `
                -Tower1 $Tower1 `
                -Tower2 $Tower2 `
                -CmbFilter $cmbScope `
                -LstItems $lstFiles `
                -TxtPath $txtPath `
                -BtnRefresh $btnRefresh `
                -BtnSaveCurrent $btnSaveCurrent `
                -BtnPretty $btnPretty
        }.GetNewClosure()

        & $layoutGenericJson
        $Page.Add_SizeChanged($layoutGenericJson)
        $Page.Add_VisibleChanged($layoutGenericJson)

        & $refreshFiles
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) {
            $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace
        }
        Show-UGSMExpansionTabMessage -Page $Page -Title ($ModuleTitle + ' tab failed') -Message $errorText -TitleColor '#FFB4B4' -ErrorAction SilentlyContinue
        if ($StatusLabel) { $StatusLabel.Text = ($ModuleTitle + ' tab failed: ' + $_.Exception.Message) }
    }
}

function New-DayZExpansionObjectsTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        $Page.Text = 'Objects'
        $ui = New-UGSMExpansionTabShell -Page $Page

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Delete File' -X 0 -Y 0 -Width 110

        foreach ($b in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnPretty, $btnRemove)) {
            [void]$ui.TopBar.Controls.Add($b)
        }

        $leftPanelHeight = [Math]::Max($UGSM_ExpansionLeftPanelMinHeight, ($UGSM_ExpansionTowerHeight + 220))
        $tower1Height = $UGSM_ExpansionTowerHeight + 20
        $tower2Height = $UGSM_ExpansionTowerHeight + 220

        $leftPanel = New-UGSMExpansionLeftListPanel -X $UGSM_ExpansionGap -Y $UGSM_ExpansionGap -Width $UGSM_ExpansionLeftPanelWidth -Height $leftPanelHeight
        [void]$ui.ContentHost.Controls.Add($leftPanel)

        $lblObjectFiles = New-UGSMExpansionEditorLabel -Text 'Object Map Files' -X 12 -Y 12 -Width 180
        $lblObjectFiles.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$leftPanel.Controls.Add($lblObjectFiles)

        $lstFiles = New-Object System.Windows.Forms.ListBox
        $lstFiles.Location = New-Object System.Drawing.Point(12, 40)
        $lstFiles.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), ($leftPanelHeight - 52))
        $lstFiles.Anchor = 'Top,Left,Bottom,Right'
        $lstFiles.BackColor = $global:UGSM_ColorInputBackground
        $lstFiles.ForeColor = $global:UGSM_ColorText
        $lstFiles.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstFiles)

        $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
        $editorWidth = [Math]::Max(760, ($ui.Body.ClientSize.Width - $editorLeft - 24))
        $editorHeight = $tower1Height + $tower2Height + $UGSM_ExpansionSectionGap + 12

        $editorScrollHost = New-Object System.Windows.Forms.Panel
        $editorScrollHost.Location = New-Object System.Drawing.Point($editorLeft, $UGSM_ExpansionGap)
        $editorScrollHost.Width = $editorWidth
        $editorScrollHost.Height = $leftPanelHeight
        $editorScrollHost.Anchor = 'Top,Left,Right,Bottom'
        $editorScrollHost.AutoScroll = $true
        $editorScrollHost.BackColor = $global:UGSM_ColorBackground
        [void]$ui.ContentHost.Controls.Add($editorScrollHost)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width $editorWidth -Height $editorHeight
        $editorPanel.Anchor = 'Top,Left,Right'
        [void]$editorScrollHost.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width $editorWidth -Height $tower1Height
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $UGSM_ExpansionSectionGap) -Width $editorWidth -Height $tower2Height
        [void]$editorPanel.Controls.Add($Tower1)
        [void]$editorPanel.Controls.Add($Tower2)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text 'Objects Editor' -X 12 -Y 12 -Width 240
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)

        $lblHeaderText = New-UGSMExpansionEditorLabel -Text 'Edit Expansion object placement files from mpmissions\<map>\expansion\objects. Each row is saved as ClassName|x y z|yaw pitch roll.' -X 12 -Y 40 -Width 960
        [void]$Tower1.Controls.Add($lblHeaderText)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'Object File' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width 260
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X 284 -Y 76 -Width 80
        $txtPath = New-UGSMExpansionEditorTextBox -X 284 -Y 96 -Width 702
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        $lblRowsTitle = New-UGSMExpansionEditorLabel -Text 'Placed Objects' -X 12 -Y 12 -Width 220
        $lblRowsTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower2.Controls.Add($lblRowsTitle)

        $lblRowsHelp = New-UGSMExpansionEditorLabel -Text 'Position format: x y z   Orientation format: yaw pitch roll' -X 12 -Y 38 -Width 760
        [void]$Tower2.Controls.Add($lblRowsHelp)

        $btnAddRow = New-UGSMExpansionAddButton -Text 'Add Row' -X 12 -Y 64 -Width 90
        $btnRemoveRow = New-UGSMExpansionRemoveButton -Text 'Remove Selected' -X 112 -Y 64 -Width 130
        [void]$Tower2.Controls.Add($btnAddRow)
        [void]$Tower2.Controls.Add($btnRemoveRow)

        $grid = New-Object System.Windows.Forms.DataGridView
        $grid.Location = New-Object System.Drawing.Point(12, 100)
        $grid.Size = New-Object System.Drawing.Size(974, 272)
        $grid.Anchor = 'Top,Left,Right,Bottom'
        $grid.BackgroundColor = $global:UGSM_ColorInputBackground
        $grid.ForeColor = $global:UGSM_ColorText
        $grid.BorderStyle = 'FixedSingle'
        $grid.AllowUserToAddRows = $false
        $grid.AllowUserToDeleteRows = $false
        $grid.AllowUserToResizeRows = $false
        $grid.SelectionMode = 'FullRowSelect'
        $grid.MultiSelect = $true
        $grid.AutoSizeColumnsMode = 'None'
        $grid.RowHeadersVisible = $false
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $grid.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $grid.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        [void]$Tower2.Controls.Add($grid)

        $null = $grid.Columns.Add('ClassName', 'ClassName')
        $null = $grid.Columns.Add('Position', 'Position')
        $null = $grid.Columns.Add('Orientation', 'Orientation')

        $grid.Columns['ClassName'].Width = 320
        $grid.Columns['Position'].Width = 260
        $grid.Columns['Orientation'].Width = 260

        $objectsState = [ordered]@{
            Files       = @()
            CurrentPath = ''
            PendingRows = $null
            Dirty       = $false
        }

        $getObjectsRoot = {
            try {
                if (Get-Command -Name Get-UGSMGameDayZProfilePaths -ErrorAction SilentlyContinue) {
                    $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance
                    if ($paths -and $paths.MissionFolderPath) {
                        return (Join-Path ([string]$paths.MissionFolderPath) 'expansion\objects')
                    }
                }

                $basePath = ''
                if ($Instance.PSObject.Properties.Name -contains 'GameProfilePath') {
                    $basePath = [string]$Instance.GameProfilePath
                }
                if ([string]::IsNullOrWhiteSpace($basePath) -and $Instance.PSObject.Properties.Name -contains 'ProfilePath') {
                    $basePath = [string]$Instance.ProfilePath
                }
                if ([string]::IsNullOrWhiteSpace($basePath)) {
                    throw 'Could not resolve mission path for Expansion objects.'
                }

                return (Join-Path $basePath 'mpmissions\dayzOffline.chernarusplus\expansion\objects')
            }
            catch {
                throw
            }
        }.GetNewClosure()

        $clearEditor = {
            $txtFile.Text = ''
            $txtPath.Text = ''
            $grid.Rows.Clear()
            $objectsState.CurrentPath = ''
            $objectsState.PendingRows = $null
            $objectsState.Dirty = $false
        }.GetNewClosure()

        $parseMapLine = {
            param([string]$Line)

            if ([string]::IsNullOrWhiteSpace($Line)) { return $null }
            $trimmed = $Line.Trim()
            if ([string]::IsNullOrWhiteSpace($trimmed)) { return $null }
            if ($trimmed.StartsWith('//')) { return $null }

            $parts = $trimmed -split '\|'
            if (@($parts).Count -lt 3) { return $null }

            return [pscustomobject]@{
                ClassName   = [string]$parts[0].Trim()
                Position    = [string]$parts[1].Trim()
                Orientation = [string]$parts[2].Trim()
            }
        }.GetNewClosure()

        $buildMapLine = {
            param(
                [string]$ClassName,
                [string]$Position,
                [string]$Orientation
            )

            $cn = [string]$ClassName
            $pos = [string]$Position
            $ori = [string]$Orientation

            if ([string]::IsNullOrWhiteSpace($cn)) { return $null }
            if ([string]::IsNullOrWhiteSpace($pos)) { return $null }
            if ([string]::IsNullOrWhiteSpace($ori)) { return $null }

            return ('{0}|{1}|{2}' -f $cn.Trim(), $pos.Trim(), $ori.Trim())
        }.GetNewClosure()

        $readObjectMapFile = {
            param([string]$Path)

            $rows = New-Object System.Collections.ArrayList
            if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
                return @($rows)
            }

            foreach ($line in @(Get-Content -LiteralPath $Path -ErrorAction Stop)) {
                $parsed = & $parseMapLine ([string]$line)
                if ($null -ne $parsed) {
                    [void]$rows.Add($parsed)
                }
            }

            return @($rows)
        }.GetNewClosure()

        $writeObjectMapFile = {
            param(
                [string]$Path,
                [object[]]$Rows
            )

            $lines = New-Object System.Collections.ArrayList
            foreach ($row in @($Rows)) {
                $line = & $buildMapLine -ClassName ([string]$row.ClassName) -Position ([string]$row.Position) -Orientation ([string]$row.Orientation)
                if (-not [string]::IsNullOrWhiteSpace([string]$line)) {
                    [void]$lines.Add($line)
                }
            }

            $content = [string]::Join([Environment]::NewLine, @($lines))
            [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content $content)
        }.GetNewClosure()

        $refreshObjectFiles = {
            try {
                $root = & $getObjectsRoot
                $selectedName = ''
                if ($lstFiles.SelectedItem) {
                    $selectedName = [string]$lstFiles.SelectedItem
                }

                $lstFiles.Items.Clear()
                $objectsState.Files = @()

                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $allFiles = @(Get-ChildItem -LiteralPath $root -File -Filter '*.map' -ErrorAction SilentlyContinue)
                $objectsState.Files = @($allFiles | Sort-Object Name)

                foreach ($file in @($objectsState.Files)) {
                    [void]$lstFiles.Items.Add([System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name))
                }

                if ($lstFiles.Items.Count -gt 0) {
                    $restoreIndex = -1
                    if (-not [string]::IsNullOrWhiteSpace($selectedName)) {
                        $restoreIndex = $lstFiles.Items.IndexOf($selectedName)
                    }
                    if ($restoreIndex -lt 0) { $restoreIndex = 0 }
                    $lstFiles.SelectedIndex = $restoreIndex
                }
                else {
                    & $clearEditor
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded ' + [string]@($objectsState.Files).Count + ' object map file(s).')
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Refreshing object files failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $loadSelectedObjectFile = {
            try {
                if ($lstFiles.SelectedIndex -lt 0 -or $lstFiles.SelectedIndex -ge @($objectsState.Files).Count) {
                    & $clearEditor
                    return
                }

                $file = $objectsState.Files[$lstFiles.SelectedIndex]
                $rows = & $readObjectMapFile -Path $file.FullName

                $txtFile.Text = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                $txtPath.Text = [string]$file.FullName
                $grid.Rows.Clear()

                foreach ($row in @($rows)) {
                    [void]$grid.Rows.Add(
                        [string]$row.ClassName,
                        [string]$row.Position,
                        [string]$row.Orientation
                    )
                }

                $objectsState.CurrentPath = [string]$file.FullName
                $objectsState.PendingRows = $null
                $objectsState.Dirty = $false

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded Object file: ' + [System.IO.Path]::GetFileName($file.FullName))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Loading object file failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $buildCurrentRows = {
            $rows = New-Object System.Collections.ArrayList
            foreach ($row in @($grid.Rows)) {
                if ($row.IsNewRow) { continue }

                $className = [string]$row.Cells['ClassName'].Value
                $position = [string]$row.Cells['Position'].Value
                $orientation = [string]$row.Cells['Orientation'].Value

                if ([string]::IsNullOrWhiteSpace($className)) { continue }
                if ([string]::IsNullOrWhiteSpace($position)) { continue }
                if ([string]::IsNullOrWhiteSpace($orientation)) { continue }

                [void]$rows.Add([pscustomobject]@{
                        ClassName   = $className.Trim()
                        Position    = $position.Trim()
                        Orientation = $orientation.Trim()
                    })
            }

            return @($rows)
        }.GetNewClosure()

        $applyObjects = {
            try {
                $objectsState.PendingRows = @(& $buildCurrentRows)
                $objectsState.Dirty = $true
                if ($StatusLabel) {
                    $StatusLabel.Text = ('Applied draft for object file: ' + [string]$txtFile.Text)
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applying object file failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $saveCurrent = {
            try {
                $rows = $(if ($objectsState.PendingRows) { $objectsState.PendingRows } else { & $buildCurrentRows })

                $fileName = [string]$txtFile.Text
                if ([string]::IsNullOrWhiteSpace($fileName)) {
                    throw 'Object File is required.'
                }
                if (-not $fileName.EndsWith('.map', [System.StringComparison]::OrdinalIgnoreCase)) {
                    $fileName += '.map'
                }

                $root = & $getObjectsRoot
                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $targetPath = Join-Path $root $fileName
                $oldPath = [string]$objectsState.CurrentPath

                if (-not [string]::IsNullOrWhiteSpace($oldPath) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
                    [void](Backup-UGSMGameDayZFile -TargetPath $oldPath)
                }

                & $writeObjectMapFile -Path $targetPath -Rows $rows

                if (
                    -not [string]::IsNullOrWhiteSpace($oldPath) -and
                    ($oldPath -ne $targetPath) -and
                    (Test-Path -LiteralPath $oldPath -PathType Leaf)
                ) {
                    Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue
                }

                $objectsState.CurrentPath = $targetPath
                $objectsState.PendingRows = $null
                $objectsState.Dirty = $false

                & $refreshObjectFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstFiles.Items.IndexOf($selectedName)
                if ($index -ge 0) {
                    $lstFiles.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Object file: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving object file failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $prettyPrintCurrent = {
            try {
                $targetPath = [string]$objectsState.CurrentPath
                if ([string]::IsNullOrWhiteSpace($targetPath) -or -not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                    throw 'Select an object file first.'
                }

                $rows = & $readObjectMapFile -Path $targetPath
                [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
                & $writeObjectMapFile -Path $targetPath -Rows $rows
                & $refreshObjectFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstFiles.Items.IndexOf($selectedName)
                if ($index -ge 0) {
                    $lstFiles.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Pretty printed Object file: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Pretty Print failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $newObjectFile = {
            try {
                $root = & $getObjectsRoot
                if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($root)
                }

                $baseName = 'UGSM_TestObjects'
                $filePath = Join-Path $root ($baseName + '.map')
                if (Test-Path -LiteralPath $filePath -PathType Leaf) {
                    for ($i = 1; $i -le 999; $i++) {
                        $candidate = Join-Path $root ('{0}_{1:D2}.map' -f $baseName, $i)
                        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                            $filePath = $candidate
                            break
                        }
                    }
                }

                & $writeObjectMapFile -Path $filePath -Rows @()
                & $refreshObjectFiles

                $newName = [System.IO.Path]::GetFileNameWithoutExtension($filePath)
                $index = $lstFiles.Items.IndexOf($newName)
                if ($index -ge 0) {
                    $lstFiles.SelectedIndex = $index
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Created Object file: ' + [System.IO.Path]::GetFileName($filePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Creating object file failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $deleteCurrent = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$objectsState.CurrentPath)) {
                    throw 'No object file is selected.'
                }

                [void](Backup-UGSMGameDayZFile -TargetPath $objectsState.CurrentPath)
                Remove-Item -LiteralPath $objectsState.CurrentPath -Force -ErrorAction Stop

                & $refreshObjectFiles
                & $clearEditor

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Deleted Object file.'
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Deleting object file failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $addRow = {
            [void]$grid.Rows.Add('', '', '')
            $objectsState.Dirty = $true
        }.GetNewClosure()

        $removeRow = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $grid.SelectedRows) {
                [void]$selected.Add($row)
            }

            if ($selected.Count -eq 0) { return }

            $ordered = @($selected | Sort-Object Index -Descending)
            foreach ($row in $ordered) {
                if (-not $row.IsNewRow) {
                    $grid.Rows.Remove($row)
                }
            }

            $objectsState.Dirty = $true
        }.GetNewClosure()

        $layout = {
            $ui.TopBar.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Height = [Math]::Max(200, ($ui.Shell.ClientSize.Height - $ui.Body.Top - 4))

            $toolbarY = 8
            $btnNew.Location = New-Object System.Drawing.Point(12, $toolbarY)
            $btnRefresh.Location = New-Object System.Drawing.Point(($btnNew.Right + 10), $toolbarY)

            $btnRemove.Location = New-Object System.Drawing.Point(($ui.TopBar.ClientSize.Width - $btnRemove.Width - 12), $toolbarY)
            $btnPretty.Location = New-Object System.Drawing.Point(($btnRemove.Left - $btnPretty.Width - 10), $toolbarY)
            $btnSaveCurrent.Location = New-Object System.Drawing.Point(($btnPretty.Left - $btnSaveCurrent.Width - 10), $toolbarY)
            $btnApply.Location = New-Object System.Drawing.Point(($btnSaveCurrent.Left - $btnApply.Width - 10), $toolbarY)

            $bodyWidth = $ui.Body.ClientSize.Width
            $bodyHeight = $ui.Body.ClientSize.Height
            $outerGap = $UGSM_ExpansionGap
            $columnGap = $UGSM_ExpansionColumnGap
            $leftWidth = $UGSM_ExpansionLeftPanelWidth

            $editorWidth = [Math]::Max(760, ($bodyWidth - ($outerGap * 2) - $leftWidth - $columnGap))
            $workspaceWidth = $leftWidth + $columnGap + $editorWidth
            $workspaceLeft = [Math]::Max($outerGap, [int](($bodyWidth - $workspaceWidth) / 2))
            $topY = $outerGap

            $leftPanel.Location = New-Object System.Drawing.Point($workspaceLeft, $topY)
            $leftPanel.Width = $leftWidth
            $leftPanel.Height = [Math]::Max(200, ($bodyHeight - ($outerGap * 2) - 8))
            $lstFiles.Height = [Math]::Max(100, ($leftPanel.ClientSize.Height - $lstFiles.Top - 12))

            $editorScrollHost.Location = New-Object System.Drawing.Point(($leftPanel.Right + $columnGap), $topY)
            $editorScrollHost.Width = $editorWidth
            $editorScrollHost.Height = $leftPanel.Height

            $editorPanel.Location = New-Object System.Drawing.Point(0, 0)
            $editorPanel.Width = $editorWidth
            $editorPanel.Height = $editorHeight

            $Tower1.Location = New-Object System.Drawing.Point(0, 0)
            $Tower1.Width = $editorWidth - 1
            $Tower1.Height = $tower1Height

            $Tower2.Location = New-Object System.Drawing.Point(0, ($Tower1.Bottom + $UGSM_ExpansionSectionGap))
            $Tower2.Width = $editorWidth - 1
            $Tower2.Height = $tower2Height

            $editorPanel.Height = $Tower2.Bottom + 1

            $txtPath.Width = [Math]::Max(180, ($Tower1.ClientSize.Width - $txtPath.Left - 12))
            $grid.Width = [Math]::Max(420, ($Tower2.ClientSize.Width - 24))
            $grid.Height = [Math]::Max(160, ($Tower2.ClientSize.Height - $grid.Top - 12))
        }.GetNewClosure()

        $btnNew.Add_Click({ & $newObjectFile }.GetNewClosure())
        $btnRefresh.Add_Click({ & $refreshObjectFiles }.GetNewClosure())
        $btnApply.Add_Click({ & $applyObjects }.GetNewClosure())
        $btnSaveCurrent.Add_Click({ & $saveCurrent }.GetNewClosure())
        $btnPretty.Add_Click({ & $prettyPrintCurrent }.GetNewClosure())
        $btnRemove.Add_Click({ & $deleteCurrent }.GetNewClosure())

        $btnAddRow.Add_Click({ & $addRow }.GetNewClosure())
        $btnRemoveRow.Add_Click({ & $removeRow }.GetNewClosure())

        $lstFiles.Add_SelectedIndexChanged({ & $loadSelectedObjectFile }.GetNewClosure())

        & $refreshObjectFiles
        & $layout
        $Page.Add_SizeChanged($layout)
    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Loading Expansion Objects tab failed: ' + $_.Exception.Message
        }
    }
}
function New-DayZExpansionP2PMarketTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    Initialize-UGSMExpansionThemeDefaults

    try {
        $Page.Text = 'P2P Market'
        $Page.BackColor = $global:UGSM_ColorBackground
        $Page.ForeColor = $global:UGSM_ColorText
        $Page.AutoScroll = $false
        $Page.Controls.Clear()

        # =====================================================================
        # =====================================================================
        $root = New-Object System.Windows.Forms.Panel
        $root.Dock = 'Fill'
        $root.autoscroll = $false
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$Page.Controls.Add($root)

        $shell = New-Object System.Windows.Forms.Panel
        $shell.Location = New-Object System.Drawing.Point(0, 0)
        $shell.Size = New-Object System.Drawing.Size([Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width), 1040)
        $shell.Anchor = 'Top,Left,Right'
        $shell.BackColor = $global:UGSM_ColorBackground
        $shell.BorderStyle = 'None'
        [void]$root.Controls.Add($shell)

        $topBar = New-Object System.Windows.Forms.Panel
        $topBar.Location = New-Object System.Drawing.Point(0, 0)
        $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
        $topBar.Anchor = 'Top,Left,Right'
        $topBar.BackColor = $global:UGSM_ColorBackground
        $topBar.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($topBar)

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthMedium
        foreach ($button in @($btnNew, $btnRefresh, $btnSaveCurrent)) {
            $button.Anchor = 'Top,Left'
            Set-UGSMExpansionButtonStyle -Button $button | Out-Null
            [void]$topBar.Controls.Add($button)
        }
        Set-UGSMExpansionToolbarButtons -Buttons @($btnNew, $btnRefresh, $btnSaveCurrent)

        $body = New-Object System.Windows.Forms.Panel
        $body.Location = New-Object System.Drawing.Point($UGSM_ExpansionOffsetX, ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap))
        $body.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12))
        $body.Anchor = 'Top,Left,Right,Bottom'
        $body.BackColor = $global:UGSM_ColorBackground
        $body.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($body)

        $leftPanel = New-UGSMExpansionLeftListPanel `
            -X ($UGSM_ExpansionGap) `
            -Y ($UGSM_ExpansionGap) `
            -Width $UGSM_ExpansionLeftPanelWidth `
            -Height 860
        [void]$body.Controls.Add($leftPanel)

        $lstFiles = New-Object System.Windows.Forms.ListBox
        $lstFiles.Location = New-Object System.Drawing.Point(12, 12)
        $lstFiles.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), 820)
        $lstFiles.Anchor = 'Top,Left,Bottom,Right'
        $lstFiles.BackColor = $global:UGSM_ColorInputBackground
        $lstFiles.ForeColor = $global:UGSM_ColorText
        $lstFiles.BorderStyle = 'FixedSingle'
        $lstFiles.IntegralHeight = $false
        [void]$leftPanel.Controls.Add($lstFiles)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 860
        $editorPanel.AutoScroll = $true
        [void]$body.Controls.Add($editorPanel)

        # =====================================================================
        # TOWER 1 - selected file/header. The actual editor is hosted in Tower 2.
        # =====================================================================
        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 130
        [void]$editorPanel.Controls.Add($Tower1)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text 'P2P Market Editor' -X 12 -Y 12 -Width 380
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)

        $lblHeaderDesc = New-UGSMExpansionEditorLabel -Text 'Structured editor for P2P market settings and P2P trader configuration files. Raw JSON editing stays in the Files tab.' -X 12 -Y 40 -Width 900
        [void]$Tower1.Controls.Add($lblHeaderDesc)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'File' -X 12 -Y 76 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width $UGSM_ExpansionFileFieldWidth
        $txtFile.ReadOnly = $false
        $txtFile.TabStop = $true
        [void]$Tower1.Controls.Add($lblFile)
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X $UGSM_ExpansionPathFieldLeft -Y 76 -Width 120
        $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 96 -Width 400
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($lblPath)
        [void]$Tower1.Controls.Add($txtPath)

        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 780
        [void]$editorPanel.Controls.Add($Tower2)

        $editorHost = New-Object System.Windows.Forms.Panel
        $editorHost.Location = New-Object System.Drawing.Point(12, 12)
        $editorHost.Size = New-Object System.Drawing.Size(950, 740)
        $editorHost.Anchor = 'Top,Left,Right,Bottom'
        $editorHost.BackColor = $global:UGSM_ColorBackground
        $editorHost.BorderStyle = 'None'
        [void]$Tower2.Controls.Add($editorHost)

        $p2pState = [ordered]@{
            Files              = @()
            CurrentFilePath    = ''
            CurrentSaveHandler = $null
            EditorHost         = $editorHost
            FileHandler        = 'None'
        }

        $showMessage = {
            param([string]$Message)
            $editorHost.Controls.Clear()
            $lbl = New-UGSMExpansionEditorLabel -Text $Message -X 12 -Y 12 -Width 850 -Height 80
            [void]$editorHost.Controls.Add($lbl)
        }.GetNewClosure()

        $sanitizeP2PFileName = {
            param([string]$Name)

            $clean = ([string]$Name).Trim()
            if ([string]::IsNullOrWhiteSpace($clean)) { throw 'File name cannot be blank.' }
            $clean = [System.IO.Path]::GetFileName($clean)
            if ([string]::IsNullOrWhiteSpace($clean)) { throw 'File name cannot be blank.' }
            foreach ($bad in [System.IO.Path]::GetInvalidFileNameChars()) {
                if ($clean.Contains([string]$bad)) { throw ('File name contains an invalid character: ' + [string]$bad) }
            }
            if (-not $clean.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) { $clean += '.json' }
            return $clean
        }.GetNewClosure()

        $getUniqueP2PPath = {
            param([Parameter(Mandatory)][string]$Folder, [Parameter(Mandatory)][string]$BaseName)
            $clean = & $sanitizeP2PFileName $BaseName
            $candidate = Join-Path $Folder $clean
            if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $candidate }
            $stem = [System.IO.Path]::GetFileNameWithoutExtension($clean)
            $ext = [System.IO.Path]::GetExtension($clean)
            $index = 1
            do {
                $candidate = Join-Path $Folder ($stem + '_' + $index + $ext)
                $index++
            } while (Test-Path -LiteralPath $candidate -PathType Leaf)
            return $candidate
        }.GetNewClosure()

        $applyFileRenameIfNeeded = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$p2pState.CurrentFilePath)) { return }
                $oldPath = [string]$p2pState.CurrentFilePath
                if (-not (Test-Path -LiteralPath $oldPath -PathType Leaf)) { return }
                $newName = & $sanitizeP2PFileName ([string]$txtFile.Text)
                $oldName = [System.IO.Path]::GetFileName($oldPath)
                if ([string]::Equals($oldName, $newName, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $txtFile.Text = $oldName
                    return
                }
                $folder = [System.IO.Path]::GetDirectoryName($oldPath)
                $newPath = Join-Path $folder $newName
                if (Test-Path -LiteralPath $newPath -PathType Leaf) { throw ('A file already exists with that name: ' + $newName) }
                Move-Item -LiteralPath $oldPath -Destination $newPath -Force
                $p2pState.CurrentFilePath = [string]$newPath
                $txtFile.Text = [System.IO.Path]::GetFileName($newPath)
                $txtPath.Text = [string]$newPath
            }
            catch { throw ('Rename failed: ' + $_.Exception.Message) }
        }.GetNewClosure()

        $refreshFiles = {
            try {
                $lstFiles.Items.Clear()
                $p2pState.Files = @()
                $p2pState.CurrentFilePath = ''
                $p2pState.CurrentSaveHandler = $null
                $txtFile.Text = ''
                $txtPath.Text = ''
                & $showMessage 'Select P2PMarketSettings.json for market options, or select a trader JSON file to edit trader spawn/display settings.'

                $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
                $candidateRoots = New-Object System.Collections.ArrayList

                if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionSettingsRoot)) {
                    [void]$candidateRoots.Add([string]$paths.MissionSettingsRoot)
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileSettingsRoot)) {
                    [void]$candidateRoots.Add([string]$paths.ProfileSettingsRoot)
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionExpansionRoot)) {
                    [void]$candidateRoots.Add([string]$paths.MissionExpansionRoot)
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileExpansionRoot)) {
                    [void]$candidateRoots.Add([string]$paths.ProfileExpansionRoot)
                }

                $found = New-Object System.Collections.ArrayList
                foreach ($rootPath in @($candidateRoots)) {
                    if ([string]::IsNullOrWhiteSpace([string]$rootPath)) { continue }
                    if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) { continue }

                    foreach ($file in @(Get-ChildItem -LiteralPath $rootPath -File -Filter '*.json' -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '\.bak\.json$' -and ([string]$_.FullName -match '(?i)[\\/]p2pmarket([\\/]|$)') } | Sort-Object FullName)) {
                        if (@($found | Where-Object { [string]$_.FullName -eq [string]$file.FullName }).Count -gt 0) { continue }
                        [void]$found.Add($file)
                    }
                }

                $p2pState.Files = @($found)
                foreach ($file in @($p2pState.Files)) {
                    $display = [string]$file.Name
                    try {
                        if ([string]$file.FullName -like '*\mpmissions\*' -or [string]$file.FullName -like '*/mpmissions/*') {
                            $display = 'Mission: ' + [string]$file.Name
                        }
                        elseif ([string]$file.FullName -like '*\profiles\*' -or [string]$file.FullName -like '*/profiles/*') {
                            $display = 'Profile: ' + [string]$file.Name
                        }
                    }
                    catch { }
                    [void]$lstFiles.Items.Add($display)
                }

                if ($lstFiles.Items.Count -gt 0) {
                    $lstFiles.SelectedIndex = 0
                }
                elseif ($StatusLabel) {
                    $StatusLabel.Text = 'No P2P market JSON files were found in Expansion p2pmarket paths.'
                }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Refreshing P2P Market files failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $loadSelectedFile = {
            try {
                $editorHost.Controls.Clear()
                $p2pState.CurrentFilePath = ''
                $p2pState.CurrentSaveHandler = $null

                if ($lstFiles.SelectedIndex -lt 0) { return }
                if ($lstFiles.SelectedIndex -ge $p2pState.Files.Count) { return }

                $file = $p2pState.Files[$lstFiles.SelectedIndex]
                $p2pState.CurrentFilePath = [string]$file.FullName
                $txtFile.Text = [string]$file.Name
                $txtPath.Text = [string]$file.FullName

                $raw = Read-UGSMGameDayZTextFileSafe -Path $file.FullName
                $json = $raw | ConvertFrom-Json
                $propNames = @($json.PSObject.Properties.Name)

                if (([string]$file.Name -ieq 'P2PMarketSettings.json') -or ($propNames -contains 'MenuCategories')) {
                    Show-DayZExpansionSettingEditor_P2PMarketSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $p2pState -StatusLabel $StatusLabel
                    if ($StatusLabel) { $StatusLabel.Text = 'Loaded P2P market settings: ' + [string]$file.Name }
                }
                elseif (($propNames -contains 'm_TraderID') -and ($propNames -contains 'm_ClassName')) {
                    Show-DayZExpansionSettingEditor_P2PTraderConfig -HostPanel $editorHost -FilePath $file.FullName -SettingsState $p2pState -StatusLabel $StatusLabel
                    if ($StatusLabel) { $StatusLabel.Text = 'Loaded P2P trader config: ' + [string]$file.Name }
                }
                else {
                    $p2pState.FileHandler = 'RawOnly'
                    $p2pState.CurrentSaveHandler = $null
                    & $showMessage ('No structured P2P editor matched this file. Use the Files tab for raw JSON editing: ' + [string]$file.Name)
                    if ($StatusLabel) { $StatusLabel.Text = 'Loaded P2P JSON as raw-only: ' + [string]$file.Name }
                }
            }
            catch {
                & $showMessage ('Loading P2P Market file failed: ' + $_.Exception.Message)
                if ($StatusLabel) { $StatusLabel.Text = 'Loading P2P Market file failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $saveCurrent = {
            try {
                if ($p2pState.CurrentSaveHandler -isnot [scriptblock]) { throw 'No structured P2P Market file is loaded.' }
                $oldPathBeforeSave = [string]$p2pState.CurrentFilePath
                & $p2pState.CurrentSaveHandler
                & $applyFileRenameIfNeeded
                $selectedPath = [string]$p2pState.CurrentFilePath
                if ([string]::IsNullOrWhiteSpace($selectedPath)) { $selectedPath = $oldPathBeforeSave }
                & $refreshFiles
                for ($i = 0; $i -lt $p2pState.Files.Count; $i++) {
                    if ([string]$p2pState.Files[$i].FullName -eq $selectedPath) {
                        $lstFiles.SelectedIndex = $i
                        break
                    }
                }
                if ($StatusLabel) { $StatusLabel.Text = 'Saved P2P Market file: ' + [System.IO.Path]::GetFileName($selectedPath) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving P2P Market failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $newFile = {
            try {
                $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
                if ([string]::IsNullOrWhiteSpace([string]$paths.MissionExpansionRoot)) {
                    throw 'Mission Expansion path could not be resolved for this server profile.'
                }

                $p2pRoot = Join-Path ([string]$paths.MissionExpansionRoot) 'p2pmarket'
                if (-not (Test-Path -LiteralPath $p2pRoot -PathType Container)) {
                    [void](New-Item -ItemType Directory -Path $p2pRoot -Force)
                }

                $choice = [System.Windows.Forms.MessageBox]::Show(
                    'Create a new P2P trader config?' + [Environment]::NewLine + [Environment]::NewLine + 'Yes = Trader config' + [Environment]::NewLine + 'No = P2PMarketSettings.json' + [Environment]::NewLine + 'Cancel = Stop',
                    'New P2P Market File',
                    [System.Windows.Forms.MessageBoxButtons]::YesNoCancel,
                    [System.Windows.Forms.MessageBoxIcon]::Question
                )

                if ($choice -eq [System.Windows.Forms.DialogResult]::Cancel) { return }

                if ($choice -eq [System.Windows.Forms.DialogResult]::No) {
                    $target = Join-Path $p2pRoot 'P2PMarketSettings.json'
                    if (Test-Path -LiteralPath $target -PathType Leaf) {
                        $target = & $getUniqueP2PPath -Folder $p2pRoot -BaseName 'P2PMarketSettings_New.json'
                    }

                    $data = [ordered]@{
                        m_Version                   = 2
                        Enabled                     = 1
                        MaxListingTime              = 691200
                        MaxListings                 = 20
                        ListingOwnerDiscountPercent = 70
                        ListingPricePercent         = 30
                        SalesDepositTime            = 691200
                        DisallowUnpersisted         = 0
                        ExcludedClassNames          = @(
                            'SurvivorBase',
                            'ExpansionMoneyBase'
                        )
                        MenuCategories              = @(
                            [ordered]@{
                                DisplayName   = 'Ammo'
                                IconPath      = 'set:dayz_inventory image:bullets'
                                Included      = @('Ammunition_Base', 'Box_Base')
                                Excluded      = @()
                                SubCategories = @(
                                    [ordered]@{
                                        DisplayName = 'Ammo-Boxes'
                                        IconPath    = 'set:dayz_inventory image:bullets'
                                        Included    = @('Box_Base')
                                        Excluded    = @()
                                    }
                                )
                            },
                            [ordered]@{
                                DisplayName   = 'Weapons'
                                IconPath      = 'set:dayz_inventory image:rifle'
                                Included      = @('Weapon_Base')
                                Excluded      = @()
                                SubCategories = @(
                                    [ordered]@{
                                        DisplayName = 'Magazines'
                                        IconPath    = 'set:dayz_inventory image:pistol'
                                        Included    = @('Magazine_Base')
                                        Excluded    = @()
                                    }
                                )
                            },
                            [ordered]@{
                                DisplayName   = 'Clothing'
                                IconPath      = 'set:dayz_inventory image:body'
                                Included      = @('ClothingBase')
                                Excluded      = @()
                                SubCategories = @()
                            },
                            [ordered]@{
                                DisplayName   = 'Food and Drinks'
                                IconPath      = 'set:dayz_inventory image:food'
                                Included      = @('Edible_Base', 'Bottle_Base')
                                Excluded      = @()
                                SubCategories = @()
                            },
                            [ordered]@{
                                DisplayName   = 'Vehicles'
                                IconPath      = 'set:dayz_inventory image:cat_vehicle_body'
                                Included      = @('CarScript', 'ExpansionHelicopterScript', 'ExpansionBoatScript')
                                Excluded      = @()
                                SubCategories = @()
                            }
                        )
                    }
                }
                else {
                    $target = & $getUniqueP2PPath -Folder $p2pRoot -BaseName 'P2PTrader_New.json'

                    $data = [ordered]@{
                        m_Version                 = 8
                        m_TraderID                = -1
                        m_ClassName               = 'ExpansionP2PTraderAllrena'
                        m_Position                = @(0, 0, 0)
                        m_Orientation             = @(0, 0, 0)
                        m_LoadoutFile             = ''
                        m_VehicleSpawnPosition    = @(0, 0, 0)
                        m_WatercraftSpawnPosition = @(0, 0, 0)
                        m_AircraftSpawnPosition   = @(0, 0, 0)
                        m_DisplayName             = 'New P2P Trader'
                        m_DisplayIcon             = ''
                        m_Faction                 = ''
                        m_IsGlobalTrader          = 0
                    }
                }

                $json = ($data | ConvertTo-Json -Depth 100)
                [void](Write-UGSMGameDayZTextFileSafe -Path $target -Content $json)

                & $refreshFiles

                for ($i = 0; $i -lt $p2pState.Files.Count; $i++) {
                    if ([string]$p2pState.Files[$i].FullName -eq [string]$target) {
                        $lstFiles.SelectedIndex = $i
                        break
                    }
                }

                if ($StatusLabel) { $StatusLabel.Text = 'Created P2P Market file: ' + [System.IO.Path]::GetFileName($target) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Creating P2P Market file failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $btnNew.Add_Click($newFile)
        $btnRefresh.Add_Click($refreshFiles)
        $btnSaveCurrent.Add_Click($saveCurrent)
        $lstFiles.Add_SelectedIndexChanged($loadSelectedFile)

        $layoutP2P = {
            Set-UGSMExpansionLayout `
                -Page $Page `
                -Root $root `
                -Shell $shell `
                -TopBar $topBar `
                -Body $body `
                -LeftPanel $leftPanel `
                -EditorPanel $editorPanel `
                -Tower1 $Tower1 `
                -Tower2 $Tower2 `
                -LstItems $lstFiles `
                -TxtPath $txtPath `
                -BtnNew $btnNew `
                -BtnRefresh $btnRefresh `
                -BtnSaveCurrent $btnSaveCurrent

            try {
                $editorHost.Location = New-Object System.Drawing.Point(12, 12)
                $editorHost.Size = New-Object System.Drawing.Size(
                    [Math]::Max(200, ($Tower2.ClientSize.Width - 24)),
                    [Math]::Max(200, ($Tower2.ClientSize.Height - 24))
                )
            }
            catch { }
        }.GetNewClosure()

        & $layoutP2P
        $Page.Add_SizeChanged($layoutP2P)
        $Page.Add_VisibleChanged($layoutP2P)

        & $refreshFiles

        if ($StatusLabel) { $StatusLabel.Text = 'P2P Market tab loaded.' }
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) {
            $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace
        }
        Show-UGSMExpansionTabMessage -Page $Page -Title 'P2P Market tab failed' -Message $errorText -TitleColor '#FFB4B4' -ErrorAction SilentlyContinue
        if ($StatusLabel) { $StatusLabel.Text = 'P2P Market tab failed: ' + $_.Exception.Message }
    }
}
