function New-DayZExpansionHardlineTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance

        # --- KEEP: File Discovery Logic ---
        # (This part is still useful to find where the Hardline file actually lives)
        $candidatePaths = @()
        if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileSettingsRoot)) {
            $candidatePaths += (Join-Path ([string]$paths.ProfileSettingsRoot) 'HardlineSettings.json')
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionSettingsRoot)) {
            $candidatePaths += (Join-Path ([string]$paths.MissionSettingsRoot) 'HardlineSettings.json')
        }
        $candidatePaths = @($candidatePaths | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -Unique)

        # Pick the best file (highest version/reputation count)
        $filePath = ''
        $bestScore = -1
        foreach ($cp in $candidatePaths) {
            # We call your score function here (keep that helper function defined inside or above)
            $score = Get-HardlineCandidateScore -CandidatePath $cp
            if ($score -gt $bestScore) {
                $bestScore = $score
                $filePath = $cp
            }
        }

        if ([string]::IsNullOrWhiteSpace($filePath)) {
            # Show error if no file found
            Show-UGSMExpansionTabMessage -Page $Page -Title 'Hardline Not Found' -Message 'Could not locate HardlineSettings.json'
            return
        }

        # --- CHANGE: Simplified State Object ---
        # We pass this into the editor. Use 'SettingsState' (Capital S) to match your editor.
        $SettingsState = [ordered]@{
            CurrentSaveHandler = $null
            CurrentFilePath    = $filePath
            Instance           = $Instance
            HardlineData       = $null
        }

        # --- CHANGE: Remove the closure bubble ---
        # Just call the editor directly. This prevents the 'Object not valid' errors 
        # because variables aren't being 'snapshotted' into a frozen state.
        
        Show-DayZExpansionSettingEditor_HardlineSettings `
            -HostPanel $Page `
            -FilePath $filePath `
            -SettingsState $SettingsState `
            -StatusLabel $StatusLabel

        if ($StatusLabel) { $StatusLabel.Text = "Ready: $([System.IO.Path]::GetFileName($filePath))" }

    }
    catch {
        Write-UGSMGameDayZExpansionSafeLog -Level 'Error' -Message ("Tab Error: {0}" -f $_.Exception.Message)
    }
}
function New-DayZExpansionLoadoutsTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    try {
        Add-Type -AssemblyName System.Windows.Forms
        Add-Type -AssemblyName System.Drawing

        Initialize-UGSMExpansionThemeDefaults

        # ---------------------------------------------------------------------
        # Script-scoped helpers are used because WinForms event handlers can fire
        # after this builder function has returned.
        # ---------------------------------------------------------------------
        function script:Set-LoadoutJsonValue {
            param($Object, [string]$Name, $Value)
            if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) { return }
            if ($Object.PSObject.Properties[$Name]) { $Object.PSObject.Properties[$Name].Value = $Value }
            else { $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force }
        }

        function script:New-ExpansionLoadoutItemTemplate {
            param([string]$ClassName = '')
            return [pscustomobject]@{
                ClassName              = $ClassName
                Include                = ''
                Chance                 = 1.0
                Quantity               = [pscustomobject]@{ Min = 0.0; Max = 0.0 }
                Health                 = @()
                InventoryAttachments   = @()
                InventoryCargo         = @()
                ConstructionPartsBuilt = @()
                Sets                   = @()
            }
        }

        function script:New-ExpansionLoadoutTemplate {
            return [pscustomobject]@{
                ClassName              = ''
                Include                = ''
                Chance                 = 1.0
                Quantity               = [pscustomobject]@{ Min = 0.0; Max = 0.0 }
                Health                 = @()
                InventoryAttachments   = @(
                    [pscustomobject]@{
                        SlotName = 'Body'
                        Items    = @((New-ExpansionLoadoutItemTemplate -ClassName 'TShirt_Black'))
                    }
                )
                InventoryCargo         = @()
                ConstructionPartsBuilt = @()
                Sets                   = @()
            }
        }

        function script:Ensure-ExpansionLoadoutShape {
            param($Loadout)
            if ($null -eq $Loadout) { return (New-ExpansionLoadoutTemplate) }
            if (-not $Loadout.PSObject.Properties['ClassName']) { $Loadout | Add-Member -NotePropertyName ClassName -NotePropertyValue '' -Force }
            if (-not $Loadout.PSObject.Properties['Include']) { $Loadout | Add-Member -NotePropertyName Include -NotePropertyValue '' -Force }
            if (-not $Loadout.PSObject.Properties['Chance']) { $Loadout | Add-Member -NotePropertyName Chance -NotePropertyValue 1.0 -Force }
            if (-not $Loadout.PSObject.Properties['Quantity'] -or $null -eq $Loadout.Quantity) { $Loadout | Add-Member -NotePropertyName Quantity -NotePropertyValue ([pscustomobject]@{ Min = 0.0; Max = 0.0 }) -Force }
            if (-not $Loadout.Quantity.PSObject.Properties['Min']) { $Loadout.Quantity | Add-Member -NotePropertyName Min -NotePropertyValue 0.0 -Force }
            if (-not $Loadout.Quantity.PSObject.Properties['Max']) { $Loadout.Quantity | Add-Member -NotePropertyName Max -NotePropertyValue 0.0 -Force }
            if (-not $Loadout.PSObject.Properties['Health']) { $Loadout | Add-Member -NotePropertyName Health -NotePropertyValue @() -Force }
            if (-not $Loadout.PSObject.Properties['InventoryAttachments']) { $Loadout | Add-Member -NotePropertyName InventoryAttachments -NotePropertyValue @() -Force }
            if (-not $Loadout.PSObject.Properties['InventoryCargo']) { $Loadout | Add-Member -NotePropertyName InventoryCargo -NotePropertyValue @() -Force }
            if (-not $Loadout.PSObject.Properties['ConstructionPartsBuilt']) { $Loadout | Add-Member -NotePropertyName ConstructionPartsBuilt -NotePropertyValue @() -Force }
            if (-not $Loadout.PSObject.Properties['Sets']) { $Loadout | Add-Member -NotePropertyName Sets -NotePropertyValue @() -Force }
            return $Loadout
        }

        function script:Ensure-ExpansionLoadoutItemShape {
            param($Item)
            if ($null -eq $Item) { return (New-ExpansionLoadoutItemTemplate) }
            if (-not $Item.PSObject.Properties['ClassName']) { $Item | Add-Member -NotePropertyName ClassName -NotePropertyValue '' -Force }
            if (-not $Item.PSObject.Properties['Include']) { $Item | Add-Member -NotePropertyName Include -NotePropertyValue '' -Force }
            if (-not $Item.PSObject.Properties['Chance']) { $Item | Add-Member -NotePropertyName Chance -NotePropertyValue 1.0 -Force }
            if (-not $Item.PSObject.Properties['Quantity'] -or $null -eq $Item.Quantity) { $Item | Add-Member -NotePropertyName Quantity -NotePropertyValue ([pscustomobject]@{ Min = 0.0; Max = 0.0 }) -Force }
            if (-not $Item.Quantity.PSObject.Properties['Min']) { $Item.Quantity | Add-Member -NotePropertyName Min -NotePropertyValue 0.0 -Force }
            if (-not $Item.Quantity.PSObject.Properties['Max']) { $Item.Quantity | Add-Member -NotePropertyName Max -NotePropertyValue 0.0 -Force }
            foreach ($name in @('Health', 'InventoryAttachments', 'InventoryCargo', 'ConstructionPartsBuilt', 'Sets')) {
                if (-not $Item.PSObject.Properties[$name]) { $Item | Add-Member -NotePropertyName $name -NotePropertyValue @() -Force }
            }
            return $Item
        }

        function script:Get-ExpansionLoadoutFirstHealth {
            param($Item)
            if ($null -eq $Item -or -not $Item.PSObject.Properties['Health'] -or $null -eq $Item.Health) { return $null }
            $arr = @($Item.Health)
            if ($arr.Count -lt 1) { return $null }
            return $arr[0]
        }

        function script:Get-ExpansionLoadoutClassNamesRecursive {
            param($Node, $Bag)
            if ($null -eq $Bag) { $Bag = New-Object System.Collections.Generic.List[string] }
            if ($null -eq $Node) { return $Bag }

            if ($Node -is [System.Collections.IEnumerable] -and -not ($Node -is [string])) {
                foreach ($child in @($Node)) { [void](Get-ExpansionLoadoutClassNamesRecursive -Node $child -Bag $Bag) }
                return $Bag
            }

            if ($Node.PSObject -and $Node.PSObject.Properties['ClassName']) {
                $cn = [string]$Node.ClassName
                if (-not [string]::IsNullOrWhiteSpace($cn) -and -not $Bag.Contains($cn)) { $Bag.Add($cn) }
            }

            foreach ($propName in @('InventoryAttachments', 'InventoryCargo', 'ConstructionPartsBuilt', 'Sets')) {
                if ($Node.PSObject -and $Node.PSObject.Properties[$propName]) {
                    [void](Get-ExpansionLoadoutClassNamesRecursive -Node $Node.$propName -Bag $Bag)
                }
            }
            if ($Node.PSObject -and $Node.PSObject.Properties['Items']) {
                [void](Get-ExpansionLoadoutClassNamesRecursive -Node $Node.Items -Bag $Bag)
            }
            return $Bag
        }

        function script:Set-ExpansionLoadoutComboItems {
            param($Combo, $CurrentJson)
            if ($null -eq $Combo) { return }
            $currentText = [string]$Combo.Text
            $values = New-Object System.Collections.Generic.List[string]
            foreach ($preset in @(
                    'SurvivorBase', 'TShirt_Black', 'Jeans_Blue', 'AthleticShoes_Black', 'Apple', 'BandageDressing',
                    'Battery9V', 'PlateCarrierVest_Black', 'PlateCarrierHolster_Black', 'PlateCarrierPouches_Black',
                    'AKM', 'AK74', 'AK101', 'Mosin9130', 'SKS', 'FNX45', 'Glock19', 'Mag_AKM_30Rnd', 'Ammo_762x39'
                )) {
                if (-not $values.Contains($preset)) { $values.Add($preset) }
            }
            if ($CurrentJson) {
                $bag = Get-ExpansionLoadoutClassNamesRecursive -Node $CurrentJson -Bag (New-Object System.Collections.Generic.List[string])
                foreach ($cn in @($bag)) { if (-not $values.Contains([string]$cn)) { $values.Add([string]$cn) } }
            }
            $Combo.Items.Clear()
            foreach ($cn in ($values | Sort-Object)) { [void]$Combo.Items.Add($cn) }
            $Combo.Text = $currentText
        }

        function script:New-ExpansionLoadoutUniquePath {
            param([string]$Folder, [string]$BaseName)
            if ([string]::IsNullOrWhiteSpace($Folder)) { throw 'Loadout folder is not available.' }
            if (-not (Test-Path -LiteralPath $Folder)) { [void](New-Item -ItemType Directory -Force -Path $Folder) }
            $name = [System.IO.Path]::GetFileNameWithoutExtension($BaseName)
            $ext = [System.IO.Path]::GetExtension($BaseName)
            if ([string]::IsNullOrWhiteSpace($ext)) { $ext = '.json' }
            $candidate = Join-Path $Folder ($name + $ext)
            $index = 1
            while (Test-Path -LiteralPath $candidate) {
                $candidate = Join-Path $Folder ('{0}_{1}{2}' -f $name, $index, $ext)
                $index++
            }
            return $candidate
        }

        function script:Get-ExpansionLoadoutSafeFileName {
            param([string]$Text)
            $name = [string]$Text
            if ([string]::IsNullOrWhiteSpace($name)) { throw 'File name cannot be blank.' }
            $name = [System.IO.Path]::GetFileName($name.Trim())
            foreach ($bad in [System.IO.Path]::GetInvalidFileNameChars()) {
                if ($name.IndexOf($bad) -ge 0) { throw ('File name contains an invalid character: ' + $bad) }
            }
            if (-not $name.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) { $name += '.json' }
            return $name
        }

        function script:Add-ExpansionLoadoutGridColumns {
            param($Grid)
            $Grid.Columns.Clear()
            [void]$Grid.Columns.Add('ClassName', 'Class Name')
            [void]$Grid.Columns.Add('Chance', 'Chance')
            [void]$Grid.Columns.Add('Qty', 'Qty Min/Max')
            [void]$Grid.Columns.Add('Health', 'Health')
            [void]$Grid.Columns.Add('Nested', 'Nested')
            $Grid.Columns['ClassName'].Width = 210
            $Grid.Columns['Chance'].Width = 70
            $Grid.Columns['Qty'].Width = 90
            $Grid.Columns['Health'].Width = 105
            $Grid.Columns['Nested'].Width = 120
        }

        function script:Add-ExpansionLoadoutItemRow {
            param($Grid, $Item)
            $Item = Ensure-ExpansionLoadoutItemShape -Item $Item
            $h = Get-ExpansionLoadoutFirstHealth -Item $Item
            $healthText = ''
            if ($h) { $healthText = ('{0}/{1}' -f [string]$h.Min, [string]$h.Max) }
            $nested = 'A:{0} C:{1} S:{2}' -f @($Item.InventoryAttachments).Count, @($Item.InventoryCargo).Count, @($Item.Sets).Count
            $idx = $Grid.Rows.Add([string]$Item.ClassName, [string]$Item.Chance, ('{0}/{1}' -f [string]$Item.Quantity.Min, [string]$Item.Quantity.Max), $healthText, $nested)
            $Grid.Rows[$idx].Tag = $Item
        }

        # ---------------------------------------------------------------------
        # ---------------------------------------------------------------------
        $Page.Text = 'Loadouts'
        $Page.BackColor = $global:UGSM_ColorBackground
        $Page.ForeColor = $global:UGSM_ColorText
        $Page.AutoScroll = $false
        $Page.Controls.Clear()

        $root = New-Object System.Windows.Forms.Panel
        $root.Dock = 'Fill'
        $root.autoscroll = $false
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$Page.Controls.Add($root)

