        $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
        $topBar.Anchor = 'Top,Left,Right'
        $topBar.BackColor = $global:UGSM_ColorBackground
        $topBar.BorderStyle = 'FixedSingle'
