        $lstFiles.ForeColor = $global:UGSM_ColorText
        $lstFiles.BorderStyle = 'FixedSingle'
        [void]$leftPanel.Controls.Add($lstFiles)

        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 1000
        [void]$body.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 145
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 160
        $Tower3 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 395
        $Tower4 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 320
        $Tower5 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 280
        foreach ($tower in @($Tower1, $Tower2, $Tower3, $Tower4, $Tower5)) { [void]$editorPanel.Controls.Add($tower) }

        # Header / file tower
        $lblTitle = New-UGSMExpansionEditorLabel -Text 'Expansion Loadout Editor' -X 12 -Y 12 -Width 360
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblTitle)
        $lblDesc = New-UGSMExpansionEditorLabel -Text 'Structured loadout view for player, NPC, trader, and AI gear. Nested attachments/cargo are preserved; use the Files tab for raw edits.' -X 12 -Y 40 -Width 900
        [void]$Tower1.Controls.Add($lblDesc)
        $lblFile = New-UGSMExpansionEditorLabel -Text 'File' -X 12 -Y 78 -Width 120
        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 98 -Width $UGSM_ExpansionFileFieldWidth
        $txtFile.ReadOnly = $false
        $txtFile.TabStop = $true
        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X $UGSM_ExpansionPathFieldLeft -Y 78 -Width 120
        $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 98 -Width 400
        $txtPath.ReadOnly = $true
        [void]$Tower1.Controls.Add($lblFile); [void]$Tower1.Controls.Add($txtFile)
        [void]$Tower1.Controls.Add($lblPath); [void]$Tower1.Controls.Add($txtPath)

        # Root settings tower
        $lblRoot = New-UGSMExpansionEditorLabel -Text 'Loadout Root Settings' -X 12 -Y 12 -Width 260
        $lblRoot.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower2.Controls.Add($lblRoot)
        $lblClass = New-UGSMExpansionEditorLabel -Text 'ClassName' -X 12 -Y 48 -Width 80
        $cmbRootClass = New-UGSMExpansionEditorComboBox -X 12 -Y 68 -Width 210
        $cmbRootClass.DropDownStyle = 'DropDown'
        $lblInclude = New-UGSMExpansionEditorLabel -Text 'Include' -X 236 -Y 48 -Width 80
        $txtRootInclude = New-UGSMExpansionEditorTextBox -X 236 -Y 68 -Width 170
        $lblChance = New-UGSMExpansionEditorLabel -Text 'Chance' -X 420 -Y 48 -Width 80
        $numRootChance = New-Object System.Windows.Forms.NumericUpDown
        $numRootChance.Location = New-Object System.Drawing.Point(420, 68)
        $numRootChance.Size = New-Object System.Drawing.Size(90, 24)
        $numRootChance.DecimalPlaces = 6; $numRootChance.Minimum = 0; $numRootChance.Maximum = 1; $numRootChance.Increment = 0.05
        $numRootChance.BackColor = $global:UGSM_ColorInputBackground; $numRootChance.ForeColor = $global:UGSM_ColorText
        $lblQMin = New-UGSMExpansionEditorLabel -Text 'Qty Min' -X 524 -Y 48 -Width 80
        $numRootQMin = New-Object System.Windows.Forms.NumericUpDown
        $numRootQMin.Location = New-Object System.Drawing.Point(524, 68); $numRootQMin.Size = New-Object System.Drawing.Size(90, 24)
        $numRootQMin.DecimalPlaces = 6; $numRootQMin.Minimum = 0; $numRootQMin.Maximum = 1000000; $numRootQMin.BackColor = $global:UGSM_ColorInputBackground; $numRootQMin.ForeColor = $global:UGSM_ColorText
        $lblQMax = New-UGSMExpansionEditorLabel -Text 'Qty Max' -X 628 -Y 48 -Width 80
        $numRootQMax = New-Object System.Windows.Forms.NumericUpDown
        $numRootQMax.Location = New-Object System.Drawing.Point(628, 68); $numRootQMax.Size = New-Object System.Drawing.Size(90, 24)
        $numRootQMax.DecimalPlaces = 6; $numRootQMax.Minimum = 0; $numRootQMax.Maximum = 1000000; $numRootQMax.BackColor = $global:UGSM_ColorInputBackground; $numRootQMax.ForeColor = $global:UGSM_ColorText
        $lblCounts = New-UGSMExpansionEditorLabel -Text 'Slots: 0   Cargo: 0   Sets: 0' -X 12 -Y 112 -Width 460
        $lblCounts.ForeColor = $global:UGSM_ColorMutedText
        foreach ($c in @($lblClass, $cmbRootClass, $lblInclude, $txtRootInclude, $lblChance, $numRootChance, $lblQMin, $numRootQMin, $lblQMax, $numRootQMax, $lblCounts)) { [void]$Tower2.Controls.Add($c) }

        # Slots/items tower
        $lblSlots = New-UGSMExpansionEditorLabel -Text 'Equipment Slots and Slot Items' -X 12 -Y 12 -Width 300
        $lblSlots.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$Tower3.Controls.Add($lblSlots)
        $btnAddSlot = New-UGSMExpansionNewButton -Text 'Add Slot' -X 12 -Y 42 -Width 90
        $btnRemoveSlot = New-UGSMExpansionRemoveButton -Text 'Remove Slot' -X 112 -Y 42 -Width 100
        $lstSlots = New-Object System.Windows.Forms.ListBox
        $lstSlots.Location = New-Object System.Drawing.Point(12, 78)
        $lstSlots.Size = New-Object System.Drawing.Size(220, 285)
        $lstSlots.BackColor = $global:UGSM_ColorInputBackground; $lstSlots.ForeColor = $global:UGSM_ColorText; $lstSlots.BorderStyle = 'FixedSingle'
        $lblSlotName = New-UGSMExpansionEditorLabel -Text 'Selected Slot Name' -X 250 -Y 42 -Width 150
        $cmbSlotName = New-UGSMExpansionEditorComboBox -X 250 -Y 62 -Width 180
        $cmbSlotName.DropDownStyle = 'DropDown'
        [void]$cmbSlotName.Items.AddRange(@('Headgear', 'Mask', 'Body', 'Vest', 'Back', 'Hips', 'Legs', 'Feet', 'Gloves', 'Shoulder', 'Melee', 'Hands'))
        $btnApplySlotName = New-UGSMExpansionApplyButton -Text 'Apply Slot' -X 440 -Y 60 -Width 90
        $btnAddSlotItem = New-UGSMExpansionNewButton -Text 'Add Item' -X 548 -Y 60 -Width 90
        $btnRemoveSlotItem = New-UGSMExpansionRemoveButton -Text 'Remove Item' -X 648 -Y 60 -Width 110
        $gridSlotItems = New-Object System.Windows.Forms.DataGridView
        $gridSlotItems.Location = New-Object System.Drawing.Point(250, 96)
        $gridSlotItems.Size = New-Object System.Drawing.Size(520, 150)
        $gridSlotItems.AllowUserToAddRows = $false; $gridSlotItems.AllowUserToDeleteRows = $false; $gridSlotItems.ReadOnly = $true
        $gridSlotItems.SelectionMode = 'FullRowSelect'; $gridSlotItems.MultiSelect = $false; $gridSlotItems.RowHeadersVisible = $false
        $gridSlotItems.BackgroundColor = $global:UGSM_ColorInputBackground; $gridSlotItems.GridColor = $global:UGSM_ColorBorder; $gridSlotItems.ForeColor = $global:UGSM_ColorText
        Add-ExpansionLoadoutGridColumns -Grid $gridSlotItems
        foreach ($c in @($btnAddSlot, $btnRemoveSlot, $lstSlots, $lblSlotName, $cmbSlotName, $btnApplySlotName, $btnAddSlotItem, $btnRemoveSlotItem, $gridSlotItems)) { [void]$Tower3.Controls.Add($c) }

        # Shared selected item editor inside slot tower
        $lblItemEditor = New-UGSMExpansionEditorLabel -Text 'Selected Item Editor' -X 790 -Y 42 -Width 180
        $lblItemClass = New-UGSMExpansionEditorLabel -Text 'ClassName' -X 790 -Y 72 -Width 100
        $cmbItemClass = New-UGSMExpansionEditorComboBox -X 790 -Y 92 -Width 190
        $cmbItemClass.DropDownStyle = 'DropDown'
        $lblItemInclude = New-UGSMExpansionEditorLabel -Text 'Include' -X 790 -Y 122 -Width 100
        $txtItemInclude = New-UGSMExpansionEditorTextBox -X 790 -Y 142 -Width 190
        $lblItemChance = New-UGSMExpansionEditorLabel -Text 'Chance' -X 790 -Y 172 -Width 100
        $numItemChance = New-Object System.Windows.Forms.NumericUpDown
        $numItemChance.Location = New-Object System.Drawing.Point(790, 192); $numItemChance.Size = New-Object System.Drawing.Size(90, 24)
        $numItemChance.DecimalPlaces = 6; $numItemChance.Minimum = 0; $numItemChance.Maximum = 1; $numItemChance.Increment = 0.05; $numItemChance.BackColor = $global:UGSM_ColorInputBackground; $numItemChance.ForeColor = $global:UGSM_ColorText
        $lblItemQty = New-UGSMExpansionEditorLabel -Text 'Quantity Min / Max' -X 790 -Y 222 -Width 140
        $numItemQMin = New-Object System.Windows.Forms.NumericUpDown
        $numItemQMin.Location = New-Object System.Drawing.Point(790, 242); $numItemQMin.Size = New-Object System.Drawing.Size(90, 24)
        $numItemQMin.DecimalPlaces = 6; $numItemQMin.Minimum = 0; $numItemQMin.Maximum = 1000000; $numItemQMin.BackColor = $global:UGSM_ColorInputBackground; $numItemQMin.ForeColor = $global:UGSM_ColorText
        $numItemQMax = New-Object System.Windows.Forms.NumericUpDown
        $numItemQMax.Location = New-Object System.Drawing.Point(890, 242); $numItemQMax.Size = New-Object System.Drawing.Size(90, 24)
        $numItemQMax.DecimalPlaces = 6; $numItemQMax.Minimum = 0; $numItemQMax.Maximum = 1000000; $numItemQMax.BackColor = $global:UGSM_ColorInputBackground; $numItemQMax.ForeColor = $global:UGSM_ColorText
        $chkUseHealth = New-Object System.Windows.Forms.CheckBox
        $chkUseHealth.Text = 'Use Health'; $chkUseHealth.Location = New-Object System.Drawing.Point(790, 274); $chkUseHealth.Size = New-Object System.Drawing.Size(120, 22); $chkUseHealth.ForeColor = $global:UGSM_ColorText; $chkUseHealth.BackColor = [System.Drawing.Color]::Transparent
        $numHealthMin = New-Object System.Windows.Forms.NumericUpDown
        $numHealthMin.Location = New-Object System.Drawing.Point(790, 304); $numHealthMin.Size = New-Object System.Drawing.Size(90, 24)
        $numHealthMin.DecimalPlaces = 6; $numHealthMin.Minimum = 0; $numHealthMin.Maximum = 1; $numHealthMin.Increment = 0.05; $numHealthMin.BackColor = $global:UGSM_ColorInputBackground; $numHealthMin.ForeColor = $global:UGSM_ColorText
        $numHealthMax = New-Object System.Windows.Forms.NumericUpDown
        $numHealthMax.Location = New-Object System.Drawing.Point(890, 304); $numHealthMax.Size = New-Object System.Drawing.Size(90, 24)
        $numHealthMax.DecimalPlaces = 6; $numHealthMax.Minimum = 0; $numHealthMax.Maximum = 1; $numHealthMax.Increment = 0.05; $numHealthMax.Value = 1; $numHealthMax.BackColor = $global:UGSM_ColorInputBackground; $numHealthMax.ForeColor = $global:UGSM_ColorText
        $txtHealthZone = New-UGSMExpansionEditorTextBox -X 790 -Y 334 -Width 190
        $btnApplyItem = New-UGSMExpansionApplyButton -Text 'Apply Item' -X 790 -Y 360 -Width 100
        foreach ($c in @($lblItemEditor, $lblItemClass, $cmbItemClass, $lblItemInclude, $txtItemInclude, $lblItemChance, $numItemChance, $lblItemQty, $numItemQMin, $numItemQMax, $chkUseHealth, $numHealthMin, $numHealthMax, $txtHealthZone, $btnApplyItem)) { [void]$Tower3.Controls.Add($c) }

        # Cargo tower
        $lblCargo = New-UGSMExpansionEditorLabel -Text 'Root Inventory Cargo' -X 12 -Y 12 -Width 240
        $lblCargo.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        $btnAddCargo = New-UGSMExpansionNewButton -Text 'Add Cargo' -X 12 -Y 42 -Width 95
        $btnRemoveCargo = New-UGSMExpansionRemoveButton -Text 'Remove Cargo' -X 117 -Y 42 -Width 110
        $gridCargo = New-Object System.Windows.Forms.DataGridView
        $gridCargo.Location = New-Object System.Drawing.Point(12, 78); $gridCargo.Size = New-Object System.Drawing.Size(760, 210)
        $gridCargo.AllowUserToAddRows = $false; $gridCargo.AllowUserToDeleteRows = $false; $gridCargo.ReadOnly = $true; $gridCargo.SelectionMode = 'FullRowSelect'; $gridCargo.MultiSelect = $false; $gridCargo.RowHeadersVisible = $false
        $gridCargo.BackgroundColor = $global:UGSM_ColorInputBackground; $gridCargo.GridColor = $global:UGSM_ColorBorder; $gridCargo.ForeColor = $global:UGSM_ColorText
        Add-ExpansionLoadoutGridColumns -Grid $gridCargo
        foreach ($c in @($lblCargo, $btnAddCargo, $btnRemoveCargo, $gridCargo)) { [void]$Tower4.Controls.Add($c) }

        # Sets tower
        $lblSets = New-UGSMExpansionEditorLabel -Text 'Sets / Weighted Groups' -X 12 -Y 12 -Width 260
        $lblSets.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        $btnAddSet = New-UGSMExpansionNewButton -Text 'Add Set' -X 12 -Y 42 -Width 90
        $btnRemoveSet = New-UGSMExpansionRemoveButton -Text 'Remove Set' -X 112 -Y 42 -Width 105
        $gridSets = New-Object System.Windows.Forms.DataGridView
        $gridSets.Location = New-Object System.Drawing.Point(12, 78); $gridSets.Size = New-Object System.Drawing.Size(760, 170)
        $gridSets.AllowUserToAddRows = $false; $gridSets.AllowUserToDeleteRows = $false; $gridSets.ReadOnly = $true; $gridSets.SelectionMode = 'FullRowSelect'; $gridSets.MultiSelect = $false; $gridSets.RowHeadersVisible = $false
        $gridSets.BackgroundColor = $global:UGSM_ColorInputBackground; $gridSets.GridColor = $global:UGSM_ColorBorder; $gridSets.ForeColor = $global:UGSM_ColorText
        Add-ExpansionLoadoutGridColumns -Grid $gridSets
        $lblSetsNote = New-UGSMExpansionEditorLabel -Text 'Sets can contain nested weapons, magazines, batteries, and attachments. This pass edits the set row and preserves nested children.' -X 790 -Y 78 -Width 280
        $lblSetsNote.Height = 70
        $lblSetsNote.ForeColor = $global:UGSM_ColorMutedText
        foreach ($c in @($lblSets, $btnAddSet, $btnRemoveSet, $gridSets, $lblSetsNote)) { [void]$Tower5.Controls.Add($c) }

        $loadoutState = [pscustomobject]@{ Files = @(); Root = ''; CurrentPath = ''; CurrentJson = $null; SelectedEditMode = ''; SelectedItem = $null; SelectedSlot = $null }

        $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
        if (-not [string]::IsNullOrWhiteSpace([string]$paths.ProfileExpansionRoot)) {
            $loadoutState.Root = Join-Path ([string]$paths.ProfileExpansionRoot) 'Loadouts'
        }

        $refreshKnownCombos = {
            Set-ExpansionLoadoutComboItems -Combo $cmbRootClass -CurrentJson $loadoutState.CurrentJson
            Set-ExpansionLoadoutComboItems -Combo $cmbItemClass -CurrentJson $loadoutState.CurrentJson
        }.GetNewClosure()

        $setSelectedItemEditor = {
            param($Item, [string]$Mode)
            $loadoutState.SelectedItem = $Item
            $loadoutState.SelectedEditMode = $Mode
            if ($null -eq $Item) {
                $cmbItemClass.Text = ''; $txtItemInclude.Text = ''; $numItemChance.Value = 1; $numItemQMin.Value = 0; $numItemQMax.Value = 0; $chkUseHealth.Checked = $false; $numHealthMin.Value = 0; $numHealthMax.Value = 1; $txtHealthZone.Text = ''
                return
            }
            $Item = Ensure-ExpansionLoadoutItemShape -Item $Item
            $cmbItemClass.Text = [string]$Item.ClassName
            $txtItemInclude.Text = [string]$Item.Include
            $numItemChance.Value = [decimal]([Math]::Min(1, [Math]::Max(0, [double]$Item.Chance)))
            $numItemQMin.Value = [decimal]([Math]::Max(0, [double]$Item.Quantity.Min))
            $numItemQMax.Value = [decimal]([Math]::Max(0, [double]$Item.Quantity.Max))
            $h = Get-ExpansionLoadoutFirstHealth -Item $Item
            if ($h) {
                $chkUseHealth.Checked = $true
                $numHealthMin.Value = [decimal]([Math]::Min(1, [Math]::Max(0, [double]$h.Min)))
                $numHealthMax.Value = [decimal]([Math]::Min(1, [Math]::Max(0, [double]$h.Max)))
                $txtHealthZone.Text = [string]$h.Zone
            }
            else {
                $chkUseHealth.Checked = $false
                $numHealthMin.Value = 0
                $numHealthMax.Value = 1
                $txtHealthZone.Text = ''
            }
        }.GetNewClosure()

        $refreshCounts = {
            if ($loadoutState.CurrentJson) {
                $lblCounts.Text = 'Slots: {0}   Cargo: {1}   Sets: {2}' -f @($loadoutState.CurrentJson.InventoryAttachments).Count, @($loadoutState.CurrentJson.InventoryCargo).Count, @($loadoutState.CurrentJson.Sets).Count
            }
            else { $lblCounts.Text = 'Slots: 0   Cargo: 0   Sets: 0' }
        }.GetNewClosure()

        $refreshSlotItems = {
            $gridSlotItems.Rows.Clear()
            $loadoutState.SelectedSlot = $null
            if ($lstSlots.SelectedIndex -lt 0 -or -not $loadoutState.CurrentJson) { & $setSelectedItemEditor $null ''; return }
            $slot = @($loadoutState.CurrentJson.InventoryAttachments)[$lstSlots.SelectedIndex]
            $loadoutState.SelectedSlot = $slot
            $cmbSlotName.Text = [string]$slot.SlotName
            foreach ($item in @($slot.Items)) { Add-ExpansionLoadoutItemRow -Grid $gridSlotItems -Item $item }
            if ($gridSlotItems.Rows.Count -gt 0) { $gridSlotItems.Rows[0].Selected = $true; & $setSelectedItemEditor $gridSlotItems.Rows[0].Tag 'SlotItem' }
            else { & $setSelectedItemEditor $null '' }
        }.GetNewClosure()

        $refreshAllEditors = {
            $lstSlots.Items.Clear(); $gridSlotItems.Rows.Clear(); $gridCargo.Rows.Clear(); $gridSets.Rows.Clear(); & $setSelectedItemEditor $null ''
            if (-not $loadoutState.CurrentJson) { return }
            $json = Ensure-ExpansionLoadoutShape -Loadout $loadoutState.CurrentJson
            $loadoutState.CurrentJson = $json
            $cmbRootClass.Text = [string]$json.ClassName
            $txtRootInclude.Text = [string]$json.Include
            $numRootChance.Value = [decimal]([Math]::Min(1, [Math]::Max(0, [double]$json.Chance)))
            $numRootQMin.Value = [decimal]([Math]::Max(0, [double]$json.Quantity.Min))
            $numRootQMax.Value = [decimal]([Math]::Max(0, [double]$json.Quantity.Max))
            foreach ($slot in @($json.InventoryAttachments)) {
                if (-not $slot.PSObject.Properties['SlotName']) { $slot | Add-Member -NotePropertyName SlotName -NotePropertyValue '' -Force }
                if (-not $slot.PSObject.Properties['Items']) { $slot | Add-Member -NotePropertyName Items -NotePropertyValue @() -Force }
                [void]$lstSlots.Items.Add(('{0} ({1})' -f [string]$slot.SlotName, @($slot.Items).Count))
            }
            foreach ($item in @($json.InventoryCargo)) { Add-ExpansionLoadoutItemRow -Grid $gridCargo -Item $item }
            foreach ($item in @($json.Sets)) { Add-ExpansionLoadoutItemRow -Grid $gridSets -Item $item }
            & $refreshCounts
            & $refreshKnownCombos
            if ($lstSlots.Items.Count -gt 0) { $lstSlots.SelectedIndex = 0 } else { $cmbSlotName.Text = '' }
        }.GetNewClosure()

        $refreshFiles = {
            try {
                $lstFiles.Items.Clear()
                $loadoutState.Files = @()
                if ([string]::IsNullOrWhiteSpace([string]$loadoutState.Root)) { throw 'Loadout folder is not available.' }
                if (-not (Test-Path -LiteralPath ([string]$loadoutState.Root))) { [void](New-Item -ItemType Directory -Force -Path ([string]$loadoutState.Root)) }
                $files = @(Get-ChildItem -LiteralPath ([string]$loadoutState.Root) -Filter '*.json' -File -ErrorAction SilentlyContinue | Sort-Object Name)
                $loadoutState.Files = $files
                foreach ($f in $files) { [void]$lstFiles.Items.Add(('Profile: ' + $f.Name)) }
                if ($lstFiles.Items.Count -gt 0 -and $lstFiles.SelectedIndex -lt 0) { $lstFiles.SelectedIndex = 0 }
                if ($StatusLabel) { $StatusLabel.Text = 'Loadouts tab loaded. Files found: ' + $files.Count }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Refreshing Loadouts failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $loadSelectedFile = {
            try {
                if ($lstFiles.SelectedIndex -lt 0 -or $lstFiles.SelectedIndex -ge @($loadoutState.Files).Count) { return }
                $file = @($loadoutState.Files)[$lstFiles.SelectedIndex]
                $raw = Get-Content -LiteralPath ([string]$file.FullName) -Raw -ErrorAction Stop
                $json = $raw | ConvertFrom-Json -ErrorAction Stop
                $json = Ensure-ExpansionLoadoutShape -Loadout $json
                $loadoutState.CurrentPath = [string]$file.FullName
                $loadoutState.CurrentJson = $json
                $txtFile.Text = [string]$file.Name
                $txtPath.Text = [string]$file.FullName
                & $refreshAllEditors
                if ($StatusLabel) { $StatusLabel.Text = 'Loaded loadout: ' + [string]$file.Name }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Loading loadout failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        $applyRootFields = {
            if (-not $loadoutState.CurrentJson) { return }
            $json = $loadoutState.CurrentJson
            Set-LoadoutJsonValue -Object $json -Name 'ClassName' -Value ([string]$cmbRootClass.Text)
            Set-LoadoutJsonValue -Object $json -Name 'Include' -Value ([string]$txtRootInclude.Text)
            Set-LoadoutJsonValue -Object $json -Name 'Chance' -Value ([double]$numRootChance.Value)
            if (-not $json.PSObject.Properties['Quantity'] -or $null -eq $json.Quantity) { Set-LoadoutJsonValue -Object $json -Name 'Quantity' -Value ([pscustomobject]@{ Min = 0.0; Max = 0.0 }) }
            Set-LoadoutJsonValue -Object $json.Quantity -Name 'Min' -Value ([double]$numRootQMin.Value)
            Set-LoadoutJsonValue -Object $json.Quantity -Name 'Max' -Value ([double]$numRootQMax.Value)
        }.GetNewClosure()

        $applySelectedItem = {
            try {
                $item = $loadoutState.SelectedItem
                if ($null -eq $item) { return }
                $item = Ensure-ExpansionLoadoutItemShape -Item $item
                Set-LoadoutJsonValue -Object $item -Name 'ClassName' -Value ([string]$cmbItemClass.Text)
                Set-LoadoutJsonValue -Object $item -Name 'Include' -Value ([string]$txtItemInclude.Text)
                Set-LoadoutJsonValue -Object $item -Name 'Chance' -Value ([double]$numItemChance.Value)
                Set-LoadoutJsonValue -Object $item.Quantity -Name 'Min' -Value ([double]$numItemQMin.Value)
                Set-LoadoutJsonValue -Object $item.Quantity -Name 'Max' -Value ([double]$numItemQMax.Value)
                if ($chkUseHealth.Checked) {
                    Set-LoadoutJsonValue -Object $item -Name 'Health' -Value @([pscustomobject]@{ Min = [double]$numHealthMin.Value; Max = [double]$numHealthMax.Value; Zone = [string]$txtHealthZone.Text })
                }
                else { Set-LoadoutJsonValue -Object $item -Name 'Health' -Value @() }
                & $refreshAllEditors
                if ($StatusLabel) { $StatusLabel.Text = 'Applied loadout item.' }
            }
            catch { if ($StatusLabel) { $StatusLabel.Text = 'Applying loadout item failed: ' + $_.Exception.Message } }
        }.GetNewClosure()

        $saveCurrent = {
            try {
                if (-not $loadoutState.CurrentJson) { throw 'No loadout is selected.' }
                if ([string]::IsNullOrWhiteSpace([string]$loadoutState.CurrentPath)) { throw 'No loadout path is selected.' }
                & $applyRootFields
                $safeName = Get-ExpansionLoadoutSafeFileName -Text $txtFile.Text
                $folder = [System.IO.Path]::GetDirectoryName([string]$loadoutState.CurrentPath)
                $target = Join-Path $folder $safeName
                if (-not [string]::Equals($target, [string]$loadoutState.CurrentPath, [System.StringComparison]::OrdinalIgnoreCase)) {
                    if (Test-Path -LiteralPath $target) { throw ('A loadout file already exists with that name: ' + $safeName) }
                    Rename-Item -LiteralPath ([string]$loadoutState.CurrentPath) -NewName $safeName -ErrorAction Stop
                    $loadoutState.CurrentPath = $target
                    $txtPath.Text = $target
                }
                $jsonText = $loadoutState.CurrentJson | ConvertTo-Json -Depth 100
                [void](Backup-UGSMGameDayZFile -TargetPath ([string]$loadoutState.CurrentPath))
                [void](Write-UGSMGameDayZTextFileSafe -Path ([string]$loadoutState.CurrentPath) -Content $jsonText)
                $selectedPath = [string]$loadoutState.CurrentPath
                & $refreshFiles
                for ($idx = 0; $idx -lt @($loadoutState.Files).Count; $idx++) {
                    if ([string]::Equals([string]$loadoutState.Files[$idx].FullName, $selectedPath, [System.StringComparison]::OrdinalIgnoreCase)) { $lstFiles.SelectedIndex = $idx; break }
                }
                if ($StatusLabel) { $StatusLabel.Text = 'Saved loadout: ' + [System.IO.Path]::GetFileName($selectedPath) }
            }
            catch { if ($StatusLabel) { $StatusLabel.Text = 'Saving loadout failed: ' + $_.Exception.Message } }
        }.GetNewClosure()

        $newFile = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$loadoutState.Root)) { throw 'Loadout folder is not available.' }
                $target = New-ExpansionLoadoutUniquePath -Folder ([string]$loadoutState.Root) -BaseName 'NewLoadout.json'
                $data = New-ExpansionLoadoutTemplate
                $jsonText = $data | ConvertTo-Json -Depth 100
                [void](Write-UGSMGameDayZTextFileSafe -Path $target -Content $jsonText)
                & $refreshFiles
                for ($idx = 0; $idx -lt @($loadoutState.Files).Count; $idx++) {
                    if ([string]::Equals([string]$loadoutState.Files[$idx].FullName, [string]$target, [System.StringComparison]::OrdinalIgnoreCase)) { $lstFiles.SelectedIndex = $idx; break }
                }
                if ($StatusLabel) { $StatusLabel.Text = 'Created loadout: ' + [System.IO.Path]::GetFileName($target) }
            }
            catch { if ($StatusLabel) { $StatusLabel.Text = 'Creating loadout failed: ' + $_.Exception.Message } }
        }.GetNewClosure()

        # Event handlers
        $lstFiles.Add_SelectedIndexChanged($loadSelectedFile)
        $lstSlots.Add_SelectedIndexChanged($refreshSlotItems)
        $gridSlotItems.Add_SelectionChanged({ if ($gridSlotItems.CurrentRow) { & $setSelectedItemEditor $gridSlotItems.CurrentRow.Tag 'SlotItem' } }.GetNewClosure())
        $gridCargo.Add_SelectionChanged({ if ($gridCargo.CurrentRow) { & $setSelectedItemEditor $gridCargo.CurrentRow.Tag 'Cargo' } }.GetNewClosure())
        $gridSets.Add_SelectionChanged({ if ($gridSets.CurrentRow) { & $setSelectedItemEditor $gridSets.CurrentRow.Tag 'Set' } }.GetNewClosure())
        $btnApplyItem.Add_Click($applySelectedItem)
        $btnApplySlotName.Add_Click({
                if ($loadoutState.SelectedSlot) {
                    Set-LoadoutJsonValue -Object $loadoutState.SelectedSlot -Name 'SlotName' -Value ([string]$cmbSlotName.Text)
                    & $refreshAllEditors
                }
            }.GetNewClosure())
        $btnAddSlot.Add_Click({
                if (-not $loadoutState.CurrentJson) { return }
                $newSlot = [pscustomobject]@{ SlotName = 'NewSlot'; Items = @() }
                $loadoutState.CurrentJson.InventoryAttachments = @(@($loadoutState.CurrentJson.InventoryAttachments) + $newSlot)
                & $refreshAllEditors
                $lstSlots.SelectedIndex = $lstSlots.Items.Count - 1
            }.GetNewClosure())
        $btnRemoveSlot.Add_Click({
                if (-not $loadoutState.CurrentJson -or $lstSlots.SelectedIndex -lt 0) { return }
                $removeIndex = $lstSlots.SelectedIndex
                $next = New-Object System.Collections.ArrayList
                for ($idx = 0; $idx -lt @($loadoutState.CurrentJson.InventoryAttachments).Count; $idx++) { if ($idx -ne $removeIndex) { [void]$next.Add(@($loadoutState.CurrentJson.InventoryAttachments)[$idx]) } }
                $loadoutState.CurrentJson.InventoryAttachments = @($next)
                & $refreshAllEditors
            }.GetNewClosure())
        $btnAddSlotItem.Add_Click({
                if (-not $loadoutState.SelectedSlot) { return }
                $item = New-ExpansionLoadoutItemTemplate -ClassName 'NewClassName'
                $loadoutState.SelectedSlot.Items = @(@($loadoutState.SelectedSlot.Items) + $item)
                & $refreshSlotItems
            }.GetNewClosure())
        $btnRemoveSlotItem.Add_Click({
                if (-not $loadoutState.SelectedSlot -or -not $gridSlotItems.CurrentRow) { return }
                $item = $gridSlotItems.CurrentRow.Tag
                $next = @(@($loadoutState.SelectedSlot.Items) | Where-Object { -not [object]::ReferenceEquals($_, $item) })
                $loadoutState.SelectedSlot.Items = $next
                & $refreshSlotItems
            }.GetNewClosure())
        $btnAddCargo.Add_Click({
                if (-not $loadoutState.CurrentJson) { return }
                $loadoutState.CurrentJson.InventoryCargo = @(@($loadoutState.CurrentJson.InventoryCargo) + (New-ExpansionLoadoutItemTemplate -ClassName 'NewCargoClass'))
                & $refreshAllEditors
            }.GetNewClosure())
        $btnRemoveCargo.Add_Click({
                if (-not $loadoutState.CurrentJson -or -not $gridCargo.CurrentRow) { return }
                $item = $gridCargo.CurrentRow.Tag
                $loadoutState.CurrentJson.InventoryCargo = @(@($loadoutState.CurrentJson.InventoryCargo) | Where-Object { -not [object]::ReferenceEquals($_, $item) })
                & $refreshAllEditors
            }.GetNewClosure())
        $btnAddSet.Add_Click({
                if (-not $loadoutState.CurrentJson) { return }
                $loadoutState.CurrentJson.Sets = @(@($loadoutState.CurrentJson.Sets) + (New-ExpansionLoadoutItemTemplate -ClassName 'NEW_SET'))
                & $refreshAllEditors
            }.GetNewClosure())
        $btnRemoveSet.Add_Click({
                if (-not $loadoutState.CurrentJson -or -not $gridSets.CurrentRow) { return }
                $item = $gridSets.CurrentRow.Tag
                $loadoutState.CurrentJson.Sets = @(@($loadoutState.CurrentJson.Sets) | Where-Object { -not [object]::ReferenceEquals($_, $item) })
                & $refreshAllEditors
            }.GetNewClosure())
        $btnNew.Add_Click($newFile)
        $btnRefresh.Add_Click($refreshFiles)
        $btnSaveCurrent.Add_Click($saveCurrent)
        $layoutLoadouts = {
            Set-UGSMExpansionLayout `
                -Page $Page `
                -Root $root `
                -Shell $shell `
                -TopBar $topBar `
                -Body $body `
                -LeftPanel $leftPanel `
                -EditorPanel $editorPanel `
                -Tower1 $Tower1 `
                -Tower2 $Tower2 `
                -Tower3 $Tower3 `
                -Tower4 $Tower4 `
                -Tower5 $Tower5 `
                -LstItems $lstFiles `
                -TxtPath $txtPath `
                -BtnNew $btnNew `
                -BtnRefresh $btnRefresh `
                -BtnSaveCurrent $btnSaveCurrent `
        }.GetNewClosure()

        & $layoutLoadouts
        $Page.Add_SizeChanged($layoutLoadouts)
        $Page.Add_VisibleChanged($layoutLoadouts)
        & $refreshFiles
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) { $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace }
        Show-UGSMExpansionTabMessage -Page $Page -Title 'Loadouts tab failed' -Message $errorText -TitleColor '#FFB4B4' -ErrorAction SilentlyContinue
        if ($StatusLabel) { $StatusLabel.Text = 'Loadouts tab failed: ' + $_.Exception.Message }
    }
}

function New-UGSMGameDayZExpansionMarketCategoryData {
    param(
        [string]$DisplayName = 'New Market Category',
        [string]$Icon = 'Deliver',
        [string]$Color = 'FBFCFEFF',
        [double]$InitStockPercent = 75.0,
        [int]$IsExchange = 0,
        [object[]]$Items = @()
    )

    return [ordered]@{
        m_Version        = 12
        DisplayName      = [string]$DisplayName
        Icon             = [string]$Icon
        Color            = [string]$Color
        IsExchange       = [int]$IsExchange
        InitStockPercent = [double]$InitStockPercent
        Items            = @($Items)
    }
}

function Read-UGSMGameDayZExpansionMarketCategoryFile {
    param(
        [Parameter(Mandatory)][string]$Path
    )

    $raw = Read-UGSMGameDayZTextFileSafe -Path $Path
    $data = $raw | ConvertFrom-Json

    if ($null -eq $data) {
        $data = New-UGSMGameDayZExpansionMarketCategoryData
    }

    if (-not ($data.PSObject.Properties.Name -contains 'Items') -or $null -eq $data.Items) {
        $data | Add-Member -NotePropertyName Items -NotePropertyValue @() -Force
    }

    return $data
}

function Write-UGSMGameDayZExpansionMarketCategoryFile {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)]$Data
    )

    $jsonText = ($Data | ConvertTo-Json -Depth 100)
    [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content $jsonText)
    return $Path
}

function Convert-UGSMDayZExpansionMarketGridRowToItem {
    param(
        [Parameter(Mandatory)]$Row
    )

    if ($null -eq $Row -or $Row.IsNewRow) { return $null }

    $className = [string]$Row.Cells['ClassName'].Value
    if ([string]::IsNullOrWhiteSpace($className)) { return $null }

    $spawnAttachments = @()
    $spawnText = [string]$Row.Cells['SpawnAttachments'].Value
    if (-not [string]::IsNullOrWhiteSpace($spawnText)) {
        $spawnAttachments = @(
            $spawnText -split ',' |
            ForEach-Object { $_.Trim() } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        )
    }

    $variants = @()
    $variantText = [string]$Row.Cells['Variants'].Value
    if (-not [string]::IsNullOrWhiteSpace($variantText)) {
        $variants = @(
            $variantText -split ',' |
            ForEach-Object { $_.Trim() } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        )
    }

    return [ordered]@{
        ClassName         = $className
        MaxPriceThreshold = [int]$Row.Cells['MaxPriceThreshold'].Value
        MinPriceThreshold = [int]$Row.Cells['MinPriceThreshold'].Value
        SellPricePercent  = [double]$Row.Cells['SellPricePercent'].Value
        MaxStockThreshold = [int]$Row.Cells['MaxStockThreshold'].Value
        MinStockThreshold = [int]$Row.Cells['MinStockThreshold'].Value
        QuantityPercent   = [int]$Row.Cells['QuantityPercent'].Value
        SpawnAttachments  = @($spawnAttachments)
        Variants          = @($variants)
    }
}

function Get-UGSMDayZExpansionSafeCategoryFileName {
    param(
        [Parameter(Mandatory)][string]$Name
    )

    $value = [string]$Name
    $value = $value -replace '\.json$', ''
    $value = $value -replace '[^A-Za-z0-9_\- ]', ''
    $value = $value.Trim()
    $value = $value -replace '\s+', '_'

    if ([string]::IsNullOrWhiteSpace($value)) {
        throw 'Category name is empty after sanitizing.'
    }

    return ($value + '.json')
}

