    $chkIsExchange = New-Object System.Windows.Forms.CheckBox
    $chkIsExchange.Text = 'Is Exchange'
    $chkIsExchange.ForeColor = $global:UGSM_ColorText
    $chkIsExchange.BackColor = [System.Drawing.Color]::Transparent
    $chkIsExchange.Location = New-Object System.Drawing.Point(140, 178)
    $chkIsExchange.AutoSize = $true
    [void]$detailsInner.Controls.Add($chkIsExchange)

    $txtInfo = New-Object System.Windows.Forms.TextBox
    $txtInfo.Location = New-Object System.Drawing.Point(0, 220)
    $txtInfo.Size = New-Object System.Drawing.Size(280, 220)
    $txtInfo.Multiline = $true
    $txtInfo.ReadOnly = $true
    $txtInfo.ScrollBars = 'Vertical'
    $txtInfo.BorderStyle = 'FixedSingle'
    $txtInfo.BackColor = $global:UGSM_ColorInputBackground
    $txtInfo.ForeColor = $global:UGSM_ColorText
    $txtInfo.Text = @"
Market tab notes

- Category files come from profiles\ExpansionMod\Market
- Each file defines a market category
- Items[] are the actual sellable classnames
- Variants and SpawnAttachments stay raw text for pass one
- Modded items can be added manually by classname
"@
    [void]$detailsInner.Controls.Add($txtInfo)

    $marketState = [ordered]@{
        Files       = @()
        CurrentPath = ''
        CurrentData = $null
    }

    $getMarketRoot = {
        $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
        return (Join-Path ([string]$paths.ProfileExpansionRoot) 'Market')
    }.GetNewClosure()

    $refreshMoveTargets = {
        try {
            $currentName = ''
            if (-not [string]::IsNullOrWhiteSpace([string]$cmbMoveTarget.Text)) {
                $currentName = [string]$cmbMoveTarget.Text
            }

            $cmbMoveTarget.Items.Clear()
            foreach ($file in @($marketState.Files)) {
                $name = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                [void]$cmbMoveTarget.Items.Add($name)
            }

            if (-not [string]::IsNullOrWhiteSpace($currentName)) {
                $existingIndex = $cmbMoveTarget.Items.IndexOf($currentName)
                if ($existingIndex -ge 0) {
                    $cmbMoveTarget.SelectedIndex = $existingIndex
                }
            }
        }
        catch { }
    }.GetNewClosure()

    $getOrCreateMoveTargetPath = {
        $root = & $getMarketRoot
        if (-not (Test-Path -LiteralPath $root -PathType Container)) {
            [void][System.IO.Directory]::CreateDirectory($root)
        }

        $newCategoryText = [string]$txtNewMoveCategory.Text
        if (-not [string]::IsNullOrWhiteSpace($newCategoryText)) {
            $fileName = Get-UGSMDayZExpansionSafeCategoryFileName -Name $newCategoryText
            $targetPath = Join-Path $root $fileName

            if (-not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                $newData = New-UGSMGameDayZExpansionMarketCategoryData -DisplayName $newCategoryText
                [void](Write-UGSMGameDayZExpansionMarketCategoryFile -Path $targetPath -Data $newData)
            }

            return $targetPath
        }

        if ([string]::IsNullOrWhiteSpace([string]$cmbMoveTarget.Text)) {
            throw 'Select an existing category or enter a new category name.'
        }

        $existingFileName = ([string]$cmbMoveTarget.Text + '.json')
        return (Join-Path $root $existingFileName)
    }.GetNewClosure()

    $moveRowsToCategory = {
        param(
            [Parameter(Mandatory)][object[]]$RowsToMove
        )

        try {
            if ([string]::IsNullOrWhiteSpace([string]$marketState.CurrentPath)) {
                throw 'No source market category is selected.'
            }

            $sourcePath = [string]$marketState.CurrentPath
            $targetPath = & $getOrCreateMoveTargetPath

            if ([string]::Equals($sourcePath, $targetPath, [System.StringComparison]::OrdinalIgnoreCase)) {
                throw 'Source and target category are the same.'
            }

            $sourceData = Read-UGSMGameDayZExpansionMarketCategoryFile -Path $sourcePath
            $targetData = Read-UGSMGameDayZExpansionMarketCategoryFile -Path $targetPath

            $moveClassNames = @()
            $itemsToMove = New-Object System.Collections.ArrayList

            foreach ($row in @($RowsToMove)) {
                $item = Convert-UGSMDayZExpansionMarketGridRowToItem -Row $row
                if ($null -eq $item) { continue }

                $className = [string]$item.ClassName
                if ([string]::IsNullOrWhiteSpace($className)) { continue }

                if ($moveClassNames -icontains $className) { continue }
                $moveClassNames += $className
                [void]$itemsToMove.Add($item)
            }

            if (@($moveClassNames).Count -eq 0) {
                throw 'No valid items were selected to move.'
            }

            $targetExisting = @{}
            foreach ($targetItem in @($targetData.Items)) {
                $targetClass = [string]$targetItem.ClassName
                if (-not [string]::IsNullOrWhiteSpace($targetClass)) {
                    $targetExisting[$targetClass.ToLowerInvariant()] = $true
                }
            }

            foreach ($item in @($itemsToMove)) {
                $classKey = ([string]$item.ClassName).ToLowerInvariant()
                if (-not $targetExisting.ContainsKey($classKey)) {
                    $targetData.Items += $item
                    $targetExisting[$classKey] = $true
                }
            }

            $remainingItems = New-Object System.Collections.ArrayList
            foreach ($sourceItem in @($sourceData.Items)) {
                $sourceClass = [string]$sourceItem.ClassName
                if ([string]::IsNullOrWhiteSpace($sourceClass)) { continue }
                if ($moveClassNames -icontains $sourceClass) { continue }
                [void]$remainingItems.Add($sourceItem)
            }
            $sourceData.Items = @($remainingItems)

            [void](Backup-UGSMGameDayZFile -TargetPath $sourcePath)
            if (Test-Path -LiteralPath $targetPath -PathType Leaf) {
                [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
            }

            [void](Write-UGSMGameDayZExpansionMarketCategoryFile -Path $sourcePath -Data $sourceData)
            [void](Write-UGSMGameDayZExpansionMarketCategoryFile -Path $targetPath -Data $targetData)

            $targetName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)

            & $refreshMarketFiles
            & $refreshMoveTargets

            $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($sourcePath)
            $index = $cmbCategories.Items.IndexOf($selectedName)
            if ($index -ge 0) {
                $cmbCategories.SelectedIndex = $index
            }

            $targetIndex = $cmbMoveTarget.Items.IndexOf($targetName)
            if ($targetIndex -ge 0) {
                $cmbMoveTarget.SelectedIndex = $targetIndex
            }

            $txtNewMoveCategory.Text = ''

            if ($StatusLabel) {
                $StatusLabel.Text = ('Moved ' + [string]@($moveClassNames).Count + ' item(s) to ' + $targetName + '.')
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Moving Market items failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $refreshMarketFiles = {
        try {
            $root = & $getMarketRoot
            $marketState.Files = @()

            $cmbCategories.Items.Clear()
            $grid.Rows.Clear()

            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                if ($StatusLabel) { $StatusLabel.Text = 'Market folder was not found for this instance.' }
                return
            }

            $marketState.Files = @(
                Get-ChildItem -LiteralPath $root -File -Filter '*.json' -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch '\.bak\.json$' } |
                Sort-Object Name
            )

            foreach ($file in $marketState.Files) {
                [void]$cmbCategories.Items.Add([System.IO.Path]::GetFileNameWithoutExtension($file.Name))
            }

            if ($cmbCategories.Items.Count -gt 0) {
                $cmbCategories.SelectedIndex = 0
            }

            & $refreshMoveTargets

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded ' + [string]$marketState.Files.Count + ' market file(s).')
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Refreshing Market files failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $loadSelectedCategory = {
        try {
            $grid.Rows.Clear()
            $marketState.CurrentPath = ''
            $marketState.CurrentData = $null

            if ($cmbCategories.SelectedIndex -lt 0) { return }
            if ($cmbCategories.SelectedIndex -ge $marketState.Files.Count) { return }

            $file = $marketState.Files[$cmbCategories.SelectedIndex]
            $raw = Read-UGSMGameDayZTextFileSafe -Path $file.FullName
            $data = $raw | ConvertFrom-Json

            $marketState.CurrentPath = [string]$file.FullName
            $marketState.CurrentData = $data

            $txtFileName.Text = [System.IO.Path]::GetFileNameWithoutExtension($file.Name)

            $txtDisplayName.Text = [string]$data.DisplayName
            $cmbIcon.Text = [string]$data.Icon
            $txtColor.Text = [string]$data.Color
            $txtInitStock.Text = [string]$data.InitStockPercent
            $chkIsExchange.Checked = ([int]$data.IsExchange -ne 0)



            foreach ($item in @($data.Items)) {
                $spawnAttachments = ''
                if ($item.SpawnAttachments) {
                    $spawnAttachments = [string]::Join(', ', @($item.SpawnAttachments))
                }

                $variants = ''
                if ($item.Variants) {
                    $variants = [string]::Join(', ', @($item.Variants))
                }

                [void]$grid.Rows.Add(
                    [string]$item.ClassName,
                    [string]$item.MaxPriceThreshold,
                    [string]$item.MinPriceThreshold,
                    [string]$item.SellPricePercent,
                    [string]$item.MaxStockThreshold,
                    [string]$item.MinStockThreshold,
                    [string]$item.QuantityPercent,
                    $spawnAttachments,
                    $variants
                )
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded Market category: ' + [System.IO.Path]::GetFileName($file.FullName))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Loading Market category failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $saveCategory = {
        try {
            if ([string]::IsNullOrWhiteSpace([string]$marketState.CurrentPath)) {
                throw 'No market category is selected.'
            }

            $fileName = [string]$txtFileName.Text
            if ([string]::IsNullOrWhiteSpace($fileName)) {
                throw 'File Name is required.'
            }

            if ($fileName -match '\.bak\.json$') {
                throw 'File Name cannot end with .bak.json'
            }

            if (-not $fileName.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) {
                $fileName += '.json'
            }

            $root = & $getMarketRoot
            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                [void][System.IO.Directory]::CreateDirectory($root)
            }

            $targetPath = Join-Path $root $fileName
            $oldPath = [string]$marketState.CurrentPath

            $items = New-Object System.Collections.ArrayList
            foreach ($row in @($grid.Rows)) {
                if ($row.IsNewRow) { continue }

                $className = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($className)) { continue }

                $spawnAttachments = @()
                $spawnText = [string]$row.Cells['SpawnAttachments'].Value
                if (-not [string]::IsNullOrWhiteSpace($spawnText)) {
                    $spawnAttachments = @(
                        $spawnText -split ',' |
                        ForEach-Object { $_.Trim() } |
                        Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                    )
                }

                $variants = @()
                $variantText = [string]$row.Cells['Variants'].Value
                if (-not [string]::IsNullOrWhiteSpace($variantText)) {
                    $variants = @(
                        $variantText -split ',' |
                        ForEach-Object { $_.Trim() } |
                        Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                    )
                }

                [void]$items.Add([ordered]@{
                        ClassName         = $className
                        MaxPriceThreshold = [int]$row.Cells['MaxPriceThreshold'].Value
                        MinPriceThreshold = [int]$row.Cells['MinPriceThreshold'].Value
                        SellPricePercent  = [double]$row.Cells['SellPricePercent'].Value
                        MaxStockThreshold = [int]$row.Cells['MaxStockThreshold'].Value
                        MinStockThreshold = [int]$row.Cells['MinStockThreshold'].Value
                        QuantityPercent   = [int]$row.Cells['QuantityPercent'].Value
                        SpawnAttachments  = @($spawnAttachments)
                        Variants          = @($variants)
                    })
            }

            $data = [ordered]@{
                m_Version        = 12
                DisplayName      = [string]$txtDisplayName.Text
                Icon             = [string]$cmbIcon.Text
                Color            = [string]$txtColor.Text
                IsExchange       = $(if ($chkIsExchange.Checked) { 1 } else { 0 })
                InitStockPercent = [double]$txtInitStock.Text
                Items            = @($items)
            }

            $jsonText = ($data | ConvertTo-Json -Depth 100)

            if (-not [string]::IsNullOrWhiteSpace($oldPath) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
                [void](Backup-UGSMGameDayZFile -TargetPath $oldPath)
            }

            [void](Write-UGSMGameDayZTextFileSafe -Path $targetPath -Content $jsonText)

            if (
                -not [string]::IsNullOrWhiteSpace($oldPath) -and
                ($oldPath -ne $targetPath) -and
                (Test-Path -LiteralPath $oldPath -PathType Leaf)
            ) {
                Remove-Item -LiteralPath $oldPath -Force -ErrorAction Stop
            }

            $marketState.CurrentPath = $targetPath

            & $refreshMarketFiles

            $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
            $index = $cmbCategories.Items.IndexOf($selectedName)
            if ($index -ge 0) {
                $cmbCategories.SelectedIndex = $index
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Saved Market category: ' + [System.IO.Path]::GetFileName($targetPath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Saving Market category failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $newCategory = {
        try {
            $root = & $getMarketRoot
            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                [void][System.IO.Directory]::CreateDirectory($root)
            }

            $baseName = 'NewMarketCategory'
            $filePath = Join-Path $root ($baseName + '.json')
            if (Test-Path -LiteralPath $filePath -PathType Leaf) {
                for ($i = 1; $i -le 999; $i++) {
                    $candidate = Join-Path $root ('{0}_{1:D2}.json' -f $baseName, $i)
                    if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                        $filePath = $candidate
                        break
                    }
                }
            }

            $data = [ordered]@{
                m_Version        = 12
                DisplayName      = 'New Market Category'
                Icon             = 'Deliver'
                Color            = 'FBFCFEFF'
                IsExchange       = 0
                InitStockPercent = 75.0
                Items            = @()
            }

            $jsonText = ($data | ConvertTo-Json -Depth 100)
            [void](Write-UGSMGameDayZTextFileSafe -Path $filePath -Content $jsonText)

            & $refreshMarketFiles

            $newName = [System.IO.Path]::GetFileNameWithoutExtension($filePath)
            $index = $cmbCategories.Items.IndexOf($newName)
            if ($index -ge 0) {
                $cmbCategories.SelectedIndex = $index
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Created Market category: ' + [System.IO.Path]::GetFileName($filePath))
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Creating Market category failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $deleteCategory = {
        try {
            if ([string]::IsNullOrWhiteSpace([string]$marketState.CurrentPath)) {
                throw 'No market category is selected.'
            }

            $fileName = [System.IO.Path]::GetFileName($marketState.CurrentPath)
            $result = [System.Windows.Forms.MessageBox]::Show(
                ('Delete market category file "' + $fileName + '"?'),
                'Delete Market Category',
                [System.Windows.Forms.MessageBoxButtons]::YesNo,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            )

            if ($result -ne [System.Windows.Forms.DialogResult]::Yes) {
                return
            }

            [void](Backup-UGSMGameDayZFile -TargetPath $marketState.CurrentPath)
            Remove-Item -LiteralPath $marketState.CurrentPath -Force -ErrorAction Stop

            & $refreshMarketFiles

            if ($StatusLabel) {
                $StatusLabel.Text = ('Deleted Market category: ' + $fileName)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Deleting Market category failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $pickColor = {
        try {
            $dialog = New-Object System.Windows.Forms.ColorDialog
            $dialog.FullOpen = $true

            $current = [string]$txtColor.Text
            if (-not [string]::IsNullOrWhiteSpace($current) -and $current.Length -eq 8) {
                try {
                    $r = [Convert]::ToInt32($current.Substring(0, 2), 16)
                    $g = [Convert]::ToInt32($current.Substring(2, 2), 16)
                    $b = [Convert]::ToInt32($current.Substring(4, 2), 16)
                    $a = [Convert]::ToInt32($current.Substring(6, 2), 16)
                    $dialog.Color = [System.Drawing.Color]::FromArgb($a, $r, $g, $b)
                }
                catch { }
            }

            if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $c = $dialog.Color
                $txtColor.Text = ('{0:X2}{1:X2}{2:X2}{3:X2}' -f $c.R, $c.G, $c.B, $c.A)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Picking color failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $syncMarketFromTypes = {
        try {
            $typesPath = ''
            if (Get-Command -Name Resolve-UGSMGameDayZTypesXmlPath -ErrorAction SilentlyContinue) {
                $typesPath = Resolve-UGSMGameDayZTypesXmlPath -Instance $Instance
            }

            if ([string]::IsNullOrWhiteSpace($typesPath) -or -not (Test-Path -LiteralPath $typesPath -PathType Leaf)) {
                try {
                    $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance
                    foreach ($candidate in @(
                            $paths.RuntimeTypesPath,
                            $(if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeDbPath)) { Join-Path ([string]$paths.RuntimeDbPath) 'types.xml' }),
                            $(if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeMissionPath)) { Join-Path ([string]$paths.RuntimeMissionPath) 'db\types.xml' }),
                            $(if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionFolderPath)) { Join-Path ([string]$paths.MissionFolderPath) 'db\types.xml' })
                        )) {
                        if (-not [string]::IsNullOrWhiteSpace([string]$candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                            $typesPath = [string]$candidate
                            break
                        }
                    }
                }
                catch { }
            }

            if ([string]::IsNullOrWhiteSpace($typesPath) -or -not (Test-Path -LiteralPath $typesPath -PathType Leaf)) {
                throw 'types.xml could not be resolved for this instance.'
            }

            if (-not (Get-Command -Name Add-UGSMGameDayZMissingTypesToExpansionMarket -ErrorAction SilentlyContinue)) {
                throw 'Expansion Market types sync function is not loaded.'
            }

            $report = Add-UGSMGameDayZMissingTypesToExpansionMarket `
                -Instance $Instance `
                -TypesPath $typesPath `
                -TargetFileName 'UGSM_Generated.json' `
                -SkipNamePattern '^(ZmbF_|ZmbM_|Zmb|StaticObj_|Land_|Animal_|Wreck_|Fireplace|Bonfire|BanditAI_)'

            & $refreshMarketFiles

            if (-not [string]::IsNullOrWhiteSpace([string]$report.TargetPath)) {
                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension([string]$report.TargetPath)
                $index = $cmbCategories.Items.IndexOf($selectedName)
                if ($index -ge 0) { $cmbCategories.SelectedIndex = $index }
            }

            if ($StatusLabel) {
                $StatusLabel.Text = "Expansion Market sync complete: $($report.ItemsAdded) added, $($report.ExistingItemsSkipped) existing/skipped, $($report.ItemsSkippedByPattern) skipped by filter; stock updated from nominal."
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Expansion Market sync from types.xml failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $addItem = {
        [void]$grid.Rows.Add(
            '',
            '100',
            '50',
            '-1',
            '100',
            '1',
            '-1',
            '',
            ''
        )
    }.GetNewClosure()

    $removeItem = {
        $selected = @($grid.SelectedRows | Sort-Object Index -Descending)
        if (@($selected).Count -eq 0) { return }

        foreach ($row in $selected) {
            if (-not $row.IsNewRow) {
                $grid.Rows.Remove($row)
            }
        }
    }.GetNewClosure()

    $moveSelectedItems = {
        $selected = @($grid.SelectedRows | Sort-Object Index)
        if (@($selected).Count -eq 0) {
            throw 'Select one or more items to move.'
        }

        & $moveRowsToCategory -RowsToMove $selected
    }.GetNewClosure()

    $moveAllItems = {
        $allRows = @(
            $grid.Rows |
            Where-Object { -not $_.IsNewRow } |
            Sort-Object Index
        )

        if (@($allRows).Count -eq 0) {
            throw 'There are no items to move.'
        }

        & $moveRowsToCategory -RowsToMove $allRows
    }.GetNewClosure()

    $btnRefreshMarket.Add_Click($refreshMarketFiles)
    $cmbCategories.Add_SelectedIndexChanged($loadSelectedCategory)
    $btnSaveCategory.Add_Click($saveCategory)
    $btnNewCategory.Add_Click($newCategory)
    $btnDeleteCategory.Add_Click($deleteCategory)
    $btnSyncMarket.Add_Click($syncMarketFromTypes)
    $btnAddItem.Add_Click($addItem)
    $btnRemoveItem.Add_Click($removeItem)
    $btnPickColor.Add_Click($pickColor)

    $btnMoveSelected.Add_Click({
            try { & $moveSelectedItems } catch { if ($StatusLabel) { $StatusLabel.Text = 'Move Selected failed: ' + $_.Exception.Message } }
        }.GetNewClosure())

    $btnMoveAll.Add_Click({
            try { & $moveAllItems } catch { if ($StatusLabel) { $StatusLabel.Text = 'Move All failed: ' + $_.Exception.Message } }
        }.GetNewClosure())

    & $refreshMarketFiles
}

function New-DayZExpansionQuestsTab {
    param($Page, $State, $Instance, $StatusLabel)
    New-DayZExpansionGenericJsonModuleTab -Page $Page -State $State -Instance $Instance -StatusLabel $StatusLabel -ModuleKey 'Quests' -ModuleTitle 'Quests'
}
function New-UGSMExpansionSettingsEditorShell {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)][string]$Title,
        [Parameter(Mandatory)][string]$Description,
        [Parameter(Mandatory)][string]$FilePath,
        [int[]]$TowerHeights = @(320),
        [int]$HeaderHeight = 130
    )

    $HostPanel.Controls.Clear()
    $HostPanel.BackColor = $global:UGSM_ColorBackground

    $root = New-Object System.Windows.Forms.Panel
    $root.Dock = 'Fill'
    $root.AutoScroll = $false
    $root.BackColor = $global:UGSM_ColorBackground
    [void]$HostPanel.Controls.Add($root)

    $shell = New-Object System.Windows.Forms.Panel
    $shell.Dock = 'Fill'
    $shell.AutoScroll = $false
    $shell.BackColor = $global:UGSM_ColorBackground
    [void]$root.Controls.Add($shell)

    $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 600
    $editorPanel.Dock = 'Fill'
    $editorPanel.AutoScroll = $true
    $editorPanel.BackColor = $global:UGSM_ColorBackground
    [void]$shell.Controls.Add($editorPanel)

    $contentHost = New-Object System.Windows.Forms.Panel
    $contentHost.Location = New-Object System.Drawing.Point(0, 0)
    $contentHost.Size = New-Object System.Drawing.Size([Math]::Max(980, $editorPanel.ClientSize.Width - 18), 600)
    $contentHost.Anchor = 'Top,Left,Right'
    $contentHost.BackColor = $global:UGSM_ColorBackground
    [void]$editorPanel.Controls.Add($contentHost)

    $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $HeaderHeight
    [void]$contentHost.Controls.Add($Tower1)

    $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text $Title -X 12 -Y 12 -Width 420
    $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
    [void]$Tower1.Controls.Add($lblHeaderTitle)

    $lblHeaderDesc = New-UGSMExpansionEditorLabel -Text $Description -X 12 -Y 40 -Width 960
    [void]$Tower1.Controls.Add($lblHeaderDesc)

    $lblFile = New-UGSMExpansionEditorLabel -Text 'File' -X 12 -Y 76 -Width 120
    $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width $UGSM_ExpansionFileFieldWidth
    $txtFile.ReadOnly = $true
    $txtFile.Text = [System.IO.Path]::GetFileName($FilePath)
    [void]$Tower1.Controls.Add($lblFile)
    [void]$Tower1.Controls.Add($txtFile)

    $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X $UGSM_ExpansionPathFieldLeft -Y 76 -Width 120
    $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 96 -Width 400
    $txtPath.ReadOnly = $true
    $txtPath.Anchor = 'Top,Left,Right'
    $txtPath.Text = $FilePath
    [void]$Tower1.Controls.Add($lblPath)
    [void]$Tower1.Controls.Add($txtPath)

    $towers = @($Tower1)
    foreach ($height in $TowerHeights) {
        $tower = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height $height
        [void]$contentHost.Controls.Add($tower)
        $towers += $tower
    }

    $towerGap = [int]$UGSM_ExpansionSectionGap

    $layout = {
        try {
            $contentWidth = [Math]::Max(980, ($editorPanel.ClientSize.Width - 18))
            $contentHost.Width = $contentWidth

            $currentY = 0
            foreach ($tower in $towers) {
                if (-not $tower.Visible) { continue }
                $tower.Location = New-Object System.Drawing.Point(0, $currentY)
                $tower.Width = [Math]::Max(980, ($contentHost.ClientSize.Width - 1))
                $currentY += $tower.Height + $towerGap
            }

            $contentHost.Height = [Math]::Max($currentY + 4, $editorPanel.ClientSize.Height)
            $txtPath.Width = [Math]::Max(180, ($Tower1.ClientSize.Width - $txtPath.Left - 12))
        }
        catch { }
    }.GetNewClosure()

    & $layout
    $HostPanel.Add_SizeChanged($layout)
    $root.Add_SizeChanged($layout)
    $shell.Add_SizeChanged($layout)
    $editorPanel.Add_SizeChanged($layout)

    return [ordered]@{
        Root           = $root
        Shell          = $shell
        EditorPanel    = $editorPanel
        ContentHost    = $contentHost
        Towers         = $towers
        Tower1         = $Tower1
        TxtFile        = $txtFile
        TxtPath        = $txtPath
        LblHeaderTitle = $lblHeaderTitle
        LblHeaderDesc  = $lblHeaderDesc
        LblFile        = $lblFile
        LblPath        = $lblPath
        Layout         = $layout
    }
}


function Show-DayZExpansionSettingEditor_AILocationSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $shellRef = New-UGSMExpansionSettingsEditorShell `
        -HostPanel $HostPanel `
        -Title 'Expansion AI Location Settings' `
        -Description 'Structured editor for roaming locations. Edit directly in the grid below and save from the top toolbar.' `
        -FilePath ([string]$FilePath) `
        -TowerHeights @(420)

    $Tower1 = $shellRef.Tower1
    $Tower2 = $shellRef.Towers[1]
    $shellRef.LblHeaderDesc.Width = 620

    $lblLocations = New-UGSMExpansionEditorLabel -Text 'Roaming Locations' -X 12 -Y 12 -Width 220
    $lblLocations.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
    [void]$Tower2.Controls.Add($lblLocations)

    $lblLocationsDesc = New-UGSMExpansionEditorLabel -Text 'Edit roaming locations directly in the grid below. Add and remove rows here; save from the top toolbar.' -X 12 -Y 40 -Width 900
    [void]$Tower2.Controls.Add($lblLocationsDesc)

    $btnAddLocation = New-UGSMExpansionNewButton -Text 'Add Location' -X 12 -Y 78 -Width 110
    $btnRemoveLocation = New-UGSMExpansionRemoveButton -Text 'Remove Location' -X 132 -Y 78 -Width 130
    foreach ($button in @($btnAddLocation, $btnRemoveLocation)) {
        Set-UGSMExpansionButtonStyle -Button $button | Out-Null
        [void]$Tower2.Controls.Add($button)
    }

    $gridLocations = New-Object System.Windows.Forms.DataGridView
    $gridLocations.Location = New-Object System.Drawing.Point(12, 118)
    $gridLocations.Size = New-Object System.Drawing.Size(960, 270)
    $gridLocations.Anchor = 'Top,Left,Right,Bottom'
    $gridLocations.BackgroundColor = $global:UGSM_ColorInputBackground
    $gridLocations.ForeColor = $global:UGSM_ColorText
    $gridLocations.BorderStyle = 'FixedSingle'
    $gridLocations.AllowUserToAddRows = $false
    $gridLocations.AllowUserToDeleteRows = $false
    $gridLocations.AllowUserToResizeRows = $false
    $gridLocations.SelectionMode = 'FullRowSelect'
    $gridLocations.MultiSelect = $false
    $gridLocations.AutoSizeColumnsMode = 'Fill'
    $gridLocations.RowHeadersVisible = $false
    $gridLocations.EnableHeadersVisualStyles = $false
    $gridLocations.ColumnHeadersHeightSizeMode = 'DisableResizing'
    $gridLocations.ColumnHeadersHeight = 22
    $gridLocations.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
    $gridLocations.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridLocations.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
    $gridLocations.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridLocations.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
    $gridLocations.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
    [void]$Tower2.Controls.Add($gridLocations)

    [void]$gridLocations.Columns.Add('Name', 'Name')
    [void]$gridLocations.Columns.Add('PosX', 'X')
    [void]$gridLocations.Columns.Add('PosY', 'Y')
    [void]$gridLocations.Columns.Add('PosZ', 'Z')
    [void]$gridLocations.Columns.Add('Radius', 'Radius')
    [void]$gridLocations.Columns.Add('Type', 'Type')
    $colEnabled = New-Object System.Windows.Forms.DataGridViewCheckBoxColumn
    $colEnabled.Name = 'Enabled'
    $colEnabled.HeaderText = 'Enabled'
    [void]$gridLocations.Columns.Add($colEnabled)

    $gridLocations.Columns['Name'].FillWeight = 34
    $gridLocations.Columns['PosX'].FillWeight = 12
    $gridLocations.Columns['PosY'].FillWeight = 8
    $gridLocations.Columns['PosZ'].FillWeight = 12
    $gridLocations.Columns['Radius'].FillWeight = 10
    $gridLocations.Columns['Type'].FillWeight = 14
    $gridLocations.Columns['Enabled'].FillWeight = 10

    $raw = Read-UGSMGameDayZTextFileSafe -Path $FilePath
    $data = $raw | ConvertFrom-Json

    $SettingsState.FileHandler = 'AILocation'
    $SettingsState.CurrentFilePath = [string]$FilePath
    $SettingsState.AILocationData = $data

    foreach ($loc in @($data.RoamingLocations)) {
        $x = '0'; $y = '0'; $z = '0'
        try {
            if ($loc.Position -and @($loc.Position).Count -ge 3) {
                $x = [string]$loc.Position[0]
                $y = [string]$loc.Position[1]
                $z = [string]$loc.Position[2]
            }
        }
        catch { }
        $enabledBool = $false
        try { $enabledBool = ([int]$loc.Enabled -ne 0) } catch { }
        [void]$gridLocations.Rows.Add(
            [string]$loc.Name,
            $x,
            $y,
            $z,
            [string]$loc.Radius,
            [string]$loc.Type,
            $enabledBool
        )
    }

    $saveAILocation = {
        try {
            $data = $SettingsState.AILocationData
            if ($null -eq $data) { throw 'AI Location settings are not loaded.' }

            $gridLocations.EndEdit()
            [System.Windows.Forms.Application]::DoEvents()

            $locations = New-Object System.Collections.ArrayList
            foreach ($row in @($gridLocations.Rows)) {
                if ($row.IsNewRow) { continue }

                $name = [string]$row.Cells['Name'].Value
                if ([string]::IsNullOrWhiteSpace($name)) { continue }

                $x = 0.0; $y = 0.0; $z = 0.0; $radius = 0.0
                try { $x = [double]([string]$row.Cells['PosX'].Value) } catch { }
                try { $y = [double]([string]$row.Cells['PosY'].Value) } catch { }
                try { $z = [double]([string]$row.Cells['PosZ'].Value) } catch { }
                try { $radius = [double]([string]$row.Cells['Radius'].Value) } catch { }
                $enabledVal = 0
                try { $enabledVal = $(if ([System.Convert]::ToBoolean($row.Cells['Enabled'].Value)) { 1 } else { 0 }) } catch { }

                $loc = [ordered]@{
                    Name     = $name
                    Position = @($x, $y, $z)
                    Radius   = $radius
                    Type     = [string]$row.Cells['Type'].Value
                    Enabled  = $enabledVal
                }
                [void]$locations.Add($loc)
            }

            $data.RoamingLocations = @($locations)
            if ($null -eq $data.ExcludedRoamingBuildings) { $data.ExcludedRoamingBuildings = @() }
            if ($null -eq $data.NoGoAreas) { $data.NoGoAreas = @() }

            $newRaw = ($data | ConvertTo-Json -Depth 100)
            [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
            [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $newRaw)

            if ($StatusLabel) { $StatusLabel.Text = ('Saved settings file: ' + [System.IO.Path]::GetFileName($FilePath)) }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving AI Location settings failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $SettingsState.CurrentSaveHandler = $saveAILocation

    $addLocation = {
        [void]$gridLocations.Rows.Add('New_Location', '0', '0', '0', '100', 'Village', $true)
        $index = $gridLocations.Rows.Count - 1
        if ($index -ge 0) {
            $gridLocations.ClearSelection()
            $gridLocations.CurrentCell = $gridLocations.Rows[$index].Cells['Name']
            $gridLocations.Rows[$index].Selected = $true
            $gridLocations.BeginEdit($true)
        }
    }.GetNewClosure()

    $removeLocation = {
        if ($gridLocations.SelectedRows.Count -gt 0) {
            $gridLocations.Rows.Remove($gridLocations.SelectedRows[0])
        }
    }.GetNewClosure()

    $normalizeAILocationGrid = {
        try {
            foreach ($row in @($gridLocations.Rows)) {
                if ($row.IsNewRow) { continue }
                foreach ($colName in @('PosX', 'PosY', 'PosZ', 'Radius')) {
                    $val = [string]$row.Cells[$colName].Value
                    if ([string]::IsNullOrWhiteSpace($val)) { $row.Cells[$colName].Value = '0' }
                }
                try { $row.Cells['Enabled'].Value = [System.Convert]::ToBoolean($row.Cells['Enabled'].Value) } catch { $row.Cells['Enabled'].Value = $false }
            }
        }
        catch { }
    }.GetNewClosure()

    $btnAddLocation.Add_Click($addLocation)
    $btnRemoveLocation.Add_Click($removeLocation)
    $gridLocations.Add_CurrentCellDirtyStateChanged({
            try {
                if ($gridLocations.IsCurrentCellDirty) {
                    $gridLocations.CommitEdit([System.Windows.Forms.DataGridViewDataErrorContexts]::Commit)
                }
            }
            catch { }
        })
    $gridLocations.Add_CellEndEdit($normalizeAILocationGrid)

    $layoutAILocation = {
        try {
            $gridLocations.Width = [Math]::Max(240, ($Tower2.ClientSize.Width - 24))
            $gridLocations.Height = [Math]::Max(120, ($Tower2.ClientSize.Height - $gridLocations.Top - 14))
        }
        catch { }
    }.GetNewClosure()
    & $layoutAILocation
    $HostPanel.Add_SizeChanged($layoutAILocation)
    $Tower2.Add_SizeChanged($layoutAILocation)

    & $normalizeAILocationGrid
    if ($gridLocations.Rows.Count -gt 0) {
        $gridLocations.ClearSelection()
        $gridLocations.Rows[0].Selected = $true
    }
}

function Show-DayZExpansionSettingEditor_AIPatrolSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $shellRef = New-UGSMExpansionSettingsEditorShell `
        -HostPanel $HostPanel `
        -Title 'Expansion AI Patrol Settings' `
        -Description 'Global AI patrol settings and patrol list editor.' `
        -FilePath ([string]$FilePath) `
        -TowerHeights @(160, 620)

    $Tower1 = $shellRef.Tower1
    $Tower2 = $shellRef.Towers[1]
    $Tower3 = $shellRef.Towers[2]

    $shellRef.LblHeaderDesc.Width = 560
    $Tower2.Height = ($UGSM_ExpansionTowerHeight - 125)
    $Tower3.Height = ($UGSM_ExpansionTowerHeight + 120)
    & $shellRef.Layout

    $chkEnabled = New-Object System.Windows.Forms.CheckBox
    $chkEnabled.Text = 'Enabled'
    $chkEnabled.ForeColor = $global:UGSM_ColorText
    $chkEnabled.BackColor = $global:UGSM_ColorBackground
    $chkEnabled.Location = New-Object System.Drawing.Point(12, 32)
    $chkEnabled.Size = New-Object System.Drawing.Size(90, 24)
    [void]$Tower2.Controls.Add($chkEnabled)

    function New-AIPatrolNumeric {
        param(
            [string]$Label,
            [int]$X,
            [int]$Y,
            [decimal]$Min = -1000000,
            [decimal]$Max = 1000000,
            [int]$Decimals = 3,
            [int]$Width = 84
        )
        $lbl = New-UGSMExpansionEditorLabel -Text $Label -X $X -Y $Y -Width 72
        [void]$Tower2.Controls.Add($lbl)

        $num = New-Object System.Windows.Forms.NumericUpDown
        $num.Location = New-Object System.Drawing.Point($X, ($Y + 20))
        $num.Size = New-Object System.Drawing.Size($Width, 24)
        $num.Minimum = $Min
        $num.Maximum = $Max
        $num.DecimalPlaces = $Decimals
        $num.BackColor = $global:UGSM_ColorInputBackground
        $num.ForeColor = $global:UGSM_ColorText
        [void]$Tower2.Controls.Add($num)
        return $num
    }

    $numFormationScale = New-AIPatrolNumeric -Label 'Formation' -X 120 -Y 14 -Min -1000 -Max 1000 -Decimals 3
    $numDespawnTime = New-AIPatrolNumeric -Label 'Despawn' -X 220 -Y 14 -Min -1000000 -Max 1000000 -Decimals 3
    $numRespawnTime = New-AIPatrolNumeric -Label 'Respawn' -X 320 -Y 14 -Min -1000000 -Max 1000000 -Decimals 3
    $numMinDist = New-AIPatrolNumeric -Label 'Min Dist' -X 420 -Y 14 -Min -1000000 -Max 1000000 -Decimals 3
    $numMaxDist = New-AIPatrolNumeric -Label 'Max Dist' -X 520 -Y 14 -Min -1000000 -Max 1000000 -Decimals 3
    $numDespawnRadius = New-AIPatrolNumeric -Label 'Despawn R' -X 620 -Y 14 -Min -1000000 -Max 1000000 -Decimals 3

    $lblTower3 = New-UGSMExpansionEditorLabel -Text 'Patrols' -X 12 -Y 12 -Width 200
    $lblTower3.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
    [void]$Tower3.Controls.Add($lblTower3)

    $btnAddPatrol = New-UGSMExpansionNewButton -Text 'Add Patrol' -X 12 -Y 46 -Width 110
    $btnRemovePatrol = New-UGSMExpansionRemoveButton -Text 'Remove Patrol' -X 132 -Y 46 -Width 130
    foreach ($button in @($btnAddPatrol, $btnRemovePatrol)) {
        Set-UGSMExpansionButtonStyle -Button $button | Out-Null
        [void]$Tower3.Controls.Add($button)
    }

    $gridPatrols = New-Object System.Windows.Forms.DataGridView
    $gridPatrols.Location = New-Object System.Drawing.Point(12, 84)
    $gridPatrols.Size = New-Object System.Drawing.Size(960, 200)
    $gridPatrols.Anchor = 'Top,Left,Right,Bottom'
    $gridPatrols.BackgroundColor = $global:UGSM_ColorInputBackground
    $gridPatrols.ForeColor = $global:UGSM_ColorText
    $gridPatrols.BorderStyle = 'FixedSingle'
    $gridPatrols.AllowUserToAddRows = $false
    $gridPatrols.AllowUserToDeleteRows = $false
    $gridPatrols.AllowUserToResizeRows = $false
    $gridPatrols.SelectionMode = 'FullRowSelect'
    $gridPatrols.MultiSelect = $false
    $gridPatrols.AutoSizeColumnsMode = 'Fill'
    $gridPatrols.RowHeadersVisible = $false
    $gridPatrols.EnableHeadersVisualStyles = $false
    $gridPatrols.ColumnHeadersHeightSizeMode = 'DisableResizing'
    $gridPatrols.ColumnHeadersHeight = 22
    $gridPatrols.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
    $gridPatrols.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridPatrols.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
    $gridPatrols.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
    $gridPatrols.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
    $gridPatrols.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
    [void]$Tower3.Controls.Add($gridPatrols)

    [void]$gridPatrols.Columns.Add('Name', 'Name')
    [void]$gridPatrols.Columns.Add('Faction', 'Faction')
    [void]$gridPatrols.Columns.Add('Behaviour', 'Behaviour')
    [void]$gridPatrols.Columns.Add('NumAI', 'AI')
    [void]$gridPatrols.Columns.Add('NumAIMax', 'AI Max')
    [void]$gridPatrols.Columns.Add('Speed', 'Speed')
    [void]$gridPatrols.Columns.Add('Chance', 'Chance')
    [void]$gridPatrols.Columns.Add('Category', 'Category')
    [void]$gridPatrols.Columns.Add('ObjectClassName', 'Object')
    [void]$gridPatrols.Columns.Add('WaypointCount', 'Waypoints')
    $gridPatrols.Columns['Name'].FillWeight = 18
    $gridPatrols.Columns['Faction'].FillWeight = 8
    $gridPatrols.Columns['Behaviour'].FillWeight = 12
    $gridPatrols.Columns['NumAI'].FillWeight = 5
    $gridPatrols.Columns['NumAIMax'].FillWeight = 6
    $gridPatrols.Columns['Speed'].FillWeight = 7
    $gridPatrols.Columns['Chance'].FillWeight = 7
    $gridPatrols.Columns['Category'].FillWeight = 12
    $gridPatrols.Columns['ObjectClassName'].FillWeight = 16
    $gridPatrols.Columns['WaypointCount'].FillWeight = 8
    $gridPatrols.Columns['WaypointCount'].ReadOnly = $true

    $raw = Read-UGSMGameDayZTextFileSafe -Path $FilePath
    $data = $raw | ConvertFrom-Json

    $SettingsState.FileHandler = 'AIPatrol'
    $SettingsState.CurrentFilePath = [string]$FilePath
    $SettingsState.AIPatrolData = $data

    try { $chkEnabled.Checked = ([int]$data.Enabled -ne 0) } catch { $chkEnabled.Checked = $false }
    try { $numFormationScale.Value = [decimal]([double]$data.FormationScale) } catch { $numFormationScale.Value = 0 }
    try { $numDespawnTime.Value = [decimal]([double]$data.DespawnTime) } catch { $numDespawnTime.Value = 0 }
    try { $numRespawnTime.Value = [decimal]([double]$data.RespawnTime) } catch { $numRespawnTime.Value = 0 }
    try { $numMinDist.Value = [decimal]([double]$data.MinDistRadius) } catch { $numMinDist.Value = 0 }
    try { $numMaxDist.Value = [decimal]([double]$data.MaxDistRadius) } catch { $numMaxDist.Value = 0 }
    try { $numDespawnRadius.Value = [decimal]([double]$data.DespawnRadius) } catch { $numDespawnRadius.Value = 0 }

    foreach ($patrol in @($data.Patrols)) {
        $waypointCount = 0
        try { $waypointCount = @($patrol.Waypoints).Count } catch { }
        [void]$gridPatrols.Rows.Add(
            [string]$patrol.Name,
            [string]$patrol.Faction,
            [string]$patrol.Behaviour,
            [string]$patrol.NumberOfAI,
            [string]$patrol.NumberOfAIMax,
            [string]$patrol.Speed,
            [string]$patrol.Chance,
            [string]$patrol.LoadBalancingCategory,
            [string]$patrol.ObjectClassName,
            [string]$waypointCount
        )
    }

    $saveAIPatrol = {
        try {
            $data = $SettingsState.AIPatrolData
            if ($null -eq $data) { throw 'AI Patrol settings are not loaded.' }

            $gridPatrols.EndEdit()
            [System.Windows.Forms.Application]::DoEvents()

            $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
            $data.FormationScale = [double]$numFormationScale.Value
            $data.DespawnTime = [double]$numDespawnTime.Value
            $data.RespawnTime = [double]$numRespawnTime.Value
            $data.MinDistRadius = [double]$numMinDist.Value
            $data.MaxDistRadius = [double]$numMaxDist.Value
            $data.DespawnRadius = [double]$numDespawnRadius.Value

            $existing = @($data.Patrols)
            $newPatrols = New-Object System.Collections.ArrayList
            for ($i = 0; $i -lt $gridPatrols.Rows.Count; $i++) {
                $row = $gridPatrols.Rows[$i]
                if ($row.IsNewRow) { continue }

                $patrol = $null
                if ($i -lt $existing.Count) {
                    $patrol = $existing[$i]
                }
                else {
                    $patrol = [pscustomobject]@{
                        Name                            = ''
                        Persist                         = 0
                        Faction                         = 'West'
                        Formation                       = ''
                        FormationScale                  = 1.5
                        FormationLooseness              = 0.0
                        Loadout                         = ''
                        Units                           = @()
                        NumberOfAI                      = 1
                        NumberOfAIMax                   = 1
                        Behaviour                       = 'ROAMING'
                        LootingBehaviour                = 'DEFAULT'
                        Speed                           = 'JOG'
                        UnderThreatSpeed                = 'SPRINT'
                        DefaultStance                   = 'STANDING'
                        DefaultLookAngle                = 0.0
                        CanBeLooted                     = 1
                        LootDropOnDeath                 = ''
                        UnlimitedReload                 = 6
                        SniperProneDistanceThreshold    = 0.0
                        AccuracyMin                     = -1.0
                        AccuracyMax                     = -1.0
                        ThreatDistanceLimit             = -1.0
                        NoiseInvestigationDistanceLimit = -1.0
                        MaxFlankingDistance             = -1.0
                        EnableFlankingOutsideCombat     = -1
                        DamageMultiplier                = -1.0
                        DamageReceivedMultiplier        = -1.0
                        HeadshotResistance              = 0.0
                        ShoryukenChance                 = 0.0
                        ShoryukenDamageMultiplier       = 0.0
                        CanSpawnInContaminatedArea      = 0
                        CanBeTriggeredByAI              = 0
                        MinDistRadius                   = -1.0
                        MaxDistRadius                   = -1.0
                        DespawnRadius                   = -1.0
                        MinSpreadRadius                 = 0.0
                        MaxSpreadRadius                 = 0.0
                        Chance                          = 1.0
                        DespawnTime                     = -1.0
                        RespawnTime                     = -2.0
                        LoadBalancingCategory           = ''
                        ObjectClassName                 = ''
                        WaypointInterpolation           = ''
                        UseRandomWaypointAsStartPoint   = 0
                        Waypoints                       = @()
                    }
                }

                $patrol.Name = [string]$row.Cells['Name'].Value
                $patrol.Faction = [string]$row.Cells['Faction'].Value
                $patrol.Behaviour = [string]$row.Cells['Behaviour'].Value
                try { $patrol.NumberOfAI = [int]([string]$row.Cells['NumAI'].Value) } catch { $patrol.NumberOfAI = 0 }
                try { $patrol.NumberOfAIMax = [int]([string]$row.Cells['NumAIMax'].Value) } catch { $patrol.NumberOfAIMax = 0 }
                $patrol.Speed = [string]$row.Cells['Speed'].Value
                try { $patrol.Chance = [double]([string]$row.Cells['Chance'].Value) } catch { $patrol.Chance = 0.0 }
                $patrol.LoadBalancingCategory = [string]$row.Cells['Category'].Value
                $patrol.ObjectClassName = [string]$row.Cells['ObjectClassName'].Value

                [void]$newPatrols.Add($patrol)
            }

            $data.Patrols = @($newPatrols)

            $newRaw = ($data | ConvertTo-Json -Depth 100)
            [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
            [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $newRaw)

            if ($StatusLabel) { $StatusLabel.Text = ('Saved settings file: ' + [System.IO.Path]::GetFileName($FilePath)) }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving AI Patrol settings failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $SettingsState.CurrentSaveHandler = $saveAIPatrol

    $addPatrol = {
        [void]$gridPatrols.Rows.Add('New Patrol', 'West', 'ROAMING', '1', '1', 'JOG', '1.0', '', '', '0')
        $index = $gridPatrols.Rows.Count - 1
        if ($index -ge 0) {
            $gridPatrols.ClearSelection()
            $gridPatrols.CurrentCell = $gridPatrols.Rows[$index].Cells['Name']
            $gridPatrols.Rows[$index].Selected = $true
            $gridPatrols.BeginEdit($true)
        }
    }.GetNewClosure()

    $removePatrol = {
        if ($gridPatrols.SelectedRows.Count -gt 0) {
            $gridPatrols.Rows.Remove($gridPatrols.SelectedRows[0])
        }
    }.GetNewClosure()

    $normalizeGrid = {
        try {
            foreach ($row in @($gridPatrols.Rows)) {
                if ($row.IsNewRow) { continue }
                foreach ($colName in @('NumAI', 'NumAIMax')) {
                    $val = [string]$row.Cells[$colName].Value
                    if ([string]::IsNullOrWhiteSpace($val)) { $row.Cells[$colName].Value = '0' }
                }
                $chanceVal = [string]$row.Cells['Chance'].Value
                if ([string]::IsNullOrWhiteSpace($chanceVal)) { $row.Cells['Chance'].Value = '0' }
                $row.Cells['WaypointCount'].ReadOnly = $true
            }
        }
        catch { }
    }.GetNewClosure()

    $btnAddPatrol.Add_Click($addPatrol)
    $btnRemovePatrol.Add_Click($removePatrol)
    $gridPatrols.Add_CellEndEdit($normalizeGrid)

    $layoutAIPatrol = {
        try {
            $usableWidth = [Math]::Max(240, ($Tower3.ClientSize.Width - 24))
            $usableHeight = [Math]::Max(120, ($Tower3.ClientSize.Height - $gridPatrols.Top - 14))
            $gridPatrols.Size = New-Object System.Drawing.Size($usableWidth, $usableHeight)
        }
        catch { }
    }.GetNewClosure()

    & $layoutAIPatrol
    $HostPanel.Add_SizeChanged($layoutAIPatrol)
    $Tower3.Add_SizeChanged($layoutAIPatrol)

    & $normalizeGrid
    if ($gridPatrols.Rows.Count -gt 0) {
        $gridPatrols.ClearSelection()
        $gridPatrols.Rows[0].Selected = $true
    }
}

function Show-DayZExpansionSettingEditor_BaseBuildingSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $HostPanel.Controls.Clear()

    $rootPanel = New-Object System.Windows.Forms.Panel
    $rootPanel.Dock = 'Fill'
    $rootPanel.BackColor = $global:UGSM_ColorBackground
    [void]$HostPanel.Controls.Add($rootPanel)

    $scrollBody = New-Object System.Windows.Forms.Panel
    $scrollBody.Dock = 'Fill'
