    $scrollBody.BackColor = $global:UGSM_ColorBackground
    [void]$rootPanel.Controls.Add($scrollBody)

    $contentPanel = New-Object System.Windows.Forms.Panel
    $contentPanel.Location = New-Object System.Drawing.Point(0, 0)
    $contentPanel.Size = New-Object System.Drawing.Size(1700, 900)
    $contentPanel.BackColor = $global:UGSM_ColorBackground
    [void]$scrollBody.Controls.Add($contentPanel)

    $topPanel = New-Object System.Windows.Forms.Panel
    $topPanel.Location = New-Object System.Drawing.Point(0, 0)
    $topPanel.Size = New-Object System.Drawing.Size(1700, 210)
    $topPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($topPanel)

    $listsPanel = New-Object System.Windows.Forms.Panel
    $listsPanel.Location = New-Object System.Drawing.Point(0, 220)
    $listsPanel.Size = New-Object System.Drawing.Size(1700, 180)
    $listsPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($listsPanel)

    $zonesPanel = New-Object System.Windows.Forms.Panel
    $zonesPanel.Location = New-Object System.Drawing.Point(0, 410)
    $zonesPanel.Size = New-Object System.Drawing.Size(1700, 420)
    $zonesPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($zonesPanel)

    function New-BBLabel {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 140)
        return (New-UGSMLabel -Text $Text -X $X -Y $Y -Width $Width -Height 18 -FontSize 8.5 -Color $global:UGSM_ColorText)
    }

    function New-BBNumeric {
        param(
            [int]$X, [int]$Y,
            [decimal]$Min = -1000000,
            [decimal]$Max = 1000000,
            [int]$Decimals = 0,
            [int]$Width = 90
        )
        $num = New-Object System.Windows.Forms.NumericUpDown
        $num.Location = New-Object System.Drawing.Point($X, $Y)
        $num.Size = New-Object System.Drawing.Size($Width, 24)
        $num.Minimum = $Min
        $num.Maximum = $Max
        $num.DecimalPlaces = $Decimals
        return $num
    }

    function New-BBTextBox {
        param([int]$X, [int]$Y, [int]$Width = 220)
        $tb = New-Object System.Windows.Forms.TextBox
        $tb.Location = New-Object System.Drawing.Point($X, $Y)
        $tb.Size = New-Object System.Drawing.Size($Width, 24)
        $tb.BorderStyle = 'FixedSingle'
        $tb.BackColor = $global:UGSM_ColorInputBackground
        $tb.ForeColor = $global:UGSM_ColorText
        return $tb
    }

    function New-BBCheck {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 220)
        $chk = New-Object System.Windows.Forms.CheckBox
        $chk.Text = $Text
        $chk.ForeColor = $global:UGSM_ColorText
        $chk.Location = New-Object System.Drawing.Point($X, $Y)
        $chk.Size = New-Object System.Drawing.Size($Width, 24)
        return $chk
    }

    function New-BBListGrid {
        $grid = New-Object System.Windows.Forms.DataGridView
        $grid.Dock = 'Fill'
        $grid.BackgroundColor = $global:UGSM_ColorInputBackground
        $grid.ForeColor = $global:UGSM_ColorText
        $grid.BorderStyle = 'FixedSingle'
        $grid.AllowUserToAddRows = $false
        $grid.AllowUserToDeleteRows = $false
        $grid.AllowUserToResizeRows = $false
        $grid.SelectionMode = 'FullRowSelect'
        $grid.MultiSelect = $false
        $grid.AutoSizeColumnsMode = 'Fill'
        $grid.RowHeadersVisible = $false
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersHeightSizeMode = 'DisableResizing'
        $grid.ColumnHeadersHeight = 22
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $grid.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $grid.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        return $grid
    }

    $raw = Read-UGSMGameDayZTextFileSafe -Path $FilePath
    $data = $raw | ConvertFrom-Json

    $SettingsState.FileHandler = 'BaseBuilding'
    $SettingsState.CurrentFilePath = [string]$FilePath
    $SettingsState.BaseBuildingData = $data

    $topBody = New-Object System.Windows.Forms.Panel
    $topBody.Dock = 'Fill'
    $topBody.Padding = New-Object System.Windows.Forms.Padding(0, 12, 0, 0)
    $topBody.BackColor = $global:UGSM_ColorBackground
    [void]$topPanel.Controls.Add($topBody)

    $topLeft = New-Object System.Windows.Forms.Panel
    $topLeft.Location = New-Object System.Drawing.Point(0, 25)
    $topLeft.Size = New-Object System.Drawing.Size(560, 178)
    $topLeft.BackColor = $global:UGSM_ColorBackground
    [void]$topBody.Controls.Add($topLeft)

    $topRight = New-Object System.Windows.Forms.Panel
    $topRight.Location = New-Object System.Drawing.Point(580, 25)
    $topRight.Size = New-Object System.Drawing.Size(760, 178)
    $topRight.BackColor = $global:UGSM_ColorBackground
    [void]$topBody.Controls.Add($topRight)

    # LEFT GROUP: numeric/settings row + territory/craft toggles
    $lblVersion = New-BBLabel -Text 'Version' -X 0 -Y 8 -Width 60
    [void]$topLeft.Controls.Add($lblVersion)
    $numVersion = New-BBNumeric -X 62 -Y 6 -Min 0 -Max 9999 -Decimals 0 -Width 70
    [void]$topLeft.Controls.Add($numVersion)

    $lblCodeLen = New-BBLabel -Text 'Code Length' -X 150 -Y 8 -Width 80
    [void]$topLeft.Controls.Add($lblCodeLen)
    $numCodeLen = New-BBNumeric -X 235 -Y 6 -Min 1 -Max 12 -Decimals 0 -Width 70
    [void]$topLeft.Controls.Add($numCodeLen)

    $lblWrongCodeDmg = New-BBLabel -Text 'Wrong Code Dmg' -X 325 -Y 8 -Width 100
    [void]$topLeft.Controls.Add($lblWrongCodeDmg)
    $numWrongCodeDmg = New-BBNumeric -X 430 -Y 6 -Min 0 -Max 1000000 -Decimals 3 -Width 100
    [void]$topLeft.Controls.Add($numWrongCodeDmg)

    $lblAttachMode = New-BBLabel -Text 'Attach Mode' -X 0 -Y 42 -Width 80
    [void]$topLeft.Controls.Add($lblAttachMode)
    $numAttachMode = New-BBNumeric -X 85 -Y 40 -Min -100 -Max 100 -Decimals 0 -Width 70
    [void]$topLeft.Controls.Add($numAttachMode)

    $lblDismantleFlagMode = New-BBLabel -Text 'Dismantle Flag' -X 175 -Y 42 -Width 95
    [void]$topLeft.Controls.Add($lblDismantleFlagMode)
    $numDismantleFlagMode = New-BBNumeric -X 275 -Y 40 -Min -100 -Max 100 -Decimals 0 -Width 70
    [void]$topLeft.Controls.Add($numDismantleFlagMode)

    $lblFlagMenuMode = New-BBLabel -Text 'Flag Menu' -X 365 -Y 42 -Width 70
    [void]$topLeft.Controls.Add($lblFlagMenuMode)
    $numFlagMenuMode = New-BBNumeric -X 440 -Y 40 -Min -100 -Max 100 -Decimals 0 -Width 70
    [void]$topLeft.Controls.Add($numFlagMenuMode)

    $chkCanBuildAnywhere = New-BBCheck -Text 'Can Build Anywhere' -X 0 -Y 78 -Width 220
    $chkAllowNoTerritory = New-BBCheck -Text 'Allow Build Without Territory' -X 260 -Y 78 -Width 260
    $chkCraftVanilla = New-BBCheck -Text 'Craft Vanilla Basebuilding' -X 0 -Y 106 -Width 220
    $chkCraftExpansion = New-BBCheck -Text 'Craft Expansion Basebuilding' -X 260 -Y 106 -Width 260
    $chkCraftFlagKit = New-BBCheck -Text 'Craft Territory Flag Kit' -X 0 -Y 134 -Width 220
    $chkSimpleTerritory = New-BBCheck -Text 'Simple Territory' -X 260 -Y 134 -Width 220
    $chkEnableVirtualStorage = New-BBCheck -Text 'Enable Virtual Storage' -X 0 -Y 162 -Width 220

    [void]$topLeft.Controls.Add($chkCanBuildAnywhere)
    [void]$topLeft.Controls.Add($chkAllowNoTerritory)
    [void]$topLeft.Controls.Add($chkCraftVanilla)
    [void]$topLeft.Controls.Add($chkCraftExpansion)
    [void]$topLeft.Controls.Add($chkCraftFlagKit)
    [void]$topLeft.Controls.Add($chkSimpleTerritory)
    [void]$topLeft.Controls.Add($chkEnableVirtualStorage)

    # RIGHT GROUP: dismantle/codelock/access + message/save
    $chkDestroyFlag = New-BBCheck -Text 'Destroy Flag On Dismantle' -X 0 -Y 8 -Width 230
    $chkDismantleOutside = New-BBCheck -Text 'Dismantle Outside Territory' -X 250 -Y 8 -Width 230
    $chkDismantleInside = New-BBCheck -Text 'Dismantle Inside Territory' -X 500 -Y 8 -Width 220

    $chkDismantleAnywhere = New-BBCheck -Text 'Dismantle Anywhere' -X 0 -Y 36 -Width 230
    $chkCodeActionsAnywhere = New-BBCheck -Text 'Codelock Actions Anywhere' -X 250 -Y 36 -Width 230
    $chkWrongCodeDamage = New-BBCheck -Text 'Damage On Wrong Code' -X 500 -Y 36 -Width 220

    $chkRememberCode = New-BBCheck -Text 'Remember Code' -X 0 -Y 64 -Width 230
    $chkAutoFlag = New-BBCheck -Text 'Automatic Flag On Creation' -X 250 -Y 64 -Width 230
    $chkGetFlagBack = New-BBCheck -Text 'Get Flag Kit After Build' -X 500 -Y 64 -Width 220

    $chkZonesNoBuild = New-BBCheck -Text 'Zones Are No-Build Zones' -X 0 -Y 92 -Width 230
    $chkPreventAccess = New-BBCheck -Text 'Prevent Access Through Obstructing Items' -X 250 -Y 92 -Width 330

    [void]$topRight.Controls.Add($chkDestroyFlag)
    [void]$topRight.Controls.Add($chkDismantleOutside)
    [void]$topRight.Controls.Add($chkDismantleInside)
    [void]$topRight.Controls.Add($chkDismantleAnywhere)
    [void]$topRight.Controls.Add($chkCodeActionsAnywhere)
    [void]$topRight.Controls.Add($chkWrongCodeDamage)
    [void]$topRight.Controls.Add($chkRememberCode)
    [void]$topRight.Controls.Add($chkAutoFlag)
    [void]$topRight.Controls.Add($chkGetFlagBack)
    [void]$topRight.Controls.Add($chkZonesNoBuild)
    [void]$topRight.Controls.Add($chkPreventAccess)

    $lblBuildMsg = New-BBLabel -Text 'Build Zone Message' -X 0 -Y 126 -Width 120
    [void]$topRight.Controls.Add($lblBuildMsg)
    $txtBuildMsg = New-BBTextBox -X 125 -Y 124 -Width 320
    [void]$topRight.Controls.Add($txtBuildMsg)

    $btnSaveBase = New-UGSMButton -Text 'Save BaseBuilding' -X 465 -Y 122 -Width 150 -Height 28 -BackColor '#F0A500'
    [void]$topRight.Controls.Add($btnSaveBase)

    try { $numVersion.Value = [decimal]([int]$data.m_Version) } catch { $numVersion.Value = 0 }
    try { $numCodeLen.Value = [decimal]([int]$data.CodeLockLength) } catch { $numCodeLen.Value = 4 }
    try { $numWrongCodeDmg.Value = [decimal]([double]$data.DamageWhenEnterWrongCodeLock) } catch { $numWrongCodeDmg.Value = 0 }
    try { $numAttachMode.Value = [decimal]([int]$data.CodelockAttachMode) } catch { $numAttachMode.Value = 0 }
    try { $numDismantleFlagMode.Value = [decimal]([int]$data.DismantleFlagMode) } catch { $numDismantleFlagMode.Value = 0 }
    try { $numFlagMenuMode.Value = [decimal]([int]$data.FlagMenuMode) } catch { $numFlagMenuMode.Value = 0 }

    $chkCanBuildAnywhere.Checked = ([int]$data.CanBuildAnywhere -eq 1)
    $chkAllowNoTerritory.Checked = ([int]$data.AllowBuildingWithoutATerritory -eq 1)
    $chkCraftVanilla.Checked = ([int]$data.CanCraftVanillaBasebuilding -eq 1)
    $chkCraftExpansion.Checked = ([int]$data.CanCraftExpansionBasebuilding -eq 1)
    $chkDestroyFlag.Checked = ([int]$data.DestroyFlagOnDismantle -eq 1)
    $chkDismantleOutside.Checked = ([int]$data.DismantleOutsideTerritory -eq 1)
    $chkDismantleInside.Checked = ([int]$data.DismantleInsideTerritory -eq 1)
    $chkDismantleAnywhere.Checked = ([int]$data.DismantleAnywhere -eq 1)
    $chkCodeActionsAnywhere.Checked = ([int]$data.CodelockActionsAnywhere -eq 1)
    $chkWrongCodeDamage.Checked = ([int]$data.DoDamageWhenEnterWrongCodeLock -eq 1)
    $chkRememberCode.Checked = ([int]$data.RememberCode -eq 1)
    $chkCraftFlagKit.Checked = ([int]$data.CanCraftTerritoryFlagKit -eq 1)
    $chkSimpleTerritory.Checked = ([int]$data.SimpleTerritory -eq 1)
    $chkAutoFlag.Checked = ([int]$data.AutomaticFlagOnCreation -eq 1)
    $chkGetFlagBack.Checked = ([int]$data.GetTerritoryFlagKitAfterBuild -eq 1)
    $chkZonesNoBuild.Checked = ([int]$data.ZonesAreNoBuildZones -eq 1)
    $chkPreventAccess.Checked = ([int]$data.PreventItemAccessThroughObstructingItems -eq 1)
    $chkEnableVirtualStorage.Checked = ([int]$data.EnableVirtualStorage -eq 1)
    $txtBuildMsg.Text = [string]$data.BuildZoneRequiredCustomMessage

    $listsLayout = New-Object System.Windows.Forms.TableLayoutPanel
    $listsLayout.Dock = 'Fill'
    $listsLayout.ColumnCount = 3
    $listsLayout.RowCount = 1
    $listsLayout.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 33.33)))
    $listsLayout.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 33.33)))
    $listsLayout.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 33.34)))
    [void]$listsPanel.Controls.Add($listsLayout)

    function New-BBListSection {
        param(
            [string]$Title,
            [string]$ColumnName,
            [string]$HeaderText
        )

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'
        $panel.Padding = New-Object System.Windows.Forms.Padding(0, 0, 8, 0)
        $panel.BackColor = $global:UGSM_ColorBackground

        $header = New-Object System.Windows.Forms.Panel
        $header.Dock = 'Top'
        $header.Height = 58
        $header.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($header)

        $body = New-Object System.Windows.Forms.Panel
        $body.Dock = 'Fill'
        $body.Padding = New-Object System.Windows.Forms.Padding(0, 60, 0, 0)
        $body.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($body)

        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = $Title
        $lbl.ForeColor = $global:UGSM_ColorText
        $lbl.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        $lbl.Location = New-Object System.Drawing.Point(0, 0)
        $lbl.Size = New-Object System.Drawing.Size(260, 18)
        [void]$header.Controls.Add($lbl)

        $btnAdd = New-UGSMButton -Text 'Add' -X 0 -Y 24 -Width 70 -Height 24 -BackColor $UGSM_ExpansionAccentColor 
        $btnRemove = New-UGSMButton -Text 'Remove' -X 80 -Y 24 -Width 80 -Height 24 -BackColor $global:UGSM_ColorDanger
        [void]$header.Controls.Add($btnAdd)
        [void]$header.Controls.Add($btnRemove)

        $grid = New-BBListGrid
        $null = $grid.Columns.Add($ColumnName, $HeaderText)
        [void]$body.Controls.Add($grid)

        return [pscustomobject]@{
            Panel        = $panel
            Grid         = $grid
            AddButton    = $btnAdd
            RemoveButton = $btnRemove
        }
    }

    $outsideSection = New-BBListSection -Title 'Deployable Outside Territory' -ColumnName 'ClassName' -HeaderText 'Class Name'
    $enemySection = New-BBListSection -Title 'Deployable In Enemy Territory' -ColumnName 'ClassName' -HeaderText 'Class Name'
    $virtualSection = New-BBListSection -Title 'Virtual Storage Excluded Containers' -ColumnName 'ClassName' -HeaderText 'Class Name'

    [void]$listsLayout.Controls.Add($outsideSection.Panel, 0, 0)
    [void]$listsLayout.Controls.Add($enemySection.Panel, 1, 0)
    [void]$listsLayout.Controls.Add($virtualSection.Panel, 2, 0)

    foreach ($item in @($data.DeployableOutsideATerritory)) {
        [void]$outsideSection.Grid.Rows.Add([string]$item)
    }
    foreach ($item in @($data.DeployableInsideAEnemyTerritory)) {
        [void]$enemySection.Grid.Rows.Add([string]$item)
    }
    foreach ($item in @($data.VirtualStorageExcludedContainers)) {
        [void]$virtualSection.Grid.Rows.Add([string]$item)
    }

    $zonesSplit = New-Object System.Windows.Forms.SplitContainer
    $zonesSplit.Dock = 'Fill'
    $zonesSplit.Orientation = 'Vertical'
    $zonesSplit.SplitterWidth = 6
    $zonesSplit.BackColor = $global:UGSM_ColorBackground
    $zonesSplit.IsSplitterFixed = $true
    $zonesSplit.Panel1MinSize = 520
    $zonesSplit.Panel2.BackColor = [System.Drawing.Color]::DarkRed
    [void]$zonesPanel.Controls.Add($zonesSplit)

    $setZonesSplit = {
        try {
            if ($zonesSplit.Width -le 700) { return }

            $target = $zonesSplit.Width - 650
            if ($target -lt $zonesSplit.Panel1MinSize) {
                $target = $zonesSplit.Panel1MinSize
            }

            if ($target -gt 0 -and $target -lt ($zonesSplit.Width - 10)) {
                $zonesSplit.SplitterDistance = $target
            }
        }
        catch { }
    }.GetNewClosure()

    $zonesSplit.Add_Layout($setZonesSplit)
    $zonesSplit.Add_SizeChanged($setZonesSplit)

    $zonesLeft = New-Object System.Windows.Forms.Panel
    $zonesLeft.Dock = 'Fill'
    $zonesLeft.Padding = New-Object System.Windows.Forms.Padding(0, 64, 0, 0)
    $zonesLeft.BackColor = $global:UGSM_ColorBackground
    [void]$zonesSplit.Panel1.Controls.Add($zonesLeft)

    $zonesHeader = New-Object System.Windows.Forms.Panel
    $zonesHeader.Dock = 'Top'
    $zonesHeader.Height = 80
    $zonesHeader.BackColor = $global:UGSM_ColorBackground
    [void]$zonesSplit.Panel1.Controls.Add($zonesHeader)
    $zonesHeader.BringToFront()

    & $setZonesSplit

    $lblZones = New-Object System.Windows.Forms.Label
    $lblZones.Text = 'Build Zones'
    $lblZones.ForeColor = $global:UGSM_ColorText
    $lblZones.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
    $lblZones.Location = New-Object System.Drawing.Point(50, 0)
    $lblZones.Size = New-Object System.Drawing.Size(180, 18)
    [void]$zonesHeader.Controls.Add($lblZones)

    $btnAddZone = New-UGSMButton -Text 'Add Zone' -X 0 -Y 50 -Width 90 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $btnRemoveZone = New-UGSMButton -Text 'Remove Zone' -X 100 -Y 50 -Width 100 -Height 24 -BackColor $global:UGSM_ColorDanger
    $btnApplyZone = New-UGSMButton -Text 'Apply Zone' -X 210 -Y 50 -Width 90 -Height 24 -BackColor '#F0A500'
    [void]$zonesHeader.Controls.Add($btnAddZone)
    [void]$zonesHeader.Controls.Add($btnRemoveZone)
    [void]$zonesHeader.Controls.Add($btnApplyZone)

    $lblZoneSelect = New-BBLabel -Text 'Zone' -X 0 -Y 24 -Width 50
    [void]$zonesHeader.Controls.Add($lblZoneSelect)

    $cmbZones = New-Object System.Windows.Forms.ComboBox
    $cmbZones.Location = New-Object System.Drawing.Point(55, 20)
    $cmbZones.Size = New-Object System.Drawing.Size(240, 24)
    $cmbZones.DropDownStyle = 'DropDownList'
    $cmbZones.BackColor = $global:UGSM_ColorInputBackground
    $cmbZones.ForeColor = $global:UGSM_ColorText
    [void]$zonesHeader.Controls.Add($cmbZones)

    foreach ($zone in @($data.Zones)) {
        $displayName = [string]$zone.Name
        if ([string]::IsNullOrWhiteSpace($displayName)) {
            $displayName = '[Unnamed Zone]'
        }
        [void]$cmbZones.Items.Add($displayName)
    }

    $zoneEditorHost = New-Object System.Windows.Forms.Panel
    $zoneEditorHost.Dock = 'Fill'
    $zoneEditorHost.Padding = New-Object System.Windows.Forms.Padding(12, 0, 100, 0)
    $zoneEditorHost.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$zonesSplit.Panel2.Controls.Add($zoneEditorHost)

    $zoneEditor = New-Object System.Windows.Forms.Panel
    $zoneEditor.Dock = 'Fill'
    $zoneEditor.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$zoneEditorHost.Controls.Add($zoneEditor)

    $zoneScroll = New-Object System.Windows.Forms.Panel
    $zoneScroll.Dock = 'Fill'
    $zoneScroll.AutoScroll = $true
    $zoneScroll.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$zoneEditor.Controls.Add($zoneScroll)

    $lblZoneEditor = New-Object System.Windows.Forms.Label
    $lblZoneEditor.Text = 'Zone Editor'
    $lblZoneEditor.ForeColor = $global:UGSM_ColorText
    $lblZoneEditor.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
    $lblZoneEditor.Location = New-Object System.Drawing.Point(120, 14)
    $lblZoneEditor.Size = New-Object System.Drawing.Size(140, 22)
    [void]$zoneScroll.Controls.Add($lblZoneEditor)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Name' -X 20 -Y 46 -Width 70))
    $txtZoneName = New-BBTextBox -X 100 -Y 44 -Width 220
    [void]$zoneScroll.Controls.Add($txtZoneName)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Center X' -X 20 -Y 80 -Width 70))
    $numZoneX = New-BBNumeric -X 100 -Y 78 -Min -1000000 -Max 1000000 -Decimals 3 -Width 140
    [void]$zoneScroll.Controls.Add($numZoneX)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Center Y' -X 20 -Y 114 -Width 70))
    $numZoneY = New-BBNumeric -X 100 -Y 112 -Min -1000000 -Max 1000000 -Decimals 3 -Width 140
    [void]$zoneScroll.Controls.Add($numZoneY)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Center Z' -X 20 -Y 148 -Width 70))
    $numZoneZ = New-BBNumeric -X 100 -Y 146 -Min -1000000 -Max 1000000 -Decimals 3 -Width 140
    [void]$zoneScroll.Controls.Add($numZoneZ)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Radius' -X 20 -Y 182 -Width 70))
    $numZoneRadius = New-BBNumeric -X 100 -Y 180 -Min 0 -Max 1000000 -Decimals 3 -Width 140
    [void]$zoneScroll.Controls.Add($numZoneRadius)

    $chkZoneWhitelist = New-BBCheck -Text 'Whitelist Zone' -X 100 -Y 214 -Width 180
    [void]$zoneScroll.Controls.Add($chkZoneWhitelist)

    [void]$zoneScroll.Controls.Add((New-BBLabel -Text 'Custom Msg' -X 20 -Y 246 -Width 80))
    $txtZoneMessage = New-BBTextBox -X 100 -Y 244 -Width 220
    [void]$zoneScroll.Controls.Add($txtZoneMessage)

    $itemsHeader = New-Object System.Windows.Forms.Label
    $itemsHeader.Text = 'Zone Items'
    $itemsHeader.ForeColor = $global:UGSM_ColorText
    $itemsHeader.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
    $itemsHeader.Location = New-Object System.Drawing.Point(20, 278)
    $itemsHeader.Size = New-Object System.Drawing.Size(120, 20)
    [void]$zoneScroll.Controls.Add($itemsHeader)

    $btnAddZoneItem = New-UGSMButton -Text 'Add Item' -X 100 -Y 304 -Width 80 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $btnRemoveZoneItem = New-UGSMButton -Text 'Remove' -X 188 -Y 304 -Width 80 -Height 24 -BackColor $global:UGSM_ColorDanger
    [void]$zoneScroll.Controls.Add($btnAddZoneItem)
    [void]$zoneScroll.Controls.Add($btnRemoveZoneItem)

    $gridZoneItems = New-BBListGrid
    $gridZoneItems.Location = New-Object System.Drawing.Point(20, 336)
    $gridZoneItems.Size = New-Object System.Drawing.Size(300, 200)
    $gridZoneItems.Anchor = 'Top,Left,Right'
    $null = $gridZoneItems.Columns.Add('ClassName', 'Class Name')
    [void]$zoneScroll.Controls.Add($gridZoneItems)

    $zoneScroll.AutoScrollMinSize = New-Object System.Drawing.Size(0, 570)

    $loadSelectedZone = {
        try {
            if ($cmbZones.SelectedIndex -lt 0) { return }

            $rowIndex = $cmbZones.SelectedIndex
            $zones = @($SettingsState.BaseBuildingData.Zones)
            if ($rowIndex -lt 0 -or $rowIndex -ge $zones.Count) { return }

            $zone = $zones[$rowIndex]
            $txtZoneName.Text = [string]$zone.Name

            try { $numZoneX.Value = [decimal]([double]$zone.Center[0]) } catch { $numZoneX.Value = 0 }
            try { $numZoneY.Value = [decimal]([double]$zone.Center[1]) } catch { $numZoneY.Value = 0 }
            try { $numZoneZ.Value = [decimal]([double]$zone.Center[2]) } catch { $numZoneZ.Value = 0 }
            try { $numZoneRadius.Value = [decimal]([double]$zone.Radius) } catch { $numZoneRadius.Value = 0 }

            $chkZoneWhitelist.Checked = ([int]$zone.IsWhitelist -eq 1)
            $txtZoneMessage.Text = [string]$zone.CustomMessage

            $gridZoneItems.Rows.Clear()
            foreach ($item in @($zone.Items)) {
                [void]$gridZoneItems.Rows.Add([string]$item)
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Loading build zone failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $applySelectedZone = {
        try {
            if ($cmbZones.SelectedIndex -lt 0) {
                throw 'Select a zone first.'
            }

            $rowIndex = $cmbZones.SelectedIndex
            $zones = New-Object System.Collections.ArrayList
            foreach ($z in @($SettingsState.BaseBuildingData.Zones)) { [void]$zones.Add($z) }

            if ($rowIndex -lt 0 -or $rowIndex -ge $zones.Count) {
                throw 'Selected zone index is invalid.'
            }

            $zone = $zones[$rowIndex]
            $zone.Name = $txtZoneName.Text
            $zone.Center = @(
                [double]$numZoneX.Value,
                [double]$numZoneY.Value,
                [double]$numZoneZ.Value
            )
            $zone.Radius = [double]$numZoneRadius.Value
            $zone.IsWhitelist = $(if ($chkZoneWhitelist.Checked) { 1 } else { 0 })
            $zone.CustomMessage = $txtZoneMessage.Text

            $items = New-Object System.Collections.ArrayList
            foreach ($row in @($gridZoneItems.Rows)) {
                if ($row.IsNewRow) { continue }
                $itemName = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($itemName)) { continue }
                [void]$items.Add($itemName)
            }
            $zone.Items = @($items)

            $SettingsState.BaseBuildingData.Zones = @($zones)

            $displayName = [string]$zone.Name
            if ([string]::IsNullOrWhiteSpace($displayName)) {
                $displayName = '[Unnamed Zone]'
            }
            $cmbZones.Items[$rowIndex] = $displayName

            if ($StatusLabel) { $StatusLabel.Text = 'Updated selected build zone.' }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Applying build zone failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $addZone = {
        $newZone = [pscustomobject]@{
            Name          = 'New Zone'
            Center        = @(0.0, 0.0, 0.0)
            Radius        = 100.0
            Items         = @()
            IsWhitelist   = 1
            CustomMessage = ''
        }

        $list = New-Object System.Collections.ArrayList
        foreach ($z in @($SettingsState.BaseBuildingData.Zones)) { [void]$list.Add($z) }
        [void]$list.Add($newZone)
        $SettingsState.BaseBuildingData.Zones = @($list)

        [void]$cmbZones.Items.Add('New Zone')
        $cmbZones.SelectedIndex = $cmbZones.Items.Count - 1
    }.GetNewClosure()

    $removeZone = {
        if ($cmbZones.SelectedIndex -lt 0) { return }

        $rowIndex = $cmbZones.SelectedIndex

        $list = New-Object System.Collections.ArrayList
        foreach ($z in @($SettingsState.BaseBuildingData.Zones)) { [void]$list.Add($z) }

        if ($rowIndex -ge 0 -and $rowIndex -lt $list.Count) {
            $list.RemoveAt($rowIndex)
            $SettingsState.BaseBuildingData.Zones = @($list)
            $cmbZones.Items.RemoveAt($rowIndex)

            if ($cmbZones.Items.Count -gt 0) {
                if ($rowIndex -ge $cmbZones.Items.Count) {
                    $cmbZones.SelectedIndex = $cmbZones.Items.Count - 1
                }
                else {
                    $cmbZones.SelectedIndex = $rowIndex
                }
            }
            else {
                $txtZoneName.Text = ''
                $numZoneX.Value = 0
                $numZoneY.Value = 0
                $numZoneZ.Value = 0
                $numZoneRadius.Value = 0
                $chkZoneWhitelist.Checked = $false
                $txtZoneMessage.Text = ''
                $gridZoneItems.Rows.Clear()
            }
        }
    }.GetNewClosure()

    $addSimpleListItem = {
        param($grid)
        [void]$grid.Rows.Add('NewClassName')
        $idx = $grid.Rows.Count - 1
        if ($idx -ge 0) {
            $grid.ClearSelection()
            $grid.Rows[$idx].Selected = $true
        }
    }.GetNewClosure()

    $removeSimpleListItem = {
        param($grid)
        if ($grid.SelectedRows.Count -gt 0) {
            $grid.Rows.Remove($grid.SelectedRows[0])
        }
    }.GetNewClosure()

    $saveBaseBuilding = {
        try {
            & $applySelectedZone

            $data = $SettingsState.BaseBuildingData
            if ($null -eq $data) {
                throw 'BaseBuilding settings are not loaded.'
            }

            $data.m_Version = [int]$numVersion.Value
            $data.CanBuildAnywhere = $(if ($chkCanBuildAnywhere.Checked) { 1 } else { 0 })
            $data.AllowBuildingWithoutATerritory = $(if ($chkAllowNoTerritory.Checked) { 1 } else { 0 })
            $data.CanCraftVanillaBasebuilding = $(if ($chkCraftVanilla.Checked) { 1 } else { 0 })
            $data.CanCraftExpansionBasebuilding = $(if ($chkCraftExpansion.Checked) { 1 } else { 0 })
            $data.DestroyFlagOnDismantle = $(if ($chkDestroyFlag.Checked) { 1 } else { 0 })
            $data.DismantleOutsideTerritory = $(if ($chkDismantleOutside.Checked) { 1 } else { 0 })
            $data.DismantleInsideTerritory = $(if ($chkDismantleInside.Checked) { 1 } else { 0 })
            $data.DismantleAnywhere = $(if ($chkDismantleAnywhere.Checked) { 1 } else { 0 })
            $data.CodelockActionsAnywhere = $(if ($chkCodeActionsAnywhere.Checked) { 1 } else { 0 })
            $data.CodeLockLength = [int]$numCodeLen.Value
            $data.DoDamageWhenEnterWrongCodeLock = $(if ($chkWrongCodeDamage.Checked) { 1 } else { 0 })
            $data.DamageWhenEnterWrongCodeLock = [double]$numWrongCodeDmg.Value
            $data.RememberCode = $(if ($chkRememberCode.Checked) { 1 } else { 0 })
            $data.CanCraftTerritoryFlagKit = $(if ($chkCraftFlagKit.Checked) { 1 } else { 0 })
            $data.SimpleTerritory = $(if ($chkSimpleTerritory.Checked) { 1 } else { 0 })
            $data.AutomaticFlagOnCreation = $(if ($chkAutoFlag.Checked) { 1 } else { 0 })
            $data.GetTerritoryFlagKitAfterBuild = $(if ($chkGetFlagBack.Checked) { 1 } else { 0 })
            $data.BuildZoneRequiredCustomMessage = $txtBuildMsg.Text
            $data.ZonesAreNoBuildZones = $(if ($chkZonesNoBuild.Checked) { 1 } else { 0 })
            $data.CodelockAttachMode = [int]$numAttachMode.Value
            $data.DismantleFlagMode = [int]$numDismantleFlagMode.Value
            $data.FlagMenuMode = [int]$numFlagMenuMode.Value
            $data.PreventItemAccessThroughObstructingItems = $(if ($chkPreventAccess.Checked) { 1 } else { 0 })
            $data.EnableVirtualStorage = $(if ($chkEnableVirtualStorage.Checked) { 1 } else { 0 })

            $outside = New-Object System.Collections.ArrayList
            foreach ($row in @($outsideSection.Grid.Rows)) {
                if ($row.IsNewRow) { continue }
                $value = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($value)) { continue }
                [void]$outside.Add($value)
            }
            $data.DeployableOutsideATerritory = @($outside)

            $enemy = New-Object System.Collections.ArrayList
            foreach ($row in @($enemySection.Grid.Rows)) {
                if ($row.IsNewRow) { continue }
                $value = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($value)) { continue }
                [void]$enemy.Add($value)
            }
            $data.DeployableInsideAEnemyTerritory = @($enemy)

            $virtual = New-Object System.Collections.ArrayList
            foreach ($row in @($virtualSection.Grid.Rows)) {
                if ($row.IsNewRow) { continue }
                $value = [string]$row.Cells['ClassName'].Value
                if ([string]::IsNullOrWhiteSpace($value)) { continue }
                [void]$virtual.Add($value)
            }
            $data.VirtualStorageExcludedContainers = @($virtual)

            $newRaw = ($data | ConvertTo-Json -Depth 100)

            [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
            [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $newRaw)

            if ($StatusLabel) {
                $StatusLabel.Text = ('Saved settings file: ' + [System.IO.Path]::GetFileName($FilePath))
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving BaseBuilding settings failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $SettingsState.CurrentSaveHandler = $saveBaseBuilding

    $outsideGrid = $outsideSection.Grid
    $enemyGrid = $enemySection.Grid
    $virtualGrid = $virtualSection.Grid

    $outsideSection.AddButton.Add_Click(({ & $addSimpleListItem $outsideGrid }).GetNewClosure())
    $outsideSection.RemoveButton.Add_Click(({ & $removeSimpleListItem $outsideGrid }).GetNewClosure())

    $enemySection.AddButton.Add_Click(({ & $addSimpleListItem $enemyGrid }).GetNewClosure())
    $enemySection.RemoveButton.Add_Click(({ & $removeSimpleListItem $enemyGrid }).GetNewClosure())

    $virtualSection.AddButton.Add_Click(({ & $addSimpleListItem $virtualGrid }).GetNewClosure())
    $virtualSection.RemoveButton.Add_Click(({ & $removeSimpleListItem $virtualGrid }).GetNewClosure())

    $cmbZones.Add_SelectedIndexChanged($loadSelectedZone)
    $btnApplyZone.Add_Click($applySelectedZone)
    $btnAddZone.Add_Click($addZone)
    $btnRemoveZone.Add_Click($removeZone)
    $zoneItemsGrid = $gridZoneItems
    $btnAddZoneItem.Add_Click(({ & $addSimpleListItem $zoneItemsGrid }).GetNewClosure())
    $btnRemoveZoneItem.Add_Click(({ & $removeSimpleListItem $zoneItemsGrid }).GetNewClosure())
    $btnSaveBase.Add_Click($saveBaseBuilding)

    if ($cmbZones.Items.Count -gt 0) {
        $cmbZones.SelectedIndex = 0
    }
}

function Show-DayZExpansionSettingEditor_HardlineSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $HostPanel.Controls.Clear()

    $rootPanel = New-Object System.Windows.Forms.Panel
