    try { $numLegendaryRequirement.Value = [decimal]([int]$data.LegendaryItemRequirement) } catch { $numLegendaryRequirement.Value = 0 }
    try { $numMythicRequirement.Value = [decimal]([int]$data.MythicItemRequirement) } catch { $numMythicRequirement.Value = 0 }
    try { $numExoticRequirement.Value = [decimal]([int]$data.ExoticItemRequirement) } catch { $numExoticRequirement.Value = 0 }

    $chkShowHardlineHUD.Checked = ([int]$data.ShowHardlineHUD -eq 1)
    $chkUseReputation.Checked = ([int]$data.UseReputation -eq 1)
    $chkUseFactionReputation.Checked = ([int]$data.UseFactionReputation -eq 1)
    $chkEnableFactionPersistence.Checked = ([int]$data.EnableFactionPersistence -eq 1)
    $chkEnableItemRarity.Checked = ([int]$data.EnableItemRarity -eq 1)
    $chkUseItemRarityIcons.Checked = ([int]$data.UseItemRarityOnInventoryIcons -eq 1)
    $chkUseItemRarityPurchase.Checked = ([int]$data.UseItemRarityForMarketPurchase -eq 1)
    $chkUseItemRaritySell.Checked = ([int]$data.UseItemRarityForMarketSell -eq 1)

    $mapsLayout = New-Object System.Windows.Forms.TableLayoutPanel
    $mapsLayout.Dock = 'None'
    $mapsLayout.Location = New-Object System.Drawing.Point(0, 0)
    $mapsLayout.Size = New-Object System.Drawing.Size(1500, 760)
    $mapsLayout.ColumnCount = 1
    $mapsLayout.RowCount = 2
    $mapsLayout.ColumnStyles.Clear()
    $mapsLayout.RowStyles.Clear()
    $mapsLayout.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Absolute, 1500)))
    $mapsLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 270)))
    $mapsLayout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 470)))
    [void]$mapsPanel.Controls.Add($mapsLayout)

    function New-HLMapSection {
        param(
            [string]$Title,
            [string[]]$Columns,
            [string[]]$Headers,
            [int]$HeaderHeight = 64
        )

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'
        $panel.Padding = New-Object System.Windows.Forms.Padding(0, 0, 8, 0)
        $panel.BackColor = $global:UGSM_ColorBackground

        $header = New-Object System.Windows.Forms.Panel
        $header.Dock = 'Top'
        $header.Height = $HeaderHeight
        $header.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($header)

        $body = New-Object System.Windows.Forms.Panel
        $body.Dock = 'Fill'
        $body.Padding = New-Object System.Windows.Forms.Padding(0, ($HeaderHeight + 2), 0, 0)
        $body.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($body)

        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = $Title
        $lbl.ForeColor = $global:UGSM_ColorText
        $lbl.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        $lbl.Location = New-Object System.Drawing.Point(0, 0)
        $lbl.Size = New-Object System.Drawing.Size(300, 18)
        [void]$header.Controls.Add($lbl)

        $btnAdd = New-UGSMButton -Text 'Add' -X 0 -Y 26 -Width 70 -Height 24 -BackColor $UGSM_ExpansionAccentColor
        $btnRemove = New-UGSMButton -Text 'Remove' -X 80 -Y 26 -Width 80 -Height 24 -BackColor $global:UGSM_ColorDanger
        [void]$header.Controls.Add($btnAdd)
        [void]$header.Controls.Add($btnRemove)

        $grid = New-HLGrid
        for ($i = 0; $i -lt $Columns.Count; $i++) {
            [void]$grid.Columns.Add($Columns[$i], $Headers[$i])
        }
        [void]$body.Controls.Add($grid)

        return [pscustomobject]@{
            Panel        = $panel
            Header       = $header
            Grid         = $grid
            AddButton    = $btnAdd
            RemoveButton = $btnRemove
        }
    }

    $entitySection = New-HLMapSection -Title 'Entity Reputation' -Columns @('ClassName', 'Reputation') -Headers @('Class Name', 'Reputation') -HeaderHeight 58
    $itemRaritySection = New-HLMapSection -Title 'Item Rarity' -Columns @('ClassName', 'Rarity') -Headers @('Class Name', 'Rarity') -HeaderHeight 90

    [void]$mapsLayout.Controls.Add($entitySection.Panel, 0, 0)
    [void]$mapsLayout.Controls.Add($itemRaritySection.Panel, 0, 1)

    $entityGrid = $entitySection.Grid
    $itemRarityGrid = $itemRaritySection.Grid

    $entityProps = @()
    try {
        $entityNode = Get-UGSMJsonPropertyValue -Object $data -Name 'EntityReputation' -DefaultValue $null
        if ($null -ne $entityNode -and $null -ne $entityNode.PSObject) {
            $entityProps = @($entityNode.PSObject.Properties)
        }
    }
    catch {
        $entityProps = @()
    }
    foreach ($prop in $entityProps) {
        [void]$entityGrid.Rows.Add([string]$prop.Name, [int]$prop.Value)
    }

    $entityGrid.AutoSizeColumnsMode = 'None'
    $entityGrid.Columns['ClassName'].Width = 740
    $entityGrid.Columns['Reputation'].Width = 140

    $itemRarityRows = New-Object System.Collections.ArrayList
    $itemRarityProps = @()
    try {
        $itemNode = Get-UGSMJsonPropertyValue -Object $data -Name 'ItemRarity' -DefaultValue $null
        if ($null -ne $itemNode -and $null -ne $itemNode.PSObject) {
            $itemRarityProps = @($itemNode.PSObject.Properties)
        }
    }
    catch {
        $itemRarityProps = @()
    }
    foreach ($prop in $itemRarityProps) {
        if (-not [string]::IsNullOrWhiteSpace($prop.Name)) {
            [void]$itemRarityRows.Add([pscustomobject]@{ ClassName = [string]$prop.Name; Rarity = [int]$prop.Value })
        }
    }

    $itemRarityGrid.AutoSizeColumnsMode = 'None'
    $itemRarityGrid.MultiSelect = $true
    $itemRarityGrid.Columns['ClassName'].Width = 1040
    $itemRarityGrid.Columns['Rarity'].Width = 80

    $btnImportItemRarity = New-UGSMButton -Text 'Import Missing From Market' -X 170 -Y 26 -Width 170 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $lblItemRaritySearch = New-HLLabel -Text 'Search' -X 360 -Y 6 -Width 60
    $txtItemRaritySearch = New-HLTextBox -X 360 -Y 26 -Width 170
    $btnItemRarityClear = New-UGSMButton -Text 'Clear' -X 540 -Y 26 -Width 70 -Height 24 -BackColor $global:UGSM_ColorNeutral
    $lblApplyItemRarity = New-HLLabel -Text 'Set Rarity' -X 620 -Y 6 -Width 80
    $numApplyItemRarity = New-HLNumeric -X 620 -Y 26 -Min 1 -Max 11 -Width 70
    $btnApplySelectedItemRarity = New-UGSMButton -Text 'Apply To Selected' -X 700 -Y 26 -Width 130 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $btnApplyFilteredItemRarity = New-UGSMButton -Text 'Apply To All' -X 840 -Y 26 -Width 125 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $lblItemRarityCount = New-HLLabel -Text '0/0' -X 980 -Y 30 -Width 100

    [void]$itemRaritySection.Header.Controls.Add($btnImportItemRarity)
    [void]$itemRaritySection.Header.Controls.Add($lblItemRaritySearch)
    [void]$itemRaritySection.Header.Controls.Add($txtItemRaritySearch)
    [void]$itemRaritySection.Header.Controls.Add($btnItemRarityClear)
    [void]$itemRaritySection.Header.Controls.Add($lblApplyItemRarity)
    [void]$itemRaritySection.Header.Controls.Add($numApplyItemRarity)
    [void]$itemRaritySection.Header.Controls.Add($btnApplySelectedItemRarity)
    [void]$itemRaritySection.Header.Controls.Add($btnApplyFilteredItemRarity)
    [void]$itemRaritySection.Header.Controls.Add($lblItemRarityCount)

    $btnNominalAuto = New-UGSMButton -Text 'Set From Nominal' -X 176 -Y 54 -Width 150 -Height 24 -BackColor $UGSM_ExpansionAccentColor
    $btnNominalUpdate = New-UGSMButton -Text 'Reapply Nominal (Caution)' -X 334 -Y 54 -Width 188 -Height 24 -BackColor '#C97A00'
    $lblNominalInfo = New-HLLabel -Text 'Opens editable nominal thresholds. Values persist for this editor session.' -X 534 -Y 58 -Width 520
    [void]$itemRaritySection.Header.Controls.Add($btnNominalAuto)
    [void]$itemRaritySection.Header.Controls.Add($btnNominalUpdate)
    [void]$itemRaritySection.Header.Controls.Add($lblNominalInfo)
    $itemRaritySection.Header.Height = 90

    $refreshItemRarityGrid = {
        $needle = ([string]$txtItemRaritySearch.Text).Trim().ToLowerInvariant()
        $itemRarityGrid.SuspendLayout()
        try {
            $itemRarityGrid.Rows.Clear()
            $visible = 0
            foreach ($entry in @($itemRarityRows)) {
                if ($null -eq $entry) { continue }
                $className = [string]$entry.ClassName
                if ([string]::IsNullOrWhiteSpace($needle) -or $className.ToLowerInvariant().Contains($needle)) {
                    [void]$itemRarityGrid.Rows.Add($className, [int]$entry.Rarity)
                    $visible++
                }
            }
            $lblItemRarityCount.Text = ('{0}/{1}' -f $visible, $itemRarityRows.Count)
        }
        finally {
            $itemRarityGrid.ResumeLayout()
        }
    }.GetNewClosure()

    & $refreshItemRarityGrid

    $script:importMissingItemRarityFromMarket = {
        
        try {
            $instance = $null
            try { $instance = $SettingsState.Instance } catch {}
            if ($null -eq $instance -or [string]::IsNullOrWhiteSpace([string]$instance.Id)) {
                throw 'Instance context is unavailable.'
            }

            $paths = Get-UGSMGameDayZExpansionPaths -Instance $instance
            $marketRoot = Join-Path ([string]$paths.ProfileExpansionRoot) 'Market'
            if (-not (Test-Path -LiteralPath $marketRoot -PathType Container)) {
                throw "Market folder not found at: $marketRoot"
            }

            $marketFiles = @(Get-ChildItem -LiteralPath $marketRoot -Filter '*.json' -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch '\.bak($|\.)' } |
                Sort-Object Name)
            
            if ($marketFiles.Count -eq 0) {
                throw 'No market files were found in the folder.'
            }

            # --- Form Setup ---
            $picker = New-Object System.Windows.Forms.Form
            $picker.Text = 'Import Missing Item Rarity'
            $picker.StartPosition = 'CenterParent'
            $picker.Size = New-Object System.Drawing.Size(520, 560)
            $picker.BackColor = $global:UGSM_ColorBackground
            $picker.ForeColor = $global:UGSM_ColorText
            $picker.FormBorderStyle = 'FixedDialog'
            $picker.MaximizeBox = $false

            $clb = New-Object System.Windows.Forms.CheckedListBox
            $clb.Location = New-Object System.Drawing.Point(12, 12)
            $clb.Size = New-Object System.Drawing.Size(480, 400)
            $clb.CheckOnClick = $true
            $clb.BackColor = $global:UGSM_ColorInputBackground
            $clb.ForeColor = $global:UGSM_ColorText
            $clb.BorderStyle = 'FixedSingle'
            foreach ($file in $marketFiles) {
                $isChecked = ($file.BaseName -ine 'NO_Sell')
                [void]$clb.Items.Add($file.Name, $isChecked)
            }
            [void]$picker.Controls.Add($clb)

            # --- Selection Buttons ---
            $btnAll = New-UGSMButton -Text 'Select All' -X 12 -Y 420 -Width 90 -Height 26 -BackColor $global:UGSM_ColorNeutral
            $btnNone = New-UGSMButton -Text 'Clear' -X 110 -Y 420 -Width 70 -Height 26 -BackColor $global:UGSM_ColorNeutral
            [void]$picker.Controls.Add($btnAll)
            [void]$picker.Controls.Add($btnNone)

            $btnAll.Add_Click({ for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $true) } })
            $btnNone.Add_Click({ for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $false) } })

            $btnImport = New-UGSMButton -Text 'Import' -X 320 -Y 470 -Width 80 -Height 30 -BackColor $UGSM_ExpansionAccentColor
            $btnCancel = New-UGSMButton -Text 'Cancel' -X 410 -Y 470 -Width 80 -Height 30 -BackColor $global:UGSM_ColorNeutral
            [void]$picker.Controls.Add($btnImport)
            [void]$picker.Controls.Add($btnCancel)
            
            $btnImport.Add_Click({ $picker.DialogResult = [System.Windows.Forms.DialogResult]::OK; $picker.Close() })
            $btnCancel.Add_Click({ $picker.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $picker.Close() })

            if ($picker.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }

            # --- Execution ---
            $selectedFiles = @()
            foreach ($checked in @($clb.CheckedItems)) { $selectedFiles += [string]$checked }
            
            # Build current lookup to avoid duplicates
            $existing = @{}
            foreach ($entry in @($itemRarityRows)) {
                if ($null -ne $entry -and -not [string]::IsNullOrWhiteSpace($entry.ClassName)) {
                    $existing[$entry.ClassName.Trim().ToLowerInvariant()] = $true
                }
            }

            $added = 0
            $defaultRarity = [int]$numDefaultItemRarity.Value

            foreach ($fileName in $selectedFiles) {
                try {
                    $fullPath = Join-Path $marketRoot $fileName
                    $marketRaw = Read-UGSMGameDayZTextFileSafe -Path $fullPath
                    if ([string]::IsNullOrWhiteSpace($marketRaw)) { continue }
                    
                    $marketData = $marketRaw | ConvertFrom-Json #-Depth 100
                    
                    # Logic to handle both "Items":[] and flat arrays
                    $items = @()
                    if ($null -ne $marketData.Items) { $items = @($marketData.Items) }
                    elseif ($marketData -is [array]) { $items = $marketData }
                    else { $items = @($marketData) }

                    foreach ($item in $items) {
                        $candidates = New-Object System.Collections.Generic.List[string]
                        
                        # Get Main ClassName
                        if ($item.ClassName) { [void]$candidates.Add([string]$item.ClassName) }
                        
                        # Get Variants
                        if ($item.Variants) { 
                            foreach ($v in $item.Variants) {
                                if ($v -is [string]) { [void]$candidates.Add($v) }
                                elseif ($v.ClassName) { [void]$candidates.Add([string]$v.ClassName) }
                            }
                        }

                        foreach ($name in $candidates) {
                            $clean = [string]$name.Trim()
                            if ([string]::IsNullOrWhiteSpace($clean) -or $clean -match '@\{') { continue }
                            
                            $lower = $clean.ToLowerInvariant()
                            if (-not $existing.ContainsKey($lower)) {
                                [void]$itemRarityRows.Add([pscustomobject]@{ ClassName = $clean; Rarity = $defaultRarity })
                                $existing[$lower] = $true
                                $added++
                            }
                        }
                    }
                }
                catch {
                    Write-UGSMGameDayZExpansionSafeLog -Level 'Warn' -Message ("Import file error. File={0}; Error={1}" -f $fileName, $_.Exception.Message)
                }
            }
            
            & $refreshItemRarityGrid
            if ($StatusLabel) { $StatusLabel.Text = "Import complete. Added $added new items." }
            Write-UGSMGameDayZExpansionSafeLog -Level 'Info' -Message ("Import complete. Added={0}" -f $added)
        }
        catch {
            Write-UGSMGameDayZExpansionSafeLog -Level 'Error' -Message ("Critical import error: {0}" -f $_.Exception.Message)
        }
    }.GetNewClosure()

    $syncItemRarityFromGrid = {
        $lookup = @{}
        foreach ($row in @($itemRarityGrid.Rows)) {
            if ($row.IsNewRow) { continue }
            $className = [string]$row.Cells['ClassName'].Value
            if ([string]::IsNullOrWhiteSpace($className)) { continue }
            $rarityValue = 2
            try { $rarityValue = [int]$row.Cells['Rarity'].Value } catch { $rarityValue = 2 }
            $lookup[$className] = $rarityValue
        }
        foreach ($entry in @($itemRarityRows)) {
            if ($null -ne $entry -and $lookup.ContainsKey([string]$entry.ClassName)) {
                $entry.Rarity = [int]$lookup[[string]$entry.ClassName]
            }
        }
    }.GetNewClosure()

    $applyToSelectedItemRarity = {
        try {
            $value = [int]$numApplyItemRarity.Value
            if ($itemRarityGrid.SelectedRows.Count -le 0) { return }
            foreach ($row in @($itemRarityGrid.SelectedRows)) {
                if ($null -eq $row -or $row.IsNewRow) { continue }
                $row.Cells['Rarity'].Value = $value
            }
            & $syncItemRarityFromGrid
        }
        catch { }
    }.GetNewClosure()

    $applyToMatchedItemRarity = {
        try {
            $value = [int]$numApplyItemRarity.Value
            foreach ($row in @($itemRarityGrid.Rows)) {
                if ($row.IsNewRow) { continue }
                $row.Cells['Rarity'].Value = $value
            }
            & $syncItemRarityFromGrid
        }
        catch { }
    }.GetNewClosure()

    $addEntityRow = {
        [void]$entityGrid.Rows.Add('NewEntityClass', 0)
    }.GetNewClosure()

    $removeEntityRow = {
        if ($entityGrid.SelectedRows.Count -gt 0) {
            foreach ($row in @($entityGrid.SelectedRows)) {
                if ($null -ne $row -and -not $row.IsNewRow) { $entityGrid.Rows.Remove($row) }
            }
        }
    }.GetNewClosure()

    $addItemRarityRow = {
        $newName = 'NewItemClass'
        [void]$itemRarityRows.Add([pscustomobject]@{ ClassName = $newName; Rarity = 2 })
        & $refreshItemRarityGrid
    }.GetNewClosure()

    $removeItemRarityRow = {
        # 1. Capture the ClassNames of everything selected in the Grid
        $selectedNames = New-Object System.Collections.Generic.HashSet[string]
        foreach ($row in @($itemRarityGrid.SelectedRows)) {
            if ($null -eq $row -or $row.IsNewRow) { continue }
            $name = [string]$row.Cells['ClassName'].Value
            if (-not [string]::IsNullOrWhiteSpace($name)) {
                [void]$selectedNames.Add($name.ToLowerInvariant())
            }
        }

        if ($selectedNames.Count -le 0) { return }

        # 2. Remove matching entries from the existing ArrayList in place
        $toRemove = New-Object System.Collections.ArrayList
        foreach ($entry in @($itemRarityRows)) {
            if ($null -eq $entry) { continue }
            $entryName = [string]$entry.ClassName
            if (-not [string]::IsNullOrWhiteSpace($entryName) -and $selectedNames.Contains($entryName.ToLowerInvariant())) {
                [void]$toRemove.Add($entry)
            }
        }

        foreach ($entry in @($toRemove)) {
            [void]$itemRarityRows.Remove($entry)
        }

        # 3. Refresh the grid from the updated backing list
        & $refreshItemRarityGrid

        # 4. Update the count label
        $lblItemRarityCount.Text = ('{0}/{1}' -f $itemRarityGrid.Rows.Count, $itemRarityRows.Count)

        Write-UGSMGameDayZExpansionSafeLog -Level 'Info' -Message ("Removed selected list items. Count={0}" -f $selectedNames.Count)
    }.GetNewClosure()

    if (-not $SettingsState.PSObject.Properties['NominalRarityThresholds']) {
    $SettingsState | Add-Member -NotePropertyName NominalRarityThresholds -NotePropertyValue ([ordered]@{
        Common    = 100
        Uncommon  = 75
        Rare      = 50
        Epic      = 20
        Legendary = 10
        Mythic    = 10
        Exotic    = 1
    }) -Force
}

$invokeNominalRarityUpdate = {
    param([bool]$RequireConfirmation)

    try {
        $instance = $null
        try { $instance = $SettingsState.Instance } catch {}
        if ($null -eq $instance -or [string]::IsNullOrWhiteSpace([string]$instance.Id)) {
            throw 'Instance context is unavailable.'
        }

        $typesPath = Get-UGSMDayZTypesXmlPath -Instance $instance
        if ([string]::IsNullOrWhiteSpace([string]$typesPath) -or -not (Test-Path -LiteralPath $typesPath -PathType Leaf)) {
            throw 'types.xml could not be resolved for this instance.'
        }

        $storedThresholds = $SettingsState.NominalRarityThresholds
        if ($null -eq $storedThresholds) {
            $storedThresholds = [ordered]@{
                Common    = 20
                Uncommon  = 12
                Rare      = 8
                Epic      = 5
                Legendary = 3
                Mythic    = 2
                Exotic    = 1
            }
            $SettingsState.NominalRarityThresholds = $storedThresholds
        }

        $dlg = New-Object System.Windows.Forms.Form
        $dlg.Text = 'Nominal To Rarity Thresholds'
        $dlg.StartPosition = 'CenterParent'
        $dlg.Size = New-Object System.Drawing.Size(420, 450)
        $dlg.FormBorderStyle = 'FixedDialog'
        $dlg.MaximizeBox = $false
        $dlg.MinimizeBox = $false
        $dlg.BackColor = $global:UGSM_ColorBackground
        $dlg.ForeColor = $global:UGSM_ColorText

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(12, 12)
        $panel.Size = New-Object System.Drawing.Size(380, 320)
        $panel.BackColor = $global:UGSM_ColorBackground
        [void]$dlg.Controls.Add($panel)

        $info = New-Object System.Windows.Forms.Label
        $info.Text = 'Set the minimum nominal required for each rarity. Highest matching threshold wins.'
        $info.Location = New-Object System.Drawing.Point(0, 0)
        $info.Size = New-Object System.Drawing.Size(372, 40)
        $info.ForeColor = $global:UGSM_ColorText
        $info.Font = New-Object System.Drawing.Font('Segoe UI', 8)
        [void]$panel.Controls.Add($info)

        $thresholdKeys = @('Common','Uncommon','Rare','Epic','Legendary','Mythic','Exotic')
        $inputs = [ordered]@{}
        $y = 52

        foreach ($key in $thresholdKeys) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = "$key >= nominal"
            $lbl.Location = New-Object System.Drawing.Point(0, $y)
            $lbl.Size = New-Object System.Drawing.Size(160, 20)
            $lbl.ForeColor = $global:UGSM_ColorText
            $lbl.Font = New-Object System.Drawing.Font('Segoe UI', 8.5)
            [void]$panel.Controls.Add($lbl)

            $num = New-Object System.Windows.Forms.NumericUpDown
            $num.Location = New-Object System.Drawing.Point(180, ($y - 2))
            $num.Size = New-Object System.Drawing.Size(120, 24)
            $num.Minimum = 0
            $num.Maximum = 1000000
            $num.BackColor = $global:UGSM_ColorInputBackground
            $num.ForeColor = $global:UGSM_ColorText
            $num.BorderStyle = 'FixedSingle'
            try { $num.Value = [decimal][int]$storedThresholds[$key] } catch { $num.Value = 0 }
            [void]$panel.Controls.Add($num)

            $inputs[$key] = $num
            $y += 32
        }

        $warn = New-Object System.Windows.Forms.Label
        $warn.Text = if ($RequireConfirmation) {
            'Caution: this will overwrite current rarity values for matching Hardline items.'
        } else {
            'This updates current Hardline rows using nominal values from types.xml.'
        }
        $warn.Location = New-Object System.Drawing.Point(12, 334)
        $warn.Size = New-Object System.Drawing.Size(378, 32)
        $warn.ForeColor = $global:UGSM_ColorText
        $warn.Font = New-Object System.Drawing.Font('Segoe UI', 8)
        [void]$dlg.Controls.Add($warn)

        $btnApply = New-UGSMButton -Text 'Apply' -X 224 -Y 382 -Width 80 -Height 28 -BackColor $UGSM_ExpansionAccentColor
        $btnCancel = New-UGSMButton -Text 'Cancel' -X 312 -Y 382 -Width 80 -Height 28 -BackColor $global:UGSM_ColorNeutral
        [void]$dlg.Controls.Add($btnApply)
        [void]$dlg.Controls.Add($btnCancel)

        $btnApply.Add_Click({ $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK; $dlg.Close() })
        $btnCancel.Add_Click({ $dlg.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $dlg.Close() })

        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }

        foreach ($key in $thresholdKeys) {
            $SettingsState.NominalRarityThresholds[$key] = [int]$inputs[$key].Value
        }

        if ($RequireConfirmation) {
            $confirm = [System.Windows.Forms.MessageBox]::Show(
                'Reapply rarity using nominal thresholds for all current Hardline items that exist in types.xml?',
                'Confirm nominal rarity update',
                [System.Windows.Forms.MessageBoxButtons]::OKCancel,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            )
            if ($confirm -ne [System.Windows.Forms.DialogResult]::OK) { return }
        }

        [xml]$typesXml = Get-Content -LiteralPath $typesPath -Raw -ErrorAction Stop
        $nominalLookup = @{}
        foreach ($typeNode in @($typesXml.types.type)) {
            try {
                $typeName = [string]$typeNode.name
                if ([string]::IsNullOrWhiteSpace($typeName)) { continue }

                $nominalValue = 0
                try { $nominalValue = [int]([string]$typeNode.nominal) } catch { $nominalValue = 0 }

                $nominalLookup[$typeName.Trim().ToLowerInvariant()] = $nominalValue
            }
            catch { }
        }

        $rules = @(
            [pscustomobject]@{ Rarity = 2; Min = [int]$SettingsState.NominalRarityThresholds['Common'] },
            [pscustomobject]@{ Rarity = 3; Min = [int]$SettingsState.NominalRarityThresholds['Uncommon'] },
            [pscustomobject]@{ Rarity = 4; Min = [int]$SettingsState.NominalRarityThresholds['Rare'] },
            [pscustomobject]@{ Rarity = 5; Min = [int]$SettingsState.NominalRarityThresholds['Epic'] },
            [pscustomobject]@{ Rarity = 6; Min = [int]$SettingsState.NominalRarityThresholds['Legendary'] },
            [pscustomobject]@{ Rarity = 7; Min = [int]$SettingsState.NominalRarityThresholds['Mythic'] },
            [pscustomobject]@{ Rarity = 8; Min = [int]$SettingsState.NominalRarityThresholds['Exotic'] }
        ) | Sort-Object Min -Descending

        $updated = 0
        $missing = 0

        foreach ($entry in @($itemRarityRows)) {
            if ($null -eq $entry) { continue }

            $className = [string]$entry.ClassName
            if ([string]::IsNullOrWhiteSpace($className)) { continue }

            $lookupKey = $className.Trim().ToLowerInvariant()
            if (-not $nominalLookup.ContainsKey($lookupKey)) {
                $missing++
                continue
            }

            $nominal = [int]$nominalLookup[$lookupKey]
            $newRarity = 1

            foreach ($rule in $rules) {
                if ($nominal -ge [int]$rule.Min) {
                    $newRarity = [int]$rule.Rarity
                    break
                }
            }

            if ([int]$entry.Rarity -ne $newRarity) {
                $entry.Rarity = $newRarity
                $updated++
            }
        }

        & $refreshItemRarityGrid
        if ($StatusLabel) {
            $StatusLabel.Text = ('Nominal rarity update complete. Updated {0} items. Missing in types.xml: {1}.' -f $updated, $missing)
        }
    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Nominal rarity update failed: ' + $_.Exception.Message
        }
    }
}.GetNewClosure()


    $saveHardline = {
        try {
            & $syncItemRarityFromGrid
            $out = [pscustomobject]@{
                m_Version                      = [int]$numVersion.Value
                PoorItemRequirement            = [int]$numPoorRequirement.Value
                CommonItemRequirement          = [int]$numCommonRequirement.Value
                UncommonItemRequirement        = [int]$numUncommonRequirement.Value
                RareItemRequirement            = [int]$numRareRequirement.Value
                EpicItemRequirement            = [int]$numEpicRequirement.Value
                LegendaryItemRequirement       = [int]$numLegendaryRequirement.Value
                MythicItemRequirement          = [int]$numMythicRequirement.Value
                ExoticItemRequirement          = [int]$numExoticRequirement.Value
                ShowHardlineHUD                = if ($chkShowHardlineHUD.Checked) { 1 } else { 0 }
                UseReputation                  = if ($chkUseReputation.Checked) { 1 } else { 0 }
                UseFactionReputation           = if ($chkUseFactionReputation.Checked) { 1 } else { 0 }
                EnableFactionPersistence       = if ($chkEnableFactionPersistence.Checked) { 1 } else { 0 }
                EnableItemRarity               = if ($chkEnableItemRarity.Checked) { 1 } else { 0 }
                UseItemRarityOnInventoryIcons  = if ($chkUseItemRarityIcons.Checked) { 1 } else { 0 }
                UseItemRarityForMarketPurchase = if ($chkUseItemRarityPurchase.Checked) { 1 } else { 0 }
                UseItemRarityForMarketSell     = if ($chkUseItemRaritySell.Checked) { 1 } else { 0 }
                MaxReputation                  = [int]$numMaxReputation.Value
                ReputationLossOnDeath          = [int]$numReputationLoss.Value
                DefaultItemRarity              = [int]$numDefaultItemRarity.Value
                EntityReputation               = @{}
                ItemRarity                     = @{}
            }
            foreach ($row in @($entityGrid.Rows)) {
                if ($row.IsNewRow) { continue }
                $out.EntityReputation[[string]$row.Cells['ClassName'].Value] = [int]$row.Cells['Reputation'].Value
            }
            foreach ($entry in $itemRarityRows) {
                $out.ItemRarity[[string]$entry.ClassName] = [int]$entry.Rarity
            }
            $json = $out | ConvertTo-Json -Depth 100
            [System.IO.File]::WriteAllText($SettingsState.CurrentFilePath, $json)
            if ($StatusLabel) { $StatusLabel.Text = 'Hardline settings saved successfully.' }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving Hardline settings failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $SettingsState.CurrentSaveHandler = $saveHardline
    $entitySection.AddButton.Add_Click($addEntityRow)
    $entitySection.RemoveButton.Add_Click($removeEntityRow)
    $itemRaritySection.AddButton.Add_Click($addItemRarityRow)
    $itemRaritySection.RemoveButton.Add_Click($removeItemRarityRow)
    $txtItemRaritySearch.Add_TextChanged($refreshItemRarityGrid)
    $btnItemRarityClear.Add_Click({ $txtItemRaritySearch.Text = '' }.GetNewClosure())
    $btnApplySelectedItemRarity.Add_Click($applyToSelectedItemRarity)
    $btnApplyFilteredItemRarity.Add_Click($applyToMatchedItemRarity)
    $btnImportItemRarity.Add_Click({ & $script:importMissingItemRarityFromMarket })
    $btnNominalAuto.Add_Click({ & $invokeNominalRarityUpdate $false }.GetNewClosure())
    $btnNominalUpdate.Add_Click({ & $invokeNominalRarityUpdate $true }.GetNewClosure())
}

function Show-DayZExpansionSettingEditor_MapSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $HostPanel.Controls.Clear()

    $rootPanel = New-Object System.Windows.Forms.Panel
    $rootPanel.Dock = 'Fill'
    $rootPanel.BackColor = $global:UGSM_ColorBackground
    [void]$HostPanel.Controls.Add($rootPanel)

    $scrollBody = New-Object System.Windows.Forms.Panel
    $scrollBody.Dock = 'Fill'
    $scrollBody.AutoScroll = $true
    $scrollBody.BackColor = $global:UGSM_ColorBackground
    [void]$rootPanel.Controls.Add($scrollBody)

    $contentPanel = New-Object System.Windows.Forms.Panel
    $contentPanel.Location = New-Object System.Drawing.Point(0, 0)
    $contentPanel.Size = New-Object System.Drawing.Size(1640, 980)
    $contentPanel.BackColor = $global:UGSM_ColorBackground
    [void]$scrollBody.Controls.Add($contentPanel)

    $topPanel = New-Object System.Windows.Forms.Panel
    $topPanel.Location = New-Object System.Drawing.Point(0, 0)
    $topPanel.Size = New-Object System.Drawing.Size(1640, 280)
    $topPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($topPanel)

    $markersPanel = New-Object System.Windows.Forms.Panel
    $markersPanel.Location = New-Object System.Drawing.Point(0, 310)
    $markersPanel.Size = New-Object System.Drawing.Size(1640, 620)
    $markersPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($markersPanel)

    function New-MSLabel {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 160)
        return (New-UGSMLabel -Text $Text -X $X -Y $Y -Width $Width -Height 18 -FontSize 8.5 -Color $global:UGSM_ColorText)
    }

    function New-MSNumeric {
        param(
            [int]$X, [int]$Y,
            [decimal]$Min = -2147483648,
            [decimal]$Max = 2147483647,
            [int]$Decimals = 0,
            [int]$Width = 100
        )
        $num = New-Object System.Windows.Forms.NumericUpDown
        $num.Location = New-Object System.Drawing.Point($X, $Y)
        $num.Size = New-Object System.Drawing.Size($Width, 24)
        $num.Minimum = $Min
        $num.Maximum = $Max
        $num.DecimalPlaces = $Decimals
        $num.BackColor = $global:UGSM_ColorInputBackground
        $num.ForeColor = $global:UGSM_ColorText
        $num.BorderStyle = 'FixedSingle'
        return $num
    }

    function New-MSTextBox {
        param([int]$X, [int]$Y, [int]$Width = 220)
        $tb = New-Object System.Windows.Forms.TextBox
        $tb.Location = New-Object System.Drawing.Point($X, $Y)
        $tb.Size = New-Object System.Drawing.Size($Width, 24)
        $tb.BorderStyle = 'FixedSingle'
        $tb.BackColor = $global:UGSM_ColorInputBackground
        $tb.ForeColor = $global:UGSM_ColorText
        return $tb
    }

    function New-MSCheck {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 250)
        $chk = New-Object System.Windows.Forms.CheckBox
        $chk.Text = $Text
        $chk.ForeColor = $global:UGSM_ColorText
        $chk.Location = New-Object System.Drawing.Point($X, $Y)
        $chk.Size = New-Object System.Drawing.Size($Width, 24)
        return $chk
    }

    function New-MSGrid {
        $grid = New-Object System.Windows.Forms.DataGridView
        $grid.Dock = 'Fill'
        $grid.BackgroundColor = $global:UGSM_ColorInputBackground
        $grid.ForeColor = $global:UGSM_ColorText
        $grid.BorderStyle = 'FixedSingle'
        $grid.AllowUserToAddRows = $false
        $grid.AllowUserToDeleteRows = $false
        $grid.AllowUserToResizeRows = $false
        $grid.SelectionMode = 'FullRowSelect'
        $grid.MultiSelect = $false
        $grid.AutoSizeColumnsMode = 'Fill'
        $grid.RowHeadersVisible = $false
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersHeightSizeMode = 'DisableResizing'
        $grid.ColumnHeadersHeight = 22
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $grid.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $grid.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        return $grid
    }

    function New-MapColorEditor {
        param(
            [System.Windows.Forms.Control]$Parent,
            [string]$LabelText,
            [int]$X,
            [int]$Y,
            [int]$LabelWidth = 130,
            [int]$TextWidth = 110
        )

        [void]$Parent.Controls.Add((New-MSLabel -Text $LabelText -X $X -Y $Y -Width $LabelWidth))

        $txt = New-MSTextBox -X ($X + $LabelWidth + 5) -Y ($Y - 2) -Width $TextWidth
        [void]$Parent.Controls.Add($txt)

        $btn = New-UGSMButton -Text 'Pick' -X ($X + $LabelWidth + $TextWidth + 15) -Y ($Y - 4) -Width 60 -Height 24 -BackColor $UGSM_ExpansionAccentColor
        [void]$Parent.Controls.Add($btn)

        $preview = New-Object System.Windows.Forms.Panel
        $preview.Location = New-Object System.Drawing.Point(($X + $LabelWidth + $TextWidth + 85), ($Y - 2))
        $preview.Size = New-Object System.Drawing.Size(26, 24)
        $preview.BorderStyle = 'FixedSingle'
        $preview.BackColor = $global:UGSM_ColorText
        [void]$Parent.Controls.Add($preview)

        return [pscustomobject]@{
            TextBox = $txt
            Button  = $btn
            Preview = $preview
        }
