    $compassBadgesColorEditor.TextBox.Text = [string]$data.CompassBadgesColor

    $syncColorPreview = {
        param($TextBox, $PreviewPanel)

        try {
            $PreviewPanel.BackColor = [System.Drawing.Color]::FromArgb([int]$TextBox.Text)
        }
        catch {
            $PreviewPanel.BackColor = [System.Drawing.Color]::Black
        }
    }.GetNewClosure()

    $pickMapColor = {
        param($TextBox, $PreviewPanel)

        try {
            $dialog = New-Object System.Windows.Forms.ColorDialog
            $dialog.FullOpen = $true
            $dialog.AnyColor = $true
            $dialog.SolidColorOnly = $false

            try {
                $dialog.Color = [System.Drawing.Color]::FromArgb([int]$TextBox.Text)
            }
            catch { }

            if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $TextBox.Text = [string]([int]$dialog.Color.ToArgb())
                $PreviewPanel.BackColor = $dialog.Color
            }
        }
        catch {
