    $btnRemoveMarker = New-UGSMButton -Text 'Remove Marker' -X 105 -Y 26 -Width 110 -Height 24 -BackColor $global:UGSM_ColorDanger
    $btnApplyMarker = New-UGSMButton -Text 'Apply Marker' -X 225 -Y 26 -Width 95 -Height 24 -BackColor '#F0A500'
    [void]$markersHeader.Controls.Add($btnAddMarker)
    [void]$markersHeader.Controls.Add($btnRemoveMarker)
    [void]$markersHeader.Controls.Add($btnApplyMarker)

    $gridMarkers = New-MSGrid
    $gridMarkers.AutoSizeColumnsMode = 'None'
    $null = $gridMarkers.Columns.Add('UID', 'UID')
    $null = $gridMarkers.Columns.Add('Text', 'Text')
    $null = $gridMarkers.Columns.Add('IconName', 'Icon')
    $gridMarkers.Columns['UID'].Width = 220
    $gridMarkers.Columns['Text'].Width = 250
    $gridMarkers.Columns['IconName'].Width = 130
    [void]$markersLeft.Controls.Add($gridMarkers)

    foreach ($marker in @($data.ServerMarkers)) {
        [void]$gridMarkers.Rows.Add([string]$marker.m_UID, [string]$marker.m_Text, [string]$marker.m_IconName)
    }

    $markerEditorHost = New-Object System.Windows.Forms.Panel
    $markerEditorHost.Dock = 'Fill'
    $markerEditorHost.Padding = New-Object System.Windows.Forms.Padding(12, 0, 40, 0)
    $markerEditorHost.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$markersSplit.Panel2.Controls.Add($markerEditorHost)

    $markerEditor = New-Object System.Windows.Forms.Panel
    $markerEditor.Dock = 'Fill'
    $markerEditor.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$markerEditorHost.Controls.Add($markerEditor)

    $markerScroll = New-Object System.Windows.Forms.Panel
    $markerScroll.Dock = 'Fill'
    $markerScroll.AutoScroll = $true
    $markerScroll.BackColor = [System.Drawing.Color]::FromArgb(24, 28, 36)
    [void]$markerEditor.Controls.Add($markerScroll)

    $lblMarkerEditor = New-Object System.Windows.Forms.Label
    $lblMarkerEditor.Text = 'Marker Editor'
    $lblMarkerEditor.ForeColor = $global:UGSM_ColorText
    $lblMarkerEditor.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
    $lblMarkerEditor.Location = New-Object System.Drawing.Point(20, 10)
    $lblMarkerEditor.Size = New-Object System.Drawing.Size(140, 22)
    [void]$markerScroll.Controls.Add($lblMarkerEditor)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'UID' -X 20 -Y 44 -Width 70))
    $txtMarkerUID = New-MSTextBox -X 115 -Y 42 -Width 240
    [void]$markerScroll.Controls.Add($txtMarkerUID)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Text' -X 20 -Y 76 -Width 70))
    $txtMarkerText = New-MSTextBox -X 115 -Y 74 -Width 240
    [void]$markerScroll.Controls.Add($txtMarkerText)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Icon' -X 20 -Y 108 -Width 70))

    $cmbMarkerIcon = New-Object System.Windows.Forms.ComboBox
    $cmbMarkerIcon.Location = New-Object System.Drawing.Point(115, 106)
    $cmbMarkerIcon.Size = New-Object System.Drawing.Size(180, 24)
    $cmbMarkerIcon.DropDownStyle = 'DropDownList'
    $cmbMarkerIcon.BackColor = $global:UGSM_ColorInputBackground
    $cmbMarkerIcon.ForeColor = $global:UGSM_ColorText
    [void]$markerScroll.Controls.Add($cmbMarkerIcon)

    try {
        foreach ($iconName in @(Get-UGSMGameDayZExpansionDefaultIcons)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$iconName)) {
                [void]$cmbMarkerIcon.Items.Add([string]$iconName)
            }
        }
    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Loading marker icons failed: ' + $_.Exception.Message
        }
    }

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Visibility' -X 20 -Y 140 -Width 70))
