    [void]$markerScroll.Controls.Add($chkMarkerIs3D)
    [void]$markerScroll.Controls.Add($chkMarkerLocked)
    [void]$markerScroll.Controls.Add($chkMarkerPersist)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Pos X' -X 20 -Y 204 -Width 70))
