    [void]$markerScroll.Controls.Add($numMarkerX)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Pos Y' -X 20 -Y 236 -Width 70))
    $numMarkerY = New-MSNumeric -X 115 -Y 234 -Min -1000000 -Max 1000000 -Decimals 3 -Width 100
    [void]$markerScroll.Controls.Add($numMarkerY)

    [void]$markerScroll.Controls.Add((New-MSLabel -Text 'Pos Z' -X 20 -Y 268 -Width 70))
    $numMarkerZ = New-MSNumeric -X 115 -Y 266 -Min -1000000 -Max 1000000 -Decimals 3 -Width 100
    [void]$markerScroll.Controls.Add($numMarkerZ)

    $markerColorEditor = New-MapColorEditor -Parent $markerScroll -LabelText 'Marker Color' -X 20 -Y 304 -LabelWidth 90

    $markerScroll.AutoScrollMinSize = New-Object System.Drawing.Size(0, 360)

    $loadSelectedMarker = {
        try {
            if ($gridMarkers.SelectedRows.Count -le 0) { return }

            $rowIndex = $gridMarkers.SelectedRows[0].Index
            $markers = @($SettingsState.MapSettingsData.ServerMarkers)
            if ($rowIndex -lt 0 -or $rowIndex -ge $markers.Count) { return }

            $marker = $markers[$rowIndex]
            $txtMarkerUID.Text = [string]$marker.m_UID
            $txtMarkerText.Text = [string]$marker.m_Text
            $markerIconName = [string]$marker.m_IconName
            if (-not [string]::IsNullOrWhiteSpace($markerIconName)) {
                $iconIndex = $cmbMarkerIcon.Items.IndexOf($markerIconName)
                if ($iconIndex -ge 0) {
                    $cmbMarkerIcon.SelectedIndex = $iconIndex
                }
                else {
                    [void]$cmbMarkerIcon.Items.Add($markerIconName)
                    $cmbMarkerIcon.SelectedIndex = $cmbMarkerIcon.Items.Count - 1
                }
            }
            else {
                $cmbMarkerIcon.SelectedIndex = -1
            }

            try { $numMarkerVisibility.Value = [decimal]([int]$marker.m_Visibility) } catch { $numMarkerVisibility.Value = 0 }
            $chkMarkerIs3D.Checked = ([int]$marker.m_Is3D -eq 1)
            $chkMarkerLocked.Checked = ([int]$marker.m_Locked -eq 1)
            $chkMarkerPersist.Checked = ([int]$marker.m_Persist -eq 1)

            try { $numMarkerX.Value = [decimal]([double]$marker.m_Position[0]) } catch { $numMarkerX.Value = 0 }
            try { $numMarkerY.Value = [decimal]([double]$marker.m_Position[1]) } catch { $numMarkerY.Value = 0 }
            try { $numMarkerZ.Value = [decimal]([double]$marker.m_Position[2]) } catch { $numMarkerZ.Value = 0 }

            $markerColorEditor.TextBox.Text = [string]$marker.m_Color
            & $syncColorPreview $markerColorEditor.TextBox $markerColorEditor.Preview
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Loading server marker failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $applySelectedMarker = {
        try {
            if ($gridMarkers.SelectedRows.Count -le 0) {
                throw 'Select a marker first.'
            }

            $rowIndex = $gridMarkers.SelectedRows[0].Index
            $markers = New-Object System.Collections.ArrayList
            foreach ($m in @($SettingsState.MapSettingsData.ServerMarkers)) { [void]$markers.Add($m) }

            if ($rowIndex -lt 0 -or $rowIndex -ge $markers.Count) {
                throw 'Selected marker index is invalid.'
            }

            $marker = $markers[$rowIndex]
            $marker.m_UID = $txtMarkerUID.Text
            $marker.m_Visibility = [int]$numMarkerVisibility.Value
            $marker.m_Is3D = $(if ($chkMarkerIs3D.Checked) { 1 } else { 0 })
            $marker.m_Text = $txtMarkerText.Text
            $marker.m_IconName = $(if ($cmbMarkerIcon.SelectedItem) { [string]$cmbMarkerIcon.SelectedItem } else { '' })
            try { $marker.m_Color = [int]$markerColorEditor.TextBox.Text } catch { $marker.m_Color = -1 }
            $marker.m_Position = @(
                [double]$numMarkerX.Value,
                [double]$numMarkerY.Value,
                [double]$numMarkerZ.Value
            )
            $marker.m_Locked = $(if ($chkMarkerLocked.Checked) { 1 } else { 0 })
            $marker.m_Persist = $(if ($chkMarkerPersist.Checked) { 1 } else { 0 })

            $SettingsState.MapSettingsData.ServerMarkers = @($markers)

            $gridMarkers.Rows[$rowIndex].Cells['UID'].Value = [string]$marker.m_UID
            $gridMarkers.Rows[$rowIndex].Cells['Text'].Value = [string]$marker.m_Text
            $gridMarkers.Rows[$rowIndex].Cells['IconName'].Value = [string]$marker.m_IconName

            if ($StatusLabel) { $StatusLabel.Text = 'Updated selected server marker.' }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Applying server marker failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $addMarker = {
        $newMarker = [pscustomobject]@{
            m_UID        = 'New_ServerMarker'
            m_Visibility = 6
            m_Is3D       = 1
            m_Text       = 'New Marker'
            m_IconName   = 'Marker'
            m_Color      = -1
            m_Position   = @(0.0, 0.0, 0.0)
            m_Locked     = 0
            m_Persist    = 1
        }

        if ($cmbMarkerIcon.Items.Count -gt 0) {
            $cmbMarkerIcon.SelectedIndex = 0
        }

        $list = New-Object System.Collections.ArrayList
        foreach ($m in @($SettingsState.MapSettingsData.ServerMarkers)) { [void]$list.Add($m) }
        [void]$list.Add($newMarker)
        $SettingsState.MapSettingsData.ServerMarkers = @($list)

        $idx = $gridMarkers.Rows.Add([string]$newMarker.m_UID, [string]$newMarker.m_Text, [string]$newMarker.m_IconName)
        $gridMarkers.ClearSelection()
        $gridMarkers.Rows[$idx].Selected = $true
    }.GetNewClosure()

    $removeMarker = {
        if ($gridMarkers.SelectedRows.Count -le 0) { return }

        $rowIndex = $gridMarkers.SelectedRows[0].Index
        $list = New-Object System.Collections.ArrayList
        foreach ($m in @($SettingsState.MapSettingsData.ServerMarkers)) { [void]$list.Add($m) }

        if ($rowIndex -ge 0 -and $rowIndex -lt $list.Count) {
            $list.RemoveAt($rowIndex)
            $SettingsState.MapSettingsData.ServerMarkers = @($list)
            $gridMarkers.Rows.RemoveAt($rowIndex)

            if ($gridMarkers.Rows.Count -gt 0) {
                $newIndex = [Math]::Min($rowIndex, $gridMarkers.Rows.Count - 1)
                $gridMarkers.ClearSelection()
                $gridMarkers.Rows[$newIndex].Selected = $true
            }
            else {
                $txtMarkerUID.Text = ''
                $txtMarkerText.Text = ''
                $cmbMarkerIcon.SelectedIndex = -1
                $numMarkerVisibility.Value = 0
                $chkMarkerIs3D.Checked = $false
                $chkMarkerLocked.Checked = $false
                $chkMarkerPersist.Checked = $false
                $numMarkerX.Value = 0
                $numMarkerY.Value = 0
                $numMarkerZ.Value = 0
                $markerColorEditor.TextBox.Text = '-1'
                & $syncColorPreview $markerColorEditor.TextBox $markerColorEditor.Preview
            }
        }
    }.GetNewClosure()

    $markerColorEditor.Button.Add_Click(({ & $pickMapColor $markerColorEditor.TextBox $markerColorEditor.Preview }).GetNewClosure())
    $markerColorEditor.TextBox.Add_TextChanged(({ & $syncColorPreview $markerColorEditor.TextBox $markerColorEditor.Preview }).GetNewClosure())

    $saveMapSettings = {
        try {
            & $applySelectedMarker

            $data = $SettingsState.MapSettingsData
            if ($null -eq $data) {
                throw 'Map settings are not loaded.'
            }

            $data.m_Version = [int]$numVersion.Value
            $data.EnableMap = $(if ($chkEnableMap.Checked) { 1 } else { 0 })
            $data.UseMapOnMapItem = $(if ($chkUseMapOnMapItem.Checked) { 1 } else { 0 })
            $data.ShowPlayerPosition = [int]$numShowPlayerPosition.Value
            $data.ShowMapStats = $(if ($chkShowMapStats.Checked) { 1 } else { 0 })
            $data.NeedPenItemForCreateMarker = $(if ($chkNeedPenItemForCreateMarker.Checked) { 1 } else { 0 })
            $data.NeedGPSItemForCreateMarker = $(if ($chkNeedGPSItemForCreateMarker.Checked) { 1 } else { 0 })
            $data.CanCreateMarker = $(if ($chkCanCreateMarker.Checked) { 1 } else { 0 })
            $data.CanCreate3DMarker = $(if ($chkCanCreate3DMarker.Checked) { 1 } else { 0 })
            $data.CanOpenMapWithKeyBinding = $(if ($chkCanOpenMapWithKeyBinding.Checked) { 1 } else { 0 })
            $data.ShowDistanceOnPersonalMarkers = $(if ($chkShowDistanceOnPersonalMarkers.Checked) { 1 } else { 0 })
            $data.EnableHUDGPS = $(if ($chkEnableHUDGPS.Checked) { 1 } else { 0 })
            $data.NeedGPSItemForKeyBinding = $(if ($chkNeedGPSItemForKeyBinding.Checked) { 1 } else { 0 })
            $data.NeedMapItemForKeyBinding = $(if ($chkNeedMapItemForKeyBinding.Checked) { 1 } else { 0 })
            $data.EnableServerMarkers = $(if ($chkEnableServerMarkers.Checked) { 1 } else { 0 })
            $data.ShowNameOnServerMarkers = $(if ($chkShowNameOnServerMarkers.Checked) { 1 } else { 0 })
            $data.ShowDistanceOnServerMarkers = $(if ($chkShowDistanceOnServerMarkers.Checked) { 1 } else { 0 })
            $data.EnableHUDCompass = $(if ($chkEnableHUDCompass.Checked) { 1 } else { 0 })
            $data.NeedCompassItemForHUDCompass = $(if ($chkNeedCompassItemForHUDCompass.Checked) { 1 } else { 0 })
            $data.NeedGPSItemForHUDCompass = $(if ($chkNeedGPSItemForHUDCompass.Checked) { 1 } else { 0 })

            try { $data.CompassColor = [int]$compassColorEditor.TextBox.Text } catch { $data.CompassColor = -1 }
            $data.CreateDeathMarker = $(if ($chkCreateDeathMarker.Checked) { 1 } else { 0 })
            $data.PlayerLocationNotifier = $(if ($chkPlayerLocationNotifier.Checked) { 1 } else { 0 })
            try { $data.CompassBadgesColor = [int]$compassBadgesColorEditor.TextBox.Text } catch { $data.CompassBadgesColor = -1 }

            $newMarkers = New-Object System.Collections.ArrayList
            foreach ($marker in @($data.ServerMarkers)) {
                [void]$newMarkers.Add([pscustomobject]@{
                        m_UID        = [string]$marker.m_UID
                        m_Visibility = [int]$marker.m_Visibility
                        m_Is3D       = [int]$marker.m_Is3D
                        m_Text       = [string]$marker.m_Text
                        m_IconName   = [string]$marker.m_IconName
                        m_Color      = [int]$marker.m_Color
                        m_Position   = @(
                            [double]$marker.m_Position[0],
                            [double]$marker.m_Position[1],
                            [double]$marker.m_Position[2]
                        )
                        m_Locked     = [int]$marker.m_Locked
                        m_Persist    = [int]$marker.m_Persist
                    })
            }
            $data.ServerMarkers = @($newMarkers)

            $newRaw = ($data | ConvertTo-Json -Depth 100)

            [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
            [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $newRaw)

            if ($StatusLabel) {
                $StatusLabel.Text = ('Saved settings file: ' + [System.IO.Path]::GetFileName($FilePath))
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving MapSettings failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $SettingsState.CurrentSaveHandler = $saveMapSettings

    $gridMarkers.Add_SelectionChanged($loadSelectedMarker)
    $btnAddMarker.Add_Click($addMarker)
    $btnRemoveMarker.Add_Click($removeMarker)
    $btnApplyMarker.Add_Click($applySelectedMarker)
    $btnSaveMap.Add_Click($saveMapSettings)

    if ($gridMarkers.Rows.Count -gt 0) {
        $gridMarkers.ClearSelection()
        $gridMarkers.Rows[0].Selected = $true
        & $loadSelectedMarker
    }
}

function Show-DayZExpansionSettingEditor_MarketSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    $HostPanel.Controls.Clear()

    $rootPanel = New-Object System.Windows.Forms.Panel
    $rootPanel.Dock = 'Fill'
    $rootPanel.BackColor = $global:UGSM_ColorBackground
    [void]$HostPanel.Controls.Add($rootPanel)

    $scrollBody = New-Object System.Windows.Forms.Panel
    $scrollBody.Dock = 'Fill'
    $scrollBody.AutoScroll = $true
    $scrollBody.BackColor = $global:UGSM_ColorBackground
    [void]$rootPanel.Controls.Add($scrollBody)

    $contentPanel = New-Object System.Windows.Forms.Panel
    $contentPanel.Location = New-Object System.Drawing.Point(0, 0)
    $contentPanel.Size = New-Object System.Drawing.Size(1540, 1180)
    $contentPanel.BackColor = $global:UGSM_ColorBackground
    [void]$scrollBody.Controls.Add($contentPanel)

    $topPanel = New-Object System.Windows.Forms.Panel
    $topPanel.Location = New-Object System.Drawing.Point(0, 0)
    $topPanel.Size = New-Object System.Drawing.Size(1540, 230)
    $topPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($topPanel)

    $listsPanel = New-Object System.Windows.Forms.Panel
    $listsPanel.Location = New-Object System.Drawing.Point(0, 240)
    $listsPanel.Size = New-Object System.Drawing.Size(1540, 180)
    $listsPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($listsPanel)

    $colorsPanel = New-Object System.Windows.Forms.Panel
    $colorsPanel.Location = New-Object System.Drawing.Point(0, 430)
    $colorsPanel.Size = New-Object System.Drawing.Size(1540, 190)
    $colorsPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($colorsPanel)

    $spawnsPanel = New-Object System.Windows.Forms.Panel
    $spawnsPanel.Location = New-Object System.Drawing.Point(0, 630)
    $spawnsPanel.Size = New-Object System.Drawing.Size(1540, 460)
    $spawnsPanel.BackColor = $global:UGSM_ColorBackground
    [void]$contentPanel.Controls.Add($spawnsPanel)

    function New-MKLabel {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 170)
        return (New-UGSMLabel -Text $Text -X $X -Y $Y -Width $Width -Height 18 -FontSize 8.5 -Color $global:UGSM_ColorText)
    }

    function New-MKNumeric {
        param(
            [int]$X,
            [int]$Y,
            [decimal]$Min = -1000000000,
            [decimal]$Max = 1000000000,
            [int]$Decimals = 0,
            [int]$Width = 110
        )

        $num = New-Object System.Windows.Forms.NumericUpDown
        $num.Location = New-Object System.Drawing.Point($X, $Y)
        $num.Size = New-Object System.Drawing.Size($Width, 24)
        $num.Minimum = $Min
        $num.Maximum = $Max
        $num.DecimalPlaces = $Decimals
        $num.BackColor = $global:UGSM_ColorInputBackground
        $num.ForeColor = $global:UGSM_ColorText
        $num.BorderStyle = 'FixedSingle'
        return $num
    }

    function New-MKTextBox {
        param([int]$X, [int]$Y, [int]$Width = 220)

        $tb = New-Object System.Windows.Forms.TextBox
        $tb.Location = New-Object System.Drawing.Point($X, $Y)
        $tb.Size = New-Object System.Drawing.Size($Width, 24)
        $tb.BorderStyle = 'FixedSingle'
        $tb.BackColor = $global:UGSM_ColorInputBackground
        $tb.ForeColor = $global:UGSM_ColorText
        return $tb
    }

    function New-MKCheck {
        param([string]$Text, [int]$X, [int]$Y, [int]$Width = 260)

        $chk = New-Object System.Windows.Forms.CheckBox
        $chk.Text = $Text
        $chk.ForeColor = $global:UGSM_ColorText
        $chk.Location = New-Object System.Drawing.Point($X, $Y)
        $chk.Size = New-Object System.Drawing.Size($Width, 24)
        return $chk
    }

    function New-MKGrid {
        $grid = New-Object System.Windows.Forms.DataGridView
        $grid.Dock = 'Fill'
        $grid.BackgroundColor = $global:UGSM_ColorInputBackground
        $grid.ForeColor = $global:UGSM_ColorText
        $grid.BorderStyle = 'FixedSingle'
        $grid.AllowUserToAddRows = $false
        $grid.AllowUserToDeleteRows = $false
        $grid.AllowUserToResizeRows = $false
        $grid.SelectionMode = 'FullRowSelect'
        $grid.MultiSelect = $false
        $grid.AutoSizeColumnsMode = 'Fill'
        $grid.RowHeadersVisible = $false
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersHeightSizeMode = 'DisableResizing'
        $grid.ColumnHeadersHeight = 22
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $grid.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $grid.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        return $grid
    }

    function New-MKListSection {
        param(
            [string]$Title,
            [string]$ColumnName,
            [string]$HeaderText
        )

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'
        $panel.Padding = New-Object System.Windows.Forms.Padding(0, 0, 8, 0)
        $panel.BackColor = $global:UGSM_ColorBackground

        $header = New-Object System.Windows.Forms.Panel
        $header.Dock = 'Top'
        $header.Height = 50
        $header.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($header)

        $body = New-Object System.Windows.Forms.Panel
        $body.Dock = 'Fill'
        $body.Padding = New-Object System.Windows.Forms.Padding(0, 52, 0, 0)
        $body.BackColor = $global:UGSM_ColorBackground
        [void]$panel.Controls.Add($body)

        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = $Title
        $lbl.ForeColor = $global:UGSM_ColorText
        $lbl.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        $lbl.Location = New-Object System.Drawing.Point(0, 0)
        $lbl.Size = New-Object System.Drawing.Size(260, 18)
        [void]$header.Controls.Add($lbl)

        $btnAdd = New-UGSMButton -Text 'Add' -X 0 -Y 24 -Width 70 -Height 24 -BackColor $UGSM_ExpansionAccentColor
        $btnRemove = New-UGSMButton -Text 'Remove' -X 80 -Y 24 -Width 80 -Height 24 -BackColor $global:UGSM_ColorDanger
        [void]$header.Controls.Add($btnAdd)
        [void]$header.Controls.Add($btnRemove)

        $grid = New-MKGrid
        $null = $grid.Columns.Add($ColumnName, $HeaderText)
        [void]$body.Controls.Add($grid)

        return [pscustomobject]@{
            Panel        = $panel
            Grid         = $grid
            AddButton    = $btnAdd
            RemoveButton = $btnRemove
        }
    }

    function New-MKColorPreview {
        param([int]$X, [int]$Y)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point($X, $Y)
        $panel.Size = New-Object System.Drawing.Size(28, 24)
        $panel.BorderStyle = 'FixedSingle'
        $panel.BackColor = $global:UGSM_ColorText
        return $panel
    }

    $convertMKHexToColor = {
        param([string]$Value)

        try {
            if ([string]::IsNullOrWhiteSpace($Value)) {
                return $global:UGSM_ColorText
            }

            $text = $Value.Trim()
            if ($text.StartsWith('#')) {
                $text = $text.Substring(1)
            }

            if ($text.Length -ne 8) {
                return $global:UGSM_ColorText
            }

            $r = [Convert]::ToInt32($text.Substring(0, 2), 16)
            $g = [Convert]::ToInt32($text.Substring(2, 2), 16)
            $b = [Convert]::ToInt32($text.Substring(4, 2), 16)
            $a = [Convert]::ToInt32($text.Substring(6, 2), 16)

            return [System.Drawing.Color]::FromArgb($a, $r, $g, $b)
        }
        catch {
            return $global:UGSM_ColorText
        }
    }.GetNewClosure()

    $convertMKColorToHex = {
        param([System.Drawing.Color]$Color)

        try {
            return ('{0:X2}{1:X2}{2:X2}{3:X2}' -f $Color.R, $Color.G, $Color.B, $Color.A)
        }
        catch {
            return 'FFFFFFFF'
        }
    }.GetNewClosure()

    $raw = Read-UGSMGameDayZTextFileSafe -Path $FilePath
    $data = $raw | ConvertFrom-Json

    $SettingsState.FileHandler = 'MarketSettings'
    $SettingsState.CurrentFilePath = [string]$FilePath
    $SettingsState.MarketSettingsData = $data

    $topLeft = New-Object System.Windows.Forms.Panel
    $topLeft.Location = New-Object System.Drawing.Point(0, 16)
    $topLeft.Size = New-Object System.Drawing.Size(500, 205)
    $topLeft.BackColor = $global:UGSM_ColorBackground
    [void]$topPanel.Controls.Add($topLeft)

    $topMid = New-Object System.Windows.Forms.Panel
    $topMid.Location = New-Object System.Drawing.Point(515, 16)
    $topMid.Size = New-Object System.Drawing.Size(500, 205)
    $topMid.BackColor = $global:UGSM_ColorBackground
    [void]$topPanel.Controls.Add($topMid)

    $topRight = New-Object System.Windows.Forms.Panel
    $topRight.Location = New-Object System.Drawing.Point(1030, 16)
    $topRight.Size = New-Object System.Drawing.Size(560, 205)
    $topRight.BackColor = $global:UGSM_ColorBackground
    [void]$topPanel.Controls.Add($topRight)

    [void]$topLeft.Controls.Add((New-MKLabel -Text 'Version' -X 0 -Y 8 -Width 90))
    $numVersion = New-MKNumeric -X 170 -Y 6 -Min 0 -Max 9999 -Width 100
    [void]$topLeft.Controls.Add($numVersion)

    $chkMarketSystemEnabled = New-MKCheck -Text 'Market System Enabled' -X 0 -Y 40 -Width 220
    [void]$topLeft.Controls.Add($chkMarketSystemEnabled)

    [void]$topLeft.Controls.Add((New-MKLabel -Text 'Currency Icon' -X 0 -Y 72 -Width 120))
    $txtCurrencyIcon = New-MKTextBox -X 170 -Y 70 -Width 320
    [void]$topLeft.Controls.Add($txtCurrencyIcon)

    [void]$topLeft.Controls.Add((New-MKLabel -Text 'Sell Price Percent' -X 0 -Y 104 -Width 120))
    $numSellPricePercent = New-MKNumeric -X 170 -Y 102 -Min 0 -Max 1000 -Decimals 2 -Width 100
    [void]$topLeft.Controls.Add($numSellPricePercent)

    [void]$topLeft.Controls.Add((New-MKLabel -Text 'Network Batch Size' -X 0 -Y 136 -Width 130))
    $numNetworkBatchSize = New-MKNumeric -X 170 -Y 134 -Min 0 -Max 1000000 -Width 100
    [void]$topLeft.Controls.Add($numNetworkBatchSize)

    $chkATMSystemEnabled = New-MKCheck -Text 'ATM System Enabled' -X 0 -Y 8 -Width 220
    [void]$topMid.Controls.Add($chkATMSystemEnabled)

    [void]$topMid.Controls.Add((New-MKLabel -Text 'Max Deposit Money' -X 0 -Y 40 -Width 130))
    $numMaxDepositMoney = New-MKNumeric -X 180 -Y 38 -Min 0 -Max 1000000000 -Width 120
    [void]$topMid.Controls.Add($numMaxDepositMoney)

    [void]$topMid.Controls.Add((New-MKLabel -Text 'Default Deposit Money' -X 0 -Y 72 -Width 140))
    $numDefaultDepositMoney = New-MKNumeric -X 180 -Y 70 -Min 0 -Max 1000000000 -Width 120
    [void]$topMid.Controls.Add($numDefaultDepositMoney)

    $chkATMPlayerTransferEnabled = New-MKCheck -Text 'ATM Player Transfer Enabled' -X 0 -Y 104 -Width 240
    $chkATMPartyLockerEnabled = New-MKCheck -Text 'ATM Party Locker Enabled' -X 250 -Y 104 -Width 230
    $chkUseWholeMapForATMPlayerList = New-MKCheck -Text 'Use Whole Map For ATM Player List' -X 0 -Y 132 -Width 270
    [void]$topMid.Controls.Add($chkATMPlayerTransferEnabled)
    [void]$topMid.Controls.Add($chkATMPartyLockerEnabled)
    [void]$topMid.Controls.Add($chkUseWholeMapForATMPlayerList)

    [void]$topMid.Controls.Add((New-MKLabel -Text 'Max Party Deposit Money' -X 0 -Y 164 -Width 150))
    $numMaxPartyDepositMoney = New-MKNumeric -X 180 -Y 162 -Min 0 -Max 1000000000 -Width 120
    [void]$topMid.Controls.Add($numMaxPartyDepositMoney)

    [void]$topRight.Controls.Add((New-MKLabel -Text 'Max Vehicle Distance' -X 0 -Y 8 -Width 140))
    $numMaxVehicleDistanceToTrader = New-MKNumeric -X 180 -Y 6 -Min 0 -Max 1000000 -Decimals 2 -Width 120
    [void]$topRight.Controls.Add($numMaxVehicleDistanceToTrader)

    [void]$topRight.Controls.Add((New-MKLabel -Text 'Max Large Vehicle Dist' -X 0 -Y 40 -Width 150))
    $numMaxLargeVehicleDistanceToTrader = New-MKNumeric -X 180 -Y 38 -Min 0 -Max 1000000 -Decimals 2 -Width 120
    [void]$topRight.Controls.Add($numMaxLargeVehicleDistanceToTrader)

    [void]$topRight.Controls.Add((New-MKLabel -Text 'Max SZ Parking Time' -X 0 -Y 72 -Width 140))
    $numMaxSZVehicleParkingTime = New-MKNumeric -X 180 -Y 70 -Min 0 -Max 100000000 -Decimals 2 -Width 120
    [void]$topRight.Controls.Add($numMaxSZVehicleParkingTime)

    [void]$topRight.Controls.Add((New-MKLabel -Text 'Parking Ticket Fine' -X 0 -Y 104 -Width 140))
    $numSZVehicleParkingTicketFine = New-MKNumeric -X 180 -Y 102 -Min 0 -Max 1000000000 -Width 120
    [void]$topRight.Controls.Add($numSZVehicleParkingTicketFine)

    $chkSZVehicleParkingFineUseKey = New-MKCheck -Text 'Parking Fine Uses Key' -X 0 -Y 136 -Width 220
    $chkDisallowUnpersisted = New-MKCheck -Text 'Disallow Unpersisted' -X 250 -Y 136 -Width 220
    $chkDisableClientSellTransactionDetails = New-MKCheck -Text 'Disable Client Sell Details' -X 0 -Y 164 -Width 250
    [void]$topRight.Controls.Add($chkSZVehicleParkingFineUseKey)
    [void]$topRight.Controls.Add($chkDisallowUnpersisted)
    [void]$topRight.Controls.Add($chkDisableClientSellTransactionDetails)

    $btnSaveMarketSettings = New-UGSMButton -Text 'Save MarketSettings' -X 300 -Y 170 -Width 170 -Height 28 -BackColor '#F0A500'
    [void]$topRight.Controls.Add($btnSaveMarketSettings)

    try { $numVersion.Value = [decimal]([int]$data.m_Version) } catch { $numVersion.Value = 0 }
    $chkMarketSystemEnabled.Checked = ([int]$data.MarketSystemEnabled -eq 1)
    $txtCurrencyIcon.Text = [string]$data.CurrencyIcon
    try { $numSellPricePercent.Value = [decimal]([double]$data.SellPricePercent) } catch { $numSellPricePercent.Value = 75 }
    try { $numNetworkBatchSize.Value = [decimal]([int]$data.NetworkBatchSize) } catch { $numNetworkBatchSize.Value = 100 }

    $chkATMSystemEnabled.Checked = ([int]$data.ATMSystemEnabled -eq 1)
