        $lblSubExcluded.Text = 'Excluded (one per line)'
        $lblSubExcluded.Location = New-Object System.Drawing.Point(760, 78)
        $lblSubExcluded.Size = New-Object System.Drawing.Size(180, 20)
        $lblSubExcluded.ForeColor = $global:UGSM_ColorText
        [void]$subPanel.Controls.Add($lblSubExcluded)

        $txtSubExcluded = New-Object System.Windows.Forms.TextBox
        $txtSubExcluded.Location = New-Object System.Drawing.Point(760, 98)
        $txtSubExcluded.Size = New-Object System.Drawing.Size(330, 304)
        $txtSubExcluded.Multiline = $true
        $txtSubExcluded.ScrollBars = 'Vertical'
        $txtSubExcluded.BackColor = $global:UGSM_ColorInputBackground
        $txtSubExcluded.ForeColor = $global:UGSM_ColorText
        $txtSubExcluded.BorderStyle = 'FixedSingle'
        [void]$subPanel.Controls.Add($txtSubExcluded)

        $psSelectedCategoryIndex = -1
        $psSelectedSubCategoryIndex = -1

        $refreshCategoryList = {
            $lstCategories.Items.Clear()
            $cats = @($data.MenuCategories)

            foreach ($cat in $cats) {
                $name = ''
                if ($cat.PSObject.Properties['DisplayName']) {
                    $name = [string]$cat.DisplayName
                }
                if ([string]::IsNullOrWhiteSpace($name)) {
                    $name = 'Unnamed Category'
                }
                [void]$lstCategories.Items.Add($name)
            }

            if ($cats.Count -gt 0) {
                if ($psSelectedCategoryIndex -lt 0 -or $psSelectedCategoryIndex -ge $cats.Count) {
                    $psSelectedCategoryIndex = 0
                }
                $lstCategories.SelectedIndex = $psSelectedCategoryIndex
            }
            else {
                $psSelectedCategoryIndex = -1
                $psSelectedSubCategoryIndex = -1
                $txtCategoryName.Text = ''
                $txtCategoryIcon.Text = ''
                $txtIncluded.Text = ''
                $txtCategoryExcluded.Text = ''
                $lstSubCategories.Items.Clear()
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
            }
        }.GetNewClosure()

        $refreshSubCategoryList = {
            $lstSubCategories.Items.Clear()

            $selectedCategoryIndex = $lstCategories.SelectedIndex
            $cats = @($data.MenuCategories)

            if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                $psSelectedSubCategoryIndex = -1
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
                return
            }

            $cat = $cats[$selectedCategoryIndex]

            if (-not $cat.PSObject.Properties['SubCategories']) {
                $cat | Add-Member -NotePropertyName SubCategories -NotePropertyValue @() -Force
            }

            $subs = @($cat.SubCategories)

            foreach ($sub in $subs) {
                $name = ''
                if ($sub.PSObject.Properties['DisplayName']) {
                    $name = [string]$sub.DisplayName
                }
                if ([string]::IsNullOrWhiteSpace($name)) {
                    $name = 'Unnamed SubCategory'
                }
                [void]$lstSubCategories.Items.Add($name)
            }

            if ($subs.Count -gt 0) {
                if ($psSelectedSubCategoryIndex -lt 0 -or $psSelectedSubCategoryIndex -ge $subs.Count) {
                    $psSelectedSubCategoryIndex = 0
                }
                $lstSubCategories.SelectedIndex = $psSelectedSubCategoryIndex
            }
            else {
                $psSelectedSubCategoryIndex = -1
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedCategory = {
            $selectedCategoryIndex = $lstCategories.SelectedIndex
            $cats = @($data.MenuCategories)

            if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                $txtCategoryName.Text = ''
                $txtCategoryIcon.Text = ''
                $txtIncluded.Text = ''
                $txtCategoryExcluded.Text = ''
                $lstSubCategories.Items.Clear()
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
                $psSelectedCategoryIndex = -1
                $psSelectedSubCategoryIndex = -1
                return
            }

            $psSelectedCategoryIndex = $selectedCategoryIndex

            $cat = $cats[$selectedCategoryIndex]

            $txtCategoryName.Text = $(if ($cat.PSObject.Properties['DisplayName']) { [string]$cat.DisplayName } else { '' })
            $txtCategoryIcon.Text = $(if ($cat.PSObject.Properties['IconPath']) { [string]$cat.IconPath } else { '' })
            $txtIncluded.Text = $(if ($cat.PSObject.Properties['Included']) { @($cat.Included) -join [Environment]::NewLine } else { '' })
            $txtCategoryExcluded.Text = $(if ($cat.PSObject.Properties['Excluded']) { @($cat.Excluded) -join [Environment]::NewLine } else { '' })

            & $refreshSubCategoryList
        }.GetNewClosure()

        $loadSelectedSubCategory = {
            $selectedCategoryIndex = $lstCategories.SelectedIndex
            $selectedSubCategoryIndex = $lstSubCategories.SelectedIndex
            $cats = @($data.MenuCategories)

            if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
                return
            }

            $cat = $cats[$selectedCategoryIndex]

            if (-not $cat.PSObject.Properties['SubCategories']) {
                $cat | Add-Member -NotePropertyName SubCategories -NotePropertyValue @() -Force
            }

            $subs = @($cat.SubCategories)

            if ($selectedSubCategoryIndex -lt 0 -or $selectedSubCategoryIndex -ge $subs.Count) {
                $txtSubCategoryName.Text = ''
                $txtSubCategoryIcon.Text = ''
                $txtSubIncluded.Text = ''
                $txtSubExcluded.Text = ''
                return
            }

            $psSelectedSubCategoryIndex = $selectedSubCategoryIndex

            $sub = $subs[$selectedSubCategoryIndex]

            $txtSubCategoryName.Text = $(if ($sub.PSObject.Properties['DisplayName']) { [string]$sub.DisplayName } else { '' })
            $txtSubCategoryIcon.Text = $(if ($sub.PSObject.Properties['IconPath']) { [string]$sub.IconPath } else { '' })
            $txtSubIncluded.Text = $(if ($sub.PSObject.Properties['Included']) { @($sub.Included) -join [Environment]::NewLine } else { '' })
            $txtSubExcluded.Text = $(if ($sub.PSObject.Properties['Excluded']) { @($sub.Excluded) -join [Environment]::NewLine } else { '' })
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $maxItems = 0
                if (-not [int]::TryParse($txtMaxItems.Text, [ref]$maxItems)) {
                    [System.Windows.Forms.MessageBox]::Show('MaxItemsPerStorage must be a valid integer.')
                    return
                }

                $excludedItems = @()
                foreach ($line in ($txtExcludedClassNames.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $excludedItems += $trim
                    }
                }

                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
                $data.UsePersonalStorageCase = $(if ($chkUseCase.Checked) { 1 } else { 0 })
                $data.MaxItemsPerStorage = $maxItems
                $data.ExcludedClassNames = @($excludedItems)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied PersonalStorage top settings.'
                }
            }.GetNewClosure())

        $lstCategories.Add_SelectedIndexChanged({
                $psSelectedCategoryIndex = $lstCategories.SelectedIndex
                & $loadSelectedCategory
            }.GetNewClosure())

        $btnAddCategory.Add_Click({
                $newCategory = [pscustomobject][ordered]@{
                    DisplayName   = 'New Category'
                    IconPath      = ''
                    Included      = @()
                    Excluded      = @()
                    SubCategories = @()
                }

                $cats = @($data.MenuCategories)
                $data.MenuCategories = @($cats + $newCategory)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $psSelectedCategoryIndex = $data.MenuCategories.Count - 1
                $psSelectedSubCategoryIndex = -1
                & $refreshCategoryList
                & $loadSelectedCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added PersonalStorage category.'
                }
            }.GetNewClosure())

        $btnRemoveCategory.Add_Click({
                $cats = @($data.MenuCategories)
                $selectedCategoryIndex = $lstCategories.SelectedIndex

                if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a category first.')
                    return
                }

                $newCats = @()
                for ($i = 0; $i -lt $cats.Count; $i++) {
                    if ($i -ne $selectedCategoryIndex) {
                        $newCats += $cats[$i]
                    }
                }

                $data.MenuCategories = @($newCats)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($data.MenuCategories.Count -eq 0) {
                    $psSelectedCategoryIndex = -1
                    $psSelectedSubCategoryIndex = -1
                }
                elseif ($selectedCategoryIndex -ge $data.MenuCategories.Count) {
                    $psSelectedCategoryIndex = $data.MenuCategories.Count - 1
                    $psSelectedSubCategoryIndex = -1
                }
                else {
                    $psSelectedCategoryIndex = $selectedCategoryIndex
                    $psSelectedSubCategoryIndex = -1
                }

                & $refreshCategoryList
                & $loadSelectedCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed PersonalStorage category.'
                }
            }.GetNewClosure())

        $btnApplyCategory.Add_Click({
                $cats = @($data.MenuCategories)
                $selectedCategoryIndex = $lstCategories.SelectedIndex
                if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a category first.')
                    return
                }

                $includedItems = @()
                foreach ($line in ($txtIncluded.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $includedItems += $trim
                    }
                }

                $excludedItems = @()
                foreach ($line in ($txtCategoryExcluded.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $excludedItems += $trim
                    }
                }

                $existingCategory = $cats[$selectedCategoryIndex]
                $existingSubCategories = @()
                if ($existingCategory.PSObject.Properties['SubCategories'] -and $existingCategory.SubCategories) {
                    $existingSubCategories = @($existingCategory.SubCategories)
                }

                $updatedCategory = [pscustomobject][ordered]@{
                    DisplayName   = $txtCategoryName.Text.Trim()
                    IconPath      = $txtCategoryIcon.Text.Trim()
                    Included      = [object[]]@($includedItems)
                    Excluded      = [object[]]@($excludedItems)
                    SubCategories = @($existingSubCategories)
                }

                $cats[$selectedCategoryIndex] = $updatedCategory
                $data.MenuCategories = @($cats)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $psSelectedCategoryIndex = $selectedCategoryIndex
                & $refreshCategoryList
                if ($selectedCategoryIndex -ge 0 -and $selectedCategoryIndex -lt $lstCategories.Items.Count) {
                    $lstCategories.SelectedIndex = $selectedCategoryIndex
                }
                & $loadSelectedCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied PersonalStorage category changes.'
                }
            }.GetNewClosure())

        $lstSubCategories.Add_SelectedIndexChanged({
                $psSelectedSubCategoryIndex = $lstSubCategories.SelectedIndex
                & $loadSelectedSubCategory
            }.GetNewClosure())

        $btnAddSubCategory.Add_Click({
                $cats = @($data.MenuCategories)
                $selectedCategoryIndex = $lstCategories.SelectedIndex

                if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a category first.')
                    return
                }

                $cat = $cats[$selectedCategoryIndex]

                $existingSubs = @()
                if ($cat.PSObject.Properties['SubCategories'] -and $cat.SubCategories) {
                    $existingSubs = @($cat.SubCategories)
                }

                $newSub = [pscustomobject][ordered]@{
                    DisplayName = 'New SubCategory'
                    IconPath    = ''
                    Included    = @()
                    Excluded    = @()
                }

                $updatedCategory = [pscustomobject][ordered]@{
                    DisplayName   = $(if ($cat.PSObject.Properties['DisplayName']) { [string]$cat.DisplayName } else { '' })
                    IconPath      = $(if ($cat.PSObject.Properties['IconPath']) { [string]$cat.IconPath } else { '' })
                    Included      = $(if ($cat.PSObject.Properties['Included']) { @($cat.Included) } else { @() })
                    Excluded      = $(if ($cat.PSObject.Properties['Excluded']) { @($cat.Excluded) } else { @() })
                    SubCategories = @($existingSubs + $newSub)
                }

                $cats[$selectedCategoryIndex] = $updatedCategory
                $data.MenuCategories = @($cats)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $psSelectedCategoryIndex = $selectedCategoryIndex
                $psSelectedSubCategoryIndex = $updatedCategory.SubCategories.Count - 1

                & $refreshCategoryList
                if ($selectedCategoryIndex -ge 0 -and $selectedCategoryIndex -lt $lstCategories.Items.Count) {
                    $lstCategories.SelectedIndex = $selectedCategoryIndex
                }

                & $refreshSubCategoryList
                if ($psSelectedSubCategoryIndex -ge 0 -and $psSelectedSubCategoryIndex -lt $lstSubCategories.Items.Count) {
                    $lstSubCategories.SelectedIndex = $psSelectedSubCategoryIndex
                }

                & $loadSelectedSubCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added PersonalStorage subcategory.'
                }
            }.GetNewClosure())

        $btnRemoveSubCategory.Add_Click({
                $cats = @($data.MenuCategories)
                $selectedCategoryIndex = $lstCategories.SelectedIndex

                if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a category first.')
                    return
                }

                $cat = $cats[$selectedCategoryIndex]

                $subs = @()
                if ($cat.PSObject.Properties['SubCategories'] -and $cat.SubCategories) {
                    $subs = @($cat.SubCategories)
                }

                $selectedSubCategoryIndex = $lstSubCategories.SelectedIndex
                if ($selectedSubCategoryIndex -lt 0 -or $selectedSubCategoryIndex -ge $subs.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a SubCategory first.')
                    return
                }

                $newSubs = @()
                for ($i = 0; $i -lt $subs.Count; $i++) {
                    if ($i -ne $selectedSubCategoryIndex) {
                        $newSubs += $subs[$i]
                    }
                }

                $updatedCategory = [pscustomobject][ordered]@{
                    DisplayName   = $(if ($cat.PSObject.Properties['DisplayName']) { [string]$cat.DisplayName } else { '' })
                    IconPath      = $(if ($cat.PSObject.Properties['IconPath']) { [string]$cat.IconPath } else { '' })
                    Included      = $(if ($cat.PSObject.Properties['Included']) { @($cat.Included) } else { @() })
                    Excluded      = $(if ($cat.PSObject.Properties['Excluded']) { @($cat.Excluded) } else { @() })
                    SubCategories = @($newSubs)
                }

                $cats[$selectedCategoryIndex] = $updatedCategory
                $data.MenuCategories = @($cats)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $psSelectedCategoryIndex = $selectedCategoryIndex
                if ($updatedCategory.SubCategories.Count -eq 0) {
                    $psSelectedSubCategoryIndex = -1
                }
                elseif ($selectedSubCategoryIndex -ge $updatedCategory.SubCategories.Count) {
                    $psSelectedSubCategoryIndex = $updatedCategory.SubCategories.Count - 1
                }
                else {
                    $psSelectedSubCategoryIndex = $selectedSubCategoryIndex
                }

                & $refreshCategoryList
                if ($selectedCategoryIndex -ge 0 -and $selectedCategoryIndex -lt $lstCategories.Items.Count) {
                    $lstCategories.SelectedIndex = $selectedCategoryIndex
                }

                & $refreshSubCategoryList
                if ($psSelectedSubCategoryIndex -ge 0 -and $psSelectedSubCategoryIndex -lt $lstSubCategories.Items.Count) {
                    $lstSubCategories.SelectedIndex = $psSelectedSubCategoryIndex
                }

                & $loadSelectedSubCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed PersonalStorage subcategory.'
                }
            }.GetNewClosure())

        $btnApplySubCategory.Add_Click({
                $cats = @($data.MenuCategories)
                $selectedCategoryIndex = $lstCategories.SelectedIndex
                if ($selectedCategoryIndex -lt 0 -or $selectedCategoryIndex -ge $cats.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a category first.')
                    return
                }

                $cat = $cats[$selectedCategoryIndex]
                $subs = @()
                if ($cat.PSObject.Properties['SubCategories'] -and $cat.SubCategories) {
                    $subs = @($cat.SubCategories)
                }

                $selectedSubCategoryIndex = $lstSubCategories.SelectedIndex
                if ($selectedSubCategoryIndex -lt 0 -or $selectedSubCategoryIndex -ge $subs.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Add and select a SubCategory first.')
                    return
                }

                $includedItems = @()
                foreach ($line in ($txtSubIncluded.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $includedItems += $trim
                    }
                }

                $excludedItems = @()
                foreach ($line in ($txtSubExcluded.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $excludedItems += $trim
                    }
                }

                $updatedSub = [pscustomobject][ordered]@{
                    DisplayName = $txtSubCategoryName.Text.Trim()
                    IconPath    = $txtSubCategoryIcon.Text.Trim()
                    Included    = [object[]]@($includedItems)
                    Excluded    = [object[]]@($excludedItems)
                }

                $subs[$selectedSubCategoryIndex] = $updatedSub

                $updatedCategory = [pscustomobject][ordered]@{
                    DisplayName   = $(if ($cat.PSObject.Properties['DisplayName']) { [string]$cat.DisplayName } else { '' })
                    IconPath      = $(if ($cat.PSObject.Properties['IconPath']) { [string]$cat.IconPath } else { '' })
                    Included      = $(if ($cat.PSObject.Properties['Included']) { @($cat.Included) } else { @() })
                    Excluded      = $(if ($cat.PSObject.Properties['Excluded']) { @($cat.Excluded) } else { @() })
                    SubCategories = @($subs)
                }

                $cats[$selectedCategoryIndex] = $updatedCategory
                $data.MenuCategories = @($cats)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $psSelectedCategoryIndex = $selectedCategoryIndex
                $psSelectedSubCategoryIndex = $selectedSubCategoryIndex
                & $refreshSubCategoryList
                if ($selectedSubCategoryIndex -ge 0 -and $selectedSubCategoryIndex -lt $lstSubCategories.Items.Count) {
                    $lstSubCategories.SelectedIndex = $selectedSubCategoryIndex
                }
                & $loadSelectedSubCategory

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied PersonalStorage subcategory changes.'
                }
            }.GetNewClosure())

        $savePersonalStorageSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No PersonalStorage settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved PersonalStorage settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving PersonalStorage settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $savePersonalStorageSettings
            $SettingsState.FileHandler = 'PersonalStorageSettings'
            $SettingsState.Data = $data
        }

        & $refreshCategoryList
        & $loadSelectedCategory

        if ($StatusLabel) {
            $StatusLabel.Text = 'PersonalStorage editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = "PersonalStorage editor failed: $($_.Exception.Message)"
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = "PersonalStorage editor failed: $($_.Exception.Message)"
        }
    }
}

function Show-DayZExpansionSettingEditor_SafeZoneSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null

        if ($SettingsState -and $SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
            }
        }

        if (-not $data) {
            throw "Failed to load SafeZone settings data."
        }

        if (-not $data.PSObject.Properties['m_Version']) { $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['Enabled']) { $data | Add-Member -NotePropertyName Enabled -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['FrameRateCheckSafeZoneInMs']) { $data | Add-Member -NotePropertyName FrameRateCheckSafeZoneInMs -NotePropertyValue 0 -Force }
        if (-not $data.PSObject.Properties['CircleZones']) { $data | Add-Member -NotePropertyName CircleZones -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['PolygonZones']) { $data | Add-Member -NotePropertyName PolygonZones -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['CylinderZones']) { $data | Add-Member -NotePropertyName CylinderZones -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['ActorsPerTick']) { $data | Add-Member -NotePropertyName ActorsPerTick -NotePropertyValue 5 -Force }
        if (-not $data.PSObject.Properties['DisablePlayerCollision']) { $data | Add-Member -NotePropertyName DisablePlayerCollision -NotePropertyValue 0 -Force }
        if (-not $data.PSObject.Properties['DisableVehicleDamageInSafeZone']) { $data | Add-Member -NotePropertyName DisableVehicleDamageInSafeZone -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['EnableForceSZCleanup']) { $data | Add-Member -NotePropertyName EnableForceSZCleanup -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['ItemLifetimeInSafeZone']) { $data | Add-Member -NotePropertyName ItemLifetimeInSafeZone -NotePropertyValue 900.0 -Force }
        if (-not $data.PSObject.Properties['EnableForceSZCleanupVehicles']) { $data | Add-Member -NotePropertyName EnableForceSZCleanupVehicles -NotePropertyValue 0 -Force }
        if (-not $data.PSObject.Properties['VehicleLifetimeInSafeZone']) { $data | Add-Member -NotePropertyName VehicleLifetimeInSafeZone -NotePropertyValue 3600.0 -Force }
        if (-not $data.PSObject.Properties['ForceSZCleanup_ExcludedItems']) { $data | Add-Member -NotePropertyName ForceSZCleanup_ExcludedItems -NotePropertyValue @() -Force }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1240)
        $root.BackColor = $global:UGSM_ColorBackground
        $root.BorderStyle = 'None'
        [void]$HostPanel.Controls.Add($root)

        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 220)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Safe Zone Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(240, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$topPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Top settings, cleanup values, and circle / polygon / cylinder zone editors'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(700, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$topPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 68)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 20)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 88)
        $txtVersion.Size = New-Object System.Drawing.Size(80, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
