        $txtCylinderHeight.Location = New-Object System.Drawing.Point(1020, 62)
        $txtCylinderHeight.Size = New-Object System.Drawing.Size(130, 26)
        $txtCylinderHeight.BackColor = $global:UGSM_ColorInputBackground
        $txtCylinderHeight.ForeColor = $global:UGSM_ColorText
        $txtCylinderHeight.BorderStyle = 'FixedSingle'
        [void]$cylinderPanel.Controls.Add($txtCylinderHeight)

        $btnApplyCylinder = New-Object System.Windows.Forms.Button
        $btnApplyCylinder.Text = 'Apply Cylinder Zone'
        $btnApplyCylinder.Location = New-Object System.Drawing.Point(1170, 60)
        $btnApplyCylinder.Size = New-Object System.Drawing.Size(170, 30)
        $btnApplyCylinder.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyCylinder.ForeColor = $global:UGSM_ColorText
        $btnApplyCylinder.FlatStyle = 'Flat'
        $btnApplyCylinder.UseVisualStyleBackColor = $false
        [void]$cylinderPanel.Controls.Add($btnApplyCylinder)

        $szSelectedCircleIndex = -1
        $szSelectedPolygonIndex = -1
        $szSelectedCylinderIndex = -1

        $refreshCircleList = {
            $lstCircleZones.Items.Clear()
            $zones = @($data.CircleZones)
            for ($i = 0; $i -lt $zones.Count; $i++) {
                $zone = $zones[$i]
                $centerText = ''
                if ($zone.PSObject.Properties['Center'] -and $zone.Center -and @($zone.Center).Count -ge 3) {
                    $centerText = ([string]$zone.Center[0]) + ',' + ([string]$zone.Center[1]) + ',' + ([string]$zone.Center[2])
                }
                $radiusText = $(if ($zone.PSObject.Properties['Radius']) { [string]$zone.Radius } else { '' })
                [void]$lstCircleZones.Items.Add(("Circle " + ($i + 1) + " | " + $centerText + " | R=" + $radiusText))
            }

            if ($zones.Count -gt 0) {
                if ($szSelectedCircleIndex -lt 0 -or $szSelectedCircleIndex -ge $zones.Count) {
                    $szSelectedCircleIndex = 0
                }
                $lstCircleZones.SelectedIndex = $szSelectedCircleIndex
            }
            else {
                $szSelectedCircleIndex = -1
                $txtCircleX.Text = ''
                $txtCircleY.Text = ''
                $txtCircleZ.Text = ''
                $txtCircleRadius.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedCircle = {
            $selectedIndex = $lstCircleZones.SelectedIndex
            $zones = @($data.CircleZones)

            if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                $txtCircleX.Text = ''
                $txtCircleY.Text = ''
                $txtCircleZ.Text = ''
                $txtCircleRadius.Text = ''
                $szSelectedCircleIndex = -1
                return
            }

            $szSelectedCircleIndex = $selectedIndex
            $zone = $zones[$selectedIndex]

            if ($zone.PSObject.Properties['Center'] -and @($zone.Center).Count -ge 3) {
                $txtCircleX.Text = [string]$zone.Center[0]
                $txtCircleY.Text = [string]$zone.Center[1]
                $txtCircleZ.Text = [string]$zone.Center[2]
            }
            else {
                $txtCircleX.Text = ''
                $txtCircleY.Text = ''
                $txtCircleZ.Text = ''
            }

            $txtCircleRadius.Text = $(if ($zone.PSObject.Properties['Radius']) { [string]$zone.Radius } else { '' })
        }.GetNewClosure()

        $refreshPolygonList = {
            $lstPolygonZones.Items.Clear()
            $zones = @($data.PolygonZones)
            for ($i = 0; $i -lt $zones.Count; $i++) {
                $zone = $zones[$i]
                $count = 0
                if ($zone.PSObject.Properties['Positions'] -and $zone.Positions) {
                    $count = @($zone.Positions).Count
                }
                [void]$lstPolygonZones.Items.Add(("Polygon " + ($i + 1) + " | Points=" + $count))
            }

            if ($zones.Count -gt 0) {
                if ($szSelectedPolygonIndex -lt 0 -or $szSelectedPolygonIndex -ge $zones.Count) {
                    $szSelectedPolygonIndex = 0
                }
                $lstPolygonZones.SelectedIndex = $szSelectedPolygonIndex
            }
            else {
                $szSelectedPolygonIndex = -1
                $txtPolygonPositions.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedPolygon = {
            $selectedIndex = $lstPolygonZones.SelectedIndex
            $zones = @($data.PolygonZones)

            if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                $txtPolygonPositions.Text = ''
                $szSelectedPolygonIndex = -1
                return
            }

            $szSelectedPolygonIndex = $selectedIndex
            $zone = $zones[$selectedIndex]

            $lines = @()
            if ($zone.PSObject.Properties['Positions'] -and $zone.Positions) {
                foreach ($pos in @($zone.Positions)) {
                    if (@($pos).Count -ge 3) {
                        $lines += (([string]$pos[0]) + ',' + ([string]$pos[1]) + ',' + ([string]$pos[2]))
                    }
                }
            }
            $txtPolygonPositions.Text = ($lines -join [Environment]::NewLine)
        }.GetNewClosure()

        $refreshCylinderList = {
            $lstCylinderZones.Items.Clear()
            $zones = @($data.CylinderZones)
            for ($i = 0; $i -lt $zones.Count; $i++) {
                $zone = $zones[$i]
                $centerText = ''
                if ($zone.PSObject.Properties['Center'] -and $zone.Center -and @($zone.Center).Count -ge 3) {
                    $centerText = ([string]$zone.Center[0]) + ',' + ([string]$zone.Center[1]) + ',' + ([string]$zone.Center[2])
                }
                $radiusText = $(if ($zone.PSObject.Properties['Radius']) { [string]$zone.Radius } else { '' })
                $heightText = $(if ($zone.PSObject.Properties['Height']) { [string]$zone.Height } else { '' })
                [void]$lstCylinderZones.Items.Add(("Cylinder " + ($i + 1) + " | " + $centerText + " | R=" + $radiusText + " | H=" + $heightText))
            }

            if ($zones.Count -gt 0) {
