                    return
                }

                $actorsPerTick = 0
                if (-not [int]::TryParse($txtActorsPerTick.Text, [ref]$actorsPerTick)) {
                    [System.Windows.Forms.MessageBox]::Show('ActorsPerTick must be a valid integer.')
                    return
                }

                $itemLifetime = 0.0
                if (-not [double]::TryParse($txtItemLifetime.Text, [ref]$itemLifetime)) {
                    [System.Windows.Forms.MessageBox]::Show('ItemLifetimeInSafeZone must be a valid number.')
                    return
                }

                $vehicleLifetime = 0.0
                if (-not [double]::TryParse($txtVehicleLifetime.Text, [ref]$vehicleLifetime)) {
                    [System.Windows.Forms.MessageBox]::Show('VehicleLifetimeInSafeZone must be a valid number.')
                    return
                }

                $excludedItems = @()
                foreach ($line in ($txtExcludedItems.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $excludedItems += $trim
                    }
                }

                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
                $data.FrameRateCheckSafeZoneInMs = $frameRate
                $data.ActorsPerTick = $actorsPerTick
                $data.DisablePlayerCollision = $(if ($chkDisablePlayerCollision.Checked) { 1 } else { 0 })
                $data.DisableVehicleDamageInSafeZone = $(if ($chkDisableVehicleDamage.Checked) { 1 } else { 0 })
                $data.EnableForceSZCleanup = $(if ($chkEnableCleanup.Checked) { 1 } else { 0 })
                $data.ItemLifetimeInSafeZone = $itemLifetime
                $data.EnableForceSZCleanupVehicles = $(if ($chkEnableCleanupVehicles.Checked) { 1 } else { 0 })
                $data.VehicleLifetimeInSafeZone = $vehicleLifetime
                $data.ForceSZCleanup_ExcludedItems = [object[]]@($excludedItems)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied SafeZone top settings.'
                }
            }.GetNewClosure())

        $lstCircleZones.Add_SelectedIndexChanged({
                & $loadSelectedCircle
            }.GetNewClosure())

        $btnAddCircle.Add_Click({
                $zones = @($data.CircleZones)
                $newZone = [pscustomobject][ordered]@{
                    Center = [object[]]@(0.0, 0.0, 0.0)
                    Radius = 500.0
                }

                $data.CircleZones = [object[]]@($zones + $newZone)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedCircleIndex = $data.CircleZones.Count - 1
                & $refreshCircleList
                & $loadSelectedCircle

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added SafeZone circle zone.'
                }
            }.GetNewClosure())

        $btnRemoveCircle.Add_Click({
                $zones = @($data.CircleZones)
                $selectedIndex = $lstCircleZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a circle zone first.')
                    return
                }

                $newZones = @()
                for ($i = 0; $i -lt $zones.Count; $i++) {
                    if ($i -ne $selectedIndex) {
                        $newZones += $zones[$i]
                    }
                }

                $data.CircleZones = [object[]]@($newZones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($data.CircleZones.Count -eq 0) {
                    $szSelectedCircleIndex = -1
                }
                elseif ($selectedIndex -ge $data.CircleZones.Count) {
                    $szSelectedCircleIndex = $data.CircleZones.Count - 1
                }
                else {
                    $szSelectedCircleIndex = $selectedIndex
                }

                & $refreshCircleList
                & $loadSelectedCircle

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed SafeZone circle zone.'
                }
            }.GetNewClosure())

        $btnApplyCircle.Add_Click({
                $zones = @($data.CircleZones)
                $selectedIndex = $lstCircleZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a circle zone first.')
                    return
                }

                $x = 0.0
                if (-not [double]::TryParse($txtCircleX.Text, [ref]$x)) {
                    [System.Windows.Forms.MessageBox]::Show('Circle Center X must be a valid number.')
                    return
                }

                $y = 0.0
                if (-not [double]::TryParse($txtCircleY.Text, [ref]$y)) {
                    [System.Windows.Forms.MessageBox]::Show('Circle Center Y must be a valid number.')
                    return
                }

                $z = 0.0
                if (-not [double]::TryParse($txtCircleZ.Text, [ref]$z)) {
                    [System.Windows.Forms.MessageBox]::Show('Circle Center Z must be a valid number.')
                    return
                }

                $radius = 0.0
                if (-not [double]::TryParse($txtCircleRadius.Text, [ref]$radius)) {
                    [System.Windows.Forms.MessageBox]::Show('Circle Radius must be a valid number.')
                    return
                }

                $zones[$selectedIndex] = [pscustomobject][ordered]@{
                    Center = [object[]]@($x, $y, $z)
                    Radius = $radius
                }

                $data.CircleZones = [object[]]@($zones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedCircleIndex = $selectedIndex
                & $refreshCircleList
                if ($selectedIndex -ge 0 -and $selectedIndex -lt $lstCircleZones.Items.Count) {
                    $lstCircleZones.SelectedIndex = $selectedIndex
                }
                & $loadSelectedCircle

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied SafeZone circle zone changes.'
                }
            }.GetNewClosure())

        $lstPolygonZones.Add_SelectedIndexChanged({
                & $loadSelectedPolygon
            }.GetNewClosure())

        $btnAddPolygon.Add_Click({
                $zones = @($data.PolygonZones)
                $newZone = [pscustomobject][ordered]@{
                    Positions = [object[]]@(
                        [object[]]@(0.0, 0.0, 0.0),
                        [object[]]@(100.0, 0.0, 0.0),
                        [object[]]@(100.0, 0.0, 100.0)
                    )
                }

                $data.PolygonZones = [object[]]@($zones + $newZone)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedPolygonIndex = $data.PolygonZones.Count - 1
                & $refreshPolygonList
                & $loadSelectedPolygon

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added SafeZone polygon zone.'
                }
            }.GetNewClosure())

        $btnRemovePolygon.Add_Click({
                $zones = @($data.PolygonZones)
                $selectedIndex = $lstPolygonZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a polygon zone first.')
                    return
                }

                $newZones = @()
                for ($i = 0; $i -lt $zones.Count; $i++) {
                    if ($i -ne $selectedIndex) {
                        $newZones += $zones[$i]
                    }
                }

                $data.PolygonZones = [object[]]@($newZones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($data.PolygonZones.Count -eq 0) {
                    $szSelectedPolygonIndex = -1
                }
                elseif ($selectedIndex -ge $data.PolygonZones.Count) {
                    $szSelectedPolygonIndex = $data.PolygonZones.Count - 1
                }
                else {
                    $szSelectedPolygonIndex = $selectedIndex
                }

                & $refreshPolygonList
                & $loadSelectedPolygon

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed SafeZone polygon zone.'
                }
            }.GetNewClosure())

        $btnApplyPolygon.Add_Click({
                $zones = @($data.PolygonZones)
                $selectedIndex = $lstPolygonZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a polygon zone first.')
                    return
                }

                $positions = @()
                foreach ($line in ($txtPolygonPositions.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if ([string]::IsNullOrWhiteSpace($trim)) {
                        continue
                    }

                    $parts = $trim -split ','
                    if ($parts.Count -ne 3) {
                        [System.Windows.Forms.MessageBox]::Show('Each polygon position must be in the format X,Y,Z')
                        return
                    }

                    $px = 0.0
                    $py = 0.0
                    $pz = 0.0

                    if (-not [double]::TryParse($parts[0].Trim(), [ref]$px)) {
                        [System.Windows.Forms.MessageBox]::Show('Invalid polygon X value: ' + $trim)
                        return
                    }
                    if (-not [double]::TryParse($parts[1].Trim(), [ref]$py)) {
                        [System.Windows.Forms.MessageBox]::Show('Invalid polygon Y value: ' + $trim)
                        return
                    }
                    if (-not [double]::TryParse($parts[2].Trim(), [ref]$pz)) {
                        [System.Windows.Forms.MessageBox]::Show('Invalid polygon Z value: ' + $trim)
                        return
                    }

                    $positions += , ([object[]]@($px, $py, $pz))
                }

                $zones[$selectedIndex] = [pscustomobject][ordered]@{
                    Positions = [object[]]@($positions)
                }

                $data.PolygonZones = [object[]]@($zones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedPolygonIndex = $selectedIndex
                & $refreshPolygonList
                if ($selectedIndex -ge 0 -and $selectedIndex -lt $lstPolygonZones.Items.Count) {
                    $lstPolygonZones.SelectedIndex = $selectedIndex
                }
                & $loadSelectedPolygon

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied SafeZone polygon zone changes.'
                }
            }.GetNewClosure())

        $lstCylinderZones.Add_SelectedIndexChanged({
                & $loadSelectedCylinder
            }.GetNewClosure())

        $btnAddCylinder.Add_Click({
                $zones = @($data.CylinderZones)
                $newZone = [pscustomobject][ordered]@{
                    Center = [object[]]@(0.0, 0.0, 0.0)
                    Radius = 500.0
                    Height = 120.0
                }

                $data.CylinderZones = [object[]]@($zones + $newZone)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedCylinderIndex = $data.CylinderZones.Count - 1
                & $refreshCylinderList
                & $loadSelectedCylinder

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added SafeZone cylinder zone.'
                }
            }.GetNewClosure())

        $btnRemoveCylinder.Add_Click({
                $zones = @($data.CylinderZones)
                $selectedIndex = $lstCylinderZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a cylinder zone first.')
                    return
                }

                $newZones = @()
                for ($i = 0; $i -lt $zones.Count; $i++) {
                    if ($i -ne $selectedIndex) {
                        $newZones += $zones[$i]
                    }
                }

                $data.CylinderZones = [object[]]@($newZones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($data.CylinderZones.Count -eq 0) {
                    $szSelectedCylinderIndex = -1
                }
                elseif ($selectedIndex -ge $data.CylinderZones.Count) {
                    $szSelectedCylinderIndex = $data.CylinderZones.Count - 1
                }
                else {
                    $szSelectedCylinderIndex = $selectedIndex
                }

                & $refreshCylinderList
                & $loadSelectedCylinder

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed SafeZone cylinder zone.'
                }
            }.GetNewClosure())

        $btnApplyCylinder.Add_Click({
                $zones = @($data.CylinderZones)
                $selectedIndex = $lstCylinderZones.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $zones.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a cylinder zone first.')
                    return
                }

                $x = 0.0
                if (-not [double]::TryParse($txtCylinderX.Text, [ref]$x)) {
                    [System.Windows.Forms.MessageBox]::Show('Cylinder Center X must be a valid number.')
                    return
                }

                $y = 0.0
                if (-not [double]::TryParse($txtCylinderY.Text, [ref]$y)) {
                    [System.Windows.Forms.MessageBox]::Show('Cylinder Center Y must be a valid number.')
                    return
                }

                $z = 0.0
                if (-not [double]::TryParse($txtCylinderZ.Text, [ref]$z)) {
                    [System.Windows.Forms.MessageBox]::Show('Cylinder Center Z must be a valid number.')
                    return
                }

                $radius = 0.0
                if (-not [double]::TryParse($txtCylinderRadius.Text, [ref]$radius)) {
                    [System.Windows.Forms.MessageBox]::Show('Cylinder Radius must be a valid number.')
                    return
                }

                $height = 0.0
                if (-not [double]::TryParse($txtCylinderHeight.Text, [ref]$height)) {
                    [System.Windows.Forms.MessageBox]::Show('Cylinder Height must be a valid number.')
                    return
                }

                $zones[$selectedIndex] = [pscustomobject][ordered]@{
                    Center = [object[]]@($x, $y, $z)
                    Radius = $radius
                    Height = $height
                }

                $data.CylinderZones = [object[]]@($zones)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $szSelectedCylinderIndex = $selectedIndex
                & $refreshCylinderList
                if ($selectedIndex -ge 0 -and $selectedIndex -lt $lstCylinderZones.Items.Count) {
                    $lstCylinderZones.SelectedIndex = $selectedIndex
                }
                & $loadSelectedCylinder

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied SafeZone cylinder zone changes.'
                }
            }.GetNewClosure())

        $saveSafeZoneSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No SafeZone settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved SafeZone settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving SafeZone settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveSafeZoneSettings
            $SettingsState.FileHandler = 'SafeZoneSettings'
            $SettingsState.Data = $data
        }

        & $refreshCircleList
        & $loadSelectedCircle
        & $refreshPolygonList
        & $loadSelectedPolygon
        & $refreshCylinderList
        & $loadSelectedCylinder

        if ($StatusLabel) {
            $StatusLabel.Text = 'SafeZone editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = "SafeZone editor failed: $($_.Exception.Message)"
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = "SafeZone editor failed: $($_.Exception.Message)"
        }
    }
}

function Show-DayZExpansionSettingEditor_SpawnSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null

        if ($SettingsState -and $SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
            }
        }

        if (-not $data) {
            throw "Failed to load Spawn settings data."
        }

        if (-not $data.PSObject.Properties['m_Version']) { $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['SpawnLocations']) { $data | Add-Member -NotePropertyName SpawnLocations -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['EnableSpawnSelection']) { $data | Add-Member -NotePropertyName EnableSpawnSelection -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['SpawnOnTerritory']) { $data | Add-Member -NotePropertyName SpawnOnTerritory -NotePropertyValue 0 -Force }
        if (-not $data.PSObject.Properties['UseLoadouts']) { $data | Add-Member -NotePropertyName UseLoadouts -NotePropertyValue 0 -Force }
        if (-not $data.PSObject.Properties['MaleLoadouts']) { $data | Add-Member -NotePropertyName MaleLoadouts -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['FemaleLoadouts']) { $data | Add-Member -NotePropertyName FemaleLoadouts -NotePropertyValue @() -Force }
        if (-not $data.PSObject.Properties['SpawnHealthValue']) { $data | Add-Member -NotePropertyName SpawnHealthValue -NotePropertyValue 100.0 -Force }
        if (-not $data.PSObject.Properties['SpawnEnergyValue']) { $data | Add-Member -NotePropertyName SpawnEnergyValue -NotePropertyValue 500.0 -Force }
        if (-not $data.PSObject.Properties['SpawnWaterValue']) { $data | Add-Member -NotePropertyName SpawnWaterValue -NotePropertyValue 500.0 -Force }
        if (-not $data.PSObject.Properties['EnableRespawnCooldowns']) { $data | Add-Member -NotePropertyName EnableRespawnCooldowns -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['RespawnCooldown']) { $data | Add-Member -NotePropertyName RespawnCooldown -NotePropertyValue 120 -Force }
        if (-not $data.PSObject.Properties['TerritoryRespawnCooldown']) { $data | Add-Member -NotePropertyName TerritoryRespawnCooldown -NotePropertyValue 240 -Force }
        if (-not $data.PSObject.Properties['PunishMultispawn']) { $data | Add-Member -NotePropertyName PunishMultispawn -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['PunishCooldown']) { $data | Add-Member -NotePropertyName PunishCooldown -NotePropertyValue 120 -Force }
        if (-not $data.PSObject.Properties['PunishTimeframe']) { $data | Add-Member -NotePropertyName PunishTimeframe -NotePropertyValue 300 -Force }
        if (-not $data.PSObject.Properties['CreateDeathMarker']) { $data | Add-Member -NotePropertyName CreateDeathMarker -NotePropertyValue 1 -Force }
        if (-not $data.PSObject.Properties['BackgroundImagePath']) { $data | Add-Member -NotePropertyName BackgroundImagePath -NotePropertyValue '' -Force }

        if (-not $data.PSObject.Properties['StartingClothing']) {
            $data | Add-Member -NotePropertyName StartingClothing -NotePropertyValue ([pscustomobject][ordered]@{
                    EnableCustomClothing = 1
                    SetRandomHealth      = 1
                    Headgear             = @()
                    Glasses              = @()
                    Masks                = @()
                    Tops                 = @()
                    Vests                = @()
                    Gloves               = @()
                    Pants                = @()
                    Belts                = @()
                    Shoes                = @()
                    Armbands             = @()
                    Backpacks            = @()
                }) -Force
        }

        if (-not $data.PSObject.Properties['StartingGear']) {
