        $btnApplyLoadouts = New-Object System.Windows.Forms.Button
        $btnApplyLoadouts.Text = 'Apply Loadouts / Respawn'
        $btnApplyLoadouts.Location = New-Object System.Drawing.Point(1120, 62)
        $btnApplyLoadouts.Size = New-Object System.Drawing.Size(200, 30)
        $btnApplyLoadouts.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyLoadouts.ForeColor = $global:UGSM_ColorText
        $btnApplyLoadouts.FlatStyle = 'Flat'
        $btnApplyLoadouts.UseVisualStyleBackColor = $false
