        $spawnSelectedIndex = -1

        $refreshSpawnList = {
            $lstSpawnLocations.Items.Clear()
            $locations = @($data.SpawnLocations)

            foreach ($loc in $locations) {
                $name = ''
                if ($loc.PSObject.Properties['Name']) { $name = [string]$loc.Name }
                if ([string]::IsNullOrWhiteSpace($name)) { $name = 'Unnamed Spawn' }
                [void]$lstSpawnLocations.Items.Add($name)
            }

            if ($locations.Count -gt 0) {
                if ($spawnSelectedIndex -lt 0 -or $spawnSelectedIndex -ge $locations.Count) {
                    $spawnSelectedIndex = 0
                }
                $lstSpawnLocations.SelectedIndex = $spawnSelectedIndex
            }
            else {
                $spawnSelectedIndex = -1
                $txtSpawnName.Text = ''
                $txtSpawnPositions.Text = ''
                $chkSpawnUseCooldown.Checked = $false
            }
        }.GetNewClosure()

        $loadSelectedSpawn = {
            $selectedIndex = $lstSpawnLocations.SelectedIndex
            $locations = @($data.SpawnLocations)

            if ($selectedIndex -lt 0 -or $selectedIndex -ge $locations.Count) {
                $spawnSelectedIndex = -1
                $txtSpawnName.Text = ''
                $txtSpawnPositions.Text = ''
                $chkSpawnUseCooldown.Checked = $false
                return
            }

            $spawnSelectedIndex = $selectedIndex
            $loc = $locations[$selectedIndex]

            $txtSpawnName.Text = $(if ($loc.PSObject.Properties['Name']) { [string]$loc.Name } else { '' })
            $chkSpawnUseCooldown.Checked = $(if ($loc.PSObject.Properties['UseCooldown']) { ([int]$loc.UseCooldown -eq 1) } else { $false })

            $lines = @()
            if ($loc.PSObject.Properties['Positions'] -and $loc.Positions) {
                foreach ($pos in @($loc.Positions)) {
                    if (@($pos).Count -ge 3) {
                        $lines += (([string]$pos[0]) + ',' + ([string]$pos[1]) + ',' + ([string]$pos[2]))
                    }
                }
            }
            $txtSpawnPositions.Text = ($lines -join [Environment]::NewLine)
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $health = 0.0
                if (-not [double]::TryParse($txtHealth.Text, [ref]$health)) {
                    [System.Windows.Forms.MessageBox]::Show('SpawnHealthValue must be a valid number.')
                    return
                }

                $energy = 0.0
                if (-not [double]::TryParse($txtEnergy.Text, [ref]$energy)) {
                    [System.Windows.Forms.MessageBox]::Show('SpawnEnergyValue must be a valid number.')
                    return
                }

                $water = 0.0
                if (-not [double]::TryParse($txtWater.Text, [ref]$water)) {
                    [System.Windows.Forms.MessageBox]::Show('SpawnWaterValue must be a valid number.')
                    return
                }

                $data.EnableSpawnSelection = $(if ($chkEnableSpawnSelection.Checked) { 1 } else { 0 })
                $data.SpawnOnTerritory = $(if ($chkSpawnOnTerritory.Checked) { 1 } else { 0 })
                $data.UseLoadouts = $(if ($chkUseLoadouts.Checked) { 1 } else { 0 })
                $data.SpawnHealthValue = $health
                $data.SpawnEnergyValue = $energy
                $data.SpawnWaterValue = $water
                $data.BackgroundImagePath = $txtBackground.Text.Trim()

                if ($SettingsState) { $SettingsState.Data = $data }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Spawn top settings.'
                }
            }.GetNewClosure())

        $lstSpawnLocations.Add_SelectedIndexChanged({
                & $loadSelectedSpawn
            }.GetNewClosure())

        $btnAddSpawn.Add_Click({
                $locations = @($data.SpawnLocations)
                $newLocation = [pscustomobject][ordered]@{
                    Name        = 'New Spawn'
                    Positions   = [object[]]@(
                        [object[]]@(0.0, 0.0, 0.0)
                    )
                    UseCooldown = 1
                }

                $data.SpawnLocations = [object[]]@($locations + $newLocation)

                if ($SettingsState) { $SettingsState.Data = $data }

                $spawnSelectedIndex = $data.SpawnLocations.Count - 1
                & $refreshSpawnList
                & $loadSelectedSpawn

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added Spawn location.'
                }
            }.GetNewClosure())

        $btnRemoveSpawn.Add_Click({
                $locations = @($data.SpawnLocations)
                $selectedIndex = $lstSpawnLocations.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $locations.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a spawn location first.')
                    return
                }

                $newLocations = @()
                for ($i = 0; $i -lt $locations.Count; $i++) {
                    if ($i -ne $selectedIndex) {
                        $newLocations += $locations[$i]
                    }
                }

                $data.SpawnLocations = [object[]]@($newLocations)

                if ($SettingsState) { $SettingsState.Data = $data }

                if ($data.SpawnLocations.Count -eq 0) {
                    $spawnSelectedIndex = -1
                }
                elseif ($selectedIndex -ge $data.SpawnLocations.Count) {
                    $spawnSelectedIndex = $data.SpawnLocations.Count - 1
                }
                else {
                    $spawnSelectedIndex = $selectedIndex
                }

                & $refreshSpawnList
                & $loadSelectedSpawn

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed Spawn location.'
                }
            }.GetNewClosure())

        $btnApplySpawn.Add_Click({
                $locations = @($data.SpawnLocations)
                $selectedIndex = $lstSpawnLocations.SelectedIndex
                if ($selectedIndex -lt 0 -or $selectedIndex -ge $locations.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a spawn location first.')
                    return
                }

                $positions = @()
                foreach ($line in ($txtSpawnPositions.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if ([string]::IsNullOrWhiteSpace($trim)) { continue }

                    $parts = $trim -split ','
                    if ($parts.Count -ne 3) {
                        [System.Windows.Forms.MessageBox]::Show('Each spawn position must be in the format X,Y,Z')
                        return
                    }

                    $x = 0.0
                    $y = 0.0
                    $z = 0.0

                    if (-not [double]::TryParse($parts[0].Trim(), [ref]$x)) { [System.Windows.Forms.MessageBox]::Show('Invalid spawn X value: ' + $trim); return }
                    if (-not [double]::TryParse($parts[1].Trim(), [ref]$y)) { [System.Windows.Forms.MessageBox]::Show('Invalid spawn Y value: ' + $trim); return }
                    if (-not [double]::TryParse($parts[2].Trim(), [ref]$z)) { [System.Windows.Forms.MessageBox]::Show('Invalid spawn Z value: ' + $trim); return }

                    $positions += , ([object[]]@($x, $y, $z))
                }

                $locations[$selectedIndex] = [pscustomobject][ordered]@{
                    Name        = $txtSpawnName.Text.Trim()
                    Positions   = [object[]]@($positions)
                    UseCooldown = $(if ($chkSpawnUseCooldown.Checked) { 1 } else { 0 })
                }

                $data.SpawnLocations = [object[]]@($locations)

                if ($SettingsState) { $SettingsState.Data = $data }

                $spawnSelectedIndex = $selectedIndex
                & $refreshSpawnList
                if ($selectedIndex -ge 0 -and $selectedIndex -lt $lstSpawnLocations.Items.Count) {
                    $lstSpawnLocations.SelectedIndex = $selectedIndex
                }
                & $loadSelectedSpawn

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Spawn location changes.'
                }
            }.GetNewClosure())

        $btnApplyClothing.Add_Click({
                $updatedClothing = [pscustomobject][ordered]@{
                    EnableCustomClothing = $(if ($chkEnableCustomClothing.Checked) { 1 } else { 0 })
                    SetRandomHealth      = $(if ($chkClothingRandomHealth.Checked) { 1 } else { 0 })
                    Headgear             = @()
                    Glasses              = @()
                    Masks                = @()
                    Tops                 = @()
                    Vests                = @()
                    Gloves               = @()
                    Pants                = @()
                    Belts                = @()
                    Shoes                = @()
                    Armbands             = @()
                    Backpacks            = @()
                }

                foreach ($key in $clothingTextBoxes.Keys) {
                    $items = @()
                    foreach ($line in ($clothingTextBoxes[$key].Text -split "(`r`n|`n|`r)")) {
                        $trim = $line.Trim()
                        if (-not [string]::IsNullOrWhiteSpace($trim)) {
                            $items += $trim
                        }
                    }
                    $updatedClothing.$key = [object[]]@($items)
                }

                $data.StartingClothing = $updatedClothing
                if ($SettingsState) { $SettingsState.Data = $data }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Starting Clothing changes.'
                }
            }.GetNewClosure())

        $btnApplyGear.Add_Click({
                try {
                    $upper = @()
                    $pants = @()
                    $backpack = @()
                    $vest = @()

                    if (-not [string]::IsNullOrWhiteSpace($txtUpperGear.Text)) { $upper = @((ConvertFrom-Json -InputObject $txtUpperGear.Text -ErrorAction Stop)) }
                    if (-not [string]::IsNullOrWhiteSpace($txtPantsGear.Text)) { $pants = @((ConvertFrom-Json -InputObject $txtPantsGear.Text -ErrorAction Stop)) }
                    if (-not [string]::IsNullOrWhiteSpace($txtBackpackGear.Text)) { $backpack = @((ConvertFrom-Json -InputObject $txtBackpackGear.Text -ErrorAction Stop)) }
                    if (-not [string]::IsNullOrWhiteSpace($txtVestGear.Text)) { $vest = @((ConvertFrom-Json -InputObject $txtVestGear.Text -ErrorAction Stop)) }

                    $data.StartingGear = [pscustomobject][ordered]@{
                        EnableStartingGear = $(if ($chkEnableStartingGear.Checked) { 1 } else { 0 })
                        ApplyEnergySources = $(if ($chkApplyEnergySources.Checked) { 1 } else { 0 })
                        SetRandomHealth    = $(if ($chkGearRandomHealth.Checked) { 1 } else { 0 })
                        UpperGear          = [object[]]@($upper)
                        PantsGear          = [object[]]@($pants)
                        BackpackGear       = [object[]]@($backpack)
                        VestGear           = [object[]]@($vest)
                        PrimaryWeapon      = $(if ($data.StartingGear.PSObject.Properties['PrimaryWeapon']) { $data.StartingGear.PrimaryWeapon } else { [pscustomobject]@{} })
                        SecondaryWeapon    = $(if ($data.StartingGear.PSObject.Properties['SecondaryWeapon']) { $data.StartingGear.SecondaryWeapon } else { [pscustomobject]@{} })
                    }

                    if ($SettingsState) { $SettingsState.Data = $data }

                    if ($StatusLabel) {
                        $StatusLabel.Text = 'Applied Starting Gear changes.'
                    }
                }
                catch {
                    [System.Windows.Forms.MessageBox]::Show('Starting gear JSON is invalid: ' + $_.Exception.Message)
                }
            }.GetNewClosure())

        $btnApplyLoadouts.Add_Click({
                try {
                    $male = @()
                    $female = @()

                    if (-not [string]::IsNullOrWhiteSpace($txtMaleLoadouts.Text)) { $male = @((ConvertFrom-Json -InputObject $txtMaleLoadouts.Text -ErrorAction Stop)) }
                    if (-not [string]::IsNullOrWhiteSpace($txtFemaleLoadouts.Text)) { $female = @((ConvertFrom-Json -InputObject $txtFemaleLoadouts.Text -ErrorAction Stop)) }

                    $respawnCooldown = 0
                    if (-not [int]::TryParse($txtRespawnCooldown.Text, [ref]$respawnCooldown)) {
                        [System.Windows.Forms.MessageBox]::Show('RespawnCooldown must be a valid integer.')
                        return
                    }

                    $territoryRespawnCooldown = 0
                    if (-not [int]::TryParse($txtTerritoryRespawnCooldown.Text, [ref]$territoryRespawnCooldown)) {
                        [System.Windows.Forms.MessageBox]::Show('TerritoryRespawnCooldown must be a valid integer.')
                        return
                    }

                    $punishCooldown = 0
                    if (-not [int]::TryParse($txtPunishCooldown.Text, [ref]$punishCooldown)) {
                        [System.Windows.Forms.MessageBox]::Show('PunishCooldown must be a valid integer.')
                        return
                    }

                    $punishTimeframe = 0
                    if (-not [int]::TryParse($txtPunishTimeframe.Text, [ref]$punishTimeframe)) {
                        [System.Windows.Forms.MessageBox]::Show('PunishTimeframe must be a valid integer.')
                        return
                    }

                    $data.MaleLoadouts = [object[]]@($male)
                    $data.FemaleLoadouts = [object[]]@($female)
                    $data.EnableRespawnCooldowns = $(if ($chkEnableRespawnCooldowns.Checked) { 1 } else { 0 })
                    $data.RespawnCooldown = $respawnCooldown
                    $data.TerritoryRespawnCooldown = $territoryRespawnCooldown
                    $data.PunishMultispawn = $(if ($chkPunishMultispawn.Checked) { 1 } else { 0 })
                    $data.PunishCooldown = $punishCooldown
                    $data.PunishTimeframe = $punishTimeframe
                    $data.CreateDeathMarker = $(if ($chkCreateDeathMarker.Checked) { 1 } else { 0 })

                    if ($SettingsState) { $SettingsState.Data = $data }

                    if ($StatusLabel) {
                        $StatusLabel.Text = 'Applied Loadouts / Respawn changes.'
                    }
                }
                catch {
                    [System.Windows.Forms.MessageBox]::Show('Loadout JSON is invalid: ' + $_.Exception.Message)
                }
            }.GetNewClosure())

        $saveSpawnSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Spawn settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Spawn settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Spawn settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveSpawnSettings
            $SettingsState.FileHandler = 'SpawnSettings'
            $SettingsState.Data = $data
        }

        & $refreshSpawnList
        & $loadSelectedSpawn

        if ($StatusLabel) {
            $StatusLabel.Text = 'Spawn editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = "Spawn editor failed: $($_.Exception.Message)"
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = "Spawn editor failed: $($_.Exception.Message)"
        }
    }
}

function Show-DayZExpansionSettingEditor_AirdropSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    Add-Type -AssemblyName System.Xml

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null

        if ($SettingsState -and $SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Airdrop settings data.'
        }

        $defaults = [ordered]@{
            m_Version                         = 8
            ServerMarkerOnDropLocation        = 1
            Server3DMarkerOnDropLocation      = 1
            ShowAirdropTypeOnMarker           = 1
            HideCargoWhileParachuteIsDeployed = 1
            HeightIsRelativeToGroundLevel     = 1
            Height                            = 450.0
            DropZoneHeight                    = 450.0
            FollowTerrainFraction             = 0.5
            Speed                             = 35.0
            DropZoneSpeed                     = 35.0
            Radius                            = 1.0
            InfectedSpawnRadius               = 50.0
            InfectedSpawnInterval             = 250
            ItemCount                         = 50
            AirdropPlaneClassName             = ''
            DropZoneProximityDistance         = 1500.0
            ExplodeAirVehiclesOnCollision     = 0
            Containers                        = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1780)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $adSelectedContainerIndex = -1
        $adSelectedLootIndex = -1

        $runtimeTypesPath = $null

        try {
            $settingsFolder = Split-Path -Parent $FilePath
            $expansionModFolder = Split-Path -Parent $settingsFolder
            $profilesFolder = Split-Path -Parent $expansionModFolder
            $serverRoot = Split-Path -Parent $profilesFolder

            $missionRoot = Join-Path $serverRoot 'mpmissions'

            if (Test-Path -LiteralPath $missionRoot) {
                $missionDirs = Get-ChildItem -LiteralPath $missionRoot -Directory -ErrorAction SilentlyContinue

                foreach ($dir in $missionDirs) {
                    $candidate = Join-Path $dir.FullName 'db\types.xml'
                    if (Test-Path -LiteralPath $candidate) {
                        $runtimeTypesPath = $candidate
                        break
                    }
                }
            }
        }
        catch {
            $runtimeTypesPath = $null
        }
        $availableTypeNames = New-Object System.Collections.Generic.List[string]
        $availableInfectedTypeNames = New-Object System.Collections.Generic.List[string]
                
        $loadTypesXml = {
            $availableTypeNames.Clear()
            $availableInfectedTypeNames.Clear()

            if ([string]::IsNullOrWhiteSpace($runtimeTypesPath) -or -not (Test-Path -LiteralPath $runtimeTypesPath)) {
                return
            }

            try {
                [xml]$typesXml = Get-Content -LiteralPath $runtimeTypesPath -Raw -ErrorAction Stop

                if ($typesXml.types -and $typesXml.types.type) {
                    foreach ($node in $typesXml.types.type) {
                        $name = ''

                        if ($node -and $node.Attributes -and $node.Attributes['name']) {
                            $name = [string]$node.Attributes['name'].Value
                        }
                        elseif ($node -and $node.name) {
                            $name = [string]$node.name
                        }

                        if (-not [string]::IsNullOrWhiteSpace($name)) {
                            if (-not $availableTypeNames.Contains($name)) {
                                $availableTypeNames.Add($name)
                            }

                            if (($name -like 'ZmbM_*') -or ($name -like 'ZmbF_*')) {
                                if (-not $availableInfectedTypeNames.Contains($name)) {
                                    $availableInfectedTypeNames.Add($name)
                                }
                            }
                        }
                    }
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'types.xml load failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $refreshInfectedDropdown = {
            if (-not $cmbContainerInfectedType) {
                return
            }

            $cmbContainerInfectedType.Items.Clear()

            foreach ($n in $availableInfectedTypeNames) {
                [void]$cmbContainerInfectedType.Items.Add($n)
            }

            if ($cmbContainerInfectedType.Items.Count -gt 0 -and [string]::IsNullOrWhiteSpace($cmbContainerInfectedType.Text)) {
                $cmbContainerInfectedType.SelectedIndex = 0
            }
        }.GetNewClosure()

        & $loadTypesXml
        

        $root.Controls.Clear()

        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 230)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

