        $btnApplyLoot.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyLoot.ForeColor = $global:UGSM_ColorText
        $btnApplyLoot.FlatStyle = 'Flat'
        $btnApplyLoot.UseVisualStyleBackColor = $false
