        $btnSyncLootName = New-Object System.Windows.Forms.Button
        $btnSyncLootName.Text = 'Use Dropdown Value'
        $btnSyncLootName.Location = New-Object System.Drawing.Point(620, 355)
        $btnSyncLootName.Size = New-Object System.Drawing.Size(160, 30)
        $btnSyncLootName.BackColor = $UGSM_ExpansionAccentColor
        $btnSyncLootName.ForeColor = $global:UGSM_ColorText
        $btnSyncLootName.FlatStyle = 'Flat'
        $btnSyncLootName.UseVisualStyleBackColor = $false
