        $savePanel = New-Object System.Windows.Forms.Panel
        $savePanel.Location = New-Object System.Drawing.Point(0, 1200)
        $savePanel.Size = New-Object System.Drawing.Size(1600, 70)
        $savePanel.BackColor = $global:UGSM_ColorPanelBackground
        $savePanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($savePanel)

        $lblSave = New-Object System.Windows.Forms.Label
        $lblSave.Text = 'This build edits top settings, containers, infected, and loot. Attachments and variants remain editable as raw JSON blocks.'
        $lblSave.Location = New-Object System.Drawing.Point(12, 24)
        $lblSave.Size = New-Object System.Drawing.Size(980, 18)
        $lblSave.ForeColor = $global:UGSM_ColorMutedText
        [void]$savePanel.Controls.Add($lblSave)

        $refreshContainerList = {
            $lstContainers.Items.Clear()
            $containers = @($data.Containers)
            for ($i = 0; $i -lt $containers.Count; $i++) {
                $c = $containers[$i]
                $name = $(if ($c.PSObject.Properties['Container']) { [string]$c.Container } else { 'Container' })
                $weight = $(if ($c.PSObject.Properties['Weight']) { [string]$c.Weight } else { '' })
                [void]$lstContainers.Items.Add(([string]::Format('{0}. {1} | W={2}', ($i + 1), $name, $weight)))
            }

            if ($containers.Count -gt 0) {
                if ($adSelectedContainerIndex -lt 0 -or $adSelectedContainerIndex -ge $containers.Count) {
                    $adSelectedContainerIndex = 0
                }
                $lstContainers.SelectedIndex = $adSelectedContainerIndex
            }
            else {
                $adSelectedContainerIndex = -1
                $adSelectedLootIndex = -1
                $lstLoot.Items.Clear()
            }
        }.GetNewClosure()

        $refreshLootList = {
            $lstLoot.Items.Clear()
            $containers = @($data.Containers)
            $selectedContainerIndex = $lstContainers.SelectedIndex
            if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                $adSelectedLootIndex = -1
                return
            }

            $container = $containers[$selectedContainerIndex]
            $lootItems = @()
            if ($container.PSObject.Properties['Loot'] -and $container.Loot) {
                $lootItems = @($container.Loot)
            }

            for ($i = 0; $i -lt $lootItems.Count; $i++) {
                $item = $lootItems[$i]
                $name = $(if ($item.PSObject.Properties['Name']) { [string]$item.Name } else { 'Loot' })
                $chance = $(if ($item.PSObject.Properties['Chance']) { [string]$item.Chance } else { '' })
                [void]$lstLoot.Items.Add(([string]::Format('{0}. {1} | C={2}', ($i + 1), $name, $chance)))
            }

            if ($lootItems.Count -gt 0) {
                if ($adSelectedLootIndex -lt 0 -or $adSelectedLootIndex -ge $lootItems.Count) {
                    $adSelectedLootIndex = 0
                }
                $lstLoot.SelectedIndex = $adSelectedLootIndex
            }
            else {
                $adSelectedLootIndex = -1
                $txtLootName.Text = ''
                $cmbLootType.Text = ''
                $lootFieldTextBoxes['txtLootChance'].Text = ''
                $lootFieldTextBoxes['txtLootQuantityPercent'].Text = ''
                $lootFieldTextBoxes['txtLootMin'].Text = ''
                $lootFieldTextBoxes['txtLootMax'].Text = ''
                $txtLootAttachments.Text = ''
                $txtLootVariants.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedContainer = {
            $containers = @($data.Containers)
            $selectedContainerIndex = $lstContainers.SelectedIndex
            if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                $adSelectedContainerIndex = -1
                foreach ($tb in $containerTextBoxes.Values) { $tb.Text = '' }
                $chkContainerSpawnInfectedForPlayerCalledDrops.Checked = $false
                $chkContainerExplodeAirVehiclesOnCollision.Checked = $false
                $txtContainerInfected.Text = ''
                & $refreshLootList
                return
            }

            $adSelectedContainerIndex = $selectedContainerIndex
            $container = $containers[$selectedContainerIndex]

            $containerTextBoxes['txtContainerClass'].Text = $(if ($container.PSObject.Properties['Container']) { [string]$container.Container } else { '' })
            $containerTextBoxes['txtContainerFallSpeed'].Text = $(if ($container.PSObject.Properties['FallSpeed']) { [string]$container.FallSpeed } else { '' })
            $containerTextBoxes['txtContainerUsage'].Text = $(if ($container.PSObject.Properties['Usage']) { [string]$container.Usage } else { '0' })
            $containerTextBoxes['txtContainerWeight'].Text = $(if ($container.PSObject.Properties['Weight']) { [string]$container.Weight } else { '' })
            $containerTextBoxes['txtContainerItemCount'].Text = $(if ($container.PSObject.Properties['ItemCount']) { [string]$container.ItemCount } else { '' })
            $containerTextBoxes['txtContainerInfectedCount'].Text = $(if ($container.PSObject.Properties['InfectedCount']) { [string]$container.InfectedCount } else { '' })
            $chkContainerSpawnInfectedForPlayerCalledDrops.Checked = $(if ($container.PSObject.Properties['SpawnInfectedForPlayerCalledDrops']) { ([int]$container.SpawnInfectedForPlayerCalledDrops -eq 1) } else { $false })
            $chkContainerExplodeAirVehiclesOnCollision.Checked = $(if ($container.PSObject.Properties['ExplodeAirVehiclesOnCollision']) { ([int]$container.ExplodeAirVehiclesOnCollision -eq 1) } else { $false })
            $txtContainerInfected.Text = $(if ($container.PSObject.Properties['Infected'] -and $container.Infected) { (@($container.Infected) -join [Environment]::NewLine) } else { '' })

            & $refreshLootList
        }.GetNewClosure()

        $loadSelectedLoot = {
            $containers = @($data.Containers)
            $selectedContainerIndex = $lstContainers.SelectedIndex
            if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                return
            }

            $container = $containers[$selectedContainerIndex]
            $lootItems = $(if ($container.PSObject.Properties['Loot'] -and $container.Loot) { @($container.Loot) } else { @() })
            $selectedLootIndex = $lstLoot.SelectedIndex
            if ($selectedLootIndex -lt 0 -or $selectedLootIndex -ge $lootItems.Count) {
                $adSelectedLootIndex = -1
                $txtLootName.Text = ''
                $cmbLootType.Text = ''
                $lootFieldTextBoxes['txtLootChance'].Text = ''
                $lootFieldTextBoxes['txtLootQuantityPercent'].Text = ''
                $lootFieldTextBoxes['txtLootMin'].Text = ''
                $lootFieldTextBoxes['txtLootMax'].Text = ''
                $txtLootAttachments.Text = ''
                $txtLootVariants.Text = ''
                return
            }

            $adSelectedLootIndex = $selectedLootIndex
            $item = $lootItems[$selectedLootIndex]
            $name = $(if ($item.PSObject.Properties['Name']) { [string]$item.Name } else { '' })
            $txtLootName.Text = $name
            $cmbLootType.Text = $name
            $lootFieldTextBoxes['txtLootChance'].Text = $(if ($item.PSObject.Properties['Chance']) { [string]$item.Chance } else { '0.0' })
            $lootFieldTextBoxes['txtLootQuantityPercent'].Text = $(if ($item.PSObject.Properties['QuantityPercent']) { [string]$item.QuantityPercent } else { '-1.0' })
            $lootFieldTextBoxes['txtLootMin'].Text = $(if ($item.PSObject.Properties['Min']) { [string]$item.Min } else { '0' })
            $lootFieldTextBoxes['txtLootMax'].Text = $(if ($item.PSObject.Properties['Max']) { [string]$item.Max } else { '-1' })
            $txtLootAttachments.Text = $(if ($item.PSObject.Properties['Attachments']) { ($item.Attachments | ConvertTo-Json -Depth 50) } else { '[]' })
            $txtLootVariants.Text = $(if ($item.PSObject.Properties['Variants']) { ($item.Variants | ConvertTo-Json -Depth 50) } else { '[]' })
        }.GetNewClosure()

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $doubleKeys = @('txtHeight', 'txtDropZoneHeight', 'txtFollowTerrainFraction', 'txtSpeed', 'txtDropZoneSpeed', 'txtRadius', 'txtInfectedSpawnRadius', 'txtDropZoneProximityDistance')
                $intKeys = @('txtInfectedSpawnInterval', 'txtItemCount')

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($topTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }
                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($topTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                $data.ServerMarkerOnDropLocation = $(if ($topChecks['ServerMarkerOnDropLocation'].Checked) { 1 } else { 0 })
                $data.Server3DMarkerOnDropLocation = $(if ($topChecks['Server3DMarkerOnDropLocation'].Checked) { 1 } else { 0 })
                $data.ShowAirdropTypeOnMarker = $(if ($topChecks['ShowAirdropTypeOnMarker'].Checked) { 1 } else { 0 })
                $data.HideCargoWhileParachuteIsDeployed = $(if ($topChecks['HideCargoWhileParachuteIsDeployed'].Checked) { 1 } else { 0 })
                $data.HeightIsRelativeToGroundLevel = $(if ($topChecks['HeightIsRelativeToGroundLevel'].Checked) { 1 } else { 0 })
                $data.ExplodeAirVehiclesOnCollision = $(if ($topChecks['ExplodeAirVehiclesOnCollision'].Checked) { 1 } else { 0 })
                $data.Height = [double]$topTextBoxes['txtHeight'].Text
                $data.DropZoneHeight = [double]$topTextBoxes['txtDropZoneHeight'].Text
                $data.FollowTerrainFraction = [double]$topTextBoxes['txtFollowTerrainFraction'].Text
                $data.Speed = [double]$topTextBoxes['txtSpeed'].Text
                $data.DropZoneSpeed = [double]$topTextBoxes['txtDropZoneSpeed'].Text
                $data.Radius = [double]$topTextBoxes['txtRadius'].Text
                $data.InfectedSpawnRadius = [double]$topTextBoxes['txtInfectedSpawnRadius'].Text
                $data.InfectedSpawnInterval = [int]$topTextBoxes['txtInfectedSpawnInterval'].Text
                $data.ItemCount = [int]$topTextBoxes['txtItemCount'].Text
                $data.DropZoneProximityDistance = [double]$topTextBoxes['txtDropZoneProximityDistance'].Text
                $data.AirdropPlaneClassName = $txtPlane.Text.Trim()

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Airdrop top settings.' }
            }.GetNewClosure())

        $lstContainers.Add_SelectedIndexChanged({ & $loadSelectedContainer }.GetNewClosure())
        $lstLoot.Add_SelectedIndexChanged({ & $loadSelectedLoot }.GetNewClosure())

        $btnAddContainer.Add_Click({
                $containers = @($data.Containers)
                $newContainer = [pscustomobject][ordered]@{
                    Container                         = 'ExpansionAirdropContainer'
                    FallSpeed                         = 4.5
                    Usage                             = 0
                    Weight                            = 1.0
                    Infected                          = @()
                    ItemCount                         = -1
                    InfectedCount                     = 0
                    SpawnInfectedForPlayerCalledDrops = 0
                    ExplodeAirVehiclesOnCollision     = 0
                    Loot                              = @()
                }
                $data.Containers = [object[]]@($containers + $newContainer)
                if ($SettingsState) { $SettingsState.Data = $data }
                $adSelectedContainerIndex = $data.Containers.Count - 1
                $adSelectedLootIndex = -1
                & $refreshContainerList
                & $loadSelectedContainer
                if ($StatusLabel) { $StatusLabel.Text = 'Added Airdrop container.' }
            }.GetNewClosure())

        $btnRemoveContainer.Add_Click({
                $containers = @($data.Containers)
                $selectedContainerIndex = $lstContainers.SelectedIndex
                if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a container first.')
                    return
                }
                $newContainers = @()
                for ($i = 0; $i -lt $containers.Count; $i++) {
                    if ($i -ne $selectedContainerIndex) { $newContainers += $containers[$i] }
                }
                $data.Containers = [object[]]@($newContainers)
                if ($SettingsState) { $SettingsState.Data = $data }
                if ($data.Containers.Count -eq 0) { $adSelectedContainerIndex = -1 } elseif ($selectedContainerIndex -ge $data.Containers.Count) { $adSelectedContainerIndex = $data.Containers.Count - 1 } else { $adSelectedContainerIndex = $selectedContainerIndex }
                $adSelectedLootIndex = -1
                & $refreshContainerList
                & $loadSelectedContainer
                if ($StatusLabel) { $StatusLabel.Text = 'Removed Airdrop container.' }
            }.GetNewClosure())

        $btnApplyContainer.Add_Click({
                $containers = @($data.Containers)
                $selectedContainerIndex = $lstContainers.SelectedIndex
                if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a container first.')
                    return
                }

                $fallSpeed = 0.0
                $weight = 0.0
                $usage = 0
                $itemCount = 0
                $infectedCount = 0
                if (-not [double]::TryParse($containerTextBoxes['txtContainerFallSpeed'].Text, [ref]$fallSpeed)) { [System.Windows.Forms.MessageBox]::Show('FallSpeed must be a valid number.'); return }
                if (-not [int]::TryParse($containerTextBoxes['txtContainerUsage'].Text, [ref]$usage)) { [System.Windows.Forms.MessageBox]::Show('Usage must be a valid integer.'); return }
                if (-not [double]::TryParse($containerTextBoxes['txtContainerWeight'].Text, [ref]$weight)) { [System.Windows.Forms.MessageBox]::Show('Weight must be a valid number.'); return }
                if (-not [int]::TryParse($containerTextBoxes['txtContainerItemCount'].Text, [ref]$itemCount)) { [System.Windows.Forms.MessageBox]::Show('ItemCount must be a valid integer.'); return }
                if (-not [int]::TryParse($containerTextBoxes['txtContainerInfectedCount'].Text, [ref]$infectedCount)) { [System.Windows.Forms.MessageBox]::Show('InfectedCount must be a valid integer.'); return }

                $existingContainer = $containers[$selectedContainerIndex]
                $existingLoot = $(if ($existingContainer.PSObject.Properties['Loot'] -and $existingContainer.Loot) { @($existingContainer.Loot) } else { @() })
                $updatedContainer = [pscustomobject][ordered]@{
                    Container                         = $containerTextBoxes['txtContainerClass'].Text.Trim()
                    FallSpeed                         = $fallSpeed
                    Usage                             = $usage
                    Weight                            = $weight
                    Infected                          = [object[]]@(& $parseLinesToArray $txtContainerInfected.Text)
                    ItemCount                         = $itemCount
                    InfectedCount                     = $infectedCount
                    SpawnInfectedForPlayerCalledDrops = $(if ($chkContainerSpawnInfectedForPlayerCalledDrops.Checked) { 1 } else { 0 })
                    ExplodeAirVehiclesOnCollision     = $(if ($chkContainerExplodeAirVehiclesOnCollision.Checked) { 1 } else { 0 })
                    Loot                              = [object[]]@($existingLoot)
                }
                $containers[$selectedContainerIndex] = $updatedContainer
                $data.Containers = [object[]]@($containers)
                if ($SettingsState) { $SettingsState.Data = $data }
                $adSelectedContainerIndex = $selectedContainerIndex
                & $refreshContainerList
                if ($selectedContainerIndex -ge 0 -and $selectedContainerIndex -lt $lstContainers.Items.Count) { $lstContainers.SelectedIndex = $selectedContainerIndex }
                & $loadSelectedContainer
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Airdrop container changes.' }
            }.GetNewClosure())

        $btnAddSelectedInfected.Add_Click({
                $selectedName = $cmbContainerInfectedType.Text.Trim()
                if ([string]::IsNullOrWhiteSpace($selectedName)) {
                    [System.Windows.Forms.MessageBox]::Show('Select an infected classname first.')
                    return
                }

                $existing = @()
                foreach ($line in ($txtContainerInfected.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $existing += $trim
                    }
                }

                if ($existing -contains $selectedName) {
                    return
                }

                $existing += $selectedName
                $txtContainerInfected.Text = ($existing -join [Environment]::NewLine)
            }.GetNewClosure())

        $btnRemoveSelectedInfected.Add_Click({
                $selectedName = $cmbContainerInfectedType.Text.Trim()
                if ([string]::IsNullOrWhiteSpace($selectedName)) {
                    [System.Windows.Forms.MessageBox]::Show('Select an infected classname first.')
                    return
                }

                $existing = @()
                foreach ($line in ($txtContainerInfected.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $existing += $trim
                    }
                }

                $updated = @()
                foreach ($item in $existing) {
                    if ($item -ne $selectedName) {
                        $updated += $item
                    }
                }

                $txtContainerInfected.Text = ($updated -join [Environment]::NewLine)
            }.GetNewClosure())

        $btnSyncLootName.Add_Click({
                if (-not [string]::IsNullOrWhiteSpace($cmbLootType.Text)) {
                    $txtLootName.Text = $cmbLootType.Text.Trim()
                }
            }.GetNewClosure())

        $btnAddLoot.Add_Click({
                $containers = @($data.Containers)
                $selectedContainerIndex = $lstContainers.SelectedIndex
                if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a container first.')
                    return
                }

                $container = $containers[$selectedContainerIndex]
                $existingLoot = $(if ($container.PSObject.Properties['Loot'] -and $container.Loot) { @($container.Loot) } else { @() })
                $newLoot = [pscustomobject][ordered]@{
                    Name            = $(if (-not [string]::IsNullOrWhiteSpace($cmbLootType.Text)) { $cmbLootType.Text.Trim() } else { 'NewItem' })
                    Chance          = 0.1
                    Attachments     = @()
                    QuantityPercent = -1.0
                    Max             = -1
                    Min             = 0
                    Variants        = @()
                }
                $updatedLoot = @()
                foreach ($loot in $existingLoot) {
                    $updatedLoot += $loot
                }
                
                $updatedLoot += $newLoot

                $container = [pscustomobject][ordered]@{
                    Container                         = $(if ($container.PSObject.Properties['Container']) { [string]$container.Container } else { '' })
                    FallSpeed                         = $(if ($container.PSObject.Properties['FallSpeed']) { [double]$container.FallSpeed } else { 0.0 })
                    Usage                             = $(if ($container.PSObject.Properties['Usage']) { [int]$container.Usage } else { 0 })
                    Weight                            = $(if ($container.PSObject.Properties['Weight']) { [double]$container.Weight } else { 0.0 })
                    Infected                          = $(if ($container.PSObject.Properties['Infected']) { [object[]]@($container.Infected) } else { @() })
                    ItemCount                         = $(if ($container.PSObject.Properties['ItemCount']) { [int]$container.ItemCount } else { 0 })
                    InfectedCount                     = $(if ($container.PSObject.Properties['InfectedCount']) { [int]$container.InfectedCount } else { 0 })
                    SpawnInfectedForPlayerCalledDrops = $(if ($container.PSObject.Properties['SpawnInfectedForPlayerCalledDrops']) { [int]$container.SpawnInfectedForPlayerCalledDrops } else { 0 })
                    ExplodeAirVehiclesOnCollision     = $(if ($container.PSObject.Properties['ExplodeAirVehiclesOnCollision']) { [int]$container.ExplodeAirVehiclesOnCollision } else { 0 })
                    Loot                              = [object[]]@($updatedLoot)
                }

                $containers[$selectedContainerIndex] = $container
                $data.Containers = [object[]]@($containers)
                if ($SettingsState) { $SettingsState.Data = $data }
                $adSelectedContainerIndex = $selectedContainerIndex
                $adSelectedLootIndex = $container.Loot.Count - 1
                & $refreshContainerList
                if ($selectedContainerIndex -ge 0 -and $selectedContainerIndex -lt $lstContainers.Items.Count) { $lstContainers.SelectedIndex = $selectedContainerIndex }
                & $refreshLootList
                if ($adSelectedLootIndex -ge 0 -and $adSelectedLootIndex -lt $lstLoot.Items.Count) { $lstLoot.SelectedIndex = $adSelectedLootIndex }
                & $loadSelectedLoot
                if ($StatusLabel) { $StatusLabel.Text = 'Added Airdrop loot item.' }
            }.GetNewClosure())

        $btnRemoveLoot.Add_Click({
                $containers = @($data.Containers)
                $selectedContainerIndex = $lstContainers.SelectedIndex
                if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a container first.')
                    return
                }

                $container = $containers[$selectedContainerIndex]
                $lootItems = $(if ($container.PSObject.Properties['Loot'] -and $container.Loot) { @($container.Loot) } else { @() })
                $selectedLootIndex = $lstLoot.SelectedIndex
                if ($selectedLootIndex -lt 0 -or $selectedLootIndex -ge $lootItems.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a loot item first.')
                    return
                }

                $newLoot = @()
                for ($i = 0; $i -lt $lootItems.Count; $i++) {
                    if ($i -ne $selectedLootIndex) { $newLoot += $lootItems[$i] }
                }

                $updatedContainer = [pscustomobject][ordered]@{
                    Container                         = $container.Container
                    FallSpeed                         = $container.FallSpeed
                    Usage                             = $container.Usage
                    Weight                            = $container.Weight
                    Infected                          = $(if ($container.PSObject.Properties['Infected']) { [object[]]@($container.Infected) } else { @() })
                    ItemCount                         = $container.ItemCount
                    InfectedCount                     = $container.InfectedCount
                    SpawnInfectedForPlayerCalledDrops = $container.SpawnInfectedForPlayerCalledDrops
                    ExplodeAirVehiclesOnCollision     = $(if ($container.PSObject.Properties['ExplodeAirVehiclesOnCollision']) { $container.ExplodeAirVehiclesOnCollision } else { 0 })
                    Loot                              = [object[]]@($newLoot)
                }
                $containers[$selectedContainerIndex] = $updatedContainer
                $data.Containers = [object[]]@($containers)
                if ($SettingsState) { $SettingsState.Data = $data }

                $adSelectedContainerIndex = $selectedContainerIndex
                if ($updatedContainer.Loot.Count -eq 0) { $adSelectedLootIndex = -1 } elseif ($selectedLootIndex -ge $updatedContainer.Loot.Count) { $adSelectedLootIndex = $updatedContainer.Loot.Count - 1 } else { $adSelectedLootIndex = $selectedLootIndex }
                & $refreshContainerList
                if ($selectedContainerIndex -ge 0 -and $selectedContainerIndex -lt $lstContainers.Items.Count) { $lstContainers.SelectedIndex = $selectedContainerIndex }
                & $refreshLootList
                if ($adSelectedLootIndex -ge 0 -and $adSelectedLootIndex -lt $lstLoot.Items.Count) { $lstLoot.SelectedIndex = $adSelectedLootIndex }
                & $loadSelectedLoot
                if ($StatusLabel) { $StatusLabel.Text = 'Removed Airdrop loot item.' }
            }.GetNewClosure())

        $btnApplyLoot.Add_Click({
                $containers = @($data.Containers)
                $selectedContainerIndex = $lstContainers.SelectedIndex
                if ($selectedContainerIndex -lt 0 -or $selectedContainerIndex -ge $containers.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a container first.')
                    return
                }

                $container = $containers[$selectedContainerIndex]
                $lootItems = $(if ($container.PSObject.Properties['Loot'] -and $container.Loot) { @($container.Loot) } else { @() })
                $selectedLootIndex = $lstLoot.SelectedIndex
                if ($selectedLootIndex -lt 0 -or $selectedLootIndex -ge $lootItems.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a loot item first.')
                    return
                }

                $chance = 0.0
                $quantityPercent = 0.0
                $min = 0
                $max = 0
                if (-not [double]::TryParse($lootFieldTextBoxes['txtLootChance'].Text, [ref]$chance)) { [System.Windows.Forms.MessageBox]::Show('Chance must be a valid number.'); return }
                if (-not [double]::TryParse($lootFieldTextBoxes['txtLootQuantityPercent'].Text, [ref]$quantityPercent)) { [System.Windows.Forms.MessageBox]::Show('QuantityPercent must be a valid number.'); return }
                if (-not [int]::TryParse($lootFieldTextBoxes['txtLootMin'].Text, [ref]$min)) { [System.Windows.Forms.MessageBox]::Show('Min must be a valid integer.'); return }
                if (-not [int]::TryParse($lootFieldTextBoxes['txtLootMax'].Text, [ref]$max)) { [System.Windows.Forms.MessageBox]::Show('Max must be a valid integer.'); return }

                $attachments = @()
                $variants = @()
                try {
                    if (-not [string]::IsNullOrWhiteSpace($txtLootAttachments.Text)) {
                        $attachments = @((ConvertFrom-Json -InputObject $txtLootAttachments.Text -ErrorAction Stop))
                    }
                    if (-not [string]::IsNullOrWhiteSpace($txtLootVariants.Text)) {
                        $variants = @((ConvertFrom-Json -InputObject $txtLootVariants.Text -ErrorAction Stop))
                    }
                }
                catch {
                    [System.Windows.Forms.MessageBox]::Show('Attachments or Variants JSON is invalid: ' + $_.Exception.Message)
                    return
                }

                $lootItems[$selectedLootIndex] = [pscustomobject][ordered]@{
                    Name            = $txtLootName.Text.Trim()
                    Chance          = $chance
                    Attachments     = [object[]]@($attachments)
                    QuantityPercent = $quantityPercent
                    Max             = $max
                    Min             = $min
                    Variants        = [object[]]@($variants)
                }

                $updatedContainer = [pscustomobject][ordered]@{
                    Container                         = $container.Container
                    FallSpeed                         = $container.FallSpeed
                    Usage                             = $container.Usage
                    Weight                            = $container.Weight
                    Infected                          = $(if ($container.PSObject.Properties['Infected']) { [object[]]@($container.Infected) } else { @() })
                    ItemCount                         = $container.ItemCount
                    InfectedCount                     = $container.InfectedCount
                    SpawnInfectedForPlayerCalledDrops = $container.SpawnInfectedForPlayerCalledDrops
                    ExplodeAirVehiclesOnCollision     = $(if ($container.PSObject.Properties['ExplodeAirVehiclesOnCollision']) { $container.ExplodeAirVehiclesOnCollision } else { 0 })
                    Loot                              = [object[]]@($lootItems)
                }
                $containers[$selectedContainerIndex] = $updatedContainer
                $data.Containers = [object[]]@($containers)
                if ($SettingsState) { $SettingsState.Data = $data }
                $adSelectedContainerIndex = $selectedContainerIndex
                $adSelectedLootIndex = $selectedLootIndex
                & $refreshContainerList
                if ($selectedContainerIndex -ge 0 -and $selectedContainerIndex -lt $lstContainers.Items.Count) { $lstContainers.SelectedIndex = $selectedContainerIndex }
                & $refreshLootList
                if ($selectedLootIndex -ge 0 -and $selectedLootIndex -lt $lstLoot.Items.Count) { $lstLoot.SelectedIndex = $selectedLootIndex }
                & $loadSelectedLoot
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Airdrop loot item changes.' }
            }.GetNewClosure())

        $saveAirdropSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Airdrop settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Airdrop settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Airdrop settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveAirdropSettings
            $SettingsState.FileHandler = 'AirdropSettings'
            $SettingsState.Data = $data
        }

        & $refreshContainerList
        & $loadSelectedContainer

        if ($StatusLabel) {
            $StatusLabel.Text = 'Airdrop editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Airdrop editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Airdrop editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_AISettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'AISettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))

            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load AI settings data.'
        }

        $defaults = [ordered]@{
            m_Version                           = 20
            AccuracyMin                         = 0.35
            AccuracyMax                         = 0.95
            ThreatDistanceLimit                 = 1000.0
            NoiseInvestigationDistanceLimit     = 500.0
            MaxFlankingDistance                 = 200.0
            EnableFlankingOutsideCombat         = 0
            DamageMultiplier                    = 1.0
            DamageReceivedMultiplier            = 1.0
            ShoryukenChance                     = 0.01
            ShoryukenDamageMultiplier           = 3.0
            Admins                              = @()
            Vaulting                            = 1
            SniperProneDistanceThreshold        = 0.0
            AggressionTimeout                   = 120.0
            GuardAggressionTimeout              = 150.0
            Manners                             = 0
            MemeLevel                           = 1
            CanRecruitFriendly                  = 1
            CanRecruitGuards                    = 0
            MaxRecruitableAI                    = 1
            PreventClimb                        = @()
            FormationScale                      = 1.0
            PlayerFactions                      = @()
            LogAIHitBy                          = 1
            LogAIKilled                         = 1
            EnableZombieVehicleAttackHandler    = 0
            EnableZombieVehicleAttackPhysics    = 0
            OverrideClientWeaponFiring          = 1
            RecreateWeaponNetworkRepresentation = 1
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.PSObject.Properties['LightingConfigMinNightVisibilityMeters'] -or -not $data.LightingConfigMinNightVisibilityMeters) {
            $data | Add-Member -NotePropertyName LightingConfigMinNightVisibilityMeters -NotePropertyValue ([pscustomobject][ordered]@{
                    '0' = 100.0
                    '1' = 10.0
                }) -Force
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1220)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $mainPanel = New-Object System.Windows.Forms.Panel
        $mainPanel.Location = New-Object System.Drawing.Point(0, 0)
        $mainPanel.Size = New-Object System.Drawing.Size(1600, 1120)
        $mainPanel.BackColor = $global:UGSM_ColorPanelBackground
        $mainPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($mainPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'AI Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$mainPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Combat tuning, recruit settings, logging, faction arrays, and lighting config'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(700, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblSub)

        $numericConfigs = @(
            @{ Label = 'Version'; Name = 'txtVersion'; X = 12; Y = 80; W = 60; Text = [string]$data.m_Version; ReadOnly = $true },
            @{ Label = 'AccuracyMin'; Name = 'txtAccuracyMin'; X = 110; Y = 80; W = 80; Text = [string]$data.AccuracyMin },
            @{ Label = 'AccuracyMax'; Name = 'txtAccuracyMax'; X = 225; Y = 80; W = 80; Text = [string]$data.AccuracyMax },
            @{ Label = 'ThreatDistanceLimit'; Name = 'txtThreatDistanceLimit'; X = 340; Y = 80; W = 105; Text = [string]$data.ThreatDistanceLimit },
            @{ Label = 'NoiseInvestigationDistanceLimit'; Name = 'txtNoiseInvestigationDistanceLimit'; X = 475; Y = 80; W = 150; Text = [string]$data.NoiseInvestigationDistanceLimit },
            @{ Label = 'MaxFlankingDistance'; Name = 'txtMaxFlankingDistance'; X = 655; Y = 80; W = 100; Text = [string]$data.MaxFlankingDistance },
            @{ Label = 'DamageMultiplier'; Name = 'txtDamageMultiplier'; X = 790; Y = 80; W = 90; Text = [string]$data.DamageMultiplier },
            @{ Label = 'DamageReceivedMultiplier'; Name = 'txtDamageReceivedMultiplier'; X = 915; Y = 80; W = 125; Text = [string]$data.DamageReceivedMultiplier },
            @{ Label = 'ShoryukenChance'; Name = 'txtShoryukenChance'; X = 1070; Y = 80; W = 90; Text = [string]$data.ShoryukenChance },
            @{ Label = 'ShoryukenDamageMultiplier'; Name = 'txtShoryukenDamageMultiplier'; X = 1195; Y = 80; W = 140; Text = [string]$data.ShoryukenDamageMultiplier },

            @{ Label = 'SniperProneDistanceThreshold'; Name = 'txtSniperProneDistanceThreshold'; X = 12; Y = 170; W = 150; Text = [string]$data.SniperProneDistanceThreshold },
            @{ Label = 'AggressionTimeout'; Name = 'txtAggressionTimeout'; X = 200; Y = 170; W = 105; Text = [string]$data.AggressionTimeout },
            @{ Label = 'GuardAggressionTimeout'; Name = 'txtGuardAggressionTimeout'; X = 335; Y = 170; W = 125; Text = [string]$data.GuardAggressionTimeout },
            @{ Label = 'Manners'; Name = 'txtManners'; X = 490; Y = 170; W = 60; Text = [string]$data.Manners },
            @{ Label = 'MemeLevel'; Name = 'txtMemeLevel'; X = 585; Y = 170; W = 60; Text = [string]$data.MemeLevel },
            @{ Label = 'MaxRecruitableAI'; Name = 'txtMaxRecruitableAI'; X = 680; Y = 170; W = 100; Text = [string]$data.MaxRecruitableAI },
            @{ Label = 'FormationScale'; Name = 'txtFormationScale'; X = 815; Y = 170; W = 100; Text = [string]$data.FormationScale }
        )

        $numericTextBoxes = @{}
        foreach ($cfg in $numericConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(([int]$cfg.W + 30), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$mainPanel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $(if ($cfg.ReadOnly) { $global:UGSM_ColorPanelBackground } else { $global:UGSM_ColorInputBackground })
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            $tb.ReadOnly = [bool]$cfg.ReadOnly
            [void]$mainPanel.Controls.Add($tb)

            $numericTextBoxes[$cfg.Name] = $tb
        }

        $checkConfigs = @(
            @{ Text = 'EnableFlankingOutsideCombat'; Name = 'chkEnableFlankingOutsideCombat'; X = 12; Y = 240; Checked = ([int]$data.EnableFlankingOutsideCombat -eq 1) },
            @{ Text = 'Vaulting'; Name = 'chkVaulting'; X = 300; Y = 240; Checked = ([int]$data.Vaulting -eq 1) },
            @{ Text = 'CanRecruitFriendly'; Name = 'chkCanRecruitFriendly'; X = 600; Y = 240; Checked = ([int]$data.CanRecruitFriendly -eq 1) },
            @{ Text = 'CanRecruitGuards'; Name = 'chkCanRecruitGuards'; X = 900; Y = 240; Checked = ([int]$data.CanRecruitGuards -eq 1) },
            @{ Text = 'LogAIHitBy'; Name = 'chkLogAIHitBy'; X = 1200; Y = 240; Checked = ([int]$data.LogAIHitBy -eq 1) },
            
            @{ Text = 'LogAIKilled'; Name = 'chkLogAIKilled'; X = 12; Y = 272; Checked = ([int]$data.LogAIKilled -eq 1) },
            @{ Text = 'EnableZombieVehicleAttackHandler'; Name = 'chkEnableZombieVehicleAttackHandler'; X = 300; Y = 272; Checked = ([int]$data.EnableZombieVehicleAttackHandler -eq 1) },
            @{ Text = 'EnableZombieVehicleAttackPhysics'; Name = 'chkEnableZombieVehicleAttackPhysics'; X = 600; Y = 272; Checked = ([int]$data.EnableZombieVehicleAttackPhysics -eq 1) },
            @{ Text = 'OverrideClientWeaponFiring'; Name = 'chkOverrideClientWeaponFiring'; X = 900; Y = 272; Checked = ([int]$data.OverrideClientWeaponFiring -eq 1) },
            @{ Text = 'RecreateWeaponNetworkRepresentation'; Name = 'chkRecreateWeaponNetworkRepresentation'; X = 1200; Y = 272; Checked = ([int]$data.RecreateWeaponNetworkRepresentation -eq 1) }
        )

        $checkBoxes = @{}
        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(270, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$mainPanel.Controls.Add($cb)

            $checkBoxes[$cfg.Name] = $cb
        }

        $lblAdmins = New-Object System.Windows.Forms.Label
        $lblAdmins.Text = 'Admins (one per line)'
        $lblAdmins.Location = New-Object System.Drawing.Point(12, 340)
        $lblAdmins.Size = New-Object System.Drawing.Size(180, 18)
        $lblAdmins.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblAdmins)

        $txtAdmins = New-Object System.Windows.Forms.TextBox
        $txtAdmins.Location = New-Object System.Drawing.Point(12, 360)
        $txtAdmins.Size = New-Object System.Drawing.Size(300, 220)
        $txtAdmins.Multiline = $true
        $txtAdmins.ScrollBars = 'Vertical'
        $txtAdmins.BackColor = $global:UGSM_ColorInputBackground
        $txtAdmins.ForeColor = $global:UGSM_ColorText
        $txtAdmins.BorderStyle = 'FixedSingle'
        if ($data.Admins) { $txtAdmins.Text = (@($data.Admins) -join [Environment]::NewLine) }
        [void]$mainPanel.Controls.Add($txtAdmins)

        $lblPreventClimb = New-Object System.Windows.Forms.Label
        $lblPreventClimb.Text = 'PreventClimb (one per line)'
        $lblPreventClimb.Location = New-Object System.Drawing.Point(330, 340)
        $lblPreventClimb.Size = New-Object System.Drawing.Size(200, 18)
        $lblPreventClimb.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblPreventClimb)

        $txtPreventClimb = New-Object System.Windows.Forms.TextBox
        $txtPreventClimb.Location = New-Object System.Drawing.Point(330, 360)
        $txtPreventClimb.Size = New-Object System.Drawing.Size(300, 220)
        $txtPreventClimb.Multiline = $true
        $txtPreventClimb.ScrollBars = 'Vertical'
        $txtPreventClimb.BackColor = $global:UGSM_ColorInputBackground
        $txtPreventClimb.ForeColor = $global:UGSM_ColorText
        $txtPreventClimb.BorderStyle = 'FixedSingle'
        if ($data.PreventClimb) { $txtPreventClimb.Text = (@($data.PreventClimb) -join [Environment]::NewLine) }
        [void]$mainPanel.Controls.Add($txtPreventClimb)

        $lblPlayerFactions = New-Object System.Windows.Forms.Label
        $lblPlayerFactions.Text = 'PlayerFactions (one per line)'
        $lblPlayerFactions.Location = New-Object System.Drawing.Point(648, 340)
        $lblPlayerFactions.Size = New-Object System.Drawing.Size(210, 18)
        $lblPlayerFactions.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblPlayerFactions)

        $txtPlayerFactions = New-Object System.Windows.Forms.TextBox
        $txtPlayerFactions.Location = New-Object System.Drawing.Point(648, 360)
        $txtPlayerFactions.Size = New-Object System.Drawing.Size(300, 220)
        $txtPlayerFactions.Multiline = $true
        $txtPlayerFactions.ScrollBars = 'Vertical'
        $txtPlayerFactions.BackColor = $global:UGSM_ColorInputBackground
        $txtPlayerFactions.ForeColor = $global:UGSM_ColorText
        $txtPlayerFactions.BorderStyle = 'FixedSingle'
        if ($data.PlayerFactions) { $txtPlayerFactions.Text = (@($data.PlayerFactions) -join [Environment]::NewLine) }
        [void]$mainPanel.Controls.Add($txtPlayerFactions)

        $lblLighting = New-Object System.Windows.Forms.Label
        $lblLighting.Text = 'LightingConfigMinNightVisibilityMeters'
        $lblLighting.Location = New-Object System.Drawing.Point(980, 340)
        $lblLighting.Size = New-Object System.Drawing.Size(280, 18)
        $lblLighting.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblLighting)

        $lblLighting0 = New-Object System.Windows.Forms.Label
        $lblLighting0.Text = 'Key 0'
        $lblLighting0.Location = New-Object System.Drawing.Point(980, 380)
        $lblLighting0.Size = New-Object System.Drawing.Size(80, 18)
        $lblLighting0.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblLighting0)

        $txtLighting0 = New-Object System.Windows.Forms.TextBox
        $txtLighting0.Location = New-Object System.Drawing.Point(980, 400)
        $txtLighting0.Size = New-Object System.Drawing.Size(120, 26)
        $txtLighting0.Text = $(if ($data.LightingConfigMinNightVisibilityMeters.PSObject.Properties['0']) { [string]$data.LightingConfigMinNightVisibilityMeters.'0' } else { '100.0' })
        $txtLighting0.BackColor = $global:UGSM_ColorInputBackground
        $txtLighting0.ForeColor = $global:UGSM_ColorText
        $txtLighting0.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtLighting0)

        $lblLighting1 = New-Object System.Windows.Forms.Label
        $lblLighting1.Text = 'Key 1'
        $lblLighting1.Location = New-Object System.Drawing.Point(1120, 380)
        $lblLighting1.Size = New-Object System.Drawing.Size(80, 18)
        $lblLighting1.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblLighting1)

        $txtLighting1 = New-Object System.Windows.Forms.TextBox
        $txtLighting1.Location = New-Object System.Drawing.Point(1120, 400)
        $txtLighting1.Size = New-Object System.Drawing.Size(120, 26)
        $txtLighting1.Text = $(if ($data.LightingConfigMinNightVisibilityMeters.PSObject.Properties['1']) { [string]$data.LightingConfigMinNightVisibilityMeters.'1' } else { '10.0' })
        $txtLighting1.BackColor = $global:UGSM_ColorInputBackground
        $txtLighting1.ForeColor = $global:UGSM_ColorText
        $txtLighting1.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtLighting1)

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'Arrays are simple one-per-line editors. Lighting config keeps the two current keys from the JSON.'
        $lblHelp.Location = New-Object System.Drawing.Point(980, 450)
        $lblHelp.Size = New-Object System.Drawing.Size(500, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply AI Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(980, 500)
        $btnApplyAll.Size = New-Object System.Drawing.Size(160, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyAll)

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $btnApplyAll.Add_Click({
                $doubleKeys = @(
                    'txtAccuracyMin',
                    'txtAccuracyMax',
                    'txtThreatDistanceLimit',
                    'txtNoiseInvestigationDistanceLimit',
                    'txtMaxFlankingDistance',
                    'txtDamageMultiplier',
                    'txtDamageReceivedMultiplier',
                    'txtShoryukenChance',
                    'txtShoryukenDamageMultiplier',
                    'txtSniperProneDistanceThreshold',
                    'txtAggressionTimeout',
                    'txtGuardAggressionTimeout',
                    'txtFormationScale'
                )

                $intKeys = @(
                    'txtManners',
                    'txtMemeLevel',
                    'txtMaxRecruitableAI'
                )

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                $lighting0 = 0.0
                $lighting1 = 0.0
                if (-not [double]::TryParse($txtLighting0.Text, [ref]$lighting0)) {
                    [System.Windows.Forms.MessageBox]::Show('Lighting key 0 must be a valid number.')
                    return
                }
                if (-not [double]::TryParse($txtLighting1.Text, [ref]$lighting1)) {
                    [System.Windows.Forms.MessageBox]::Show('Lighting key 1 must be a valid number.')
                    return
                }

                $data.AccuracyMin = [double]$numericTextBoxes['txtAccuracyMin'].Text
                $data.AccuracyMax = [double]$numericTextBoxes['txtAccuracyMax'].Text
                $data.ThreatDistanceLimit = [double]$numericTextBoxes['txtThreatDistanceLimit'].Text
                $data.NoiseInvestigationDistanceLimit = [double]$numericTextBoxes['txtNoiseInvestigationDistanceLimit'].Text
                $data.MaxFlankingDistance = [double]$numericTextBoxes['txtMaxFlankingDistance'].Text
                $data.EnableFlankingOutsideCombat = $(if ($checkBoxes['chkEnableFlankingOutsideCombat'].Checked) { 1 } else { 0 })
                $data.DamageMultiplier = [double]$numericTextBoxes['txtDamageMultiplier'].Text
                $data.DamageReceivedMultiplier = [double]$numericTextBoxes['txtDamageReceivedMultiplier'].Text
                $data.ShoryukenChance = [double]$numericTextBoxes['txtShoryukenChance'].Text
                $data.ShoryukenDamageMultiplier = [double]$numericTextBoxes['txtShoryukenDamageMultiplier'].Text
                $data.Admins = [object[]]@(& $parseLinesToArray $txtAdmins.Text)
                $data.Vaulting = $(if ($checkBoxes['chkVaulting'].Checked) { 1 } else { 0 })
                $data.SniperProneDistanceThreshold = [double]$numericTextBoxes['txtSniperProneDistanceThreshold'].Text
                $data.AggressionTimeout = [double]$numericTextBoxes['txtAggressionTimeout'].Text
                $data.GuardAggressionTimeout = [double]$numericTextBoxes['txtGuardAggressionTimeout'].Text
                $data.Manners = [int]$numericTextBoxes['txtManners'].Text
                $data.MemeLevel = [int]$numericTextBoxes['txtMemeLevel'].Text
                $data.CanRecruitFriendly = $(if ($checkBoxes['chkCanRecruitFriendly'].Checked) { 1 } else { 0 })
                $data.CanRecruitGuards = $(if ($checkBoxes['chkCanRecruitGuards'].Checked) { 1 } else { 0 })
                $data.MaxRecruitableAI = [int]$numericTextBoxes['txtMaxRecruitableAI'].Text
                $data.PreventClimb = [object[]]@(& $parseLinesToArray $txtPreventClimb.Text)
                $data.FormationScale = [double]$numericTextBoxes['txtFormationScale'].Text
                $data.PlayerFactions = [object[]]@(& $parseLinesToArray $txtPlayerFactions.Text)
                $data.LogAIHitBy = $(if ($checkBoxes['chkLogAIHitBy'].Checked) { 1 } else { 0 })
                $data.LogAIKilled = $(if ($checkBoxes['chkLogAIKilled'].Checked) { 1 } else { 0 })
                $data.EnableZombieVehicleAttackHandler = $(if ($checkBoxes['chkEnableZombieVehicleAttackHandler'].Checked) { 1 } else { 0 })
                $data.EnableZombieVehicleAttackPhysics = $(if ($checkBoxes['chkEnableZombieVehicleAttackPhysics'].Checked) { 1 } else { 0 })
                $data.OverrideClientWeaponFiring = $(if ($checkBoxes['chkOverrideClientWeaponFiring'].Checked) { 1 } else { 0 })
                $data.RecreateWeaponNetworkRepresentation = $(if ($checkBoxes['chkRecreateWeaponNetworkRepresentation'].Checked) { 1 } else { 0 })
                $data.LightingConfigMinNightVisibilityMeters = [pscustomobject][ordered]@{
                    '0' = $lighting0
                    '1' = $lighting1
                }

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied AI settings.'
                }
            }.GetNewClosure())

        $saveAISettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No AI settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved AI settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving AI settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveAISettings
            $SettingsState.FileHandler = 'AISettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'AI editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'AI editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'AI editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_BookSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'BookSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Book settings data.'
        }

        $defaults = [ordered]@{
            m_Version                            = 5
            EnableStatusTab                      = 1
            EnablePartyTab                       = 1
            EnableServerInfoTab                  = 1
            EnableServerRulesTab                 = 1
            EnableTerritoryTab                   = 1
            EnableBookMenu                       = 1
            CreateBookmarks                      = 0
            ShowHaBStats                         = 1
            ShowPlayerFaction                    = 0
            DisplayServerSettingsInServerInfoTab = 1
            EnableCraftingRecipesTab             = 1
            RuleCategories                       = @()
            SettingCategories                    = @()
            Links                                = @()
            Descriptions                         = @()
            CraftingCategories                   = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 2350)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $bookSelectedRuleCategoryIndex = -1
        $bookSelectedRuleIndex = -1
        $bookSelectedSettingCategoryIndex = -1
        $bookSelectedSettingIndex = -1
        $bookSelectedLinkIndex = -1
        $bookSelectedDescriptionCategoryIndex = -1
        $bookSelectedDescriptionIndex = -1
        $bookSelectedCraftingCategoryIndex = -1

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        # Top settings
        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 180)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Book Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$topPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Tabs, rule categories, setting categories, links, descriptions, and crafting categories'
