            @{ Text = 'EnablePartyTab'; X = 410; Y = 60; Checked = ([int]$data.EnablePartyTab -eq 1) },
            @{ Text = 'EnableServerInfoTab'; X = 710; Y = 60; Checked = ([int]$data.EnableServerInfoTab -eq 1) },
