        $btnApplyCraftingCategory.Size = New-Object System.Drawing.Size(170, 30)
        $btnApplyCraftingCategory.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyCraftingCategory.ForeColor = $global:UGSM_ColorText
        $btnApplyCraftingCategory.FlatStyle = 'Flat'
        $btnApplyCraftingCategory.UseVisualStyleBackColor = $false
        [void]$craftPanel.Controls.Add($btnApplyCraftingCategory)

        $refreshRuleCategoryList = {
            $lstRuleCategories.Items.Clear()
            foreach ($cat in @($data.RuleCategories)) {
                [void]$lstRuleCategories.Items.Add([string]$cat.CategoryName)
            }
            if ($lstRuleCategories.Items.Count -gt 0) {
                if ($bookSelectedRuleCategoryIndex -lt 0 -or $bookSelectedRuleCategoryIndex -ge $lstRuleCategories.Items.Count) {
                    $bookSelectedRuleCategoryIndex = 0
                }
                $lstRuleCategories.SelectedIndex = $bookSelectedRuleCategoryIndex
            }
        }.GetNewClosure()

        $refreshRuleList = {
            $lstRules.Items.Clear()
            $ruleCats = @($data.RuleCategories)
            $idx = $lstRuleCategories.SelectedIndex
            if ($idx -lt 0 -or $idx -ge $ruleCats.Count) {
                $bookSelectedRuleIndex = -1
                return
            }
            $rules = @($ruleCats[$idx].Rules)
            foreach ($rule in $rules) {
                [void]$lstRules.Items.Add(([string]$rule.RuleParagraph + ' ' + [string]$rule.RuleText))
            }
            if ($lstRules.Items.Count -gt 0) {
                if ($bookSelectedRuleIndex -lt 0 -or $bookSelectedRuleIndex -ge $lstRules.Items.Count) {
                    $bookSelectedRuleIndex = 0
                }
                $lstRules.SelectedIndex = $bookSelectedRuleIndex
            }
        }.GetNewClosure()

        $loadSelectedRuleCategory = {
            $ruleCats = @($data.RuleCategories)
            $idx = $lstRuleCategories.SelectedIndex
            if ($idx -lt 0 -or $idx -ge $ruleCats.Count) {
                $bookSelectedRuleCategoryIndex = -1
                $txtRuleCategoryName.Text = ''
                $lstRules.Items.Clear()
                return
            }
            $bookSelectedRuleCategoryIndex = $idx
            $txtRuleCategoryName.Text = [string]$ruleCats[$idx].CategoryName
            & $refreshRuleList
        }.GetNewClosure()

        $loadSelectedRule = {
            $ruleCats = @($data.RuleCategories)
            $catIdx = $lstRuleCategories.SelectedIndex
            if ($catIdx -lt 0 -or $catIdx -ge $ruleCats.Count) { return }
            $rules = @($ruleCats[$catIdx].Rules)
            $idx = $lstRules.SelectedIndex
            if ($idx -lt 0 -or $idx -ge $rules.Count) {
                $bookSelectedRuleIndex = -1
                $txtRuleParagraph.Text = ''
                $txtRuleText.Text = ''
                return
            }
            $bookSelectedRuleIndex = $idx
            $txtRuleParagraph.Text = [string]$rules[$idx].RuleParagraph
            $txtRuleText.Text = [string]$rules[$idx].RuleText
        }.GetNewClosure()

        $refreshSettingCategoryList = {
            $lstSettingCategories.Items.Clear()
            foreach ($cat in @($data.SettingCategories)) {
                [void]$lstSettingCategories.Items.Add([string]$cat.CategoryName)
            }
            if ($lstSettingCategories.Items.Count -gt 0) {
                if ($bookSelectedSettingCategoryIndex -lt 0 -or $bookSelectedSettingCategoryIndex -ge $lstSettingCategories.Items.Count) {
                    $bookSelectedSettingCategoryIndex = 0
                }
                $lstSettingCategories.SelectedIndex = $bookSelectedSettingCategoryIndex
            }
        }.GetNewClosure()

        $refreshSettingList = {
            $lstSettings.Items.Clear()
            $cats = @($data.SettingCategories)
            $idx = $lstSettingCategories.SelectedIndex
            if ($idx -lt 0 -or $idx -ge $cats.Count) {
                $bookSelectedSettingIndex = -1
                return
            }
            $settings = @($cats[$idx].Settings)
            foreach ($s in $settings) {
                [void]$lstSettings.Items.Add([string]$s.SettingTitle)
