                $data.CraftingCategories = [object[]]@($cats)
                $bookSelectedCraftingCategoryIndex = $data.CraftingCategories.Count - 1
                & $refreshCraftingCategoryList
                & $loadSelectedCraftingCategory
            }.GetNewClosure())

        $btnRemoveCraftingCategory.Add_Click({
                $cats = @($data.CraftingCategories)
                $idx = $lstCraftingCategories.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $cats.Count) { return }
                $newCats = @()
                for ($i = 0; $i -lt $cats.Count; $i++) { if ($i -ne $idx) { $newCats += $cats[$i] } }
                $data.CraftingCategories = [object[]]@($newCats)
                $bookSelectedCraftingCategoryIndex = $(if ($newCats.Count -gt 0) { [Math]::Min($idx, $newCats.Count - 1) } else { -1 })
                & $refreshCraftingCategoryList
                & $loadSelectedCraftingCategory
            }.GetNewClosure())

        $btnApplyCraftingCategory.Add_Click({
                $cats = @($data.CraftingCategories)
                $idx = $lstCraftingCategories.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $cats.Count) { return }

                $cats[$idx] = [pscustomobject][ordered]@{
                    CategoryName = $txtCraftCategoryName.Text.Trim()
                    Results      = [object[]]@(& $parseLinesToArray $txtCraftResults.Text)
                }

                $data.CraftingCategories = [object[]]@($cats)
                & $refreshCraftingCategoryList
                if ($idx -ge 0 -and $idx -lt $lstCraftingCategories.Items.Count) { $lstCraftingCategories.SelectedIndex = $idx }
            }.GetNewClosure())

        $saveBookSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Book settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Book settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Book settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveBookSettings
            $SettingsState.FileHandler = 'BookSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshRuleCategoryList
        & $loadSelectedRuleCategory
        & $refreshSettingCategoryList
        & $loadSelectedSettingCategory
        & $refreshLinks
        & $loadSelectedLink
        & $refreshDescriptionCategoryList
        & $loadSelectedDescriptionCategory
        & $refreshCraftingCategoryList
        & $loadSelectedCraftingCategory

        if ($StatusLabel) {
            $StatusLabel.Text = 'Book editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Book editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Book editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_ChatSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'ChatSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Chat settings data.'
        }

        $defaults = [ordered]@{
            m_Version           = 4
            EnableGlobalChat    = 1
            EnablePartyChat     = 1
            EnableTransportChat = 1
            EnableExpansionChat = 1
            BlacklistedWords    = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.PSObject.Properties['ChatColors'] -or -not $data.ChatColors) {
            $data | Add-Member -NotePropertyName ChatColors -NotePropertyValue ([pscustomobject][ordered]@{
                    SystemChatColor       = 'EB45EBFF'
                    AdminChatColor        = 'FF392BFF'
                    GlobalChatColor       = '58C3FFFF'
                    DirectChatColor       = 'FFFFFFFF'
                    TransportChatColor    = 'FFCE09FF'
                    PartyChatColor        = '0AFA7AFF'
                    TransmitterChatColor  = 'F9FF49FF'
                    StatusMessageColor    = '4B77BEFF'
                    ActionMessageColor    = 'F7CA18FF'
                    FriendlyMessageColor  = '2ECC71FF'
                    ImportantMessageColor = 'F22613FF'
                    DefaultMessageColor   = 'FFFFFFFF'
                }) -Force
        }

        $colorKeys = @(
            'SystemChatColor',
            'AdminChatColor',
            'GlobalChatColor',
            'DirectChatColor',
            'TransportChatColor',
            'PartyChatColor',
            'TransmitterChatColor',
            'StatusMessageColor',
            'ActionMessageColor',
            'FriendlyMessageColor',
            'ImportantMessageColor',
            'DefaultMessageColor'
        )

        foreach ($key in $colorKeys) {
            if (-not $data.ChatColors.PSObject.Properties[$key]) {
                $data.ChatColors | Add-Member -NotePropertyName $key -NotePropertyValue 'FFFFFFFF' -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1180)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $mainPanel = New-Object System.Windows.Forms.Panel
        $mainPanel.Location = New-Object System.Drawing.Point(0, 0)
        $mainPanel.Size = New-Object System.Drawing.Size(1600, 1080)
        $mainPanel.BackColor = $global:UGSM_ColorPanelBackground
        $mainPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($mainPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Chat Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$mainPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Chat toggles, chat colors, and blacklisted words'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(520, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtVersion)

        $checkBoxes = @{}
        $checkConfigs = @(
            @{ Text = 'EnableGlobalChat'; X = 110; Y = 92; Checked = ([int]$data.EnableGlobalChat -eq 1) },
            @{ Text = 'EnablePartyChat'; X = 380; Y = 92; Checked = ([int]$data.EnablePartyChat -eq 1) },
            @{ Text = 'EnableTransportChat'; X = 560; Y = 92; Checked = ([int]$data.EnableTransportChat -eq 1) },
            @{ Text = 'EnableExpansionChat'; X = 760; Y = 92; Checked = ([int]$data.EnableExpansionChat -eq 1) }
        )

        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(180, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$mainPanel.Controls.Add($cb)
            $checkBoxes[$cfg.Text] = $cb
        }

        $lblColorHelp = New-Object System.Windows.Forms.Label
        $lblColorHelp.Text = 'Colors save as 8-character hex like FFFFFFFF.'
        $lblColorHelp.Location = New-Object System.Drawing.Point(12, 135)
        $lblColorHelp.Size = New-Object System.Drawing.Size(340, 18)
        $lblColorHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblColorHelp)

        $colorControls = @{}
        $colorPicker = New-Object System.Windows.Forms.ColorDialog
        $colorPicker.FullOpen = $true

        $colorLayout = @(
            @{ Key = 'SystemChatColor'; X = 12; Y = 180 },
            @{ Key = 'AdminChatColor'; X = 405; Y = 180 },
            @{ Key = 'GlobalChatColor'; X = 798; Y = 180 },

            @{ Key = 'DirectChatColor'; X = 12; Y = 255 },
            @{ Key = 'TransportChatColor'; X = 405; Y = 255 },
            @{ Key = 'PartyChatColor'; X = 798; Y = 255 },

            @{ Key = 'TransmitterChatColor'; X = 12; Y = 330 },
            @{ Key = 'StatusMessageColor'; X = 405; Y = 330 },
            @{ Key = 'ActionMessageColor'; X = 798; Y = 330 },

            @{ Key = 'FriendlyMessageColor'; X = 12; Y = 405 },
            @{ Key = 'ImportantMessageColor'; X = 405; Y = 405 },
            @{ Key = 'DefaultMessageColor'; X = 798; Y = 405 }
        )

        foreach ($cfg in $colorLayout) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Key
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $lbl.Size = New-Object System.Drawing.Size(180, 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$mainPanel.Controls.Add($lbl)

            $txt = New-Object System.Windows.Forms.TextBox
            $txt.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y + 20))
            $txt.Size = New-Object System.Drawing.Size(130, 26)
            $txt.Text = [string]$data.ChatColors.$($cfg.Key)
            $txt.BackColor = $global:UGSM_ColorInputBackground
            $txt.ForeColor = $global:UGSM_ColorText
            $txt.BorderStyle = 'FixedSingle'
            [void]$mainPanel.Controls.Add($txt)

            $preview = New-Object System.Windows.Forms.Panel
            $preview.Location = New-Object System.Drawing.Point(($cfg.X + 140), ($cfg.Y + 20))
            $preview.Size = New-Object System.Drawing.Size(36, 26)
            $preview.BorderStyle = 'FixedSingle'
            $preview.BackColor = Convert-UGSMHexToColor -Hex $txt.Text
            [void]$mainPanel.Controls.Add($preview)

            $btnPick = New-Object System.Windows.Forms.Button
            $btnPick.Text = 'Pick'
            $btnPick.Location = New-Object System.Drawing.Point(($cfg.X + 186), ($cfg.Y + 18))
            $btnPick.Size = New-Object System.Drawing.Size(70, 30)
            $btnPick.BackColor = $UGSM_ExpansionAccentColor
            $btnPick.ForeColor = $global:UGSM_ColorText
            $btnPick.FlatStyle = 'Flat'
            $btnPick.UseVisualStyleBackColor = $false
            [void]$mainPanel.Controls.Add($btnPick)

            $txt.Add_TextChanged({
                    Update-UGSMColorPreview -TextBox $txt $preview
                }.GetNewClosure())

            $btnPick.Add_Click({
                    $colorPicker.Color = Convert-UGSMHexToColor -Hex $txt.Text
                    if ($colorPicker.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                        $txt.Text = Convert-UGSMColorToHex -Color $colorPicker.Color
                        Update-UGSMColorPreview -TextBox $txt -Panel $preview
                    }
                }.GetNewClosure())

            $colorControls[$cfg.Key] = @{
                TextBox = $txt
                Preview = $preview
                Button  = $btnPick
            }
        }

        $lblBlacklist = New-Object System.Windows.Forms.Label
        $lblBlacklist.Text = 'BlacklistedWords (one per line)'
        $lblBlacklist.Location = New-Object System.Drawing.Point(12, 510)
        $lblBlacklist.Size = New-Object System.Drawing.Size(220, 18)
        $lblBlacklist.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblBlacklist)

        $txtBlacklistedWords = New-Object System.Windows.Forms.TextBox
        $txtBlacklistedWords.Location = New-Object System.Drawing.Point(12, 530)
        $txtBlacklistedWords.Size = New-Object System.Drawing.Size(520, 220)
        $txtBlacklistedWords.Multiline = $true
        $txtBlacklistedWords.ScrollBars = 'Vertical'
        $txtBlacklistedWords.BackColor = $global:UGSM_ColorInputBackground
        $txtBlacklistedWords.ForeColor = $global:UGSM_ColorText
        $txtBlacklistedWords.BorderStyle = 'FixedSingle'
        if ($data.BlacklistedWords) {
            $txtBlacklistedWords.Text = (@($data.BlacklistedWords) -join [Environment]::NewLine)
        }
        [void]$mainPanel.Controls.Add($txtBlacklistedWords)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Chat Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 470)
        $btnApplyAll.Size = New-Object System.Drawing.Size(160, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                foreach ($key in $colorKeys) {
                    $hex = ([string]$colorControls[$key].TextBox.Text).Trim().TrimStart('#').ToUpper()
                    if ($hex.Length -ne 8 -or $hex -notmatch '^[0-9A-F]{8}$') {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be an 8-character hex value like FFFFFFFF.'))
                        return
                    }
                }

                $data.EnableGlobalChat = $(if ($checkBoxes['EnableGlobalChat'].Checked) { 1 } else { 0 })
                $data.EnablePartyChat = $(if ($checkBoxes['EnablePartyChat'].Checked) { 1 } else { 0 })
                $data.EnableTransportChat = $(if ($checkBoxes['EnableTransportChat'].Checked) { 1 } else { 0 })
                $data.EnableExpansionChat = $(if ($checkBoxes['EnableExpansionChat'].Checked) { 1 } else { 0 })

                foreach ($key in $colorKeys) {
                    $data.ChatColors.$key = ([string]$colorControls[$key].TextBox.Text).Trim().TrimStart('#').ToUpper()
                }

                $words = @()
                foreach ($line in ($txtBlacklistedWords.Text -split "(`r`n|`n|`r)")) {
                    $trim = $line.Trim()
                    if (-not [string]::IsNullOrWhiteSpace($trim)) {
                        $words += $trim
                    }
                }
                $data.BlacklistedWords = [object[]]@($words)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Chat settings.'
                }
            }.GetNewClosure())

        $saveChatSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Chat settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Chat settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Chat settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveChatSettings
            $SettingsState.FileHandler = 'ChatSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Chat editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Chat editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Chat editor failed: ' + $_.Exception.Message
        }
    }
}

