        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $rateLimit = 0
                if (-not [int]::TryParse($txtRate.Text, [ref]$rateLimit)) {
                    [System.Windows.Forms.MessageBox]::Show('ServerUpdateRateLimit must be a valid integer.')
                    return
                }

                if ($rateLimit -ne 0 -and $rateLimit -lt 40) {
                    [System.Windows.Forms.MessageBox]::Show('ServerUpdateRateLimit must be 0 or at least 40.')
                    return
                }

                $data.ServerUpdateRateLimit = $rateLimit
                $data.ForceExactCEItemLifetime = $(if ($chkForceExactCE.Checked) { 1 } else { 0 })
                $data.EnableInventoryCargoTidy = $(if ($chkEnableCargoTidy.Checked) { 1 } else { 0 })

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Core settings.'
                }
            }.GetNewClosure())

        $saveCoreSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Core settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Core settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Core settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveCoreSettings
            $SettingsState.FileHandler = 'CoreSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Core editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Core editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Core editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_DamageSystemSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'DamageSystemSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load DamageSystem settings data.'
        }

        $defaults = [ordered]@{
            m_Version               = 1
            Enabled                 = 1
            CheckForBlockingObjects = 1
            ExplosionTargets        = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.PSObject.Properties['ExplosiveProjectiles'] -or -not $data.ExplosiveProjectiles) {
            $data | Add-Member -NotePropertyName ExplosiveProjectiles -NotePropertyValue ([pscustomobject][ordered]@{}) -Force
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 760)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $mainPanel = New-Object System.Windows.Forms.Panel
        $mainPanel.Location = New-Object System.Drawing.Point(0, 0)
        $mainPanel.Size = New-Object System.Drawing.Size(1600, 700)
        $mainPanel.BackColor = $global:UGSM_ColorPanelBackground
        $mainPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($mainPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Damage System Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(260, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$mainPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Explosion damage system toggles, targets, and explosive projectile mappings'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(760, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtVersion)

        $chkEnabled = New-Object System.Windows.Forms.CheckBox
        $chkEnabled.Text = 'Enabled'
        $chkEnabled.Location = New-Object System.Drawing.Point(110, 92)
        $chkEnabled.Size = New-Object System.Drawing.Size(120, 22)
        $chkEnabled.Checked = ([int]$data.Enabled -eq 1)
        $chkEnabled.ForeColor = $global:UGSM_ColorText
        $chkEnabled.BackColor = [System.Drawing.Color]::Transparent
        [void]$mainPanel.Controls.Add($chkEnabled)

        $chkBlocking = New-Object System.Windows.Forms.CheckBox
        $chkBlocking.Text = 'CheckForBlockingObjects'
        $chkBlocking.Location = New-Object System.Drawing.Point(240, 92)
        $chkBlocking.Size = New-Object System.Drawing.Size(220, 22)
        $chkBlocking.Checked = ([int]$data.CheckForBlockingObjects -eq 1)
        $chkBlocking.ForeColor = $global:UGSM_ColorText
        $chkBlocking.BackColor = [System.Drawing.Color]::Transparent
        [void]$mainPanel.Controls.Add($chkBlocking)

        $btnApplyTop = New-Object System.Windows.Forms.Button
        $btnApplyTop.Text = 'Apply Top Settings'
        $btnApplyTop.Location = New-Object System.Drawing.Point(490, 88)
        $btnApplyTop.Size = New-Object System.Drawing.Size(150, 30)
        $btnApplyTop.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyTop.ForeColor = $global:UGSM_ColorText
        $btnApplyTop.FlatStyle = 'Flat'
        $btnApplyTop.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyTop)

        $lblTargets = New-Object System.Windows.Forms.Label
        $lblTargets.Text = 'ExplosionTargets (one per line)'
        $lblTargets.Location = New-Object System.Drawing.Point(12, 150)
        $lblTargets.Size = New-Object System.Drawing.Size(240, 18)
        $lblTargets.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblTargets)

        $txtExplosionTargets = New-Object System.Windows.Forms.TextBox
        $txtExplosionTargets.Location = New-Object System.Drawing.Point(12, 170)
        $txtExplosionTargets.Size = New-Object System.Drawing.Size(420, 220)
        $txtExplosionTargets.Multiline = $true
        $txtExplosionTargets.ScrollBars = 'Vertical'
        $txtExplosionTargets.BackColor = $global:UGSM_ColorInputBackground
        $txtExplosionTargets.ForeColor = $global:UGSM_ColorText
        $txtExplosionTargets.BorderStyle = 'FixedSingle'
        if ($data.ExplosionTargets) {
            $txtExplosionTargets.Text = (@($data.ExplosionTargets) -join [Environment]::NewLine)
        }
        [void]$mainPanel.Controls.Add($txtExplosionTargets)

        $lblTargetHelp = New-Object System.Windows.Forms.Label
        $lblTargetHelp.Text = 'These are targets that should receive Expansion explosion damage, not the explosives themselves.'
        $lblTargetHelp.Location = New-Object System.Drawing.Point(12, 398)
        $lblTargetHelp.Size = New-Object System.Drawing.Size(520, 18)
        $lblTargetHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblTargetHelp)

        $btnApplyTargets = New-Object System.Windows.Forms.Button
        $btnApplyTargets.Text = 'Apply Targets'
        $btnApplyTargets.Location = New-Object System.Drawing.Point(12, 428)
        $btnApplyTargets.Size = New-Object System.Drawing.Size(130, 30)
        $btnApplyTargets.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyTargets.ForeColor = $global:UGSM_ColorText
        $btnApplyTargets.FlatStyle = 'Flat'
        $btnApplyTargets.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyTargets)

        $lblProjectileMap = New-Object System.Windows.Forms.Label
        $lblProjectileMap.Text = 'ExplosiveProjectiles'
        $lblProjectileMap.Location = New-Object System.Drawing.Point(470, 150)
        $lblProjectileMap.Size = New-Object System.Drawing.Size(180, 18)
        $lblProjectileMap.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblProjectileMap)

        $lstProjectileMap = New-Object System.Windows.Forms.ListBox
        $lstProjectileMap.Location = New-Object System.Drawing.Point(470, 170)
        $lstProjectileMap.Size = New-Object System.Drawing.Size(340, 220)
        $lstProjectileMap.BackColor = $global:UGSM_ColorInputBackground
        $lstProjectileMap.ForeColor = $global:UGSM_ColorText
        $lstProjectileMap.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($lstProjectileMap)

        $btnAddProjectileMap = New-Object System.Windows.Forms.Button
        $btnAddProjectileMap.Text = 'Add'
        $btnAddProjectileMap.Location = New-Object System.Drawing.Point(825, 170)
        $btnAddProjectileMap.Size = New-Object System.Drawing.Size(90, 28)
        $btnAddProjectileMap.BackColor = $UGSM_ExpansionAccentColor
        $btnAddProjectileMap.ForeColor = $global:UGSM_ColorText
        $btnAddProjectileMap.FlatStyle = 'Flat'
        $btnAddProjectileMap.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnAddProjectileMap)

        $btnRemoveProjectileMap = New-Object System.Windows.Forms.Button
        $btnRemoveProjectileMap.Text = 'Remove'
        $btnRemoveProjectileMap.Location = New-Object System.Drawing.Point(825, 208)
        $btnRemoveProjectileMap.Size = New-Object System.Drawing.Size(90, 28)
        $btnRemoveProjectileMap.BackColor = $global:UGSM_ColorDanger
        $btnRemoveProjectileMap.ForeColor = $global:UGSM_ColorText
        $btnRemoveProjectileMap.FlatStyle = 'Flat'
        $btnRemoveProjectileMap.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnRemoveProjectileMap)

        $lblProjectileKey = New-Object System.Windows.Forms.Label
        $lblProjectileKey.Text = 'Projectile classname'
        $lblProjectileKey.Location = New-Object System.Drawing.Point(950, 170)
        $lblProjectileKey.Size = New-Object System.Drawing.Size(160, 18)
        $lblProjectileKey.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblProjectileKey)

        $txtProjectileKey = New-Object System.Windows.Forms.TextBox
        $txtProjectileKey.Location = New-Object System.Drawing.Point(950, 190)
        $txtProjectileKey.Size = New-Object System.Drawing.Size(280, 26)
        $txtProjectileKey.BackColor = $global:UGSM_ColorInputBackground
        $txtProjectileKey.ForeColor = $global:UGSM_ColorText
        $txtProjectileKey.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtProjectileKey)

        $lblProjectileValue = New-Object System.Windows.Forms.Label
        $lblProjectileValue.Text = 'Explosive ammo classname'
        $lblProjectileValue.Location = New-Object System.Drawing.Point(950, 235)
        $lblProjectileValue.Size = New-Object System.Drawing.Size(190, 18)
        $lblProjectileValue.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblProjectileValue)

        $txtProjectileValue = New-Object System.Windows.Forms.TextBox
        $txtProjectileValue.Location = New-Object System.Drawing.Point(950, 255)
        $txtProjectileValue.Size = New-Object System.Drawing.Size(280, 26)
        $txtProjectileValue.BackColor = $global:UGSM_ColorInputBackground
        $txtProjectileValue.ForeColor = $global:UGSM_ColorText
        $txtProjectileValue.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtProjectileValue)

        $btnApplyProjectileMap = New-Object System.Windows.Forms.Button
        $btnApplyProjectileMap.Text = 'Apply Mapping'
        $btnApplyProjectileMap.Location = New-Object System.Drawing.Point(950, 305)
        $btnApplyProjectileMap.Size = New-Object System.Drawing.Size(140, 30)
        $btnApplyProjectileMap.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyProjectileMap.ForeColor = $global:UGSM_ColorText
        $btnApplyProjectileMap.FlatStyle = 'Flat'
        $btnApplyProjectileMap.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyProjectileMap)

        $lblMapHelp = New-Object System.Windows.Forms.Label
        $lblMapHelp.Text = 'Example: Bullet_40mm_Explosive -> Explosion_40mm_Ammo'
        $lblMapHelp.Location = New-Object System.Drawing.Point(950, 345)
        $lblMapHelp.Size = New-Object System.Drawing.Size(360, 18)
        $lblMapHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblMapHelp)

        $damageSelectedProjectileIndex = -1

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $refreshProjectileMap = {
            $lstProjectileMap.Items.Clear()

            $props = @()
            if ($data.ExplosiveProjectiles -and $data.ExplosiveProjectiles.PSObject -and $data.ExplosiveProjectiles.PSObject.Properties) {
                $props = @($data.ExplosiveProjectiles.PSObject.Properties)
            }

            foreach ($prop in $props) {
                [void]$lstProjectileMap.Items.Add(($prop.Name + ' -> ' + [string]$prop.Value))
            }

            if ($lstProjectileMap.Items.Count -gt 0) {
                if ($damageSelectedProjectileIndex -lt 0 -or $damageSelectedProjectileIndex -ge $lstProjectileMap.Items.Count) {
                    $damageSelectedProjectileIndex = 0
                }
                $lstProjectileMap.SelectedIndex = $damageSelectedProjectileIndex
            }
            else {
                $damageSelectedProjectileIndex = -1
                $txtProjectileKey.Text = ''
                $txtProjectileValue.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedProjectileMap = {
            $props = @()
            if ($data.ExplosiveProjectiles -and $data.ExplosiveProjectiles.PSObject -and $data.ExplosiveProjectiles.PSObject.Properties) {
                $props = @($data.ExplosiveProjectiles.PSObject.Properties)
            }

            $idx = $lstProjectileMap.SelectedIndex
            if ($idx -lt 0 -or $idx -ge $props.Count) {
                $damageSelectedProjectileIndex = -1
                $txtProjectileKey.Text = ''
                $txtProjectileValue.Text = ''
                return
            }

            $damageSelectedProjectileIndex = $idx
            $txtProjectileKey.Text = [string]$props[$idx].Name
            $txtProjectileValue.Text = [string]$props[$idx].Value
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
                $data.CheckForBlockingObjects = $(if ($chkBlocking.Checked) { 1 } else { 0 })

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied DamageSystem top settings.'
                }
            }.GetNewClosure())

        $btnApplyTargets.Add_Click({
                $data.ExplosionTargets = [object[]]@(& $parseLinesToArray $txtExplosionTargets.Text)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied ExplosionTargets.'
                }
            }.GetNewClosure())

        $lstProjectileMap.Add_SelectedIndexChanged({
                & $loadSelectedProjectileMap
            }.GetNewClosure())

        $btnAddProjectileMap.Add_Click({
                $existing = [ordered]@{}
                foreach ($prop in @($data.ExplosiveProjectiles.PSObject.Properties)) {
                    $existing[$prop.Name] = [string]$prop.Value
                }

                $baseName = 'NewProjectile'
                $newKey = $baseName
                $n = 1
                while ($existing.Contains($newKey)) {
                    $newKey = ($baseName + $n)
                    $n++
                }

                $existing[$newKey] = 'NewExplosiveAmmo'
                $data.ExplosiveProjectiles = [pscustomobject]$existing

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $damageSelectedProjectileIndex = $existing.Count - 1
                & $refreshProjectileMap
                & $loadSelectedProjectileMap

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Added projectile mapping.'
                }
            }.GetNewClosure())

        $btnRemoveProjectileMap.Add_Click({
                $props = @($data.ExplosiveProjectiles.PSObject.Properties)
                $idx = $lstProjectileMap.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $props.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a projectile mapping first.')
                    return
                }

                $existing = [ordered]@{}
                for ($i = 0; $i -lt $props.Count; $i++) {
                    if ($i -ne $idx) {
                        $existing[$props[$i].Name] = [string]$props[$i].Value
                    }
                }

                $data.ExplosiveProjectiles = [pscustomobject]$existing

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($existing.Count -eq 0) {
                    $damageSelectedProjectileIndex = -1
                }
                elseif ($idx -ge $existing.Count) {
                    $damageSelectedProjectileIndex = $existing.Count - 1
                }
                else {
                    $damageSelectedProjectileIndex = $idx
                }

                & $refreshProjectileMap
                & $loadSelectedProjectileMap

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removed projectile mapping.'
                }
            }.GetNewClosure())

        $btnApplyProjectileMap.Add_Click({
                $props = @($data.ExplosiveProjectiles.PSObject.Properties)
                $idx = $lstProjectileMap.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $props.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a projectile mapping first.')
                    return
                }

                $newKey = $txtProjectileKey.Text.Trim()
                $newValue = $txtProjectileValue.Text.Trim()

                if ([string]::IsNullOrWhiteSpace($newKey)) {
                    [System.Windows.Forms.MessageBox]::Show('Projectile classname cannot be blank.')
                    return
                }

                if ([string]::IsNullOrWhiteSpace($newValue)) {
                    [System.Windows.Forms.MessageBox]::Show('Explosive ammo classname cannot be blank.')
                    return
                }

                $existing = [ordered]@{}
                for ($i = 0; $i -lt $props.Count; $i++) {
                    if ($i -eq $idx) {
                        $existing[$newKey] = $newValue
                    }
                    else {
                        if (-not $existing.Contains($props[$i].Name)) {
                            $existing[$props[$i].Name] = [string]$props[$i].Value
                        }
                    }
                }

                $data.ExplosiveProjectiles = [pscustomobject]$existing

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                $damageSelectedProjectileIndex = $idx
                & $refreshProjectileMap
                if ($idx -ge 0 -and $idx -lt $lstProjectileMap.Items.Count) {
                    $lstProjectileMap.SelectedIndex = $idx
                }
                & $loadSelectedProjectileMap

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied projectile mapping.'
                }
            }.GetNewClosure())

        $saveDamageSystemSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No DamageSystem settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved DamageSystem settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving DamageSystem settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveDamageSystemSettings
            $SettingsState.FileHandler = 'DamageSystemSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshProjectileMap
        & $loadSelectedProjectileMap

        if ($StatusLabel) {
            $StatusLabel.Text = 'DamageSystem editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'DamageSystem editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'DamageSystem editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_GarageSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'GarageSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Garage settings data.'
        }

        $defaults = [ordered]@{
            m_Version                     = 6
            Enabled                       = 1
            AllowStoringDEVehicles        = 0
            GarageMode                    = 0
            GarageStoreMode               = 0
            GarageRetrieveMode            = 0
            MaxStorableVehicles           = 2
            VehicleSearchRadius           = 20.0
            MaxDistanceFromStoredPosition = 150.0
            CanStoreWithCargo             = 1
            UseVirtualStorageForCargo     = 0
            NeedKeyToStore                = 1
            EntityWhitelist               = @()
            EnableGroupFeatures           = 1
            GroupStoreMode                = 2
            EnableMarketFeatures          = 1
            StorePricePercent             = 5.0
            StaticStorePrice              = 0
            MaxStorableTier1              = 2
            MaxStorableTier2              = 4
            MaxStorableTier3              = 6
            MaxRangeTier1                 = 20.0
            MaxRangeTier2                 = 30.0
            MaxRangeTier3                 = 40.0
            ParkingMeterEnableFlavor      = 1
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 900)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $mainPanel = New-Object System.Windows.Forms.Panel
        $mainPanel.Location = New-Object System.Drawing.Point(0, 0)
        $mainPanel.Size = New-Object System.Drawing.Size(1600, 840)
        $mainPanel.BackColor = $global:UGSM_ColorPanelBackground
        $mainPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($mainPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Garage Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$mainPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Garage mode, storage limits, market/group features, whitelist, and parking meter tiers'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(900, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtVersion)

        $comboConfigs = @(
            @{
                Label = 'GarageMode'; Name = 'cmbGarageMode'; X = 110; Y = 92; W = 180; Value = [int]$data.GarageMode;
                Items = @('0 = Territory Mode', '1 = Personal Mode')
            },
            @{
                Label = 'GarageStoreMode'; Name = 'cmbGarageStoreMode'; X = 310; Y = 92; W = 220; Value = [int]$data.GarageStoreMode;
                Items = @('0 = Personal Mode', '1 = Shared Mode', '2 = Tyrannical Mode')
            },
            @{
                Label = 'GarageRetrieveMode'; Name = 'cmbGarageRetrieveMode'; X = 550; Y = 92; W = 230; Value = [int]$data.GarageRetrieveMode;
                Items = @('0 = Personal Mode', '1 = Shared Mode', '2 = Tyrannical Mode')
            },
            @{
                Label = 'GroupStoreMode'; Name = 'cmbGroupStoreMode'; X = 800; Y = 92; W = 230; Value = [int]$data.GroupStoreMode;
                Items = @('0 = Store only', '1 = Retrieve only', '2 = Store and retrieve')
            }
        )

        $comboBoxes = @{}
        foreach ($cfg in $comboConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, 72)
            $lbl.Size = New-Object System.Drawing.Size($cfg.W, 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$mainPanel.Controls.Add($lbl)

            $cmb = New-Object System.Windows.Forms.ComboBox
            $cmb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cmb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $cmb.DropDownStyle = 'DropDownList'
            $cmb.BackColor = $global:UGSM_ColorInputBackground
            $cmb.ForeColor = $global:UGSM_ColorText
            foreach ($item in $cfg.Items) { [void]$cmb.Items.Add($item) }
            if ($cfg.Value -ge 0 -and $cfg.Value -lt $cmb.Items.Count) { $cmb.SelectedIndex = $cfg.Value } else { $cmb.SelectedIndex = 0 }
            [void]$mainPanel.Controls.Add($cmb)

            $comboBoxes[$cfg.Name] = $cmb
        }

        $checkConfigs = @(
            @{ Text = 'Enabled'; Name = 'chkEnabled'; X = 12; Y = 150; Checked = ([int]$data.Enabled -eq 1) },
            @{ Text = 'AllowStoringDEVehicles'; Name = 'chkAllowStoringDEVehicles'; X = 300; Y = 150; Checked = ([int]$data.AllowStoringDEVehicles -eq 1) },
            @{ Text = 'CanStoreWithCargo'; Name = 'chkCanStoreWithCargo'; X = 600; Y = 150; Checked = ([int]$data.CanStoreWithCargo -eq 1) },
            @{ Text = 'UseVirtualStorageForCargo'; Name = 'chkUseVirtualStorageForCargo'; X = 900; Y = 150; Checked = ([int]$data.UseVirtualStorageForCargo -eq 1) },
            
            @{ Text = 'NeedKeyToStore'; Name = 'chkNeedKeyToStore'; X = 12; Y = 182; Checked = ([int]$data.NeedKeyToStore -eq 1) },
            @{ Text = 'EnableGroupFeatures'; Name = 'chkEnableGroupFeatures'; X = 300; Y = 182; Checked = ([int]$data.EnableGroupFeatures -eq 1) },
            @{ Text = 'EnableMarketFeatures'; Name = 'chkEnableMarketFeatures'; X = 600; Y = 182; Checked = ([int]$data.EnableMarketFeatures -eq 1) },
            @{ Text = 'ParkingMeterEnableFlavor'; Name = 'chkParkingMeterEnableFlavor'; X = 900; Y = 182; Checked = ([int]$data.ParkingMeterEnableFlavor -eq 1) }
        )

        $checkBoxes = @{}
        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(220, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$mainPanel.Controls.Add($cb)
            $checkBoxes[$cfg.Name] = $cb
        }

        $numericConfigs = @(
            @{ Label = 'MaxStorableVehicles'; Name = 'txtMaxStorableVehicles'; X = 12; Y = 250; W = 90; Text = [string]$data.MaxStorableVehicles },
            @{ Label = 'VehicleSearchRadius'; Name = 'txtVehicleSearchRadius'; X = 150; Y = 250; W = 90; Text = [string]$data.VehicleSearchRadius },
            @{ Label = 'MaxDistanceFromStoredPosition'; Name = 'txtMaxDistanceFromStoredPosition'; X = 290; Y = 250; W = 90; Text = [string]$data.MaxDistanceFromStoredPosition },
            @{ Label = 'StorePricePercent'; Name = 'txtStorePricePercent'; X = 460; Y = 250; W = 90; Text = [string]$data.StorePricePercent },
            @{ Label = 'StaticStorePrice'; Name = 'txtStaticStorePrice'; X = 600; Y = 250; W = 90; Text = [string]$data.StaticStorePrice },
            @{ Label = 'MaxStorableTier1'; Name = 'txtMaxStorableTier1'; X = 740; Y = 250; W = 90; Text = [string]$data.MaxStorableTier1 },
            
            @{ Label = 'MaxStorableTier2'; Name = 'txtMaxStorableTier2'; X = 12; Y = 330; W = 90; Text = [string]$data.MaxStorableTier2 },
            @{ Label = 'MaxStorableTier3'; Name = 'txtMaxStorableTier3'; X = 150; Y = 330; W = 90; Text = [string]$data.MaxStorableTier3 },
            @{ Label = 'MaxRangeTier1'; Name = 'txtMaxRangeTier1'; X = 290; Y = 330; W = 90; Text = [string]$data.MaxRangeTier1 },
            @{ Label = 'MaxRangeTier2'; Name = 'txtMaxRangeTier2'; X = 460; Y = 330; W = 90; Text = [string]$data.MaxRangeTier2 },
            @{ Label = 'MaxRangeTier3'; Name = 'txtMaxRangeTier3'; X = 600; Y = 330; W = 90; Text = [string]$data.MaxRangeTier3 }
        )

        $numericTextBoxes = @{}
        foreach ($cfg in $numericConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 50), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$mainPanel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            [void]$mainPanel.Controls.Add($tb)

            $numericTextBoxes[$cfg.Name] = $tb
        }

        $lblWhitelist = New-Object System.Windows.Forms.Label
        $lblWhitelist.Text = 'EntityWhitelist (one per line)'
        $lblWhitelist.Location = New-Object System.Drawing.Point(12, 420)
        $lblWhitelist.Size = New-Object System.Drawing.Size(220, 18)
        $lblWhitelist.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblWhitelist)

        $txtEntityWhitelist = New-Object System.Windows.Forms.TextBox
        $txtEntityWhitelist.Location = New-Object System.Drawing.Point(12, 440)
        $txtEntityWhitelist.Size = New-Object System.Drawing.Size(520, 180)
        $txtEntityWhitelist.Multiline = $true
        $txtEntityWhitelist.ScrollBars = 'Vertical'
        $txtEntityWhitelist.BackColor = $global:UGSM_ColorInputBackground
        $txtEntityWhitelist.ForeColor = $global:UGSM_ColorText
        $txtEntityWhitelist.BorderStyle = 'FixedSingle'
        if ($data.EntityWhitelist) {
            $txtEntityWhitelist.Text = (@($data.EntityWhitelist) -join [Environment]::NewLine)
        }
        [void]$mainPanel.Controls.Add($txtEntityWhitelist)

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'EntityWhitelist defines which entity class names can act as garage access points.'
        $lblHelp.Location = New-Object System.Drawing.Point(12, 628)
        $lblHelp.Size = New-Object System.Drawing.Size(620, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Garage Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 370)
        $btnApplyAll.Size = New-Object System.Drawing.Size(170, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyAll)

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $btnApplyAll.Add_Click({
                $intKeys = @(
                    'txtMaxStorableVehicles',
                    'txtStaticStorePrice',
                    'txtMaxStorableTier1',
                    'txtMaxStorableTier2',
                    'txtMaxStorableTier3'
                )

                $doubleKeys = @(
                    'txtVehicleSearchRadius',
                    'txtMaxDistanceFromStoredPosition',
                    'txtStorePricePercent',
                    'txtMaxRangeTier1',
                    'txtMaxRangeTier2',
                    'txtMaxRangeTier3'
                )

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }

                $data.Enabled = $(if ($checkBoxes['chkEnabled'].Checked) { 1 } else { 0 })
                $data.AllowStoringDEVehicles = $(if ($checkBoxes['chkAllowStoringDEVehicles'].Checked) { 1 } else { 0 })
                $data.GarageMode = $comboBoxes['cmbGarageMode'].SelectedIndex
                $data.GarageStoreMode = $comboBoxes['cmbGarageStoreMode'].SelectedIndex
                $data.GarageRetrieveMode = $comboBoxes['cmbGarageRetrieveMode'].SelectedIndex
                $data.MaxStorableVehicles = [int]$numericTextBoxes['txtMaxStorableVehicles'].Text
                $data.VehicleSearchRadius = [double]$numericTextBoxes['txtVehicleSearchRadius'].Text
                $data.MaxDistanceFromStoredPosition = [double]$numericTextBoxes['txtMaxDistanceFromStoredPosition'].Text
                $data.CanStoreWithCargo = $(if ($checkBoxes['chkCanStoreWithCargo'].Checked) { 1 } else { 0 })
                $data.UseVirtualStorageForCargo = $(if ($checkBoxes['chkUseVirtualStorageForCargo'].Checked) { 1 } else { 0 })
                $data.NeedKeyToStore = $(if ($checkBoxes['chkNeedKeyToStore'].Checked) { 1 } else { 0 })
                $data.EntityWhitelist = [object[]]@(& $parseLinesToArray $txtEntityWhitelist.Text)
                $data.EnableGroupFeatures = $(if ($checkBoxes['chkEnableGroupFeatures'].Checked) { 1 } else { 0 })
                $data.GroupStoreMode = $comboBoxes['cmbGroupStoreMode'].SelectedIndex
                $data.EnableMarketFeatures = $(if ($checkBoxes['chkEnableMarketFeatures'].Checked) { 1 } else { 0 })
                $data.StorePricePercent = [double]$numericTextBoxes['txtStorePricePercent'].Text
                $data.StaticStorePrice = [int]$numericTextBoxes['txtStaticStorePrice'].Text
                $data.MaxStorableTier1 = [int]$numericTextBoxes['txtMaxStorableTier1'].Text
                $data.MaxStorableTier2 = [int]$numericTextBoxes['txtMaxStorableTier2'].Text
                $data.MaxStorableTier3 = [int]$numericTextBoxes['txtMaxStorableTier3'].Text
                $data.MaxRangeTier1 = [double]$numericTextBoxes['txtMaxRangeTier1'].Text
                $data.MaxRangeTier2 = [double]$numericTextBoxes['txtMaxRangeTier2'].Text
                $data.MaxRangeTier3 = [double]$numericTextBoxes['txtMaxRangeTier3'].Text
                $data.ParkingMeterEnableFlavor = $(if ($checkBoxes['chkParkingMeterEnableFlavor'].Checked) { 1 } else { 0 })

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Garage settings.'
                }
            }.GetNewClosure())

        $saveGarageSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Garage settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Garage settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Garage settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveGarageSettings
            $SettingsState.FileHandler = 'GarageSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Garage editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Garage editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Garage editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_GeneralSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'GeneralSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load General settings data.'
        }

        $defaults = [ordered]@{
            m_Version                      = 16
            DisableShootToUnlock           = 0
            EnableGravecross               = 0
            EnableAIGravecross             = 0
            GravecrossDeleteBody           = 1
            GravecrossTimeThreshold        = 1200.0
            GravecrossSpawnTimeDelay       = 180.0
            EnableLamps                    = 3
            LampAmount_OneInX              = 3
            LampSelectionMode              = 'FARTHEST_RANDOM'
            EnableGenerators               = 0
            EnableLighthouses              = 1
            EnableHUDNightvisionOverlay    = 1
            DisableMagicCrosshair          = 0
            EnableAutoRun                  = 1
            UseDeathScreen                 = 1
            UseDeathScreenStatistics       = 1
            UseExpansionMainMenuLogo       = 1
            UseExpansionMainMenuIcons      = 1
            UseExpansionMainMenuIntroScene = 1
            UseNewsFeedInGameMenu          = 1
            UseHUDColors                   = 0
            EnableEarPlugs                 = 1
            InGameMenuLogoPath             = ''
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.PSObject.Properties['Mapping'] -or -not $data.Mapping) {
            $data | Add-Member -NotePropertyName Mapping -NotePropertyValue ([pscustomobject][ordered]@{
                    UseCustomMappingModule = 0
                    Mapping                = @()
                    BuildingInteriors      = 0
                    Interiors              = @()
                    BuildingIvys           = 0
                }) -Force
        }

        foreach ($mk in @('UseCustomMappingModule', 'Mapping', 'BuildingInteriors', 'Interiors', 'BuildingIvys')) {
            if (-not $data.Mapping.PSObject.Properties[$mk]) {
                switch ($mk) {
                    'Mapping' { $data.Mapping | Add-Member -NotePropertyName $mk -NotePropertyValue @() -Force }
                    'Interiors' { $data.Mapping | Add-Member -NotePropertyName $mk -NotePropertyValue @() -Force }
                    default { $data.Mapping | Add-Member -NotePropertyName $mk -NotePropertyValue 0 -Force }
                }
            }
        }

        if (-not $data.PSObject.Properties['HUDColors'] -or -not $data.HUDColors) {
            $data | Add-Member -NotePropertyName HUDColors -NotePropertyValue ([pscustomobject][ordered]@{
                    StaminaBarColor          = 'FFFFFFFF'
                    StaminaBarColorHalf      = 'FFFFFFFF'
                    StaminaBarColorLow       = 'FFFFFFFF'
                    NotifierDividerColor     = 'DCDCDCFF'
                    TemperatureBurningColor  = 'DC0000FF'
                    TemperatureHotColor      = 'DCDC00FF'
                    TemperatureIdealColor    = 'DCDCDCFF'
                    TemperatureColdColor     = '00CED1FF'
                    TemperatureFreezingColor = '1E90DCFF'
                    NotifiersIdealColor      = 'DCDCDCFF'
                    NotifiersHalfColor       = 'DCDC00FF'
                    NotifiersLowColor        = 'DC0000FF'
                    ReputationBaseColor      = 'DCDCDCFF'
                    ReputationMedColor       = 'DCDC00FF'
                    ReputationHighColor      = 'DC0000FF'
                }) -Force
        }

        $hudColorKeys = @(
            'StaminaBarColor',
            'StaminaBarColorHalf',
            'StaminaBarColorLow',
            'NotifierDividerColor',
            'TemperatureBurningColor',
            'TemperatureHotColor',
            'TemperatureIdealColor',
            'TemperatureColdColor',
            'TemperatureFreezingColor',
            'NotifiersIdealColor',
            'NotifiersHalfColor',
            'NotifiersLowColor',
            'ReputationBaseColor',
            'ReputationMedColor',
            'ReputationHighColor'
        )

        foreach ($key in $hudColorKeys) {
            if (-not $data.HUDColors.PSObject.Properties[$key]) {
                $data.HUDColors | Add-Member -NotePropertyName $key -NotePropertyValue 'FFFFFFFF' -Force
            }
        }

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 2100)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 300)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'General Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$topPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Gravecross, mapping, lamps, HUD, menu, and general gameplay toggles'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(760, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$topPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$topPanel.Controls.Add($txtVersion)

        $numericConfigs = @(
