        $lblColorTitle.ForeColor = $global:UGSM_ColorText
        $lblColorTitle.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        [void]$colorPanel.Controls.Add($lblColorTitle)

        $lblColorHelp = New-Object System.Windows.Forms.Label
