        $lblColorHelp.Location = New-Object System.Drawing.Point(12, 34)
        $lblColorHelp.Size = New-Object System.Drawing.Size(420, 18)
        $lblColorHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$colorPanel.Controls.Add($lblColorHelp)

        $colorControls = @{}
