        $btnApplyHUDColors.Text = 'Apply HUD Colors'
        $btnApplyHUDColors.Location = New-Object System.Drawing.Point(12, 470)
        $btnApplyHUDColors.Size = New-Object System.Drawing.Size(160, 30)
        $btnApplyHUDColors.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyHUDColors.ForeColor = $global:UGSM_ColorText
