                $intKeys = @('txtEnableLamps', 'txtLampAmount_OneInX', 'txtEnableGenerators')

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                $data.DisableShootToUnlock = $(if ($checkBoxes['chkDisableShootToUnlock'].Checked) { 1 } else { 0 })
                $data.EnableGravecross = $(if ($checkBoxes['chkEnableGravecross'].Checked) { 1 } else { 0 })
                $data.EnableAIGravecross = $(if ($checkBoxes['chkEnableAIGravecross'].Checked) { 1 } else { 0 })
                $data.GravecrossDeleteBody = $(if ($checkBoxes['chkGravecrossDeleteBody'].Checked) { 1 } else { 0 })
                $data.GravecrossTimeThreshold = [double]$numericTextBoxes['txtGravecrossTimeThreshold'].Text
                $data.GravecrossSpawnTimeDelay = [double]$numericTextBoxes['txtGravecrossSpawnTimeDelay'].Text
                $data.EnableLamps = [int]$numericTextBoxes['txtEnableLamps'].Text
                $data.LampAmount_OneInX = [int]$numericTextBoxes['txtLampAmount_OneInX'].Text
                $data.LampSelectionMode = [string]$cmbLampSelectionMode.SelectedItem
                $data.EnableGenerators = [int]$numericTextBoxes['txtEnableGenerators'].Text
                $data.EnableLighthouses = $(if ($checkBoxes['chkEnableLighthouses'].Checked) { 1 } else { 0 })
                $data.EnableHUDNightvisionOverlay = $(if ($checkBoxes['chkEnableHUDNightvisionOverlay'].Checked) { 1 } else { 0 })
                $data.DisableMagicCrosshair = $(if ($checkBoxes['chkDisableMagicCrosshair'].Checked) { 1 } else { 0 })
                $data.EnableAutoRun = $(if ($checkBoxes['chkEnableAutoRun'].Checked) { 1 } else { 0 })
                $data.UseDeathScreen = $(if ($checkBoxes['chkUseDeathScreen'].Checked) { 1 } else { 0 })
                $data.UseDeathScreenStatistics = $(if ($checkBoxes['chkUseDeathScreenStatistics'].Checked) { 1 } else { 0 })
                $data.UseExpansionMainMenuLogo = $(if ($checkBoxes['chkUseExpansionMainMenuLogo'].Checked) { 1 } else { 0 })
                $data.UseExpansionMainMenuIcons = $(if ($checkBoxes['chkUseExpansionMainMenuIcons'].Checked) { 1 } else { 0 })
                $data.UseExpansionMainMenuIntroScene = $(if ($checkBoxes['chkUseExpansionMainMenuIntroScene'].Checked) { 1 } else { 0 })
                $data.UseNewsFeedInGameMenu = $(if ($checkBoxes['chkUseNewsFeedInGameMenu'].Checked) { 1 } else { 0 })
                $data.UseHUDColors = $(if ($checkBoxes['chkUseHUDColors'].Checked) { 1 } else { 0 })
                $data.EnableEarPlugs = $(if ($checkBoxes['chkEnableEarPlugs'].Checked) { 1 } else { 0 })
                $data.InGameMenuLogoPath = $txtInGameMenuLogoPath.Text.Trim()

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied General top settings.' }
            }.GetNewClosure())

        $btnApplyMapping.Add_Click({
                $data.Mapping.UseCustomMappingModule = $(if ($chkUseCustomMappingModule.Checked) { 1 } else { 0 })
                $data.Mapping.BuildingInteriors = $(if ($chkBuildingInteriors.Checked) { 1 } else { 0 })
                $data.Mapping.BuildingIvys = $(if ($chkBuildingIvys.Checked) { 1 } else { 0 })
                $data.Mapping.Mapping = [object[]]@(& $parseLinesToArray $txtMappingList.Text)
                $data.Mapping.Interiors = [object[]]@(& $parseLinesToArray $txtInteriors.Text)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Mapping settings.' }
            }.GetNewClosure())

        $btnApplyHUDColors.Add_Click({
                foreach ($key in $hudColorKeys) {
                    $hex = ([string]$colorControls[$key].TextBox.Text).Trim().TrimStart('#').ToUpper()
                    if ($hex.Length -ne 8 -or $hex -notmatch '^[0-9A-F]{8}$') {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be an 8-character hex value like FFFFFFFF.'))
                        return
                    }
                }

                foreach ($key in $hudColorKeys) {
                    $data.HUDColors.$key = ([string]$colorControls[$key].TextBox.Text).Trim().TrimStart('#').ToUpper()
                }

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied HUD colors.' }
            }.GetNewClosure())

        $saveGeneralSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No General settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved General settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving General settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveGeneralSettings
            $SettingsState.FileHandler = 'GeneralSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'General editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'General editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'General editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_LogsSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'LogsSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Logs settings data.'
        }

        $logKeys = @(
            'Safezone',
            'AdminTools',
            'ExplosionDamageSystem',
            'VehicleCarKey',
            'VehicleTowing',
            'VehicleLockPicking',
            'VehicleDestroyed',
            'VehicleAttachments',
            'VehicleEnter',
            'VehicleLeave',
            'VehicleDeleted',
            'VehicleEngine',
            'BaseBuildingRaiding',
            'CodeLockRaiding',
            'Territory',
            'Killfeed',
            'SpawnSelection',
            'Party',
            'MissionAirdrop',
            'Chat',
            'Market',
            'ATM',
            'AIGeneral',
            'AIPatrol',
            'AIObjectPatrol',
            'LogToScripts',
            'LogToADM',
            'Hardline',
            'Garage',
            'VehicleCover',
            'EntityStorage',
            'Quests'
        )

        if (-not $data.PSObject.Properties['m_Version']) {
            $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 8 -Force
        }

        foreach ($key in $logKeys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue 0 -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 720)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $mainPanel = New-Object System.Windows.Forms.Panel
        $mainPanel.Location = New-Object System.Drawing.Point(0, 0)
        $mainPanel.Size = New-Object System.Drawing.Size(1600, 660)
        $mainPanel.BackColor = $global:UGSM_ColorPanelBackground
        $mainPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($mainPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Logs Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$mainPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Enable or disable log categories and output targets'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(500, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$mainPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$mainPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$mainPanel.Controls.Add($txtVersion)

        $checkBoxes = @{}
        $columns = 4
        $columnWidth = 360
        $startX = 12
        $startY = 140
        $rowHeight = 30

        for ($i = 0; $i -lt $logKeys.Count; $i++) {
            $key = $logKeys[$i]
            $col = [math]::Floor($i / 8)
            $row = $i % 8

            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $key
            $cb.Location = New-Object System.Drawing.Point(($startX + ($col * $columnWidth)), ($startY + ($row * $rowHeight)))
            $cb.Size = New-Object System.Drawing.Size(320, 22)
            $cb.Checked = ([int]$data.$key -eq 1)
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$mainPanel.Controls.Add($cb)

            $checkBoxes[$key] = $cb
        }

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Logs Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 400)
        $btnApplyAll.Size = New-Object System.Drawing.Size(160, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$mainPanel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                foreach ($key in $logKeys) {
                    $data.$key = $(if ($checkBoxes[$key].Checked) { 1 } else { 0 })
                }

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Logs settings.'
                }
            }.GetNewClosure())

        $saveLogsSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Logs settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Logs settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Logs settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveLogsSettings
            $SettingsState.FileHandler = 'LogsSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Logs editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Logs editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Logs editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_MissionSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'MissionSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Mission settings data.'
        }

        $defaults = [ordered]@{
            m_Version                 = 2
            Enabled                   = 1
            InitialMissionStartDelay  = 300000
            TimeBetweenMissions       = 3600000
            MinMissions               = 0
            MaxMissions               = 1
            MinPlayersToStartMissions = 0
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 360)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 290)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Mission Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Mission enable toggle, mission timing, counts, and minimum player requirement'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(760, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $chkEnabled = New-Object System.Windows.Forms.CheckBox
        $chkEnabled.Text = 'Enabled'
        $chkEnabled.Location = New-Object System.Drawing.Point(110, 92)
        $chkEnabled.Size = New-Object System.Drawing.Size(120, 22)
        $chkEnabled.Checked = ([int]$data.Enabled -eq 1)
        $chkEnabled.ForeColor = $global:UGSM_ColorText
        $chkEnabled.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkEnabled)

        $fieldConfigs = @(
            @{ Label = 'InitialMissionStartDelay'; Name = 'txtInitialMissionStartDelay'; X = 12; Y = 170; W = 120; Text = [string]$data.InitialMissionStartDelay },
            @{ Label = 'TimeBetweenMissions'; Name = 'txtTimeBetweenMissions'; X = 190; Y = 170; W = 120; Text = [string]$data.TimeBetweenMissions },
            @{ Label = 'MinMissions'; Name = 'txtMinMissions'; X = 370; Y = 170; W = 70; Text = [string]$data.MinMissions },
            @{ Label = 'MaxMissions'; Name = 'txtMaxMissions'; X = 500; Y = 170; W = 70; Text = [string]$data.MaxMissions },
            @{ Label = 'MinPlayersToStartMissions'; Name = 'txtMinPlayersToStartMissions'; X = 630; Y = 170; W = 130; Text = [string]$data.MinPlayersToStartMissions }
        )

        $textBoxes = @{}
        foreach ($cfg in $fieldConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 50), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($tb)
            $textBoxes[$cfg.Name] = $tb
        }

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'Mission timing values are milliseconds. MinMissions should not be greater than MaxMissions.'
        $lblHelp.Location = New-Object System.Drawing.Point(12, 208)
        $lblHelp.Size = New-Object System.Drawing.Size(760, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Mission Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 240)
        $btnApplyAll.Size = New-Object System.Drawing.Size(170, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $intKeys = @(
                    'txtInitialMissionStartDelay',
                    'txtTimeBetweenMissions',
                    'txtMinMissions',
                    'txtMaxMissions',
                    'txtMinPlayersToStartMissions'
                )

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($textBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                $minMissions = [int]$textBoxes['txtMinMissions'].Text
                $maxMissions = [int]$textBoxes['txtMaxMissions'].Text
                if ($minMissions -gt $maxMissions) {
                    [System.Windows.Forms.MessageBox]::Show('MinMissions cannot be greater than MaxMissions.')
                    return
                }

                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
                $data.InitialMissionStartDelay = [int]$textBoxes['txtInitialMissionStartDelay'].Text
                $data.TimeBetweenMissions = [int]$textBoxes['txtTimeBetweenMissions'].Text
                $data.MinMissions = $minMissions
                $data.MaxMissions = $maxMissions
                $data.MinPlayersToStartMissions = [int]$textBoxes['txtMinPlayersToStartMissions'].Text

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Mission settings.' }
            }.GetNewClosure())

        $saveMissionSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Mission settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved Mission settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Mission settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveMissionSettings
            $SettingsState.FileHandler = 'MissionSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) { $StatusLabel.Text = 'Mission editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Mission editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'Mission editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_NameTagsSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'NameTagsSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load NameTags settings data.'
        }

        $defaults = [ordered]@{
            m_Version                    = 4
            EnablePlayerTags             = 1
            PlayerTagViewRange           = 5
            PlayerTagsIcon               = 'Persona'
            PlayerTagsColor              = -1
            PlayerNameColor              = -1
            OnlyInSafeZones              = 0
            OnlyInTerritories            = 0
            ShowPlayerItemInHands        = 0
            ShowNPCTags                  = 0
            ShowPlayerFaction            = 0
            UseRarityColorForItemInHands = 0
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $convertIntToColor = {
            param([string]$Value)

            $argb = -1
            if (-not [int]::TryParse($Value, [ref]$argb)) {
                return $global:UGSM_ColorText
            }

            try {
                return [System.Drawing.Color]::FromArgb($argb)
            }
            catch {
                return $global:UGSM_ColorText
            }
        }.GetNewClosure()

        $convertColorToIntString = {
            param([System.Drawing.Color]$Color)
            return [string]$Color.ToArgb()
        }.GetNewClosure()

        $updateIntColorPreview = {
            param($TextBox, $Panel)
            $Panel.BackColor = & $convertIntToColor $TextBox.Text
        }.GetNewClosure()

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 430)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 360)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Name Tags Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(240, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Name tag visibility, range, icon, colors, and display behavior'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(700, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $chkEnablePlayerTags = New-Object System.Windows.Forms.CheckBox
        $chkEnablePlayerTags.Text = 'EnablePlayerTags'
        $chkEnablePlayerTags.Location = New-Object System.Drawing.Point(110, 92)
        $chkEnablePlayerTags.Size = New-Object System.Drawing.Size(160, 22)
        $chkEnablePlayerTags.Checked = ([int]$data.EnablePlayerTags -eq 1)
        $chkEnablePlayerTags.ForeColor = $global:UGSM_ColorText
        $chkEnablePlayerTags.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkEnablePlayerTags)

        $fieldConfigs = @(
            @{ Label = 'PlayerTagViewRange'; Name = 'txtPlayerTagViewRange'; X = 12; Y = 170; W = 100; Text = [string]$data.PlayerTagViewRange },
            @{ Label = 'PlayerTagsIcon'; Name = 'txtPlayerTagsIcon'; X = 150; Y = 170; W = 200; Text = [string]$data.PlayerTagsIcon },
            @{ Label = 'PlayerTagsColor'; Name = 'txtPlayerTagsColor'; X = 390; Y = 170; W = 110; Text = [string]$data.PlayerTagsColor },
            @{ Label = 'PlayerNameColor'; Name = 'txtPlayerNameColor'; X = 620; Y = 170; W = 110; Text = [string]$data.PlayerNameColor }
        )

        $textBoxes = @{}
        foreach ($cfg in $fieldConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 40), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($tb)
            $textBoxes[$cfg.Name] = $tb
        }

        $colorDialog = New-Object System.Windows.Forms.ColorDialog
        $colorDialog.FullOpen = $true

        $pnlPlayerTagsColorPreview = New-Object System.Windows.Forms.Panel
        $pnlPlayerTagsColorPreview.Location = New-Object System.Drawing.Point(510, 170)
        $pnlPlayerTagsColorPreview.Size = New-Object System.Drawing.Size(36, 26)
        $pnlPlayerTagsColorPreview.BorderStyle = 'FixedSingle'
        $pnlPlayerTagsColorPreview.BackColor = & $convertIntToColor $textBoxes['txtPlayerTagsColor'].Text
        [void]$panel.Controls.Add($pnlPlayerTagsColorPreview)

