        [void]$panel.Controls.Add($btnPickPlayerTagsColor)

        $pnlPlayerNameColorPreview = New-Object System.Windows.Forms.Panel
        $pnlPlayerNameColorPreview.Location = New-Object System.Drawing.Point(740, 170)
        $pnlPlayerNameColorPreview.Size = New-Object System.Drawing.Size(36, 26)
        $pnlPlayerNameColorPreview.BorderStyle = 'FixedSingle'
        $pnlPlayerNameColorPreview.BackColor = & $convertIntToColor $textBoxes['txtPlayerNameColor'].Text
        [void]$panel.Controls.Add($pnlPlayerNameColorPreview)

        $btnPickPlayerNameColor = New-Object System.Windows.Forms.Button
        $btnPickPlayerNameColor.Text = 'Pick'
        $btnPickPlayerNameColor.Location = New-Object System.Drawing.Point(786, 168)
        $btnPickPlayerNameColor.Size = New-Object System.Drawing.Size(54, 30)
        $btnPickPlayerNameColor.BackColor = $UGSM_ExpansionAccentColor
        $btnPickPlayerNameColor.ForeColor = $global:UGSM_ColorText
        $btnPickPlayerNameColor.FlatStyle = 'Flat'
        $btnPickPlayerNameColor.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnPickPlayerNameColor)

        $textBoxes['txtPlayerTagsColor'].Add_TextChanged({
                & $updateIntColorPreview $textBoxes['txtPlayerTagsColor'] $pnlPlayerTagsColorPreview
            }.GetNewClosure())

        $textBoxes['txtPlayerNameColor'].Add_TextChanged({
                & $updateIntColorPreview $textBoxes['txtPlayerNameColor'] $pnlPlayerNameColorPreview
            }.GetNewClosure())

        $checkConfigs = @(
            @{ Text = 'OnlyInSafeZones'; Name = 'chkOnlyInSafeZones'; X = 12; Y = 245; Checked = ([int]$data.OnlyInSafeZones -eq 1) },
            @{ Text = 'OnlyInTerritories'; Name = 'chkOnlyInTerritories'; X = 270; Y = 245; Checked = ([int]$data.OnlyInTerritories -eq 1) },
            @{ Text = 'ShowPlayerItemInHands'; Name = 'chkShowPlayerItemInHands'; X = 528; Y = 245; Checked = ([int]$data.ShowPlayerItemInHands -eq 1) },
            @{ Text = 'ShowNPCTags'; Name = 'chkShowNPCTags'; X = 786; Y = 245; Checked = ([int]$data.ShowNPCTags -eq 1) },
            @{ Text = 'ShowPlayerFaction'; Name = 'chkShowPlayerFaction'; X = 1044; Y = 245; Checked = ([int]$data.ShowPlayerFaction -eq 1) },
            @{ Text = 'UseRarityColorForItemInHands'; Name = 'chkUseRarityColorForItemInHands'; X = 1302; Y = 245; Checked = ([int]$data.UseRarityColorForItemInHands -eq 1) }
        )

        $checkBoxes = @{}
        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(260, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$panel.Controls.Add($cb)
            $checkBoxes[$cfg.Name] = $cb
        }

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'PlayerTagsColor and PlayerNameColor use signed integer color values.'
        $lblHelp.Location = New-Object System.Drawing.Point(12, 285)
        $lblHelp.Size = New-Object System.Drawing.Size(520, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Name Tags Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 315)
        $btnApplyAll.Size = New-Object System.Drawing.Size(190, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnPickPlayerTagsColor.Add_Click({
                $colorDialog.Color = & $convertIntToColor $textBoxes['txtPlayerTagsColor'].Text
                if ($colorDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                    $textBoxes['txtPlayerTagsColor'].Text = & $convertColorToIntString $colorDialog.Color
                    & $updateIntColorPreview $textBoxes['txtPlayerTagsColor'] $pnlPlayerTagsColorPreview
                }
            }.GetNewClosure())

        $btnPickPlayerNameColor.Add_Click({
                $colorDialog.Color = & $convertIntToColor $textBoxes['txtPlayerNameColor'].Text
                if ($colorDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                    $textBoxes['txtPlayerNameColor'].Text = & $convertColorToIntString $colorDialog.Color
                    & $updateIntColorPreview $textBoxes['txtPlayerNameColor'] $pnlPlayerNameColorPreview
                }
            }.GetNewClosure())

        $btnApplyAll.Add_Click({
                $range = 0
                if (-not [int]::TryParse($textBoxes['txtPlayerTagViewRange'].Text, [ref]$range)) {
                    [System.Windows.Forms.MessageBox]::Show('PlayerTagViewRange must be a valid integer.')
                    return
                }

                $iconColor = 0
                if (-not [int]::TryParse($textBoxes['txtPlayerTagsColor'].Text, [ref]$iconColor)) {
                    [System.Windows.Forms.MessageBox]::Show('PlayerTagsColor must be a valid integer.')
                    return
                }

                $nameColor = 0
                if (-not [int]::TryParse($textBoxes['txtPlayerNameColor'].Text, [ref]$nameColor)) {
                    [System.Windows.Forms.MessageBox]::Show('PlayerNameColor must be a valid integer.')
                    return
                }

                $data.EnablePlayerTags = $(if ($chkEnablePlayerTags.Checked) { 1 } else { 0 })
                $data.PlayerTagViewRange = $range
                $data.PlayerTagsIcon = $textBoxes['txtPlayerTagsIcon'].Text.Trim()
                $data.PlayerTagsColor = $iconColor
                $data.PlayerNameColor = $nameColor
                $data.OnlyInSafeZones = $(if ($checkBoxes['chkOnlyInSafeZones'].Checked) { 1 } else { 0 })
                $data.OnlyInTerritories = $(if ($checkBoxes['chkOnlyInTerritories'].Checked) { 1 } else { 0 })
                $data.ShowPlayerItemInHands = $(if ($checkBoxes['chkShowPlayerItemInHands'].Checked) { 1 } else { 0 })
                $data.ShowNPCTags = $(if ($checkBoxes['chkShowNPCTags'].Checked) { 1 } else { 0 })
                $data.ShowPlayerFaction = $(if ($checkBoxes['chkShowPlayerFaction'].Checked) { 1 } else { 0 })
                $data.UseRarityColorForItemInHands = $(if ($checkBoxes['chkUseRarityColorForItemInHands'].Checked) { 1 } else { 0 })

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Name Tags settings.' }
            }.GetNewClosure())

        $saveNameTagsSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No NameTags settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved NameTags settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving NameTags settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveNameTagsSettings
            $SettingsState.FileHandler = 'NameTagsSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) { $StatusLabel.Text = 'NameTags editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'NameTags editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'NameTags editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_MonitoringSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'MonitoringSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Monitoring settings data.'
        }

        if (-not $data.PSObject.Properties['m_Version']) {
            $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 1 -Force
        }

        if (-not $data.PSObject.Properties['Enabled']) {
            $data | Add-Member -NotePropertyName Enabled -NotePropertyValue 1 -Force
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 280)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 220)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Monitoring Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Simple monitoring enable toggle'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(320, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $chkEnabled = New-Object System.Windows.Forms.CheckBox
        $chkEnabled.Text = 'Enabled'
        $chkEnabled.Location = New-Object System.Drawing.Point(110, 92)
        $chkEnabled.Size = New-Object System.Drawing.Size(120, 22)
        $chkEnabled.Checked = ([int]$data.Enabled -eq 1)
        $chkEnabled.ForeColor = $global:UGSM_ColorText
        $chkEnabled.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkEnabled)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Monitoring Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 150)
        $btnApplyAll.Size = New-Object System.Drawing.Size(210, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Monitoring settings.'
                }
            }.GetNewClosure())

        $saveMonitoringSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Monitoring settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)

                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Monitoring settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Monitoring settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveMonitoringSettings
            $SettingsState.FileHandler = 'MonitoringSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Monitoring editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Monitoring editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Monitoring editor failed: ' + $_.Exception.Message
        }
    }
}

