    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'TerritorySettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Territory settings data.'
        }

        $defaults = [ordered]@{
            m_Version                             = 6
            EnableTerritories                     = 1
            UseWholeMapForInviteList              = 0
            TerritorySize                         = 150.0
            TerritoryPerimeterSize                = 150.0
            MaxMembersInTerritory                 = 10
            MaxTerritoryPerPlayer                 = 1
            TerritoryInviteAcceptRadius           = 150.0
            AuthenticateCodeLockIfTerritoryMember = 0
            InviteCooldown                        = 0
            OnlyInviteGroupMember                 = 0
            MaxCodeLocksOnBBPerTerritory          = -1
            MaxCodeLocksOnItemsPerTerritory       = -1
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 430)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 360)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Territory Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Territory enable, invite rules, size, limits, and code lock limits'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(700, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $checkConfigs = @(
            @{ Text = 'EnableTerritories'; Name = 'chkEnableTerritories'; X = 110; Y = 92; Checked = ([int]$data.EnableTerritories -eq 1) },
            @{ Text = 'UseWholeMapForInviteList'; Name = 'chkUseWholeMapForInviteList'; X = 280; Y = 92; Checked = ([int]$data.UseWholeMapForInviteList -eq 1) },
            @{ Text = 'AuthenticateCodeLockIfTerritoryMember'; Name = 'chkAuthenticateCodeLockIfTerritoryMember'; X = 520; Y = 92; Checked = ([int]$data.AuthenticateCodeLockIfTerritoryMember -eq 1) },
            @{ Text = 'OnlyInviteGroupMember'; Name = 'chkOnlyInviteGroupMember'; X = 900; Y = 92; Checked = ([int]$data.OnlyInviteGroupMember -eq 1) }
        )

        $checkBoxes = @{}
        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(330, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$panel.Controls.Add($cb)
            $checkBoxes[$cfg.Name] = $cb
        }

        $fieldConfigs = @(
            @{ Label = 'TerritorySize'; Name = 'txtTerritorySize'; X = 12; Y = 170; W = 70; Text = [string]$data.TerritorySize },
            @{ Label = 'TerritoryPerimeterSize'; Name = 'txtTerritoryPerimeterSize'; X = 150; Y = 170; W = 100; Text = [string]$data.TerritoryPerimeterSize },
            @{ Label = 'MaxMembersInTerritory'; Name = 'txtMaxMembersInTerritory'; X = 320; Y = 170; W = 100; Text = [string]$data.MaxMembersInTerritory },
            @{ Label = 'MaxTerritoryPerPlayer'; Name = 'txtMaxTerritoryPerPlayer'; X = 480; Y = 170; W = 100; Text = [string]$data.MaxTerritoryPerPlayer },
            @{ Label = 'TerritoryInviteAcceptRadius'; Name = 'txtTerritoryInviteAcceptRadius'; X = 640; Y = 170; W = 100; Text = [string]$data.TerritoryInviteAcceptRadius },

            @{ Label = 'InviteCooldown'; Name = 'txtInviteCooldown'; X = 12; Y = 245; W = 70; Text = [string]$data.InviteCooldown },
            @{ Label = 'MaxCodeLocksOnBBPerTerritory'; Name = 'txtMaxCodeLocksOnBBPerTerritory'; X = 150; Y = 245; W = 120; Text = [string]$data.MaxCodeLocksOnBBPerTerritory },
            @{ Label = 'MaxCodeLocksOnItemsPerTerritory'; Name = 'txtMaxCodeLocksOnItemsPerTerritory'; X = 340; Y = 245; W = 140; Text = [string]$data.MaxCodeLocksOnItemsPerTerritory }
        )

        $textBoxes = @{}
        foreach ($cfg in $fieldConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 60), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($tb)
            $textBoxes[$cfg.Name] = $tb
        }

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'Size and radius fields are meters. MaxCodeLocks values of -1 mean unlimited.'
        $lblHelp.Location = New-Object System.Drawing.Point(12, 285)
        $lblHelp.Size = New-Object System.Drawing.Size(620, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Territory Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 315)
        $btnApplyAll.Size = New-Object System.Drawing.Size(180, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $doubleKeys = @(
                    'txtTerritorySize',
                    'txtTerritoryPerimeterSize',
                    'txtTerritoryInviteAcceptRadius'
                )

                $intKeys = @(
                    'txtMaxMembersInTerritory',
                    'txtMaxTerritoryPerPlayer',
                    'txtInviteCooldown',
                    'txtMaxCodeLocksOnBBPerTerritory',
                    'txtMaxCodeLocksOnItemsPerTerritory'
                )

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($textBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($textBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                $data.EnableTerritories = $(if ($checkBoxes['chkEnableTerritories'].Checked) { 1 } else { 0 })
                $data.UseWholeMapForInviteList = $(if ($checkBoxes['chkUseWholeMapForInviteList'].Checked) { 1 } else { 0 })
                $data.AuthenticateCodeLockIfTerritoryMember = $(if ($checkBoxes['chkAuthenticateCodeLockIfTerritoryMember'].Checked) { 1 } else { 0 })
                $data.OnlyInviteGroupMember = $(if ($checkBoxes['chkOnlyInviteGroupMember'].Checked) { 1 } else { 0 })

                $data.TerritorySize = [double]$textBoxes['txtTerritorySize'].Text
                $data.TerritoryPerimeterSize = [double]$textBoxes['txtTerritoryPerimeterSize'].Text
                $data.MaxMembersInTerritory = [int]$textBoxes['txtMaxMembersInTerritory'].Text
                $data.MaxTerritoryPerPlayer = [int]$textBoxes['txtMaxTerritoryPerPlayer'].Text
                $data.TerritoryInviteAcceptRadius = [double]$textBoxes['txtTerritoryInviteAcceptRadius'].Text
                $data.InviteCooldown = [int]$textBoxes['txtInviteCooldown'].Text
                $data.MaxCodeLocksOnBBPerTerritory = [int]$textBoxes['txtMaxCodeLocksOnBBPerTerritory'].Text
                $data.MaxCodeLocksOnItemsPerTerritory = [int]$textBoxes['txtMaxCodeLocksOnItemsPerTerritory'].Text

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Territory settings.' }
            }.GetNewClosure())

        $saveTerritorySettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Territory settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved Territory settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Territory settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveTerritorySettings
            $SettingsState.FileHandler = 'TerritorySettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) { $StatusLabel.Text = 'Territory editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Territory editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'Territory editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_NotificationSchedulerSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'NotificationSchedulerSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load NotificationScheduler settings data.'
        }

        $defaults = [ordered]@{
            m_Version      = 2
            Enabled        = 0
            UTC            = 0
            UseMissionTime = 0
            Notifications  = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.Notifications) {
            $data.Notifications = @()
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 760)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $notificationSelectedIndex = -1

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 700)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Notification Scheduler Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(300, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Scheduled notifications with time, text, icon, and color'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(600, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $chkEnabled = New-Object System.Windows.Forms.CheckBox
        $chkEnabled.Text = 'Enabled'
        $chkEnabled.Location = New-Object System.Drawing.Point(110, 92)
        $chkEnabled.Size = New-Object System.Drawing.Size(120, 22)
        $chkEnabled.Checked = ([int]$data.Enabled -eq 1)
        $chkEnabled.ForeColor = $global:UGSM_ColorText
        $chkEnabled.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkEnabled)

        $chkUTC = New-Object System.Windows.Forms.CheckBox
        $chkUTC.Text = 'UTC'
        $chkUTC.Location = New-Object System.Drawing.Point(240, 92)
        $chkUTC.Size = New-Object System.Drawing.Size(90, 22)
        $chkUTC.Checked = ([int]$data.UTC -eq 1)
        $chkUTC.ForeColor = $global:UGSM_ColorText
        $chkUTC.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkUTC)

        $chkUseMissionTime = New-Object System.Windows.Forms.CheckBox
        $chkUseMissionTime.Text = 'UseMissionTime'
        $chkUseMissionTime.Location = New-Object System.Drawing.Point(330, 92)
        $chkUseMissionTime.Size = New-Object System.Drawing.Size(160, 22)
        $chkUseMissionTime.Checked = ([int]$data.UseMissionTime -eq 1)
        $chkUseMissionTime.ForeColor = $global:UGSM_ColorText
        $chkUseMissionTime.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkUseMissionTime)

        $btnApplyTop = New-Object System.Windows.Forms.Button
        $btnApplyTop.Text = 'Apply Top Settings'
        $btnApplyTop.Location = New-Object System.Drawing.Point(520, 88)
        $btnApplyTop.Size = New-Object System.Drawing.Size(150, 30)
        $btnApplyTop.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyTop.ForeColor = $global:UGSM_ColorText
        $btnApplyTop.FlatStyle = 'Flat'
        $btnApplyTop.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyTop)

        $lstNotifications = New-Object System.Windows.Forms.ListBox
        $lstNotifications.Location = New-Object System.Drawing.Point(12, 150)
        $lstNotifications.Size = New-Object System.Drawing.Size(360, 420)
        $lstNotifications.BackColor = $global:UGSM_ColorInputBackground
        $lstNotifications.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lstNotifications)

        $btnAddNotification = New-Object System.Windows.Forms.Button
        $btnAddNotification.Text = 'Add Notification'
        $btnAddNotification.Location = New-Object System.Drawing.Point(12, 590)
        $btnAddNotification.Size = New-Object System.Drawing.Size(150, 30)
        $btnAddNotification.BackColor = $UGSM_ExpansionAccentColor
        $btnAddNotification.ForeColor = $global:UGSM_ColorText
        $btnAddNotification.FlatStyle = 'Flat'
        $btnAddNotification.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnAddNotification)

        $btnRemoveNotification = New-Object System.Windows.Forms.Button
        $btnRemoveNotification.Text = 'Remove Notification'
        $btnRemoveNotification.Location = New-Object System.Drawing.Point(175, 590)
        $btnRemoveNotification.Size = New-Object System.Drawing.Size(160, 30)
        $btnRemoveNotification.BackColor = $global:UGSM_ColorDanger
        $btnRemoveNotification.ForeColor = $global:UGSM_ColorText
        $btnRemoveNotification.FlatStyle = 'Flat'
        $btnRemoveNotification.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnRemoveNotification)

        $detailX = 410

        $fieldConfigs = @(
            @{ Label = 'Hour'; Name = 'txtHour'; X = $detailX; Y = 170; W = 50; Text = '' },
            @{ Label = 'Minute'; Name = 'txtMinute'; X = ($detailX + 110); Y = 170; W = 50; Text = '' },
            @{ Label = 'Second'; Name = 'txtSecond'; X = ($detailX + 220); Y = 170; W = 50; Text = '' },
            @{ Label = 'Icon'; Name = 'txtIcon'; X = ($detailX + 330); Y = 170; W = 130; Text = '' },
            @{ Label = 'Color'; Name = 'txtColor'; X = ($detailX + 530); Y = 170; W = 60; Text = '' },

            @{ Label = 'Title'; Name = 'txtTitle'; X = $detailX; Y = 250; W = 420; Text = '' },
            @{ Label = 'Text'; Name = 'txtText'; X = $detailX; Y = 330; W = 700; Text = '' }
        )

        $textBoxes = @{}
        foreach ($cfg in $fieldConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, ($cfg.Y - 20))
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 40), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'

            if ($cfg.Name -eq 'txtText') {
                $tb.Multiline = $true
                $tb.ScrollBars = 'Vertical'
                $tb.Size = New-Object System.Drawing.Size($cfg.W, 140)
            }

            [void]$panel.Controls.Add($tb)
            $textBoxes[$cfg.Name] = $tb
        }

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'Hour uses 0-23. Minute and Second use 0-59. Color is kept as raw text.'
        $lblHelp.Location = New-Object System.Drawing.Point($detailX, 490)
        $lblHelp.Size = New-Object System.Drawing.Size(520, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblHelp)

        $btnApplyNotification = New-Object System.Windows.Forms.Button
        $btnApplyNotification.Text = 'Apply Notification'
        $btnApplyNotification.Location = New-Object System.Drawing.Point($detailX, 530)
        $btnApplyNotification.Size = New-Object System.Drawing.Size(150, 32)
        $btnApplyNotification.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyNotification.ForeColor = $global:UGSM_ColorText
        $btnApplyNotification.FlatStyle = 'Flat'
        $btnApplyNotification.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyNotification)

        $refreshNotifications = {
            $lstNotifications.Items.Clear()
            $notifications = @($data.Notifications)

            foreach ($n in $notifications) {
                $line = ('{0:D2}:{1:D2}:{2:D2} - {3}' -f [int]$n.Hour, [int]$n.Minute, [int]$n.Second, [string]$n.Title)
                [void]$lstNotifications.Items.Add($line)
            }

            if ($lstNotifications.Items.Count -gt 0) {
                if ($notificationSelectedIndex -lt 0 -or $notificationSelectedIndex -ge $lstNotifications.Items.Count) {
                    $notificationSelectedIndex = 0
                }
                $lstNotifications.SelectedIndex = $notificationSelectedIndex
            }
            else {
                $notificationSelectedIndex = -1
            }
        }.GetNewClosure()

        $loadSelectedNotification = {
            $notifications = @($data.Notifications)
            $idx = $lstNotifications.SelectedIndex

            if ($idx -lt 0 -or $idx -ge $notifications.Count) {
                $notificationSelectedIndex = -1
                foreach ($name in $textBoxes.Keys) {
                    $textBoxes[$name].Text = ''
                }
                return
            }

            $notificationSelectedIndex = $idx
            $n = $notifications[$idx]

            $textBoxes['txtHour'].Text = [string]$n.Hour
            $textBoxes['txtMinute'].Text = [string]$n.Minute
            $textBoxes['txtSecond'].Text = [string]$n.Second
            $textBoxes['txtTitle'].Text = [string]$n.Title
            $textBoxes['txtText'].Text = [string]$n.Text
            $textBoxes['txtIcon'].Text = [string]$n.Icon
            $textBoxes['txtColor'].Text = [string]$n.Color
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $data.Enabled = $(if ($chkEnabled.Checked) { 1 } else { 0 })
                $data.UTC = $(if ($chkUTC.Checked) { 1 } else { 0 })
                $data.UseMissionTime = $(if ($chkUseMissionTime.Checked) { 1 } else { 0 })

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied NotificationScheduler top settings.' }
            }.GetNewClosure())

        $lstNotifications.Add_SelectedIndexChanged({
                & $loadSelectedNotification
            }.GetNewClosure())

        $btnAddNotification.Add_Click({
                $notifications = @($data.Notifications)
                $notifications += [pscustomobject][ordered]@{
                    Hour   = 0
                    Minute = 0
                    Second = 0
                    Title  = 'New Notification'
                    Text   = ''
                    Icon   = 'Info'
                    Color  = ''
                }

                $data.Notifications = [object[]]@($notifications)

                if ($SettingsState) { $SettingsState.Data = $data }

                $notificationSelectedIndex = $notifications.Count - 1
                & $refreshNotifications
                & $loadSelectedNotification
            }.GetNewClosure())

        $btnRemoveNotification.Add_Click({
                $notifications = @($data.Notifications)
                $idx = $lstNotifications.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $notifications.Count) { return }

                $newNotifications = @()
                for ($i = 0; $i -lt $notifications.Count; $i++) {
                    if ($i -ne $idx) {
                        $newNotifications += $notifications[$i]
                    }
                }

                $data.Notifications = [object[]]@($newNotifications)

                if ($SettingsState) { $SettingsState.Data = $data }

                if ($newNotifications.Count -eq 0) {
                    $notificationSelectedIndex = -1
                }
                elseif ($idx -ge $newNotifications.Count) {
                    $notificationSelectedIndex = $newNotifications.Count - 1
                }
                else {
                    $notificationSelectedIndex = $idx
                }

                & $refreshNotifications
                & $loadSelectedNotification
            }.GetNewClosure())

        $btnApplyNotification.Add_Click({
                $idx = $lstNotifications.SelectedIndex
                $notifications = @($data.Notifications)

                if ($idx -lt 0 -or $idx -ge $notifications.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a notification first.')
                    return
                }

                $hour = 0
                $minute = 0
                $second = 0

                if (-not [int]::TryParse($textBoxes['txtHour'].Text, [ref]$hour)) {
                    [System.Windows.Forms.MessageBox]::Show('Hour must be a valid integer.')
                    return
                }
                if (-not [int]::TryParse($textBoxes['txtMinute'].Text, [ref]$minute)) {
                    [System.Windows.Forms.MessageBox]::Show('Minute must be a valid integer.')
                    return
                }
                if (-not [int]::TryParse($textBoxes['txtSecond'].Text, [ref]$second)) {
                    [System.Windows.Forms.MessageBox]::Show('Second must be a valid integer.')
                    return
                }

                if ($hour -lt 0 -or $hour -gt 23) {
                    [System.Windows.Forms.MessageBox]::Show('Hour must be between 0 and 23.')
                    return
                }
                if ($minute -lt 0 -or $minute -gt 59) {
                    [System.Windows.Forms.MessageBox]::Show('Minute must be between 0 and 59.')
                    return
                }
                if ($second -lt 0 -or $second -gt 59) {
                    [System.Windows.Forms.MessageBox]::Show('Second must be between 0 and 59.')
                    return
                }

                $notifications[$idx] = [pscustomobject][ordered]@{
                    Hour   = $hour
                    Minute = $minute
                    Second = $second
                    Title  = $textBoxes['txtTitle'].Text.Trim()
                    Text   = $textBoxes['txtText'].Text
                    Icon   = $textBoxes['txtIcon'].Text.Trim()
                    Color  = $textBoxes['txtColor'].Text.Trim()
                }

                $data.Notifications = [object[]]@($notifications)

                if ($SettingsState) { $SettingsState.Data = $data }

                $notificationSelectedIndex = $idx
                & $refreshNotifications
                if ($idx -ge 0 -and $idx -lt $lstNotifications.Items.Count) {
                    $lstNotifications.SelectedIndex = $idx
                }
            }.GetNewClosure())

        $saveNotificationSchedulerSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No NotificationScheduler settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved NotificationScheduler settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving NotificationScheduler settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveNotificationSchedulerSettings
            $SettingsState.FileHandler = 'NotificationSchedulerSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshNotifications
        & $loadSelectedNotification

        if ($StatusLabel) { $StatusLabel.Text = 'NotificationScheduler editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'NotificationScheduler editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'NotificationScheduler editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_NotificationSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'NotificationSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
