            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Notification settings data.'
        }

        $allKeys = @(
            'EnableNotification',
            'ShowPlayerJoinServer',
            'JoinMessageType',
            'ShowPlayerLeftServer',
            'LeftMessageType',
            'ShowAirdropStarted',
            'ShowAirdropClosingOn',
            'ShowAirdropDropped',
