            'KillFeedCarHitNoDriver',
            'KillFeedCarCrash',
            'KillFeedCarCrashCrew',
            'KillFeedHeliHitDriver',
            'KillFeedHeliHitNoDriver',
            'KillFeedHeliCrash',
            'KillFeedHeliCrashCrew',
            'KillFeedBoatHitDriver',
            'KillFeedBoatHitNoDriver',
            'KillFeedBoatCrash',
            'KillFeedBoatCrashCrew',
            'KillFeedBarbedWire',
            'KillFeedFire',
            'KillFeedWeaponExplosion',
            'KillFeedDehydration',
            'KillFeedStarvation',
            'KillFeedBleeding',
            'KillFeedStatusEffects',
            'KillFeedSuicide',
            'KillFeedWeapon',
            'KillFeedMeleeWeapon',
            'KillFeedBarehands',
            'KillFeedInfected',
            'KillFeedAnimal',
            'KillFeedAI',
            'KillFeedDrowned',
            'KillFeedKilledUnknown',
            'KillFeedDiedUnknown',
            'EnableKillFeedDiscordMsg'
        )

        if (-not $data.PSObject.Properties['m_Version']) {
            $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 5 -Force
        }

        foreach ($key in $allKeys) {
            if (-not $data.PSObject.Properties[$key]) {
                $defaultValue = 0
                if ($key -in @('JoinMessageType', 'LeftMessageType', 'KillFeedMessageType')) {
                    $defaultValue = 1
                }
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaultValue -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 980)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 920)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

