        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Join/left notifications, airdrop notices, territory notifications, and kill-feed options'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(820, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $chkEnableNotification = New-Object System.Windows.Forms.CheckBox
