        $chkEnableNotification.Checked = ([int]$data.EnableNotification -eq 1)
        $chkEnableNotification.ForeColor = $global:UGSM_ColorText
        $chkEnableNotification.BackColor = [System.Drawing.Color]::Transparent
        [void]$panel.Controls.Add($chkEnableNotification)

        $messageTypeConfigs = @(
            @{ Label = 'JoinMessageType'; Name = 'cmbJoinMessageType'; X = 320; Value = [int]$data.JoinMessageType },
            @{ Label = 'LeftMessageType'; Name = 'cmbLeftMessageType'; X = 550; Value = [int]$data.LeftMessageType },
            @{ Label = 'KillFeedMessageType'; Name = 'cmbKillFeedMessageType'; X = 780; Value = [int]$data.KillFeedMessageType }
        )

        $comboBoxes = @{}
        foreach ($cfg in $messageTypeConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, 72)
            $lbl.Size = New-Object System.Drawing.Size(160, 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $cmb = New-Object System.Windows.Forms.ComboBox
            $cmb.Location = New-Object System.Drawing.Point($cfg.X, 92)
            $cmb.Size = New-Object System.Drawing.Size(200, 26)
            $cmb.DropDownStyle = 'DropDownList'
            $cmb.BackColor = $global:UGSM_ColorText
            foreach ($item in @('0 = Chat', '1 = Top-left notification')) { [void]$cmb.Items.Add($item) }
            if ($cfg.Value -ge 0 -and $cfg.Value -lt 2) { $cmb.SelectedIndex = $cfg.Value } else { $cmb.SelectedIndex = 1 }
            [void]$panel.Controls.Add($cmb)

            $comboBoxes[$cfg.Name] = $cmb
        }

        $checkBoxes = @{}
        $checkConfigs = @(
            'ShowPlayerJoinServer',
            'ShowPlayerLeftServer',
            'ShowAirdropStarted',
            'ShowAirdropClosingOn',
            'ShowAirdropDropped',
            'ShowAirdropEnded',
            'ShowPlayerAirdropStarted',
            'ShowPlayerAirdropClosingOn',
            'ShowPlayerAirdropDropped',
            'ShowTerritoryNotifications',
            'EnableKillFeed',
            'KillFeedFall',
            'KillFeedCarHitDriver',
            'KillFeedCarHitNoDriver',
            'KillFeedCarCrash',
            'KillFeedCarCrashCrew',
            'KillFeedHeliHitDriver',
            'KillFeedHeliHitNoDriver',
            'KillFeedHeliCrash',
            'KillFeedHeliCrashCrew',
            'KillFeedBoatHitDriver',
            'KillFeedBoatHitNoDriver',
            'KillFeedBoatCrash',
            'KillFeedBoatCrashCrew',
            'KillFeedBarbedWire',
            'KillFeedFire',
            'KillFeedWeaponExplosion',
            'KillFeedDehydration',
            'KillFeedStarvation',
            'KillFeedBleeding',
            'KillFeedStatusEffects',
            'KillFeedSuicide',
            'KillFeedWeapon',
            'KillFeedMeleeWeapon',
            'KillFeedBarehands',
            'KillFeedInfected',
            'KillFeedAnimal',
            'KillFeedAI',
            'KillFeedDrowned',
            'KillFeedKilledUnknown',
            'KillFeedDiedUnknown',
            'EnableKillFeedDiscordMsg'
        )

        $startX = 12
        $startY = 160
        $columnWidth = 380
        $rowHeight = 28

        for ($i = 0; $i -lt $checkConfigs.Count; $i++) {
            $key = $checkConfigs[$i]
            $col = [math]::Floor($i / 11)
            $row = $i % 11

            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $key
            $cb.Location = New-Object System.Drawing.Point(($startX + ($col * $columnWidth)), ($startY + ($row * $rowHeight)))
            $cb.Size = New-Object System.Drawing.Size(340, 22)
            $cb.Checked = ([int]$data.$key -eq 1)
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$panel.Controls.Add($cb)

            $checkBoxes[$key] = $cb
        }

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Notification Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 475)
        $btnApplyAll.Size = New-Object System.Drawing.Size(210, 32)
