        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $data.EnableNotification = $(if ($chkEnableNotification.Checked) { 1 } else { 0 })
                $data.JoinMessageType = $comboBoxes['cmbJoinMessageType'].SelectedIndex
                $data.LeftMessageType = $comboBoxes['cmbLeftMessageType'].SelectedIndex
                $data.KillFeedMessageType = $comboBoxes['cmbKillFeedMessageType'].SelectedIndex

                foreach ($key in $checkConfigs) {
                    $data.$key = $(if ($checkBoxes[$key].Checked) { 1 } else { 0 })
                }

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Notification settings.'
                }
            }.GetNewClosure())

        $saveNotificationSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Notification settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Notification settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Notification settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveNotificationSettings
            $SettingsState.FileHandler = 'NotificationSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Notification editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Notification editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Notification editor failed: ' + $_.Exception.Message
        }
    }
}

