        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 400)
        $btnApplyAll.Size = New-Object System.Drawing.Size(170, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $maxMembers = 0
                if (-not [int]::TryParse($txtMaxMembersInParty.Text, [ref]$maxMembers)) {
                    [System.Windows.Forms.MessageBox]::Show('MaxMembersInParty must be a valid integer.')
                    return
                }

                $inviteCooldown = 0
                if (-not [int]::TryParse($txtInviteCooldown.Text, [ref]$inviteCooldown)) {
                    [System.Windows.Forms.MessageBox]::Show('InviteCooldown must be a valid integer.')
                    return
                }

                foreach ($key in $checkKeys) {
                    $data.$key = $(if ($checkBoxes[$key].Checked) { 1 } else { 0 })
                }

                $data.MaxMembersInParty = $maxMembers
                $data.InviteCooldown = $inviteCooldown

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applied Party settings.'
                }
            }.GetNewClosure())

        $savePartySettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Party settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) {
                    $SettingsState.Data = $data
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Party settings: ' + [System.IO.Path]::GetFileName($FilePath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Party settings failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $savePartySettings
            $SettingsState.FileHandler = 'PartySettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) {
            $StatusLabel.Text = 'Party editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Party editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Party editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_QuestSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'QuestSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Quest settings data.'
        }

        $defaults = [ordered]@{
            m_Version                    = 10
            EnableQuests                 = 1
            EnableQuestLogTab            = 1
            CreateQuestNPCMarkers        = 1
            QuestAcceptedTitle           = 'Quest Accepted'
            QuestAcceptedText            = 'The quest %1 has been accepted!'
            QuestCompletedTitle          = 'Quest Completed'
            QuestCompletedText           = 'All objectives of the quest %1 have been completed'
            QuestFailedTitle             = 'Quest Failed'
            QuestFailedText              = 'The quest %1 failed!'
            QuestCanceledTitle           = 'Quest Canceled'
            QuestCanceledText            = 'The quest %1 has been canceled!'
            QuestTurnInTitle             = 'Quest Turn-In'
            QuestTurnInText              = 'The quest %1 has been completed!'
            QuestObjectiveCompletedTitle = 'Objective Completed'
            QuestObjectiveCompletedText  = 'You have completed the objective %1 of the quest %2.'
            QuestCooldownTitle           = 'Quest Cooldown'
            QuestCooldownText            = 'This quest is still on cooldown! Come back in %1'
            QuestNotInGroupTitle         = 'Group Quest'
            QuestNotInGroupText          = 'Group quests can only be accepted while in a group!'
            QuestNotGroupOwnerTitle      = 'Group Quest'
            QuestNotGroupOwnerText       = 'Only a group owner can accept and turn-in a group quest!'
            GroupQuestMode               = 0
            AchievementCompletedTitle    = 'Achievement "%1" completed!'
            AchievementCompletedText     = '%1'
            WeeklyResetDay               = 'Wednesday'
            WeeklyResetMinute            = 0
            WeeklyResetHour              = 8
            DailyResetHour               = 8
            DailyResetMinute             = 0
            UseUTCTime                   = 0
            UseQuestNPCIndicators        = 1
            MaxActiveQuests              = -1
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1800)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
        $panel.Location = New-Object System.Drawing.Point(0, 0)
        $panel.Size = New-Object System.Drawing.Size(1600, 1720)
        $panel.BackColor = $global:UGSM_ColorPanelBackground
        $panel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($panel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Quest Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$panel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Quest toggles, quest message strings, quest reset schedule, and group quest behavior'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(860, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtVersion)

        $checkBoxes = @{}
        $checkConfigs = @(
            @{ Text = 'EnableQuests'; Name = 'chkEnableQuests'; X = 110; Y = 92; Checked = ([int]$data.EnableQuests -eq 1) },
            @{ Text = 'EnableQuestLogTab'; Name = 'chkEnableQuestLogTab'; X = 110; Y = 120; Checked = ([int]$data.EnableQuestLogTab -eq 1) },
            @{ Text = 'CreateQuestNPCMarkers'; Name = 'chkCreateQuestNPCMarkers'; X = 450; Y = 92; Checked = ([int]$data.CreateQuestNPCMarkers -eq 1) },
            @{ Text = 'UseUTCTime'; Name = 'chkUseUTCTime'; X = 800; Y = 92; Checked = ([int]$data.UseUTCTime -eq 1) },
            @{ Text = 'UseQuestNPCIndicators'; Name = 'chkUseQuestNPCIndicators'; X = 450; Y = 120; Checked = ([int]$data.UseQuestNPCIndicators -eq 1) }
        )

        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Size = New-Object System.Drawing.Size(220, 22)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$panel.Controls.Add($cb)
            $checkBoxes[$cfg.Name] = $cb
        }

        $lblGroupQuestMode = New-Object System.Windows.Forms.Label
        $lblGroupQuestMode.Text = 'GroupQuestMode'
        $lblGroupQuestMode.Location = New-Object System.Drawing.Point(1100, 72)
        $lblGroupQuestMode.Size = New-Object System.Drawing.Size(130, 18)
        $lblGroupQuestMode.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblGroupQuestMode)

        $cmbGroupQuestMode = New-Object System.Windows.Forms.ComboBox
        $cmbGroupQuestMode.Location = New-Object System.Drawing.Point(1100, 92)
        $cmbGroupQuestMode.Size = New-Object System.Drawing.Size(220, 26)
        $cmbGroupQuestMode.DropDownStyle = 'DropDownList'
        foreach ($item in @('0', '1', '2')) { [void]$cmbGroupQuestMode.Items.Add($item) }
        $groupModeIndex = [int]$data.GroupQuestMode
        if ($groupModeIndex -ge 0 -and $groupModeIndex -lt $cmbGroupQuestMode.Items.Count) {
            $cmbGroupQuestMode.SelectedIndex = $groupModeIndex
        }
        else {
            $cmbGroupQuestMode.SelectedIndex = 0
        }
        [void]$panel.Controls.Add($cmbGroupQuestMode)

        $lblMaxActiveQuests = New-Object System.Windows.Forms.Label
        $lblMaxActiveQuests.Text = 'MaxActiveQuests'
        $lblMaxActiveQuests.Location = New-Object System.Drawing.Point(1340, 72)
        $lblMaxActiveQuests.Size = New-Object System.Drawing.Size(120, 18)
        $lblMaxActiveQuests.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblMaxActiveQuests)

        $txtMaxActiveQuests = New-Object System.Windows.Forms.TextBox
        $txtMaxActiveQuests.Location = New-Object System.Drawing.Point(1340, 92)
        $txtMaxActiveQuests.Size = New-Object System.Drawing.Size(120, 26)
        $txtMaxActiveQuests.Text = [string]$data.MaxActiveQuests
        $txtMaxActiveQuests.BackColor = $global:UGSM_ColorInputBackground
        $txtMaxActiveQuests.ForeColor = $global:UGSM_ColorText
        $txtMaxActiveQuests.BorderStyle = 'FixedSingle'
        [void]$panel.Controls.Add($txtMaxActiveQuests)

        $messageConfigs = @(
            @{ TitleLabel = 'QuestAcceptedTitle'; TitleName = 'txtQuestAcceptedTitle'; TitleText = [string]$data.QuestAcceptedTitle; TextLabel = 'QuestAcceptedText'; TextName = 'txtQuestAcceptedText'; TextText = [string]$data.QuestAcceptedText; Y = 170 },
            @{ TitleLabel = 'QuestCompletedTitle'; TitleName = 'txtQuestCompletedTitle'; TitleText = [string]$data.QuestCompletedTitle; TextLabel = 'QuestCompletedText'; TextName = 'txtQuestCompletedText'; TextText = [string]$data.QuestCompletedText; Y = 285 },
            @{ TitleLabel = 'QuestFailedTitle'; TitleName = 'txtQuestFailedTitle'; TitleText = [string]$data.QuestFailedTitle; TextLabel = 'QuestFailedText'; TextName = 'txtQuestFailedText'; TextText = [string]$data.QuestFailedText; Y = 400 },
            @{ TitleLabel = 'QuestCanceledTitle'; TitleName = 'txtQuestCanceledTitle'; TitleText = [string]$data.QuestCanceledTitle; TextLabel = 'QuestCanceledText'; TextName = 'txtQuestCanceledText'; TextText = [string]$data.QuestCanceledText; Y = 515 },
            @{ TitleLabel = 'QuestTurnInTitle'; TitleName = 'txtQuestTurnInTitle'; TitleText = [string]$data.QuestTurnInTitle; TextLabel = 'QuestTurnInText'; TextName = 'txtQuestTurnInText'; TextText = [string]$data.QuestTurnInText; Y = 630 },
            @{ TitleLabel = 'QuestObjectiveCompletedTitle'; TitleName = 'txtQuestObjectiveCompletedTitle'; TitleText = [string]$data.QuestObjectiveCompletedTitle; TextLabel = 'QuestObjectiveCompletedText'; TextName = 'txtQuestObjectiveCompletedText'; TextText = [string]$data.QuestObjectiveCompletedText; Y = 745 },
            @{ TitleLabel = 'QuestCooldownTitle'; TitleName = 'txtQuestCooldownTitle'; TitleText = [string]$data.QuestCooldownTitle; TextLabel = 'QuestCooldownText'; TextName = 'txtQuestCooldownText'; TextText = [string]$data.QuestCooldownText; Y = 860 },
            @{ TitleLabel = 'QuestNotInGroupTitle'; TitleName = 'txtQuestNotInGroupTitle'; TitleText = [string]$data.QuestNotInGroupTitle; TextLabel = 'QuestNotInGroupText'; TextName = 'txtQuestNotInGroupText'; TextText = [string]$data.QuestNotInGroupText; Y = 975 },
            @{ TitleLabel = 'QuestNotGroupOwnerTitle'; TitleName = 'txtQuestNotGroupOwnerTitle'; TitleText = [string]$data.QuestNotGroupOwnerTitle; TextLabel = 'QuestNotGroupOwnerText'; TextName = 'txtQuestNotGroupOwnerText'; TextText = [string]$data.QuestNotGroupOwnerText; Y = 1090 },
            @{ TitleLabel = 'AchievementCompletedTitle'; TitleName = 'txtAchievementCompletedTitle'; TitleText = [string]$data.AchievementCompletedTitle; TextLabel = 'AchievementCompletedText'; TextName = 'txtAchievementCompletedText'; TextText = [string]$data.AchievementCompletedText; Y = 1205 }
        )

        $textBoxes = @{}
        foreach ($cfg in $messageConfigs) {
            $lblTitleField = New-Object System.Windows.Forms.Label
            $lblTitleField.Text = $cfg.TitleLabel
            $lblTitleField.Location = New-Object System.Drawing.Point(12, $cfg.Y)
            $lblTitleField.Size = New-Object System.Drawing.Size(240, 18)
            $lblTitleField.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lblTitleField)

            $txtTitleField = New-Object System.Windows.Forms.TextBox
            $txtTitleField.Location = New-Object System.Drawing.Point(12, ($cfg.Y + 20))
            $txtTitleField.Size = New-Object System.Drawing.Size(360, 26)
            $txtTitleField.Text = $cfg.TitleText
            $txtTitleField.BackColor = $global:UGSM_ColorInputBackground
            $txtTitleField.ForeColor = $global:UGSM_ColorText
            $txtTitleField.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($txtTitleField)
            $textBoxes[$cfg.TitleName] = $txtTitleField

            $lblTextField = New-Object System.Windows.Forms.Label
            $lblTextField.Text = $cfg.TextLabel
            $lblTextField.Location = New-Object System.Drawing.Point(400, $cfg.Y)
            $lblTextField.Size = New-Object System.Drawing.Size(260, 18)
            $lblTextField.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lblTextField)

            $txtTextField = New-Object System.Windows.Forms.TextBox
            $txtTextField.Location = New-Object System.Drawing.Point(400, ($cfg.Y + 20))
            $txtTextField.Size = New-Object System.Drawing.Size(940, 70)
            $txtTextField.Multiline = $true
            $txtTextField.ScrollBars = 'Vertical'
            $txtTextField.Text = $cfg.TextText
            $txtTextField.BackColor = $global:UGSM_ColorInputBackground
            $txtTextField.ForeColor = $global:UGSM_ColorText
            $txtTextField.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($txtTextField)
            $textBoxes[$cfg.TextName] = $txtTextField
        }

        $lblWeeklyResetDay = New-Object System.Windows.Forms.Label
        $lblWeeklyResetDay.Text = 'WeeklyResetDay'
        $lblWeeklyResetDay.Location = New-Object System.Drawing.Point(12, 1340)
        $lblWeeklyResetDay.Size = New-Object System.Drawing.Size(130, 18)
        $lblWeeklyResetDay.ForeColor = $global:UGSM_ColorText
        [void]$panel.Controls.Add($lblWeeklyResetDay)

        $cmbWeeklyResetDay = New-Object System.Windows.Forms.ComboBox
        $cmbWeeklyResetDay.Location = New-Object System.Drawing.Point(12, 1360)
        $cmbWeeklyResetDay.Size = New-Object System.Drawing.Size(160, 26)
        $cmbWeeklyResetDay.DropDownStyle = 'DropDownList'
        foreach ($item in @('Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday')) { [void]$cmbWeeklyResetDay.Items.Add($item) }
        $dayIndex = $cmbWeeklyResetDay.Items.IndexOf([string]$data.WeeklyResetDay)
        if ($dayIndex -ge 0) { $cmbWeeklyResetDay.SelectedIndex = $dayIndex } else { $cmbWeeklyResetDay.SelectedIndex = 3 }
        [void]$panel.Controls.Add($cmbWeeklyResetDay)

        $numericResetConfigs = @(
            @{ Label = 'WeeklyResetHour'; Name = 'txtWeeklyResetHour'; X = 190; Y = 1360; W = 100; Text = [string]$data.WeeklyResetHour },
            @{ Label = 'WeeklyResetMinute'; Name = 'txtWeeklyResetMinute'; X = 310; Y = 1360; W = 100; Text = [string]$data.WeeklyResetMinute },
            @{ Label = 'DailyResetHour'; Name = 'txtDailyResetHour'; X = 430; Y = 1360; W = 100; Text = [string]$data.DailyResetHour },
            @{ Label = 'DailyResetMinute'; Name = 'txtDailyResetMinute'; X = 550; Y = 1360; W = 100; Text = [string]$data.DailyResetMinute }
        )

        foreach ($cfg in $numericResetConfigs) {
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $cfg.Label
            $lbl.Location = New-Object System.Drawing.Point($cfg.X, 1340)
            $lbl.Size = New-Object System.Drawing.Size(($cfg.W + 20), 18)
            $lbl.ForeColor = $global:UGSM_ColorText
            [void]$panel.Controls.Add($lbl)

            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $tb.Size = New-Object System.Drawing.Size($cfg.W, 26)
            $tb.Text = $cfg.Text
            $tb.BackColor = $global:UGSM_ColorInputBackground
            $tb.ForeColor = $global:UGSM_ColorText
            $tb.BorderStyle = 'FixedSingle'
            [void]$panel.Controls.Add($tb)
            $textBoxes[$cfg.Name] = $tb
        }

        $lblHelp = New-Object System.Windows.Forms.Label
        $lblHelp.Text = 'Reset hours use 0-23, minutes use 0-59. MaxActiveQuests can be -1 for unlimited.'
        $lblHelp.Location = New-Object System.Drawing.Point(12, 1410)
        $lblHelp.Size = New-Object System.Drawing.Size(760, 18)
        $lblHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$panel.Controls.Add($lblHelp)

        $btnApplyAll = New-Object System.Windows.Forms.Button
        $btnApplyAll.Text = 'Apply Quest Settings'
        $btnApplyAll.Location = New-Object System.Drawing.Point(12, 1450)
        $btnApplyAll.Size = New-Object System.Drawing.Size(180, 32)
        $btnApplyAll.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyAll.ForeColor = $global:UGSM_ColorText
        $btnApplyAll.FlatStyle = 'Flat'
        $btnApplyAll.UseVisualStyleBackColor = $false
        [void]$panel.Controls.Add($btnApplyAll)

        $btnApplyAll.Add_Click({
                $intFields = @(
                    'txtWeeklyResetHour',
                    'txtWeeklyResetMinute',
                    'txtDailyResetHour',
                    'txtDailyResetMinute'
                )

                foreach ($field in $intFields) {
                    $v = 0
                    if (-not [int]::TryParse($textBoxes[$field].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($field + ' must be a valid integer.'))
                        return
                    }
                }

                $maxActive = 0
                if (-not [int]::TryParse($txtMaxActiveQuests.Text, [ref]$maxActive)) {
                    [System.Windows.Forms.MessageBox]::Show('MaxActiveQuests must be a valid integer.')
                    return
                }

                $weeklyHour = [int]$textBoxes['txtWeeklyResetHour'].Text
                $weeklyMinute = [int]$textBoxes['txtWeeklyResetMinute'].Text
                $dailyHour = [int]$textBoxes['txtDailyResetHour'].Text
                $dailyMinute = [int]$textBoxes['txtDailyResetMinute'].Text

                if ($weeklyHour -lt 0 -or $weeklyHour -gt 23 -or $dailyHour -lt 0 -or $dailyHour -gt 23) {
                    [System.Windows.Forms.MessageBox]::Show('Reset hours must be between 0 and 23.')
                    return
                }

                if ($weeklyMinute -lt 0 -or $weeklyMinute -gt 59 -or $dailyMinute -lt 0 -or $dailyMinute -gt 59) {
                    [System.Windows.Forms.MessageBox]::Show('Reset minutes must be between 0 and 59.')
                    return
                }

                $data.EnableQuests = $(if ($checkBoxes['chkEnableQuests'].Checked) { 1 } else { 0 })
                $data.EnableQuestLogTab = $(if ($checkBoxes['chkEnableQuestLogTab'].Checked) { 1 } else { 0 })
                $data.CreateQuestNPCMarkers = $(if ($checkBoxes['chkCreateQuestNPCMarkers'].Checked) { 1 } else { 0 })
                $data.UseUTCTime = $(if ($checkBoxes['chkUseUTCTime'].Checked) { 1 } else { 0 })
                $data.UseQuestNPCIndicators = $(if ($checkBoxes['chkUseQuestNPCIndicators'].Checked) { 1 } else { 0 })

                $data.GroupQuestMode = $cmbGroupQuestMode.SelectedIndex
                $data.MaxActiveQuests = $maxActive

                $data.QuestAcceptedTitle = $textBoxes['txtQuestAcceptedTitle'].Text.Trim()
                $data.QuestAcceptedText = $textBoxes['txtQuestAcceptedText'].Text
                $data.QuestCompletedTitle = $textBoxes['txtQuestCompletedTitle'].Text.Trim()
                $data.QuestCompletedText = $textBoxes['txtQuestCompletedText'].Text
                $data.QuestFailedTitle = $textBoxes['txtQuestFailedTitle'].Text.Trim()
                $data.QuestFailedText = $textBoxes['txtQuestFailedText'].Text
                $data.QuestCanceledTitle = $textBoxes['txtQuestCanceledTitle'].Text.Trim()
                $data.QuestCanceledText = $textBoxes['txtQuestCanceledText'].Text
                $data.QuestTurnInTitle = $textBoxes['txtQuestTurnInTitle'].Text.Trim()
                $data.QuestTurnInText = $textBoxes['txtQuestTurnInText'].Text
                $data.QuestObjectiveCompletedTitle = $textBoxes['txtQuestObjectiveCompletedTitle'].Text.Trim()
                $data.QuestObjectiveCompletedText = $textBoxes['txtQuestObjectiveCompletedText'].Text
                $data.QuestCooldownTitle = $textBoxes['txtQuestCooldownTitle'].Text.Trim()
                $data.QuestCooldownText = $textBoxes['txtQuestCooldownText'].Text
                $data.QuestNotInGroupTitle = $textBoxes['txtQuestNotInGroupTitle'].Text.Trim()
                $data.QuestNotInGroupText = $textBoxes['txtQuestNotInGroupText'].Text
                $data.QuestNotGroupOwnerTitle = $textBoxes['txtQuestNotGroupOwnerTitle'].Text.Trim()
                $data.QuestNotGroupOwnerText = $textBoxes['txtQuestNotGroupOwnerText'].Text
                $data.AchievementCompletedTitle = $textBoxes['txtAchievementCompletedTitle'].Text.Trim()
                $data.AchievementCompletedText = $textBoxes['txtAchievementCompletedText'].Text

                $data.WeeklyResetDay = [string]$cmbWeeklyResetDay.SelectedItem
                $data.WeeklyResetHour = $weeklyHour
                $data.WeeklyResetMinute = $weeklyMinute
                $data.DailyResetHour = $dailyHour
                $data.DailyResetMinute = $dailyMinute

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Quest settings.' }
            }.GetNewClosure())

        $saveQuestSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Quest settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved Quest settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Quest settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveQuestSettings
            $SettingsState.FileHandler = 'QuestSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        if ($StatusLabel) { $StatusLabel.Text = 'Quest editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Quest editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'Quest editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_SocialMediaSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'SocialMediaSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load SocialMedia settings data.'
        }

        if (-not $data.PSObject.Properties['m_Version']) {
            $data | Add-Member -NotePropertyName m_Version -NotePropertyValue 2 -Force
        }
        if (-not $data.PSObject.Properties['NewsFeedTexts']) {
            $data | Add-Member -NotePropertyName NewsFeedTexts -NotePropertyValue @() -Force
        }
        if (-not $data.PSObject.Properties['NewsFeedLinks']) {
            $data | Add-Member -NotePropertyName NewsFeedLinks -NotePropertyValue @() -Force
        }

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 780)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $panel = New-Object System.Windows.Forms.Panel
