        $lblNewsText = New-Object System.Windows.Forms.Label
        $lblNewsText.Text = 'm_Text'
        $lblNewsText.Location = New-Object System.Drawing.Point(280, 105)
        $lblNewsText.Size = New-Object System.Drawing.Size(100, 18)
        $lblNewsText.ForeColor = $global:UGSM_ColorText
        [void]$textPanel.Controls.Add($lblNewsText)

        $txtNewsText = New-Object System.Windows.Forms.TextBox
        $txtNewsText.Location = New-Object System.Drawing.Point(280, 125)
        $txtNewsText.Size = New-Object System.Drawing.Size(470, 220)
        $txtNewsText.Multiline = $true
        $txtNewsText.ScrollBars = 'Vertical'
        $txtNewsText.BackColor = $global:UGSM_ColorInputBackground
        $txtNewsText.ForeColor = $global:UGSM_ColorText
        $txtNewsText.BorderStyle = 'FixedSingle'
        [void]$textPanel.Controls.Add($txtNewsText)

        $btnApplyText = New-Object System.Windows.Forms.Button
        $btnApplyText.Text = 'Apply Text'
        $btnApplyText.Location = New-Object System.Drawing.Point(280, 360)
        $btnApplyText.Size = New-Object System.Drawing.Size(120, 30)
        $btnApplyText.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyText.ForeColor = $global:UGSM_ColorText
        $btnApplyText.FlatStyle = 'Flat'
        $btnApplyText.UseVisualStyleBackColor = $false
        [void]$textPanel.Controls.Add($btnApplyText)

        $linkPanel = New-Object System.Windows.Forms.Panel
        $linkPanel.Location = New-Object System.Drawing.Point(800, 140)
        $linkPanel.Size = New-Object System.Drawing.Size(790, 560)
        $linkPanel.BackColor = $global:UGSM_ColorPanelBackground
        [void]$panel.Controls.Add($linkPanel)

        $lblLinksTitle = New-Object System.Windows.Forms.Label
        $lblLinksTitle.Text = 'NewsFeedLinks'
        $lblLinksTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblLinksTitle.Size = New-Object System.Drawing.Size(160, 22)
        $lblLinksTitle.ForeColor = $global:UGSM_ColorText
        $lblLinksTitle.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        [void]$linkPanel.Controls.Add($lblLinksTitle)

        $lstLinks = New-Object System.Windows.Forms.ListBox
        $lstLinks.Location = New-Object System.Drawing.Point(12, 40)
        $lstLinks.Size = New-Object System.Drawing.Size(240, 380)
        $lstLinks.BackColor = $global:UGSM_ColorInputBackground
        $lstLinks.ForeColor = $global:UGSM_ColorText
        [void]$linkPanel.Controls.Add($lstLinks)

        $btnAddLink = New-Object System.Windows.Forms.Button
        $btnAddLink.Text = 'Add Link'
        $btnAddLink.Location = New-Object System.Drawing.Point(12, 435)
        $btnAddLink.Size = New-Object System.Drawing.Size(110, 28)
        $btnAddLink.BackColor = $UGSM_ExpansionAccentColor
        $btnAddLink.ForeColor = $global:UGSM_ColorText
        $btnAddLink.FlatStyle = 'Flat'
        $btnAddLink.UseVisualStyleBackColor = $false
        [void]$linkPanel.Controls.Add($btnAddLink)

        $btnRemoveLink = New-Object System.Windows.Forms.Button
        $btnRemoveLink.Text = 'Remove Link'
        $btnRemoveLink.Location = New-Object System.Drawing.Point(135, 435)
        $btnRemoveLink.Size = New-Object System.Drawing.Size(117, 28)
        $btnRemoveLink.BackColor = $global:UGSM_ColorDanger
        $btnRemoveLink.ForeColor = $global:UGSM_ColorText
        $btnRemoveLink.FlatStyle = 'Flat'
        $btnRemoveLink.UseVisualStyleBackColor = $false
        [void]$linkPanel.Controls.Add($btnRemoveLink)

        $lblLinkLabel = New-Object System.Windows.Forms.Label
        $lblLinkLabel.Text = 'm_Label'
        $lblLinkLabel.Location = New-Object System.Drawing.Point(280, 40)
        $lblLinkLabel.Size = New-Object System.Drawing.Size(100, 18)
        $lblLinkLabel.ForeColor = $global:UGSM_ColorText
        [void]$linkPanel.Controls.Add($lblLinkLabel)

        $txtLinkLabel = New-Object System.Windows.Forms.TextBox
        $txtLinkLabel.Location = New-Object System.Drawing.Point(280, 60)
        $txtLinkLabel.Size = New-Object System.Drawing.Size(220, 26)
        $txtLinkLabel.BackColor = $global:UGSM_ColorInputBackground
        $txtLinkLabel.ForeColor = $global:UGSM_ColorText
        $txtLinkLabel.BorderStyle = 'FixedSingle'
        [void]$linkPanel.Controls.Add($txtLinkLabel)

        $lblLinkIcon = New-Object System.Windows.Forms.Label
        $lblLinkIcon.Text = 'm_Icon'
        $lblLinkIcon.Location = New-Object System.Drawing.Point(280, 105)
        $lblLinkIcon.Size = New-Object System.Drawing.Size(100, 18)
        $lblLinkIcon.ForeColor = $global:UGSM_ColorText
        [void]$linkPanel.Controls.Add($lblLinkIcon)

        $txtLinkIcon = New-Object System.Windows.Forms.TextBox
        $txtLinkIcon.Location = New-Object System.Drawing.Point(280, 125)
        $txtLinkIcon.Size = New-Object System.Drawing.Size(470, 26)
        $txtLinkIcon.BackColor = $global:UGSM_ColorInputBackground
        $txtLinkIcon.ForeColor = $global:UGSM_ColorText
        $txtLinkIcon.BorderStyle = 'FixedSingle'
        [void]$linkPanel.Controls.Add($txtLinkIcon)

        $lblLinkUrl = New-Object System.Windows.Forms.Label
        $lblLinkUrl.Text = 'm_URL'
        $lblLinkUrl.Location = New-Object System.Drawing.Point(280, 170)
        $lblLinkUrl.Size = New-Object System.Drawing.Size(100, 18)
        $lblLinkUrl.ForeColor = $global:UGSM_ColorText
        [void]$linkPanel.Controls.Add($lblLinkUrl)

        $txtLinkUrl = New-Object System.Windows.Forms.TextBox
        $txtLinkUrl.Location = New-Object System.Drawing.Point(280, 190)
        $txtLinkUrl.Size = New-Object System.Drawing.Size(470, 26)
        $txtLinkUrl.BackColor = $global:UGSM_ColorInputBackground
        $txtLinkUrl.ForeColor = $global:UGSM_ColorText
        $txtLinkUrl.BorderStyle = 'FixedSingle'
        [void]$linkPanel.Controls.Add($txtLinkUrl)

        $btnApplyLink = New-Object System.Windows.Forms.Button
        $btnApplyLink.Text = 'Apply Link'
        $btnApplyLink.Location = New-Object System.Drawing.Point(280, 240)
        $btnApplyLink.Size = New-Object System.Drawing.Size(120, 30)
        $btnApplyLink.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyLink.ForeColor = $global:UGSM_ColorText
        $btnApplyLink.FlatStyle = 'Flat'
        $btnApplyLink.UseVisualStyleBackColor = $false
        [void]$linkPanel.Controls.Add($btnApplyLink)

        $refreshTexts = {
            $lstTexts.Items.Clear()
            foreach ($item in @($data.NewsFeedTexts)) {
                [void]$lstTexts.Items.Add([string]$item.m_Title)
            }

            if ($lstTexts.Items.Count -gt 0) {
                if ($socialSelectedTextIndex -lt 0 -or $socialSelectedTextIndex -ge $lstTexts.Items.Count) {
                    $socialSelectedTextIndex = 0
                }
                $lstTexts.SelectedIndex = $socialSelectedTextIndex
            }
            else {
                $socialSelectedTextIndex = -1
                $txtNewsTitle.Text = ''
                $txtNewsText.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedText = {
            $items = @($data.NewsFeedTexts)
            $idx = $lstTexts.SelectedIndex

            if ($idx -lt 0 -or $idx -ge $items.Count) {
                $socialSelectedTextIndex = -1
                $txtNewsTitle.Text = ''
                $txtNewsText.Text = ''
                return
            }

            $socialSelectedTextIndex = $idx
            $txtNewsTitle.Text = [string]$items[$idx].m_Title
            $txtNewsText.Text = [string]$items[$idx].m_Text
        }.GetNewClosure()

        $refreshLinks = {
            $lstLinks.Items.Clear()
            foreach ($item in @($data.NewsFeedLinks)) {
                [void]$lstLinks.Items.Add([string]$item.m_Label)
            }

            if ($lstLinks.Items.Count -gt 0) {
                if ($socialSelectedLinkIndex -lt 0 -or $socialSelectedLinkIndex -ge $lstLinks.Items.Count) {
                    $socialSelectedLinkIndex = 0
                }
                $lstLinks.SelectedIndex = $socialSelectedLinkIndex
            }
            else {
                $socialSelectedLinkIndex = -1
                $txtLinkLabel.Text = ''
                $txtLinkIcon.Text = ''
                $txtLinkUrl.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedLink = {
            $items = @($data.NewsFeedLinks)
            $idx = $lstLinks.SelectedIndex

            if ($idx -lt 0 -or $idx -ge $items.Count) {
                $socialSelectedLinkIndex = -1
                $txtLinkLabel.Text = ''
                $txtLinkIcon.Text = ''
                $txtLinkUrl.Text = ''
                return
            }

            $socialSelectedLinkIndex = $idx
            $txtLinkLabel.Text = [string]$items[$idx].m_Label
            $txtLinkIcon.Text = [string]$items[$idx].m_Icon
            $txtLinkUrl.Text = [string]$items[$idx].m_URL
        }.GetNewClosure()

        $lstTexts.Add_SelectedIndexChanged({
                & $loadSelectedText
            }.GetNewClosure())

        $lstLinks.Add_SelectedIndexChanged({
                & $loadSelectedLink
            }.GetNewClosure())

        $btnAddText.Add_Click({
                $items = @($data.NewsFeedTexts)
                $items += [pscustomobject][ordered]@{
                    m_Title = 'New Title'
                    m_Text  = 'New text'
                }
                $data.NewsFeedTexts = [object[]]@($items)
                if ($SettingsState) { $SettingsState.Data = $data }

                $socialSelectedTextIndex = $items.Count - 1
                & $refreshTexts
                & $loadSelectedText
            }.GetNewClosure())

        $btnRemoveText.Add_Click({
                $items = @($data.NewsFeedTexts)
                $idx = $lstTexts.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $items.Count) { return }

                $newItems = @()
                for ($i = 0; $i -lt $items.Count; $i++) {
                    if ($i -ne $idx) { $newItems += $items[$i] }
                }

                $data.NewsFeedTexts = [object[]]@($newItems)
                if ($SettingsState) { $SettingsState.Data = $data }

                if ($newItems.Count -eq 0) {
                    $socialSelectedTextIndex = -1
                }
                elseif ($idx -ge $newItems.Count) {
                    $socialSelectedTextIndex = $newItems.Count - 1
                }
                else {
                    $socialSelectedTextIndex = $idx
                }

                & $refreshTexts
                & $loadSelectedText
            }.GetNewClosure())

        $btnApplyText.Add_Click({
                $idx = $lstTexts.SelectedIndex
                $items = @($data.NewsFeedTexts)
                if ($idx -lt 0 -or $idx -ge $items.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a news text entry first.')
                    return
                }

                $items[$idx] = [pscustomobject][ordered]@{
                    m_Title = $txtNewsTitle.Text.Trim()
                    m_Text  = $txtNewsText.Text
                }

                $data.NewsFeedTexts = [object[]]@($items)
                if ($SettingsState) { $SettingsState.Data = $data }

                $socialSelectedTextIndex = $idx
                & $refreshTexts
                if ($idx -ge 0 -and $idx -lt $lstTexts.Items.Count) {
                    $lstTexts.SelectedIndex = $idx
                }
            }.GetNewClosure())

        $btnAddLink.Add_Click({
                $items = @($data.NewsFeedLinks)
                $items += [pscustomobject][ordered]@{
                    m_Label = 'New Link'
                    m_Icon  = ''
                    m_URL   = ''
                }
                $data.NewsFeedLinks = [object[]]@($items)
                if ($SettingsState) { $SettingsState.Data = $data }

                $socialSelectedLinkIndex = $items.Count - 1
                & $refreshLinks
                & $loadSelectedLink
            }.GetNewClosure())

        $btnRemoveLink.Add_Click({
                $items = @($data.NewsFeedLinks)
                $idx = $lstLinks.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $items.Count) { return }

                $newItems = @()
                for ($i = 0; $i -lt $items.Count; $i++) {
                    if ($i -ne $idx) { $newItems += $items[$i] }
                }

                $data.NewsFeedLinks = [object[]]@($newItems)
                if ($SettingsState) { $SettingsState.Data = $data }

                if ($newItems.Count -eq 0) {
                    $socialSelectedLinkIndex = -1
                }
                elseif ($idx -ge $newItems.Count) {
                    $socialSelectedLinkIndex = $newItems.Count - 1
                }
                else {
                    $socialSelectedLinkIndex = $idx
                }

                & $refreshLinks
                & $loadSelectedLink
            }.GetNewClosure())

        $btnApplyLink.Add_Click({
                $idx = $lstLinks.SelectedIndex
                $items = @($data.NewsFeedLinks)
                if ($idx -lt 0 -or $idx -ge $items.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a news link entry first.')
                    return
                }

                $items[$idx] = [pscustomobject][ordered]@{
                    m_Label = $txtLinkLabel.Text.Trim()
                    m_Icon  = $txtLinkIcon.Text.Trim()
                    m_URL   = $txtLinkUrl.Text.Trim()
                }

                $data.NewsFeedLinks = [object[]]@($items)
                if ($SettingsState) { $SettingsState.Data = $data }

                $socialSelectedLinkIndex = $idx
                & $refreshLinks
                if ($idx -ge 0 -and $idx -lt $lstLinks.Items.Count) {
                    $lstLinks.SelectedIndex = $idx
                }
            }.GetNewClosure())

        $saveSocialMediaSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No SocialMedia settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved SocialMedia settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving SocialMedia settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveSocialMediaSettings
            $SettingsState.FileHandler = 'SocialMediaSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshTexts
        & $loadSelectedText
        & $refreshLinks
        & $loadSelectedLink

        if ($StatusLabel) { $StatusLabel.Text = 'SocialMedia editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'SocialMedia editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'SocialMedia editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_VehicleSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'VehicleSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop
            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Vehicle settings data.'
        }

        $defaults = [ordered]@{
            m_Version                                     = 23
            VehicleSync                                   = 0
            VehicleRequireKeyToStart                      = 1
            VehicleRequireAllDoors                        = 1
            VehicleLockedAllowInventoryAccess             = 0
            VehicleLockedAllowInventoryAccessWithoutDoors = 1
            MasterKeyPairingMode                          = 2
            MasterKeyUses                                 = 2
            CanPickLock                                   = 0
            PickLockTools                                 = @('Lockpick')
            PickLockChancePercent                         = 40.0
            PickLockTimeSeconds                           = 120
            PickLockToolDamagePercent                     = 10.0
            EnableWindAerodynamics                        = 0
            EnableMainRotorDamage                         = 1
            EnableTailRotorDamage                         = 1
            Towing                                        = 1
            EnableHelicopterExplosions                    = 1
            DisableVehicleDamage                          = 0
            VehicleCrewDamageMultiplier                   = 1.0
            VehicleSpeedDamageMultiplier                  = 1.0
            VehicleRoadKillDamageMultiplier               = 1.0
            CollisionDamageIfEngineOff                    = 0
            CollisionDamageMinSpeedKmh                    = 30.0
            CanChangeLock                                 = 0
            ChangeLockTools                               = @('Screwdriver')
            ChangeLockTimeSeconds                         = 120
            ChangeLockToolDamagePercent                   = 10.0
            PlacePlayerOnGroundOnReconnectInVehicle       = 2
            RevvingOverMaxRPMRuinsEngineInstantly         = 0
            VehicleDropsRuinedDoors                       = 1
            ExplodingVehicleDropsAttachments              = 1
            DesyncInvulnerabilityTimeoutSeconds           = 3.0
