        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

