                $cn = [string]$entry.ClassName
                if (-not [string]::IsNullOrWhiteSpace($cn) -and -not $vehicleClassNameChoices.Contains($cn)) {
                    $vehicleClassNameChoices.Add($cn)
                }
            }
        }

