        $lblLockComplexity = New-Object System.Windows.Forms.Label
        $lblLockComplexity.Text = 'LockComplexity'
        $lblLockComplexity.Location = New-Object System.Drawing.Point(390, 220)
        $lblLockComplexity.Size = New-Object System.Drawing.Size(120, 18)
        $lblLockComplexity.ForeColor = $global:UGSM_ColorText
        [void]$configPanel.Controls.Add($lblLockComplexity)

        $txtVehicleLockComplexity = New-Object System.Windows.Forms.TextBox
        $txtVehicleLockComplexity.Location = New-Object System.Drawing.Point(390, 240)
        $txtVehicleLockComplexity.Size = New-Object System.Drawing.Size(140, 26)
        $txtVehicleLockComplexity.BackColor = $global:UGSM_ColorInputBackground
        $txtVehicleLockComplexity.ForeColor = $global:UGSM_ColorText
        $txtVehicleLockComplexity.BorderStyle = 'FixedSingle'
        [void]$configPanel.Controls.Add($txtVehicleLockComplexity)

        $btnApplyVehicleConfig = New-Object System.Windows.Forms.Button
        $btnApplyVehicleConfig.Text = 'Apply Vehicle Entry'
        $btnApplyVehicleConfig.Location = New-Object System.Drawing.Point(390, 300)
        $btnApplyVehicleConfig.Size = New-Object System.Drawing.Size(160, 32)
        $btnApplyVehicleConfig.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyVehicleConfig.ForeColor = $global:UGSM_ColorText
        $btnApplyVehicleConfig.FlatStyle = 'Flat'
        $btnApplyVehicleConfig.UseVisualStyleBackColor = $false
        [void]$configPanel.Controls.Add($btnApplyVehicleConfig)

        $cmbVehicleClassName.Add_SelectedIndexChanged({
                if (-not [string]::IsNullOrWhiteSpace([string]$cmbVehicleClassName.Text)) {
                    $txtVehicleClassName.Text = [string]$cmbVehicleClassName.Text
                }
            }.GetNewClosure())

        $refreshVehiclesConfig = {
            $lstVehiclesConfig.Items.Clear()
            foreach ($entry in @($data.VehiclesConfig)) {
                $line = ([string]$entry.ClassName + ' | LockComplexity=' + [string]$entry.LockComplexity)
                [void]$lstVehiclesConfig.Items.Add($line)
            }

            if ($lstVehiclesConfig.Items.Count -gt 0) {
                if ($vehicleSettingsSelectedConfigIndex -lt 0 -or $vehicleSettingsSelectedConfigIndex -ge $lstVehiclesConfig.Items.Count) {
                    $vehicleSettingsSelectedConfigIndex = 0
                }
                $lstVehiclesConfig.SelectedIndex = $vehicleSettingsSelectedConfigIndex
            }
            else {
                $vehicleSettingsSelectedConfigIndex = -1
                $txtVehicleClassName.Text = ''
                $txtVehicleLockComplexity.Text = ''
                $cmbVehicleClassName.Text = ''
            }
        }.GetNewClosure()

        $loadSelectedVehicleConfig = {
            $entries = @($data.VehiclesConfig)
            $idx = $lstVehiclesConfig.SelectedIndex

            if ($idx -lt 0 -or $idx -ge $entries.Count) {
                $vehicleSettingsSelectedConfigIndex = -1
                $txtVehicleClassName.Text = ''
                $txtVehicleLockComplexity.Text = ''
                $cmbVehicleClassName.Text = ''
                return
            }

            $vehicleSettingsSelectedConfigIndex = $idx
            $txtVehicleClassName.Text = [string]$entries[$idx].ClassName
            $txtVehicleLockComplexity.Text = [string]$entries[$idx].LockComplexity
            $cmbVehicleClassName.Text = [string]$entries[$idx].ClassName
        }.GetNewClosure()

        $lstVehiclesConfig.Add_SelectedIndexChanged({
                & $loadSelectedVehicleConfig
            }.GetNewClosure())

        $btnAddVehicleConfig.Add_Click({
                $entries = @($data.VehiclesConfig)
                $entries += [pscustomobject][ordered]@{
                    ClassName      = 'NewVehicleClassName'
                    LockComplexity = 1.0
                }
                $data.VehiclesConfig = [object[]]@($entries)

                if (-not $vehicleClassNameChoices.Contains('NewVehicleClassName')) {
                    $vehicleClassNameChoices.Add('NewVehicleClassName')
                    [void]$cmbVehicleClassName.Items.Add('NewVehicleClassName')
                }

                if ($SettingsState) { $SettingsState.Data = $data }

                $vehicleSettingsSelectedConfigIndex = $entries.Count - 1
                & $refreshVehiclesConfig
                & $loadSelectedVehicleConfig
            }.GetNewClosure())

        $btnRemoveVehicleConfig.Add_Click({
                $entries = @($data.VehiclesConfig)
                $idx = $lstVehiclesConfig.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $entries.Count) { return }

                $newEntries = @()
                for ($i = 0; $i -lt $entries.Count; $i++) {
                    if ($i -ne $idx) { $newEntries += $entries[$i] }
                }

                $data.VehiclesConfig = [object[]]@($newEntries)
                if ($SettingsState) { $SettingsState.Data = $data }

                if ($newEntries.Count -eq 0) {
                    $vehicleSettingsSelectedConfigIndex = -1
                }
                elseif ($idx -ge $newEntries.Count) {
                    $vehicleSettingsSelectedConfigIndex = $newEntries.Count - 1
                }
                else {
                    $vehicleSettingsSelectedConfigIndex = $idx
                }

                & $refreshVehiclesConfig
                & $loadSelectedVehicleConfig
            }.GetNewClosure())

        $btnApplyVehicleConfig.Add_Click({
                $entries = @($data.VehiclesConfig)
                $idx = $lstVehiclesConfig.SelectedIndex
                if ($idx -lt 0 -or $idx -ge $entries.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a vehicle entry first.')
                    return
                }

                $className = $txtVehicleClassName.Text.Trim()
                if ([string]::IsNullOrWhiteSpace($className)) {
                    [System.Windows.Forms.MessageBox]::Show('ClassName cannot be blank.')
                    return
                }

                $lockComplexity = 0.0
                if (-not [double]::TryParse($txtVehicleLockComplexity.Text, [ref]$lockComplexity)) {
                    [System.Windows.Forms.MessageBox]::Show('LockComplexity must be a valid number.')
                    return
                }

                $entries[$idx] = [pscustomobject][ordered]@{
                    ClassName      = $className
                    LockComplexity = $lockComplexity
                }

                $data.VehiclesConfig = [object[]]@($entries)

                if (-not $vehicleClassNameChoices.Contains($className)) {
                    $vehicleClassNameChoices.Add($className)
                    [void]$cmbVehicleClassName.Items.Add($className)
                }

                if ($SettingsState) { $SettingsState.Data = $data }

                $vehicleSettingsSelectedConfigIndex = $idx
                & $refreshVehiclesConfig
                if ($idx -ge 0 -and $idx -lt $lstVehiclesConfig.Items.Count) {
                    $lstVehiclesConfig.SelectedIndex = $idx
                }
            }.GetNewClosure())

        $btnApplyTop.Add_Click({
                $intKeys = @(
                    'txtMasterKeyUses',
                    'txtPickLockTimeSeconds',
                    'txtChangeLockTimeSeconds'
                )
                $doubleKeys = @(
                    'txtPickLockChancePercent',
                    'txtPickLockToolDamagePercent',
                    'txtVehicleCrewDamageMultiplier',
                    'txtVehicleSpeedDamageMultiplier',
                    'txtVehicleRoadKillDamageMultiplier',
                    'txtCollisionDamageMinSpeedKmh',
                    'txtChangeLockToolDamagePercent',
                    'txtDesyncInvulnerabilityTimeoutSeconds',
                    'txtPilotlessAutoHoverEngineStopDelaySeconds',
                    'txtRoughLandingVerticalSpeedThreshold',
                    'txtDamagedEngineStartupChancePercent',
                    'txtFuelConsumptionPercent',
                    'txtVehicleAutoCoverTimeSeconds'
                )

                foreach ($key in $intKeys) {
                    $v = 0
                    if (-not [int]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid integer.'))
                        return
                    }
                }

                foreach ($key in $doubleKeys) {
                    $v = 0.0
                    if (-not [double]::TryParse($numericTextBoxes[$key].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($key + ' must be a valid number.'))
                        return
                    }
                }

                $data.VehicleSync = $(if ($checkBoxes['chkVehicleSync'].Checked) { 1 } else { 0 })
                $data.VehicleRequireKeyToStart = $cmbVehicleRequireKeyToStart.SelectedIndex
                $data.VehicleRequireAllDoors = $(if ($checkBoxes['chkVehicleRequireAllDoors'].Checked) { 1 } else { 0 })
                $data.VehicleLockedAllowInventoryAccess = $(if ($checkBoxes['chkVehicleLockedAllowInventoryAccess'].Checked) { 1 } else { 0 })
                $data.VehicleLockedAllowInventoryAccessWithoutDoors = $(if ($checkBoxes['chkVehicleLockedAllowInventoryAccessWithoutDoors'].Checked) { 1 } else { 0 })

                $data.MasterKeyPairingMode = $masterKeyModeValues[$cmbMasterKeyPairingMode.SelectedIndex]
                $data.MasterKeyUses = [int]$numericTextBoxes['txtMasterKeyUses'].Text

                $data.CanPickLock = $(if ($checkBoxes['chkCanPickLock'].Checked) { 1 } else { 0 })
                $data.PickLockTools = [object[]]@(& $parseLinesToArray $txtPickLockTools.Text)
                $data.PickLockChancePercent = [double]$numericTextBoxes['txtPickLockChancePercent'].Text
                $data.PickLockTimeSeconds = [int]$numericTextBoxes['txtPickLockTimeSeconds'].Text
                $data.PickLockToolDamagePercent = [double]$numericTextBoxes['txtPickLockToolDamagePercent'].Text

                $data.EnableWindAerodynamics = $(if ($checkBoxes['chkEnableWindAerodynamics'].Checked) { 1 } else { 0 })
                $data.EnableMainRotorDamage = $(if ($checkBoxes['chkEnableMainRotorDamage'].Checked) { 1 } else { 0 })
                $data.EnableTailRotorDamage = $(if ($checkBoxes['chkEnableTailRotorDamage'].Checked) { 1 } else { 0 })
                $data.Towing = $(if ($checkBoxes['chkTowing'].Checked) { 1 } else { 0 })
                $data.EnableHelicopterExplosions = $(if ($checkBoxes['chkEnableHelicopterExplosions'].Checked) { 1 } else { 0 })
                $data.DisableVehicleDamage = $(if ($checkBoxes['chkDisableVehicleDamage'].Checked) { 1 } else { 0 })
                $data.VehicleCrewDamageMultiplier = [double]$numericTextBoxes['txtVehicleCrewDamageMultiplier'].Text
                $data.VehicleSpeedDamageMultiplier = [double]$numericTextBoxes['txtVehicleSpeedDamageMultiplier'].Text
                $data.VehicleRoadKillDamageMultiplier = [double]$numericTextBoxes['txtVehicleRoadKillDamageMultiplier'].Text
                $data.CollisionDamageIfEngineOff = $(if ($checkBoxes['chkCollisionDamageIfEngineOff'].Checked) { 1 } else { 0 })
                $data.CollisionDamageMinSpeedKmh = [double]$numericTextBoxes['txtCollisionDamageMinSpeedKmh'].Text

                $data.CanChangeLock = $(if ($checkBoxes['chkCanChangeLock'].Checked) { 1 } else { 0 })
                $data.ChangeLockTools = [object[]]@(& $parseLinesToArray $txtChangeLockTools.Text)
                $data.ChangeLockTimeSeconds = [int]$numericTextBoxes['txtChangeLockTimeSeconds'].Text
                $data.ChangeLockToolDamagePercent = [double]$numericTextBoxes['txtChangeLockToolDamagePercent'].Text

                $data.PlacePlayerOnGroundOnReconnectInVehicle = $cmbReconnectMode.SelectedIndex
                $data.RevvingOverMaxRPMRuinsEngineInstantly = $(if ($checkBoxes['chkRevvingOverMaxRPMRuinsEngineInstantly'].Checked) { 1 } else { 0 })
                $data.VehicleDropsRuinedDoors = $(if ($checkBoxes['chkVehicleDropsRuinedDoors'].Checked) { 1 } else { 0 })
                $data.ExplodingVehicleDropsAttachments = $(if ($checkBoxes['chkExplodingVehicleDropsAttachments'].Checked) { 1 } else { 0 })

                $data.DesyncInvulnerabilityTimeoutSeconds = [double]$numericTextBoxes['txtDesyncInvulnerabilityTimeoutSeconds'].Text
                $data.PilotlessAutoHoverEngineStopDelaySeconds = [double]$numericTextBoxes['txtPilotlessAutoHoverEngineStopDelaySeconds'].Text
                $data.RoughLandingVerticalSpeedThreshold = [double]$numericTextBoxes['txtRoughLandingVerticalSpeedThreshold'].Text
                $data.DamagedEngineStartupChancePercent = [double]$numericTextBoxes['txtDamagedEngineStartupChancePercent'].Text
                $data.FuelConsumptionPercent = [double]$numericTextBoxes['txtFuelConsumptionPercent'].Text

                $data.EnableVehicleCovers = $(if ($checkBoxes['chkEnableVehicleCovers'].Checked) { 1 } else { 0 })
                $data.AllowCoveringDEVehicles = $(if ($checkBoxes['chkAllowCoveringDEVehicles'].Checked) { 1 } else { 0 })
                $data.CanCoverWithCargo = $(if ($checkBoxes['chkCanCoverWithCargo'].Checked) { 1 } else { 0 })
                $data.UseVirtualStorageForCoverCargo = $(if ($checkBoxes['chkUseVirtualStorageForCoverCargo'].Checked) { 1 } else { 0 })
                $data.VehicleAutoCoverTimeSeconds = [double]$numericTextBoxes['txtVehicleAutoCoverTimeSeconds'].Text
                $data.VehicleAutoCoverRequireCamonet = $(if ($checkBoxes['chkVehicleAutoCoverRequireCamonet'].Checked) { 1 } else { 0 })
                $data.EnableAutoCoveringDEVehicles = $(if ($checkBoxes['chkEnableAutoCoveringDEVehicles'].Checked) { 1 } else { 0 })
                $data.CFToolsHeliCoverIconName = $numericTextBoxes['txtCFToolsHeliCoverIconName'].Text.Trim()
                $data.CFToolsBoatCoverIconName = $numericTextBoxes['txtCFToolsBoatCoverIconName'].Text.Trim()
                $data.CFToolsCarCoverIconName = $numericTextBoxes['txtCFToolsCarCoverIconName'].Text.Trim()
                $data.ShowVehicleOwners = $(if ($checkBoxes['chkShowVehicleOwners'].Checked) { 1 } else { 0 })

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Vehicle settings.' }
            }.GetNewClosure())

        $saveVehicleSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Vehicle settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved Vehicle settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Vehicle settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveVehicleSettings
            $SettingsState.FileHandler = 'VehicleSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshVehiclesConfig
        & $loadSelectedVehicleConfig

        if ($StatusLabel) {
            $StatusLabel.Text = 'Vehicle editor loaded.'
        }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Vehicle editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Vehicle editor failed: ' + $_.Exception.Message
        }
    }
}

function Show-DayZExpansionSettingEditor_PersonalStorageNewSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'PersonalStorageNewSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load PersonalStorageNew settings data.'
        }

        $defaults = [ordered]@{
            m_Version       = 4
            UseCategoryMenu = 0
            ExcludedItems   = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        if (-not $data.PSObject.Properties['StorageLevels'] -or -not $data.StorageLevels) {
            $data | Add-Member -NotePropertyName StorageLevels -NotePropertyValue ([pscustomobject]@{}) -Force
        }

        for ($i = 1; $i -le 10; $i++) {
            $levelKey = [string]$i
            if (-not $data.StorageLevels.PSObject.Properties[$levelKey]) {
                $data.StorageLevels | Add-Member -NotePropertyName $levelKey -NotePropertyValue ([pscustomobject][ordered]@{
                        ReputationRequirement = -1
                        QuestID               = 0
                        ExcludedSlots         = @()
                        AllowAttachmentCargo  = 0
                    }) -Force
            }
            else {
                $level = $data.StorageLevels.$levelKey
                if (-not $level.PSObject.Properties['ReputationRequirement']) {
                    $level | Add-Member -NotePropertyName ReputationRequirement -NotePropertyValue -1 -Force
                }
                if (-not $level.PSObject.Properties['QuestID']) {
                    $level | Add-Member -NotePropertyName QuestID -NotePropertyValue 0 -Force
                }
                if (-not $level.PSObject.Properties['ExcludedSlots']) {
                    $level | Add-Member -NotePropertyName ExcludedSlots -NotePropertyValue @() -Force
                }
                if (-not $level.PSObject.Properties['AllowAttachmentCargo']) {
                    $level | Add-Member -NotePropertyName AllowAttachmentCargo -NotePropertyValue 0 -Force
                }
            }
        }

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $psnewSelectedLevelIndex = -1

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 980)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 250)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Personal Storage New Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(320, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$topPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Top settings, excluded items, and per-storage-level requirements'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(700, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$topPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
        $txtVersion.Size = New-Object System.Drawing.Size(70, 26)
        $txtVersion.Text = [string]$data.m_Version
        $txtVersion.ReadOnly = $true
        $txtVersion.BackColor = $global:UGSM_ColorPanelBackground
        $txtVersion.ForeColor = $global:UGSM_ColorText
        $txtVersion.BorderStyle = 'FixedSingle'
        [void]$topPanel.Controls.Add($txtVersion)

        $chkUseCategoryMenu = New-Object System.Windows.Forms.CheckBox
        $chkUseCategoryMenu.Text = 'UseCategoryMenu'
        $chkUseCategoryMenu.Location = New-Object System.Drawing.Point(110, 92)
        $chkUseCategoryMenu.Size = New-Object System.Drawing.Size(160, 22)
        $chkUseCategoryMenu.Checked = ([int]$data.UseCategoryMenu -eq 1)
        $chkUseCategoryMenu.ForeColor = $global:UGSM_ColorText
        $chkUseCategoryMenu.BackColor = [System.Drawing.Color]::Transparent
        [void]$topPanel.Controls.Add($chkUseCategoryMenu)

        $lblExcludedItems = New-Object System.Windows.Forms.Label
        $lblExcludedItems.Text = 'ExcludedItems (one per line)'
        $lblExcludedItems.Location = New-Object System.Drawing.Point(12, 140)
        $lblExcludedItems.Size = New-Object System.Drawing.Size(220, 18)
        $lblExcludedItems.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblExcludedItems)

        $txtExcludedItems = New-Object System.Windows.Forms.TextBox
        $txtExcludedItems.Location = New-Object System.Drawing.Point(12, 160)
        $txtExcludedItems.Size = New-Object System.Drawing.Size(620, 60)
        $txtExcludedItems.Multiline = $true
        $txtExcludedItems.ScrollBars = 'Vertical'
        $txtExcludedItems.BackColor = $global:UGSM_ColorInputBackground
        $txtExcludedItems.ForeColor = $global:UGSM_ColorText
        $txtExcludedItems.BorderStyle = 'FixedSingle'
        if ($data.ExcludedItems) {
            $txtExcludedItems.Text = (@($data.ExcludedItems) -join [Environment]::NewLine)
        }
        [void]$topPanel.Controls.Add($txtExcludedItems)

        $btnApplyTop = New-Object System.Windows.Forms.Button
        $btnApplyTop.Text = 'Apply Top Settings'
        $btnApplyTop.Location = New-Object System.Drawing.Point(660, 176)
        $btnApplyTop.Size = New-Object System.Drawing.Size(150, 32)
        $btnApplyTop.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyTop.ForeColor = $global:UGSM_ColorText
        $btnApplyTop.FlatStyle = 'Flat'
        $btnApplyTop.UseVisualStyleBackColor = $false
        [void]$topPanel.Controls.Add($btnApplyTop)

        $levelsPanel = New-Object System.Windows.Forms.Panel
        $levelsPanel.Location = New-Object System.Drawing.Point(0, 265)
        $levelsPanel.Size = New-Object System.Drawing.Size(1600, 650)
        $levelsPanel.BackColor = $global:UGSM_ColorPanelBackground
        $levelsPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($levelsPanel)

        $lblLevelsTitle = New-Object System.Windows.Forms.Label
        $lblLevelsTitle.Text = 'Storage Levels'
        $lblLevelsTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblLevelsTitle.Size = New-Object System.Drawing.Size(180, 24)
        $lblLevelsTitle.ForeColor = $global:UGSM_ColorText
        $lblLevelsTitle.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        [void]$levelsPanel.Controls.Add($lblLevelsTitle)

        $lblLevelsSub = New-Object System.Windows.Forms.Label
        $lblLevelsSub.Text = 'Select a level and edit its requirements, excluded slots, and attachment cargo behavior'
        $lblLevelsSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblLevelsSub.Size = New-Object System.Drawing.Size(760, 18)
        $lblLevelsSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$levelsPanel.Controls.Add($lblLevelsSub)

        $lstLevels = New-Object System.Windows.Forms.ListBox
        $lstLevels.Location = New-Object System.Drawing.Point(12, 70)
        $lstLevels.Size = New-Object System.Drawing.Size(220, 500)
        $lstLevels.BackColor = $global:UGSM_ColorInputBackground
        $lstLevels.ForeColor = $global:UGSM_ColorText
        [void]$levelsPanel.Controls.Add($lstLevels)

        $lblReputationRequirement = New-Object System.Windows.Forms.Label
        $lblReputationRequirement.Text = 'ReputationRequirement'
        $lblReputationRequirement.Location = New-Object System.Drawing.Point(270, 70)
        $lblReputationRequirement.Size = New-Object System.Drawing.Size(170, 18)
        $lblReputationRequirement.ForeColor = $global:UGSM_ColorText
        [void]$levelsPanel.Controls.Add($lblReputationRequirement)

        $txtReputationRequirement = New-Object System.Windows.Forms.TextBox
        $txtReputationRequirement.Location = New-Object System.Drawing.Point(270, 90)
        $txtReputationRequirement.Size = New-Object System.Drawing.Size(160, 26)
        $txtReputationRequirement.BackColor = $global:UGSM_ColorInputBackground
        $txtReputationRequirement.ForeColor = $global:UGSM_ColorText
        $txtReputationRequirement.BorderStyle = 'FixedSingle'
        [void]$levelsPanel.Controls.Add($txtReputationRequirement)

        $lblQuestID = New-Object System.Windows.Forms.Label
        $lblQuestID.Text = 'QuestID'
        $lblQuestID.Location = New-Object System.Drawing.Point(460, 70)
        $lblQuestID.Size = New-Object System.Drawing.Size(100, 18)
        $lblQuestID.ForeColor = $global:UGSM_ColorText
        [void]$levelsPanel.Controls.Add($lblQuestID)

        $txtQuestID = New-Object System.Windows.Forms.TextBox
        $txtQuestID.Location = New-Object System.Drawing.Point(460, 90)
        $txtQuestID.Size = New-Object System.Drawing.Size(120, 26)
        $txtQuestID.BackColor = $global:UGSM_ColorInputBackground
        $txtQuestID.ForeColor = $global:UGSM_ColorText
        $txtQuestID.BorderStyle = 'FixedSingle'
        [void]$levelsPanel.Controls.Add($txtQuestID)

        $chkAllowAttachmentCargo = New-Object System.Windows.Forms.CheckBox
        $chkAllowAttachmentCargo.Text = 'AllowAttachmentCargo'
        $chkAllowAttachmentCargo.Location = New-Object System.Drawing.Point(610, 92)
        $chkAllowAttachmentCargo.Size = New-Object System.Drawing.Size(180, 22)
        $chkAllowAttachmentCargo.ForeColor = $global:UGSM_ColorText
        $chkAllowAttachmentCargo.BackColor = [System.Drawing.Color]::Transparent
        [void]$levelsPanel.Controls.Add($chkAllowAttachmentCargo)

        $lblExcludedSlots = New-Object System.Windows.Forms.Label
        $lblExcludedSlots.Text = 'ExcludedSlots (one per line)'
        $lblExcludedSlots.Location = New-Object System.Drawing.Point(270, 145)
        $lblExcludedSlots.Size = New-Object System.Drawing.Size(220, 18)
        $lblExcludedSlots.ForeColor = $global:UGSM_ColorText
        [void]$levelsPanel.Controls.Add($lblExcludedSlots)

        $txtExcludedSlots = New-Object System.Windows.Forms.TextBox
        $txtExcludedSlots.Location = New-Object System.Drawing.Point(270, 165)
        $txtExcludedSlots.Size = New-Object System.Drawing.Size(520, 220)
        $txtExcludedSlots.Multiline = $true
        $txtExcludedSlots.ScrollBars = 'Vertical'
        $txtExcludedSlots.BackColor = $global:UGSM_ColorInputBackground
        $txtExcludedSlots.ForeColor = $global:UGSM_ColorText
        $txtExcludedSlots.BorderStyle = 'FixedSingle'
        [void]$levelsPanel.Controls.Add($txtExcludedSlots)

        $lblLevelHelp = New-Object System.Windows.Forms.Label
        $lblLevelHelp.Text = 'ReputationRequirement can be -1. QuestID can be 0. ExcludedSlots should match slot names exactly.'
        $lblLevelHelp.Location = New-Object System.Drawing.Point(270, 400)
        $lblLevelHelp.Size = New-Object System.Drawing.Size(760, 18)
        $lblLevelHelp.ForeColor = $global:UGSM_ColorMutedText
        [void]$levelsPanel.Controls.Add($lblLevelHelp)

        $btnApplyLevel = New-Object System.Windows.Forms.Button
        $btnApplyLevel.Text = 'Apply Selected Level'
        $btnApplyLevel.Location = New-Object System.Drawing.Point(270, 435)
        $btnApplyLevel.Size = New-Object System.Drawing.Size(170, 32)
        $btnApplyLevel.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyLevel.ForeColor = $global:UGSM_ColorText
        $btnApplyLevel.FlatStyle = 'Flat'
        $btnApplyLevel.UseVisualStyleBackColor = $false
        [void]$levelsPanel.Controls.Add($btnApplyLevel)

        $refreshLevels = {
            $lstLevels.Items.Clear()
            for ($i = 1; $i -le 10; $i++) {
                $levelKey = [string]$i
                $level = $data.StorageLevels.$levelKey
                $line = ('Level ' + $levelKey + ' | Rep=' + [string]$level.ReputationRequirement + ' | QuestID=' + [string]$level.QuestID)
                [void]$lstLevels.Items.Add($line)
            }

            if ($lstLevels.Items.Count -gt 0) {
                if ($psnewSelectedLevelIndex -lt 0 -or $psnewSelectedLevelIndex -ge $lstLevels.Items.Count) {
                    $psnewSelectedLevelIndex = 0
                }
                $lstLevels.SelectedIndex = $psnewSelectedLevelIndex
            }
        }.GetNewClosure()

        $loadSelectedLevel = {
            $idx = $lstLevels.SelectedIndex
            if ($idx -lt 0) {
                $psnewSelectedLevelIndex = -1
                $txtReputationRequirement.Text = ''
                $txtQuestID.Text = ''
                $txtExcludedSlots.Text = ''
                $chkAllowAttachmentCargo.Checked = $false
                return
            }

            $psnewSelectedLevelIndex = $idx
            $levelKey = [string]($idx + 1)
            $level = $data.StorageLevels.$levelKey

            $txtReputationRequirement.Text = [string]$level.ReputationRequirement
            $txtQuestID.Text = [string]$level.QuestID
            $txtExcludedSlots.Text = (@($level.ExcludedSlots) -join [Environment]::NewLine)
            $chkAllowAttachmentCargo.Checked = ([int]$level.AllowAttachmentCargo -eq 1)
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $data.UseCategoryMenu = $(if ($chkUseCategoryMenu.Checked) { 1 } else { 0 })
                $data.ExcludedItems = [object[]]@(& $parseLinesToArray $txtExcludedItems.Text)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied PersonalStorageNew top settings.' }
            }.GetNewClosure())

        $lstLevels.Add_SelectedIndexChanged({
                & $loadSelectedLevel
            }.GetNewClosure())

        $btnApplyLevel.Add_Click({
                $idx = $lstLevels.SelectedIndex
                if ($idx -lt 0) {
                    [System.Windows.Forms.MessageBox]::Show('Select a storage level first.')
                    return
                }

                $rep = 0
                if (-not [int]::TryParse($txtReputationRequirement.Text, [ref]$rep)) {
                    [System.Windows.Forms.MessageBox]::Show('ReputationRequirement must be a valid integer.')
                    return
                }

                $questId = 0
                if (-not [int]::TryParse($txtQuestID.Text, [ref]$questId)) {
                    [System.Windows.Forms.MessageBox]::Show('QuestID must be a valid integer.')
                    return
                }

                $levelKey = [string]($idx + 1)
                $level = $data.StorageLevels.$levelKey
                $level.ReputationRequirement = $rep
                $level.QuestID = $questId
                $level.ExcludedSlots = [object[]]@(& $parseLinesToArray $txtExcludedSlots.Text)
                $level.AllowAttachmentCargo = $(if ($chkAllowAttachmentCargo.Checked) { 1 } else { 0 })

                if ($SettingsState) { $SettingsState.Data = $data }

                $psnewSelectedLevelIndex = $idx
                & $refreshLevels
                if ($idx -ge 0 -and $idx -lt $lstLevels.Items.Count) {
                    $lstLevels.SelectedIndex = $idx
                }

                if ($StatusLabel) { $StatusLabel.Text = ('Applied storage level ' + $levelKey + '.') }
            }.GetNewClosure())

        $savePersonalStorageNewSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No PersonalStorageNew settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved PersonalStorageNew settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving PersonalStorageNew settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $savePersonalStorageNewSettings
            $SettingsState.FileHandler = 'PersonalStorageNewSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshLevels
        & $loadSelectedLevel

        if ($StatusLabel) { $StatusLabel.Text = 'PersonalStorageNew editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'PersonalStorageNew editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'PersonalStorageNew editor failed: ' + $_.Exception.Message }
    }
}

function Show-DayZExpansionSettingEditor_RaidSettings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$HostPanel,
        [Parameter(Mandatory)]$FilePath,
        [Parameter(Mandatory)]$SettingsState,
        [Parameter()]$StatusLabel
    )

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $HostPanel.Controls.Clear()
    $HostPanel.AutoScroll = $true

    $baseX = $UGSM_ExpansionBaseX
    $baseY = $UGSM_ExpansionBaseY
    $maxWidth = $UGSM_ExpansionMaxWidth

    
    
    
    
    
    
    

    try {
        $data = $null
        $useCachedData = $false

        if ($SettingsState) {
            $sameHandler = ($SettingsState.PSObject.Properties['FileHandler'] -and $SettingsState.FileHandler -eq 'RaidSettings')
            $samePath = ($SettingsState.PSObject.Properties['CurrentFilePath'] -and [string]::Equals([string]$SettingsState.CurrentFilePath, [string]$FilePath, [System.StringComparison]::OrdinalIgnoreCase))
            if ($SettingsState.PSObject.Properties['Data'] -and $SettingsState.Data -and $sameHandler -and $samePath) {
                $useCachedData = $true
            }
        }

        if ($useCachedData) {
            $data = $SettingsState.Data
        }
        else {
            $raw = Get-Content -LiteralPath $FilePath -Raw -ErrorAction Stop
            $data = $raw | ConvertFrom-Json -ErrorAction Stop

            if ($SettingsState) {
                $SettingsState | Add-Member -NotePropertyName Data -NotePropertyValue $data -Force
                $SettingsState | Add-Member -NotePropertyName CurrentFilePath -NotePropertyValue $FilePath -Force
            }
        }

        if (-not $data) {
            throw 'Failed to load Raid settings data.'
        }

        $defaults = [ordered]@{
            m_Version                            = 5
            BaseBuildingRaidMode                 = 0
            ExplosionTime                        = 30.0
            ExplosiveDamageWhitelist             = @()
            EnableExplosiveWhitelist             = 0
            ExplosionDamageMultiplier            = 50.0
            ProjectileDamageMultiplier           = 1.0
            CanRaidSafes                         = 1
            SafeRaidUseSchedule                  = 1
            SafeExplosionDamageMultiplier        = 17.0
            SafeProjectileDamageMultiplier       = 1.0
            SafeRaidTools                        = @()
            SafeRaidToolTimeSeconds              = 600
            SafeRaidToolCycles                   = 5
            SafeRaidToolDamagePercent            = 100.0
            CanRaidBarbedWire                    = 1
            BarbedWireRaidTools                  = @()
            BarbedWireRaidToolTimeSeconds        = 300
            BarbedWireRaidToolCycles             = 5
            BarbedWireRaidToolDamagePercent      = 100.0
            CanRaidLocksOnWalls                  = 0
            CanRaidLocksOnFences                 = 0
            CanRaidLocksOnTents                  = 0
            LockRaidTools                        = @()
            LockOnWallRaidToolTimeSeconds        = 900
            LockOnFenceRaidToolTimeSeconds       = 900
            LockOnTentRaidToolTimeSeconds        = 600
            LockRaidToolCycles                   = 5
            LockRaidToolDamagePercent            = 100.0
            CanRaidLocksOnContainers             = 1
            LockOnContainerRaidUseSchedule       = 1
            LockOnContainerRaidTools             = @()
            LockOnContainerRaidToolTimeSeconds   = 600
            LockOnContainerRaidToolCycles        = 5
            LockOnContainerRaidToolDamagePercent = 100.0
            Schedule                             = @()
        }

        foreach ($key in $defaults.Keys) {
            if (-not $data.PSObject.Properties[$key]) {
                $data | Add-Member -NotePropertyName $key -NotePropertyValue $defaults[$key] -Force
            }
        }

        $weekdayNames = @('Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday')

        if (-not $data.Schedule) { $data.Schedule = @() }

        foreach ($day in $weekdayNames) {
            $found = $false
            foreach ($entry in @($data.Schedule)) {
                if ([string]$entry.Weekday -eq $day) {
                    $found = $true
                    break
                }
            }
            if (-not $found) {
                $data.Schedule += [pscustomobject][ordered]@{
                    Weekday         = $day
                    StartHour       = 0
                    StartMinute     = 0
                    DurationMinutes = 1440
                }
            }
        }

        $parseLinesToArray = {
            param([string]$Text)
            $items = @()
            foreach ($line in ($Text -split "(`r`n|`n|`r)")) {
                $trim = $line.Trim()
                if (-not [string]::IsNullOrWhiteSpace($trim)) {
                    $items += $trim
                }
            }
            return [object[]]@($items)
        }.GetNewClosure()

        $raidSelectedScheduleIndex = -1

        $root = New-Object System.Windows.Forms.Panel
        $root.Location = New-Object System.Drawing.Point($baseX, $baseY)
        $root.Size = New-Object System.Drawing.Size($maxWidth, 1280)
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$HostPanel.Controls.Add($root)

        $topPanel = New-Object System.Windows.Forms.Panel
        $topPanel.Location = New-Object System.Drawing.Point(0, 0)
        $topPanel.Size = New-Object System.Drawing.Size(1600, 760)
        $topPanel.BackColor = $global:UGSM_ColorPanelBackground
        $topPanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($topPanel)

        $lblTitle = New-Object System.Windows.Forms.Label
        $lblTitle.Text = 'Raid Settings'
        $lblTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblTitle.Size = New-Object System.Drawing.Size(220, 24)
        $lblTitle.ForeColor = $global:UGSM_ColorText
        $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 10, [System.Drawing.FontStyle]::Bold)
        [void]$topPanel.Controls.Add($lblTitle)

        $lblSub = New-Object System.Windows.Forms.Label
        $lblSub.Text = 'Base raid mode, whitelist, safe/barbed wire/lock/container raid tools, and weekly schedule'
        $lblSub.Location = New-Object System.Drawing.Point(12, 34)
        $lblSub.Size = New-Object System.Drawing.Size(900, 20)
        $lblSub.ForeColor = $global:UGSM_ColorMutedText
        [void]$topPanel.Controls.Add($lblSub)

        $lblVersion = New-Object System.Windows.Forms.Label
        $lblVersion.Text = 'Version'
        $lblVersion.Location = New-Object System.Drawing.Point(12, 72)
        $lblVersion.Size = New-Object System.Drawing.Size(80, 18)
        $lblVersion.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblVersion)

        $txtVersion = New-Object System.Windows.Forms.TextBox
        $txtVersion.Location = New-Object System.Drawing.Point(12, 92)
