        $lblRaidMode = New-Object System.Windows.Forms.Label
        $lblRaidMode.Text = 'BaseBuildingRaidMode'
        $lblRaidMode.Location = New-Object System.Drawing.Point(110, 72)
        $lblRaidMode.Size = New-Object System.Drawing.Size(160, 18)
        $lblRaidMode.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblRaidMode)

        $cmbRaidMode = New-Object System.Windows.Forms.ComboBox
        $cmbRaidMode.Location = New-Object System.Drawing.Point(110, 92)
        $cmbRaidMode.Size = New-Object System.Drawing.Size(220, 26)
        $cmbRaidMode.DropDownStyle = 'DropDownList'
        foreach ($item in @('0', '1', '2')) { [void]$cmbRaidMode.Items.Add($item) }
        $raidModeIndex = [int]$data.BaseBuildingRaidMode
        if ($raidModeIndex -ge 0 -and $raidModeIndex -lt $cmbRaidMode.Items.Count) {
            $cmbRaidMode.SelectedIndex = $raidModeIndex
        }
        else {
            $cmbRaidMode.SelectedIndex = 0
        }
        [void]$topPanel.Controls.Add($cmbRaidMode)

        $checkConfigs = @(
            @{ Text = 'EnableExplosiveWhitelist'; Name = 'chkEnableExplosiveWhitelist'; X = 360; Y = 92; Checked = ([int]$data.EnableExplosiveWhitelist -eq 1) },
            @{ Text = 'CanRaidSafes'; Name = 'chkCanRaidSafes'; X = 620; Y = 92; Checked = ([int]$data.CanRaidSafes -eq 1) },
            @{ Text = 'SafeRaidUseSchedule'; Name = 'chkSafeRaidUseSchedule'; X = 780; Y = 92; Checked = ([int]$data.SafeRaidUseSchedule -eq 1) },

            @{ Text = 'CanRaidBarbedWire'; Name = 'chkCanRaidBarbedWire'; X = 360; Y = 122; Checked = ([int]$data.CanRaidBarbedWire -eq 1) },
            @{ Text = 'CanRaidLocksOnWalls'; Name = 'chkCanRaidLocksOnWalls'; X = 560; Y = 122; Checked = ([int]$data.CanRaidLocksOnWalls -eq 1) },
            @{ Text = 'CanRaidLocksOnFences'; Name = 'chkCanRaidLocksOnFences'; X = 770; Y = 122; Checked = ([int]$data.CanRaidLocksOnFences -eq 1) },

            @{ Text = 'CanRaidLocksOnTents'; Name = 'chkCanRaidLocksOnTents'; X = 360; Y = 152; Checked = ([int]$data.CanRaidLocksOnTents -eq 1) },
            @{ Text = 'CanRaidLocksOnContainers'; Name = 'chkCanRaidLocksOnContainers'; X = 560; Y = 152; Checked = ([int]$data.CanRaidLocksOnContainers -eq 1) },
            @{ Text = 'LockOnContainerRaidUseSchedule'; Name = 'chkLockOnContainerRaidUseSchedule'; X = 820; Y = 152; Checked = ([int]$data.LockOnContainerRaidUseSchedule -eq 1) }
        )

        $checkBoxes = @{}
        foreach ($cfg in $checkConfigs) {
            $cb = New-Object System.Windows.Forms.CheckBox
            $cb.AutoSize = $true
            $cb.Text = $cfg.Text
            $cb.Location = New-Object System.Drawing.Point($cfg.X, $cfg.Y)
            $cb.Checked = $cfg.Checked
            $cb.ForeColor = $global:UGSM_ColorText
            $cb.BackColor = [System.Drawing.Color]::Transparent
            [void]$topPanel.Controls.Add($cb)
        }

        $numericConfigs = @(
            @{ Label = 'ExplosionTime'; Name = 'txtExplosionTime'; X = 12; Y = 230; W = 120; Text = [string]$data.ExplosionTime },
            @{ Label = 'ExplosionDamageMultiplier'; Name = 'txtExplosionDamageMultiplier'; X = 150; Y = 230; W = 150; Text = [string]$data.ExplosionDamageMultiplier },
            @{ Label = 'ProjectileDamageMultiplier'; Name = 'txtProjectileDamageMultiplier'; X = 320; Y = 230; W = 150; Text = [string]$data.ProjectileDamageMultiplier },

            @{ Label = 'SafeExplosionDamageMultiplier'; Name = 'txtSafeExplosionDamageMultiplier'; X = 12; Y = 305; W = 170; Text = [string]$data.SafeExplosionDamageMultiplier },
            @{ Label = 'SafeProjectileDamageMultiplier'; Name = 'txtSafeProjectileDamageMultiplier'; X = 200; Y = 305; W = 170; Text = [string]$data.SafeProjectileDamageMultiplier },
            @{ Label = 'SafeRaidToolTimeSeconds'; Name = 'txtSafeRaidToolTimeSeconds'; X = 390; Y = 305; W = 140; Text = [string]$data.SafeRaidToolTimeSeconds },
            @{ Label = 'SafeRaidToolCycles'; Name = 'txtSafeRaidToolCycles'; X = 550; Y = 305; W = 120; Text = [string]$data.SafeRaidToolCycles },
