            @{ Label = 'BarbedWireRaidToolDamagePercent'; Name = 'txtBarbedWireRaidToolDamagePercent'; X = 380; Y = 380; W = 180; Text = [string]$data.BarbedWireRaidToolDamagePercent },

            @{ Label = 'LockOnWallRaidToolTimeSeconds'; Name = 'txtLockOnWallRaidToolTimeSeconds'; X = 12; Y = 455; W = 180; Text = [string]$data.LockOnWallRaidToolTimeSeconds },
            @{ Label = 'LockOnFenceRaidToolTimeSeconds'; Name = 'txtLockOnFenceRaidToolTimeSeconds'; X = 210; Y = 455; W = 180; Text = [string]$data.LockOnFenceRaidToolTimeSeconds },
            @{ Label = 'LockOnTentRaidToolTimeSeconds'; Name = 'txtLockOnTentRaidToolTimeSeconds'; X = 410; Y = 455; W = 170; Text = [string]$data.LockOnTentRaidToolTimeSeconds },
            @{ Label = 'LockRaidToolCycles'; Name = 'txtLockRaidToolCycles'; X = 600; Y = 455; W = 120; Text = [string]$data.LockRaidToolCycles },
