            @{ Label = 'LockOnContainerRaidToolCycles'; Name = 'txtLockOnContainerRaidToolCycles'; X = 230; Y = 530; W = 170; Text = [string]$data.LockOnContainerRaidToolCycles },
            @{ Label = 'LockOnContainerRaidToolDamagePercent'; Name = 'txtLockOnContainerRaidToolDamagePercent'; X = 420; Y = 530; W = 200; Text = [string]$data.LockOnContainerRaidToolDamagePercent }
        )

