        if ($data.ExplosiveDamageWhitelist) { $txtExplosiveWhitelist.Text = (@($data.ExplosiveDamageWhitelist) -join [Environment]::NewLine) }
        [void]$topPanel.Controls.Add($txtExplosiveWhitelist)

        $lblSafeRaidTools = New-Object System.Windows.Forms.Label
        $lblSafeRaidTools.Text = 'SafeRaidTools (one per line)'
        $lblSafeRaidTools.Location = New-Object System.Drawing.Point(980, 420)
        $lblSafeRaidTools.Size = New-Object System.Drawing.Size(220, 18)
        $lblSafeRaidTools.ForeColor = $global:UGSM_ColorText
