        $lblBarbedWireRaidTools = New-Object System.Windows.Forms.Label
        $lblBarbedWireRaidTools.Text = 'BarbedWireRaidTools (one per line)'
        $lblBarbedWireRaidTools.Location = New-Object System.Drawing.Point(1180, 420)
        $lblBarbedWireRaidTools.Size = New-Object System.Drawing.Size(240, 18)
        $lblBarbedWireRaidTools.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblBarbedWireRaidTools)

        $txtBarbedWireRaidTools = New-Object System.Windows.Forms.TextBox
        $txtBarbedWireRaidTools.Location = New-Object System.Drawing.Point(1180, 440)
        $txtBarbedWireRaidTools.Size = New-Object System.Drawing.Size(180, 65)
        $txtBarbedWireRaidTools.Multiline = $true
        $txtBarbedWireRaidTools.ScrollBars = 'Vertical'
        $txtBarbedWireRaidTools.BackColor = $global:UGSM_ColorInputBackground
        $txtBarbedWireRaidTools.ForeColor = $global:UGSM_ColorText
        $txtBarbedWireRaidTools.BorderStyle = 'FixedSingle'
        if ($data.BarbedWireRaidTools) { $txtBarbedWireRaidTools.Text = (@($data.BarbedWireRaidTools) -join [Environment]::NewLine) }
        [void]$topPanel.Controls.Add($txtBarbedWireRaidTools)

        $lblLockRaidTools = New-Object System.Windows.Forms.Label
        $lblLockRaidTools.Text = 'LockRaidTools (one per line)'
        $lblLockRaidTools.Location = New-Object System.Drawing.Point(980, 550)
        $lblLockRaidTools.Size = New-Object System.Drawing.Size(220, 18)
        $lblLockRaidTools.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblLockRaidTools)

        $txtLockRaidTools = New-Object System.Windows.Forms.TextBox
        $txtLockRaidTools.Location = New-Object System.Drawing.Point(980, 570)
        $txtLockRaidTools.Size = New-Object System.Drawing.Size(180, 65)
        $txtLockRaidTools.Multiline = $true
        $txtLockRaidTools.ScrollBars = 'Vertical'
        $txtLockRaidTools.BackColor = $global:UGSM_ColorInputBackground
        $txtLockRaidTools.ForeColor = $global:UGSM_ColorText
        $txtLockRaidTools.BorderStyle = 'FixedSingle'
        if ($data.LockRaidTools) { $txtLockRaidTools.Text = (@($data.LockRaidTools) -join [Environment]::NewLine) }
        [void]$topPanel.Controls.Add($txtLockRaidTools)

        $lblLockOnContainerRaidTools = New-Object System.Windows.Forms.Label
        $lblLockOnContainerRaidTools.Text = 'LockOnContainerRaidTools (one per line)'
        $lblLockOnContainerRaidTools.Location = New-Object System.Drawing.Point(1180, 550)
        $lblLockOnContainerRaidTools.Size = New-Object System.Drawing.Size(260, 18)
        $lblLockOnContainerRaidTools.ForeColor = $global:UGSM_ColorText
        [void]$topPanel.Controls.Add($lblLockOnContainerRaidTools)

        $txtLockOnContainerRaidTools = New-Object System.Windows.Forms.TextBox
        $txtLockOnContainerRaidTools.Location = New-Object System.Drawing.Point(1180, 570)
        $txtLockOnContainerRaidTools.Size = New-Object System.Drawing.Size(180, 65)
        $txtLockOnContainerRaidTools.Multiline = $true
        $txtLockOnContainerRaidTools.ScrollBars = 'Vertical'
        $txtLockOnContainerRaidTools.BackColor = $global:UGSM_ColorInputBackground
        $txtLockOnContainerRaidTools.ForeColor = $global:UGSM_ColorText
        $txtLockOnContainerRaidTools.BorderStyle = 'FixedSingle'
        if ($data.LockOnContainerRaidTools) { $txtLockOnContainerRaidTools.Text = (@($data.LockOnContainerRaidTools) -join [Environment]::NewLine) }
        [void]$topPanel.Controls.Add($txtLockOnContainerRaidTools)

        $btnApplyTop = New-Object System.Windows.Forms.Button
        $btnApplyTop.Text = 'Apply Raid Settings'
        $btnApplyTop.Location = New-Object System.Drawing.Point(980, 670)
        $btnApplyTop.Size = New-Object System.Drawing.Size(160, 34)
        $btnApplyTop.BackColor = $UGSM_ExpansionAccentColor
        $btnApplyTop.ForeColor = $global:UGSM_ColorText
        $btnApplyTop.FlatStyle = 'Flat'
        $btnApplyTop.UseVisualStyleBackColor = $false
        [void]$topPanel.Controls.Add($btnApplyTop)

        $schedulePanel = New-Object System.Windows.Forms.Panel
        $schedulePanel.Location = New-Object System.Drawing.Point(0, 775)
        $schedulePanel.Size = New-Object System.Drawing.Size(1600, 380)
        $schedulePanel.BackColor = $global:UGSM_ColorPanelBackground
        $schedulePanel.BorderStyle = 'FixedSingle'
        [void]$root.Controls.Add($schedulePanel)

        $lblScheduleTitle = New-Object System.Windows.Forms.Label
        $lblScheduleTitle.Text = 'Raid Schedule'
        $lblScheduleTitle.Location = New-Object System.Drawing.Point(12, 10)
        $lblScheduleTitle.Size = New-Object System.Drawing.Size(180, 24)
        $lblScheduleTitle.ForeColor = $global:UGSM_ColorText
        $lblScheduleTitle.Font = New-Object System.Drawing.Font('Segoe UI', 9, [System.Drawing.FontStyle]::Bold)
        [void]$schedulePanel.Controls.Add($lblScheduleTitle)

        $lstSchedule = New-Object System.Windows.Forms.ListBox
        $lstSchedule.Location = New-Object System.Drawing.Point(12, 45)
        $lstSchedule.Size = New-Object System.Drawing.Size(260, 280)
        $lstSchedule.BackColor = $global:UGSM_ColorInputBackground
        $lstSchedule.ForeColor = $global:UGSM_ColorText
        [void]$schedulePanel.Controls.Add($lstSchedule)

        $lblWeekday = New-Object System.Windows.Forms.Label
        $lblWeekday.Text = 'Weekday'
        $lblWeekday.Location = New-Object System.Drawing.Point(310, 45)
        $lblWeekday.Size = New-Object System.Drawing.Size(100, 18)
        $lblWeekday.ForeColor = $global:UGSM_ColorText
        [void]$schedulePanel.Controls.Add($lblWeekday)

        $cmbWeekday = New-Object System.Windows.Forms.ComboBox
        $cmbWeekday.Location = New-Object System.Drawing.Point(310, 65)
        $cmbWeekday.Size = New-Object System.Drawing.Size(160, 26)
        $cmbWeekday.DropDownStyle = 'DropDownList'
        foreach ($day in $weekdayNames) { [void]$cmbWeekday.Items.Add($day) }
        [void]$schedulePanel.Controls.Add($cmbWeekday)

        $lblStartHour = New-Object System.Windows.Forms.Label
        $lblStartHour.Text = 'StartHour'
        $lblStartHour.Location = New-Object System.Drawing.Point(500, 45)
        $lblStartHour.Size = New-Object System.Drawing.Size(90, 18)
        $lblStartHour.ForeColor = $global:UGSM_ColorText
        [void]$schedulePanel.Controls.Add($lblStartHour)

        $txtStartHour = New-Object System.Windows.Forms.TextBox
        $txtStartHour.Location = New-Object System.Drawing.Point(500, 65)
        $txtStartHour.Size = New-Object System.Drawing.Size(100, 26)
        $txtStartHour.BackColor = $global:UGSM_ColorInputBackground
        $txtStartHour.ForeColor = $global:UGSM_ColorText
        $txtStartHour.BorderStyle = 'FixedSingle'
        [void]$schedulePanel.Controls.Add($txtStartHour)

        $lblStartMinute = New-Object System.Windows.Forms.Label
        $lblStartMinute.Text = 'StartMinute'
        $lblStartMinute.Location = New-Object System.Drawing.Point(620, 45)
        $lblStartMinute.Size = New-Object System.Drawing.Size(100, 18)
        $lblStartMinute.ForeColor = $global:UGSM_ColorText
        [void]$schedulePanel.Controls.Add($lblStartMinute)

        $txtStartMinute = New-Object System.Windows.Forms.TextBox
        $txtStartMinute.Location = New-Object System.Drawing.Point(620, 65)
        $txtStartMinute.Size = New-Object System.Drawing.Size(100, 26)
        $txtStartMinute.BackColor = $global:UGSM_ColorInputBackground
        $txtStartMinute.ForeColor = $global:UGSM_ColorText
        $txtStartMinute.BorderStyle = 'FixedSingle'
        [void]$schedulePanel.Controls.Add($txtStartMinute)

        $lblDurationMinutes = New-Object System.Windows.Forms.Label
        $lblDurationMinutes.Text = 'DurationMinutes'
        $lblDurationMinutes.Location = New-Object System.Drawing.Point(740, 45)
        $lblDurationMinutes.Size = New-Object System.Drawing.Size(120, 18)
        $lblDurationMinutes.ForeColor = $global:UGSM_ColorText
        [void]$schedulePanel.Controls.Add($lblDurationMinutes)

        $txtDurationMinutes = New-Object System.Windows.Forms.TextBox
        $txtDurationMinutes.Location = New-Object System.Drawing.Point(740, 65)
        $txtDurationMinutes.Size = New-Object System.Drawing.Size(120, 26)
        $txtDurationMinutes.BackColor = $global:UGSM_ColorInputBackground
        $txtDurationMinutes.ForeColor = $global:UGSM_ColorText
        $txtDurationMinutes.BorderStyle = 'FixedSingle'
        [void]$schedulePanel.Controls.Add($txtDurationMinutes)

        $btnApplySchedule = New-Object System.Windows.Forms.Button
        $btnApplySchedule.Text = 'Apply Selected Day'
        $btnApplySchedule.Location = New-Object System.Drawing.Point(310, 120)
        $btnApplySchedule.Size = New-Object System.Drawing.Size(160, 32)
        $btnApplySchedule.BackColor = $UGSM_ExpansionAccentColor
        $btnApplySchedule.ForeColor = $global:UGSM_ColorText
        $btnApplySchedule.FlatStyle = 'Flat'
        $btnApplySchedule.UseVisualStyleBackColor = $false
        [void]$schedulePanel.Controls.Add($btnApplySchedule)

        $refreshSchedule = {
            $lstSchedule.Items.Clear()
            foreach ($entry in @($data.Schedule)) {
                $line = ([string]$entry.Weekday + ' | ' + ('{0:D2}:{1:D2}' -f [int]$entry.StartHour, [int]$entry.StartMinute) + ' | ' + [string]$entry.DurationMinutes + ' min')
                [void]$lstSchedule.Items.Add($line)
            }

            if ($lstSchedule.Items.Count -gt 0) {
                if ($raidSelectedScheduleIndex -lt 0 -or $raidSelectedScheduleIndex -ge $lstSchedule.Items.Count) {
                    $raidSelectedScheduleIndex = 0
                }
                $lstSchedule.SelectedIndex = $raidSelectedScheduleIndex
            }
        }.GetNewClosure()

        $loadSelectedSchedule = {
            $idx = $lstSchedule.SelectedIndex
            $items = @($data.Schedule)
            if ($idx -lt 0 -or $idx -ge $items.Count) {
                $raidSelectedScheduleIndex = -1
                $cmbWeekday.SelectedIndex = -1
                $txtStartHour.Text = ''
                $txtStartMinute.Text = ''
                $txtDurationMinutes.Text = ''
                return
            }

            $raidSelectedScheduleIndex = $idx
            $item = $items[$idx]
            $dayIndex = $cmbWeekday.Items.IndexOf([string]$item.Weekday)
            $cmbWeekday.SelectedIndex = $dayIndex
            $txtStartHour.Text = [string]$item.StartHour
            $txtStartMinute.Text = [string]$item.StartMinute
            $txtDurationMinutes.Text = [string]$item.DurationMinutes
        }.GetNewClosure()

        $btnApplyTop.Add_Click({
                $doubleFields = @(
                    'txtExplosionTime',
                    'txtExplosionDamageMultiplier',
                    'txtProjectileDamageMultiplier',
                    'txtSafeExplosionDamageMultiplier',
                    'txtSafeProjectileDamageMultiplier',
                    'txtSafeRaidToolDamagePercent',
                    'txtBarbedWireRaidToolDamagePercent',
                    'txtLockRaidToolDamagePercent',
                    'txtLockOnContainerRaidToolDamagePercent'
                )
                $intFields = @(
                    'txtSafeRaidToolTimeSeconds',
                    'txtSafeRaidToolCycles',
                    'txtBarbedWireRaidToolTimeSeconds',
                    'txtBarbedWireRaidToolCycles',
                    'txtLockOnWallRaidToolTimeSeconds',
                    'txtLockOnFenceRaidToolTimeSeconds',
                    'txtLockOnTentRaidToolTimeSeconds',
                    'txtLockRaidToolCycles',
                    'txtLockOnContainerRaidToolTimeSeconds',
                    'txtLockOnContainerRaidToolCycles'
                )

                foreach ($field in $doubleFields) {
                    $v = 0.0
                    if (-not [double]::TryParse($textBoxes[$field].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($field + ' must be a valid number.'))
                        return
                    }
                }

                foreach ($field in $intFields) {
                    $v = 0
                    if (-not [int]::TryParse($textBoxes[$field].Text, [ref]$v)) {
                        [System.Windows.Forms.MessageBox]::Show(($field + ' must be a valid integer.'))
                        return
                    }
                }

                $data.BaseBuildingRaidMode = $cmbRaidMode.SelectedIndex
                $data.EnableExplosiveWhitelist = $(if ($checkBoxes['chkEnableExplosiveWhitelist'].Checked) { 1 } else { 0 })
                $data.CanRaidSafes = $(if ($checkBoxes['chkCanRaidSafes'].Checked) { 1 } else { 0 })
                $data.SafeRaidUseSchedule = $(if ($checkBoxes['chkSafeRaidUseSchedule'].Checked) { 1 } else { 0 })
                $data.CanRaidBarbedWire = $(if ($checkBoxes['chkCanRaidBarbedWire'].Checked) { 1 } else { 0 })
                $data.CanRaidLocksOnWalls = $(if ($checkBoxes['chkCanRaidLocksOnWalls'].Checked) { 1 } else { 0 })
                $data.CanRaidLocksOnFences = $(if ($checkBoxes['chkCanRaidLocksOnFences'].Checked) { 1 } else { 0 })
                $data.CanRaidLocksOnTents = $(if ($checkBoxes['chkCanRaidLocksOnTents'].Checked) { 1 } else { 0 })
                $data.CanRaidLocksOnContainers = $(if ($checkBoxes['chkCanRaidLocksOnContainers'].Checked) { 1 } else { 0 })
                $data.LockOnContainerRaidUseSchedule = $(if ($checkBoxes['chkLockOnContainerRaidUseSchedule'].Checked) { 1 } else { 0 })

                $data.ExplosionTime = [double]$textBoxes['txtExplosionTime'].Text
                $data.ExplosionDamageMultiplier = [double]$textBoxes['txtExplosionDamageMultiplier'].Text
                $data.ProjectileDamageMultiplier = [double]$textBoxes['txtProjectileDamageMultiplier'].Text
                $data.ExplosiveDamageWhitelist = [object[]]@(& $parseLinesToArray $txtExplosiveWhitelist.Text)

                $data.SafeExplosionDamageMultiplier = [double]$textBoxes['txtSafeExplosionDamageMultiplier'].Text
                $data.SafeProjectileDamageMultiplier = [double]$textBoxes['txtSafeProjectileDamageMultiplier'].Text
                $data.SafeRaidTools = [object[]]@(& $parseLinesToArray $txtSafeRaidTools.Text)
                $data.SafeRaidToolTimeSeconds = [int]$textBoxes['txtSafeRaidToolTimeSeconds'].Text
                $data.SafeRaidToolCycles = [int]$textBoxes['txtSafeRaidToolCycles'].Text
                $data.SafeRaidToolDamagePercent = [double]$textBoxes['txtSafeRaidToolDamagePercent'].Text

                $data.BarbedWireRaidTools = [object[]]@(& $parseLinesToArray $txtBarbedWireRaidTools.Text)
                $data.BarbedWireRaidToolTimeSeconds = [int]$textBoxes['txtBarbedWireRaidToolTimeSeconds'].Text
                $data.BarbedWireRaidToolCycles = [int]$textBoxes['txtBarbedWireRaidToolCycles'].Text
                $data.BarbedWireRaidToolDamagePercent = [double]$textBoxes['txtBarbedWireRaidToolDamagePercent'].Text

                $data.LockRaidTools = [object[]]@(& $parseLinesToArray $txtLockRaidTools.Text)
                $data.LockOnWallRaidToolTimeSeconds = [int]$textBoxes['txtLockOnWallRaidToolTimeSeconds'].Text
                $data.LockOnFenceRaidToolTimeSeconds = [int]$textBoxes['txtLockOnFenceRaidToolTimeSeconds'].Text
                $data.LockOnTentRaidToolTimeSeconds = [int]$textBoxes['txtLockOnTentRaidToolTimeSeconds'].Text
                $data.LockRaidToolCycles = [int]$textBoxes['txtLockRaidToolCycles'].Text
                $data.LockRaidToolDamagePercent = [double]$textBoxes['txtLockRaidToolDamagePercent'].Text

                $data.LockOnContainerRaidTools = [object[]]@(& $parseLinesToArray $txtLockOnContainerRaidTools.Text)
                $data.LockOnContainerRaidToolTimeSeconds = [int]$textBoxes['txtLockOnContainerRaidToolTimeSeconds'].Text
                $data.LockOnContainerRaidToolCycles = [int]$textBoxes['txtLockOnContainerRaidToolCycles'].Text
                $data.LockOnContainerRaidToolDamagePercent = [double]$textBoxes['txtLockOnContainerRaidToolDamagePercent'].Text

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = 'Applied Raid settings.' }
            }.GetNewClosure())

        $lstSchedule.Add_SelectedIndexChanged({
                & $loadSelectedSchedule
            }.GetNewClosure())

        $btnApplySchedule.Add_Click({
                $idx = $lstSchedule.SelectedIndex
                $items = @($data.Schedule)
                if ($idx -lt 0 -or $idx -ge $items.Count) {
                    [System.Windows.Forms.MessageBox]::Show('Select a schedule entry first.')
                    return
                }

                $hour = 0
                $minute = 0
                $duration = 0

                if (-not [int]::TryParse($txtStartHour.Text, [ref]$hour)) {
                    [System.Windows.Forms.MessageBox]::Show('StartHour must be a valid integer.')
                    return
                }
                if (-not [int]::TryParse($txtStartMinute.Text, [ref]$minute)) {
                    [System.Windows.Forms.MessageBox]::Show('StartMinute must be a valid integer.')
                    return
                }
                if (-not [int]::TryParse($txtDurationMinutes.Text, [ref]$duration)) {
                    [System.Windows.Forms.MessageBox]::Show('DurationMinutes must be a valid integer.')
                    return
                }

                if ($hour -lt 0 -or $hour -gt 23) {
                    [System.Windows.Forms.MessageBox]::Show('StartHour must be between 0 and 23.')
                    return
                }
                if ($minute -lt 0 -or $minute -gt 59) {
                    [System.Windows.Forms.MessageBox]::Show('StartMinute must be between 0 and 59.')
                    return
                }

                $items[$idx] = [pscustomobject][ordered]@{
                    Weekday         = [string]$cmbWeekday.SelectedItem
                    StartHour       = $hour
                    StartMinute     = $minute
                    DurationMinutes = $duration
                }

                $data.Schedule = [object[]]@($items)
                if ($SettingsState) { $SettingsState.Data = $data }

                $raidSelectedScheduleIndex = $idx
                & $refreshSchedule
                if ($idx -ge 0 -and $idx -lt $lstSchedule.Items.Count) {
                    $lstSchedule.SelectedIndex = $idx
                }

                if ($StatusLabel) { $StatusLabel.Text = ('Applied raid schedule for ' + [string]$cmbWeekday.SelectedItem + '.') }
            }.GetNewClosure())

        $saveRaidSettings = {
            try {
                if ([string]::IsNullOrWhiteSpace([string]$FilePath)) {
                    throw 'No Raid settings file path is available.'
                }

                $jsonText = ($data | ConvertTo-Json -Depth 100)
                [void](Backup-UGSMGameDayZFile -TargetPath $FilePath)
                [void](Write-UGSMGameDayZTextFileSafe -Path $FilePath -Content $jsonText)

                if ($SettingsState) { $SettingsState.Data = $data }
                if ($StatusLabel) { $StatusLabel.Text = ('Saved Raid settings: ' + [System.IO.Path]::GetFileName($FilePath)) }
            }
            catch {
                if ($StatusLabel) { $StatusLabel.Text = 'Saving Raid settings failed: ' + $_.Exception.Message }
            }
        }.GetNewClosure()

        if ($SettingsState) {
            $SettingsState.CurrentSaveHandler = $saveRaidSettings
            $SettingsState.FileHandler = 'RaidSettings'
            $SettingsState.CurrentFilePath = $FilePath
            $SettingsState.Data = $data
        }

        & $refreshSchedule
        & $loadSelectedSchedule

        if ($StatusLabel) { $StatusLabel.Text = 'Raid editor loaded.' }
    }
    catch {
        $HostPanel.Controls.Clear()

        $err = New-Object System.Windows.Forms.Label
        $err.Location = New-Object System.Drawing.Point(0, 27)
        $err.Size = New-Object System.Drawing.Size(1450, 60)
        $err.Text = 'Raid editor failed: ' + $_.Exception.Message
        $err.ForeColor = [System.Drawing.Color]::Tomato
        [void]$HostPanel.Controls.Add($err)

        if ($StatusLabel) { $StatusLabel.Text = 'Raid editor failed: ' + $_.Exception.Message }
    }
}

function New-DayZExpansionSettingsTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter(Mandatory)]$State,
        [Parameter(Mandatory)]$Instance,
        [Parameter()]$StatusLabel
    )

    Initialize-UGSMExpansionThemeDefaults

    $Page.Controls.Clear()
    $Page.BackColor = $global:UGSM_ColorBackground
    $Page.ForeColor = $global:UGSM_ColorText
    $Page.AutoScroll = $false

    $root = New-Object System.Windows.Forms.Panel
    $root.Dock = 'Fill'
    $root.AutoScroll = $false
    $root.BackColor = $global:UGSM_ColorBackground
    [void]$Page.Controls.Add($root)

    $shell = New-Object System.Windows.Forms.Panel
    $shell.Location = New-Object System.Drawing.Point(0, 0)
    $shell.Size = New-Object System.Drawing.Size(
        [Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width),
        980
    )
    $shell.Anchor = 'Top,Left,Right'
    $shell.BackColor = $global:UGSM_ColorBackground
    $shell.BorderStyle = 'None'
    [void]$root.Controls.Add($shell)

    $topBar = New-Object System.Windows.Forms.Panel
    $topBar.Location = New-Object System.Drawing.Point(0, 0)
    $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
    $topBar.Anchor = 'Top,Left,Right'
    $topBar.BackColor = $global:UGSM_ColorBackground
    $topBar.BorderStyle = 'FixedSingle'
    [void]$shell.Controls.Add($topBar)

    $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
    $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
    $btnSaveAll = New-UGSMExpansionSaveButton -Text 'Save All' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall

    foreach ($button in @($btnRefresh, $btnSaveCurrent, $btnSaveAll)) {
        $button.Anchor = 'Top,Left'
        Set-UGSMExpansionButtonStyle -Button $button | Out-Null
        [void]$topBar.Controls.Add($button)
    }

    $layoutSettingsToolbar = {
        Set-UGSMExpansionToolbarLayout -Toolbar $topBar -BtnRefresh $btnRefresh -BtnSaveCurrent $btnSaveCurrent -BtnSaveAll $btnSaveAll
    }.GetNewClosure()
    & $layoutSettingsToolbar
    $topBar.Add_SizeChanged($layoutSettingsToolbar)

    $body = New-Object System.Windows.Forms.Panel
    $body.Location = New-Object System.Drawing.Point(
        $UGSM_ExpansionOffsetX,
        ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap)
    )
    $body.Size = New-Object System.Drawing.Size(
        $shell.ClientSize.Width,
        ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12)
    )
    $body.Anchor = 'Top,Left,Right,Bottom'
    $body.BackColor = $global:UGSM_ColorBackground
    $body.BorderStyle = 'FixedSingle'
    [void]$shell.Controls.Add($body)

    $leftPanel = New-UGSMExpansionLeftListPanel -X ($UGSM_ExpansionGap) -Y ($UGSM_ExpansionGap) -Width $UGSM_ExpansionLeftPanelWidth -Height $styleTestLeftMinHeight
    [void]$body.Controls.Add($leftPanel)

    $cmbSource = New-UGSMExpansionEditorComboBox -X 12 -Y 12 -Width ($UGSM_ExpansionLeftPanelWidth - 24)
    $cmbSource.DropDownStyle = 'DropDownList'
    [void]$cmbSource.Items.Add('Mission Settings')
    [void]$cmbSource.Items.Add('Profile Settings')
    [void]$leftPanel.Controls.Add($cmbSource)

    $lstFiles = New-Object System.Windows.Forms.ListBox
    $lstFiles.Location = New-Object System.Drawing.Point(12, 46)
    $lstFiles.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), 620)
    $lstFiles.Anchor = 'Top,Left,Bottom,Right'
    $lstFiles.BackColor = $global:UGSM_ColorInputBackground
    $lstFiles.ForeColor = $global:UGSM_ColorText
    $lstFiles.BorderStyle = 'FixedSingle'
    $lstFiles.IntegralHeight = $false
    [void]$leftPanel.Controls.Add($lstFiles)

    $editorHost = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 700
    [void]$body.Controls.Add($editorHost)

    $settingsState = [ordered]@{
        Roots              = [ordered]@{}
        Files              = @()
        CurrentRootKey     = ''
        CurrentRootPath    = ''
        CurrentFilePath    = ''
        CurrentObject      = $null
        CurrentScalarProps = @()
        IsStructured       = $false
        FileHandler        = 'None'
        EditorHost         = $editorHost
        CurrentSaveHandler = $null
        Instance           = $Instance
    }

    $getSettingsRoots = {
        $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance

        $roots = [ordered]@{}
        $roots['Mission Settings'] = Join-Path ([string]$paths.MissionExpansionRoot) 'settings'
        $roots['Profile Settings'] = Join-Path ([string]$paths.ProfileExpansionRoot) 'Settings'
        return $roots
    }.GetNewClosure()

    $clearEditor = {
        $editorHost.Controls.Clear()
        $settingsState.CurrentFilePath = ''
        $settingsState.CurrentObject = $null
        $settingsState.CurrentScalarProps = @()
        $settingsState.IsStructured = $false
        $settingsState.FileHandler = 'None'
        $settingsState.CurrentSaveHandler = $null
    }.GetNewClosure()

    $showGenericPlaceholder = {
        param($filePath)

        $editorHost.Controls.Clear()

        $p = New-Object System.Windows.Forms.Panel
        $p.Dock = 'Fill'
        $p.BackColor = $global:UGSM_ColorBackground
        [void]$editorHost.Controls.Add($p)

        $lbl = New-Object System.Windows.Forms.Label
        $lbl.Text = 'No file-specific editor has been built for this file yet.' + [Environment]::NewLine + [Environment]::NewLine + [System.IO.Path]::GetFileName($filePath)
        $lbl.ForeColor = $global:UGSM_ColorText
        $lbl.Location = New-Object System.Drawing.Point(12, 12)
        $lbl.Size = New-Object System.Drawing.Size(700, 60)
        [void]$p.Controls.Add($lbl)

        $settingsState.FileHandler = 'GenericPlaceholder'
        $settingsState.CurrentSaveHandler = $null
    }.GetNewClosure()

    $refreshFileList = {
        try {
            & $clearEditor

            $lstFiles.Items.Clear()
            $settingsState.Files = @()

            $selectedSource = [string]$cmbSource.SelectedItem
            if ([string]::IsNullOrWhiteSpace($selectedSource)) { return }

            $rootPath = [string]$settingsState.Roots[$selectedSource]
            $settingsState.CurrentRootKey = $selectedSource
            $settingsState.CurrentRootPath = $rootPath

            if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
                if ($StatusLabel) { $StatusLabel.Text = ($selectedSource + ' folder was not found.') }
                return
            }

            $settingsState.Files = @(
                Get-ChildItem -LiteralPath $rootPath -File -Filter '*.json' -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -notmatch '\.bak\.json$' } |
                Sort-Object Name
            )

            foreach ($file in $settingsState.Files) {
                [void]$lstFiles.Items.Add([string]$file.Name)
            }

            if ($lstFiles.Items.Count -gt 0) {
                $lstFiles.SelectedIndex = 0
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded ' + [string]$settingsState.Files.Count + ' setting file(s) from ' + $selectedSource + '.')
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Refreshing settings files failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $loadSelectedFile = {
        try {
            & $clearEditor

            if ($lstFiles.SelectedIndex -lt 0) { return }
            if ($lstFiles.SelectedIndex -ge $settingsState.Files.Count) { return }

            $file = $settingsState.Files[$lstFiles.SelectedIndex]
            $settingsState.CurrentFilePath = [string]$file.FullName

            switch ([string]$file.Name) {
                'AILocationSettings.json' {
                    Show-DayZExpansionSettingEditor_AILocationSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'AIPatrolSettings.json' {
                    Show-DayZExpansionSettingEditor_AIPatrolSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'BaseBuildingSettings.json' {
                    Show-DayZExpansionSettingEditor_BaseBuildingSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'HardlineSettings.json' {
                    Show-DayZExpansionSettingEditor_HardlineSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'MapSettings.json' {
                    Show-DayZExpansionSettingEditor_MapSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'MarketSettings.json' {
                    Show-DayZExpansionSettingEditor_MarketSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'P2PMarketSettings.json' {
                    Show-DayZExpansionSettingEditor_P2PMarketSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'PersonalStorageSettings.json' {
                    Show-DayZExpansionSettingEditor_PersonalStorageSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'SafeZoneSettings.json' {
                    Show-DayZExpansionSettingEditor_SafeZoneSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'SpawnSettings.json' {
                    Show-DayZExpansionSettingEditor_SpawnSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'AirdropSettings.json' {
                    Show-DayZExpansionSettingEditor_AirdropSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'AISettings.json' {
                    Show-DayZExpansionSettingEditor_AISettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'BookSettings.json' {
                    Show-DayZExpansionSettingEditor_BookSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'ChatSettings.json' {
                    Show-DayZExpansionSettingEditor_ChatSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'CodeLockSettings.json' {
                    Show-DayZExpansionSettingEditor_CodeLockSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'CoreSettings.json' {
                    Show-DayZExpansionSettingEditor_CoreSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'DamageSystemSettings.json' {
                    Show-DayZExpansionSettingEditor_DamageSystemSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'DebugSettings.json' {
                    Show-DayZExpansionSettingEditor_DebugSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'GarageSettings.json' {
                    Show-DayZExpansionSettingEditor_GarageSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'GeneralSettings.json' {
                    Show-DayZExpansionSettingEditor_GeneralSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'GlobalMarkerSettings.json' {
                    Show-DayZExpansionSettingEditor_GlobalMarkerSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'GroupSettings.json' {
                    Show-DayZExpansionSettingEditor_GroupSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'LoadoutSettings.json' {
                    Show-DayZExpansionSettingEditor_LoadoutSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'LogSettings.json' {
                    Show-DayZExpansionSettingEditor_LogSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'MissionSettings.json' {
                    Show-DayZExpansionSettingEditor_MissionSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'NameTagsSettings.json' {
                    Show-DayZExpansionSettingEditor_NameTagsSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'NotificationSettings.json' {
                    Show-DayZExpansionSettingEditor_NotificationSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'PartySettings.json' {
                    Show-DayZExpansionSettingEditor_PartySettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'PlayerListSettings.json' {
                    Show-DayZExpansionSettingEditor_PlayerListSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'QuestSettings.json' {
                    Show-DayZExpansionSettingEditor_QuestSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'RaidSettings.json' {
                    Show-DayZExpansionSettingEditor_RaidSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'SocialMediaSettings.json' {
                    Show-DayZExpansionSettingEditor_SocialMediaSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'TerritorySettings.json' {
                    Show-DayZExpansionSettingEditor_TerritorySettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                'VehicleSettings.json' {
                    Show-DayZExpansionSettingEditor_VehicleSettings -HostPanel $editorHost -FilePath $file.FullName -SettingsState $settingsState -StatusLabel $StatusLabel
                }
                default {
                    & $showGenericPlaceholder $file.FullName
                }
            }

            if ($StatusLabel) {
                $StatusLabel.Text = ('Loaded settings file: ' + [string]$file.Name)
            }
        }
        catch {
            if ($StatusLabel) {
                $StatusLabel.Text = 'Loading settings file failed: ' + $_.Exception.Message
            }
        }
    }.GetNewClosure()

    $saveCurrentFile = {
        try {
            if ($settingsState.CurrentSaveHandler -is [scriptblock]) {
                & $settingsState.CurrentSaveHandler
                return
            }

            throw 'No save handler is registered for the selected settings file yet.'
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Saving current settings file failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $saveAllFiles = {
        try {
            if ($lstFiles.Items.Count -eq 0) {
                throw 'There are no settings files to save.'
            }

            & $saveCurrentFile

            if ($StatusLabel) {
                $StatusLabel.Text = 'Save All completed for the current settings set.'
            }
        }
        catch {
            if ($StatusLabel) { $StatusLabel.Text = 'Save All failed: ' + $_.Exception.Message }
        }
    }.GetNewClosure()

    $settingsState.Roots = & $getSettingsRoots

    $btnRefresh.Add_Click($refreshFileList)
    $btnSaveCurrent.Add_Click($saveCurrentFile)
    $btnSaveAll.Add_Click($saveAllFiles)
    $cmbSource.Add_SelectedIndexChanged($refreshFileList)
    $lstFiles.Add_SelectedIndexChanged($loadSelectedFile)

    $layoutSettings = {
        try {
            $shell.Width = [Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width)
            $body.Size = New-Object System.Drawing.Size(
                $shell.ClientSize.Width,
                ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12)
            )
            $editorHost.Location = New-Object System.Drawing.Point(($UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2)), $UGSM_ExpansionGap)
            $editorHost.Size = New-Object System.Drawing.Size(
                [Math]::Max(300, ($body.ClientSize.Width - $UGSM_ExpansionLeftPanelWidth - ($UGSM_ExpansionGap * 3))),
                [Math]::Max(300, ($body.ClientSize.Height - ($UGSM_ExpansionGap * 2)))
            )
            $leftPanel.Height = [Math]::Max($styleTestLeftMinHeight, ($body.ClientSize.Height - ($UGSM_ExpansionGap * 2)))
            $lstFiles.Height = [Math]::Max(180, ($leftPanel.ClientSize.Height - 58))
        }
        catch { }
    }.GetNewClosure()

    if ($cmbSource.Items.Count -gt 0) {
        $cmbSource.SelectedIndex = 0
    }

    & $layoutSettings
    $Page.Add_SizeChanged($layoutSettings)
    $Page.Add_VisibleChanged($layoutSettings)

    try { & $refreshFileList } catch { if ($StatusLabel) { $StatusLabel.Text = 'Settings tab init failed: ' + $_.Exception.Message } }
}

# REFACTORED TABS

function New-DayZExpansionFilesTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter()]$State,
        [Parameter()]$Instance,
        [Parameter()]$StatusLabel,
        [Parameter()]$RefreshDataAction
    )

    try {
        $Page.Text = 'Files'
        $Page.BackColor = $global:UGSM_ColorBackground
        $Page.ForeColor = $global:UGSM_ColorText
        $Page.AutoScroll = $false
        $Page.Controls.Clear()

        # ============================================================
        # Root / shell
        # ============================================================
        $root = New-Object System.Windows.Forms.Panel
        $root.Dock = 'Fill'
        $root.autoscroll = $false
        $root.BackColor = $global:UGSM_ColorBackground
        [void]$Page.Controls.Add($root)

        $shell = New-Object System.Windows.Forms.Panel
        $shell.Location = New-Object System.Drawing.Point(0, 0)
        $shell.Size = New-Object System.Drawing.Size(
            [Math]::Max($UGSM_ExpansionMaxWidth, $Page.ClientSize.Width),
            980
        )
        $shell.Anchor = 'Top,Left,Right'
        $shell.BackColor = $global:UGSM_ColorBackground
        $shell.BorderStyle = 'None'
        [void]$root.Controls.Add($shell)

        # ============================================================
        # Top bar
        # ============================================================
        $topBar = New-Object System.Windows.Forms.Panel
        $topBar.Location = New-Object System.Drawing.Point(0, 0)
        $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
        $topBar.Anchor = 'Top,Left,Right'
        $topBar.BackColor = $global:UGSM_ColorBackground
        $topBar.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($topBar)

        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X $UGSM_ExpansionToolbarLeftStartX -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y $UGSM_ExpansionToolbarButtonY -Width $UGSM_ExpansionButtonWidthSmall

        foreach ($button in @($btnRefresh, $btnSaveCurrent, $btnPretty)) {
            $button.Anchor = 'Top,Left'
            $button.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $button.UseVisualStyleBackColor = $false
            $button.FlatAppearance.BorderSize = 1
            $button.FlatAppearance.MouseDownBackColor = $button.BackColor
            $button.FlatAppearance.MouseOverBackColor = $button.BackColor
            [void]$topBar.Controls.Add($button)
        }
        Set-UGSMExpansionToolbarButtons -Buttons @($btnRefresh, $btnSaveCurrent, $btnPretty)

        # ============================================================
        # Body
        # ============================================================
        $body = New-Object System.Windows.Forms.Panel
        $body.Location = New-Object System.Drawing.Point(
            $UGSM_ExpansionOffsetX,
            ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap)
        )
        $body.Size = New-Object System.Drawing.Size(
            $shell.ClientSize.Width,
            ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 12)
        )
        $body.Anchor = 'Top,Left,Right,Bottom'
        $body.BackColor = $global:UGSM_ColorBackground
        $body.BorderStyle = 'FixedSingle'
        [void]$shell.Controls.Add($body)

        # ============================================================
        # Left panel
        # ============================================================
        $leftPanel = New-UGSMExpansionLeftListPanel `
            -X ($UGSM_ExpansionGap) `
            -Y ($UGSM_ExpansionGap) `
            -Width $UGSM_ExpansionLeftPanelWidth `
            -Height 700
        [void]$body.Controls.Add($leftPanel)

        $lstItems = New-Object System.Windows.Forms.ListBox
        $lstItems.Location = New-Object System.Drawing.Point(12, 12)
        $lstItems.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), 676)
        $lstItems.Anchor = 'Top,Left,Right,Bottom'
        $lstItems.BackColor = $global:UGSM_ColorInputBackground
        $lstItems.ForeColor = $global:UGSM_ColorText
        $lstItems.BorderStyle = 'FixedSingle'
        $lstItems.HorizontalScrollbar = $true
        [void]$leftPanel.Controls.Add($lstItems)

        # ============================================================
        # Editor host
        # ============================================================
        $editorPanel = New-UGSMExpansionEditorHost -X 0 -Y 0 -Width 1000 -Height 700
        $editorPanel.AutoScroll = $true
        [void]$body.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width 1000 -Height 700
        [void]$editorPanel.Controls.Add($Tower1)

        # ============================================================
        # Tower 1 content
        # ============================================================
        $lblTower1Title = New-UGSMExpansionEditorLabel -Text 'Expansion Files Editor' -X 12 -Y 12 -Width 320
        $lblTower1Title.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblTower1Title)

        $lblTower1Desc = New-UGSMExpansionEditorLabel -Text 'Select a JSON file on the left to view and edit its raw contents.' -X 12 -Y 40 -Width 850
        [void]$Tower1.Controls.Add($lblTower1Desc)

        $lblFile = New-UGSMExpansionEditorLabel -Text 'File' -X 12 -Y 76 -Width 120
        [void]$Tower1.Controls.Add($lblFile)

        $txtFile = New-UGSMExpansionEditorTextBox -X 12 -Y 96 -Width $UGSM_ExpansionFileFieldWidth
        $txtFile.ReadOnly = $false
        $txtFile.TabStop = $true
        [void]$Tower1.Controls.Add($txtFile)

        $lblPath = New-UGSMExpansionEditorLabel -Text 'Path' -X $UGSM_ExpansionPathFieldLeft -Y 76 -Width 120
        [void]$Tower1.Controls.Add($lblPath)

        $txtPath = New-UGSMExpansionEditorTextBox -X $UGSM_ExpansionPathFieldLeft -Y 96 -Width 400
        $txtPath.ReadOnly = $true
        $txtPath.Anchor = 'Top,Left,Right'
        [void]$Tower1.Controls.Add($txtPath)

        $lblRaw = New-UGSMExpansionEditorLabel -Text 'Raw JSON' -X 12 -Y 132 -Width 160
        [void]$Tower1.Controls.Add($lblRaw)

        $txtRawJson = New-Object System.Windows.Forms.TextBox
        $txtRawJson.Location = New-Object System.Drawing.Point(12, 152)
        $txtRawJson.Size = New-Object System.Drawing.Size(($Tower1.ClientSize.Width - 24), ($Tower1.ClientSize.Height - 164))
        $txtRawJson.Anchor = 'Top,Left,Right,Bottom'
        $txtRawJson.Multiline = $true
        $txtRawJson.ScrollBars = 'Both'
        $txtRawJson.AcceptsReturn = $true
        $txtRawJson.AcceptsTab = $true
        $txtRawJson.WordWrap = $false
        $txtRawJson.Font = New-Object System.Drawing.Font('Consolas', 10)
        $txtRawJson.BackColor = $global:UGSM_ColorInputBackground
        $txtRawJson.ForeColor = $global:UGSM_ColorText
        $txtRawJson.BorderStyle = 'FixedSingle'
        [void]$Tower1.Controls.Add($txtRawJson)

        # ============================================================
        # First-pass sample data
        # ============================================================

        $updateFileButtonState = {
            $hasSelection = ($lstItems.Items.Count -gt 0 -and $lstItems.SelectedIndex -ge 0)

            if ($btnSaveCurrent) { $btnSaveCurrent.Enabled = ($hasSelection -and $txtRawJson.Modified) }
            if ($btnPretty) { $btnPretty.Enabled = $hasSelection }
        }.GetNewClosure()

        $refreshFileList = {
            try {
                if ($RefreshDataAction -is [scriptblock]) {
                    & $RefreshDataAction
                }

                $selectedPathBefore = [string]$State.CurrentPath

                $lstItems.BeginUpdate()
                try {
                    $lstItems.Items.Clear()
                    foreach ($item in @($State.Files)) {
                        [void]$lstItems.Items.Add((Get-UGSMGameDayZExpansionDisplayName -Item $item))
                    }
                }
                finally {
                    $lstItems.EndUpdate()
                }

                if ($lstItems.Items.Count -le 0) {
                    $txtFile.Clear()
                    $txtPath.Clear()
                    $txtRawJson.Clear()
                    $State.CurrentPath = ''
                    $State.CurrentFile = $null
                    & $updateFileButtonState
                    return
                }

                $matchIndex = -1
                if (-not [string]::IsNullOrWhiteSpace($selectedPathBefore)) {
                    for ($i = 0; $i -lt @($State.Files).Count; $i++) {
                        $itemPath = ''
                        if ($State.Files[$i].PSObject.Properties['FullName']) {
                            $itemPath = [string]$State.Files[$i].FullName
                        }
                        elseif ($State.Files[$i].PSObject.Properties['Path']) {
                            $itemPath = [string]$State.Files[$i].Path
                        }

                        if ($itemPath -eq $selectedPathBefore) {
                            $matchIndex = $i
                            break
                        }
                    }
                }

                if ($matchIndex -ge 0) {
                    $lstItems.SelectedIndex = $matchIndex
                }
                else {
                    $lstItems.SelectedIndex = 0
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Refreshing Files tab failed: ' + $_.Exception.Message
                }
            }

            & $updateFileButtonState
        }.GetNewClosure()

        $loadSelectedFile = {
            try {
                if ($lstItems.SelectedIndex -lt 0 -or $lstItems.SelectedIndex -ge @($State.Files).Count) {
                    $txtFile.Clear()
                    $txtPath.Clear()
                    $txtRawJson.Clear()
                    $State.CurrentPath = ''
                    $State.CurrentFile = $null
                    & $updateFileButtonState
                    return
                }

                $selectedItem = $State.Files[$lstItems.SelectedIndex]
                $path = ''

                if ($selectedItem.PSObject.Properties['FullName']) {
                    $path = [string]$selectedItem.FullName
                }
                elseif ($selectedItem.PSObject.Properties['Path']) {
                    $path = [string]$selectedItem.Path
                }

                if ([string]::IsNullOrWhiteSpace($path)) {
                    throw 'Selected Expansion file path is empty.'
                }

                $raw = Read-UGSMGameDayZTextFileSafe -Path $path

                $State.CurrentFile = $selectedItem
                $State.CurrentPath = $path

                $txtFile.Text = [string](Get-UGSMGameDayZExpansionDisplayName -Item $selectedItem)
                $txtPath.Text = $path
                $txtRawJson.Text = [string]$raw
                $txtRawJson.Modified = $false

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Loaded Expansion file: ' + $txtFile.Text
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Loading Expansion file failed: ' + $_.Exception.Message
                }
            }

            & $updateFileButtonState
        }.GetNewClosure()

        $saveCurrentFile = {
            try {
                if ([string]::IsNullOrWhiteSpace($State.CurrentPath)) {
                    return
                }

                Write-UGSMGameDayZTextFileSafe -Path $State.CurrentPath -Content $txtRawJson.Text
                $txtRawJson.Modified = $false

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saved Expansion file: ' + $txtFile.Text
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Expansion file failed: ' + $_.Exception.Message
                }
            }

            & $updateFileButtonState
        }.GetNewClosure()

        $prettyPrintCurrent = {
            try {
                if ([string]::IsNullOrWhiteSpace($txtRawJson.Text)) {
                    return
                }

                $formatted = ($txtRawJson.Text | ConvertFrom-Json | ConvertTo-Json -Depth 100)
                $txtRawJson.Text = $formatted
                $txtRawJson.Modified = $true

                if ($StatusLabel) {
                    $StatusLabel.Text = 'Pretty printed: ' + $txtFile.Text
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Pretty print failed: ' + $_.Exception.Message
                }
            }

            & $updateFileButtonState
        }.GetNewClosure()

        $lstItems.Add_SelectedIndexChanged($loadSelectedFile)
        $btnRefresh.Add_Click($refreshFileList)
        $btnSaveCurrent.Add_Click($saveCurrentFile)
        $btnPretty.Add_Click($prettyPrintCurrent)

        $txtRawJson.Add_TextChanged({
                & $updateFileButtonState
            }.GetNewClosure())

        & $refreshFileList

        # ============================================================
        # Layout
        # ============================================================
        $layoutFiles = {
            Set-UGSMExpansionLayout `
                -Page $Page `
                -Root $root `
                -Shell $shell `
                -TopBar $topBar `
                -Body $body `
                -LeftPanel $leftPanel `
                -EditorPanel $editorPanel `
                -Tower1 $Tower1 `
                -LstItems $lstItems `
                -TxtPath $txtPath `
                -BtnRefresh $btnRefresh `
                -BtnSaveCurrent $btnSaveCurrent `
                -BtnPretty $btnPretty

            $rawTop = 152
            $rawMargin = 12

            $txtRawJson.Location = New-Object System.Drawing.Point($rawMargin, $rawTop)
            $txtRawJson.Size = New-Object System.Drawing.Size(
                [Math]::Max(200, ($Tower1.ClientSize.Width - ($rawMargin * 2))),
                [Math]::Max(200, ($Tower1.ClientSize.Height - $rawTop - $rawMargin))
            )

            $txtPath.Width = [Math]::Max(250, ($Tower1.ClientSize.Width - $txtPath.Left - 12))
        }.GetNewClosure()

        & $layoutFiles
        $Page.Add_SizeChanged($layoutFiles)
        $Page.Add_VisibleChanged($layoutFiles)

        if ($StatusLabel) {
            $StatusLabel.Text = 'Expansion Files tab loaded.'
        }
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) {
            $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace
        }

        Show-UGSMExpansionTabMessage `
            -Page $Page `
            -Title 'Files tab failed' `
            -Message $errorText `
            -TitleColor '#FFB4B4' `
            -ErrorAction SilentlyContinue

        if ($StatusLabel) {
            $StatusLabel.Text = 'Expansion Files tab failed: ' + $_.Exception.Message
        }
    }
}

# ===== Clean helper-based overrides for Style Test and Market =====
function New-UGSMExpansionContentHost {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][int]$X,
        [Parameter(Mandatory)][int]$Y,
        [Parameter(Mandatory)][int]$Width,
        [Parameter(Mandatory)][int]$Height
    )

    $panel = New-Object System.Windows.Forms.Panel
    $panel.Location = New-Object System.Drawing.Point($X, $Y)
    $panel.Size = New-Object System.Drawing.Size($Width, $Height)
    $panel.Anchor = 'Top,Left,Right'
    $panel.BackColor = $global:UGSM_ColorBackground
    $panel.BorderStyle = 'None'
    return $panel
}

if (-not (Get-Variable -Name UGSM_ExpansionLeftPanelMinHeight -Scope Script -ErrorAction SilentlyContinue)) { $UGSM_ExpansionLeftPanelMinHeight = 620 }
if (-not (Get-Variable -Name UGSM_ExpansionScrollBottomPadding -Scope Script -ErrorAction SilentlyContinue)) { $UGSM_ExpansionScrollBottomPadding = 120 }

function New-UGSMExpansionTabShell {
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Page)

    $Page.BackColor = $global:UGSM_ColorBackground
    $Page.ForeColor = $global:UGSM_ColorText
    $Page.AutoScroll = $false
    $Page.Controls.Clear()

    $root = New-Object System.Windows.Forms.Panel
    $root.Dock = 'Fill'
    $root.AutoScroll = $false
    $root.BackColor = $global:UGSM_ColorBackground
    [void]$Page.Controls.Add($root)

    $shell = New-Object System.Windows.Forms.Panel
    $shell.Dock = 'Fill'
    $shell.BackColor = $global:UGSM_ColorBackground
    [void]$root.Controls.Add($shell)

    $topBar = New-Object System.Windows.Forms.Panel
    $topBar.Location = New-Object System.Drawing.Point(0, 0)
    $topBar.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, $UGSM_ExpansionToolbarHeight)
    $topBar.Anchor = 'Top,Left,Right'
    $topBar.BackColor = $global:UGSM_ColorBackground
    $topBar.BorderStyle = 'FixedSingle'
    [void]$shell.Controls.Add($topBar)

    $body = New-Object System.Windows.Forms.Panel
    $body.Location = New-Object System.Drawing.Point(0, ($UGSM_ExpansionToolbarHeight + $UGSM_ExpansionGap))
    $body.Size = New-Object System.Drawing.Size($shell.ClientSize.Width, ($shell.ClientSize.Height - $UGSM_ExpansionToolbarHeight - $UGSM_ExpansionGap - 4))
    $body.Anchor = 'Top,Left,Right,Bottom'
    $body.AutoScroll = $true
    $body.BackColor = $global:UGSM_ColorBackground
    $body.BorderStyle = 'FixedSingle'
    [void]$shell.Controls.Add($body)

    $contentHost = New-UGSMExpansionContentHost -X 0 -Y 0 -Width ([Math]::Max(600, ($body.ClientSize.Width - 24))) -Height $UGSM_ExpansionLeftPanelMinHeight
    $contentHost.Anchor = 'Top,Left,Right'
    [void]$body.Controls.Add($contentHost)

    return [pscustomobject]@{
        Root        = $root
        Shell       = $shell
        TopBar      = $topBar
        Body        = $body
        ContentHost = $contentHost
    }
}

function Set-UGSMExpansionToolbarButtonLayout {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][System.Windows.Forms.Panel]$Toolbar,
        [System.Windows.Forms.Control]$BtnNew,
        [System.Windows.Forms.Control]$BtnRefresh,
        [System.Windows.Forms.Control]$BtnApply,
        [System.Windows.Forms.Control]$BtnSaveCurrent,
        [System.Windows.Forms.Control]$BtnSaveAll,
        [System.Windows.Forms.Control]$BtnPretty,
        [System.Windows.Forms.Control]$BtnRemove
    )
    Set-UGSMExpansionToolbarLayout -Toolbar $Toolbar -BtnNew $BtnNew -BtnRefresh $BtnRefresh -BtnApply $BtnApply -BtnSaveCurrent $BtnSaveCurrent -BtnSaveAll $BtnSaveAll -BtnPretty $BtnPretty -BtnRemove $BtnRemove
}

function Set-UGSMExpansionScrollLayout {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Body,
        [Parameter(Mandatory)]$ContentHost,
        [Parameter(Mandatory)]$LeftPanel,
        [Parameter(Mandatory)]$EditorPanel,
        [Parameter(Mandatory)]$Tower1,
        [Parameter(Mandatory)]$Tower2,
        [Parameter(Mandatory)]$Tower3,
        [int]$BottomPadding = $UGSM_ExpansionScrollBottomPadding
    )

    [int]$contentBottom = 0
    $contentBottom = [Math]::Max($contentBottom, [int]$EditorPanel.Bottom)
    $contentBottom = [Math]::Max($contentBottom, [int]$Tower1.Bottom + [int]$EditorPanel.Top)
    $contentBottom = [Math]::Max($contentBottom, [int]$Tower2.Bottom + [int]$EditorPanel.Top)
    $contentBottom = [Math]::Max($contentBottom, [int]$Tower3.Bottom + [int]$EditorPanel.Top)
    $contentBottom += [int]$BottomPadding

    $ContentHost.Width = [Math]::Max([int]$Body.ClientSize.Width - 24, [int]$EditorPanel.Right + 24)
    $ContentHost.Height = [int]$contentBottom
    $LeftPanel.Height = [Math]::Max($UGSM_ExpansionLeftPanelMinHeight, [int]$contentBottom - [int]$UGSM_ExpansionGap)
    try { $Body.PerformLayout(); $Body.Invalidate(); $Body.Update() } catch {}
}

function New-DayZExpansionStyleTestTab {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Page,
        [Parameter()]$State,
        [Parameter()]$Instance,
        [Parameter()]$StatusLabel
    )
    try {
        $Page.Text = 'Style Test'
        $ui = New-UGSMExpansionTabShell -Page $Page

        $btnNew = New-UGSMExpansionNewButton -Text 'New' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRefresh = New-UGSMExpansionNeutralButton -Text 'Refresh' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnApply = New-UGSMExpansionApplyButton -Text 'Apply' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveCurrent = New-UGSMExpansionSaveButton -Text 'Save Current' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnSaveAll = New-UGSMExpansionSaveButton -Text 'Save All' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnPretty = New-UGSMExpansionPrettyPrintButton -Text 'Pretty Print' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        $btnRemove = New-UGSMExpansionRemoveButton -Text 'Remove' -X 0 -Y 0 -Width $UGSM_ExpansionButtonWidthSmall
        foreach ($b in @($btnNew, $btnRefresh, $btnApply, $btnSaveCurrent, $btnSaveAll, $btnPretty, $btnRemove)) { [void]$ui.TopBar.Controls.Add($b) }

        [int]$leftPanelHeight = $UGSM_ExpansionLeftPanelMinHeight
        [int]$tower1Height = $UGSM_ExpansionTowerHeight
        [int]$tower2Height = $UGSM_ExpansionTowerHeight
        [int]$tower3Height = $UGSM_ExpansionTowerHeight
        [int]$bottomPadding = $UGSM_ExpansionScrollBottomPadding

        $leftPanel = New-UGSMExpansionLeftListPanel -X $UGSM_ExpansionGap -Y $UGSM_ExpansionGap -Width $UGSM_ExpansionLeftPanelWidth -Height $leftPanelHeight
        [void]$ui.ContentHost.Controls.Add($leftPanel)
        $cmbFilter = New-UGSMExpansionEditorComboBox -X 12 -Y 12 -Width ($UGSM_ExpansionLeftPanelWidth - 24)
        $cmbFilter.DropDownStyle = 'DropDownList'
        $cmbFilter.Items.AddRange(@('Profile Settings', 'Mission Files', 'Zones', 'Traders'))
        $cmbFilter.SelectedIndex = 0
        [void]$leftPanel.Controls.Add($cmbFilter)
        $lstItems = New-Object System.Windows.Forms.ListBox
        $lstItems.Location = New-Object System.Drawing.Point(12, 46)
        $lstItems.Size = New-Object System.Drawing.Size(($UGSM_ExpansionLeftPanelWidth - 24), ($leftPanelHeight - 58))
        $lstItems.Anchor = 'Top,Left,Bottom,Right'
        $lstItems.BackColor = $global:UGSM_ColorInputBackground
        $lstItems.ForeColor = $global:UGSM_ColorText
        $lstItems.BorderStyle = 'FixedSingle'
        $lstItems.Items.AddRange(@('AirdropSettings.json', 'AISettings.json', 'MissionSettings.json', 'TerritorySettings.json', 'VehicleSettings.json'))
        $lstItems.SelectedIndex = 0
        [void]$leftPanel.Controls.Add($lstItems)

        $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
        $editorWidth = [Math]::Max(500, ($ui.Body.ClientSize.Width - $editorLeft - 24))
        $editorPanel = New-UGSMExpansionEditorHost -X $editorLeft -Y $UGSM_ExpansionGap -Width $editorWidth -Height 10
        $editorPanel.Anchor = 'Top,Left,Right'
        [void]$ui.ContentHost.Controls.Add($editorPanel)

        $Tower1 = New-UGSMExpansionSectionPanel -X 0 -Y 0 -Width $editorWidth -Height $tower1Height
        $Tower2 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $UGSM_ExpansionSectionGap) -Width $editorWidth -Height $tower2Height
        $Tower3 = New-UGSMExpansionSectionPanel -X 0 -Y ($tower1Height + $tower2Height + ($UGSM_ExpansionSectionGap * 2)) -Width $editorWidth -Height $tower3Height
        [void]$editorPanel.Controls.Add($Tower1)
        [void]$editorPanel.Controls.Add($Tower2)
        [void]$editorPanel.Controls.Add($Tower3)

        $lblHeaderTitle = New-UGSMExpansionEditorLabel -Text 'Expansion Style Test Editor' -X 12 -Y 12 -Width 320
        $lblHeaderTitle.Font = New-Object System.Drawing.Font('Segoe UI', 11, [System.Drawing.FontStyle]::Bold)
        [void]$Tower1.Controls.Add($lblHeaderTitle)
        [void]$Tower1.Controls.Add((New-UGSMExpansionEditorLabel -Text 'Template tab for shared Expansion layout and tower sizing.' -X 12 -Y 40 -Width 700))
        [void](New-UGSMExpansionVersionField -Parent $Tower2 -X 12 -Y 46 -Value '6')
        [void](New-UGSMExpansionTextField -Parent $Tower2 -LabelText 'MissionName' -X 130 -Y 46 -LabelWidth 140 -TextBoxWidth 220 -Value 'AirdropTest1')
        [void](New-UGSMExpansionTextField -Parent $Tower2 -LabelText 'Difficulty' -X 368 -Y 46 -LabelWidth 120 -TextBoxWidth 120 -Value '0')
        [void](New-UGSMExpansionTextField -Parent $Tower2 -LabelText 'Weight' -X 506 -Y 46 -LabelWidth 120 -TextBoxWidth 120 -Value '1')
        [void](New-UGSMExpansionTextField -Parent $Tower2 -LabelText 'Height' -X 644 -Y 46 -LabelWidth 120 -TextBoxWidth 120 -Value '450')
        [void](New-UGSMExpansionCheckBoxField -Parent $Tower2 -Text 'Enabled' -X 12 -Y 114 -Width 120 -Checked $true)
        [void](New-UGSMExpansionCheckBoxField -Parent $Tower2 -Text 'ShowNotification' -X 150 -Y 114 -Width 160 -Checked $true)
        $lstNested = New-Object System.Windows.Forms.ListBox
        $lstNested.Location = New-Object System.Drawing.Point(12, 40)
        $lstNested.Size = New-Object System.Drawing.Size(280, 150)
        $lstNested.BackColor = $global:UGSM_ColorInputBackground
        $lstNested.ForeColor = $global:UGSM_ColorText
        $lstNested.BorderStyle = 'FixedSingle'
        $lstNested.Items.AddRange(@('Container 1', 'Container 2', 'Container 3'))
        $lstNested.SelectedIndex = 0
        [void]$Tower3.Controls.Add($lstNested)
        [void]$Tower3.Controls.Add((New-UGSMExpansionAddButton -Text 'Add' -X 310 -Y 40 -Width $UGSM_ExpansionButtonWidthSmall))
        [void]$Tower3.Controls.Add((New-UGSMExpansionRemoveButton -Text 'Remove' -X 310 -Y 76 -Width $UGSM_ExpansionButtonWidthSmall))

        $layout = {
            $ui.TopBar.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Height = [Math]::Max(200, ($ui.Shell.ClientSize.Height - $ui.Body.Top - 4))
            Set-UGSMExpansionToolbarButtonLayout -Toolbar $ui.TopBar -BtnNew $btnNew -BtnRefresh $btnRefresh -BtnApply $btnApply -BtnSaveCurrent $btnSaveCurrent -BtnSaveAll $btnSaveAll -BtnPretty $btnPretty -BtnRemove $btnRemove
            $leftPanel.Location = New-Object System.Drawing.Point($UGSM_ExpansionGap, $UGSM_ExpansionGap)
            $leftPanel.Width = $UGSM_ExpansionLeftPanelWidth
            $cmbFilter.Width = [Math]::Max(100, ($leftPanel.ClientSize.Width - 24))
            $lstItems.Width = [Math]::Max(100, ($leftPanel.ClientSize.Width - 24))
            $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
            $editorWidth = [Math]::Max(500, ($ui.Body.ClientSize.Width - $editorLeft - 24))
            $editorPanel.Location = New-Object System.Drawing.Point($editorLeft, $UGSM_ExpansionGap)
            $editorPanel.Width = $editorWidth
            $Tower1.Width = $editorWidth - 1; $Tower1.Height = $tower1Height; $Tower1.Location = New-Object System.Drawing.Point(0, 0)
            $Tower2.Width = $editorWidth - 1; $Tower2.Height = $tower2Height; $Tower2.Location = New-Object System.Drawing.Point(0, ($Tower1.Bottom + $UGSM_ExpansionSectionGap))
            $Tower3.Width = $editorWidth - 1; $Tower3.Height = $tower3Height; $Tower3.Location = New-Object System.Drawing.Point(0, ($Tower2.Bottom + $UGSM_ExpansionSectionGap))
            $editorPanel.Height = $Tower3.Bottom + 1
            Set-UGSMExpansionScrollLayout -Body $ui.Body -ContentHost $ui.ContentHost -LeftPanel $leftPanel -EditorPanel $editorPanel -Tower1 $Tower1 -Tower2 $Tower2 -Tower3 $Tower3 -BottomPadding $bottomPadding
            $lstItems.Height = [Math]::Max(100, ($leftPanel.ClientSize.Height - $lstItems.Top - 12))
        }.GetNewClosure()
        & $layout
        $Page.Add_SizeChanged($layout)
        $Page.Add_VisibleChanged($layout)
        if ($StatusLabel) { $StatusLabel.Text = 'Expansion Style Test tab loaded.' }
    }
    catch {
        $errorText = $_.Exception.Message
        if ($_.ScriptStackTrace) { $errorText += [Environment]::NewLine + [Environment]::NewLine + $_.ScriptStackTrace }
        Show-UGSMExpansionTabMessage -Page $Page -Title 'Style Test tab failed' -Message $errorText -TitleColor '#FFB4B4' -ErrorAction SilentlyContinue
        if ($StatusLabel) { $StatusLabel.Text = 'Style Test tab failed: ' + $_.Exception.Message }
    }
}

