        $grid.Anchor = 'Top,Left,Right,Bottom'
        $grid.BackgroundColor = $global:UGSM_ColorInputBackground
        $grid.ForeColor = $global:UGSM_ColorText
        $grid.BorderStyle = 'FixedSingle'
        $grid.AllowUserToAddRows = $false
        $grid.AllowUserToDeleteRows = $false
        $grid.AllowUserToResizeRows = $false
        $grid.SelectionMode = 'FullRowSelect'
        $grid.MultiSelect = $true
        $grid.AutoSizeColumnsMode = 'None'
        $grid.RowHeadersVisible = $false
        $grid.EnableHeadersVisualStyles = $false
        $grid.ColumnHeadersDefaultCellStyle.BackColor = $global:UGSM_ColorGridHeader
        $grid.ColumnHeadersDefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.BackColor = $global:UGSM_ColorInputBackground
        $grid.DefaultCellStyle.ForeColor = $global:UGSM_ColorText
        $grid.DefaultCellStyle.SelectionBackColor = $global:UGSM_ColorGridSelection
        $grid.DefaultCellStyle.SelectionForeColor = $global:UGSM_ColorText
        [void]$Tower2.Controls.Add($grid)

        $null = $grid.Columns.Add('ClassName', 'ClassName')
        $null = $grid.Columns.Add('MaxPriceThreshold', 'Max Price')
        $null = $grid.Columns.Add('MinPriceThreshold', 'Min Price')
        $null = $grid.Columns.Add('SellPricePercent', 'Sell %')
        $null = $grid.Columns.Add('MaxStockThreshold', 'Max Stock')
        $null = $grid.Columns.Add('MinStockThreshold', 'Min Stock')
        $null = $grid.Columns.Add('QuantityPercent', 'Qty %')
        $null = $grid.Columns.Add('SpawnAttachments', 'SpawnAttachments')
        $null = $grid.Columns.Add('Variants', 'Variants')

        $grid.Columns['ClassName'].Width = 180
        $grid.Columns['MaxPriceThreshold'].Width = 90
        $grid.Columns['MinPriceThreshold'].Width = 90
        $grid.Columns['SellPricePercent'].Width = 70
        $grid.Columns['MaxStockThreshold'].Width = 85
        $grid.Columns['MinStockThreshold'].Width = 85
        $grid.Columns['QuantityPercent'].Width = 70
        $grid.Columns['SpawnAttachments'].Width = 140
        $grid.Columns['Variants'].Width = 180

        $applyMarketSearchFilter = {
            try {
                $query = ''
                if ($txtSearch) {
                    $query = [string]$txtSearch.Text
                }
                $query = $query.Trim().ToLowerInvariant()

                $totalRows = 0
                $visibleRows = 0
                foreach ($row in @($grid.Rows)) {
                    if ($row.IsNewRow) { continue }
                    $totalRows++

                    $isVisible = $true
                    if (-not [string]::IsNullOrWhiteSpace($query)) {
                        $parts = New-Object System.Collections.ArrayList
                        foreach ($columnName in @('ClassName', 'SpawnAttachments', 'Variants')) {
                            try {
                                $cellValue = [string]$row.Cells[$columnName].Value
                                if (-not [string]::IsNullOrWhiteSpace($cellValue)) {
                                    [void]$parts.Add($cellValue)
                                }
                            }
                            catch {}
                        }
                        $haystack = ([string]::Join(' ', @($parts))).ToLowerInvariant()
                        $isVisible = $haystack.Contains($query)
                    }

                    $row.Visible = $isVisible
                    if ($isVisible) { $visibleRows++ }
                }

                if ($lblSearchCount) {
                    $lblSearchCount.Text = ([string]$visibleRows + '/' + [string]$totalRows)
                }
            }
            catch {}
        }.GetNewClosure()

        $marketState = [ordered]@{
            Files       = @()
            CurrentPath = ''
            CurrentData = $null
            PendingData = $null
            Dirty       = $false
        }

        $toNumberOrDefault = {
            param($Value, $DefaultValue)
            try {
                if ($null -eq $Value) { return $DefaultValue }
                $text = [string]$Value
                if ([string]::IsNullOrWhiteSpace($text)) { return $DefaultValue }
                if ($DefaultValue -is [double]) { return [double]$text }
                return [int]$text
            }
            catch {
                return $DefaultValue
            }
        }.GetNewClosure()

        $getMarketRoot = {
            $paths = Get-UGSMGameDayZExpansionPaths -Instance $Instance
            return (Join-Path ([string]$paths.ProfileExpansionRoot) 'Market')
        }.GetNewClosure()

        $setEditorDefaults = {
            param([string]$FileName, [string]$DisplayName)
            $txtFile.Text = $FileName
            $txtDisplay.Text = $DisplayName
            $txtPath.Text = ''
            $txtVersion.Text = '12'
            $cmbIcon.Text = 'Deliver'
            $txtColor.Text = 'FBFCFEFF'
            $txtInitStock.Text = '75'
            $chkIsExchange.Checked = $false
            $txtBulkValue.Text = ''
            $grid.Rows.Clear()
            $marketState.CurrentPath = ''
            $marketState.CurrentData = $null
            $marketState.PendingData = $null
            $marketState.Dirty = $false
        }.GetNewClosure()

        $clearEditor = { & $setEditorDefaults -FileName '' -DisplayName '' }.GetNewClosure()

        $safeJoinList = {
            param($Values)
            if ($null -eq $Values) { return '' }
            $parts = New-Object System.Collections.ArrayList
            foreach ($v in @($Values)) {
                $text = [string]$v
                if (-not [string]::IsNullOrWhiteSpace($text)) {
                    [void]$parts.Add($text.Trim())
                }
            }
            return [string]::Join(', ', @($parts))
        }.GetNewClosure()

        $splitCommaList = {
            param([string]$Text)
            $list = New-Object System.Collections.ArrayList
            if ([string]::IsNullOrWhiteSpace($Text)) {
                return @($list)
            }
            foreach ($part in ([string]$Text).Split(',')) {
                $clean = [string]$part
                if ($null -ne $clean) { $clean = $clean.Trim() }
                if (-not [string]::IsNullOrWhiteSpace($clean)) {
                    [void]$list.Add($clean)
                }
            }
            return @($list)
        }.GetNewClosure()

        $readMarketCategoryFile = {
            param([string]$Path)
            $raw = Read-UGSMGameDayZTextFileSafe -Path $Path
            $data = $raw | ConvertFrom-Json
            if ($null -eq $data) {
                $data = [ordered]@{
                    m_Version        = 12
                    DisplayName      = 'New Market Category'
                    Icon             = 'Deliver'
                    Color            = 'FBFCFEFF'
                    IsExchange       = 0
                    InitStockPercent = 75
                    Items            = @()
                }
            }
            if (-not ($data.PSObject.Properties.Name -contains 'Items') -or $null -eq $data.Items) {
                $data | Add-Member -NotePropertyName Items -NotePropertyValue @() -Force
            }
            return $data
        }.GetNewClosure()

        $writeMarketCategoryFile = {
            param([string]$Path, $Data)
            [void](Write-UGSMGameDayZTextFileSafe -Path $Path -Content ($Data | ConvertTo-Json -Depth 100))
        }.GetNewClosure()

        $getSafeCategoryFileName = {
            param([string]$Name)
            $value = [string]$Name
            $value = $value -replace '\.json$', ''
            $value = $value -replace '[^A-Za-z0-9_\- ]', ''
            $value = $value.Trim()
            $value = $value -replace '\s+', '_'
            if ([string]::IsNullOrWhiteSpace($value)) {
                throw 'Category name is empty after sanitizing.'
            }
            return ($value + '.json')
        }.GetNewClosure()

        $refreshMoveTargets = {
            try {
                $currentName = ''
                if ($cmbMoveTarget -and -not [string]::IsNullOrWhiteSpace([string]$cmbMoveTarget.Text)) {
                    $currentName = [string]$cmbMoveTarget.Text
                }

                $cmbMoveTarget.Items.Clear()
                foreach ($file in @($marketState.Files)) {
                    $name = [System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name)
                    [void]$cmbMoveTarget.Items.Add($name)
                }

                if (-not [string]::IsNullOrWhiteSpace($currentName)) {
                    $existingIndex = $cmbMoveTarget.Items.IndexOf($currentName)
                    if ($existingIndex -ge 0) {
                        $cmbMoveTarget.SelectedIndex = $existingIndex
                    }
                }
            }
            catch {}
        }.GetNewClosure()

        $loadDataIntoEditor = {
            param([string]$Path, $Data)

            $txtFile.Text = [System.IO.Path]::GetFileNameWithoutExtension([string]$Path)
            $txtDisplay.Text = [string]$Data.DisplayName
            $txtPath.Text = [string]$Path
            $txtVersion.Text = [string]$(if ($null -ne $Data.m_Version) { $Data.m_Version } else { 12 })
            $cmbIcon.Text = [string]$Data.Icon
            $txtColor.Text = [string]$Data.Color
            $txtInitStock.Text = [string]$Data.InitStockPercent
            $chkIsExchange.Checked = ([int]$Data.IsExchange -ne 0)
            $txtBulkValue.Text = ''

            $grid.Rows.Clear()
            foreach ($item in @($Data.Items)) {
                $spawnAttachments = & $safeJoinList $item.SpawnAttachments
                $variants = & $safeJoinList $item.Variants

                [void]$grid.Rows.Add(
                    [string]$item.ClassName,
                    [string]$item.MaxPriceThreshold,
                    [string]$item.MinPriceThreshold,
                    [string]$item.SellPricePercent,
                    [string]$item.MaxStockThreshold,
                    [string]$item.MinStockThreshold,
                    [string]$item.QuantityPercent,
                    $spawnAttachments,
                    $variants
                )
            }

            $marketState.CurrentPath = [string]$Path
            $marketState.CurrentData = $Data
            $marketState.PendingData = $null
            $marketState.Dirty = $false
            & $applyMarketSearchFilter
        }.GetNewClosure()

        $refreshMarketFiles = {
            try {
                $rootPath = & $getMarketRoot
                $selectedName = ''
                if ($lstItems.SelectedItem) {
                    $selectedName = [string]$lstItems.SelectedItem
                }

                $lstItems.Items.Clear()
                $marketState.Files = @()

                if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($rootPath)
                }

                $allFiles = @(Get-ChildItem -LiteralPath $rootPath -File -Filter '*.json' -ErrorAction SilentlyContinue)
                $filteredFiles = New-Object System.Collections.ArrayList
                foreach ($file in $allFiles) {
                    if ($file.Name -notmatch '\.bak(\.|$)') {
                        [void]$filteredFiles.Add($file)
                    }
                }
                $marketState.Files = @($filteredFiles | Sort-Object Name)

                foreach ($file in @($marketState.Files)) {
                    [void]$lstItems.Items.Add([System.IO.Path]::GetFileNameWithoutExtension([string]$file.Name))
                }

                if ($lstItems.Items.Count -gt 0) {
                    $restoreIndex = -1
                    if (-not [string]::IsNullOrWhiteSpace($selectedName)) {
                        $restoreIndex = $lstItems.Items.IndexOf($selectedName)
                    }
                    if ($restoreIndex -lt 0) { $restoreIndex = 0 }
                    $lstItems.SelectedIndex = $restoreIndex
                }
                else {
                    & $clearEditor
                }

                & $refreshMoveTargets

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded ' + [string]@($marketState.Files).Count + ' market category file(s).')
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Refreshing Market files failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $loadSelectedCategory = {
            try {
                if ($lstItems.SelectedIndex -lt 0 -or $lstItems.SelectedIndex -ge @($marketState.Files).Count) {
                    & $clearEditor
                    return
                }

                $file = $marketState.Files[$lstItems.SelectedIndex]
                $data = & $readMarketCategoryFile -Path $file.FullName
                & $loadDataIntoEditor -Path $file.FullName -Data $data

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Loaded Market category: ' + [System.IO.Path]::GetFileName([string]$file.FullName))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Loading Market category failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $gridRowToMarketItem = {
            param($Row)
            if ($null -eq $Row -or $Row.IsNewRow) { return $null }

            $className = [string]$Row.Cells['ClassName'].Value
            if ([string]::IsNullOrWhiteSpace($className)) { return $null }

            $spawnAttachments = & $splitCommaList ([string]$Row.Cells['SpawnAttachments'].Value)
            $variants = & $splitCommaList ([string]$Row.Cells['Variants'].Value)

            return [ordered]@{
                ClassName         = $className
                MaxPriceThreshold = (& $toNumberOrDefault $Row.Cells['MaxPriceThreshold'].Value 100)
                MinPriceThreshold = (& $toNumberOrDefault $Row.Cells['MinPriceThreshold'].Value 50)
                SellPricePercent  = (& $toNumberOrDefault $Row.Cells['SellPricePercent'].Value ([double]-1))
                MaxStockThreshold = (& $toNumberOrDefault $Row.Cells['MaxStockThreshold'].Value 100)
                MinStockThreshold = (& $toNumberOrDefault $Row.Cells['MinStockThreshold'].Value 1)
                QuantityPercent   = (& $toNumberOrDefault $Row.Cells['QuantityPercent'].Value -1)
                SpawnAttachments  = @($spawnAttachments)
                Variants          = @($variants)
            }
        }.GetNewClosure()

        $buildCurrentCategoryData = {
            $fileName = [string]$txtFile.Text
            if ([string]::IsNullOrWhiteSpace($fileName)) {
                throw 'Category File is required.'
            }

            $versionValue = 12
            try {
                if (-not [string]::IsNullOrWhiteSpace([string]$txtVersion.Text)) {
                    $versionValue = [int]$txtVersion.Text
                }
            }
            catch {
                $versionValue = 12
            }

            $items = New-Object System.Collections.ArrayList
            foreach ($row in @($grid.Rows)) {
                if ($row.IsNewRow) { continue }
                $item = & $gridRowToMarketItem -Row $row
                if ($null -eq $item) { continue }
                [void]$items.Add($item)
            }

            return [ordered]@{
                m_Version        = $versionValue
                DisplayName      = [string]$txtDisplay.Text
                Icon             = [string]$cmbIcon.Text
                Color            = [string]$txtColor.Text
                IsExchange       = $(if ($chkIsExchange.Checked) { 1 } else { 0 })
                InitStockPercent = (& $toNumberOrDefault $txtInitStock.Text ([double]75))
                Items            = @($items)
            }
        }.GetNewClosure()

        $applyCategory = {
            try {
                $marketState.PendingData = & $buildCurrentCategoryData
                $marketState.Dirty = $true
                if ($StatusLabel) {
                    $StatusLabel.Text = ('Applied draft for Market category: ' + [string]$txtFile.Text)
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Applying Market category failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $saveCurrent = {
            try {
                $data = $(if ($marketState.PendingData) { $marketState.PendingData } else { & $buildCurrentCategoryData })

                $fileName = [string]$txtFile.Text
                if ([string]::IsNullOrWhiteSpace($fileName)) { throw 'Category File is required.' }
                if ($fileName -match '\.bak\.json$') { throw 'Category File cannot end with .bak.json' }
                if (-not $fileName.EndsWith('.json', [System.StringComparison]::OrdinalIgnoreCase)) {
                    $fileName += '.json'
                }

                $rootPath = & $getMarketRoot
                if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
                    [void][System.IO.Directory]::CreateDirectory($rootPath)
                }

                $targetPath = Join-Path $rootPath $fileName
                $oldPath = [string]$marketState.CurrentPath

                if (-not [string]::IsNullOrWhiteSpace($oldPath) -and (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
                    [void](Backup-UGSMGameDayZFile -TargetPath $oldPath)
                }

                [void](Write-UGSMGameDayZTextFileSafe -Path $targetPath -Content ($data | ConvertTo-Json -Depth 100))

                if (-not [string]::IsNullOrWhiteSpace($oldPath) -and
                    ($oldPath -ne $targetPath) -and
                    (Test-Path -LiteralPath $oldPath -PathType Leaf)) {
                    Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue
                }

                $marketState.CurrentPath = $targetPath
                $marketState.CurrentData = $data
                $marketState.PendingData = $null
                $marketState.Dirty = $false

                & $refreshMarketFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstItems.Items.IndexOf($selectedName)
                if ($index -ge 0) { $lstItems.SelectedIndex = $index }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved Market category: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Saving Market category failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $prettyPrintCurrent = {
            try {
                $targetPath = [string]$marketState.CurrentPath
                if ([string]::IsNullOrWhiteSpace($targetPath) -or -not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                    throw 'Select a Market category first.'
                }

                $data = & $readMarketCategoryFile -Path $targetPath
                [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
                & $writeMarketCategoryFile -Path $targetPath -Data $data
                & $refreshMarketFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)
                $index = $lstItems.Items.IndexOf($selectedName)
                if ($index -ge 0) { $lstItems.SelectedIndex = $index }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Pretty printed Market category: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Pretty Print failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $saveAll = {
            try {
                if ($marketState.PendingData -or $marketState.Dirty) {
                    & $saveCurrent
                }

                $rootPath = & $getMarketRoot
                if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) {
                    throw 'Market folder was not found.'
                }

                $count = 0
                foreach ($file in (Get-ChildItem -LiteralPath $rootPath -File -Filter '*.json' -ErrorAction SilentlyContinue)) {
                    if ($file.Name -match '\.bak\.json$') { continue }
                    $data = & $readMarketCategoryFile -Path $file.FullName
                    & $writeMarketCategoryFile -Path $file.FullName -Data $data
                    $count++
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Saved/normalized ' + [string]$count + ' Market category file(s).')
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Save All failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $removeCurrent = {
            try {
                $targetPath = [string]$marketState.CurrentPath
                if ([string]::IsNullOrWhiteSpace($targetPath) -or -not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                    throw 'Select a Market category to remove.'
                }

                [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
                Remove-Item -LiteralPath $targetPath -Force -ErrorAction Stop

                & $refreshMarketFiles

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Removed Market category: ' + [System.IO.Path]::GetFileName($targetPath))
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Removing Market category failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $getOrCreateMoveTargetPath = {
            $root = & $getMarketRoot
            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                [void][System.IO.Directory]::CreateDirectory($root)
            }

            $newCategoryText = [string]$txtNewMoveCategory.Text
            if (-not [string]::IsNullOrWhiteSpace($newCategoryText)) {
                $fileName = & $getSafeCategoryFileName $newCategoryText
                $targetPath = Join-Path $root $fileName

                if (-not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
                    $newData = [ordered]@{
                        m_Version        = 12
                        DisplayName      = $newCategoryText
                        Icon             = 'Deliver'
                        Color            = 'FBFCFEFF'
                        IsExchange       = 0
                        InitStockPercent = 75
                        Items            = @()
                    }
                    & $writeMarketCategoryFile -Path $targetPath -Data $newData
                }

                return $targetPath
            }

            if ([string]::IsNullOrWhiteSpace([string]$cmbMoveTarget.Text)) {
                throw 'Select an existing category or enter a new category name.'
            }

            return (Join-Path $root (([string]$cmbMoveTarget.Text) + '.json'))
        }.GetNewClosure()

        $moveRowsToCategory = {
            param([object[]]$RowsToMove)

            try {
                if ([string]::IsNullOrWhiteSpace([string]$marketState.CurrentPath)) {
                    throw 'No source market category is selected.'
                }

                $sourcePath = [string]$marketState.CurrentPath
                $targetPath = & $getOrCreateMoveTargetPath

                if ([string]::Equals($sourcePath, $targetPath, [System.StringComparison]::OrdinalIgnoreCase)) {
                    throw 'Source and target category are the same.'
                }

                $sourceData = & $readMarketCategoryFile -Path $sourcePath
                $targetData = & $readMarketCategoryFile -Path $targetPath

                $moveClassNames = New-Object System.Collections.ArrayList
                $itemsToMove = New-Object System.Collections.ArrayList

                foreach ($row in @($RowsToMove)) {
                    $item = & $gridRowToMarketItem -Row $row
                    if ($null -eq $item) { continue }

                    $className = [string]$item.ClassName
                    if ([string]::IsNullOrWhiteSpace($className)) { continue }

                    $alreadyListed = $false
                    foreach ($existingClass in @($moveClassNames)) {
                        if ([string]::Equals([string]$existingClass, $className, [System.StringComparison]::OrdinalIgnoreCase)) {
                            $alreadyListed = $true
                            break
                        }
                    }
                    if ($alreadyListed) { continue }

                    [void]$moveClassNames.Add($className)
                    [void]$itemsToMove.Add($item)
                }

                if ($moveClassNames.Count -eq 0) {
                    throw 'No valid items were selected to move.'
                }

                $targetExisting = @{}
                foreach ($targetItem in @($targetData.Items)) {
                    $targetClass = [string]$targetItem.ClassName
                    if (-not [string]::IsNullOrWhiteSpace($targetClass)) {
                        $targetExisting[$targetClass.ToLowerInvariant()] = $true
                    }
                }

                foreach ($item in @($itemsToMove)) {
                    $classKey = ([string]$item.ClassName).ToLowerInvariant()
                    if (-not $targetExisting.ContainsKey($classKey)) {
                        $targetData.Items += $item
                        $targetExisting[$classKey] = $true
                    }
                }

                $remainingItems = New-Object System.Collections.ArrayList
                foreach ($sourceItem in @($sourceData.Items)) {
                    $sourceClass = [string]$sourceItem.ClassName
                    if ([string]::IsNullOrWhiteSpace($sourceClass)) { continue }

                    $shouldSkip = $false
                    foreach ($moveClass in @($moveClassNames)) {
                        if ([string]::Equals([string]$moveClass, $sourceClass, [System.StringComparison]::OrdinalIgnoreCase)) {
                            $shouldSkip = $true
                            break
                        }
                    }

                    if (-not $shouldSkip) {
                        [void]$remainingItems.Add($sourceItem)
                    }
                }
                $sourceData.Items = @($remainingItems)

                [void](Backup-UGSMGameDayZFile -TargetPath $sourcePath)
                if (Test-Path -LiteralPath $targetPath -PathType Leaf) {
                    [void](Backup-UGSMGameDayZFile -TargetPath $targetPath)
                }

                & $writeMarketCategoryFile -Path $sourcePath -Data $sourceData
                & $writeMarketCategoryFile -Path $targetPath -Data $targetData

                $targetName = [System.IO.Path]::GetFileNameWithoutExtension($targetPath)

                & $refreshMarketFiles

                $selectedName = [System.IO.Path]::GetFileNameWithoutExtension($sourcePath)
                $index = $lstItems.Items.IndexOf($selectedName)
                if ($index -ge 0) { $lstItems.SelectedIndex = $index }

                $targetIndex = $cmbMoveTarget.Items.IndexOf($targetName)
                if ($targetIndex -ge 0) { $cmbMoveTarget.SelectedIndex = $targetIndex }

                $txtNewMoveCategory.Text = ''

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Moved ' + [string]$moveClassNames.Count + ' item(s) to ' + $targetName + '.')
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Moving Market items failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $removeItem = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $grid.SelectedRows) {
                [void]$selected.Add($row)
            }

            if ($selected.Count -eq 0) { return }

            $ordered = @($selected | Sort-Object Index -Descending)
            foreach ($row in $ordered) {
                if (-not $row.IsNewRow) {
                    $grid.Rows.Remove($row)
                }
            }

            $marketState.Dirty = $true
        }.GetNewClosure()

        $moveSelectedItems = {
            $selected = New-Object System.Collections.ArrayList
            foreach ($row in $grid.SelectedRows) {
                [void]$selected.Add($row)
            }

            if ($selected.Count -eq 0) {
                throw 'Select one or more items to move.'
            }

            $orderedRows = @($selected | Sort-Object Index)
            & $moveRowsToCategory -RowsToMove $orderedRows
        }.GetNewClosure()

        $moveAllItems = {
            $allRows = New-Object System.Collections.ArrayList
            foreach ($row in $grid.Rows) {
                if (-not $row.IsNewRow) {
                    [void]$allRows.Add($row)
                }
            }

            if ($allRows.Count -eq 0) {
                throw 'There are no items to move.'
            }

            $orderedRows = @($allRows | Sort-Object Index)
            & $moveRowsToCategory -RowsToMove $orderedRows
        }.GetNewClosure()

        $applyBulkEdit = {
            param([bool]$ApplyToAll)

            $columnName = [string]$cmbBulkColumn.Text
            $rawValue = [string]$txtBulkValue.Text

            if ([string]::IsNullOrWhiteSpace($columnName)) {
                throw 'Select a bulk edit column.'
            }
            if ([string]::IsNullOrWhiteSpace($rawValue)) {
                throw 'Enter a bulk edit value.'
            }

            $targetRows = New-Object System.Collections.ArrayList
            if ($ApplyToAll) {
                foreach ($row in $grid.Rows) {
                    if (-not $row.IsNewRow) {
                        [void]$targetRows.Add($row)
                    }
                }
            }
            else {
                foreach ($row in $grid.SelectedRows) {
                    [void]$targetRows.Add($row)
                }
            }

            if ($targetRows.Count -eq 0) {
                throw 'No rows available for bulk edit.'
            }

            $numericColumns = @(
                'MaxPriceThreshold',
                'MinPriceThreshold',
                'SellPricePercent',
                'MaxStockThreshold',
                'MinStockThreshold',
                'QuantityPercent'
            )

            if ($numericColumns -contains $columnName) {
                try {
                    [void][double]$rawValue
                }
                catch {
                    throw 'Bulk edit value must be numeric for this column.'
                }
            }

            foreach ($row in @($targetRows)) {
                if ($row.IsNewRow) { continue }
                $row.Cells[$columnName].Value = $rawValue
            }

            $marketState.Dirty = $true

            if ($StatusLabel) {
                $scopeText = $(if ($ApplyToAll) { 'all rows' } else { 'selected rows' })
                $StatusLabel.Text = ('Applied bulk edit to ' + $scopeText + ': ' + $columnName + ' = ' + $rawValue)
            }
        }.GetNewClosure()

        $syncMarketFromTypes = {
            try {
                $typesPath = ''
                if (Get-Command -Name Resolve-UGSMGameDayZTypesXmlPath -ErrorAction SilentlyContinue) {
                    $typesPath = Resolve-UGSMGameDayZTypesXmlPath -Instance $Instance
                }

                if ([string]::IsNullOrWhiteSpace($typesPath) -or -not (Test-Path -LiteralPath $typesPath -PathType Leaf)) {
                    try {
                        $paths = Get-UGSMGameDayZProfilePaths -Instance $Instance
                        $candidates = @()

                        if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeTypesPath)) {
                            $candidates += [string]$paths.RuntimeTypesPath
                        }
                        if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeDbPath)) {
                            $candidates += (Join-Path ([string]$paths.RuntimeDbPath) 'types.xml')
                        }
                        if (-not [string]::IsNullOrWhiteSpace([string]$paths.RuntimeMissionPath)) {
                            $candidates += (Join-Path ([string]$paths.RuntimeMissionPath) 'db\types.xml')
                        }
                        if (-not [string]::IsNullOrWhiteSpace([string]$paths.MissionFolderPath)) {
                            $candidates += (Join-Path ([string]$paths.MissionFolderPath) 'db\types.xml')
                        }

                        foreach ($candidate in @($candidates)) {
                            if (-not [string]::IsNullOrWhiteSpace([string]$candidate) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
                                $typesPath = [string]$candidate
                                break
                            }
                        }
                    }
                    catch {}
                }

                if ([string]::IsNullOrWhiteSpace($typesPath) -or -not (Test-Path -LiteralPath $typesPath -PathType Leaf)) {
                    throw 'types.xml could not be resolved for this instance.'
                }

                $report = Add-UGSMGameDayZMissingTypesToExpansionMarket -Instance $Instance -TypesPath $typesPath -TargetFileName 'UGSM_Generated.json' -SkipNamePattern '^(ZmbF_|ZmbM_|Zmb|StaticObj_|Land_|Animal_|Wreck_|Fireplace|Bonfire|BanditAI_)'

                & $refreshMarketFiles

                if (-not [string]::IsNullOrWhiteSpace([string]$report.TargetPath)) {
                    $selectedName = [System.IO.Path]::GetFileNameWithoutExtension([string]$report.TargetPath)
                    $index = $lstItems.Items.IndexOf($selectedName)
                    if ($index -ge 0) {
                        $lstItems.SelectedIndex = $index
                    }
                }

                if ($StatusLabel) {
                    $StatusLabel.Text = ('Expansion Market sync complete: ' + [string]$report.ItemsAdded + ' added, ' + [string]$report.ExistingItemsSkipped + ' existing/skipped, ' + [string]$report.ItemsSkippedByPattern + ' skipped by filter.')
                }
            }
            catch {
                if ($StatusLabel) {
                    $StatusLabel.Text = 'Sync From types.xml failed: ' + $_.Exception.Message
                }
            }
        }.GetNewClosure()

        $btnNew.Add_Click({
                try {
                    & $setEditorDefaults -FileName 'UGSM_Generated' -DisplayName 'UGSM Generated'
                    $marketState.Dirty = $true
                    if ($StatusLabel) {
                        $StatusLabel.Text = 'Ready to create a new Market category.'
                    }
                }
                catch {
                    if ($StatusLabel) {
                        $StatusLabel.Text = 'New Market category failed: ' + $_.Exception.Message
                    }
                }
            }.GetNewClosure())

        $btnRefresh.Add_Click({ & $refreshMarketFiles }.GetNewClosure())
        $btnApply.Add_Click({ & $applyCategory }.GetNewClosure())
        $btnSaveCurrent.Add_Click({ & $saveCurrent }.GetNewClosure())
        $btnSaveAll.Add_Click({ & $saveAll }.GetNewClosure())
        $btnPretty.Add_Click({ & $prettyPrintCurrent }.GetNewClosure())
        $btnRemove.Add_Click({ & $removeCurrent }.GetNewClosure())

        $btnAddItem.Add_Click({
                [void]$grid.Rows.Add('', '100', '50', '-1', '100', '1', '-1', '', '')
                $marketState.Dirty = $true
                & $applyMarketSearchFilter
            }.GetNewClosure())

        $btnRemoveItem.Add_Click({
                & $removeItem
                & $applyMarketSearchFilter
            }.GetNewClosure())
        $btnSyncTypes.Add_Click({ & $syncMarketFromTypes }.GetNewClosure())

        $btnMoveSelected.Add_Click({
                try { & $moveSelectedItems } catch { if ($StatusLabel) { $StatusLabel.Text = 'Move Selected failed: ' + $_.Exception.Message } }
            }.GetNewClosure())

        $btnMoveAll.Add_Click({
                try { & $moveAllItems } catch { if ($StatusLabel) { $StatusLabel.Text = 'Move All failed: ' + $_.Exception.Message } }
            }.GetNewClosure())

        $btnBulkSelected.Add_Click({
                try { & $applyBulkEdit $false; & $applyMarketSearchFilter } catch { if ($StatusLabel) { $StatusLabel.Text = 'Apply Selected failed: ' + $_.Exception.Message } }
            }.GetNewClosure())

        $btnBulkAll.Add_Click({
                try { & $applyBulkEdit $true; & $applyMarketSearchFilter } catch { if ($StatusLabel) { $StatusLabel.Text = 'Apply All failed: ' + $_.Exception.Message } }
            }.GetNewClosure())

        $txtSearch.Add_TextChanged({ & $applyMarketSearchFilter }.GetNewClosure())
        $btnClearSearch.Add_Click({
                $txtSearch.Text = ''
                & $applyMarketSearchFilter
            }.GetNewClosure())

        $lstItems.Add_SelectedIndexChanged({ & $loadSelectedCategory }.GetNewClosure())
        $cmbFilter.Add_SelectedIndexChanged({ & $refreshMarketFiles }.GetNewClosure())

        $btnPickColor.Add_Click({
                try {
                    $dialog = New-Object System.Windows.Forms.ColorDialog
                    $dialog.FullOpen = $true
                    $current = [string]$txtColor.Text
                    if ($current.Length -eq 8) {
                        try {
                            $r = [Convert]::ToInt32($current.Substring(0, 2), 16)
                            $g = [Convert]::ToInt32($current.Substring(2, 2), 16)
                            $b = [Convert]::ToInt32($current.Substring(4, 2), 16)
                            $a = [Convert]::ToInt32($current.Substring(6, 2), 16)
                            $dialog.Color = [System.Drawing.Color]::FromArgb($a, $r, $g, $b)
                        }
                        catch {}
                    }

                    if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                        $c = $dialog.Color
                        $txtColor.Text = ('{0:X2}{1:X2}{2:X2}{3:X2}' -f $c.R, $c.G, $c.B, $c.A)
                        $marketState.Dirty = $true
                    }
                }
                catch {
                    if ($StatusLabel) {
                        $StatusLabel.Text = 'Picking color failed: ' + $_.Exception.Message
                    }
                }
            }.GetNewClosure())

        $layout = {
            $ui.TopBar.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Width = $ui.Shell.ClientSize.Width
            $ui.Body.Height = [Math]::Max(200, ($ui.Shell.ClientSize.Height - $ui.Body.Top - 4))

            Set-UGSMExpansionToolbarButtonLayout -Toolbar $ui.TopBar -BtnNew $btnNew -BtnRefresh $btnRefresh -BtnApply $btnApply -BtnSaveCurrent $btnSaveCurrent -BtnSaveAll $btnSaveAll -BtnPretty $btnPretty -BtnRemove $btnRemove

            $leftPanel.Location = New-Object System.Drawing.Point($UGSM_ExpansionGap, $UGSM_ExpansionGap)
            $leftPanel.Width = $UGSM_ExpansionLeftPanelWidth
            $cmbFilter.Width = [Math]::Max(100, ($leftPanel.ClientSize.Width - 24))
            $lstItems.Height = [Math]::Max(100, ($leftPanel.ClientSize.Height - $lstItems.Top - 12))

            $editorLeft = $UGSM_ExpansionLeftPanelWidth + ($UGSM_ExpansionGap * 2) + $UGSM_ExpansionColumnGap
            $editorWidth = [Math]::Max(500, ($ui.Body.ClientSize.Width - $editorLeft - 24))
            $editorPanel.Location = New-Object System.Drawing.Point($editorLeft, $UGSM_ExpansionGap)
            $editorPanel.Width = $editorWidth

            $Tower1.Width = $editorWidth - 1
            $Tower1.Height = $tower1Height
            $Tower1.Location = New-Object System.Drawing.Point(0, 0)

            $Tower2.Width = $editorWidth - 1
            $Tower2.Height = $tower2Height - 25
            $Tower2.Location = New-Object System.Drawing.Point(0, ($Tower1.Bottom + $UGSM_ExpansionSectionGap))

            $editorPanel.Height = $Tower2.Bottom + 1

            $txtPath.Width = [Math]::Max(180, ($Tower1.ClientSize.Width - $txtPath.Left - 12))
            $grid.Width = [Math]::Max(420, ($Tower2.ClientSize.Width - 24))
            $grid.Height = [Math]::Max(160, ($Tower2.ClientSize.Height - $grid.Top - 24))
        }.GetNewClosure()

        & $layout
        $Page.Add_SizeChanged($layout)
        $Page.Add_VisibleChanged($layout)

        & $refreshMarketFiles
    }
    catch {
        if ($StatusLabel) {
            $StatusLabel.Text = 'Loading Expansion Market tab failed: ' + $_.Exception.Message
        }
    }
}
